import{n as e}from"./rolldown-runtime-hePW80VL.js";var t=e({diyaloglar:()=>r,dosyalar:()=>n}),n=JSON.parse(`[{"ders":"kat-hizmetleri-10","sinif":10,"unite":1,"baslik":"Kat Ofisi İşlemleri","onay":true,"kazanimlar":["Ulusal standartlara ve işletme prosedürüne uygun olarak kat ofisi düzenlemesini yapar.","Ulusal standartlara ve işletme prosedürüne uygun olarak kat arabasını hazırlar.","İş sağlığı ve güvenliği standartlarına uygun olarak ekipmanların bakımını yapar.","İş sağlığı ve güvenliği standartlarına uygun olarak kat hizmetlerinde kullanılan form ve raporları doldurur."],"soz":"Kat ofisi, arabası ve formlarıyla düzenli başlayan vardiya odaya düzenli gider.","dersler":[{"baslik":"Kat Ofisi: Hizmetin Perde Arkası","ilk":"kh1-1-001"},{"baslik":"Kuru, Havadar ve Temiz Bir Üs","ilk":"kh1-1-005"},{"baslik":"Rafın Duvara, Kimyasalın Kilide Bağlı Olması","ilk":"kh1-1-008"},{"baslik":"Su, Elektrik ve Hazırlık Köşesi","ilk":"kh1-1-011"},{"baslik":"Biten Malzemeyi Kim Duyar?","ilk":"kh1-1-014"},{"baslik":"Tabelalar Ne Söylüyor?","ilk":"kh1-1-019"},{"baslik":"Ofisi Sıfırdan Hazırla","ilk":"kh1-1-023"},{"baslik":"Ofisi Kapat, Puanını Gör","ilk":"kh1-1-026"},{"baslik":"Dört Araç ve Arabanın Katları","ilk":"kh1-1-305"},{"baslik":"Çok da Olmaz, Az da","ilk":"kh1-1-035"},{"baslik":"Arabayı Provada Hazırla","ilk":"kh1-1-039"},{"baslik":"Kimyasaldan Son Kontrole","ilk":"kh1-1-044"},{"baslik":"Lobinin Sessiz Arabası","ilk":"kh1-1-046"},{"baslik":"Mop Suyu ve Askılar","ilk":"kh1-1-049"},{"baslik":"Kirli Çamaşırın Yolculuğu","ilk":"kh1-1-052"},{"baslik":"Araba Gerekmezse Basket","ilk":"kh1-1-056"},{"baslik":"Rapordaki Harfler Ne Diyor?","ilk":"kh1-1-058"},{"baslik":"Özel Konuklar ve Rahatsız Etmeyin","ilk":"kh1-1-067"},{"baslik":"Kaç Kişilik, Hangi Vardiya?","ilk":"kh1-1-070"},{"baslik":"Sessiz Süpürge, Güvenli Zemin","ilk":"kh1-1-151"},{"baslik":"Görünmeyen Düşmana Karşı","ilk":"kh1-1-155"},{"baslik":"Halıdan Parlak Zemine","ilk":"kh1-1-161"},{"baslik":"Pedin Rengi Neyi Anlatır?","ilk":"kh1-1-165"},{"baslik":"Konuğun Dokunduğu Tekstil","ilk":"kh1-1-171"},{"baslik":"Havlu ve Yedek Stok","ilk":"kh1-1-176"},{"baslik":"Küçük Detay, Büyük İzlenim","ilk":"kh1-1-179"},{"baslik":"Kovadan Süpürgeye","ilk":"kh1-1-183"},{"baslik":"Paspas ve Mop Seçimi","ilk":"kh1-1-187"},{"baslik":"Bez Renkleri Ne Anlatır?","ilk":"kh1-1-190"},{"baslik":"Doğru Ürün, Doğru Yüzey","ilk":"kh1-1-196"},{"baslik":"Cam, Boru ve Kireç","ilk":"kh1-1-201"},{"baslik":"Etiketi Okumadan Kullanma","ilk":"kh1-1-207"},{"baslik":"Kapağı Kapat, Ürünü Sakla","ilk":"kh1-1-212"},{"baslik":"Kendini Koruyarak Yüksekte Çalış","ilk":"kh1-1-219"},{"baslik":"Raporların Yolculuğu","ilk":"kh1-1-222"},{"baslik":"Rapor Kimlere Gider?","ilk":"kh1-1-228"},{"baslik":"Boş, Kirli, Giriş, Çıkış","ilk":"kh1-1-234"},{"baslik":"Dolu, Temiz, Arızalı","ilk":"kh1-1-240"},{"baslik":"Kat Görevlisinin Günlük Raporu","ilk":"kh1-1-245"},{"baslik":"İki Rapor Çelişirse","ilk":"kh1-1-249"},{"baslik":"Raporu Baştan Sona Hazırla","ilk":"kh1-1-254"},{"baslik":"Bozuk Olanı Kime Söylersin?","ilk":"kh1-1-256"},{"baslik":"Planlı Temizlik","ilk":"kh1-1-262"},{"baslik":"Anahtarın Kaydı","ilk":"kh1-1-265"},{"baslik":"Hasar Fark Edilince","ilk":"kh1-1-268"},{"baslik":"Çamaşırlar Karışmasın","ilk":"kh1-1-272"},{"baslik":"Unutulan Eşya Kime Teslim Edilir?","ilk":"kh1-1-276"},{"baslik":"Hizmet Verilemediyse Konuk Ne Görür?","ilk":"kh1-1-282"},{"baslik":"Son Kontrol Kimde?","ilk":"kh1-1-284"},{"baslik":"Diğer Formlar Rehberi","ilk":"kh1-1-287"},{"baslik":"Çalışanın Belgeleri ve Acil Numara","ilk":"kh1-1-293"}],"kavramlar":[{"id":"kh1-1-001","konu":"1.1","terim":"Kat ofisi","ingilizce":"Housekeeping office","tanim":"Kat görevlilerinin günlük hazırlıklarını yaptığı, araç gereçlerini sakladığı ve çalışma arasında kısa süre dinlendiği bölümdür.","ornek":"Sabah 07.30’da oda görevlisi Ayşe, otelin 2. kat ofisinde kat arabasını hazırlar; öğle arasında yine aynı ofiste kısa bir mola verir.","sektor":"Hazırlık ve malzeme tek yerde toplandığı için görevli ihtiyacını aramadan bulur ve işe hemen başlar. Konuk bu bölümü görmez ama hizmetin kalitesi buradaki düzenle başlar.","iliskili":["kh1-1-002","kh1-1-003"],"kontrol":null},{"id":"kh1-1-002","konu":"1.1","terim":"Kat ofisinin yeri ve sayısı","ingilizce":"Location and number of housekeeping offices","tanim":"Kat ofislerinin otelin mimari yapısına ve olanaklarına göre farklı yerlerde ve farklı sayıda kurulabilmesidir.","ornek":"Kapadokya’da taş binalardan oluşan butik bir otelde tek kat ofisi bütün odalara hizmet ederken Bodrum’daki geniş bir tatil köyünde her blokta ayrı bir kat ofisi bulunur.","sektor":"Ofis odalara uzak olursa görevli malzeme için çok yürür ve zaman kaybeder. Bu yüzden ofisin yeri ve sayısı, odalara kolay ulaşım düşünülerek belirlenir.","iliskili":["kh1-1-001","kh1-1-003"],"kontrol":null},{"id":"kh1-1-003","konu":"1.1","terim":"Kat deposu","ingilizce":"Housekeeping store room","tanim":"Yedek malzemelerin ve temizlik kimyasallarının stokta tutulduğu alandır.","ornek":"Öğleden sonra kat şefi Hülya, 3. kat ofisindeki havlu stokunun azaldığını görür ve yedek havlu paketini katın deposundan alır.","sektor":"Depo, günlük ihtiyacın üstündeki stoku ofisten ayırarak ofisin dağınıklaşmasını önler. Rutubetli bir yer depo olarak kullanılmaz.","iliskili":["kh1-1-001","kh1-1-005"],"kontrol":null,"gorsel":"h3b-temizlik-dolabi"},{"id":"kh1-1-004","konu":"1.1","terim":"Kat ofisinde bulunan araç gereçler","ingilizce":"Housekeeping office equipment and supplies","tanim":"Elektrikli süpürge, kat arabaları, yatak takımları, buklet malzemeleri, formlar, kovalar, bezler, deterjanlar, toz ve jel kimyasallar ile eldiven gibi hizmet için gereken ekipman ve malzemelerin bütünüdür.","ornek":"Sabah vardiya başında oda görevlisi Elif, kat arabasını, bez setini, dezenfektanı ve eldivenini aynı ofiste hazır bulduğu için işine hemen başlar.","sektor":"Her malzemenin ayrıntısı ilerleyen konularda anlatılır; ofiste önemli olan hepsinin aranmadan bulunabilecek biçimde düzenli durmasıdır.","iliskili":["kh1-1-001","kh1-1-003","kh1-1-007","kh1-1-300"],"kontrol":null,"gorsel":"t12a-mop-supurge-set"},{"id":"kh1-1-300","konu":"1.1","terim":"Amonyak ve sirke","ingilizce":"Ammonia and vinegar","tanim":"Kat ofisi malzemeleri arasında sayılan; amonyağın yağ ve cam temizliğinde, sirkenin kireç ve koku gidermede kullanıldığı iki temizlik maddesidir.","ornek":"Sabah 09.15’te oda görevlisi Elif, kat ofisi rafında amonyak ve sirke şişelerini etiketleriyle yerinde bulur; lavabo armatüründeki hafif kireç için sirkeli bezi kullanır.","sektor":"Amonyak, çamaşır suyu gibi klor içeren ürünlerle karıştırılmaz; sirke de aynı ürünle karışırsa zehirli gaz çıkar. Sirke mermer ve doğal taş gibi yüzeylerde matlık yapabilir. İşletmenin onayladığı ürün listesi ve etiket esas alınır.","iliskili":["kh1-1-004","kh1-1-196","kh1-1-210"],"kontrol":null},{"id":"kh1-1-005","konu":"1.1","terim":"Ofis ve depoda rutubet","ingilizce":"Damp-free office and store rooms","tanim":"Kat ofisinin ve deponun nemli yerlere kurulmaması, kuru ve rutubetsiz tutulması ilkesidir.","ornek":"Bodrum katta duvarı sürekli nem çeken bir oda depo yapılmak istenince kat şefi Hülya, havluların ve çarşafların bozulacağını söyleyerek daha kuru bir yer seçilmesini ister.","sektor":"Nemli depoda tekstil ve kimyasal zarar görür. Kuru depo hem malzemeyi hem bütçeyi korur.","iliskili":["kh1-1-003","kh1-1-006"],"kontrol":null},{"id":"kh1-1-006","konu":"1.1","terim":"Havalandırma ve kolay temizlenen yüzey","ingilizce":"Ventilation and easy-to-clean surfaces","tanim":"Kat ofisi ve depoda havalandırma sisteminin bulunmasını ve yüzeylerin kolay temizlenebilmesini isteyen düzenleme ilkesidir.","ornek":"Ofiste kimyasal kokusu birikince oda görevlisi Murat havalandırmayı çalıştırır; zemini kolay silinen seramikten olduğu için dökülen sıvıyı da hemen temizler.","sektor":"Havalandırma koku ve nemi dışarı atar; kolay silinen yüzey ise ofisin kendisinin hijyenik kalmasını sağlar.","iliskili":["kh1-1-005","kh1-1-007"],"kontrol":null},{"id":"kh1-1-007","konu":"1.1","terim":"Kat ofisi düzeninde hijyen ve ergonomi","ingilizce":"Hygiene and ergonomics in office layout","tanim":"Kat ofisi ve depoların iş sağlığı ve güvenliğine göre düzenlenirken temizlik kurallarına ve çalışanı zorlamayan bir çalışma düzenine uyulmasıdır.","ornek":"Kat şefi Hülya, ağır deterjan bidonlarını belden aşağıdaki rafa, her gün kullanılan bez setini ise el hizasındaki rafa yerleştirir.","sektor":"Düzenli ve temiz ofiste çalışan ihtiyacı olan malzemeyi zaman kaybetmeden bulur; uygun yerleştirme yorgunluğu ve iş kazası riskini de azaltır.","iliskili":["kh1-1-004","kh1-1-008"],"kontrol":null},{"id":"kh1-1-008","konu":"1.1","terim":"Dolap ve raf düzeni","ingilizce":"Cupboards and shelving","tanim":"Araç gereçlerin düzenli durması için yeterli sayıda dolap ve rafın kurulması ve bunların duvara sağlam biçimde monte edilmesidir.","ornek":"Teknik servis çalışanı Kemal, kat ofisindeki rafları duvara vidalayarak sabitler; böylece havlu yüklü raf, görevli yanından geçerken devrilmez.","sektor":"Sabitlenmemiş raf devrilerek yaralanmaya ve malzeme kaybına yol açabilir. Yeterli raf da malzemenin yerde yığılmasını önler.","iliskili":["kh1-1-007","kh1-1-009","kh1-1-012"],"kontrol":null},{"id":"kh1-1-009","konu":"1.1","terim":"Kilitli kimyasal dolabı","ingilizce":"Locked chemical cabinet","tanim":"Kimyasal ve zehirli maddelerin yetkisi olmayan kişilerin eline geçmemesi için konulduğu kilitli dolaptır.","ornek":"Vardiya sonunda oda görevlisi Murat, dezenfektan ve ovma maddelerini kilitli dolaba yerleştirir ve anahtarı kat şefine teslim eder.","sektor":"Kilit, yetkisiz kişilerin kimyasala ulaşıp kaza yaşamasını önler. Kimyasalın yeri bilindiği için de stok takibi kolaylaşır.","iliskili":["kh1-1-008","kh1-1-015"],"kontrol":null},{"id":"kh1-1-010","konu":"1.1","terim":"Alçak musluklu lavabo","ingilizce":"Low-level sink","tanim":"Kova ve bidon gibi büyük kapların kaldırılmadan doldurulabildiği, musluğu alçakta olan lavabodur.","ornek":"Oda görevlisi Selin, paspas kovasını yerden kaldırmadan alçak musluğun altına yerleştirip doldurur.","sektor":"Dolu kovayı yukarı kaldırmak sırtı yorar. Alçak musluk, çalışanı zorlamadığı gibi zaman da kazandırır.","iliskili":["kh1-1-011","kh1-1-007"],"kontrol":null,"gorsel":"t11a-servis-lavabosu"},{"id":"kh1-1-011","konu":"1.1","terim":"Ofiste sıcak ve soğuk su tesisatı","ingilizce":"Hot and cold water supply in the office","tanim":"Kat ofisinde görevlilerin temizlik için ihtiyaç duyduğu suyun hem sıcak hem soğuk olarak alınabildiği tesisattır.","ornek":"Sabah mop suyunu hazırlayan oda görevlisi Selin, ofisteki sıcak ve soğuk su musluklarından ihtiyacına göre su alır.","sektor":"Su ofiste bulunursa görevli temizlik suyunu odaya çıkmadan hazırlar ve işe daha hızlı başlar.","iliskili":["kh1-1-010","kh1-1-012"],"kontrol":null},{"id":"kh1-1-012","konu":"1.1","terim":"Islak malzeme ve elektrikli ekipman için ayrı bölümler","ingilizce":"Separate areas for wet items and electrical equipment","tanim":"Kat ofisinde ıslak malzemelerin ve elektrikli ekipmanın birbirinden ayrı iki bölümde tutulması kuralıdır.","ornek":"Oda görevlisi Murat, ıslak mop ve kovaları kapılı alt bölüme, elektrikli süpürgeyi ise prizin yanındaki kuru bölüme yerleştirir.","sektor":"Su ile elektriğin yan yana bulunması cihaz arızası ve elektrik çarpması riski yaratır; ayrı bölüm bu riski azaltır.","iliskili":["kh1-1-011","kh1-1-008"],"kontrol":null},{"id":"kh1-1-013","konu":"1.1","terim":"Oda görevlisi çalışma alanı","ingilizce":"Room attendant preparation area","tanim":"Oda görevlilerinin günlük hazırlıklarını rahatça yapabilmesi için kat ofisinde ayrıca düzenlenen alandır.","ornek":"Her sabah oda görevlisi Selin, ofisin köşesindeki düzenli masada iş programını inceler ve kat arabasını hazırlamaya başlar.","sektor":"Hazırlık için ayrılmış alan olduğunda görevli, işe aceleyle değil planlı başlar.","iliskili":["kh1-1-001","kh1-1-007"],"kontrol":null},{"id":"kh1-1-014","konu":"1.1","terim":"Ekipman bakımı ve değişimi","ingilizce":"Equipment maintenance and replacement","tanim":"Kat ofisindeki ekipmanın temizliğinin ve bakımının düzenli yapılması, eskiyen ya da bozulan ekipmanın yenisiyle değiştirilmesidir.","ornek":"Haftalık kontrolde kat şefi Hülya, tekerleği kopmuş bir paspas kovasını fark eder ve değiştirilmesi için talep hazırlar.","sektor":"Bozuk ekipman işi yavaşlatır ve kaza riski taşır. Zamanında yapılan bakım ve değişim hem işi hem çalışanı korur.","iliskili":["kh1-1-016","kh1-1-015"],"kontrol":null},{"id":"kh1-1-306","konu":"1.1","terim":"Araç gereçleri özenle kullanma","ingilizce":"Careful handling of equipment","tanim":"Kat hizmetleri çalışanlarının kat ofisindeki araç gereçleri dikkatli ve amacına uygun kullanmasıdır.","ornek":"Sabah 07.45’te oda görevlisi Selin, elektrikli süpürgeyi kullandıktan sonra kablosunu düzgünce sarar, makineyi temizler ve kuru bölümdeki yerine koyar.","sektor":"Özenle kullanılan ekipman daha uzun ömürlü olur; bozulma ve yenileme gideri azalır, bozuk araç yüzünden işin aksaması önlenir.","iliskili":["kh1-1-014","kh1-1-004"],"kontrol":null},{"id":"kh1-1-015","konu":"1.1","terim":"Kimyasal stokunun yenilenmesi","ingilizce":"Chemical stock replenishment","tanim":"Temizlik kimyasallarının bitmesi beklenmeden yenilerinin alınıp depoya konulmasıdır.","ornek":"Cuma günü kat şefi Hülya, cam temizleyicinin son şişesini görünce hafta sonu yoğunluğu başlamadan yenisini ister.","sektor":"Kimyasal bittiğinde temizlik durursa oda satışa geç hazırlanır; bu da hem konuğu hem işletmeyi etkiler.","iliskili":["kh1-1-009","kh1-1-017"],"kontrol":null},{"id":"kh1-1-016","konu":"1.1","terim":"Eksik malzemenin kat şefine bildirilmesi","ingilizce":"Reporting shortages","tanim":"Çalışanların eksik olan malzemeyi kendi başlarına temin etmeye çalışmadan kat şefine iletmesidir.","ornek":"Oda görevlisi Selin, bez setinin azaldığını görünce vardiyanın başında kat şefi Hülya’ya söyler.","sektor":"Eksikleri şef toplarsa ofisin ihtiyacı tek listede görünür ve malzeme tek seferde istenir.","iliskili":["kh1-1-014","kh1-1-017"],"kontrol":null},{"id":"kh1-1-017","konu":"1.1","terim":"Mal talep formu","ingilizce":"Requisition form","tanim":"Kat şefinin kat ofisinin eksik malzemelerini listeleyip depodan istediği formdur.","ornek":"Öğleden sonra kat şefi Hülya, çalışanların bildirdiği eksikleri forma yazar ve depoya teslim eder; malzeme ertesi sabah ofise gelir.","sektor":"Yazılı talep, depodan hangi malzemenin hangi ofis için çıktığını kayıt altına alır ve yanlış ya da eksik teslimi önler.","iliskili":["kh1-1-016","kh1-1-018"],"kontrol":null,"gorsel":"t12a-form-kalem"},{"id":"kh1-1-018","konu":"1.1","terim":"FIFO yöntemi","ingilizce":"FIFO (First In, First Out)","tanim":"Depoya ilk giren malzemenin ilk kullanılmasını esas alan, yeni gelenin eskilerin arkasına konulduğu yerleştirme yöntemidir.","ornek":"Depoya yeni sabun kolileri gelince Hülya, onları raftaki eski kolilerin arkasına yerleştirir; böylece önce eskiler kullanılır.","sektor":"Eski stok önce çıktığı için malzeme rafta bekleyip bozulmaz. FIFO, gıdada olduğu kadar tekstil ve kimyasal stokunda da kullanılır.","iliskili":["kh1-1-017","kh1-1-003"],"kontrol":null},{"id":"kh1-1-019","konu":"1.1","terim":"Güvenlik işaretleri","ingilizce":"Safety signs","tanim":"Çalışanı tehlikeden korumak için kat ofisi ve depolarda kullanılan; yasaklayıcı, emredici ve uyarıcı olmak üzere üç gruba ayrılan işaretlerdir.","ornek":"Sabah 07.40’ta kimyasal deposuna giren oda görevlisi Murat, kapıdaki “iş ayakkabısı giy” ve “toksik madde” işaretlerini okur; ayakkabısını değiştirip eldivenini takar.","sektor":"İşaret, yazılı talimat okunamayacak hızlı anlarda bile tehlikeyi anlatır. Bu yüzden ofis ve depolarda görünür yerde bulunur.","iliskili":["kh1-1-020","kh1-1-021","kh1-1-022"],"kontrol":null,"gorsel":"mg-uyari-isareti"},{"id":"kh1-1-020","konu":"1.1","terim":"Yasaklayıcı işaretler","ingilizce":"Prohibition signs","tanim":"Belirli bir davranışın yapılmasını yasaklayan güvenlik işaretleridir.","ornek":"Kimyasal deposunun kapısındaki “sigara içilmez” işaretini gören yeni personel Emre, sigarasını dışarıda içer.","sektor":"Dokunma ve sigara içilmez işaretleri bunun örnekleridir. Yasaklayıcı işaretler yangın ve kaza riskini en baştan keser.","iliskili":["kh1-1-019","kh1-1-021"],"kontrol":null,"gorsel":"mg-yasaklayici-isaret"},{"id":"kh1-1-021","konu":"1.1","terim":"Emredici işaretler","ingilizce":"Mandatory signs","tanim":"Bulunulan alanda mutlaka yapılması gereken davranışı belirten güvenlik işaretleridir.","ornek":"Kat deposunun girişindeki “iş ayakkabısı giy” işaretini gören Murat, yedek ayakkabılarını giyip içeri girer.","sektor":"Koruyucu elbise giy ve iş ayakkabısı giy işaretleri bunun örnekleridir. Emredici işaret “şunu yap” der; uyulmazsa çalışan gereksiz yere risk altında kalır.","iliskili":["kh1-1-019","kh1-1-022"],"kontrol":null,"gorsel":"t15aa-emredici-isaretler"},{"id":"kh1-1-022","konu":"1.1","terim":"Uyarıcı işaretler","ingilizce":"Warning signs","tanim":"Çalışanı bulunduğu yerdeki tehlikeye karşı uyaran güvenlik işaretleridir.","ornek":"Islak zemin uyarısı olan koridorda Selin dikkatli yürür; kimyasal depo kapısında toksik madde işaretini görünce eldiven ve maskesini takar.","sektor":"Düşme tehlikesi ve toksik (zehirli) madde işaretleri bunun örnekleridir. Uyarıcı işaret tehlikeyi bildirir ama ne yapılacağını söylemez; çalışan uygun önlemi kendisi alır.","iliskili":["kh1-1-019","kh1-1-020"],"kontrol":null,"gorsel":"h5a-kaygan-zemin"},{"id":"kh1-1-023","konu":"1.1","terim":"Kat ofisi düzenleme uygulaması","ingilizce":"Housekeeping office set-up exercise","tanim":"Kat ofisinin güvenlik ve FIFO kurallarına, ergonomi ve hijyen standartlarına göre düzenlenmesini öğreten, kat hizmetleri atölyesinde yapılan uygulamadır.","ornek":"Atölye dersinde öğrenciler, öğretmenlerinin verdiği yönergeye göre boş bir ofis köşesini ön hazırlıktan son kontrole kadar adım adım düzenler.","sektor":"Ders materyaline göre uygulama 40 dakika sürer ve kat hizmetleri atölyesinde yapılır. Uygulama, ön hazırlık, ofis düzenleme işlemleri ve son kontrol adımlarından oluşur.","iliskili":["kh1-1-024","kh1-1-028"],"kontrol":null},{"id":"kh1-1-024","konu":"1.1","terim":"Ofis hazırlığı: havalandırma ve temizlik","ingilizce":"Preparing the office: airing and cleaning","tanim":"Malzeme yerleştirilmeden önce kat ofisinin havalandırılması, genel temizliğinin yapılması ve içindeki rafların silinmesi işlemidir.","ornek":"Atölyede öğrenci Deniz, ofisin penceresini açar, zemini siler ve rafları nemli bezle temizler; ancak ondan sonra malzemeleri getirir.","sektor":"Temiz olmayan rafa konulan temiz tekstil de kirlenir; bu yüzden temizlik yerleştirmeden önce yapılır.","iliskili":["kh1-1-023","kh1-1-025"],"kontrol":null},{"id":"kh1-1-025","konu":"1.1","terim":"Ofiste temiz malzemelerin yerleştirilmesi","ingilizce":"Placing clean supplies in the office","tanim":"Temiz yatak takımlarının, çarşafların ve havluların temizlenmiş raflara, buklet malzemelerinin ve odalara dağıtılacak form ve magazinlerin de ayrı yerlere yerleştirilmesi işlemidir.","ornek":"Deniz, temiz yatak takımlarını, çarşafları ve havluları raflara dizer; buklet setlerini ve odalara konacak magazinleri ayrı bir rafa koyar.","sektor":"Temiz tekstil ve buklet malzemesi, nemden ve kimyasaldan uzak tutulduğunda konuğa temiz ve kullanıma hazır ulaşır.","iliskili":["kh1-1-024","kh1-1-026"],"kontrol":null,"gorsel":"h3b-camasir-dolabi-ofis"},{"id":"kh1-1-026","konu":"1.1","terim":"Kimyasalların kapalı bölüme yerleştirilmesi","ingilizce":"Placing chemicals in the closed section","tanim":"Oda temizliğinde kullanılan kimyasalların kapalı bölüme konulması ve bulundukları bölümdeki uyarı levhalarının kontrol edilmesi işlemidir.","ornek":"Deniz, kimyasalları kapaklı dolaba yerleştirir ve dolabın kapağındaki uyarı levhasının yerinde olup olmadığına bakar.","sektor":"Kapalı bölüm, kimyasalın tekstile ya da gıdaya bulaşmasını engeller. Uyarı levhası da ofise yeni giren çalışanı kimyasalın tehlikesine karşı uyarır.","iliskili":["kh1-1-025","kh1-1-027"],"kontrol":null},{"id":"kh1-1-027","konu":"1.1","terim":"Yedek sarf malzemeleri ve temizlik gereçlerinin yerleştirilmesi","ingilizce":"Placing spare consumables and cleaning tools","tanim":"Odalara konulacak tuvalet ve havlu kâğıtlarının istiflenmesi, yedek çöp torbalarının, fırçaların, mopların ve süpürgelerin yerleştirilmesi işlemidir.","ornek":"Deniz, tuvalet kâğıtlarını rafa dizer; yedek çöp torbalarını, fırçaları, mop ve süpürgeleri de kendi bölümlerine yerleştirir.","sektor":"Her malzemenin sabit yeri olunca eksik olan hemen fark edilir, yedek de bulunması zor bir yerde kalmaz.","iliskili":["kh1-1-026","kh1-1-028"],"kontrol":null},{"id":"kh1-1-028","konu":"1.1","terim":"Ofiste elektrikli ekipman ve kat arabalarının yerleşimi","ingilizce":"Placing electrical equipment and trolleys","tanim":"Kat ve oda temizliğinde kullanılan elektrikli ekipmanın yerleştirilmesi, kat arabalarının düzenlenmesi ve ofisin hazırlık bittikten sonra kapatılması işlemidir.","ornek":"Deniz elektrikli süpürgeyi kuru bölümdeki prizin yanına koyar, kat arabalarını sıraya dizer ve ofis hazır olunca kapıyı kapatır.","sektor":"Ofis en son kontrolden sonra kapatılır; böylece sabah gelen ekip hazır ve düzenli bir ofis bulur.","iliskili":["kh1-1-027","kh1-1-012"],"kontrol":null},{"id":"kh1-1-029","konu":"1.1","terim":"Atölye uygulaması puanlama çizelgesi","ingilizce":"Practical assessment sheet","tanim":"Bir kat hizmetleri uygulamasının ön hazırlık, uygulama becerisi, zamanı kullanma, iletişim ve olağan dışı durumlara hazır bulunma ölçütleriyle puanlandığı çizelgedir.","ornek":"Uygulama sonunda öğretmen, Deniz’in ön hazırlığını, işi süresinde bitirmesini ve arkadaşlarıyla iletişimini çizelgeye puanlayarak işler.","sektor":"Uygulamanın türüne göre öğretmenin belirleyeceği ölçütler de çizelgede yer alır. Çizelge, öğrencinin hangi beceride güçlenmesi gerektiğini gösterir.","iliskili":["kh1-1-023","kh1-1-039"],"kontrol":null},{"id":"kh1-1-305","konu":"1.2","terim":"Kat hizmetlerinde kullanılan araba ve basket türleri","ingilizce":"Types of housekeeping trolleys and caddies","tanim":"Kat arabası, genel alan temizlik arabası, kirli çamaşır toplama arabası ve elle taşınabilir temizlik basketi olmak üzere kat hizmetlerinde kullanılan dört araçtır.","ornek":"Sabah 07.30’da kat şefi Hülya, yeni oda görevlisi Selin’e ofisteki dört aracı tek tek gösterir: odalar için kat arabası, lobi için genel alan arabası, toplanan çamaşır için kirli çamaşır arabası, küçük ve acil işler için basket.","sektor":"Hangi iş için hangi aracın seçileceğini bilmek zaman kazandırır. Yemek servisinde kullanılan oda servisi arabası kat hizmetlerinin araçlarından biri değildir.","iliskili":["kh1-1-030","kh1-1-046","kh1-1-052","kh1-1-056"],"kontrol":null},{"id":"kh1-1-030","konu":"1.2.1","terim":"Kat arabası","ingilizce":"Housekeeping trolley","tanim":"Oda temizliğinde gerekli ekipman ve malzemelerin bulunduğu, kat hizmetleri çalışanlarının kullandığı arabadır.","ornek":"Sabah 08.00’de oda görevlisi Murat, temizleyeceği odalara hazır bir kat arabasıyla çıkar; temiz çarşaf, havlu ve bez setini yanında taşır.","sektor":"Kat arabası görevlinin hareketli deposudur. İyi düzenlenmiş araba, ofise tekrar tekrar dönmeyi gereksiz kılar.","iliskili":["kh1-1-031","kh1-1-032","kh1-1-033"],"kontrol":null,"gorsel":"h3a-on-buronun-kat-hizmetleriyle"},{"id":"kh1-1-031","konu":"1.2.1","terim":"Kat arabasının üst bölümü","ingilizce":"Trolley top section","tanim":"Kat arabasında buklet malzemelerinin ve formların konulduğu üst kısımdır.","ornek":"Oda görevlisi Selin, arabanın üst bölümüne şampuan ve sabun setlerini, oda formlarını yerleştirir.","sektor":"Buklet ve formlar sık kullanıldığı için üstte, görevlinin hemen ulaşabileceği yerde durur.","iliskili":["kh1-1-030","kh1-1-032"],"kontrol":null,"gorsel":"t11a-temizlik-arabasi-havlular"},{"id":"kh1-1-032","konu":"1.2.1","terim":"Kat arabasının alt rafları","ingilizce":"Trolley lower shelves","tanim":"Kat arabasında temiz çarşaf, yatak takımı ve havluların katlanarak yerleştirildiği alt kısımdır.","ornek":"Sabah 08.10’da Murat, ağır havlu istiflerini ve çarşafları katlayıp arabanın alt raflarına dizer; üst bölüme yalnızca buklet setlerini koyar, böylece koridorda araba dengeli ilerler.","sektor":"Ağır ve hacimli tekstil altta durduğu için araba devrilmeden dengeli ilerler.","iliskili":["kh1-1-030","kh1-1-031","kh1-1-033"],"kontrol":null},{"id":"kh1-1-033","konu":"1.2.1","terim":"Kat arabasının yan bölmeleri","ingilizce":"Trolley side compartments","tanim":"Kat arabasının kenarlarında, oda temizliğinde kullanılan kimyasalların ve yanlarında toz bezlerinin bulunduğu bölmelerdir.","ornek":"Selin, kimyasalları arabanın yan bölmesine, toz bezlerini de hemen yanına yerleştirir; mopu bir tarafa, çöp torbalarını öbür tarafa takar.","sektor":"Kimyasal yan bölmede tutulunca tekstilden ayrı kalır. Arabanın bir tarafına mop gibi araçlar, diğer tarafına çöp torbaları yerleştirilir.","iliskili":["kh1-1-030","kh1-1-032","kh1-1-034"],"kontrol":null},{"id":"kh1-1-034","konu":"1.2.1","terim":"Atık ayrıştırmaya uygun renkli çöp torbaları","ingilizce":"Colour-coded waste bags","tanim":"Odalardan toplanan cam, plastik, kâğıt ve diğer atıkların geri dönüşüm amacıyla ayrı toplanabilmesi için kat arabasında kullanılan farklı renkli torbalardır.","ornek":"Sabah 10.30’da 214 numaralı odayı temizleyen Murat, plastik şişeleri bir torbaya, kâğıtları ayrı renkteki torbaya koyar; torba renklerinin hangi atığa ayrıldığını işletmenin listesinden bilir.","sektor":"Atık, baştan ayrı toplanırsa geri dönüşüme gider ve otel çevreye karşı sorumluluğunu yerine getirir.","iliskili":["kh1-1-033","kh1-1-030"],"kontrol":null},{"id":"kh1-1-035","konu":"1.2.1","terim":"Kat arabasının temiz ve arızasız olması","ingilizce":"Clean and fault-free trolley","tanim":"Kat arabasının kirli ya da bozuk olmaması, tekerleğinin ve rafının sağlam olması ilkesidir.","ornek":"Sabah 07.50’de vardiyaya başlayan Selin, arabasının tekerleğinin takıldığını görür; koridorda konuklar varken gıcırdayacağı için kullanmadan kat şefine bildirir ve yedek araba ister.","sektor":"Kirli ya da arızalı araba iş yavaşlatır, konuk gözü önünde de kötü izlenim bırakır.","iliskili":["kh1-1-030","kh1-1-037"],"kontrol":null,"gorsel":"t12n-temizlik-arabasi"},{"id":"kh1-1-036","konu":"1.2.1","terim":"Arabaya konulacak temiz çamaşırın doğru hesaplanması","ingilizce":"Calculating clean linen for the trolley","tanim":"Kat arabasına konulacak temiz çarşaf, yastık kılıfı ve havlunun temizlenecek oda ve yatak sayısına göre hesaplanmasıdır.","ornek":"Selin’in raporunda tek kişilik yataklı iki oda, çift kişilik yataklı üç oda vardır; arabasına bu yatak sayısına uygun çarşafı ve havluyu alır.","sektor":"Doğru hesap hem eksikliği hem de gereksiz yükü önler.","iliskili":["kh1-1-030","kh1-1-037","kh1-1-038"],"kontrol":null},{"id":"kh1-1-037","konu":"1.2.1","terim":"Arabanın eksik hazırlanması","ingilizce":"Under-stocked trolley","tanim":"Kat arabasına gerekli malzemelerin tamamının konulmaması durumudur.","ornek":"Murat sabah 08.00’de arabasına yalnızca altı havlu alıp çıkar; 3. kattaki dördüncü odada havlu bitince iki kez ofise döner ve vardiya sonunda planladığından iki oda eksik temizler.","sektor":"Eksik hazırlanan araba zaman ve enerji kaybına yol açar: görevli yürür, bekler ve vardiya içinde temizlenen oda sayısı düşer.","iliskili":["kh1-1-036","kh1-1-038"],"kontrol":null},{"id":"kh1-1-038","konu":"1.2.1","terim":"Arabanın fazla yüklenmesi","ingilizce":"Overloaded trolley","tanim":"Kat arabasına gerekenden fazla araç gereç konulması durumudur.","ornek":"Selin, arabaya iki günlük havlu alınca arabayı itmekte zorlanır ve köşede bir bez seti yere düşer.","sektor":"Fazla yük arabayı ağırlaştırır ve malzemenin dökülmesine yol açabilir; görevliyi yorar, kaza riskini artırır. Araba ihtiyaç kadar doldurulur.","iliskili":["kh1-1-037","kh1-1-036"],"kontrol":null},{"id":"kh1-1-039","konu":"1.2.1","terim":"Kat arabası hazırlama uygulaması","ingilizce":"Trolley preparation exercise","tanim":"Kat arabasının hazırlık işlemlerini otel standartlarına ve işletme prosedürüne uygun biçimde yapmayı öğreten, atölyede ya da işletmede yapılan uygulamadır.","ornek":"Atölye dersinde öğrenci Deniz, yönergeye göre boş bir kat arabasını güvenlik önlemlerinden son kontrole kadar hazırlar.","sektor":"Ders materyaline göre uygulama 20 dakika sürer ve konaklama atölyesinde ya da işletmede yapılır. Adımlar ön hazırlık, sayım ve rapor, malzemelerin yerleştirilmesi ve son kontroldür.","iliskili":["kh1-1-040","kh1-1-041"],"kontrol":null},{"id":"kh1-1-040","konu":"1.2.1","terim":"Kat arabası ön hazırlığı","ingilizce":"Preliminary trolley preparation","tanim":"Arabaya malzeme yerleştirmeden önce iş sağlığı ve güvenliği önlemlerinin alınması ve arabanın temizliğinin yapılmasıdır.","ornek":"Deniz eldivenini takar, arabanın raflarını silerek temizler ve ancak ondan sonra malzeme almaya gider.","sektor":"Temiz olmayan araba temiz tekstili kirletir; güvenlik önlemi de görevliyi korur.","iliskili":["kh1-1-039","kh1-1-041"],"kontrol":null},{"id":"kh1-1-041","konu":"1.2.1","terim":"Rapordan oda ve yatak sayısı kontrolü","ingilizce":"Checking the number of rooms and beds from the report","tanim":"Kat görevlisi raporuna bakılarak temizlenecek oda ve yatak sayısının kontrol edilmesi ve odaların durumlarının not alınmasıdır.","ornek":"Deniz raporu açıp yedi odanın kaçında tek, kaçında çift kişilik yatak olduğunu sayar ve odaların durumlarını not eder.","sektor":"Sayı bilinmeden hazırlanan araba eksik ya da fazla olur; bu yüzden sayım, malzeme almadan önce yapılır.","iliskili":["kh1-1-040","kh1-1-042"],"kontrol":null},{"id":"kh1-1-042","konu":"1.2.1","terim":"Arabaya yatak malzemelerinin yerleştirilmesi","ingilizce":"Placing bed linen and towels on the trolley","tanim":"Oda ve yatak sayısı kadar tek ve çift kişilik yatak çarşaflarının, yastık kılıflarının ve havlu takımlarının arabaya yerleştirilmesidir.","ornek":"Deniz, rapordaki yatak sayısına göre tek ve çift kişilik çarşaf ile yastık kılıflarını sayıp arabanın alt rafına dizer.","sektor":"Sayıya göre alınan tekstil, odada eksiği tamamlamak için ofise gidiş gelişi önler.","iliskili":["kh1-1-041","kh1-1-043"],"kontrol":null},{"id":"kh1-1-043","konu":"1.2.1","terim":"Arabaya buklet, magazin ve form yerleştirilmesi","ingilizce":"Placing amenities and forms on the trolley","tanim":"Hazırlanacak oda sayısı kadar buklet setinin ve odalara konulacak magazin ve formların kat arabasına yerleştirilmesidir.","ornek":"Deniz, yedi oda için yedi buklet seti sayar; magazinleri ve formları arabanın üst bölümüne koyar.","sektor":"Buklet seti odaya göre sayılınca ne eksik ne fazla olur. Fazlası arabayı ağırlaştırır.","iliskili":["kh1-1-042","kh1-1-044"],"kontrol":null},{"id":"kh1-1-044","konu":"1.2.1","terim":"Arabaya kimyasal, bez ve fırça yerleştirilmesi","ingilizce":"Placing chemicals, cloths and brushes on the trolley","tanim":"Temizlikte kullanılacak deterjan ve kimyasalların hazırlanıp kat arabasının kimyasal bölümüne, temizlik bezleriyle fırçaların da yanına yerleştirilmesidir.","ornek":"Deniz, deterjan ve kimyasalları arabanın kimyasal bölmesine, bezleri ve fırçaları da yanına koyar.","sektor":"Kimyasal, temiz tekstilden ayrı ve sağlam bir bölmede taşınır; böylece çarşaf ve havlu kirlenmez. Ders metni kimyasalların arabanın yan bölmelerine, uygulama yaprağı ise arabanın “en üst kısmındaki bölüme” konmasını söyler; yer araba modeline göre değişir, değişmeyen kural kimyasalın tekstilden ayrı tutulmasıdır.","iliskili":["kh1-1-043","kh1-1-045"],"kontrol":null,"gorsel":"t15aa-kat-arabasi-fircali"},{"id":"kh1-1-045","konu":"1.2.1","terim":"Kat arabası son kontrolü","ingilizce":"Final trolley check","tanim":"Odalara konulacak yedek torba ve kâğıtların yerleştirilip atık torbalarının geri dönüşüm renklerine göre takıldığı, temiz mop ve paspasların araba kenarına konduğu ve arabanın ofiste uygun yere çekildiği son aşamadır.","ornek":"Deniz yedek torbaları ve kâğıtları yerleştirir, atık torbalarını renklerine göre takar, mopu araba kenarına koyar ve arabayı ofiste uygun yere çeker.","sektor":"Son kontrol, görevlinin odada eksik malzeme yüzünden duraksamamasını sağlar.","iliskili":["kh1-1-044","kh1-1-034"],"kontrol":null},{"id":"kh1-1-046","konu":"1.2.2","terim":"Genel alan temizlik arabası","ingilizce":"Public area cleaning trolley","tanim":"Konaklama işletmelerinde lobi, restoran gibi genel alanların temizliğinde kullanılan arabadır.","ornek":"Gece 23.00’te lobide konuklar hâlâ otururken lobi görevlisi Emre, genel alan arabasını sessizce çekerek mermer zemini siler; konukların sohbeti kesilmez.","sektor":"Genel alan arabası konuklar varken çalışır; bu yüzden sessiz ve düzenli olmalıdır.","iliskili":["kh1-1-047","kh1-1-049","kh1-1-048"],"kontrol":null,"gorsel":"t10a-genel-alan-arabasi"},{"id":"kh1-1-047","konu":"1.2.2","terim":"Genel alan arabasının tekerlekleri","ingilizce":"Public area trolley wheels","tanim":"Arabanın konuklar arasında sessizce ilerlemesini, çarpmalara karşı korunmasını ve park edildiğinde kaymamasını sağlayan kolay hareketli, tamponlu ve frenli tekerlek yapısıdır.","ornek":"Gece 23.15’te Emre, tamponlu ve sessiz tekerlekli arabayı lobiden asansör önüne sürer; asansör kapısında freni kullanarak arabanın kendiliğinden kaymasını önler.","sektor":"Sessiz tekerlek konukları rahatsız etmez; fren de arabanın kayıp kazaya yol açmasını engeller.","iliskili":["kh1-1-046","kh1-1-048"],"kontrol":null,"gorsel":"t12a-genel-alan-arabasi"},{"id":"kh1-1-048","konu":"1.2.2","terim":"Genel alan arabasının gövdesi ve bölmeleri","ingilizce":"Public area trolley body and compartments","tanim":"Kolay temizlenebilen, dayanıklı malzemeden yapılmış gövdesi ile kapalı ve açık bölümlerinden oluşan yapıdır.","ornek":"Sabah 06.45’te Emre, kimyasal şişelerini arabanın kapalı bölümüne, sık kullandığı bezleri ise elinin altındaki açık bölüme koyar; gün sonunda gövdeyi nemli bezle silerek temiz tutar.","sektor":"Kapalı bölüm kimyasalı gizler; açık bölüm sık kullanılanı hızlı erişilir kılar. Kolay silinen gövde arabanın kendi hijyenini korur.","iliskili":["kh1-1-046","kh1-1-051"],"kontrol":null,"gorsel":"t15aa-genel-alan-arabasi"},{"id":"kh1-1-049","konu":"1.2.2","terim":"Pres kova sistemi","ingilizce":"Mop wringer bucket","tanim":"Genel alan arabasında mop suyunun sıkıldığı kova sistemidir.","ornek":"Gece 23.20’de lobiyi silen Emre, mopu pres kovada iyice sıkar; zemin fazla ıslanmadığı için geç saatte inen bir konuk kaymadan yürür.","sektor":"Mop suyunun iyi sıkılması zemini fazla ıslatmaz; böylece kayma riski azalır.","iliskili":["kh1-1-046","kh1-1-050"],"kontrol":null,"gorsel":"t13c-pres-kovali-sistem"},{"id":"kh1-1-050","konu":"1.2.2","terim":"Kuru ve ıslak mop ve paspas takımları","ingilizce":"Dry and wet mop and floor-cloth sets","tanim":"Genel alan arabasında zemin temizliği için taşınan, kuru ve ıslak kullanılmak üzere ayrılmış mop ve paspas takımlarıdır.","ornek":"Sabah 06.30’da Emre, lobideki tozu önce kuru mopla toplar, ardından ıslak paspasla zemini siler; kuru mopu ıslak suya hiç sokmaz.","sektor":"Kuru ve ıslak takımın ayrı tutulması, kuru tozla ıslak mopun kirletilmemesini sağlar.","iliskili":["kh1-1-049","kh1-1-046"],"kontrol":null,"gorsel":"t11a-mop-basliklari"},{"id":"kh1-1-051","konu":"1.2.2","terim":"Askı aparatı ve tepsiler","ingilizce":"Hooks and trays","tanim":"Genel alan arabasında dezenfektan ve kimyasalları taşımaya yarayan askı aparatları ve tepsilerdir.","ornek":"Akşam 21.00’de Emre, dezenfektan şişesini arabanın askı aparatına asar ve küçük bezlerini tepsiye dizer; koltuk yanındaki lekeye uzanırken şişe devrilmez.","sektor":"Askı ve tepsi, kimyasalın devrilip dökülmesini önler ve eldeki işe yakın tutar.","iliskili":["kh1-1-048","kh1-1-050"],"kontrol":null},{"id":"kh1-1-052","konu":"1.2.3","terim":"Kirli çamaşır toplama arabası","ingilizce":"Soiled linen trolley","tanim":"Oda temizliği sırasında toplanan kirli çarşaf, havlu ve yatak takımlarının konulduğu arabadır.","ornek":"Murat, 3. katta odalardan topladığı kirli çarşafları ve havluları kirli çamaşır arabasına koyar.","sektor":"Kirli çamaşırın ayrı bir arabada toplanması temiz tekstille karışmasını önler.","iliskili":["kh1-1-053","kh1-1-054"],"kontrol":null,"gorsel":"h3b-camasir-arabalari"},{"id":"kh1-1-053","konu":"1.2.3","terim":"Kirli çamaşır arabasının bölümleri","ingilizce":"Soiled linen trolley sections","tanim":"Çamaşırın türüne göre ayrı toplanabilmesi için havlu ve çarşaf gibi tekstili birbirinden ayıran farklı bölmelerdir.","ornek":"Sabah 11.00’de 3. kattaki odaları toplayan Murat, havluları arabanın bir bölmesine, çarşafları diğerine atar; çamaşırhane görevlisi teslimde türleri ayırmakla uğraşmaz.","sektor":"Çamaşır baştan türüne göre ayrılırsa çamaşırhanenin işi kolaylaşır.","iliskili":["kh1-1-052","kh1-1-054"],"kontrol":null},{"id":"kh1-1-054","konu":"1.2.3","terim":"Kirli çamaşır arabasının konumu","ingilizce":"Positioning the soiled linen trolley","tanim":"Çamaşır toplama arabasının temizlik yapılan odalara yakın, koridordaki geçişi engellemeyecek bir noktada bulundurulmasıdır.","ornek":"Murat, kirli çamaşır arabasını temizlediği odaların koridorunda, geçişi engellemeyecek bir noktada bırakır.","sektor":"Araba odaya yakın olunca görevli kirli çamaşırı uzağa taşımaz, zaman kazanır.","iliskili":["kh1-1-052","kh1-1-055"],"kontrol":null,"gorsel":"h3a-kat-hizmetleri-departmani"},{"id":"kh1-1-055","konu":"1.2.3","terim":"Kirli çamaşırın çamaşırhaneye teslimi","ingilizce":"Handing over soiled linen to the laundry","tanim":"Görevlinin tüm odalardan topladığı kirli çamaşırları çamaşırhane birimine teslim etmesidir.","ornek":"Öğle arasından önce, 12.15’te Murat, 3. kattaki bütün kirli çamaşırı çamaşırhane birimine teslim eder; öğleden sonra temiz tekstil rafı yenilenir.","sektor":"Kirli çamaşır ofiste bekletilmeyip çamaşırhaneye zamanında verilirse temiz tekstil stoku düzenli yenilenir.","iliskili":["kh1-1-052","kh1-1-054"],"kontrol":null,"gorsel":"t11a-kirli-camasir-sepetleri"},{"id":"kh1-1-056","konu":"1.2.4","terim":"Elle taşınabilir temizlik basketi","ingilizce":"Cleaning caddy","tanim":"Lobi, restoran gibi yerlerde araba yerine kullanılan, genel temizlik kimyasalları ve bezlerin taşındığı sepettir.","ornek":"Akşam 19.00’da lobide koltuk yanına çay damlayınca Selin, temizlik basketini alıp lekeyi siler.","sektor":"Basket kolay taşınır; bu yüzden acil durumlarda ve basit yüzeysel temizliklerde hızlıdır.","iliskili":["kh1-1-057","kh1-1-030"],"kontrol":null,"gorsel":"t12r-temizlik-basketi"},{"id":"kh1-1-057","konu":"1.2.4","terim":"Temizlik basketinin kullanım alanı","ingilizce":"Where a cleaning caddy is used","tanim":"Araba götürülemeyen veya götürmeye gerek olmayan kısa işlerde, acil durumlarda ve basit yüzeysel temizliklerde basketin tercih edilmesidir.","ornek":"Akşam yemeğinde restoranda bir masaya bardak devrilince Emre arabayı çağırmaz; basketini alıp masayı iki dakikada siler, çünkü iş küçük ve acildir.","sektor":"Doğru araç seçimi zaman kazandırır. Büyük işte basket yetmez, küçük iş için araba da gerekmez.","iliskili":["kh1-1-056","kh1-1-046"],"kontrol":null,"gorsel":"t15aa-temizlik-basketi"},{"id":"kh1-1-058","konu":"1.2.4","terim":"Oda durumu kısaltmaları","ingilizce":"Room status abbreviations","tanim":"Raporlarda ve ofis listelerinde oda durumunu kısaca belirtmek için kullanılan harf ve işaretlerdir.","ornek":"Sabah Selin, rapordaki “V/C”, “OCC” gibi kısaltmaları okuyarak hangi odanın nasıl bir durumda olduğunu anlar.","sektor":"Kısaltma, kat hizmetleri ile ön büronun aynı dili konuşmasını sağlar. Kısaltma işletmeden işletmeye değişebilir; kullanılan liste ofiste hazır bulundurulur.","iliskili":["kh1-1-234","kh1-1-240","kh1-1-242","kh1-1-063"],"kontrol":null},{"id":"kh1-1-063","konu":"1.2.4","terim":"DEP kısaltması","ingilizce":"DEP (Departure)","tanim":"Konuğun o gün işletmeden ayrılmasının beklendiğini gösteren kısaltmadır.","ornek":"Raporda 305 numaralı odanın yanında DEP yazdığını gören Selin, o odada konuğun bugün ayrılacağını anlar.","sektor":"DEP, hangi odanın bugün ayrılacağını bilmeyi sağlar; temizlik planı bu bilgiye göre yapılır. Çıkış işleminin yapıldığını C/O gösterir.","iliskili":["kh1-1-236","kh1-1-064"],"kontrol":null},{"id":"kh1-1-064","konu":"1.2.4","terim":"ARR kısaltması","ingilizce":"ARR (Arrival)","tanim":"Konuğun o gün otele varmasının beklendiğini gösteren kısaltmadır.","ornek":"Rapora ARR yazılan odayı gören Selin, o oda için gün içinde yeni bir konuğun geleceğini anlar ve odayı hazır tutar.","sektor":"ARR, arrival (varış) demektir. ARR’lı odalar öncelikli hazırlanır; konuğun geldiği saatte oda hazır olmalıdır.","iliskili":["kh1-1-237","kh1-1-063"],"kontrol":null},{"id":"kh1-1-065","konu":"1.2.4","terim":"D/U kısaltması","ingilizce":"D/U (Day use)","tanim":"Odanın gün içinde kısa süreli, geceleme olmadan kullanıldığını gösteren kısaltmadır.","ornek":"Öğleden sonra D/U yazılı bir odayı akşam yeni konuk için hazırlayan Selin, odayı baştan temizler.","sektor":"Gündüz kullanımından sonra oda akşam başka konuğa verilebilir; bu yüzden tam temizlik gerekir.","iliskili":["kh1-1-064","kh1-1-058"],"kontrol":null},{"id":"kh1-1-067","konu":"1.2.4","terim":"VIP kısaltması","ingilizce":"VIP (Very Important Person)","tanim":"Odada kalan konuğun özel ilgi gerektiren önemli bir misafir olduğunu gösteren kısaltmadır.","ornek":"Sabah 09.30’da rapordaki VIP yazılı 702 numaralı odayı hazırlayan Selin, çarşafları ve bukletleri bir kez daha kontrol eder; hazırlıktan sonra kat şefinin bakmasını ister.","sektor":"VIP’li odada küçük ayrıntılar hizmeti yükseltir; özel hazırlığın kapsamı işletmenin prosedürüne göre belirlenir.","iliskili":["kh1-1-058","kh1-1-068"],"kontrol":null},{"id":"kh1-1-068","konu":"1.2.4","terim":"COMP kısaltması","ingilizce":"COMP (Complimentary)","tanim":"İşletmede ücretsiz konaklayan misafirleri gösteren kısaltmadır.","ornek":"Rapordaki COMP yazılı odayı gören Selin, yönetimin davet ettiği ücretsiz misafirin odasını da diğer konuklarla aynı standartta hazırlar.","sektor":"Ücret ödenmemesi hizmet standardını değiştirmez.","iliskili":["kh1-1-067","kh1-1-069"],"kontrol":null},{"id":"kh1-1-069","konu":"1.2.4","terim":"DND kısaltması","ingilizce":"DND (Do Not Disturb)","tanim":"Rahatsız etmeyin anlamına gelen ve odaya hiçbir şekilde girilmemesi gerektiğini bildiren kısaltmadır.","ornek":"Sabah 10.00’da raporda DND yazan 505 numaralı odayı gören Murat, kapıyı çalmadan sonraki odaya geçer; konuk uyanıp isterse temizlik daha sonra yapılır.","sektor":"Konuk DND diyorsa ona saygı gösterilir; ayrıntılı uygulama ikinci ünitede anlatılır.","iliskili":["kh1-1-068","kh1-1-067"],"kontrol":null,"gorsel":"f3c-dnd-cokdilli"},{"id":"kh1-1-070","konu":"1.2.4","terim":"SNG kısaltması","ingilizce":"SNG (Single)","tanim":"Odanın tek kişilik olduğunu gösteren kısaltmadır.","ornek":"Rapordaki SNG yazan odayı gören Selin, tek kişilik yatak takımını ve tek konuk için havlu ayırır.","sektor":"Oda tipi bilinirse arabaya doğru miktarda yatak takımı ve havlu konur.","iliskili":["kh1-1-071","kh1-1-072"],"kontrol":null,"gorsel":"t10a-tek-kisilik-oda"},{"id":"kh1-1-071","konu":"1.2.4","terim":"DBL kısaltması","ingilizce":"DBL (Double)","tanim":"Odanın çift kişilik olduğunu gösteren kısaltmadır.","ornek":"Sabah 09.45’te raporda DBL yazan 306 numaralı odaya Selin iki kişilik yatak takımı ve iki konuğa yetecek havlu hazırlar; arabasından eksik havlu için ofise dönmez.","sektor":"Çift kişilik odada iki konuk için tekstil gerekir; oda tipi karışırsa konuk eksik malzemeyle karşılaşır.","iliskili":["kh1-1-070","kh1-1-072"],"kontrol":null,"gorsel":"t12a-cift-kisilik-oda"},{"id":"kh1-1-072","konu":"1.2.4","terim":"TRP kısaltması","ingilizce":"TRP (Triple)","tanim":"Odanın üç kişilik olduğunu gösteren kısaltmadır.","ornek":"TRP yazılı odayı hazırlayan Murat, üç konuk için üç takım havlu ve gerekli yatak takımını arabaya alır.","sektor":"Üç kişilik odada tekstil miktarı artar; arabaya buna göre malzeme konulur.","iliskili":["kh1-1-071","kh1-1-073"],"kontrol":null,"gorsel":"os-triple"},{"id":"kh1-1-073","konu":"1.2.4","terim":"SUIT kısaltması","ingilizce":"SUIT (Suite)","tanim":"Büyük odayı, yani suiti gösteren kısaltmadır.","ornek":"Sabah 09.00’da rapordaki SUIT yazılı 701 numaralı oda için Selin, diğer odalardan daha fazla süre ayırır ve arabasına ek havlu ile buklet alır.","sektor":"Suitler daha büyük olduğu için daha çok zaman ve malzeme gerektirir.","iliskili":["kh1-1-072","kh1-1-074"],"kontrol":null,"gorsel":"h6-aile-suiti"},{"id":"kh1-1-074","konu":"1.2.4","terim":"SHIFT kısaltması","ingilizce":"SHIFT (Shift)","tanim":"Vardiyayı, yani nöbeti gösteren kısaltmadır.","ornek":"Pazar günü 07.30’da çalışma çizelgesindeki SHIFT yazısını gören Selin, bunun vardiya yani nöbet anlamına geldiğini bilir ve yarın akşam vardiyasına göre gün planını yapar.","sektor":"Vardiya kısaltması iş programında çalışma saatini bildirir.","iliskili":["kh1-1-073","kh1-1-075"],"kontrol":null},{"id":"kh1-1-075","konu":"1.2.4","terim":"O ve X işaretleri","ingilizce":"O and X marks","tanim":"Bazı kat raporlarında “O” işaretinin tamir gerektiren odayı, “X” işaretinin meşgul odayı belirttiği kısaltmalardır.","ornek":"Sabah 09.20’de rapordaki O işaretli 412 numaralı odanın tamir gerektirdiğini gören Selin, odaya girmeden kat şefine bildirir; kat şefi teknik servisi arar.","sektor":"Bu işaretler uluslararası bir standart değildir ve her işletmede aynı olmayabilir; ofisteki işaret listesine bakmak gerekir.","iliskili":["kh1-1-058","kh1-1-074"],"kontrol":null},{"id":"kh1-1-151","konu":"1.3.1","terim":"Otel tipi elektrikli süpürge","ingilizce":"Commercial vacuum cleaner","tanim":"Yüksek emiş gücü ve sessiz çalışmasıyla zemindeki çok küçük kirlere kadar derin temizlik yapan, kolay taşınan endüstriyel süpürgedir.","ornek":"Sabah 10.15’te Bodrum’daki bir otelde oda görevlisi Ayşe, çıkış yapan konuğun halı kaplı odasında sessiz çalışan süpürgeyle yatağın altını da temizler; koridordaki konuklar rahatsız olmaz.","sektor":"Zeminde bulunan akar (mite) türü mikroskobik canlılara kadar temizlik yapılması hijyeni sağlar. Sessiz ve kolay taşınır olması konuğun rahatsız edilmemesi için de önemlidir.","iliskili":["kh1-1-152","kh1-1-153"],"kontrol":null},{"id":"kh1-1-152","konu":"1.3.1","terim":"Islak-kuru elektrikli süpürge","ingilizce":"Wet-and-dry vacuum cleaner","tanim":"Kuru süpürmenin yanında ıslak kirleri de çekebilen, belirli aralıklarla halı, mobilya ve yatak yıkamada da kullanılan elektrikli süpürgedir.","ornek":"Öğleden sonra 14.30’da kat şefi Murat, konuğun devirdiği suyun halıda bıraktığı ıslaklığı ıslak-kuru süpürgeyle çektirir.","sektor":"Elektrikli süpürgelerin bir kısmı yalnızca kuru süpürme yapar, bir kısmı ıslak-kuru kullanıma uygundur. Kullanmadan önce makinenin hangi türde olduğuna bakılır.","iliskili":["kh1-1-151","kh1-1-161"],"kontrol":null},{"id":"kh1-1-153","konu":"1.3.2","terim":"Zemin temizleme makinesi","ingilizce":"Floor scrubber-dryer","tanim":"Lobi, havuz kenarı ve restoran gibi temizliğe duyarlı alanlarda yüksek vakumla ıslak-kuru çalışarak zemini temizleyen makinedir.","ornek":"Gece 23.30’da genel alan görevlisi Burak, lobideki mermeri zemin temizleme makinesiyle yıkar ve aynı geçişte kurutur; sabah erken inen konuklar kaygan zemine basmaz.","sektor":"Silip aynı anda suyu çektiği için kayma ve düşme riskini azaltır. Konuğun en çok yürüdüğü alanlarda güvenlik demektir.","iliskili":["kh1-1-154","kh1-1-151"],"kontrol":null,"gorsel":"t15aa-zemin-temizleme-makinesi"},{"id":"kh1-1-154","konu":"1.3.2","terim":"Çok işlevli zemin makinesi","ingilizce":"Multi-function floor machine","tanim":"Temizleme, silme, yıkama ve cila işlemlerini tek makinede yapabilen yeni nesil zemin makinesidir.","ornek":"Sezon açılışına üç gün kala Antalya’daki bir otelin teknik ekibi, tek makineyle hem lobi zeminini yıkar hem de cilalar.","sektor":"Tek makine birden çok ihtiyacı karşıladığı için işletme daha az ekipman alır, depoda daha az yer tutar ve bakım işi azalır.","iliskili":["kh1-1-153","kh1-1-163"],"kontrol":null},{"id":"kh1-1-155","konu":"1.3.3","terim":"Cansız ortamda dezenfeksiyon","ingilizce":"Disinfection of inanimate surfaces","tanim":"Hastalık yapıcı mikroorganizmaların cansız ortamda öldürülmesi ya da üremelerinin durdurulması işlemidir.","ornek":"Sabah 09.30’da oda görevlisi Selin, çıkış yapan konuğun odasında kapı kolunu ve televizyon kumandasını önce siler, sonra dezenfekte eder.","sektor":"Dezenfeksiyon ısı, ultraviyole (UV) ışını ve kimyasal maddelerle yapılır. Temizlik kiri alır; dezenfeksiyon ise mikroorganizmayı hedefler.","iliskili":["kh1-1-156","kh1-1-157"],"kontrol":null},{"id":"kh1-1-156","konu":"1.3.3","terim":"Dezenfektanın temizlik maddesinden farkı","ingilizce":"Disinfectant versus cleaning agent","tanim":"Cansız yüzeylerdeki mikroorganizmaları yok etmek için kullanılan, temizlik maddesi sayılmayan kimyasal maddedir.","ornek":"Akşam 18.00’de banyoyu temizleyen Emre, lavabo çevresini önce genel temizlik maddesiyle siler, durular, ardından dezenfektan uygular.","sektor":"Dezenfektan bir temizlik maddesi değildir; bu yüzden temizlikten sonra kullanılır. Yüzeye ve ortamdaki mikroorganizmanın türüne göre seçilir.","iliskili":["kh1-1-155","kh1-1-157"],"kontrol":null,"gorsel":"t12r-dezenfektan-sprey"},{"id":"kh1-1-157","konu":"1.3.3","terim":"Dezenfeksiyon yöntemleri","ingilizce":"Disinfection methods","tanim":"Dezenfeksiyonun ısıyla, ultraviyole (UV) ışınlarıyla ya da kimyasal maddelerle yapılabilmesidir.","ornek":"Bir otelin çamaşırhanesinde yüksek ısıyla işlem yapılırken, kat ofisinde kimyasal dezenfektan, spa bölümünde ise UV cihazı tercih edilir.","sektor":"Yöntem; yüzeye, ortama ve mikroorganizmaya göre seçilir. UV ışını bu yöntemlerden biridir.","iliskili":["kh1-1-155","kh1-1-158"],"kontrol":null},{"id":"kh1-1-158","konu":"1.3.3","terim":"Buharlı dezenfeksiyon makinesi","ingilizce":"Steam disinfection machine","tanim":"Güçlü buhar teknolojisiyle yalnızca dezenfeksiyon işlemi yapan makinedir.","ornek":"Öğleden sonra 15.00’te kat şefi Hülya, çocuk odalarındaki koltukların dezenfeksiyonu için buharlı makineyi hazırlatır.","sektor":"Dezenfeksiyon makineleri iki türdedir: yalnızca güçlü buharla çalışanlar ve solüsyonla çalışanlar.","iliskili":["kh1-1-159","kh1-1-160"],"kontrol":null},{"id":"kh1-1-159","konu":"1.3.3","terim":"Solüsyonlu dezenfeksiyon makinesi","ingilizce":"Solution-based disinfection machine","tanim":"Dezenfektan solüsyonlarıyla işlem yapan dezenfeksiyon makinesidir.","ornek":"Gece vardiyasında genel alan ekibi, toplantı salonunun sandalyelerini solüsyonlu makineyle dezenfekte eder.","sektor":"Solüsyonlu makinede kullanılacak dezenfektan, yüzeye ve kullanma talimatına uygun seçilir ve oranına dikkat edilir.","iliskili":["kh1-1-158","kh1-1-156"],"kontrol":null},{"id":"kh1-1-160","konu":"1.3.3","terim":"Kapalı yer ve eşya dezenfeksiyonu","ingilizce":"Disinfection of rooms and items","tanim":"Buhar ya da püskürtülen dezenfektanla kapalı alanların, buhar ya da kuru ısıyla eşyaların dezenfekte edilmesidir.","ornek":"Pazartesi sabahı 08.00’de kapalı bir toplantı odası püskürtülen dezenfektanla işlenirken, odanın perdeleri buharla dezenfekte edilir.","sektor":"Kapalı yerler ile eşyalar için yöntemler farklı olduğundan işe başlamadan önce neyin dezenfekte edileceği belirlenir.","iliskili":["kh1-1-155","kh1-1-158"],"kontrol":null},{"id":"kh1-1-161","konu":"1.3.4","terim":"Halı ve koltuk yıkama makinesi","ingilizce":"Carpet and upholstery extraction machine","tanim":"Yıkama ve süpürme işini tek makinede yapabilen, halı ve koltukları yıkamakta kullanılan makinedir.","ornek":"Uludağ’daki bir otelde sezon öncesi sabah 09.00’da halı kaplı odalarda halı yıkama makinesiyle derin temizlik yapılır.","sektor":"Teknoloji ilerledikçe yıkama ve süpürme tek makinede birleşti; bu da işi hızlandırır ve odanın kapalı kalma süresini kısaltır.","iliskili":["kh1-1-152","kh1-1-151"],"kontrol":null},{"id":"kh1-1-162","konu":"1.3.5","terim":"Cila","ingilizce":"Floor polish","tanim":"Yüzeyi korumak, temizliğini kolaylaştırmak ve estetik bir görünüm kazandırmak için uygulanan kimyasal maddedir.","ornek":"Sezon açılışından önce lobinin mermer zemini yeniden cilalanır; ilk gün gelen konuklar parlak bir zeminde yürür.","sektor":"Zeminin özelliğine göre farklı cilalar seçilir ve yüksek devirle çalışan makinelerle uygulanır.","iliskili":["kh1-1-163","kh1-1-164"],"kontrol":null},{"id":"kh1-1-163","konu":"1.3.5","terim":"Cilalama makinesi","ingilizce":"Floor polishing machine","tanim":"Zeminin cinsine uygun cilayı yüksek devirle uygulayan makinedir.","ornek":"Gece 01.00’de restoran kapandıktan sonra bakım ekibi, ahşap zemini yüksek devirli cilalama makinesiyle işler; zemin sabah 07.00’de kullanıma hazırdır.","sektor":"Cilalama sık yapılan bir iş olmadığından makine ve ekipmanları kat ofisinde ya da depoda iyi korunarak saklanır.","iliskili":["kh1-1-162","kh1-1-165"],"kontrol":null},{"id":"kh1-1-164","konu":"1.3.5","terim":"Sert zeminlerin cilalanma sıklığı","ingilizce":"Floor polishing frequency","tanim":"Zeminin genellikle sezon başında ve sonunda, ayrıca yıpranma durumuna göre ara dönemlerde yeniden cilalanmasıdır.","ornek":"Mayıs başında sezon açılırken otelin taş zeminleri cilalanır; temmuzda yoğun geçiş olan koridorda bir parlatma daha yapılır.","sektor":"Ders materyaline göre sert zeminlere sezon başı ve sezon sonu olmak üzere iki kez cila uygulanır. Yumuşak ve yıpranmaya yatkın yüzeylerde cilalama daha sık yapılabilir.","iliskili":["kh1-1-162","kh1-1-163"],"kontrol":null},{"id":"kh1-1-165","konu":"1.3.5","terim":"Renk kodlu cila pedleri","ingilizce":"Colour-coded floor pads","tanim":"Cilalama makinelerinde yüzeye ve işin türüne göre rengiyle ayırt edilen pedlerin kullanılmasıdır.","ornek":"Bakım ekibi şefi Kemal, ovma işinde yeşil pedi, ardından parlatmada beyaz pedi makineye takar; ped renklerinin anlamını üreticinin kullanım talimatından da kontrol eder.","sektor":"Doğru ped seçilmezse zemin gereğinden fazla aşınabilir. Ped renkleri üreticiye göre değişebileceği için kullanım talimatına bakılır.","iliskili":["kh1-1-166","kh1-1-170","kh1-1-163"],"kontrol":null,"gorsel":"t11a-zemin-pedleri"},{"id":"kh1-1-166","konu":"1.3.5","terim":"Beyaz ped","ingilizce":"White floor pad","tanim":"Islak ve kuru zemini parlatmak için kullanılan cilalama pedidir.","ornek":"Cila uygulandıktan sonra bakım görevlisi Ferhat, zeminin parlaklığını artırmak için makineye beyaz ped takar.","sektor":"Beyaz ped parlatma işinin son basamağında kullanılır; ovma ve söküm pedleriyle karıştırılmaz.","iliskili":["kh1-1-165","kh1-1-167"],"kontrol":null},{"id":"kh1-1-167","konu":"1.3.5","terim":"Yeşil ped","ingilizce":"Green floor pad","tanim":"Cilalamadan önce zemini ovmak için kullanılan pedidir.","ornek":"Sabah 07.30’da bakım görevlisi Nur, yeni cila sürülmeden önce lobi zeminini yeşil pedle ovar; kir kalkmazsa cilanın düzgün tutunmayacağını bilir.","sektor":"Ovma yüzeydeki kiri alır ve cilanın düzgün tutunmasına hazırlık yapar.","iliskili":["kh1-1-165","kh1-1-166"],"kontrol":null},{"id":"kh1-1-168","konu":"1.3.5","terim":"Mavi ped","ingilizce":"Blue floor pad","tanim":"Islak ve köpüklü ovma işlemlerinde ve kuvvetli sprey ile yapılan temizlikte kullanılan pedidir.","ornek":"Sabah 06.00’da havuz çevresindeki kaygan zemini ıslak ve köpüklü ovmak için Ömer, cilalama makinesine mavi pedi takar; iş bitince zemini durular.","sektor":"Ped seçimi iş türüne göre yapılır; ıslak ve köpüklü işte mavi, parlatmada beyaz ped kullanılır.","iliskili":["kh1-1-165","kh1-1-169"],"kontrol":null},{"id":"kh1-1-169","konu":"1.3.5","terim":"Kırmızı ped","ingilizce":"Red floor pad","tanim":"Sprey temizliğinde kullanılan cilalama makinesi pedidir.","ornek":"Her sabah 06.30’da koridorun günlük bakımında Zeynep, kırmızı pedi takıp zemini sprey temizlikle hızla geçer; derin ovma gereken yerde başka ped seçer.","sektor":"Günlük hafif bakım ile derin ovma ya da cila sökme işleri için farklı pedler gerekir.","iliskili":["kh1-1-165","kh1-1-168"],"kontrol":null},{"id":"kh1-1-170","konu":"1.3.5","terim":"Siyah ped","ingilizce":"Black floor pad","tanim":"Pedlerin en sert ve aşındırıcı olanı olup cila sökme ve yaş yüzeylerde etkin temizlik için kullanılan pedidir.","ornek":"Sezon sonunda eski cilanın kalkmasını isteyen bakım ekibi, günlük bakım pedlerini kenara koyup siyah pedi seçer; zemini aşındırmamak için süreyi kısa tutar.","sektor":"En sert ped olduğu için günlük bakım yerine eski cilayı sökerken kullanılır; yanlış yerde kullanılırsa zemini aşındırabilir.","iliskili":["kh1-1-165","kh1-1-167"],"kontrol":null},{"id":"kh1-1-171","konu":"1.3.6","terim":"Yatak takımları","ingilizce":"Bed linen sets","tanim":"Konuğun rahat uyuması için hazırlanan yatak, çarşaf, yastık ve nevresim gibi ürünlerden oluşan takımlardır.","ornek":"Akşam 17.00’de oda görevlisi Pelin, 410 numaralı odanın yatak takımını açık renkli, ütülü ve lekesiz ürünlerle hazırlar; konuk gelince yatağı ilk bakışta temiz bulur.","sektor":"Konaklama işletmeleri rahat, temiz ve kaliteli yataklar sunarak konuğun memnuniyetini artırmayı amaçlar. Oda yatakları büyüklüklerine göre tek tip seçilir; böylece çarşaf ve nevresim her yatağa uyar.","iliskili":["kh1-1-172","kh1-1-178"],"kontrol":null,"gorsel":"h3b-gergin-carsaf"},{"id":"kh1-1-172","konu":"1.3.6","terim":"Otel nevresimi","ingilizce":"Hotel duvet cover","tanim":"Yatak yapımında yorgan ya da battaniyeyi saran açık renkli otel tekstilidir.","ornek":"Sabah 11.00’de oda görevlisi Elif, çıkış yapan konuğun nevresimini söküp kat arabasındaki temiz takımla değiştirir.","sektor":"Açık renk nevresim lekeyi ve temizliği hemen belli ettiği için konuğa temizlik güvencesi verir.","iliskili":["kh1-1-173","kh1-1-171"],"kontrol":null,"gorsel":"h6-nevresim-yatak"},{"id":"kh1-1-173","konu":"1.3.6","terim":"Nevresimin yıkamaya dayanıklılığı","ingilizce":"Durability of linen in washing","tanim":"Günlük yıkanan nevresimlerin yıkama ve ütüleme işlemlerine dayanıklı olması gerekliliğidir.","ornek":"Satın alma müdürü Cem, deneme amaçlı aldığı ince kumaşın birkaç yıkamada eskidiğini görünce dayanıklı bir ürüne geçer.","sektor":"Yıkamada çabuk eskiyen nevresim sık değiştirilir; bu hem maliyeti artırır hem de odadaki görüntüyü bozar.","iliskili":["kh1-1-172","kh1-1-174"],"kontrol":null},{"id":"kh1-1-174","konu":"1.3.6","terim":"Eponj havlu","ingilizce":"Terry towel","tanim":"Otellerde kullanılan, ilmikli dokumasıyla suyu iyi emen havlu türüdür.","ornek":"Akşam 18.30’da spa girişinde resepsiyon görevlisi Aylin, havuzdan çıkan konuğa suyu iyi emen, ilmikli dokulu temiz bir eponj havlu uzatır.","sektor":"Otel havluları kaliteli iplikle dokunursa daha uzun ömürlü olur.","iliskili":["kh1-1-175","kh1-1-176"],"kontrol":null,"gorsel":"h3b-havlu-yigini"},{"id":"kh1-1-175","konu":"1.3.6","terim":"Otel havlusunda aranan nitelikler","ingilizce":"Qualities of a hotel towel","tanim":"Suyu iyi emmesi, yıkamaya dayanması ve sertleşme oranının düşük olması gibi otel havlusundan beklenen özelliklerdir.","ornek":"Satın alma ekibi, numune havlulara su damlatıp yıkama sonrası yumuşaklığını karşılaştırarak seçim yapar.","sektor":"Sertleşen ya da suyu zor emen havlu konuğun beklentisini karşılamaz; kalite bu yüzden iplik ve dokumaya bakılarak belirlenir.","iliskili":["kh1-1-174","kh1-1-176"],"kontrol":null,"gorsel":"t12a-beyaz-havlu"},{"id":"kh1-1-176","konu":"1.3.6","terim":"Standart havlu ölçüleri","ingilizce":"Standard towel sizes","tanim":"Havluların el, banyo ve ayak gibi kullanım yerlerine göre belirli ebatlarda hazırlanmasıdır.","ornek":"Kat ofisinde depo sorumlusu Gül, ayak havlularını banyo havlularından ebat farkıyla ayırarak rafa dizer.","sektor":"Ders materyaline göre el havlusu 50x90 cm, banyo havlusu 70x140, 90x150 ya da 100x150 cm, ayak havlusu 50x70 cm ölçüsündedir.","iliskili":["kh1-1-177","kh1-1-174"],"kontrol":null},{"id":"kh1-1-177","konu":"1.3.6","terim":"El, banyo, ayak havlusu ve bornoz","ingilizce":"Hand, bath and foot towels and bathrobe","tanim":"Konuklara sunulan, üst kalitede olması gereken havlu çeşitleri ile bornozdur.","ornek":"Gece 21.00’de turn-down servisi yapan Ece, banyoda el, banyo ve ayak havlularını yerli yerine koyar, bornozu askıya asar.","sektor":"El, vücut ve ayak havluları ile bornozun kalitesi, konuğun odayı ve oteli değerlendirmesinde belirleyicidir.","iliskili":["kh1-1-176","kh1-1-178"],"kontrol":null,"gorsel":"t10a-bornoz-banyo"},{"id":"kh1-1-178","konu":"1.3.6","terim":"Yedek nevresim ve havlu takımları","ingilizce":"Spare linen and towel sets","tanim":"Konuk talebiyle gün içinde değiştirilecek takımlar için kat ofisinde oda ve yatak sayısından fazla nevresim ve havlu bulundurulmasıdır.","ornek":"Öğleden sonra 16.00’da denizden dönen bir konuk ikinci kez havlu isteyince oda görevlisi Naz, kat ofisindeki yedek takımdan hemen getirir.","sektor":"Yedek stok olmazsa konuk beklemek zorunda kalır; yedek bulundurmak hizmet kalitesini korur.","iliskili":["kh1-1-177","kh1-1-171"],"kontrol":null,"gorsel":"h3b-camasir-dolabi"},{"id":"kh1-1-179","konu":"1.3.7","terim":"Buklet seti","ingilizce":"Guest amenity set","tanim":"Konuğun odadaki ihtiyaçlarını karşılamak için hazırlanan kişisel bakım ve banyo ürünlerinden oluşan settir.","ornek":"Sabah 11.30’da oda görevlisi Derya, konuk sayısı kadar buklet setini kat arabasından alıp banyodaki tepsiye yerleştirir.","sektor":"Buklet setleri işletmenin saygınlığını artıran küçük ama önemli detaylardır.","iliskili":["kh1-1-180","kh1-1-181","kh1-1-182"],"kontrol":null,"gorsel":"t10a-banyo-seti"},{"id":"kh1-1-180","konu":"1.3.7","terim":"Banyo ürünleri","ingilizce":"Bathroom toiletries","tanim":"Şampuan, sabun ve vücut losyonu gibi konuğun banyoda kullandığı ürünlerdir.","ornek":"Gece 21.30’da 508 numaralı odada duşa giren konuk, şampuanı ve sabunu banyo rafında hazır bulur; eksik olsaydı resepsiyonu arayıp yeniden isterdi.","sektor":"Banyo ürünleri buklet setinin temel parçasıdır; eksik olması konuğun şikâyetine neden olabilir.","iliskili":["kh1-1-179","kh1-1-181"],"kontrol":null,"gorsel":"t12r-banyo-tepsi"},{"id":"kh1-1-181","konu":"1.3.7","terim":"Yardımcı buklet ürünleri","ingilizce":"Additional amenities","tanim":"Kibrit, tırnak törpüsü ve duş bonesi gibi banyo ürünlerini tamamlayan küçük ürünlerdir.","ornek":"Düğün için gelen konuk grubunun odalarını 15.00’te hazırlayan Derya, her banyo tepsisine duş bonesi ve tırnak törpüsünü de koyar; konuklar bunları ayrıca istemek zorunda kalmaz.","sektor":"Yardımcı ürünler, temel ürünlerin yanında konuğa düşünüldüğünü hissettirir.","iliskili":["kh1-1-179","kh1-1-180"],"kontrol":null,"gorsel":"t15ab-buklet-yardimci-set"},{"id":"kh1-1-182","konu":"1.3.7","terim":"Buklet malzemelerinin görünümü","ingilizce":"Presentation of amenities","tanim":"İşletmenin saygınlığını yansıtacak şekilde setlerin şık ve düzenli görünmesine özen gösterilmesidir.","ornek":"Kat şefi Sibel, 14.00’te oda kontrolünde buklet ürünlerinin tepside düzgün sıralandığına ve etiketlerin öne dönük durduğuna bakar; eğri duran seti kendisi düzeltir.","sektor":"Estetik görünüm konuğun otelle ilgili ilk izlenimini güçlendirir.","iliskili":["kh1-1-179","kh1-1-180"],"kontrol":null,"gorsel":"t15ab-buklet-kutu-dizisi"},{"id":"kh1-1-183","konu":"1.3.8","terim":"Kova","ingilizce":"Bucket","tanim":"İçine sıvı konulup taşınmasını sağlayan temel temizlik malzemesidir.","ornek":"Sabah 09.00’da koridor görevlisi Hakan, kovaya temizlik suyunu doldurur; kovayı sağlam bir zemine koyarak devrilmesini önler.","sektor":"Kova, kat hizmetlerinin temel malzemelerindendir; farklı ebat ve renklerde bulunur.","iliskili":["kh1-1-184","kh1-1-185"],"kontrol":null,"gorsel":"t10a-paspas-kovasi"},{"id":"kh1-1-184","konu":"1.3.8","terim":"Fırça","ingilizce":"Brush","tanim":"Doğal lif (kıl, ot) ya da plastikten yapılan, kat görevlilerinin işini kolaylaştıran temizlik ekipmanıdır.","ornek":"Akşam 18.00’de banyo temizliğinde Gülcan, klozet çevresini plastik fırçayla ovar; fırçayı iş bitince kimyasal artığı kalmayacak biçimde yıkar.","sektor":"Fırçalar pratik oldukları için yaygın kullanılır; yüzeye göre biçimleri değişir.","iliskili":["kh1-1-185","kh1-1-183"],"kontrol":null,"gorsel":"t10a-el-fircasi-faras"},{"id":"kh1-1-185","konu":"1.3.8","terim":"Yüzeye göre fırça seçimi","ingilizce":"Choosing brushes by surface","tanim":"Sert zemin, genel yüzey, banyo, lavabo ve klozet gibi ıslak alanlarda doğal lifli ya da plastik fırçalardan yüzeye uygun olanın seçilmesidir.","ornek":"Oda görevlisi Berk, 10.30’da mermer lavabonun yüzeyini çizmemek için yumuşak fırça seçer; sert fırçayı yalnızca zemin derzleri gibi dayanıklı yerlerde kullanır.","sektor":"Yanlış fırça yüzeyi çizebilir ya da temizliği yetersiz bırakır; bu yüzden yüzey önce tanınır.","iliskili":["kh1-1-184","kh1-1-186"],"kontrol":null,"gorsel":"t12a-el-fircasi"},{"id":"kh1-1-186","konu":"1.3.8","terim":"Süpürge","ingilizce":"Broom","tanim":"Kullanılacak yüzeye göre biçimi değişen temizlik aracıdır.","ornek":"Terasta kahvaltı başlamadan, 08.30’da Orhan sert zemini yüzeye uygun süpürgeyle süpürür; toz konukların masalarına yapışmasın diye süpürmeyi önceden bitirir.","sektor":"Süpürge ve fırçalar kat hizmetlerinde yüzeye göre seçilen temel ekipmanlardır.","iliskili":["kh1-1-185","kh1-1-183"],"kontrol":null,"gorsel":"t13c-supurge-faras-paspas"},{"id":"kh1-1-301","konu":"1.3.8","terim":"Sünger","ingilizce":"Sponge","tanim":"Fırçayla birlikte kat görevlilerinin kullandığı, yüzeyleri silmeyi ve ovmayı kolaylaştıran temizlik malzemesidir.","ornek":"Akşam 18.30’da banyo temizliğinde oda görevlisi Burak, lavabonun kenarını elinde rahat tutabildiği küçük bir süngerle siler; sonra süngeri kimyasal artığı kalmayacak biçimde yıkar.","sektor":"Kova, fırça ve süngerler farklı ebat ve renklerde bulunur; renkler işletmeye göre hangi aracın hangi alanda kullanılacağını göstermek için seçilir.","iliskili":["kh1-1-184","kh1-1-183","kh1-1-192"],"kontrol":null,"gorsel":"t15ab-sunger-sari-yesil"},{"id":"kh1-1-187","konu":"1.3.9","terim":"Mop","ingilizce":"Mop","tanim":"İç zeminlerin ıslak ve kuru temizliğinde kullanılan temizlik aracıdır.","ornek":"Akşam 19.00’da koridoru silerken Gamze, ıslak silme için ayrılmış mopu, kuru silme için başka renkteki mopu seçer; renkler işletmenin listesine göredir.","sektor":"Islak silme, kuru silme ve nemli silme için farklı renkte mop kullanmak temizliği kolaylaştırır. Renk-iş eşleşmesi işletmeye göre değişir.","iliskili":["kh1-1-188","kh1-1-189"],"kontrol":null,"gorsel":"t11a-mop-kovada"},{"id":"kh1-1-188","konu":"1.3.9","terim":"Saçaklı paspas","ingilizce":"String mop","tanim":"Yüzeylerin ıslak silinmesinde kullanılan saçaklı paspastır.","ornek":"Sabah 08.30’da banyo zeminini silen Kadir, ıslak silmek için saçaklı paspası kullanır; suyu fazla kalan yerleri lastikli paspasla çeker.","sektor":"Saçaklı paspaslar ıslak silme için uygundur; fazla suyu çekmek için lastikli paspas tercih edilir.","iliskili":["kh1-1-187","kh1-1-189"],"kontrol":null,"gorsel":"t11a-sacakli-paspas"},{"id":"kh1-1-189","konu":"1.3.9","terim":"Lastikli paspas","ingilizce":"Squeegee","tanim":"Beton, mozaik, taş ve mermer gibi zeminlerde fazla suyu çekip yüzeyi toz ve çamurdan arındıran paspastır.","ornek":"Yağmurlu bir günde teras girişinde biriken suyu Ali, 10.00’da lastikli paspasla dışarı çeker; içeri giren konuklar kaymaz.","sektor":"Fazla su zeminde kaymaya yol açabilir; lastikli paspas bu riski azaltır.","iliskili":["kh1-1-188","kh1-1-187"],"kontrol":null,"gorsel":"t13c-lastikli-paspas"},{"id":"kh1-1-190","konu":"1.3.10","terim":"Mikrofiber bezin otel kullanımı","ingilizce":"Microfibre cloth in hotel use","tanim":"Çok inceltilmiş ipliklerden üretilen, nemli ya da kuru kullanılabilen ve konaklama işletmelerinde en çok tercih edilen temizlik bezidir.","ornek":"Sabah 10.00’da oda görevlisi Beyza, banyo aynasını nemli mikrofiber bezle siler; aynı bezi sonra tuvalet çevresinde kullanmaz.","sektor":"Mikrofiber bez nemli de kuru da kullanılabildiği için hem zemin hem toz temizliğinde tercih edilir.","iliskili":["kh1-1-191","kh1-1-192"],"kontrol":null,"gorsel":"h3b-mikrofiber-bez"},{"id":"kh1-1-191","konu":"1.3.10","terim":"Mikrofiber bezin nemli ve kuru kullanımı","ingilizce":"Damp and dry use of microfibre cloths","tanim":"Zemin temizliğinde bezin nemli, toz almada kuru kullanılmasıdır.","ornek":"Sabah 10.20’de Beyza, oda masasındaki tozu kuru bezle alır, banyo zeminini ise nemli bezle siler; kuru bezi ıslak yüzeyde kullanmaz.","sektor":"Bu şekilde kullanım temizliği daha hijyenik ve daha kısa sürede yapılabilir hâle getirir.","iliskili":["kh1-1-190","kh1-1-192"],"kontrol":null},{"id":"kh1-1-192","konu":"1.3.10","terim":"Renk kodlu bez sistemi","ingilizce":"Colour-coded cloth system","tanim":"Temizlenen alana göre farklı renkte bez kullanılmasıdır.","ornek":"Kat şefi Sevgi, yeni gelen oda görevlilerine bez renklerinin hangi alan için ayrıldığını tahtadaki listeyle gösterir.","sektor":"Renk kodu, bezlerin yanlış alanda kullanılmasını önler ve hijyeni korur. Renk-alan eşleşmesi işletmeye göre değişebilir.","iliskili":["kh1-1-193","kh1-1-194","kh1-1-190"],"kontrol":null,"gorsel":"t12r-mikrofiber-set"},{"id":"kh1-1-193","konu":"1.3.10","terim":"Sarı mikrofiber bez","ingilizce":"Yellow microfibre cloth","tanim":"Küvet ve lavabo yüzeylerini silmek için ayrılan mikrofiber bezdir.","ornek":"Sabah 11.00’de banyoyu temizleyen Tuğba, küveti ve lavaboyu sarı bezle siler; aynı bezle klozeti silmez, çünkü o iş için ayrı bez vardır.","sektor":"Aynı bezin başka alanlarda kullanılması hijyeni bozar; küvet-lavabo bezi yalnızca bu işte kullanılır.","iliskili":["kh1-1-192","kh1-1-194"],"kontrol":null},{"id":"kh1-1-194","konu":"1.3.10","terim":"Cam, toz ve banyo zemini için bez renkleri","ingilizce":"Cloth colours for glass, dust and bathroom floor","tanim":"Cam silmede mavi, toz almada pembe, banyo zemininde yeşil mikrofiber bezin kullanılmasıdır.","ornek":"Haftalık toplantıda kat şefi Hasan, yeni oda görevlilerine tahtadaki renk tablosunu göstererek mavi bezin yalnızca camda, pembe bezin toz almada kullanıldığını anlatır.","sektor":"Bez renkleri ve işleri işletmeye göre farklılık gösterebilir; işletmenin kendi renk tablosuna bakılır.","iliskili":["kh1-1-192","kh1-1-193"],"kontrol":null,"gorsel":"t15ab-renkli-mikrofiber-bezler"},{"id":"kh1-1-195","konu":"1.3.10","terim":"Bardak ve klozet çevresinde kâğıt havlu","ingilizce":"Paper towel for glasses and toilet area","tanim":"Bez yerine kâğıt havlunun bardak silmede ve klozet ile çevresinin temizliğinde kullanılmasıdır.","ornek":"Konuk odasında bardakları kâğıt havluyla silen Merve, klozet çevresini de tek kullanımlık havluyla temizler.","sektor":"Kâğıt havlu tek kullanımlıktır; kirin başka alanlara taşınmasını önler. İşletmeye göre tuvalet için ayrılmış renkli bez de kullanılabilir.","iliskili":["kh1-1-192","kh1-1-190"],"kontrol":null},{"id":"kh1-1-196","konu":"1.3.11","terim":"Temizlik maddesi seçimi","ingilizce":"Choosing cleaning agents","tanim":"Kaliteli ve yüzeye uygun ürünün seçilerek iş gücü kaybının, yüzey hasarının ve sağlık risklerinin önlenmesidir.","ornek":"Yeni gelen ahşap parkeyi görünce satın alma sorumlusu Deniz, parkeye uygun nötr temizlik maddesi alır.","sektor":"Doğru ürün seçmek iş gücü kaybını önler; ayrıca iş sağlığı ve güvenliği için de önemlidir.","iliskili":["kh1-1-197","kh1-1-198","kh1-1-199"],"kontrol":null,"gorsel":"t12a-temizlik-basketi"},{"id":"kh1-1-197","konu":"1.3.11","terim":"Temel temizlik maddeleri","ingilizce":"Heavy-duty cleaners","tanim":"Taş, mozaik ve fayans gibi yüzeylerdeki yoğunlaşmış kiri ve cilayı yüzeyden çıkarmakta kullanılan maddelerdir.","ornek":"Sezon açılışında taş zeminlerdeki yoğun kiri temizlemek için bakım ekibi temel temizlik maddesi kullanır.","sektor":"Ahşap zeminde kesinlikle kullanılmaz; yanlış yüzeyde kullanılması zarar verir.","iliskili":["kh1-1-196","kh1-1-198"],"kontrol":null},{"id":"kh1-1-198","konu":"1.3.11","terim":"Genel temizlik maddeleri","ingilizce":"General-purpose cleaners","tanim":"Banyo, küvet, fayans, cam, ayna ve kapı gibi yüzeylerde kullanılan, asitli madde içermediği için yüzeye zarar vermeyen maddelerdir.","ornek":"Akşam 18.30’da banyo temizliğinde Melike, küvet ve fayansı genel temizlik maddesiyle siler, ardından yüzeyi bol suyla durular.","sektor":"Kullanıldıktan sonra yüzey iyi durulanır. Bu ürünler genellikle hoş kokuludur ve asitli madde içermediği için yüzeye zarar vermez.","iliskili":["kh1-1-196","kh1-1-199"],"kontrol":null,"gorsel":"t12a-sprey-sisler"},{"id":"kh1-1-199","konu":"1.3.11","terim":"Nötr temizlik maddeleri","ingilizce":"Neutral cleaners","tanim":"Asitli ve alkali maddelerin zarar verdiği cilalı yüzeylerde tercih edilen, kimyasal etkisi nötr temizlik maddeleridir.","ornek":"Lobideki cilalı mermeri silen Tolga, cilanın matlaşmaması için nötr temizlik maddesi kullanır.","sektor":"Asitli maddeler cilanın matlaşmasına ya da çıkmasına yol açar; alkaliler de zarar verir.","iliskili":["kh1-1-198","kh1-1-197"],"kontrol":null},{"id":"kh1-1-200","konu":"1.3.11","terim":"Ovma maddeleri","ingilizce":"Scouring agents","tanim":"Yüzeydeki kirleri ovma yoluyla temizleyen, banyo, lavabo, küvet ve fayans temizliğinde kullanılan maddelerdir.","ornek":"Banyodaki inatçı lekeyi temizlemek için Seda, toz ovma maddesi yerine sıvı ovma maddesini seçer.","sektor":"Klor içeren ovma maddeleri kirleri yok eder ve yüzeyi ağartır. Toz ovma maddeleri yüzeyi sıvılara göre daha çok çizdiği için sıvı olanlar tercih edilir.","iliskili":["kh1-1-198","kh1-1-203"],"kontrol":null,"gorsel":"t11a-ovma-teli"},{"id":"kh1-1-201","konu":"1.3.11","terim":"Cam ve ayna temizleme maddeleri","ingilizce":"Glass cleaners","tanim":"Cam ve aynalardaki parmak izi ile lekeyi gidermek için üretilmiş temizlik gereçleridir.","ornek":"Sabah 10.30’da Ceren, balkon kapısının camını cam temizleme maddesiyle siler; konuk manzarayı lekesiz görsün diye köşeleri de kontrol eder.","sektor":"Cam ve ayna konuğun ilk bakacağı yerlerdendir; bu yüzden özel temizlik maddeleri kullanılır.","iliskili":["kh1-1-198","kh1-1-206"],"kontrol":null,"gorsel":"t12r-cam-silme"},{"id":"kh1-1-202","konu":"1.3.11","terim":"Tıkanmış boru açma maddeleri","ingilizce":"Drain openers","tanim":"Su tesisatında saç ve sabun artıkları gibi tıkanıklıkları kimyasal etkiyle eriterek boruları ve giderleri açan güçlü maddelerdir.","ornek":"Banyo gideri yavaş akınca teknik servis görevlisi boru açma maddesini eldiven ve maskeyle uygular.","sektor":"Güçlü kimyasal olduklarından eldiven, maske ve havadar ortamla kullanılır. Ders kitabı bu ürünleri asitli gereçler olarak tanıtır; piyasada alkali olanlar da bulunduğundan ürünün etiketi mutlaka okunur.","iliskili":["kh1-1-203","kh1-1-215"],"kontrol":null},{"id":"kh1-1-203","konu":"1.3.11","terim":"Kireç ve pas çözücüler","ingilizce":"Descalers and rust removers","tanim":"Musluk, lavabo, küvet ve gider gibi sürekli su ile temas eden yüzeylerde oluşan kireci çözen, asit oranı yüksek maddelerdir.","ornek":"Duş armatürü mat görününce Murat, kireç çözücüyü ürün talimatına uygun uygulayıp durular.","sektor":"Sürekli suyla temas eden armatürler zamanla kireçlenir; kireç çözücü yüzeyi eski görünümüne kavuşturur.","iliskili":["kh1-1-200","kh1-1-215"],"kontrol":null,"gorsel":"t11a-klozet-jeli"},{"id":"kh1-1-204","konu":"1.3.11","terim":"Leke çözücüler","ingilizce":"Stain removers","tanim":"Yüzeye ve lekeye göre ayrı çeşitleri bulunan, sprey ya da sıvı hâlde kullanılan temizlik maddeleridir.","ornek":"Halıdaki kahve lekesini temizlemek için Esra, ürünün halı için uygun olduğunu kontrol eder.","sektor":"Her yüzey ve leke için ayrı leke çözücü vardır; yanlış ürün lekeyi kalıcı hâle getirebilir.","iliskili":["kh1-1-206","kh1-1-198"],"kontrol":null},{"id":"kh1-1-205","konu":"1.3.11","terim":"Cilaların kullanım alanı","ingilizce":"Where floor polishes are used","tanim":"Mermer, mozaik, ahşap, parke ve marley gibi yüzeyleri parlatan, çizilmeye karşı koruyan maddelerdir.","ornek":"Sezon sonunda salonu 22.00’de kapatan bakım ekibi, görünümünü ve çizilmeye karşı direncini korumak için parke zemini cilayla işler.","sektor":"Cila zemini hijyenik ve kolay temizlenebilir kılar, görünümünü güzelleştirir.","iliskili":["kh1-1-162","kh1-1-206"],"kontrol":null},{"id":"kh1-1-206","konu":"1.3.11","terim":"Özel temizlik maddeleri","ingilizce":"Specialist cleaners","tanim":"Metal, mobilya ve deri gibi yüzeylerin temizliğinde kullanılan özel gereçlerdir.","ornek":"Resepsiyondaki deri koltuğu silen Okan, yalnızca deri için üretilmiş temizleyici kullanır.","sektor":"Her yüzey kendi temizleyicisini ister; genel ürünle silinen deri ya da metal zarar görebilir.","iliskili":["kh1-1-201","kh1-1-204"],"kontrol":null},{"id":"kh1-1-207","konu":"1.3.11","terim":"Kullanma talimatına uyma","ingilizce":"Following usage instructions","tanim":"Temizlik maddesini kullanmadan önce talimatın okunması ve talimata uyulmasıdır.","ornek":"Yeni bir dezenfektan gelince Gülşen, kullanmadan önce etiketteki oranı, kullanım yerini ve güvenlik önlemlerini okur.","sektor":"Talimat oranı, kullanım yerini ve güvenlik önlemlerini gösterir; okunmadan kullanılan ürün hem yüzeye hem kişiye zarar verebilir.","iliskili":["kh1-1-208","kh1-1-211"],"kontrol":null},{"id":"kh1-1-208","konu":"1.3.11","terim":"Maddeyi üretildiği yüzeyde kullanma","ingilizce":"Using a cleaner only on its intended surface","tanim":"Temizlik maddelerinin yalnızca üretildikleri yüzey için kullanılmasıdır.","ornek":"Sabah 10.00’da mermer tezgâhı kendi cam temizleyicisiyle silmeye başlayan yeni görevliyi gören kat şefi Pınar, ürünün mermer için üretilmediğini söyleyip doğru ürünü verir.","sektor":"Her yüzey için üretilmiş ürün o yüzeye zarar vermeyecek şekilde tasarlanmıştır.","iliskili":["kh1-1-207","kh1-1-196"],"kontrol":null},{"id":"kh1-1-209","konu":"1.3.11","terim":"Yağ çözücülerde eldiven","ingilizce":"Gloves with degreasers","tanim":"Yağ çözücülerin çıplak elle kullanılmayıp mutlaka eldiven takılarak uygulanmasıdır.","ornek":"Mutfağa yakın koridorda 12.30’da yağ lekesini silen Şükrü, yağ çözücüyü eldivenle uygular; ellerinin kurumasını ve çatlamasını böyle önler.","sektor":"Yağ çözücüler ciltteki yağlı maddeleri uzaklaştırarak cildi kurutur; bazı ürünlerde ayrıca maske de takılır.","iliskili":["kh1-1-219","kh1-1-207"],"kontrol":null,"gorsel":"t10a-eldiven-sprey"},{"id":"kh1-1-210","konu":"1.3.11","terim":"Temizlik maddelerini karıştırmama","ingilizce":"Never mixing cleaning agents","tanim":"Farklı temizlik maddelerinin asla birbirine karıştırılmamasıdır.","ornek":"Banyoda iki ürünü aynı kovaya dökmek isteyen stajyer Efe’yi kat görevlisi Nilay durdurur.","sektor":"Ürünler birbiriyle tepkimeye girdiğinde göze, ciğere ve solunum sistemine zarar verir; örneğin çamaşır suyu tuz ruhuyla karışınca zehirli gaz oluşur.","iliskili":["kh1-1-211","kh1-1-215"],"kontrol":null},{"id":"kh1-1-211","konu":"1.3.11","terim":"Sıvı maddeyi oranına göre seyreltme","ingilizce":"Diluting to the stated ratio","tanim":"Kullanma talimatındaki oranda sıvı temizlik maddesinin suyla karıştırılmasıdır.","ornek":"Kovaya talimattaki kadar madde ekleyen Gökçe, “biraz fazla olsun” diyerek ölçüyü artırmaz; yüzey çok köpürmez, durulama süresi de uzamaz.","sektor":"Gereğinden fazla kullanılan ürün yüzeye zarar verir, daha çok durulama gerektirir ve ekonomik zarar yaratır.","iliskili":["kh1-1-207","kh1-1-210"],"kontrol":null},{"id":"kh1-1-212","konu":"1.3.11","terim":"Sıvı ve sprey ürünleri çalkalama","ingilizce":"Shaking liquid and spray products","tanim":"Kullanmadan önce içindeki maddelerin iyice karışması için sıvı ve sprey ürünlerin çalkalanmasıdır.","ornek":"Sabah 09.10’da Deniz, cam temizleyici şişesini kullanmadan önce birkaç kez çalkalar; içindeki maddelerin dengeli karışmasını sağlar.","sektor":"Çalkalama içindeki maddelerin dengeli karışmasını sağlar; ürün etkisini tam gösterir.","iliskili":["kh1-1-211","kh1-1-213"],"kontrol":null},{"id":"kh1-1-213","konu":"1.3.11","terim":"Kullanımdan sonra kapağı kapatma","ingilizce":"Closing containers after use","tanim":"Temizlik maddelerinin kullanımdan hemen sonra kapaklarının kapatılmasıdır.","ornek":"Banyo temizliğini bitiren Tuna, arabadaki bütün şişelerin kapaklarını hemen kapatır; araba koridorda sallanırken ürün dökülmez.","sektor":"Açık kalan ürün dökülebilir, buharlaşabilir ve çevreye zarar verebilir.","iliskili":["kh1-1-212","kh1-1-214"],"kontrol":null},{"id":"kh1-1-214","konu":"1.3.11","terim":"Kendi ambalajında saklama ve etiketleme","ingilizce":"Keeping products in original packaging and labelling","tanim":"Temizlik maddelerinin kendi ambalajında saklanması, başka bir kaba konulacaksa üzerine ne olduğunun etiketle yazılmasıdır.","ornek":"Küçük kaba ürün aktaran Nermin, 10.40’ta kabın üzerine ürünün adını etiketle yazar; sonraki vardiyanın görevlisi içeriği karıştırmaz.","sektor":"Etiketsiz kap yanlış ürünün kullanılmasına yol açabilir; bu da iş kazasına neden olur.","iliskili":["kh1-1-213","kh1-1-218"],"kontrol":null},{"id":"kh1-1-215","konu":"1.3.11","terim":"Asitli maddelerle çalışırken önlem","ingilizce":"Precautions with acidic products","tanim":"Asit içeren temizlik maddelerinin havadar bir yerde, maske ve eldivenle kullanılmasıdır.","ornek":"Kireç çözücüyle çalışan Kerem, banyo penceresini açar, maske ve eldiven takar.","sektor":"Asitli ürünlerin buharı solunum yollarını tahriş edebilir.","iliskili":["kh1-1-203","kh1-1-210"],"kontrol":null,"gorsel":"t12a-eldivenli-el"},{"id":"kh1-1-216","konu":"1.3.11","terim":"Tene veya göze sıçrayan madde","ingilizce":"Product splashes on skin or in eyes","tanim":"Temizlik maddesi tene ya da göze sıçradığında o bölgenin bol suyla yıkanmasıdır.","ornek":"Gözüne ürün sıçrayan Esin, hemen göz yıkama musluğuna gidip bol suyla yıkar ve amirine haber verir.","sektor":"Önce ilk müdahale yapılır, ardından amire haber verilir; gerekirse sağlık yardımı alınır.","iliskili":["kh1-1-215","kh1-1-207"],"kontrol":null,"gorsel":"t12a-goz-yikama"},{"id":"kh1-1-217","konu":"1.3.11","terim":"Maddeyi yüzeye doğrudan dökmeme","ingilizce":"Not pouring cleaners directly onto surfaces","tanim":"Temizlik maddelerinin temizlenecek yüzeye doğrudan dökülmeyip bezle ya da uygun araçla uygulanmasıdır.","ornek":"Mobilya temizliğinde Aysun, spreyi doğrudan ahşap yüzeye sıkmaz, önce bezin üzerine sıkar; yüzeyde leke ve damla izi kalmaz.","sektor":"Doğrudan dökülen madde yüzeyde leke ve hasar bırakabilir.","iliskili":["kh1-1-208","kh1-1-211"],"kontrol":null},{"id":"kh1-1-218","konu":"1.3.11","terim":"Temizlik maddelerinin depolanması","ingilizce":"Storing cleaning products","tanim":"Maddelerin kapağı kapalı, gıdadan uzak ve kendi ambalajında saklanması; toz kimyasalların nemsiz ortamda tutulması ve deponun sık havalandırılmasıdır.","ornek":"Depo sorumlusu Hakan, toz ürünleri nemden uzak rafa koyar ve depoyu her sabah havalandırır.","sektor":"Doğru depolama kazayı, bozulmayı ve gıdaya bulaşmayı önler.","iliskili":["kh1-1-214","kh1-1-213"],"kontrol":null,"gorsel":"h3b-kimyasal-deposu"},{"id":"kh1-1-219","konu":"1.3.12","terim":"Eldiven, bone ve maske","ingilizce":"Gloves, cap and mask","tanim":"Temizlik sırasında kimyasallardan etkilenmemek için elin, yüzün ve saçın korunmasında kullanılan malzemelerdir.","ornek":"Sabah 10.15’te banyoda kireç çözücü kullanmadan önce Duygu eldiven, bone ve maske takar; sıçrama olursa eli, yüzü ve saçı korunur.","sektor":"Koruyucu malzeme kullanmak iş sağlığı ve güvenliği için temel bir adımdır.","iliskili":["kh1-1-209","kh1-1-215"],"kontrol":null,"gorsel":"t10a-mavi-eldiven"},{"id":"kh1-1-220","konu":"1.3.13","terim":"Merdiven","ingilizce":"Ladder","tanim":"Kat görevlilerinin yüksek yerlere daha rahat uzanabilmesi için kullandığı araçtır.","ornek":"Sabah 09.00’da perde raylarını silecek Mehmet, sağlam bir merdiveni düz zemine kurar ve çıkarken bir arkadaşından merdiveni tutmasını ister.","sektor":"Yüksekte çalışırken merdiven ve tabure düşmeyi önleyen güvenlik ekipmanıdır.","iliskili":["kh1-1-221","kh1-1-219"],"kontrol":null,"gorsel":"t15ab-merdiven-aluminyum"},{"id":"kh1-1-221","konu":"1.3.13","terim":"Tabure","ingilizce":"Step stool","tanim":"Temizliği daha rahat yapabilmek için kat görevlilerinin kullandığı alçak basamaklı araçtır.","ornek":"Dolap üstündeki tozu alacak Selin, tabureyi düz ve sağlam zemine koyup basamağın ortasına basar; sandalyeye çıkmaz.","sektor":"Tabure düşük yükseklikler için uygundur; yüksek yerlerde merdiven kullanılır.","iliskili":["kh1-1-220","kh1-1-219"],"kontrol":null,"gorsel":"t10a-tabure"},{"id":"kh1-1-222","konu":"1.4","terim":"Kat hizmetlerinde form ve rapor","ingilizce":"Housekeeping forms and reports","tanim":"Kat hizmetleri çalışanları ve yöneticilerince işlerin sağlıklı yürümesi için belirli aralıklarla düzenlenen kayıt belgeleridir.","ornek":"Her sabah 08.00’de kat ofisinde kat şefi Nesrin, o günün form ve raporlarını masaya dizer.","sektor":"Yazılı kayıt, kimin ne zaman ne yaptığını gösterir; bölümler arası bilgi akışını ve hesap verebilirliği sağlar.","iliskili":["kh1-1-223","kh1-1-245","kh1-1-256"],"kontrol":null},{"id":"kh1-1-223","konu":"1.4.1","terim":"Housekeeping raporu","ingilizce":"Housekeeping report","tanim":"Konuk odalarının o günkü durumunun housekeeper tarafından kaydedildiği rapordur.","ornek":"Sabah 09.30’da housekeeper Aslı, ön büro listesi ile kat görevlilerinden gelen bilgileri karşılaştırıp günün ilk housekeeping raporunu hazırlar.","sektor":"Rapor, ön bürodaki oda durumu ile kat hizmetlerindeki gerçek durumun uyuşmasını sağlar; ön büro hangi odayı satabileceğini bu bilgiye dayanarak bilir.","iliskili":["kh1-1-224","kh1-1-225","kh1-1-229"],"kontrol":null},{"id":"kh1-1-224","konu":"1.4.1","terim":"Housekeeper","ingilizce":"Executive housekeeper","tanim":"Kat görevlilerine odaları dağıtan, raporları karşılaştıran ve housekeeping raporunu hazırlayan kat hizmetleri yöneticisidir.","ornek":"Sabah 09.00’da housekeeper Aslı, kat şeflerinden gelen kontrol formlarını masasında toplar ve ön büro bilgileriyle karşılaştırır.","sektor":"Housekeeper, ön büro ile kat hizmetleri arasındaki bilgi akışının merkezindedir. Ders materyali housekeeper sözcüğünü parantezde “kat görevlisi” diye çevirir; ancak raporları dağıtan, karşılaştıran ve hazırlayan kişi kat hizmetleri yöneticisidir.","iliskili":["kh1-1-223","kh1-1-226"],"kontrol":null},{"id":"kh1-1-225","konu":"1.4.1","terim":"Housekeeping raporunun düzenlenme zamanı","ingilizce":"Timing of the housekeeping report","tanim":"Raporun gün içinde sabah ve öğleden sonra olmak üzere iki ayrı zamanda düzenlenmesidir.","ornek":"Oteldeki housekeeper, birinci raporu 09.00’da, ikinci raporu öğleden sonra odaların işlemleri bittiğinde hazırlar.","sektor":"Sabah raporu günün başlangıç durumunu, öğleden sonra hazırlanan rapor işlemler bittikten sonraki son durumu gösterir.","iliskili":["kh1-1-226","kh1-1-227"],"kontrol":null},{"id":"kh1-1-226","konu":"1.4.1","terim":"Günün ilk housekeeping raporu","ingilizce":"First housekeeping report of the day","tanim":"Housekeeper’ın ön bürodan gelen bilgileri kat görevlilerinin geri bildirimleriyle karşılaştırarak günün başında hazırladığı rapordur.","ornek":"Aslı, ön bürodan gelen oda listesini kat görevlilerinin kontrolüyle karşılaştırıp 10.00’da ilk raporu bitirir.","sektor":"Karşılaştırma sırasında fark çıkarsa uyuşmazlık raporu düzenlenir.","iliskili":["kh1-1-227","kh1-1-249"],"kontrol":null},{"id":"kh1-1-227","konu":"1.4.1","terim":"Günün ikinci housekeeping raporu","ingilizce":"Second housekeeping report of the day","tanim":"Kat görevlilerinin gün sonu raporlarının kat şefleri aracılığıyla alınıp oda durumu ve kişi sayısı kontrol edildikten sonra housekeeper’ın hazırladığı rapordur.","ornek":"Öğleden sonra 16.00’da tüm odaların işlemleri bitince Aslı ikinci raporunu hazırlar ve bir örneğini ön büroya gönderir.","sektor":"İkinci rapor, günün son oda durumunu ön büroya taşır; satış ekibi buna göre çalışır.","iliskili":["kh1-1-226","kh1-1-228"],"kontrol":null},{"id":"kh1-1-228","konu":"1.4.1","terim":"Housekeeping raporunun nüshaları","ingilizce":"Copies of the housekeeping report","tanim":"Raporun ön büroya, muhasebeye ve kat şefinin dosyasına gitmek üzere çoğaltılmasıdır.","ornek":"Rapor çıktısını alan Aslı, nüshaları ön büroya, muhasebeye ve kat şefi dosyasına dağıtır.","sektor":"Ders materyaline göre rapor üç nüsha düzenlenir: birinci nüsha ön büroya, ikinci nüsha muhasebeye, üçüncü nüsha kat şefinin dosyasına konur.","iliskili":["kh1-1-227","kh1-1-229"],"kontrol":null},{"id":"kh1-1-229","konu":"1.4.1","terim":"Housekeeping raporunun içeriği","ingilizce":"Contents of the housekeeping report","tanim":"Satılan oda sayısı ve numaraları ile her odanın boş, dolu, arızalı, bagajlı, bagajsız, meşgul ya da o gece yatılmamış olma durumunun raporda gösterilmesidir.","ornek":"Aslı, 304 numaralı odanın OOO olduğunu raporda arıza notuyla belirtir; konuğunun geceyi dışarıda geçirdiği 410 numaralı odayı S/O ile gösterir, satılan oda sayısını ve numaralarını da aynı rapora yazar.","sektor":"Raporda eksik ya da yanlış bilgi olursa ön büro odayı yanlış satabilir; bu yüzden bilgiler eksiksiz yazılır. Raporun altında oda sayısı, ön büro durumu, kat hizmetleri durumu ve son durum ile raporu hazırlayan ve kontrol eden kişi için alanlar bulunur.","iliskili":["kh1-1-223","kh1-1-228","kh1-1-243"],"kontrol":null},{"id":"kh1-1-230","konu":"1.4.1","terim":"Ön büronun günlük oda durum raporu","ingilizce":"Front office room status report","tanim":"Ön büronun her gün hazırlayıp kat hizmetlerine ilettiği, dolu odaların listesini ve erken ya da geç ayrılan konuk değişikliklerini içeren rapordur.","ornek":"Sabah 07.30’da ön büro görevlisi Cansu, dolu odaların listesini ve geç çıkış yapacak konukları kat hizmetlerine iletir.","sektor":"Bilgi manuel olarak ya da iki bölümün ortak kullandığı otomasyon programı aracılığıyla sabah erken saatlerde verilir.","iliskili":["kh1-1-223","kh1-1-226"],"kontrol":null},{"id":"kh1-1-231","konu":"1.4.1","terim":"Oda listesinin kat görevlilerine dağıtılması","ingilizce":"Distributing room lists to room attendants","tanim":"Housekeeper’ın ön bürodan gelen bilgilere göre odaları kat görevlilerine dağıtmasıdır.","ornek":"Sabah 08.30’da Aslı, ön büro raporuna göre her kat görevlisine temizleyeceği odaların listesini verir.","sektor":"Kat görevlileri listedeki odaların temizliğini ve sorumlu olduğu kattaki odaların denetimini yapar, sonucu housekeeper’a bildirir.","iliskili":["kh1-1-230","kh1-1-226"],"kontrol":null},{"id":"kh1-1-232","konu":"1.4.1","terim":"Gün sonu oda durumu işaretleme","ingilizce":"End-of-day room status marking","tanim":"Kat görevlisinin temizlik ve kontrol bitince sorumlu olduğu odaların durumunu rapordaki sembollerle işaretlemesidir.","ornek":"Öğleden sonra 16.30’da kat görevlisi Hande, bitirdiği odaların durumunu rapordaki sembollerle işaretler.","sektor":"Kat şefleri bu raporları housekeeper’a iletir; housekeeper oda durumunu ve oda kişi sayısını raporlara göre kontrol eder.","iliskili":["kh1-1-245","kh1-1-227"],"kontrol":null},{"id":"kh1-1-233","konu":"1.4.1","terim":"Raporların otomasyonda hazırlanması","ingilizce":"Producing reports in the hotel system","tanim":"Housekeeping raporlarının otel otomasyon programına veri girilerek çıktı alınmasıyla hazırlanmasıdır.","ornek":"Sabah 10.00’da İzmir’deki bir otelin kat ofisinde housekeeper Aslı, oda durumlarını otomasyon programına girer ve raporun çıktısını alır.","sektor":"Ön büro ve kat hizmetleri aynı programı kullandığında oda bilgisi iki bölümde de aynı anda güncellenir.","iliskili":["kh1-1-223","kh1-1-228"],"kontrol":null},{"id":"kh1-1-234","konu":"1.4.1","terim":"Raporda boş temiz oda (V/C)","ingilizce":"Vacant clean (V/C)","tanim":"Housekeeping raporunun anahtarında konuğun bulunmadığı, temizliği yapılmış odayı gösteren kısaltmadır.","ornek":"Sabah 10.20’de kat görevlisi Hande, boş ve temizlenmiş 215 numaralı odayı raporda V/C ile işaretler; kat şefi kontrol edene kadar satışa hazır saymaz.","sektor":"V/C boş ve temizlenmiş oda demektir. Ders materyalinin ikinci ünitesi bu odanın henüz satışa hazır hâle gelmemiş olabileceğini de söyler; kat şefi kontrol edip satışa hazır sayınca oda konuğa verilebilir. OOO odası ise arıza giderilene kadar hiçbir hâlde verilemez.","iliskili":["kh1-1-235","kh1-1-241"],"kontrol":null,"gorsel":"t12a-hazir-oda"},{"id":"kh1-1-235","konu":"1.4.1","terim":"Raporda boş kirli oda (V/D)","ingilizce":"Vacant dirty (V/D)","tanim":"Housekeeping raporunun anahtarında konuğun bulunmadığı, ancak temizlenmeyi bekleyen odayı gösteren kısaltmadır.","ornek":"Çıkış sonrası 218 numaralı odayı V/D olarak gören kat görevlisi Hande, akşam gelecek konuk için odayı listenin başına alır.","sektor":"V/D odaların temizliği, yeni gelecek konuğa oda hazırlamanın ilk basamağıdır.","iliskili":["kh1-1-234","kh1-1-236"],"kontrol":null},{"id":"kh1-1-236","konu":"1.4.1","terim":"Raporda çıkış yapılan oda (C/O)","ingilizce":"Check-out room (C/O)","tanim":"Housekeeping raporunun anahtarında konuğun o gün çıkış yaptığı odayı gösteren kısaltmadır.","ornek":"Sabah 11.00’de çıkış yapan konuğun odası raporda C/O olarak işaretlenir; öğleden sonra gelecek konuk için oda öncelikle temizlenir.","sektor":"C/O odalar yeni konuk için hazırlanacağından genellikle önceliklidir. Temizlenmeden C/I konuğa verilemez; kısaltmaları karıştırmak oda hazırlığında gecikme yaratır.","iliskili":["kh1-1-235","kh1-1-237"],"kontrol":null},{"id":"kh1-1-237","konu":"1.4.1","terim":"Raporda giriş yapılan oda (C/I)","ingilizce":"Check-in room (C/I)","tanim":"Housekeeping raporunun anahtarında o gün konuk girişi olan odayı gösteren kısaltmadır.","ornek":"Öğleden sonra gelecek bir aile için hazırlanan 412 numaralı oda raporda C/I ile belirtilir.","sektor":"C/I odalar konuk gelmeden önce hazır olmalıdır.","iliskili":["kh1-1-236","kh1-1-234"],"kontrol":null},{"id":"kh1-1-238","konu":"1.4.1","terim":"Raporda personel kullanımı (H/U)","ingilizce":"House use (H/U)","tanim":"Housekeeping raporunun anahtarında odanın konuk yerine otel personeli tarafından kullanıldığını gösteren kısaltmadır.","ornek":"Akşam toplantısı için idari personele ayrılan 102 numaralı oda H/U olarak işaretlenir.","sektor":"H/U odalar konuğa satılmaz; bu yüzden raporda ayrıca gösterilir. H/U’lu odada konuk değil personel bulunur.","iliskili":["kh1-1-242","kh1-1-243"],"kontrol":null},{"id":"kh1-1-239","konu":"1.4.1","terim":"Raporda oda değişimi (R/C)","ingilizce":"Room change (R/C)","tanim":"Housekeeping raporunun anahtarında konuğun odasının değiştirildiğini gösteren kısaltmadır.","ornek":"Konuğun isteğiyle 307’den 309’a geçmesi üzerine eski oda raporda R/C ile işaretlenir; Selin iki odayı da hazırlar.","sektor":"Oda değişimi, ön büro ve kat hizmetlerinin aynı odayı aynı şekilde kaydetmesini gerektirir. Oda değişikliğinde hem eski hem yeni oda ayrı ayrı hazırlanır.","iliskili":["kh1-1-238","kh1-1-236"],"kontrol":null},{"id":"kh1-1-240","konu":"1.4.1","terim":"Raporda dolu oda (OCC)","ingilizce":"Occupied (OCC)","tanim":"Housekeeping raporunun anahtarında konuğun kaldığı, yani dolu odayı gösteren kısaltmadır.","ornek":"Sabah 09.00’da konuğun içeride kaldığı 305 numaralı oda raporda OCC olarak görünür; temizlik bitip oda kontrol edilince işaret OK’ye çevrilir.","sektor":"OCC, occupied (dolu) demektir. Ders materyali birinci ünitenin rapor anahtarında “dolu temiz”, kutusunda ve ikinci ünitede “dolu oda” diye verir; temizlik durumu ayrıca (örneğin OK ile) bildirilir.","iliskili":["kh1-1-234","kh1-1-243"],"kontrol":null},{"id":"kh1-1-241","konu":"1.4.1","terim":"Raporda temiz oda (OK)","ingilizce":"Okay (OK)","tanim":"Housekeeping raporunun anahtarında odanın temizliğinin tamamlandığını gösteren işarettir.","ornek":"Kat şefi Hülya, temizliği biten 210 numaralı odayı kontrol ettikten sonra raporda OK olarak işaretler.","sektor":"Ders materyali OK’yi birinci ünitede “temizlenmiş, satışa hazır oda”, ikinci ünitede “temizlenmiş dolu oda” diye verir; ikinci ünitenin örnek raporunda işaret hem çıkış yapılıp temizlenen odanın hem günlük temizliği biten dolu odanın yanında yazılır. Kısaca OK “temizlik tamamlandı, oda sorunsuz” der; boş odada satışa hazır, dolu odada hizmeti bitmiş oda anlamı taşır.","iliskili":["kh1-1-234","kh1-1-240"],"kontrol":null},{"id":"kh1-1-242","konu":"1.4.1","terim":"Raporda arızalı oda (OOO)","ingilizce":"Out of order (OOO)","tanim":"Housekeeping raporunun anahtarında arıza nedeniyle satışa kapatılmış odayı gösteren kısaltmadır.","ornek":"Banyo gideri tıkanan 308 numaralı oda sorun giderilene kadar raporda OOO olarak kalır.","sektor":"OOO oda satılmaz; arıza giderilip kontrol edilene kadar satış dışıdır. V/C ile karıştırılırsa yanlış oda satılır.","iliskili":["kh1-1-238","kh1-1-235"],"kontrol":null},{"id":"kh1-1-243","konu":"1.4.1","terim":"Raporda dolu kullanılmamış oda (S/O)","ingilizce":"Sleep-out (S/O)","tanim":"Housekeeping raporunun anahtarında konuk adına dolu görünen ancak kullanılmamış odayı gösteren kısaltmadır.","ornek":"Gece odasına dönmeyen konuğun yatağı sabah düzenli bulununca kat görevlisi odayı S/O olarak işaretler.","sektor":"S/O bilgisi ön büroya iletilir; çünkü konuk kayıtlıdır ama o gece odayı kullanmamıştır. Konuk kayıtlı olduğu için oda o gece için dolu sayılır ve eşyaları odada durur.","iliskili":["kh1-1-240","kh1-1-244"],"kontrol":null},{"id":"kh1-1-244","konu":"1.4.1","terim":"Raporda dolu bagajsız oda (W/L)","ingilizce":"Without luggage (W/L)","tanim":"Housekeeping raporunun anahtarında konuğun bagajı bulunmayan dolu odayı gösteren kısaltmadır.","ornek":"Konuğun hiçbir eşyası görünmeyen 320 numaralı oda raporda W/L olarak işaretlenir.","sektor":"W/L, “without luggage” (bagajsız) demektir. Kat görevlisi odadaki bagaj durumunu W/L ile işaretleyerek ön büroya bilgi verir.","iliskili":["kh1-1-243","kh1-1-240"],"kontrol":null},{"id":"kh1-1-245","konu":"1.4.2","terim":"Kat görevlisi raporu","ingilizce":"Room attendant’s report","tanim":"Konuk odalarında kat görevlisi tarafından yapılan işlemlerin ve son kontrollerin gösterildiği rapordur.","ornek":"Hande, 16.30’da gün sonunda temizlediği altı odanın son durumunu kat görevlisi raporuna işler ve imza karşılığı teslim eder.","sektor":"Maid raporu adıyla da bilinir; güncel sektör dilinde room attendant tercih edilir.","iliskili":["kh1-1-246","kh1-1-232","kh1-1-247"],"kontrol":null},{"id":"kh1-1-246","konu":"1.4.2","terim":"Kat görevlisi raporunun teslim alınması ve verilmesi","ingilizce":"Collecting and returning the attendant’s report","tanim":"Kat görevlisinin raporu sabah odalara gitmeden önce imza karşılığı alıp gün bitiminde yaptığı işlemleri yazarak yine imza karşılığı teslim etmesidir.","ornek":"Hande sabah 08.45’te raporu imza karşılığı alır, öğleden sonra 16.45’te doldurup teslim eder.","sektor":"İmza, raporun kimde olduğunu ve kimin sorumlu olduğunu gösterir.","iliskili":["kh1-1-245","kh1-1-227"],"kontrol":null},{"id":"kh1-1-247","konu":"1.4.2","terim":"Raporda ek yatak ve bebek yatağı kaydı","ingilizce":"Extra bed and baby cot entries","tanim":"Kat görevlisi raporunda odaya konulan ek yatak ya da bebek yatağının ayrıca belirtilmesidir.","ornek":"Çocuklu aile için 414 numaralı odaya bebek yatağı konunca Hande bunu kat görevlisi raporunda belirtir.","sektor":"Bu bilgi raporu inceleyen yöneticilerin odadaki ek yatağı ve bebek yatağını takip etmesini sağlar.","iliskili":["kh1-1-245","kh1-1-246"],"kontrol":null},{"id":"kh1-1-248","konu":"1.4.2","terim":"Kat görevlisi raporlarından housekeeper raporuna","ingilizce":"From attendant reports to the housekeeping report","tanim":"Housekeeper’ın gün bitiminde kat görevlilerinin raporlarına dayanarak kendi raporunu hazırlayıp ilgili bölüme iletmesidir.","ornek":"Akşam 17.00’de housekeeper Aslı, kat görevlilerinin raporlarına bakarak housekeeping raporunu bitirir ve ilgili bölüme gönderir.","sektor":"Böylece kat görevlisinin sahadaki bilgisi ön büro ve muhasebeye aktarılır.","iliskili":["kh1-1-245","kh1-1-227"],"kontrol":null},{"id":"kh1-1-249","konu":"1.4.3","terim":"Uyuşmazlık raporu","ingilizce":"Discrepancy report","tanim":"Ön büro ile housekeeper raporları arasında oda durumu farkı bulunduğunda, farklı olan oda numaralarını belirten rapordur.","ornek":"Sabah 09.50’de ön büro 1103’ü V/C, kat görevlisi OCC yazınca Aslı farkı uyuşmazlık raporuna işler ve nedenini araştırmak üzere kat şefinden bilgi ister.","sektor":"Uyuşmazlık raporu, aynı odanın iki bölümde farklı görünmesini önler.","iliskili":["kh1-1-250","kh1-1-255"],"kontrol":null},{"id":"kh1-1-250","konu":"1.4.3","terim":"Uyuşmazlığın nedenlerini araştırma","ingilizce":"Investigating discrepancies","tanim":"Raporlar arasındaki farkın nereden kaynaklandığının incelenip sebebinin bulunmasıdır.","ornek":"Sabah 10.30’da 1214 numaralı oda iki raporda farklı görününce kat şefi Hülya, ön büroyu arar ve fark nedenini birlikte araştırır.","sektor":"Neden bulunmadan düzeltme yapılırsa aynı hata tekrar edebilir.","iliskili":["kh1-1-249","kh1-1-251"],"kontrol":null},{"id":"kh1-1-251","konu":"1.4.3","terim":"Eksik ya da yanlış işaretleme","ingilizce":"Missing or incorrect marking","tanim":"Ön büronun ya da kat hizmetlerinin oda durumunu eksik ya da yanlış işaretlemesidir.","ornek":"Akşam 18.00’de kat görevlisi Hande, boş ama kirli olan 215 numaralı odayı yanlışlıkla V/C diye işaretler; ön büro odayı temiz sanır.","sektor":"Raporlar arasındaki uyuşmazlığın başlıca nedenlerinden biridir; işaretleme yapılırken oda kapısında kontrol edilir.","iliskili":["kh1-1-249","kh1-1-252"],"kontrol":null},{"id":"kh1-1-252","konu":"1.4.3","terim":"Oda satışının raporda gösterilmemesi","ingilizce":"Unrecorded room sale","tanim":"Yapılan oda satışının rapora işlenmemesidir.","ornek":"Akşam 20.00’de resepsiyon görevlisi Cansu, son dakikada satılan 612 numaralı odayı rapora işlemeyi unutur; kat hizmetleri odayı boş görür.","sektor":"Satış rapora geçmediğinde ön büro ile kat hizmetleri aynı odayı farklı durumda görür ve uyuşmazlık doğar.","iliskili":["kh1-1-251","kh1-1-253"],"kontrol":null},{"id":"kh1-1-253","konu":"1.4.3","terim":"Oda durumu değişikliğinin yansımaması","ingilizce":"Status change not reflected","tanim":"Odanın durumundaki bir değişikliğin raporlara işlenmemesidir.","ornek":"Gece 22.00’de konuğun odası 307’den 309’a alınır ama değişiklik kat hizmetleri raporuna yansımaz; sabah iki oda da dolu görünür.","sektor":"Oda değişikliği, ön büro ve kat hizmetlerinin raporlarına birlikte işlenmelidir; işlenmezse iki rapor farklı çıkar.","iliskili":["kh1-1-252","kh1-1-249"],"kontrol":null},{"id":"kh1-1-254","konu":"1.4.3","terim":"Odaların son durumunun bildirilmesi","ingilizce":"Reporting final room status","tanim":"Kat hizmetlerinin odaları yeniden kontrol ettikten sonra son durumu ön büroya bildirmesidir.","ornek":"Sabah 11.30’da kat şefi Hülya, uyuşmazlık çıkan odaları yeniden kontrol eder ve gördüğü son durumu ön büroya telefonla bildirir.","sektor":"Son durum bildirildikten sonra raporlar değerlendirilir ve ön büronun kayıtları kat hizmetlerinin gerçek durumuna göre düzeltilir.","iliskili":["kh1-1-250","kh1-1-249"],"kontrol":null},{"id":"kh1-1-255","konu":"1.4.3","terim":"Uyuşmazlık raporunun alanları","ingilizce":"Fields of the discrepancy report","tanim":"Raporda katın, oda numarasının ve tipinin, kişi sayısının, ön büronun ve housekeeping’in oda durumunun ve kontrol sonucunun yer almasıdır.","ornek":"Housekeeper Aslı, 1214 numaralı oda için uyuşmazlık raporuna ön büro durumunu OCC, housekeeping durumunu V/C diye yan yana yazar.","sektor":"Her iki bölümün oda durumunun yan yana görünmesi farkı bulmayı kolaylaştırır.","iliskili":["kh1-1-249","kh1-1-254"],"kontrol":null},{"id":"kh1-1-302","konu":"1.4.1","terim":"Housekeeping raporu hazırlama uygulaması","ingilizce":"Housekeeping report exercise","tanim":"Ön büro oda durum raporundan başlayarak housekeeping raporunun hazırlanmasını, ön büro raporuyla karşılaştırılmasını ve gerekirse uyuşmazlık raporu düzenlenmesini öğreten atölye uygulamasıdır.","ornek":"Atölye dersinde iki kişilik grupta Deniz ve Eylül, öğretmenin verdiği ön büro raporunu alır; kat şefi rolündeki arkadaşlarına odaları kontrol ettirir, ikinci raporu bitirip örnekleri dağıtır.","sektor":"Ders materyaline göre uygulama 30 dakika sürer ve iki kişilik gruplarla yapılır. Adımlar: raporu alma, kontrol ettirip kat raporunu hazırlama, housekeeping raporunu hazırlama, ön büroyla karşılaştırma ve gerekirse uyuşmazlık raporu, örnekleri ön büroya ve muhasebeye gönderme ve öğleden sonra ikinci raporu hazırlama.","iliskili":["kh1-1-223","kh1-1-226","kh1-1-249"],"kontrol":null},{"id":"kh1-1-256","konu":"1.4.4","terim":"Arıza bilgi formu","ingilizce":"Defect information form","tanim":"Kat görevlilerinin temizlik ve kontrol sırasında tespit ettiği arızaların yazıldığı bilgi formudur.","ornek":"Sabah 11.00’de 108 numaralı odada televizyonun açılmadığını gören kat görevlisi Hande, bunu arıza bilgi formuna yazar.","sektor":"Formda misafir odalarında ve ortak alanlarda tespit edilen arızalarla ilgili ayrıntılı bilgi yer alır.","iliskili":["kh1-1-257","kh1-1-258"],"kontrol":null},{"id":"kh1-1-257","konu":"1.4.4","terim":"Arıza raporu","ingilizce":"Defect report","tanim":"Kat şeflerinin topladığı arıza bilgi formlarına dayanarak housekeeper’ın düzenlediği ve teknik servise ilettiği rapordur.","ornek":"Öğleden sonra 14.00’te housekeeper Aslı, kat şeflerinden gelen formları birleştirip arıza raporunu hazırlar ve teknik servise gönderir.","sektor":"Ders materyaline göre arıza raporu üç nüsha olarak düzenlenir.","iliskili":["kh1-1-256","kh1-1-258"],"kontrol":null},{"id":"kh1-1-258","konu":"1.4.4","terim":"Arızanın bildirim zinciri","ingilizce":"Defect reporting chain","tanim":"Kat görevlisinin tespit ettiği arızanın kat şefi aracılığıyla housekeeper’a, oradan teknik servise iletilmesidir.","ornek":"Hande, 214 numaralı odadaki klima arızasını kat şefi Hülya’ya bildirir; Hülya formları toplayıp housekeeper’a verir.","sektor":"Zincir bozulursa arıza geç giderilir ve konuk memnuniyetsizliği artar.","iliskili":["kh1-1-256","kh1-1-257"],"kontrol":null},{"id":"kh1-1-259","konu":"1.4.4","terim":"Misafirin bildirdiği arıza","ingilizce":"Guest-reported fault","tanim":"Odada kalan misafirin ön büroya bildirdiği ve kat görevlilerinin tespit ettiklerinden ayrı olarak raporla teknik servise iletilen arızadır.","ornek":"Gece 21.00’de 410 numaralı odanın konuğu klimanın çalışmadığını ön büroya bildirir; ön büro bu arızayı kat hizmetlerine iletir.","sektor":"Konuğun bildirdiği arıza da kat görevlisinin bulduğu arıza gibi rapora işlenir ve gün içinde çözülmesi için çalışılır.","iliskili":["kh1-1-258","kh1-1-260"],"kontrol":null},{"id":"kh1-1-260","konu":"1.4.4","terim":"Çözülemeyen arıza ve OOO","ingilizce":"Unresolved fault and OOO","tanim":"Gün içinde çözülemeyecek arızada odanın OOO olarak sisteme işlenip sorun çözülene kadar satışa kapatılmasıdır.","ornek":"Sabah 11.00’de 308 numaralı odanın banyo gideri tıkandı ve gün içinde çözülemeyeceği anlaşıldı; oda sisteme OOO olarak işlendi.","sektor":"OOO işlemi odanın yanlışlıkla konuğa satılmasını önler.","iliskili":["kh1-1-259","kh1-1-242"],"kontrol":null},{"id":"kh1-1-261","konu":"1.4.4","terim":"Arıza raporunun alanları","ingilizce":"Fields of the defect report","tanim":"Raporda katın, oda numarasının ve durumunun, arıza türünün ve arıza durumunun belirtilmesidir.","ornek":"Housekeeper Aslı, 201 numaralı odanın televizyon arızasını rapora arıza türü ve arıza durumuyla birlikte yazar.","sektor":"Alanlar sayesinde teknik servis arızayı hızlıca bulur.","iliskili":["kh1-1-257","kh1-1-258"],"kontrol":null},{"id":"kh1-1-304","konu":"1.4.4","terim":"Arıza formu uygulaması","ingilizce":"Defect form exercise","tanim":"Odada tespit edilen bir arızanın kat şefine bildirilmesini, arıza formuna yazılmasını ve teknik servise iletilmesini öğreten atölye uygulamasıdır.","ornek":"Atölye dersinde Mina, kontrol sırasında odada klozet sifonunun bozuk olduğunu fark eden kat görevlisi rolündedir; arızayı kat şefine bildirir, formu doldurtur ve teknik servise ulaştırır.","sektor":"Ders materyaline göre uygulama 10 dakika sürer. Adımlar: arızayı tespit etme, kat şefine bildirme, formda ayrıntıları yazma, arızayı teknik servis ve housekeeper’a iletme, tamirin yapılmasını ve sonucun kat hizmetlerine bildirilmesini sağlama.","iliskili":["kh1-1-256","kh1-1-257","kh1-1-258"],"kontrol":null},{"id":"kh1-1-262","konu":"1.4.5","terim":"Periyodik temizlik planı","ingilizce":"Periodic cleaning plan","tanim":"Temizlenecek odalar ve genel alanlarla ilgili housekeeper tarafından hazırlanıp kat hizmetleri personeline verilen iş planıdır.","ornek":"Pazartesi sabahı 08.00’de housekeeper Aslı, haftalık periyodik temizlik planını kat ofisinin panosuna asar.","sektor":"Plan, hangi işin ne zaman yapılacağını belli ederek işlerin aksamasını önler.","iliskili":["kh1-1-263","kh1-1-264"],"kontrol":null},{"id":"kh1-1-263","konu":"1.4.5","terim":"Periyodik planda genel alan işleri","ingilizce":"Public-area tasks in the plan","tanim":"Genel alanlarda hangi işlemlerin hangi sıklıkla yapılacağının planda yazılmasıdır.","ornek":"Planda lobideki camların her hafta, havuz çevresinin her gün silineceği yazar; genel alan görevlisi Burak buna göre çalışır.","sektor":"Sıklık belirlenince işlerin düzenli yapılması kolaylaşır.","iliskili":["kh1-1-262","kh1-1-264"],"kontrol":null},{"id":"kh1-1-264","konu":"1.4.5","terim":"Periyodik planda oda işleri","ingilizce":"Room tasks in the plan","tanim":"Odalarda yapılacak günlük temizlik işlemlerinin ve check-out yapan odaların yeni konuklar için hazırlanmasının planda gösterilmesidir.","ornek":"Plan, çıkış yapan odaların öğleden önce yeni konuklar için hazırlanmasını ve dolu odalarda günlük temizlik yapılmasını gösterir.","sektor":"Plan, check-out odalarının yeni konuklar için zamanında hazırlanmasını güvence altına alır.","iliskili":["kh1-1-262","kh1-1-263"],"kontrol":null},{"id":"kh1-1-265","konu":"1.4.6","terim":"Anahtar/pas kartı kontrol defteri","ingilizce":"Key control book","tanim":"Kat görevlilerinin oda temizliği için kullandıkları pas anahtarı ve kartların kaydedildiği defterdir.","ornek":"Sabah 08.30’da kat ofisinde Hande, pas kartını anahtar kontrol defterine adını ve saati yazıp imzalayarak teslim alır.","sektor":"Pas anahtarı ve kart teslim alma ile teslim etme işlemleri imza ile yapılır; böylece kimde olduğu bellidir.","iliskili":["kh1-1-267","kh1-1-266"],"kontrol":null},{"id":"kh1-1-266","konu":"1.4.6","terim":"Anahtar teslim alma ve verme imzası","ingilizce":"Signing keys in and out","tanim":"Pas anahtarı ve kartın alınması ile geri verilmesinin imza karşılığı kayda geçirilmesidir.","ornek":"Akşam 17.00’de vardiyası biten Hande, pas kartını geri verirken defterde teslim saatini yazıp imzalar; kartın kimde olduğu kayıttan görülür.","sektor":"İmza, anahtarın kimde olduğunu gösterir ve güvenliği sağlar.","iliskili":["kh1-1-265","kh1-1-267"],"kontrol":null},{"id":"kh1-1-267","konu":"1.4.6","terim":"Anahtar ya da kartın kaybedilmesi","ingilizce":"Lost key or card","tanim":"Pas anahtarı ya da kart kaybolduğunda görevlilerce gerekli işlemlerin hemen başlatılmasıdır.","ornek":"Akşam 17.15’te pas kartının kaybolduğunu fark eden kat görevlisi Hande, durumu hemen kat şefi Hülya’ya bildirir.","sektor":"Kayıp kart güvenlik riski taşır; bu nedenle gecikmeden bildirilir.","iliskili":["kh1-1-265","kh1-1-266"],"kontrol":null,"gorsel":"h6-oda-anahtari-21"},{"id":"kh1-1-268","konu":"1.4.7","terim":"Oda demirbaş hasar ve kayıp formu","ingilizce":"Room damage and loss form","tanim":"Kat görevlisinin kontrolünde konuk tarafından yapıldığı tespit edilen hasarların ve demirbaş eşya kayıplarının yazıldığı ve kat şeflerine bildirildiği formdur.","ornek":"Çıkış sonrası 305 numaralı odada kırık bir bardak ve hasarlı bir sehpa bulan Hande, hasarı forma yazar.","sektor":"Hasar ya da eksik malzeme görüldüğü anda kat şefi aracılığıyla housekeeper’a bildirilir.","iliskili":["kh1-1-269","kh1-1-270"],"kontrol":null},{"id":"kh1-1-269","konu":"1.4.7","terim":"Hasar tespit raporunun alanları","ingilizce":"Fields of the damage report","tanim":"Formda tarih, oda numarası, hasar gören eşya, hasar durumu, hasarı veren konuk, giriş-çıkış tarihleri, tur operatörü, tespit eden kişi ve departman müdürü bilgilerinin yer almasıdır.","ornek":"Hande, hasar formuna önce tarihi ve oda numarasını, sonra hasar gören eşyayı ve hasar durumunu yazar.","sektor":"Form eksiksiz doldurulursa ön büro hasar işlemini doğru kayıtla yürütür.","iliskili":["kh1-1-268","kh1-1-270"],"kontrol":null},{"id":"kh1-1-270","konu":"1.4.7","terim":"Eksik ya da bozuk malzemenin bildirimi","ingilizce":"Reporting missing or damaged items","tanim":"Fark edilen eksik ya da bozuk malzemenin hemen kat şefi aracılığıyla housekeeper’a, oradan ön büroya iletilmesidir.","ornek":"Hande, 410 numaralı odada eksik bir bornoz fark eder; kat şefi Hülya’ya bildirir, Hülya durumu housekeeper’a iletir.","sektor":"Zamanında bildirim, konuk otelden ayrılmadan işlem yapılmasını sağlar.","iliskili":["kh1-1-268","kh1-1-271"],"kontrol":null},{"id":"kh1-1-271","konu":"1.4.7","terim":"Konuk ayrılmadan hasar işlemi","ingilizce":"Handling damage before departure","tanim":"Misafir işletmeden henüz ayrılmamışsa gerekli işlemlerin ön büro tarafından başlatılmasıdır.","ornek":"Öğleden önce 11.00’de hasar fark edildiğinde konuk hâlâ lobide olduğundan ön büro konukla hemen görüşür.","sektor":"Konuk ayrılmadan işlem başlatmak, hasarın kayda geçirilmesini ve konukla görüşülmesini kolaylaştırır.","iliskili":["kh1-1-270","kh1-1-268"],"kontrol":null},{"id":"kh1-1-272","konu":"1.4.8","terim":"Misafir çamaşır işlem formu","ingilizce":"Guest laundry form","tanim":"Konuk çamaşırlarının yıkanması, temizlenmesi ve ütülenmesi işlemlerini izlemek için kullanılan formdur.","ornek":"Öğleden sonra 14.00’te 504 numaralı odadaki konuk, çamaşır işlem formunu doldurup imzalar.","sektor":"Form, çamaşırların karışmadan konuk odasına teslim edilmesini sağlar.","iliskili":["kh1-1-273","kh1-1-274","kh1-1-275"],"kontrol":null},{"id":"kh1-1-273","konu":"1.4.8","terim":"Çamaşır formundaki bilgiler","ingilizce":"Details on the laundry form","tanim":"Formda çamaşırın adedinin, cinsinin, ütü ya da kuru temizleme isteğinin, istenen zamanın ve işlem ücretlerinin yazılmasıdır.","ornek":"Konuk formda dört gömleğin ütülenmesini yazar ve çamaşırların ertesi sabah 08.00’e kadar odada olmasını ister.","sektor":"Konuk işlem ücretlerini formdan görür; ücret yazılmazsa teslimde “bu kadar tutacağını bilmiyordum” itirazı çıkabilir.","iliskili":["kh1-1-272","kh1-1-274"],"kontrol":null},{"id":"kh1-1-274","konu":"1.4.8","terim":"Çamaşır formunun nüshaları ve yeri","ingilizce":"Laundry form copies and location","tanim":"Formun odada gardıropta ya da masa çekmecesinde bulunması ve nüshalarının konukta, çamaşırhanede ve kat hizmetleri ofisinde kalmasıdır.","ornek":"Konuk 504 numaralı odanın masa çekmecesindeki formu alır; doldurulan nüshalar konukta, çamaşırhanede ve kat ofisinde kalır.","sektor":"Ders materyaline göre form üç nüsha hâlinde düzenlenir: biri konukta, biri çamaşırhanede, biri kat ofisinde kalır.","iliskili":["kh1-1-272","kh1-1-275"],"kontrol":null},{"id":"kh1-1-275","konu":"1.4.8","terim":"Formun çamaşırla birlikte torbaya konması","ingilizce":"Placing the form and laundry in the bag","tanim":"Konuğun doldurup imzaladığı formun çamaşırla birlikte kirli çamaşır torbasına konmasıdır.","ornek":"Akşam 18.00’de oda görevlisi Hande, konuğun torbasındaki formu ve çamaşırları çamaşırhaneye teslim eder.","sektor":"Formun diğer bölümlerini ilgili kat görevlisi doldurur; böylece çamaşırlar birbirine karışmadan çıkarılıp odaya gönderilir.","iliskili":["kh1-1-272","kh1-1-273"],"kontrol":null},{"id":"kh1-1-276","konu":"1.4.9","terim":"Konukların unuttuğu eşya (kayıp eşya)","ingilizce":"Lost property","tanim":"Konuğun konaklaması sırasında ya da ayrılırken odalarda ve genel alanlarda unuttuğu her türlü eşyadır.","ornek":"Çıkış sonrası 412 numaralı odada bir saat bulan oda görevlisi Hande, saati kat şefine teslim eder.","sektor":"Sektörde “lost property” ya da “lost and found” denir.","iliskili":["kh1-1-277","kh1-1-278"],"kontrol":null,"gorsel":"t10a-kayip-esya-kutusu"},{"id":"kh1-1-277","konu":"1.4.9","terim":"Kayıp eşya sorumluluğu","ingilizce":"Responsibility for lost property","tanim":"Unutulan eşyanın saklanması ve istenince konuğa geri verilmesine ilişkin tüm işlemlerin kat hizmetleri bölümünde olmasıdır.","ornek":"Konuk telefonla unuttuğu şemsiyeyi sorunca ön büro, çağrıyı kat hizmetlerine yönlendirir.","sektor":"İşlemler işletmenin kayıp eşya prosedürüne göre yürütülür.","iliskili":["kh1-1-276","kh1-1-278"],"kontrol":null,"gorsel":"t12b-kayip-esya-kameralar"},{"id":"kh1-1-278","konu":"1.4.9","terim":"Kayıp eşya formunun düzenlenmesi","ingilizce":"Completing a lost property form","tanim":"Bulunan eşya için kat şefi tarafından ayrı ayrı hazırlanan forma eşya bilgilerinin yazılmasıdır.","ornek":"Kat şefi Hülya, odada bulunan saat için kayıp eşya formunu düzenler ve eşyanın cinsini yazar.","sektor":"Form eşyanın kaydını tutar ve konuğa teslimde dayanak olur.","iliskili":["kh1-1-279","kh1-1-280"],"kontrol":null},{"id":"kh1-1-279","konu":"1.4.9","terim":"Kayıp eşya formunun alanları","ingilizce":"Fields of the lost property form","tanim":"Formda eşyanın cinsinin, bulunduğu yerin ve tarihin, bulunduğu andaki durumunun, bulan, teslim eden ve teslim alan kişilerin ve açıklamaların yer almasıdır.","ornek":"Hülya forma eşyanın bulunduğu yeri, tarihini, bulan kişinin adını ve teslim alan kişiyi yazar.","sektor":"Her alan, eşyanın kimden kime geçtiğini izlemeyi sağlar.","iliskili":["kh1-1-278","kh1-1-280"],"kontrol":null},{"id":"kh1-1-280","konu":"1.4.9","terim":"Kayıp eşya formunun nüshaları","ingilizce":"Copies of the lost property form","tanim":"Formun bir nüshasının ön büroya gönderilmesi, diğerinin kat hizmetleri ofisinde kalmasıdır.","ornek":"Hülya formun bir nüshasını ön büroya gönderir, diğerini kat ofisinin dosyasına koyar.","sektor":"Ders materyaline göre form iki nüsha hazırlanır.","iliskili":["kh1-1-278","kh1-1-279"],"kontrol":null},{"id":"kh1-1-281","konu":"1.4.9","terim":"Kayıp eşyanın değerine göre muhafazası","ingilizce":"Storing lost property by value","tanim":"Değerine göre uygun şart ve ortamda saklanan, unutulmuş eşyanın korunmasıdır.","ornek":"Kat ofisinde bulunan değerli bir saat, kilitli dolapta; sıradan bir şemsiye ise depodaki eşya rafında saklanır.","sektor":"Kıymetli eşyanın güvenli saklanması, eşyanın zarar görmesini ve karışmasını önler.","iliskili":["kh1-1-278","kh1-1-277"],"kontrol":null},{"id":"kh1-1-303","konu":"1.4.9","terim":"Kayıp eşya formu uygulaması","ingilizce":"Lost property form exercise","tanim":"Odada unutulmuş değerli bir eşyanın bulunmasından, kayıp eşya formunun düzenlenip imzalanmasına ve housekeeper aracılığıyla ön büroya iletilmesine kadar olan adımları öğreten atölye uygulamasıdır.","ornek":"Atölye dersinde Kaan ve Zeynep kat görevlisi ile kat şefi rollerini paylaşır; odada bulunan bir saati forma yazar, imzalar ve housekeeper rolündeki arkadaşlarına teslim eder.","sektor":"Ders materyaline göre uygulama 20 dakika sürer. Adımlar: eşyayı kat şefine bildirme, formu düzenleme, eşyanın cinsini, yerini, kim tarafından bulunduğunu ve durumunu yazma, kat şefiyle imzalama, raporu housekeeper’a iletme, housekeeper’ın raporu incelemesini ve ön büroya bilgi vermesini sağlama.","iliskili":["kh1-1-278","kh1-1-279","kh1-1-276"],"kontrol":null},{"id":"kh1-1-282","konu":"1.4.10","terim":"Oda bilgi kartı","ingilizce":"Room information card","tanim":"Çeşitli nedenlerle temizlik hizmeti verilemeyen odadaki konuğu bilgilendirmek için kat hizmetlerince hazırlanıp odaya bırakılan karttır.","ornek":"Konuk sabah 09.00’da temizlik istemediğini bildirince Hande, oda bilgi kartını hazırlar ve odaya bırakır.","sektor":"Kart, konuğun neden hizmet alamadığını bilmesini sağlar.","iliskili":["kh1-1-283","kh1-1-284"],"kontrol":null},{"id":"kh1-1-283","konu":"1.4.10","terim":"Oda bilgi kartındaki bilgiler","ingilizce":"Content of the room information card","tanim":"Kartta odaya hangi nedenle, saat kaça kadar hizmet verilemediğinin ayrıntılı yazılmasıdır.","ornek":"Hande kartın üzerine odaya hizmet verilemeyişinin nedenini ve saatini, örneğin “14.00’e kadar” diye yazar.","sektor":"Konuk, odasına neden girilemediğini ve ne zaman girileceğini kartta okursa beklemeyi daha kolay kabul eder; kart ön büroya gelen şikâyeti de azaltır.","iliskili":["kh1-1-282","kh1-1-284"],"kontrol":null},{"id":"kh1-1-284","konu":"1.4.11","terim":"Oda denetleme formu","ingilizce":"Room inspection form","tanim":"Odaların temizliğinden sonra kat şefi tarafından yapılan son kontrol için kullanılan formdur.","ornek":"Öğleden sonra 15.00’te kat şefi Hülya, temizlenen 312 numaralı odada oda denetleme formunu adım adım kontrol eder.","sektor":"Form, temizlik kalitesinin ölçülmesini sağlar.","iliskili":["kh1-1-285","kh1-1-286"],"kontrol":null},{"id":"kh1-1-285","konu":"1.4.11","terim":"Denetleme formundaki temizlik standartları","ingilizce":"Cleaning standards on the inspection form","tanim":"Formda işletmenin oda temizlik standartlarına göre belirlediği kuralların yer almasıdır.","ornek":"Formda yatak yapımı, banyo temizliği ve toz alma gibi işletmenin belirlediği standartlar sıralanır; Hülya her maddeyi işaretler.","sektor":"Kat şefi bu kuralların yerine getirilip getirilmediğine bakar.","iliskili":["kh1-1-284","kh1-1-286"],"kontrol":null},{"id":"kh1-1-286","konu":"1.4.11","terim":"Denetimde eksik işlemin tamamlatılması","ingilizce":"Having missed tasks completed","tanim":"Denetim sırasında bulunan eksik ya da yapılmamış işlemin tamamlanmasının sağlanmasıdır.","ornek":"Öğleden sonra 15.00’te denetim yapan kat şefi Hülya, 312 numaralı odada banyo aynasında leke bulur; Hande’nin lekeyi silmesini sağlayıp odayı yeniden kontrol eder.","sektor":"Odanın satışa hazır sayılması için eksik işlemler tamamlanır.","iliskili":["kh1-1-284","kh1-1-285"],"kontrol":null},{"id":"kh1-1-287","konu":"1.4.12","terim":"Diğer kat hizmetleri formları ve belgeleri","ingilizce":"Other housekeeping forms and documents","tanim":"İşletmenin büyüklüğüne ve kat hizmetleri bölümünün yönetim politikasına göre kullanılan ek form ve belgelerdir.","ornek":"Büyük bir şehir otelinde birçok ek form kullanılırken, küçük bir pansiyon yalnızca birkaç forma ihtiyaç duyar.","sektor":"Hangi form ve belgenin kullanılacağı işletmeden işletmeye değişir.","iliskili":["kh1-1-288","kh1-1-289","kh1-1-298"],"kontrol":null},{"id":"kh1-1-288","konu":"1.4.12","terim":"İşletme temizlik standartları formu","ingilizce":"Cleaning standards form","tanim":"İşletmenin oda ve alan temizliğinde uyulacak ölçüleri yazılı olarak gösteren formdur.","ornek":"Yeni başlayan oda görevlisi Selin, bir odanın nasıl temizleneceğini işletme temizlik standartları formundan öğrenir.","sektor":"Standartlar herkes için aynı kaliteyi güvence altına alır.","iliskili":["kh1-1-287","kh1-1-297"],"kontrol":null},{"id":"kh1-1-289","konu":"1.4.12","terim":"Oda değişim formu","ingilizce":"Room change form","tanim":"Konuğun odasının değiştirilmesi durumunda düzenlenen formdur.","ornek":"Gece 22.00’de klima arızası yüzünden 307’den 309’a geçen konuk için oda değişim formu düzenlenir.","sektor":"Form oda değişiminin kayda geçirilmesini sağlar.","iliskili":["kh1-1-287","kh1-1-290"],"kontrol":null},{"id":"kh1-1-290","konu":"1.4.12","terim":"Ekstra yatak ve bebek yatağı işlem formları","ingilizce":"Extra bed and baby cot forms","tanim":"Odaya ek yatak ya da bebek yatağı konulması işlemlerinin kaydedildiği formlardır.","ornek":"Akşam 19.00’da çocuklu bir aile bebek yatağı isteyince kat ofisi bebek yatağı işlem formunu düzenler.","sektor":"Formlar yatakların takibini sağlar; form olmazsa odadan çıkarılan ekstra yatak unutulur ve konuk gereksiz yere ücretlendirilebilir.","iliskili":["kh1-1-287","kh1-1-289"],"kontrol":null},{"id":"kh1-1-291","konu":"1.4.12","terim":"Çamaşırhane kirli ve temiz malzeme teslim formları","ingilizce":"Laundry exchange forms","tanim":"Kirli ve temiz malzemenin çamaşırhane ile kat ofisi arasında teslim edildiğini gösteren formlardır.","ornek":"Kat görevlisi Hande, sabah 09.00’da kirli nevresimleri çamaşırhaneye teslim ederken teslim formunu düzenler.","sektor":"Teslim formları çamaşır kaybını önler; hangi çamaşırın kimde olduğu belli olmazsa eksik çıkan havlunun sorumlusu bulunamaz.","iliskili":["kh1-1-287","kh1-1-292"],"kontrol":null},{"id":"kh1-1-292","konu":"1.4.12","terim":"Kat ofisi ve çamaşır sayım tutanakları","ingilizce":"Store and linen count sheets","tanim":"Kat ofisindeki malzemelerin ve çamaşırların sayımının kaydedildiği tutanaklardır.","ornek":"Ay sonunda sabah 08.00’de kat ofisinde havlular ve nevresimler sayılır; sonuç sayım tutanağına yazılıp stok kaydıyla karşılaştırılır.","sektor":"Sayım stok kontrolünü sağlar; eksik çıkan havlu fark edilmezse yeni alım geç yapılır ve oda hazırlığı aksar.","iliskili":["kh1-1-287","kh1-1-291"],"kontrol":null},{"id":"kh1-1-293","konu":"1.4.12","terim":"Personel değerlendirme formu","ingilizce":"Staff appraisal form","tanim":"Çalışanın işini ne kadar iyi yaptığının dönem dönem yazılı olarak değerlendirildiği formdur.","ornek":"Yıl sonunda kat şefi Hülya, her oda görevlisi için personel değerlendirme formunu doldurur ve gelişim alanlarını çalışanla birlikte konuşur.","sektor":"Değerlendirme gelişim alanlarını gösterir.","iliskili":["kh1-1-294","kh1-1-295"],"kontrol":null,"gorsel":"m1-degerlendirme-formu"},{"id":"kh1-1-294","konu":"1.4.12","terim":"İş tanımı kartı","ingilizce":"Job description card","tanim":"Bir görevin sorumluluklarını gösteren karttır.","ornek":"İşe yeni başlayan Selin, ilk gün iş tanımı kartında oda görevlisinin sorumluluklarını okur; hangi işlerin kendisine ait olduğunu böylece öğrenir.","sektor":"Kart herkesin ne yapacağını bilmesini sağlar.","iliskili":["kh1-1-293","kh1-1-295"],"kontrol":null},{"id":"kh1-1-295","konu":"1.4.12","terim":"Haftalık çalışma çizelgesi","ingilizce":"Weekly duty roster","tanim":"Personelin haftalık çalışma günlerini ve vardiyalarını gösteren çizelgedir.","ornek":"Pazartesi sabahı kat ofisinin panosuna asılan haftalık çalışma çizelgesinden Hande hangi gün hangi vardiyada olduğunu öğrenir.","sektor":"Çizelge asılmadan oda dağılımı yapılamaz; vardiyasını bilmeyen görevli işe geç kalır ya da hiç gelmez.","iliskili":["kh1-1-294","kh1-1-293"],"kontrol":null,"gorsel":"os-cizelge-kodlari"},{"id":"kh1-1-296","konu":"1.4.12","terim":"Elektrikli araçların kullanma kılavuzu","ingilizce":"Equipment user manual","tanim":"Makine ve elektrikli araçların güvenli kullanımını anlatan yazılı kılavuzdur.","ornek":"Kat ofisine yeni bir halı yıkama makinesi gelince, kullanma kılavuzu makinenin yanında saklanır.","sektor":"Kılavuz makine arızasını ve iş kazasını azaltır.","iliskili":["kh1-1-297","kh1-1-288"],"kontrol":null},{"id":"kh1-1-297","konu":"1.4.12","terim":"Malzeme kullanım talimatı","ingilizce":"Instructions for use of cleaning materials","tanim":"Temizlik malzemelerinin nasıl kullanılacağını anlatan yazılı talimattır.","ornek":"Dezenfektanın saklandığı dolabın kapağına malzeme kullanım talimatı asılır; yeni gelen görevli Burak, oranı ve eldiven uyarısını sabah 08.00’de oradan okur.","sektor":"Talimat okunmadan kullanılan ürün hem yüzeye hem kişiye zarar verir; doğru oran talimattan öğrenilir.","iliskili":["kh1-1-296","kh1-1-288"],"kontrol":null},{"id":"kh1-1-298","konu":"1.4.12","terim":"Memorandum","ingilizce":"Memorandum","tanim":"İşletme içinde duyuru niteliğinde kısa yazılı notlardır.","ornek":"Yönetici, yeni çalışma düzenini personelin görebileceği panoya memorandum olarak asar; vardiyaya gelen herkes ilk gün oradan okur.","sektor":"Memorandum bilgiyi kayıtlı olarak yayar; “duymadım” denmesini önler ve herkes aynı değişikliği aynı gün öğrenir.","iliskili":["kh1-1-287","kh1-1-297"],"kontrol":null},{"id":"kh1-1-299","konu":"1.4.12","terim":"112 Acil Çağrı Merkezi","ingilizce":"Emergency call centre (112)","tanim":"İtfaiye, jandarma, polis, sağlık, orman, sahil güvenlik ve AFAD gibi acil kurumların çağrılarının tek numarada toplandığı merkezdir.","ornek":"Öğleden sonra 15.00’te koridorda bayılan bir konuğu gören oda görevlisi Hande, önce 112’yi arar ve amirine haber verir.","sektor":"Acil durumlarda tek numara aranır; önce can güvenliği için 112 aranır, ardından amire haber verilir.","iliskili":["kh1-1-287","kh1-1-222"],"kontrol":null,"gorsel":"t11a-ambulans-112"}],"sorular":[{"id":"kh1-1-s001","tur":"coktan-secmeli","soru":"Otel yönetimi kat ofisi için dört boş oda arasından seçim yapıyor. Hangisi kat ofisi ve depo olarak en uygundur?","secenekler":["Duvarlarından nem sızan, bodrum katındaki geniş oda","Çamaşırhane buharının geçtiği, nemli koridorun yanındaki oda","Penceresi ve havalandırması olmayan küçük oda","Kuru, havalandırmalı ve zemini kolay temizlenen oda"],"dogru":3,"aciklama":"Kat ofisi ve depolar kuru, havalandırmalı ve kolay temizlenebilir olmalıdır; nemli yerde tekstil ve kimyasal zarar görür.","konu":"1.1"},{"id":"kh1-1-s002","tur":"coktan-secmeli","soru":"Kimyasal ve zehirli maddelerin neden kilitli dolapta saklandığı sorulduğunda hangi yanıt doğrudur?","secenekler":["Yetkisi olmayanların ulaşıp kaza yaşamasını önlemek için","Stok sayımının her gün daha hızlı yapılabilmesi için","Kimyasal kokusunun diğer odalara yayılmasını engellemek için","FIFO yönteminin uygulanmasını zorunlu kıldığı için"],"dogru":0,"aciklama":"Kilitli dolap kimyasalı yetkisiz kişilerden korur. Koku ya da sayım kilidin esas amacı değildir; FIFO ise stokun sırasıyla ilgilidir.","konu":"1.1"},{"id":"kh1-1-s003","tur":"coktan-secmeli","soru":"Koridorda ıslak zemin için “düşme tehlikesi” işareti asılı. Bu işaret diğer işaret gruplarından hangi özelliğiyle ayrılır?","secenekler":["Tehlikeyi bildirir; önlemi çalışan kendisi alır","Belirli bir davranışın yapılmasını kesin olarak yasaklar","Bulunulan alanda mutlaka yapılacak davranışı belirtir","Yalnızca kimyasal depolarında asılması zorunludur"],"dogru":0,"aciklama":"Uyarıcı işaret tehlikeyi bildirir ama ne yapılacağını söylemez. Yasaklayıcı işaret davranışı yasaklar, emredici işaret ise yapılacak davranışı gösterir.","konu":"1.1"},{"id":"kh1-1-s004","tur":"coktan-secmeli","soru":"Kimyasal deposunun kapısında “sigara içilmez” ve “toksik madde” işaretleri yan yana asılıdır. Bu iki işaret hangi gruplara girer?","secenekler":["Sigara içilmez uyarıcı, toksik madde yasaklayıcıdır","Sigara içilmez yasaklayıcı, toksik madde uyarıcıdır","Sigara içilmez emredici, toksik madde uyarıcıdır","Sigara içilmez yasaklayıcı, toksik madde emredicidir"],"dogru":1,"aciklama":"Yasaklayıcı işaret bir davranışı yasaklar; uyarıcı işaret tehlikeyi bildirir. Emredici işaret ise mutlaka yapılacak davranışı gösterir.","konu":"1.1"},{"id":"kh1-1-s005","tur":"coktan-secmeli","soru":"Depoya yeni sabun kolileri geldi; rafta eski koliler duruyor. FIFO yöntemine göre ne yapılmalıdır?","secenekler":["Yenileri öne koyup eskilerin arkada beklemesini sağlamak","Eski ve yeni kolileri açıp birbirine karıştırmak","Yeni kolileri ayrı bir rafa koyup eskilere dokunmamak","Yenileri eskilerin arkasına koymak, eskileri öne almak"],"dogru":3,"aciklama":"FIFO’da ilk giren ilk çıkar; eski stok öne alınır. Yenileri öne koymak eski malzemeyi rafta bekletip bozulmasına yol açar.","konu":"1.1"},{"id":"kh1-1-s006","tur":"coktan-secmeli","soru":"Kat ofisinde FIFO yönteminin uygulanmasının asıl amacı hangisidir?","secenekler":["Malzemelerin renklerine ve boylarına göre dizilmesi","Eski malzemenin rafta bekleyip bozulmadan kullanılması","Rafların daha az yer kaplayacak biçimde düzenlenmesi","Kimyasalların tekstil malzemesinden ayrı bölmede tutulması"],"dogru":1,"aciklama":"FIFO, stokta ilk giren malzemeyi ilk kullandırarak eskimeyi önler. Renk, yer ve kimyasal ayrımı başka düzenleme ilkeleridir.","konu":"1.1"},{"id":"kh1-1-s007","tur":"coktan-secmeli","soru":"Kat ofisinin eksik malzemelerini depodan temin etmek için hangi yol izlenir?","secenekler":["Oda görevlisi, eksikleri mal talep formuyla depodan alır","Kat şefi, eksikleri uyuşmazlık raporuyla depoya bildirir","Depo görevlisi, ofisin eksiklerini kendiliğinden tamamlayıp getirir","Kat şefi, eksikleri mal talep formuyla depodan temin eder"],"dogru":3,"aciklama":"Çalışan eksiği kat şefine iletir; kat şefi listeyi mal talep formuyla depoya iletir.","konu":"1.1"},{"id":"kh1-1-s008","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi kat ofisi düzenine ilişkin yanlış bir uygulamadır?","secenekler":["Islak malzemeyi elektrikli ekipmanla aynı bölümde tutmak","Dolap ve rafları duvara sağlam şekilde monte etmek","Kimyasal ve zehirli maddeleri kilitli dolaplarda saklamak","Ofiste hem sıcak hem soğuk su tesisatı bulundurmak"],"dogru":0,"aciklama":"Su ile elektriğin yakınlığı kaza riski yaratır; bu yüzden ıslak malzeme ve elektrikli ekipman ayrı bölümlerde durur.","konu":"1.1"},{"id":"kh1-1-s009","tur":"coktan-secmeli","soru":"Kat ofisinde ıslak mop ve kovalar ile elektrikli süpürge neden ayrı bölümlerde tutulur?","secenekler":["Mopun kokusunun süpürgenin torbasına ve filtresine geçmesini önlemek için","Süpürge çalışırken mop ve kovaların kurumasını sağlamak için","Kovaların süpürgenin gövdesini aşındırmasını engellemek için","Su ve elektriğin yakınlığı kaza ve arıza riski yarattığı için"],"dogru":3,"aciklama":"Islak malzeme elektrikli cihaza zarar verir ve elektrik çarpması riski doğurur. Koku ya da aşınma bu ayrımın gerekçesi değildir.","konu":"1.1"},{"id":"kh1-1-s010","tur":"coktan-secmeli","soru":"Oda görevlisi her gün büyük kovayı yüksek bir lavabonun altına zorlukla yerleştirip kaldırıyor. Ofiste hangi düzenleme bu sorunu çözer?","secenekler":["Daha büyük bir kova kullanmak","Alçak musluklu bir lavabo bulundurmak","Kovayı akşamdan doldurup rafta bekletmek","Kimyasal dolabını lavaboya yaklaştırmak"],"dogru":1,"aciklama":"Alçak musluk, kova ve bidonları kaldırmadan doldurmayı sağlar; ergonomik ve hızlıdır. Daha büyük kova yükü ağırlaştırır.","konu":"1.1"},{"id":"kh1-1-s011","tur":"coktan-secmeli","soru":"Oda görevlisi Selin, vardiya başında bez setinin bittiğini fark etti. İlk adımı ne olmalıdır?","secenekler":["Eksik malzemeyi kat şefine bildirmek","Başka katın ofisinden bez almak","Kendi başına mal talep formu hazırlamak","Bez olmadan çalışmaya başlamak"],"dogru":0,"aciklama":"Çalışanlar eksik malzemeyi kat şefine bildirir; ofisin eksik listesini şef toplayıp depodan ister.","konu":"1.1"},{"id":"kh1-1-s012","tur":"coktan-secmeli","soru":"Kat arabasının üst bölümlerinde hangi malzemeler bulunur?","secenekler":["Temiz çarşaf, yastık kılıfı ve katlanmış havlular","Kimyasal şişeleri ve toz bezleri","Kirli çarşaf ve havlu torbası","Buklet malzemeleri ve oda formları"],"dogru":3,"aciklama":"Üst bölümde buklet ve formlar, alt raflarda temiz tekstil, kenar bölmelerde kimyasallar durur.","konu":"1.2.1"},{"id":"kh1-1-s013","tur":"coktan-secmeli","soru":"Oda görevlisi arabaya temiz havluları yerleştirecek. Hangi yerleşim doğrudur?","secenekler":["Katlayıp arabanın alt raflarına yerleştirmek","Buklet setlerinin yanındaki üst bölüme koymak","Kimyasalların bulunduğu yan bölmeye koymak","Çöp torbalarının asılı olduğu tarafa koymak"],"dogru":0,"aciklama":"Temiz çarşaf, yatak takımı ve havlular alt raflara katlanarak yerleştirilir.","konu":"1.2.1"},{"id":"kh1-1-s014","tur":"coktan-secmeli","soru":"Kat arabasına yerleştirme hakkında hangisi yanlıştır?","secenekler":["Buklet ve formlar üst bölümde durur","Kimyasallar, temiz çarşafların konduğu alt rafa yerleştirilir","Kimyasalların yanına toz bezleri konabilir","Arabanın bir yanına mop, diğer yanına çöp torbaları yerleştirilir"],"dogru":1,"aciklama":"Kimyasal temiz tekstille aynı rafta durmaz; yan bölmelerde, yanında toz bezleriyle taşınır.","konu":"1.2.1"},{"id":"kh1-1-s015","tur":"coktan-secmeli","soru":"Kat arabasında neden farklı renklerde çöp torbaları bulunur?","secenekler":["Çöpün hangi katın ya da odanın olduğunu ayırt etmek için","Torbaların boyutlarının birbirinden ayırt edilmesi için","Çöpün konuklar tarafından görülmemesini sağlamak için","Atıkların geri dönüşüm için türüne göre ayrı toplanması"],"dogru":3,"aciklama":"Çöpler genellikle geri dönüşüm amacıyla ayrıştırıldığı için farklı renkte torbalar kullanılır.","konu":"1.2.1"},{"id":"kh1-1-s016","tur":"coktan-secmeli","soru":"Oda görevlisi arabasına ihtiyacından çok fazla araç gereç yükledi. Bunun sonucu hangisidir?","secenekler":["Görevli eksik malzeme için ofise dönüp zaman kaybeder","Araba ağırlaşır, görevli yorulur ve malzeme dökülür","Temiz çamaşır sayısı yetersiz kalır ve oda bekler","Atık torbaları yetersiz kalır ve çöp odada birikir"],"dogru":1,"aciklama":"Fazla yük arabayı ağırlaştırır ve dökülmeye yol açar. Zaman ve enerji kaybı ise eksik hazırlanan arabanın sonucudur.","konu":"1.2.1"},{"id":"kh1-1-s017","tur":"coktan-secmeli","soru":"Selin’in raporunda tek kişilik yataklı iki oda ve çift kişilik yataklı üç oda var. Arabaya çarşafı nasıl yerleştirmelidir?","secenekler":["Bütün çarşafları çift kişilik alıp arabayı fazlasıyla doldurmak","Yalnız çift kişilik çarşaf alıp tek kişiliği odada sonradan istemek","Her oda için kat şefinden ayrı ayrı çarşaf talep etmek","Oda ve yatak sayısına göre tek ve çift kişilik ayrı ayrı"],"dogru":3,"aciklama":"Çarşaf ve yastık kılıfı, temizlenecek oda ve yatak sayısı kadar tek ve çift kişilik ayrı alınır; fazlası arabayı ağırlaştırır.","konu":"1.2.1"},{"id":"kh1-1-s018","tur":"coktan-secmeli","soru":"Kat arabası hazırlanırken kat görevlisi raporu hangi amaçla kullanılır?","secenekler":["Oda ve yatak sayısını denetleyip odaların durumunu not etmek için","Konukların kimlik ve ödeme bilgilerini kontrol edip doğrulamak için","Arabaya konacak malzemelerin fiyatlarını hesaplamak için","Günün sonunda kat şefine teslim edilecek raporu doldurmak için"],"dogru":0,"aciklama":"Rapor sayıma dayanak olur; arabaya konan tekstil ve buklet buna göre hesaplanır.","konu":"1.2.1"},{"id":"kh1-1-s019","tur":"coktan-secmeli","soru":"Genel alan temizlik arabasında aşağıdakilerden hangisi bulunmaz?","secenekler":["Mop suyunun sıkıldığı pres kova sistemi","Temiz çarşaf ve yastık kılıfı için alt raflar","Kuru ve ıslak kullanılan mop ve paspas takımları","Dezenfektan için askı aparatları ve tepsiler"],"dogru":1,"aciklama":"Çarşaf ve havlu kat arabasında taşınır; genel alan arabası zemin ve yüzey temizliği içindir.","konu":"1.2.2"},{"id":"kh1-1-s020","tur":"coktan-secmeli","soru":"Genel alan temizlik arabasının tekerleklerinin sessiz ve frenli olmasının nedeni hangisidir?","secenekler":["Arabanın hızını artırarak işi daha kısa sürede bitirmek","Arabadaki mop ve kovaların tekerleğe takılmasını önlemek","Aracın dar koridorlardan geçerken çevik ve daha kolay dönmesini sağlamak","Konukları rahatsız etmeden çalışmak ve aracın kaymasını önlemek"],"dogru":3,"aciklama":"Lobi ve restoran gibi yerlerde araba sessiz hareket etmeli, durduğunda kaymamalıdır.","konu":"1.2.2"},{"id":"kh1-1-s021","tur":"coktan-secmeli","soru":"Lobide zemini silen Emre’nin mopu fazla ıslak kalıyor ve zemin kayganlaşıyor. Genel alan arabasının hangi bölümüyle suyu sıkmalıdır?","secenekler":["Askı aparatıyla","Kapalı kimyasal bölümüyle","Pres kova sistemiyle","Dezenfektan tepsisiyle"],"dogru":2,"aciklama":"Mop suyu pres kova sisteminde sıkılır; zemin fazla ıslanmadığı için kayma riski azalır. Askı ve tepsi kimyasalı taşımak içindir.","konu":"1.2.2"},{"id":"kh1-1-s022","tur":"coktan-secmeli","soru":"Kirli çamaşır toplama arabasının farklı bölümlere ayrılmasının nedeni nedir?","secenekler":["Temiz ve kirli çamaşırın birlikte taşınması","Çamaşırın çamaşırhaneye ayrılmadan teslim edilmesi","Kimyasalların çamaşırdan ayrı tutulması","Çamaşırların türüne göre ayrı toplanması"],"dogru":3,"aciklama":"Farklı bölümler çamaşırı türüne göre ayırır ve çamaşırhanenin işini kolaylaştırır.","konu":"1.2.3"},{"id":"kh1-1-s023","tur":"coktan-secmeli","soru":"Oda görevlisi kirli çamaşır arabasını nerede tutmalıdır?","secenekler":["Temizlik yaptığı odalara yakın bir yerde","Kat ofisinin içindeki kapalı bir bölümde","Asansör holünde herkesin göreceği yerde","Çamaşırhane birimi girişinin hemen önünde"],"dogru":0,"aciklama":"Araba temizlenen odalara yakın tutulur; görevli kirli çamaşırı uzağa taşımaz.","konu":"1.2.3"},{"id":"kh1-1-s024","tur":"coktan-secmeli","soru":"Akşam 19.00’da lobide koltuğun yanına çay döküldü. Hangi araç en uygun ve en hızlı çözümdür?","secenekler":["Oda temizliğinde kullanılan kat arabası","Kirli çamaşırları toplayan araba","Halı ve koltuk yıkama makinesi","Elle taşınabilir temizlik basketi"],"dogru":3,"aciklama":"Basket, lobi gibi alanlarda acil durumlarda ve basit yüzey temizliğinde kolaylık sağlar.","konu":"1.2.4"},{"id":"kh1-1-s025","tur":"coktan-secmeli","soru":"Rapordaki bir odada konuk gece kalmamış ama oda boş değil. Bu oda hangi kısaltmayla gösterilir?","secenekler":["V/C","S/O","C/O","OOO"],"dogru":1,"aciklama":"S/O, dolu olduğu hâlde konuğun geceyi başka yerde geçirdiği odadır. V/C boş temiz, C/O çıkış, OOO arızalı odadır.","konu":"1.4.1"},{"id":"kh1-1-s026","tur":"coktan-secmeli","soru":"V/C ve OOO kısaltmalarını doğru karşılaştıran ifade hangisidir?","secenekler":["V/C boş ve temiz oda, OOO ise arızalı, kullanım dışı oda","V/C boş ve temiz oda, OOO ise dolu ve kullanımda olan oda","V/C arızalı kullanım dışı oda, OOO ise boş ve temiz oda","V/C ile OOO her ikisi de konuğa verilebilecek boş oda"],"dogru":0,"aciklama":"V/C boş ve temizlenmiş odadır; satışa verilmeden önce kat şefi kontrol eder. OOO ise arıza nedeniyle satış dışı kalan odadır. İkisini karıştırmak yanlış odanın satılmasına yol açar.","konu":"1.4.1"},{"id":"kh1-1-s027","tur":"coktan-secmeli","soru":"Bir konuk 307 numaralı odadan 309 numaralı odaya geçirildi ve raporda R/C yazıyor. Selin ne yapmalıdır?","secenekler":["Yalnız yeni odayı hazırlayıp eski odayı olduğu gibi bırakmalıdır","Konuk dışarıda olduğundan odayı boş kabul etmelidir","Temizliği bitmiş sayıp odanın kapısını kilitlemelidir","Hem eski odayı hem yeni odayı ayrı ayrı hazırlamalıdır"],"dogru":3,"aciklama":"R/C oda değişimidir; konuk eski odadan yeni odaya geçtiği için iki oda da ayrı ayrı hazırlanır. Yalnız yeni odayı hazırlamak eski odayı kullanıma hazır bırakmaz.","konu":"1.4.1"},{"id":"kh1-1-s028","tur":"coktan-secmeli","soru":"Raporda COMP yazan odayı hazırlayan Selin nasıl davranmalıdır?","secenekler":["Konuk ücret ödemediği için temizlik kapsamını kısaltmalıdır","Odayı diğer konuk odalarıyla aynı standartta hazırlamalıdır","Odayı yalnızca yönetim istediğinde ayrıca hazırlamalıdır","Standart buklet seti yerine sade bir set bırakmalıdır"],"dogru":1,"aciklama":"COMP ücretsiz konaklayan misafirdir; ücret ödenmemesi hizmet standardını değiştirmez. Özel ilgi gerektiren konuk ise VIP ile gösterilir.","konu":"1.2.4"},{"id":"kh1-1-s029","tur":"coktan-secmeli","soru":"Rapordaki “H/U” yazılı oda için hangi ifade doğrudur?","secenekler":["Oda ücretsiz konaklayan misafirin kullanımında","Oda otel personeli tarafından kullanılıyor","Oda gündüz kullanımı için konuğa verilmiş","Oda arıza nedeniyle satışa kapatılmış"],"dogru":1,"aciklama":"H/U house use demektir; oda otel personeli tarafından kullanılır. COMP ise ücretsiz misafiri gösterir.","konu":"1.4.1"},{"id":"kh1-1-s030","tur":"coktan-secmeli","soru":"Raporda kısaltma-anlam eşleşmelerinden hangisi yanlıştır?","secenekler":["DBL – tek kişilik oda","SNG – tek kişilik oda","TRP – üç kişilik oda","SUIT – büyük oda, yani suit"],"dogru":0,"aciklama":"DBL double yani çift kişilik odayı gösterir; tek kişilik oda SNG’dir.","konu":"1.2.4"},{"id":"kh1-1-s031","tur":"coktan-secmeli","soru":"Selin, kısaltma listesinde vardiya, yani nöbet anlamına gelen kısaltmayı arıyor. Hangisine bakmalıdır?","secenekler":["DEP","ARR","D/U","SHIFT"],"dogru":3,"aciklama":"SHIFT vardiya, yani nöbet demektir. DEP ayrılışı, ARR varışı, D/U gündüz kullanımını gösterir.","konu":"1.2.4"},{"id":"kh1-1-s032","tur":"coktan-secmeli","soru":"Kat ofisi düzenleme uygulamasında malzemeleri yerleştirmeden önce hangi işlem yapılmalıdır?","secenekler":["Kimyasalları kapalı bölüme yerleştirip levhaları kontrol etmek","Kat arabalarını düzenleyip ofisteki yerlerine koymak","Ofisi havalandırıp genel temizliği yapmak, rafları silmek","Yedek çöp torbalarını ve kâğıtları raflara dizmek"],"dogru":2,"aciklama":"Temiz olmayan rafa konan malzeme kirlenir; bu yüzden hazırlık temizlik, yerleştirme sonradır.","konu":"1.1"},{"id":"kh1-1-s033","tur":"coktan-secmeli","soru":"Uygulamada kimyasalların bulunduğu bölümde hangi kontrol yapılır?","secenekler":["Kimyasalların fiyatlarının mal talep formunda yazılı olup olmadığı","Bölümdeki uyarı levhalarının yerinde olup olmadığı","Kimyasal şişelerinin kaç adet kaldığının sayımı","Kimyasalların renk sırasına göre dizilip dizilmediği"],"dogru":1,"aciklama":"Kapalı bölümdeki uyarı levhaları çalışanı kimyasalın tehlikesine karşı uyarır; yerinde olması kontrol edilir.","konu":"1.1"},{"id":"kh1-1-s034","tur":"coktan-secmeli","soru":"Atölye uygulamasında bir öğrenci işi süresinde bitirdi ama grup arkadaşlarıyla hiç iletişim kurmadı. Çizelgede hangi ölçütten puan kaybeder?","secenekler":["Ön hazırlık","Zamanı kullanma becerisi","Olağan dışı durumlara hazır bulunma","İletişim becerisi"],"dogru":3,"aciklama":"İletişim becerisi çizelgedeki ölçütlerden biridir. Süre zamanı kullanma becerisiyle ölçülür ve bu yönden eksik yoktur.","konu":"1.1"},{"id":"kh1-1-s035","tur":"coktan-secmeli","soru":"Raflar duvara vidalanmadan kat ofisine yerleştirildi ve havlular dolu raflarda duruyor. Hangisi riski gidermek için en uygun çözümdür?","secenekler":["Rafların ayaklarına tekerlek takıp yerini değiştirmek","Rafları ıslak malzeme bölümüne taşımak","Rafları duvara sağlam şekilde monte etmek","Rafların üzerindeki havluları daha sık saymak"],"dogru":2,"aciklama":"Dolap ve raflar duvara sağlam monte edilirse devrilmez ve çalışanı yaralamaz.","konu":"1.1"},{"id":"kh1-1-s036","tur":"coktan-secmeli","soru":"Selin her gün ağır deterjan bidonlarını en üst raftan indirmek zorunda kalıyor. Ergonomi açısından en doğru düzenleme hangisidir?","secenekler":["Bidonları kilitli dolabın en üst rafına çıkarıp yerleştirmek","Bidonları kat arabasının üst bölümüne taşıyıp orada bırakmak","Bidonları depodan çıkarmayıp her seferinde depoya gitmek","Ağır bidonları belden aşağıdaki, kolay erişilen rafa koymak"],"dogru":3,"aciklama":"Ağır ve sık kullanılan malzeme el ve bel hizasında durursa çalışan zorlanmaz; kat ofisi düzeni ergonomiye göre kurulur.","konu":"1.1"},{"id":"kh1-1-s037","tur":"coktan-secmeli","soru":"Yeni başlayan bir kat görevlisi ilk gün kat ofisine yönlendirildi. Orada hangi iş yapılır?","secenekler":["Konuk şikâyetleri alınıp ön büroya kayıtla iletilir","Günlük hazırlık yapılır, araç gereç saklanır, mola verilir","Konuk çamaşırları yıkanır, ütülenir ve odaya teslim edilir","Bulunan eşyalar konuklara teslim edilmek üzere sergilenir"],"dogru":1,"aciklama":"Kat ofisi, kat görevlilerinin hazırlık yaptığı, araç gerecini sakladığı ve kısa dinlendiği bölümdür. Çamaşır ve bulunan eşya işlemleri başka birimlerin ve formların konusudur.","konu":"1.1"},{"id":"kh1-1-s038","tur":"coktan-secmeli","soru":"Kimyasal stokunun yönetiminde hangi uygulama doğrudur?","secenekler":["Kimyasal tamamen bitince yenisini sipariş etmek","Kimyasalı yalnız konuk talep edince temin etmek","Kimyasal bitmeden yenisini almak ve depoya koymak","Kimyasalı iki ofis arasında paylaştırarak stoku uzatmak"],"dogru":2,"aciklama":"Kimyasalın bitmesi beklenmez; temizliğin aksamaması için yenisi önceden alınır.","konu":"1.1"},{"id":"kh1-1-s039","tur":"dogru-yanlis","soru":"Kat ofislerinin yeri ve sayısı bütün otellerde aynıdır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Ofislerin yeri ve sayısı otelin mimari yapısına ve olanaklarına göre değişir.","konu":"1.1"},{"id":"kh1-1-s041","tur":"dogru-yanlis","soru":"Kat ofisinde bozulan ekipmanın yenisi alınmaz; yalnızca temizlenip bir kenara konur.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Eskiyen ve bozulan ekipman değiştirilir; yerine yenisi alınır.","konu":"1.1"},{"id":"kh1-1-s045","tur":"senaryo","durum":"Sabah 08.00’de kat ofisinde yeni havlu paketlerini teslim aldın. Rafta geçen haftadan kalan paketler duruyor.","soru":"Ne yaparsın?","secenekler":["Yeni paketleri öne koyup eski paketleri arkada bırakırsın","Eski paketleri öne çekip yenileri arkalarına koyarsın","Eski paketleri kullanmadan başka bir ofise gönderirsin","Yeni ve eski paketleri açıp birbirine karıştırırsın"],"dogru":1,"aciklama":"FIFO’ya göre ilk gelen ilk kullanılır; eski stok öne alınır ki rafta bekleyip bozulmasın.","konu":"1.1"},{"id":"kh1-1-s046","tur":"senaryo","durum":"Sabah 08.15’te kat şefi arabanı hazırlamanı söyledi. Raporda üç oda çift kişilik, iki oda tek kişilik yataklı görünüyor.","soru":"Arabana ne yerleştirirsin?","secenekler":["Elindeki bütün çarşafları ve havluları arabaya doldurursun","Yalnız çift kişilik çarşaf alırsın, tek kişilikleri sonradan getirirsin","Her oda için aynı sayıda tekstil alırsın ve rapora bakmazsın","Rapora bakıp oda ve yatak sayısına uygun çarşaf ve havlu alırsın"],"dogru":3,"aciklama":"Tekstil rapordaki oda ve yatak sayısına göre hesaplanır; fazlası arabayı ağırlaştırır, eksiği zaman kaybettirir.","konu":"1.2.1"},{"id":"kh1-1-s047","tur":"senaryo","durum":"Kat ofisine girdin; kimyasal dolabının kilidinin bozulduğunu, içinde dezenfektan ve ovma maddeleri olduğunu gördün.","soru":"Ne yaparsın?","secenekler":["Kat şefine bildirir, kilit onarılana kadar önlem istersin","Dolabın kapağını kapalı tutarak işine devam edersin","Kimyasalları kat arabasının yan bölmesine alıp gün boyu taşırsın","Kimyasalları kimse görmesin diye ofisin ortasındaki rafa çıkarırsın"],"dogru":0,"aciklama":"Kimyasalın kilitli durması yetkisiz kişilerin ulaşıp kaza yaşamasını önler. Eksiği bildirmek şefin işidir; kendi başına çözüm kuralı aşar.","konu":"1.1"},{"id":"kh1-1-s048","tur":"senaryo","durum":"Sabah 07.45’te arabanı hazırlıyorsun. Lobiden konuk, koltuk yanına kahve döküldüğünü söyleyip yardım istiyor. Altı odalık listen de bekliyor.","soru":"Ne yaparsın?","secenekler":["Bütün kat arabasını lobiye çekip lekeyi orada temizlersin","Konuğa durumu ön büroya bildirmesini söyleyip işine dönersin","Elle taşınabilir temizlik basketini alıp lekeyi hemen silersin","Altı odayı bitirdikten sonra lobiye bakacağını konuğa söylersin"],"dogru":2,"aciklama":"Basket acil durumlarda ve basit yüzey temizliğinde hızlı çözüm sağlar; araba küçük bir iş için gereksiz yük olur.","konu":"1.2.4"},{"id":"kh1-1-s101","tur":"coktan-secmeli","soru":"Yağmurlu bir günde lobinin zemini ıslandı. Zemini yıkayıp aynı anda kurutarak kayma riskini azaltan makine hangisidir?","secenekler":["Otel tipi elektrikli süpürge","Halı yıkama makinesi","Cilalama makinesi","Zemin temizleme makinesi"],"dogru":3,"aciklama":"Zemin temizleme makinesi ıslak-kuru çalışıp suyu çeker. Otel tipi süpürge yalnızca kuru kirleri alır, cilalama makinesi ise zemini yıkamak yerine cila uygular.","konu":"1.3.2"},{"id":"kh1-1-s102","tur":"coktan-secmeli","soru":"Zemin temizleme makineleri neden lobi ve havuz kenarı gibi alanlarda tercih edilir?","secenekler":["Zemini yumuşatıp ayağa rahat bir his verdiği için tercih edildiğinden","Suyu çekip zemini kuruttuğu için kayma ve düşme riskini azalttığından","Yalnızca gece saatlerinde sessizce çalışabilen tek makine olduğundan","Dezenfeksiyonu zemin yıkamadan önce otomatik yaptığından"],"dogru":1,"aciklama":"Konuğun yürüdüğü alanlarda zemin hem temiz hem kuru kalmalıdır. Makinenin sessiz olması süpürgeler için önemlidir; zemin makinesinin asıl yararı kayma riskini azaltmasıdır.","konu":"1.3.2"},{"id":"kh1-1-s103","tur":"coktan-secmeli","soru":"Kat şefi, belirli aralıklarla halı, mobilya ve yatakların da yıkanabileceği bir elektrikli süpürge seçecek. Hangisini seçmelidir?","secenekler":["Islak-kuru kullanıma uygun süpürge","Yalnızca kuru süpürme yapan süpürge","Buharla dezenfeksiyon yapan makine","Saçaklı paspas takımı"],"dogru":0,"aciklama":"Islak-kuru modeller hem süpürür hem yıkama yapar. Yalnızca kuru çalışan süpürge ıslak yüzeylerde kullanılamaz.","konu":"1.3.1"},{"id":"kh1-1-s104","tur":"coktan-secmeli","soru":"Otel tipi elektrikli süpürgenin sessiz ve kolay taşınır olması neden önemlidir?","secenekler":["Zemindeki mite türü kirlerin görünür olması için","Süpürgenin her odada saklanabilmesi için","Konukların rahatsız edilmemesi için","Halıların yıkanmasını gereksiz kılması için"],"dogru":2,"aciklama":"Temizlik araçlarının sessiz olması konuklar uyurken ya da dinlenirken rahatsızlığı önler. Derin temizlik ise emiş gücüyle sağlanır.","konu":"1.3.1"},{"id":"kh1-1-s105","tur":"coktan-secmeli","soru":"Çok işlevli zemin makinesi hakkında hangisi yanlıştır?","secenekler":["Temizleme ve silme işlemlerini yapabilir.","Yalnızca halı yıkama işini yapabilir.","Yıkama ve cila işlemlerini yapabilir.","Birden fazla ihtiyacı tek makineyle karşılar."],"dogru":1,"aciklama":"Çok işlevli makine temizleme, silme, yıkama ve cila gibi birden fazla işi yapar; yalnızca halı yıkamakla sınırlı değildir.","konu":"1.3.2"},{"id":"kh1-1-s106","tur":"coktan-secmeli","soru":"Kat görevlisi kapı kolunu önce siliyor, sonra dezenfektan uyguluyor. Bu sıranın nedeni nedir?","secenekler":["Dezenfektanın kokusu temizlik maddesinin kokusunu bastırdığı için","Temizlik maddesi mikroorganizmaları öldürdüğü için dezenfektan gereksiz kalır","Dezenfektan temizlik maddesi olmadığı için önce kirin alınması gerekir","Dezenfektan her kiri çözdüğü için sıra önemli değildir"],"dogru":2,"aciklama":"Dezenfektan kiri temizlemez; mikroorganizmaları hedefler. Bu yüzden önce temizlik yapılır, sonra dezenfektan uygulanır.","konu":"1.3.3"},{"id":"kh1-1-s107","tur":"coktan-secmeli","soru":"Temizlik ile dezenfeksiyon arasındaki fark hangisidir?","secenekler":["Temizlik mikroorganizmayı öldürür; dezenfeksiyon yalnızca kiri alır.","Her ikisi de aynı işlemdir ve aynı maddeyle birlikte yapılır.","Dezenfeksiyon yalnızca ısıyla, temizlik yalnızca kimyasalla yapılır.","Temizlik kiri giderir; dezenfeksiyon mikroorganizmayı hedefler."],"dogru":3,"aciklama":"Dezenfeksiyon cansız ortamdaki mikroorganizmaları hedefler ve ısı, UV ışını ya da kimyasalla yapılır; temizlik ise kirin giderilmesidir.","konu":"1.3.3"},{"id":"kh1-1-s108","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi dezenfeksiyon yöntemi değildir?","secenekler":["Cilalama","Isı kullanma","Ultraviyole (UV) ışını","Kimyasal madde kullanma"],"dogru":0,"aciklama":"Dezenfeksiyon ısı, UV ışını ve kimyasal maddelerle yapılır. Cilalama zemini koruyan ve parlatan bir işlemdir.","konu":"1.3.3"},{"id":"kh1-1-s109","tur":"coktan-secmeli","soru":"Çocuk odasındaki koltukları yalnızca güçlü buharla dezenfekte etmek isteyen kat şefi hangi makineyi hazırlatır?","secenekler":["Solüsyonlu dezenfeksiyon makinesini","Buharlı dezenfeksiyon makinesini","Halı ve koltuk yıkama makinesini","Zemin temizleme makinesini"],"dogru":1,"aciklama":"Dezenfeksiyon makineleri iki türdür: yalnızca güçlü buharla çalışanlar ve dezenfektan solüsyonuyla çalışanlar. Halı ve koltuk yıkama makinesi yıkar, dezenfekte etmez.","konu":"1.3.3"},{"id":"kh1-1-s110","tur":"coktan-secmeli","soru":"Kat görevlisi solüsyonlu dezenfeksiyon makinesini hazırlıyor. Hangi davranış doğrudur?","secenekler":["Ürünü yüzeye uygun seçip talimattaki oranı korumak","Etkisi artsın diye oranı göz kararı artırmak","Daha önce kullanılan ürünle yeni ürünü karıştırmak","Talimatı okumadan elindeki ilk ürünü doldurmak"],"dogru":0,"aciklama":"Solüsyonlu makinede ürün yüzeye ve talimata uygun seçilir, oranına dikkat edilir. Göz kararı oran ve ürün karıştırma güvenlik riski doğurur.","konu":"1.3.3"},{"id":"kh1-1-s111","tur":"coktan-secmeli","soru":"Zeminde eski cilayı sökmek için hangi ped seçilir?","secenekler":["Beyaz ped","Yeşil ped","Kırmızı ped","Siyah ped"],"dogru":3,"aciklama":"Siyah ped pedlerin en sert olanıdır ve cila sökmede kullanılır. Beyaz ped parlatır, yeşil ped cila öncesi ovar.","konu":"1.3.5"},{"id":"kh1-1-s112","tur":"coktan-secmeli","soru":"Bir zemin önce ovulup sonra parlatılacak. Pedler hangi sırayla kullanılır?","secenekler":["Önce beyaz, sonra siyah ped","Önce kırmızı, sonra yeşil ped","Önce yeşil, sonra beyaz ped","Önce siyah, sonra mavi ped"],"dogru":2,"aciklama":"Yeşil ped cilalanma öncesi ovma içindir, beyaz ped ise parlatma içindir. Siyah ped cila sökmede kullanıldığı için bu sıraya girmez.","konu":"1.3.5"},{"id":"kh1-1-s113","tur":"coktan-secmeli","soru":"Zemine cila neden uygulanır?","secenekler":["Zemindeki mikroorganizmaları yok edip dezenfekte etmek için","Zemini yumuşatıp ayağı daha az yoran hâle getirmek için","Zemindeki suyu çekip yüzeyi hızla kurutmak için","Yüzeyi korumak ve temizliğini kolaylaştırmak için"],"dogru":3,"aciklama":"Cila yüzeyi koruyan ve temizliği kolaylaştıran kimyasal bir maddedir. Mikroorganizmaları öldürmek dezenfeksiyonun işidir.","konu":"1.3.5"},{"id":"kh1-1-s114","tur":"coktan-secmeli","soru":"Havuz çevresindeki kaygan zemin ıslak ve köpüklü ovulacak. Cilalama makinesine hangi ped takılır?","secenekler":["Beyaz ped","Siyah ped","Mavi ped","Kırmızı ped"],"dogru":2,"aciklama":"Mavi ped ıslak, köpüklü ovma ve kuvvetli sprey temizliği içindir. Kırmızı ped sprey temizliğinde kullanılır, beyaz ped parlatır.","konu":"1.3.5"},{"id":"kh1-1-s115","tur":"coktan-secmeli","soru":"Sert zeminin cilalanmasıyla ilgili hangisi yanlıştır?","secenekler":["Cilalama sık yapıldığından ekipmanı saklamaya gerek yoktur.","Zeminin özelliğine göre farklı türde cilalar seçilir.","Cila yüksek devirle çalışan makineler yardımıyla uygulanır.","Yumuşak ve yıpranmaya yatkın yüzeylerde cilalama daha sık uygulanabilir."],"dogru":0,"aciklama":"Cilalama sık yapılan bir iş olmadığı için makine ve ekipmanları kat ofisinde ya da depoda iyi korunarak saklanır.","konu":"1.3.5"},{"id":"kh1-1-s116","tur":"coktan-secmeli","soru":"Nevresimlerin yıkamaya ve ütüye dayanıklı olması neden gerekir?","secenekler":["Koyu renkli kumaşlar çabuk soluk göründüğü için","Günlük olarak yıkanıp ütülendikleri için","Konuklar nevresimi odadan götürebildiği için","Nevresim yıl boyunca bir kez yıkandığı için"],"dogru":1,"aciklama":"Nevresimin temizliği günlük yapıldığından kumaşın bu işlemlere dayanması gerekir; dayanıksız kumaş çabuk eskir.","konu":"1.3.6"},{"id":"kh1-1-s117","tur":"coktan-secmeli","soru":"Öğleden sonra konuk ikinci kez havlu istedi ve oda görevlisi kat ofisindeki yedek takımdan hemen getirdi. Bu hizmeti hangi uygulama sağladı?","secenekler":["Her odaya yalnızca tek bir temiz havlu takımı bırakılması","Havluların yalnızca çamaşırhanede toplu hâlde tutulması","Kat ofisinde oda ve yatak sayısından fazla takım bulundurulması","Kat arabasında yedek takım bulundurulmaması ve çamaşırhaneden istenmesi"],"dogru":2,"aciklama":"Misafir talebine göre takımlar gün içinde değiştirileceğinden kat ofisinde yedek stok tutulur; stok olmazsa konuk beklemek zorunda kalır.","konu":"1.3.6"},{"id":"kh1-1-s118","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi iyi bir otel havlusunun niteliği değildir?","secenekler":["Yıkandıkça sertleşmesi","Suyu iyi emmesi","Yıkamaya dayanıklı olması","Kaliteli iplikle dokunmuş olması"],"dogru":0,"aciklama":"Havlunun sertleşme oranı düşük olmalıdır; yıkandıkça sertleşen havlu konuğun beklentisini karşılamaz.","konu":"1.3.6"},{"id":"kh1-1-s119","tur":"coktan-secmeli","soru":"Yatak yapımında yorgan ya da battaniyeyi saran, açık renkli otel tekstili hangisidir?","secenekler":["Yastık kılıfı","Ayak havlusu","Nevresim","Bornoz"],"dogru":2,"aciklama":"Nevresim yorgan ya da battaniyeyi saran tekstildir. Yastık kılıfı yastık içindir, ayak havlusu ve bornoz banyo tekstilidir.","konu":"1.3.6"},{"id":"kh1-1-s120","tur":"coktan-secmeli","soru":"Buklet setinde bulunan şampuan, sabun ve vücut losyonu hangi gruba girer?","secenekler":["Yardımcı buklet ürünleri","Özel temizlik maddeleri","Cilalar","Banyo ürünleri"],"dogru":3,"aciklama":"Şampuan, sabun ve losyon konuğun banyoda kullandığı ürünlerdir. Kibrit, tırnak törpüsü ve duş bonesi ise yardımcı ürünlerdir.","konu":"1.3.7"},{"id":"kh1-1-s121","tur":"coktan-secmeli","soru":"Hangisi yardımcı buklet ürünlerinden biridir?","secenekler":["Şampuan","Sabun","Duş bonesi","Vücut losyonu"],"dogru":2,"aciklama":"Duş bonesi, tırnak törpüsü ve kibrit yardımcı ürünlerdir. Şampuan, sabun ve losyon temel banyo ürünleridir.","konu":"1.3.7"},{"id":"kh1-1-s122","tur":"coktan-secmeli","soru":"Buklet malzemelerinin estetik görünümüne neden önem verilir?","secenekler":["Malzemeler odada kalıp konuk tarafından satın alındığı için","Kat arabasında daha az yer kaplayıp taşımayı kolaylaştırdığı için","Temizlik süresini kısaltıp odanın daha hızlı hazırlanmasını sağlamak için","İşletmenin saygınlığını artıran önemli detaylar oldukları için"],"dogru":3,"aciklama":"Buklet setleri işletmenin saygınlığını artıran küçük detaylardır; bu nedenle şık ve düzenli görünmelidir.","konu":"1.3.7"},{"id":"kh1-1-s123","tur":"coktan-secmeli","soru":"Beton, mozaik, taş ve mermer zeminlerde fazla suyu çekmek için hangi paspas kullanılır?","secenekler":["Saçaklı paspas","Kuru mop takımı","Lastikli paspas","Mikrofiber bez"],"dogru":2,"aciklama":"Lastikli paspas fazla suyu çekerek yüzeyi toz ve çamurdan arındırır. Saçaklı paspas ise ıslak silme işleminde kullanılır.","konu":"1.3.9"},{"id":"kh1-1-s124","tur":"coktan-secmeli","soru":"Zemini ıslak silmek için hangisi kullanılır?","secenekler":["Lastikli paspas","Kâğıt havlu","Saçaklı paspas","Kuru süpürge"],"dogru":2,"aciklama":"Saçaklı paspaslar ıslak silme işleminde kullanılır. Lastikli paspas ise fazla suyu çekmek içindir.","konu":"1.3.9"},{"id":"kh1-1-s125","tur":"coktan-secmeli","soru":"Islak, kuru ve nemli silme için farklı renkte mop kullanmanın yararı nedir?","secenekler":["Zeminin renginin zamanla değişmesi","Temizliğin daha kolay yapılması","Zeminde daha az su kullanılması","Mopların toptan daha ucuza alınması"],"dogru":1,"aciklama":"Renk ayrımı hangi mopun hangi işte kullanıldığını kolayca gösterir ve işi kolaylaştırır.","konu":"1.3.9"},{"id":"kh1-1-s126","tur":"coktan-secmeli","soru":"Ders materyalindeki renk koduna göre banyoda küvet ve lavaboyu silecek oda görevlisi hangi renkte mikrofiber bezi almalıdır?","secenekler":["Mavi","Pembe","Yeşil","Sarı"],"dogru":3,"aciklama":"Küvet ve lavabo için sarı bez ayrılır. Diğer renkler cam, toz ya da zemin gibi başka alanlar içindir ve işletmeye göre değişebilir.","konu":"1.3.10"},{"id":"kh1-1-s127","tur":"coktan-secmeli","soru":"Mikrofiber bezin zemin temizliğinde nemli, toz almada kuru kullanılması ne sağlar?","secenekler":["Bezin her kullanımdan sonra atılabilmesini","Zeminin aynı anda cilalanıp parlatılmasını","Temizliğin daha hijyenik ve hızlı yapılmasını","Bezin renginin yıkamalarda solmadan kalmasını"],"dogru":2,"aciklama":"Mikrofiber bez nemli de kuru da kullanılabilir; işe uygun hâliyle kullanmak temizliği hijyenik ve hızlı yapar.","konu":"1.3.10"},{"id":"kh1-1-s128","tur":"coktan-secmeli","soru":"İşletmeler neden renk kodlu bez sistemi kullanır?","secenekler":["Kirin bir alandan diğerine taşınmasını önlemek için","Bezlerin toptan ve daha ucuza alınabilmesi için","Bezlerin her kullanımdan sonra yıkanmasını gereksiz kılmak için","Bezlerin tamamını tek kullanımlık hâle getirmek için"],"dogru":0,"aciklama":"Temizlenen alana göre bez kullanmak hijyeni korur; bir alanın kiri başka alana taşınmaz.","konu":"1.3.10"},{"id":"kh1-1-s129","tur":"coktan-secmeli","soru":"Mikrofiber bez hakkında hangisi doğrudur?","secenekler":["Yalnızca kuru hâlde kullanılabilir.","Yalnızca cam ve ayna silmede kullanılabilir.","Her kullanımdan sonra atılması gereken bir üründür.","Hem nemli hem de kuru kullanılabilir."],"dogru":3,"aciklama":"Mikrofiber bez çok ince ipliklerden yapılır ve nemli ya da kuru kullanılabilir.","konu":"1.3.10"},{"id":"kh1-1-s130","tur":"coktan-secmeli","soru":"Lobideki cilalı mermer silinecek. Asitli ve alkali ürünler cilayı bozabileceğine göre hangi grup seçilir?","secenekler":["Nötr temizlik maddeleri","Kireç ve pas çözücüler","Temel temizlik maddeleri","Ovma maddeleri"],"dogru":0,"aciklama":"Asitli maddeler cilanın matlaşmasına, alkaliler ise zarara yol açar; nötr maddeler cilalı yüzeylerde tercih edilir.","konu":"1.3.11"},{"id":"kh1-1-s131","tur":"coktan-secmeli","soru":"Hangi temizlik maddesi ahşap zeminde kesinlikle kullanılmaz?","secenekler":["Genel temizlik maddeleri","Nötr temizlik maddeleri","Temel temizlik maddeleri","Cam ve ayna temizleme maddeleri"],"dogru":2,"aciklama":"Temel temizlik maddeleri yoğun kir ve cilayı söken güçlü ürünlerdir; ahşapta kullanılmaz.","konu":"1.3.11"},{"id":"kh1-1-s132","tur":"coktan-secmeli","soru":"Musluk, lavabo ve küvet gibi sürekli suyla temas eden yüzeylerde biriken kireci çözmek için hangisi kullanılır?","secenekler":["Genel temizlik maddeleri","Kireç ve pas çözücüler","Leke çözücüler","Cam ve ayna temizleme maddeleri"],"dogru":1,"aciklama":"Kireç ve pas çözücülerin asit oranı yüksektir ve kireçli yüzeylerde iyi sonuç verir.","konu":"1.3.11"},{"id":"kh1-1-s133","tur":"coktan-secmeli","soru":"Banyo temizliğinde toz ovma maddesi yerine sıvı ovma maddesi tercih edilmesinin nedeni nedir?","secenekler":["Sıvı ovma maddelerinin klor içermediği ve ağartmadığı için","Toz ovma maddeleri yüzeyi sıvılardan daha çok çizdiği için","Toz maddelerin kirleri yeterince temizleyemediği için","Sıvı ürünlerin daha ucuza satın alındığı için"],"dogru":1,"aciklama":"Toz ovma maddeleri yüzeyi daha çok çizer; sıvı maddeler daha güvenlidir.","konu":"1.3.11"},{"id":"kh1-1-s134","tur":"coktan-secmeli","soru":"Bir görevli ağır lekeyi çıkaramayınca çamaşır suyuna tuz ruhu eklemek istiyor. Neden vazgeçirilmelidir?","secenekler":["Karışım yüzeyde kalıcı bir leke bırakıp rengi değiştirir.","Çamaşır suyu tuz ruhuyla karışınca etkisini tümüyle kaybeder.","Karışım zehirli gaz çıkarıp solunuma zarar verir.","Karışım ahşap zeminlerde şişme ve çatlak yapar."],"dogru":2,"aciklama":"Temizlik ürünleri birbirine karıştırılmaz; çamaşır suyu ile tuz ruhunun karışımı zehirli gaz çıkarır.","konu":"1.3.11"},{"id":"kh1-1-s135","tur":"coktan-secmeli","soru":"Yeni bir leke çözücü geldi. Kullanmadan önce ne yapılır?","secenekler":["Kullanma talimatı okunup talimata uyulur.","Eski ürünle karıştırılarak güçlendirilir.","Doğrudan yüzeye dökülür.","Etiketi çıkarılıp başka kaba aktarılır."],"dogru":0,"aciklama":"Talimat oran, kullanım yeri ve güvenlik önlemlerini gösterir; okunmadan kullanılan ürün hem yüzeye hem kişiye zarar verebilir.","konu":"1.3.11"},{"id":"kh1-1-s136","tur":"coktan-secmeli","soru":"Sıvı bir temizlik maddesini gereğinden fazla kullanmak neden sorun yaratır?","secenekler":["Ürünün etkisini tümüyle ortadan kaldırır.","Yüzeyi dezenfekte ederek ek işlem gerektirir.","Cilayı daha parlak hâle getirir.","Yüzeye zarar verir, durulamayı güçleştirir."],"dogru":3,"aciklama":"Ürün talimatta yazılan oranda su ile karıştırılır; fazlası yüzeye zarar verir, durulamayı zorlaştırır ve ekonomik zarar yaratır.","konu":"1.3.11"},{"id":"kh1-1-s137","tur":"coktan-secmeli","soru":"Yağ çözücü çıplak elle kullanılırsa ne olur?","secenekler":["Ürünün etkisi azalır ve yüzeyde leke kalır.","Ciltteki yağı alıp cildin kurumasına yol açar.","Cilt ürünü emerek daha güçlü hâle gelir.","Ürün tene yapışıp sertleşerek kabuk oluşturur."],"dogru":1,"aciklama":"Yağ çözücüler ciltteki yağı alır ve kurumaya neden olur; bu yüzden eldiven kullanılır.","konu":"1.3.11"},{"id":"kh1-1-s138","tur":"coktan-secmeli","soru":"Bir temizlik maddesi görevlinin gözüne sıçradı. İlk doğru davranış hangisidir?","secenekler":["Gözü ovuşturup işe devam etmek","Ürünü gidermek için başka bir kimyasal damlatmak","Önce depoyu havalandırıp sonra yıkamak","Bol suyla yıkayıp amire haber vermek"],"dogru":3,"aciklama":"Sıçrayan maddenin bulunduğu bölge hemen bol suyla yıkanır, ardından amire haber verilir.","konu":"1.3.11"},{"id":"kh1-1-s139","tur":"coktan-secmeli","soru":"Temizlik maddelerinin kullanımıyla ilgili hangisi yanlıştır?","secenekler":["Kullanma talimatına uyulur.","Sıvı ürünler talimattaki oranda suyla karıştırılır.","Ürün etiketsiz küçük bir kaba aktarılabilir.","Kullanımdan sonra kapaklar kapatılır."],"dogru":2,"aciklama":"Başka bir kaba konulan ürünün üzerine hangi madde olduğu etiketle yazılmalıdır; etiketsiz kap yanlış kullanıma yol açar.","konu":"1.3.11"},{"id":"kh1-1-s140","tur":"coktan-secmeli","soru":"Depo sorumlusu toz kimyasalları nasıl saklamalıdır?","secenekler":["Nemsiz ortamda, kendi ambalajında, gıdadan uzakta","Gıda maddelerinin yanındaki, kapağı açık bir rafta","Etiketsiz tek bir kapta, hep birlikte toplayarak","Nemli depo zeminine yakın, açık torbalarda"],"dogru":0,"aciklama":"Toz kimyasallar nemsiz ortamda, kendi ambalajında ve gıdadan uzak saklanır; depo da sık sık havalandırılır.","konu":"1.3.11"},{"id":"kh1-1-s141","tur":"coktan-secmeli","soru":"Sıvı ve sprey temizlik ürünleri neden kullanılmadan önce çalkalanır?","secenekler":["Kullanım sırasında köpürmesini önlemek için","İçindeki sıvının daha çabuk soğumasını sağlamak için","Kapağın yerine daha sıkı oturmasını sağlamak için","İçindeki maddelerin dengeli ve iyice karışması için"],"dogru":3,"aciklama":"Çalkalama, içindeki maddelerin dengeli karışmasını sağlayarak ürünün etkisini tam gösterir.","konu":"1.3.11"},{"id":"kh1-1-s142","tur":"coktan-secmeli","soru":"Asit içeren bir temizlik maddesiyle çalışırken hangi uygulama doğrudur?","secenekler":["Havadar bir yerde maske ve eldiven kullanmak","Kapalı banyoda kapıyı kapatıp maskesiz çalışmak","Yalnızca eldiven takıp maske kullanmamak","Ürünü hava almayan dar bir alanda uygulamak"],"dogru":0,"aciklama":"Asitli ürünler havadar ortamda, maske ve eldivenle kullanılır; buharı solunum yollarını tahriş edebilir.","konu":"1.3.11"},{"id":"kh1-1-s143","tur":"coktan-secmeli","soru":"Eldiven, bone ve maske hangi amaçla kullanılır?","secenekler":["Temizlik süresini kısaltıp işi hızlandırmak","Elin, yüzün ve saçın kimyasallardan korunması","Kullanılan bezlerin çabuk kirlenmesini önlemek","Konuğa düzenli bir kıyafet görüntüsü vermek"],"dogru":1,"aciklama":"Bu malzemeler kimyasallara karşı kişiyi korur; amaç iş sağlığı ve güvenliğidir.","konu":"1.3.12"},{"id":"kh1-1-s144","tur":"coktan-secmeli","soru":"Housekeeper birinci raporu sabah 09.00’da hazırladı. İkinci rapor ne zaman düzenlenir?","secenekler":["Ertesi sabah, vardiya başlarken","Gece yarısı, gece görevlisi gelince","Öğleden sonra, odalar bittikten sonra","Aynı gün, her saat başında"],"dogru":2,"aciklama":"Rapor gün içinde sabah ve öğleden sonra olmak üzere iki kez düzenlenir; ikincisi odaların işlemleri bitince son durumu gösterir.","konu":"1.4.1"},{"id":"kh1-1-s145","tur":"coktan-secmeli","soru":"Housekeeping raporunun nüshaları hangi yerlere gönderilir?","secenekler":["Yalnızca ön büroya ve genel müdüre","Teknik servise, çamaşırhaneye ve güvenliğe","Genel müdüre, satın almaya ve insan kaynaklarına","Ön büroya, muhasebeye ve kat şefinin dosyasına"],"dogru":3,"aciklama":"Rapor ön büroya, muhasebeye ve kat şefinin dosyasına dağıtılır; böylece her bölüm gerekli bilgiye ulaşır.","konu":"1.4.1"},{"id":"kh1-1-s146","tur":"coktan-secmeli","soru":"Housekeeping raporuyla ilgili hangisi yanlıştır?","secenekler":["Günümüzde bilgisayar otomasyon programlarıyla hazırlanabilir.","Rapor yalnızca ön büro tarafından yazılır.","Bir nüshası muhasebeye gönderilir.","Günün ilk raporu sabah hazırlanır."],"dogru":1,"aciklama":"Housekeeping raporunu kat hizmetlerinde housekeeper hazırlar; ön büro ise kendi oda durum raporunu hazırlar.","konu":"1.4.1"},{"id":"kh1-1-s147","tur":"coktan-secmeli","soru":"Ön büronun günlük oda durum raporunda aşağıdakilerden hangisi yer alır?","secenekler":["Arıza raporları ile teknik servisin tamir çalışma notları","Çamaşır formlarının sayısı ile ütü ücretleri","Dolu odaların listesi ve ayrılan konuk değişiklikleri","Kayıp eşya formlarının listesi ve saklama yerleri"],"dogru":2,"aciklama":"Ön büro, dolu odaların listesini ve erken ya da geç ayrılmayla ilgili değişiklikleri kat hizmetlerine bildirir.","konu":"1.4.1"},{"id":"kh1-1-s148","tur":"coktan-secmeli","soru":"Konuğun bulunmadığı ama temizlenmeyi bekleyen oda raporda hangi kısaltmayla gösterilir?","secenekler":["V/D","V/C","OCC","OOO"],"dogru":0,"aciklama":"V/D boş kirli odayı gösterir. V/C boş ve temizlenmiş, OOO arızalı odadır.","konu":"1.4.1"},{"id":"kh1-1-s149","tur":"coktan-secmeli","soru":"Gideri tıkanan odanın arızası gün içinde çözülemeyecek. Odayı satıştan çıkarmak için raporda hangi kısaltma kullanılır?","secenekler":["OOO","S/O","H/U","R/C"],"dogru":0,"aciklama":"OOO arızalı, satış dışı odayı gösterir; S/O kullanılmamış dolu oda, H/U personel kullanımı, R/C oda değişimidir.","konu":"1.4.1"},{"id":"kh1-1-s151","tur":"coktan-secmeli","soru":"Konuğun odasının değiştirildiğini gösteren kısaltma hangisidir?","secenekler":["R/C","C/I","C/O","H/U"],"dogru":0,"aciklama":"R/C (room change) oda değişimini gösterir; C/I giriş, C/O çıkıştır.","konu":"1.4.1"},{"id":"kh1-1-s152","tur":"coktan-secmeli","soru":"Odanın konuk yerine otel personeli tarafından kullanıldığını hangi kısaltma gösterir?","secenekler":["S/O","H/U","OOO","C/I"],"dogru":1,"aciklama":"H/U (house use) personel kullanımındaki odayı gösterir; bu oda konuğa satılmaz.","konu":"1.4.1"},{"id":"kh1-1-s153","tur":"coktan-secmeli","soru":"Sabah 11.00’de konuk çıkış yaptı. Bu oda housekeeping raporunda hangi işaretle gösterilir?","secenekler":["C/I","C/O","H/U","S/O"],"dogru":1,"aciklama":"C/O konuğun o gün çıkış yaptığı odayı belirtir; C/I giriş yapan konuk odasıdır.","konu":"1.4.1"},{"id":"kh1-1-s154","tur":"coktan-secmeli","soru":"Kat görevlisi raporu neyi gösterir?","secenekler":["Ön büronun günlük satış ve gelir tutarlarını","Teknik servisin vardiya ve çalışma saatlerini","Konukların kimlik ve iletişim bilgilerini","Odalarda yapılan işlemleri ve son kontrolleri"],"dogru":3,"aciklama":"Kat görevlisi raporu, kat görevlisinin odalarda yaptığı işlemleri ve son kontrolleri gösterir.","konu":"1.4.2"},{"id":"kh1-1-s155","tur":"coktan-secmeli","soru":"Kat görevlisi raporunun sabah imza karşılığı alınıp gün sonunda imza karşılığı teslim edilmesinin yararı nedir?","secenekler":["Raporun kimde olduğunun ve sorumlunun bilinmesi","Raporun arşivde daha uzun süre saklanabilmesi","Raporun otomasyon programından silinmesinin kolaylaşması","Raporun konuk tarafından da imzalanıp onaylanması"],"dogru":0,"aciklama":"İmza, raporun kimde olduğunu ve sorumluluğu belirler; böylece takip kolaylaşır.","konu":"1.4.2"},{"id":"kh1-1-s156","tur":"coktan-secmeli","soru":"Ön büro raporunda bir oda boş temiz görünürken kat görevlisi odada konuğun bavulunu buldu. Hangi rapor düzenlenir?","secenekler":["Arıza bilgi formu","Kayıp eşya formu","Uyuşmazlık raporu","Oda değişim formu"],"dogru":2,"aciklama":"Raporlar arasındaki oda durumu farkı uyuşmazlık raporuyla belirtilir ve nedeni araştırılır.","konu":"1.4.3"},{"id":"kh1-1-s157","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi raporlar arasında uyuşmazlığa yol açan nedenlerden biri değildir?","secenekler":["Oda durumunun eksik ya da yanlış işaretlenmesi","Kat görevlisinin raporu imza karşılığı alması","Yapılan oda satışının raporda gösterilmemesi","Oda durumundaki değişikliğin raporlara işlenmemesi"],"dogru":1,"aciklama":"Raporu imza karşılığı almak sorumluluğu belirler; uyuşmazlık nedenleri işaretleme hataları, gösterilmeyen satış ve yansımayan değişikliklerdir.","konu":"1.4.3"},{"id":"kh1-1-s158","tur":"coktan-secmeli","soru":"Uyuşmazlık çıkınca düzeltme yapmadan önce nedeninin araştırılması neden gerekir?","secenekler":["Raporun daha uzun görünmesi için","Ön büroyu cezalandırmak için","Konuk odasının hemen boşaltılması için","Aynı hatanın tekrar etmemesi için"],"dogru":3,"aciklama":"Neden bulunmadan yapılan düzeltme hatayı gidermez; bu yüzden önce kaynak bulunur.","konu":"1.4.3"},{"id":"kh1-1-s159","tur":"coktan-secmeli","soru":"Kat görevlisinin temizlik sırasında tespit ettiği arıza hangi forma yazılır?","secenekler":["Uyuşmazlık raporuna","Oda denetleme formuna","Arıza bilgi formuna","Misafir çamaşır işlem formuna"],"dogru":2,"aciklama":"Arıza bilgi formu, temizlik ve kontrol sırasında tespit edilen arızaların yazıldığı formdur.","konu":"1.4.4"},{"id":"kh1-1-s160","tur":"coktan-secmeli","soru":"Kat görevlisi 214 numaralı odada klimanın çalışmadığını fark etti. Arızayı önce kime bildirir?","secenekler":["Kat şefine","Doğrudan genel müdüre","Çamaşırhane sorumlusuna","Bir sonraki gelen konuğa"],"dogru":0,"aciklama":"Arıza kat şefine bildirilir; kat şefi formları toplayıp housekeeper’a iletir, oradan teknik servise gider.","konu":"1.4.4"},{"id":"kh1-1-s161","tur":"coktan-secmeli","soru":"Gün içinde çözülemeyecek arızalı oda neden OOO olarak işlenir?","secenekler":["Odanın yanlışlıkla konuğa satılmasını önlemek için","Odanın temizliğini daha kolay ve hızlı yapmak için","Arıza için konuktan ayrıca ücret alınabilmesi için","Teknik servisin iş yükünü kısa sürede azaltmak için"],"dogru":0,"aciklama":"OOO işlemi, arıza giderilene kadar odayı satış dışı bırakır.","konu":"1.4.4"},{"id":"kh1-1-s162","tur":"coktan-secmeli","soru":"Arıza raporunda aşağıdakilerden hangisi yer alır?","secenekler":["Konuğun çamaşır sayısı ve ücreti","Arıza türü ve arıza durumu","Bulunan eşyanın tarihi ve yeri","Havlu ölçüleri ve renkleri"],"dogru":1,"aciklama":"Arıza raporunda kat, oda numarası, oda durumu, arıza türü ve arıza durumu belirtilir.","konu":"1.4.4"},{"id":"kh1-1-s163","tur":"coktan-secmeli","soru":"Genel alanlarda hangi işin hangi sıklıkla yapılacağını gösteren iş planı hangisidir?","secenekler":["Oda denetleme formu","Haftalık çalışma çizelgesi","Periyodik temizlik planı","Kat ofisi sayım tutanağı"],"dogru":2,"aciklama":"Periyodik temizlik planı temizlenecek oda ve genel alanları ile işlerin sıklığını gösterir. Haftalık çizelge ise personelin çalışma günlerini belirtir.","konu":"1.4.5"},{"id":"kh1-1-s164","tur":"coktan-secmeli","soru":"Pas anahtarı ve kartın imza ile teslim alınıp teslim edilmesi neden önemlidir?","secenekler":["Anahtarın kopyalanması ve çoğaltılması kolaylaşır.","Anahtar yalnızca sabah vardiyasındaki personele verilir.","Anahtar kaybolursa bildirim yapmak gerekmez.","Anahtarın kimde olduğu bilinir ve güvenlik sağlanır."],"dogru":3,"aciklama":"İmza, anahtarın kimde olduğunu gösterir; kayıp durumunda sorumluluk ve işlemler hızla belirlenir.","konu":"1.4.6"},{"id":"kh1-1-s165","tur":"coktan-secmeli","soru":"Bir kat görevlisi pas kartını kaybettiğini fark etti. Ne yapmalıdır?","secenekler":["Gecikmeden bildirip gerekli işlemleri başlatmalıdır.","Kartı bulana kadar durumu kimseye söylememelidir.","Başka bir görevlinin kartını izin almadan kullanmalıdır.","Durumu sonraki vardiyaya bırakıp o zaman bildirmelidir."],"dogru":0,"aciklama":"Kayıp kart güvenlik riski taşıdığı için gecikmeden bildirilir ve gerekli işlemler başlatılır.","konu":"1.4.6"},{"id":"kh1-1-s166","tur":"coktan-secmeli","soru":"Konuk kaynaklı kırık bir bardak ve hasarlı sehpa bulan kat görevlisi hangi forma yazmalıdır?","secenekler":["Arıza bilgi formu ve arıza raporuna","Kayıp eşya ve bulunmuş eşya formuna","Oda bilgi kartı ve denetleme formuna","Oda demirbaş hasar ve kayıp formuna"],"dogru":3,"aciklama":"Konuk tarafından yapıldığı tespit edilen hasar ve demirbaş kaybı hasar ve kayıp formuna yazılır. Arıza bilgi formu teknik arızalar içindir.","konu":"1.4.7"},{"id":"kh1-1-s167","tur":"coktan-secmeli","soru":"Hasarın fark edilir edilmez bildirilmesi neden önemlidir?","secenekler":["Hasarlı eşyanın hemen çöpe atılıp yenisinin konulabilmesi için","Konuk ayrılmadan ön büronun işlem başlatabilmesi için","Konuğun odasının hemen yeniden satışa verilebilmesi için","Raporun daha kısa ve sade hazırlanabilmesi için"],"dogru":1,"aciklama":"Konuk işletmeden ayrılmamışsa ön büro gerekli işlemleri hemen başlatabilir.","konu":"1.4.7"},{"id":"kh1-1-s168","tur":"coktan-secmeli","soru":"Misafir çamaşır işlem formunun asıl amacı nedir?","secenekler":["Çamaşır ücretinin personel maaşından kesilmesi","Konuğun kıyafet beden ve boyutlarını kaydetmek","Çamaşırların karışmadan konuk odasına teslim edilmesi","Çamaşırhanenin vardiya ve çalışma saatlerini belirlemek"],"dogru":2,"aciklama":"Form, çamaşırların yıkanması, temizlenmesi ve ütülenmesi işlemlerini izler ve çamaşırların birbirine karışmasını önler.","konu":"1.4.8"},{"id":"kh1-1-s169","tur":"coktan-secmeli","soru":"Konuk çamaşırlarını yıkatmak istiyor. Formu ve çamaşırı nasıl teslim eder?","secenekler":["Formu resepsiyona bırakıp çamaşırı kat ofisine verir.","Çamaşırı koridora bırakıp formu doldurmayı atlar.","Formu odada bırakıp çamaşırı kendisi çamaşırhaneye götürür.","Formu doldurup imzalar, çamaşırla birlikte torbaya koyar."],"dogru":3,"aciklama":"Doldurulan form çamaşırla birlikte torbaya konur; formun diğer bölümlerini kat görevlisi tamamlar.","konu":"1.4.8"},{"id":"kh1-1-s170","tur":"coktan-secmeli","soru":"Misafir çamaşır işlem formunun nüshaları hangi yerlerde kalır?","secenekler":["Konukta, çamaşırhanede ve kat ofisinde","Ön büroda, muhasebede ve teknik serviste","Genel müdürde, satın almada ve güvenlikte","Yalnızca çamaşırhanede"],"dogru":0,"aciklama":"Form üç nüsha hâlinde düzenlenir; konukta, çamaşırhanede ve kat hizmetleri ofisinde kalır.","konu":"1.4.8"},{"id":"kh1-1-s171","tur":"coktan-secmeli","soru":"Çıkış sonrası odada bir saat bulundu. Kat şefi ne yapar?","secenekler":["Saati kendi dolabında saklar.","Kayıp eşya formunu düzenler.","Formu düzenlemeden saati ön büroya bırakır.","Saati konuğa ulaşmak için posta ile gönderir."],"dogru":1,"aciklama":"Bulunan eşya için kat şefi form hazırlar; eşya değerine göre uygun yerde muhafaza edilir.","konu":"1.4.9"},{"id":"kh1-1-s172","tur":"coktan-secmeli","soru":"Kayıp eşya formunda aşağıdakilerden hangisi yer almaz?","secenekler":["Eşyanın cinsi","Eşyanın bulunduğu yer ve tarih","Odanın arıza durumu","Teslim alan kişi"],"dogru":2,"aciklama":"Formda eşyanın cinsi, yeri, tarihi, durumu ile bulan, teslim eden ve teslim alan kişiler yer alır.","konu":"1.4.9"},{"id":"kh1-1-s173","tur":"coktan-secmeli","soru":"Ön büro görevlisine bir konuk telefonla odasında unuttuğu şemsiyeyi soruyor. Görevli çağrıyı nereye yönlendirir?","secenekler":["Güvenlik ve emniyet birimine","Kat hizmetleri bölümüne","Satın alma ve ambar birimine","Teknik servis bölümüne"],"dogru":1,"aciklama":"Unutulan eşyanın saklanması ve konuğa geri verilmesi kat hizmetleri bölümünün sorumluluğundadır ve işletmenin prosedürüne göre yürütülür.","konu":"1.4.9"},{"id":"kh1-1-s174","tur":"coktan-secmeli","soru":"Kayıp eşyanın değerine göre uygun şart ve ortamda saklanması neden gerekir?","secenekler":["Eşyanın zarar görmesini ve karışmasını önlemek için","Eşyanın daha çabuk el değiştirip satılması için","Formun daha kısa ve sade tutulabilmesi için","Konuğun eşyayı tamamen unutup gitmesini sağlamak için"],"dogru":0,"aciklama":"Değerli eşyanın güvenli saklanması, kayıp ve karışıklığı önler.","konu":"1.4.9"},{"id":"kh1-1-s175","tur":"coktan-secmeli","soru":"Konuk “rahatsız etmeyiniz” kartı astığı için oda temizlenemedi. Konuğu bilgilendirmek için ne hazırlanır?","secenekler":["Arıza bilgi formu ve teknik servis raporu","Kayıp eşya formu ile ilgili bir not","Nedeni ve saati yazılı oda bilgi kartı","Oda denetleme formu ve kontrol listesi"],"dogru":2,"aciklama":"Temizlik hizmeti verilemeyen odadaki konuğu bilgilendirmek için nedenin ve saatin yazıldığı oda bilgi kartı hazırlanır.","konu":"1.4.10"},{"id":"kh1-1-s176","tur":"coktan-secmeli","soru":"Odalar temizlendikten sonra kat şefinin yaptığı son kontrol için hangi form kullanılır?","secenekler":["Oda bilgi kartı","Oda denetleme formu","Oda demirbaş hasar ve kayıp formu","Periyodik temizlik planı"],"dogru":1,"aciklama":"Oda denetleme formu işletmenin temizlik standartlarına göre yapılan son kontrol içindir.","konu":"1.4.11"},{"id":"kh1-1-s177","tur":"coktan-secmeli","soru":"Denetimde kat şefi banyo aynasında leke buldu. Ne yapılır?","secenekler":["Odanın hemen satışa hazır sayılması","Lekenin forma yazılıp odanın olduğu gibi bırakılması","Odanın OOO olarak işlenmesi","Eksik işlemin kat görevlisine tamamlattırılması"],"dogru":3,"aciklama":"Denetimde eksik ya da yapılmamış işlem varsa tamamlanması sağlanır; oda ancak sonra satışa hazır sayılır.","konu":"1.4.11"},{"id":"kh1-1-s178","tur":"coktan-secmeli","soru":"Konuğun odasının değiştirilmesi durumunda hangi form düzenlenir?","secenekler":["Ekstra yatak işlem formu","Oda değişim formu","Oda demirbaş hasar ve kayıp formu","Arıza bilgi formu"],"dogru":1,"aciklama":"Oda değişim formu konuğun odasının değiştirilmesi için düzenlenir.","konu":"1.4.12"},{"id":"kh1-1-s179","tur":"coktan-secmeli","soru":"Personelin haftalık çalışma günlerini ve vardiyalarını hangisi gösterir?","secenekler":["İş tanımı kartı","Personel değerlendirme formu","Haftalık çalışma çizelgesi","Malzeme kullanım talimatı"],"dogru":2,"aciklama":"Haftalık çalışma çizelgesi vardiya ve çalışma günlerini gösterir; iş tanımı kartı ise sorumlulukları anlatır.","konu":"1.4.12"},{"id":"kh1-1-s180","tur":"coktan-secmeli","soru":"Her kat hizmetleri bölümünde aynı form ve belgeler kullanılmaz. Bunun nedeni nedir?","secenekler":["Formlar işletmenin büyüklüğüne ve politikasına göre değişir.","Formlar yalnızca büyük otellerde zorunlu tutulan belgelerdir.","Formlar her yıl bakanlıkça yeniden belirlenir.","Bütün işletmeler her zaman yalnızca iki form kullanır."],"dogru":0,"aciklama":"İşletmelerin büyüklüğü ve yönetim politikaları farklı olduğundan form ihtiyacı da farklıdır.","konu":"1.4.12"},{"id":"kh1-1-s181","tur":"coktan-secmeli","soru":"Koridorda rahatsızlanıp yere yığılan bir konuğu gören oda görevlisi hangi adımı izler?","secenekler":["Konuğu kendi başına kaldırıp dinlenmesi için odasına götürür","Teknik servise haber verip olayı vardiya defterine yazar","112 Acil Çağrı Merkezi’ni arayıp amirine haber verir","Konuğun yakınlarını arayıp onların gelmesini bekler"],"dogru":2,"aciklama":"Acil durumda önce can güvenliği için tek numara olan 112 aranır, ardından amire haber verilir. Konuğu tek başına taşımak ya da yakınlarını beklemek müdahaleyi geciktirir.","konu":"1.4.12"},{"id":"kh1-1-s182","tur":"dogru-yanlis","soru":"Dezenfektan bir temizlik maddesidir ve kirli yüzeye doğrudan uygulanabilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Dezenfektan temizlik maddesi değildir; önce kir temizlenir, sonra dezenfektan uygulanır.","konu":"1.3.3"},{"id":"kh1-1-s183","tur":"dogru-yanlis","soru":"Siyah ped, cilalama makinesi pedleri içinde en sert ve aşındırıcı olanıdır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Siyah ped cila sökme ve yaş yüzeylerde etkin temizlik için kullanılır ve en sert pedlerdendir.","konu":"1.3.5"},{"id":"kh1-1-s184","tur":"dogru-yanlis","soru":"Ahşap zeminlerde temel temizlik maddeleri güvenle kullanılabilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Temel temizlik maddeleri ahşap zeminde kesinlikle kullanılmaz.","konu":"1.3.11"},{"id":"kh1-1-s185","tur":"dogru-yanlis","soru":"Kayıp eşya formunun bir nüshası ön büroya gönderilir, diğer nüsha kat hizmetleri ofisinde kalır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Form kat şefi tarafından iki nüsha hazırlanır; biri ön büroya, diğeri kat ofisine gider.","konu":"1.4.9"},{"id":"kh1-1-s186","tur":"dogru-yanlis","soru":"Kat görevlisi, raporunu sabah odalara gitmeden önce imza karşılığı teslim alır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Rapor sabah imza karşılığı alınır, gün sonunda doldurularak yine imza karşılığı teslim edilir.","konu":"1.4.2"},{"id":"kh1-1-s187","tur":"dogru-yanlis","soru":"Konuk çamaşırlarının karışmaması için işlem formu çamaşırla birlikte kirli çamaşır torbasına konur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Form çamaşırın sahibini ve istenen işlemleri gösterir; torbada birlikte gönderilir.","konu":"1.4.8"},{"id":"kh1-1-s190","tur":"dogru-yanlis","soru":"OOO olarak işlenmiş bir oda satışa açıktır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"OOO arıza nedeniyle satışa kapatılmış odadır; arıza giderilene kadar satılmaz.","konu":"1.4.4"},{"id":"kh1-1-s191","tur":"dogru-yanlis","soru":"Hasar fark edilir edilmez bildirilirse, konuk işletmeden ayrılmadan ön büro gerekli işlemleri başlatabilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Konuk ayrılmamışsa ön büro hemen işlem yapabilir; geç bildirim bunu zorlaştırır.","konu":"1.4.7"},{"id":"kh1-1-s192","tur":"senaryo","durum":"Sabah 09.30’da kat görevlisisin. Ön büro raporunda 1103 numaralı oda boş temiz görünüyor; ancak kapıyı çalıp cevap alamayınca içeri giriyorsun ve açık bir bavul ile kişisel eşyalar görüyorsun.","soru":"Ne yaparsın?","secenekler":["Odayı gördüğün gibi işaretler, kat şefine bildirip uyuşmazlık raporunu hazırlatırsın.","Ön büro raporuna güvenip odanın boş olduğunu kabul eder, hiç beklemeden temizliğe başlarsın.","Konuğun eşyalarını toplayıp odadaki karışıklığı gidermek için başka bir odaya taşırsın.","Farkı kimseye söylemeden raporu ön büronun yazdığı gibi bırakır, işine devam edersin."],"dogru":0,"aciklama":"Raporlar arasındaki fark uyuşmazlık raporuyla belirtilir ve nedeni araştırılır. Odayı gördüğün duruma göre işaretlemek ve kat şefini bilgilendirmek doğru adımdır; eşyaya dokunmak ya da sessiz kalmak konuk ve işletme için risk taşır.","konu":"1.4.3"},{"id":"kh1-1-s193","tur":"senaryo","durum":"Banyoda kireç ve sabun lekesini bir türlü çıkaramıyorsun. Kat arabasında hem çamaşır suyu hem de tuz ruhu bulunuyor. Kat şefin başka katta.","soru":"Ne yaparsın?","secenekler":["Daha güçlü sonuç almak için iki ürünü aynı kovada karıştırır, lekeye birlikte uygularsın.","Ürünü bezle uygulamak yerine doğrudan lekenin üzerine bol miktarda döküp beklersin.","Ürünleri karıştırmaz, talimatı okuyup yüzeye uygun tek ürünü kullanırsın.","Etiketi okumadan uygun gördüğün ürünü hemen kullanırsın."],"dogru":2,"aciklama":"Temizlik ürünleri birbirine karıştırılmaz; çamaşır suyu ile tuz ruhu zehirli gaz oluşturur. Talimata uymak ve yüzeye uygun ürünü seçmek hem güvenliği hem sonucu korur.","konu":"1.3.11"},{"id":"kh1-1-s194","tur":"senaryo","durum":"Akşam 17.00’de çıkış yapan konuğun odasını hazırlarken yatağın altında bir cüzdan buluyorsun. Konuk çoktan ayrılmış.","soru":"Ne yaparsın?","secenekler":["Cüzdanı kat şefine bildirir, kayıp eşya formunun düzenlenmesini sağlarsın.","Cüzdanı herhangi bir forma yazmadan ön büro masasına bırakıp temizliğe devam edersin.","Konuk geri dönüp isteyene kadar cüzdanı cebinde ya da kat arabasında taşırsın.","Bir gün içinde sahibi başvurmazsa cüzdanı kendin saklamaya karar verirsin."],"dogru":0,"aciklama":"Kayıp eşya işlemleri kat hizmetlerinin sorumluluğundadır ve form düzenlenerek yürütülür. Form eşyanın kimden kime geçtiğini gösterir; yanında taşımak ya da formsuz teslim etmek kayıt dışı kalmasına yol açar.","konu":"1.4.9"},{"id":"kh1-1-s195","tur":"senaryo","durum":"Öğleden sonra 14.00’te çıkış yapılmış bir odada televizyon kumandasının kırık olduğunu ve masa üzerinde hasar bulunduğunu görüyorsun. Konuk hâlâ lobide oturuyor.","soru":"Ne yaparsın?","secenekler":["Konuğa yaklaşıp hasarın bedelini ödemesini doğrudan kendin istersin.","Hasarı kendine not edip vardiyanın sonunda amirine söylersin.","Kırık kumandayı sessizce aynı modelle değiştirir, hasarı kimseye söylemezsin.","Hasarı hasar ve kayıp formuna yazar, kat şefine hemen bildirirsin."],"dogru":3,"aciklama":"Hasar fark edilir edilmez forma yazılıp kat şefi aracılığıyla bildirilirse, konuk ayrılmadan ön büro gerekli işlemleri başlatabilir. Bedeli sormak ön büronun işidir; gecikmek ya da gizlemek işlemi zorlaştırır.","konu":"1.4.7"},{"id":"kh1-1-s196","tur":"senaryo","durum":"Sabah 11.00’de oda temizliğinde banyo giderinin tamamen tıkandığını ve suyun geri geldiğini görüyorsun. Odanın akşam konuğu var.","soru":"Ne yaparsın?","secenekler":["Odayı her zamanki gibi hazırlayıp arızayı konuğun kendisinin fark etmesine bırakırsın.","Arıza formuna yazıp kat şefine bildirirsin; çözülmezse OOO işlenmesini sağlarsın.","Gideri kendin güçlü bir kimyasalla açmayı deneyip odayı hazırlarsın.","Ön büroya ve kat şefine haber vermeden odanın kapısını kilitlersin."],"dogru":1,"aciklama":"Arıza bilgi formu ve kat şefi aracılığıyla bildirim zinciri işletilir; çözülemeyen arızada oda OOO olarak işlenip satışa kapatılır. Bildirmeden odayı kilitlemek ön büronun odayı satmasına yol açabilir.","konu":"1.4.4"},{"id":"kh1-1-s197","tur":"senaryo","durum":"Sabah 10.30’da 412 numaralı odanın kapı kolunda “Rahatsız Etmeyin” kartı asılı. Çıkış saati geçmedi, ama oda listende bu oda var ve arkadaşların odaları bitirmek üzere.","soru":"Ne yaparsın?","secenekler":["Kapıyı bir kez çalar, cevap gelmezse kartı yok sayıp odayı hızlıca hazırlamaya başlarsın.","Kartı gördüğün için girmez, odayı listede işaretleyip kat şefine bildirirsin.","Anahtarla kapıyı azıcık aralayıp konuğun içeride olup olmadığına bakarsın.","Kapının önüne “temizlik bekliyor” notu bırakıp odayı akşama kadar unutursun."],"dogru":1,"aciklama":"DND, odaya hiçbir şekilde girilmemesi demektir; doğru davranış girmeden durumu bildirmektir. Çalıp girmek ya da kapıyı aralamak bu kuralı çiğner, notla odayı unutmak ise odanın takibini bırakır.","konu":"1.2.4"},{"id":"kh1-1-s198","tur":"senaryo","durum":"Öğleden sonra 15.00’te kat ofisinde cam temizleyicisinin sprey şişesi boşalmış. Dolapta aynı ürünün büyük bidonu duruyor ve yanında boş bir su şişesi var. Arabanı çabuk hazırlaman gerekiyor.","soru":"Ne yaparsın?","secenekler":["Bidondaki ürünü boş su şişesine doldurur, şişeyi hemen arabaya koyarsın.","Büyük bidonu olduğu gibi arabaya yükler, odalarda doğrudan cama dökersin.","Ürünü kendi sprey şişesine aktarır, üzerine adını etiketle yazarsın.","Boş su şişesine ürünü koyar, etiket yapıştırmadan aynı rafta bırakırsın."],"dogru":2,"aciklama":"Madde başka bir kaba konulacaksa üzerine ne olduğu etiketle yazılır. Etiketsiz su şişesi karışıklık yaratır, yüzeye doğrudan dökmek de yanlıştır.","konu":"1.3.11"},{"id":"kh1-1-s199","tur":"senaryo","durum":"Sabah 11.15’te banyo temizliği yaparken yanındaki arkadaşının elindeki sprey fırlıyor ve ürün gözüne sıçrıyor. Arkadaşın gözünü ovuşturuyor, kat şefi de o sırada başka katta.","soru":"Ne yaparsın?","secenekler":["Arkadaşından gözünü kuru bir havluyla silmesini isteyip geçmesini beklersin.","Arkadaşına durumun önemsiz olduğunu söyleyip banyoyu bitirmesini istersin.","Arkadaşına gözünü ovuşturmamasını söyleyip aynı spreyle yüzünü temizlemesini istersin.","Arkadaşını hemen lavaboya götürür, gözünü bol suyla yıkamasını sağlarsın."],"dogru":3,"aciklama":"Temizlik maddesi göze ya da tene sıçradığında o bölge bol suyla yıkanır. Silmek, beklemek ya da işe devam etmek zararı sürdürür.","konu":"1.3.11"}],"siralamalar":[{"id":"kh1-1-r01","konu":"1.1","baslik":"Kat ofisini düzenleme","yonerge":"Atölyede kat ofisini düzenleyen öğrenci olarak adımları sıraya koy.","adimlar":["Kat ofisini havalandır, genel temizliğini yap ve rafları nemli bezle sil.","Temiz yatak takımı, çarşaf, havlu, buklet malzemeleri, form ve magazinleri raflara yerleştir.","Kimyasalları kapalı bölüme koy, uyarı levhalarını kontrol et; yedek sarf malzemelerini, temizlik gereçlerini, elektrikli ekipmanı ve kat arabalarını yerlerine yerleştir.","Ofis hazır olduktan sonra kapıyı kapat."],"aciklama":"Önce ofis temizlenir, çünkü temiz olmayan rafa konan malzeme kirlenir. Ardından temiz tekstil ve buklet yerleştirilir, kalan malzeme ve ekipman yerine konur; kapatma hazırlık bittikten sonraya kalır."},{"id":"kh1-1-r02","konu":"1.2.1","baslik":"Kat arabasını hazırlama","yonerge":"Atölyede kat arabasını hazırlayan öğrenci olarak adımları sıraya koy.","adimlar":["İş sağlığı ve güvenliği önlemlerini alıp kat arabasının temizliğini yap.","Kat görevlisi raporundan oda ve yatak sayısını kontrol et, odaların durumunu not al.","Oda ve yatak sayısına göre temiz tekstili ve buklet setlerini yerleştir; deterjan, kimyasal, bez ve fırçaları arabanın kimyasal bölümüne koy.","Yedek torbaları, kâğıtları ve mopu ekleyip arabayı ofiste uygun yere çek."],"aciklama":"Önce güvenlik önlemi alınıp araba temizlenir; sayı ancak rapordan öğrenilince tekstil ve buklet hesaplanır, kimyasal da ayrı bölmeye konur. Son kontrol en sonda yapılır."},{"id":"kh1-1-r03","konu":"1.4.1","baslik":"Günlük raporun hazırlanması","yonerge":"Atölyede housekeeping raporunu hazırlayan öğrenci olarak adımları günün ilk raporundan ikinci rapora kadar sıraya koy.","adimlar":["Ön bürodan günlük oda durum raporunu al.","Raporu inceleyip kat şeflerine dağıtarak odaların kontrolünü iste.","Kat şefiyle rapordaki bilgileri kontrol edip kat raporunu hazırla.","Hazırlanan raporu incelenmesi için housekeeper’a ilet.","Gelen kontrol formlarına göre housekeeping raporunu hazırla.","Raporu ön büronun raporuyla karşılaştırıp mutabakat sağla.","Fark varsa uyuşmazlık raporu düzenleyip ön büroya bildir; housekeeping raporunun bir örneğini ön büroya, bir örneğini muhasebeye gönder.","Öğleden sonra bütün odaların işlemleri bitince housekeeping raporunu yeniden hazırlayıp bir örneğini ön büroya gönder."],"aciklama":"Önce bilgi alınır ve kontrol edilir, sonra rapor hazırlanıp ön büroyla karşılaştırılır; fark varsa uyuşmazlık raporu düzenlenir. Gün içinde işlemler bitince ikinci rapor hazırlanır ve ön büroya gönderilir."},{"id":"kh1-1-r04","konu":"1.4.9","baslik":"Kayıp eşya işlemi","yonerge":"Odada unutulmuş değerli bir eşya buldun. İşlem adımlarını sıraya koy.","adimlar":["Odada unutulan değerli eşyayı fark et.","Bulduğun değerli eşyayı kat şefine bildir.","Kat şefinin kayıp eşya formunu düzenlemesini sağla.","Eşyanın cinsini, yerini, bulanı ve durumunu forma yaz.","Formun kat şefiyle birlikte imza altına alınmasını sağla.","Düzenlenen formu ve eşyayı housekeeper’a ilet.","Housekeeper’ın formu incelemesini ve ön büroya bilgi vermesini sağla."],"aciklama":"Eşya önce bildirilir, sonra form düzenlenip doldurulur ve imzalanır; ancak kayıt tamamlandıktan sonra housekeeper’a ve ön büroya aktarılır."},{"id":"kh1-1-r05","konu":"1.4.4","baslik":"Arıza kaydı","yonerge":"Odada bozuk bir tesisat fark ettin. Arıza kayıt adımlarını sıraya koy.","adimlar":["Kontrol sırasında odadaki arızayı tespit et.","Arızayı kat şefine ilet.","Kat şefinin arıza formunu hazırlamasını sağla.","Forma arızayla ilgili ayrıntıları yaz.","Arızayı teknik servise ve housekeeper’a ilet.","Teknik servisin tamiri yapmasını ve sonucu kat hizmetlerine bildirmesini sağla."],"aciklama":"Arıza önce tespit edilip amire bildirilir, form hazırlanıp doldurulur, sonra teknik servise iletilir; tamir sonucu en son kat hizmetlerine geri bildirilir."}],"acikSorular":[{"id":"kh1-1-y01","konu":"1.2.1","soru":"Oda görevlisi Murat, vardiyaya başlarken kat arabasına yalnızca altı havlu alıp odalara çıkıyor. Murat’ın hatasını belirtiniz, arabanın eksik hazırlanmasının iş akışında yaratacağı iki sonucu yazınız ve arabaya konulacak temiz çamaşırın nasıl hesaplanması gerektiğini açıklayınız.","olcut":[{"metin":"Murat’ın hatasını, kat arabasını yeterli malzemeyle hazırlamadan (yalnızca altı havluyla) yola çıkması olarak belirtir.","puan":20},{"metin":"Eksik hazırlığın birinci sonucunu (zaman kaybı: havlu bitince ofise tekrar dönmek) yazar.","puan":20},{"metin":"Eksik hazırlığın ikinci sonucunu (enerji kaybı ve yorgunluk ya da planlanan odaların bir kısmının vardiya içinde temizlenememesi) yazar.","puan":20},{"metin":"Temiz çamaşırın temizlenecek oda ve yatak sayısına göre (rapordaki sayılara bakarak) hesaplanması gerektiğini, nedenini de belirterek açıklar (ne eksik ne fazla yüklenir).","puan":40}],"ornek":"Murat’ın hatası, arabayı rapordaki oda ve yatak sayısına göre hazırlamadan yalnızca altı havluyla yola çıkmasıdır. Havlusu bitince ofise tekrar dönmek zorunda kalır ve zaman kaybeder. Bu gidiş gelişler onu yorar, vardiya içinde planladığı odaların bir kısmını da temizleyemez. Bunu önlemek için temiz çarşaf, yastık kılıfı ve havlu, rapordaki oda ve yatak sayısına göre hesaplanmalıdır; böylece araba ne eksik ne de fazla yüklenir.","ipucu":"Arabaya konulacak malzemenin miktarını neye bakarak belirlemeniz gerektiğini düşünün."},{"id":"kh1-1-y02","konu":"1.3.11","soru":"Yeni bir görevli, banyoyu daha çabuk temizlemek için iki farklı temizlik maddesini aynı kovaya döküyor ve sıvı maddeyi talimattaki orandan fazla ekliyor. Bu iki davranışın neden yanlış olduğunu yazınız ve doğru uygulamanın ne olması gerektiğini açıklayınız.","olcut":[{"metin":"Farklı temizlik maddelerinin birbirine karıştırılmaması gerektiğini ve nedenini (tepkimeye girip göze ve solunum sistemine zarar vermesi, zehirli gaz oluşturabilmesi) belirtir.","puan":20},{"metin":"Sıvı maddenin kullanma talimatındaki oranda suyla karıştırılması gerektiğini belirtir.","puan":20},{"metin":"Fazla madde eklemenin sonucunu örnek verir (yüzeye zarar, daha çok durulama, ekonomik zarar).","puan":20},{"metin":"Doğru uygulamayı açıklar: maddeyi kullanmadan önce kullanma talimatını okuyup ona uymak, maddeyi üretildiği yüzeye ve amacına uygun kullanmak; talimatın oranı, kullanım yerini ve güvenlik önlemlerini gösterdiğini belirtir.","puan":40}],"ornek":"Farklı temizlik maddeleri birbirine karıştırılmaz; çünkü ürünler tepkimeye girerek göze ve solunum sistemine zarar verir, çamaşır suyu ile tuz ruhu karışınca zehirli gaz bile oluşur. Sıvı madde de kullanma talimatında yazan oranda suyla karıştırılır. Fazla madde eklenirse yüzey zarar görür, daha çok durulama gerekir ve işletme boşuna para harcar. Doğru uygulama, maddeyi kullanmadan önce talimatı okuyup ona uymaktır; çünkü talimat kullanılacak oranı, kullanım yerini ve güvenlik önlemlerini gösterir.","ipucu":"Etiketteki bilgilerin kimin, hangi amaçla yazdığını düşünün."}]},{"ders":"kat-hizmetleri-10","sinif":10,"unite":2,"baslik":"Oda Temizlik İşlemleri","onay":true,"kazanimlar":["Ulusal standartlara ve işletme prosedürüne uygun olarak konuk odası giriş işlemlerini yapar.","İş sağlığı ve güvenliği tedbirlerini alarak ulusal standartlara ve işletme prosedürüne uygun olarak odayı havalandırır.","İş sağlığı ve güvenliği standartlarına uygun olarak odadan çöpleri toplar.","İş sağlığı ve güvenliği standartlarına uygun olarak odadaki arızalı eşyaları tespit eder.","İş sağlığı ve güvenliği standartlarına uygun olarak mini buzdolabını temizler.","İş sağlığı ve güvenliği standartlarına uygun olarak balkon temizliğini yapar.","Ulusal standartlara ve işletme prosedürüne uygun olarak odaya buklet malzemelerini yerleştirir."],"soz":"Konuk odaya döndüğünde fark etmediği her temiz ayrıntı, kat görevlisinin sessiz imzasıdır.","dersler":[{"baslik":"Çalışmaya Başlamadan Önce Kendini Koru","ilk":"kh1-2-001"},{"baslik":"Kat Şefi Kime Hangi Odayı Verir?","ilk":"kh1-2-004"},{"baslik":"Güne Hazır Mısın?","ilk":"kh1-2-010"},{"baslik":"Rapor Neden İki Kez Yazılır?","ilk":"kh1-2-015"},{"baslik":"Üç Harfle Oda Anlatmak","ilk":"kh1-2-021"},{"baslik":"Raporda Dört Gizli İşaret","ilk":"kh1-2-026"},{"baslik":"Anahtarlar Kimde Durur?","ilk":"kh1-2-030"},{"baslik":"Kayıt Defteri Yalan Söylemez","ilk":"kh1-2-035"},{"baslik":"Kapı Çalmadan Girilmez","ilk":"kh1-2-040"},{"baslik":"Kapının Ardında Kim Var?","ilk":"kh1-2-042"},{"baslik":"Konuk Gitti, Geride Ne Kaldı?","ilk":"kh1-2-046"},{"baslik":"Kapı Kolundaki Sessiz Mesaj","ilk":"kh1-2-049"},{"baslik":"Rahatsız Etmeyin Denince","ilk":"kh1-2-053"},{"baslik":"Kapı Günlerce Asılı Kalırsa","ilk":"kh1-2-056"},{"baslik":"Pencereyi Açmak da Bir Beceridir","ilk":"kh1-2-059"},{"baslik":"Rüzgâr mı, Yağmur mu?","ilk":"kh1-2-063"},{"baslik":"Çöp mü, Atık mı?","ilk":"kh1-2-066"},{"baslik":"Çöpten Kaynak Çıkar","ilk":"kh1-2-070"},{"baslik":"Eldiven Takmadan Çöpe Dokunma","ilk":"kh1-2-073"},{"baslik":"Temizlikten Önce Kim Bakar?","ilk":"kh1-2-151"},{"baslik":"Telefon, Kasa, Perde: Hepsi Kontrolde","ilk":"kh1-2-156"},{"baslik":"Arıza Kâğıda Nasıl Dökülür?","ilk":"kh1-2-159"},{"baslik":"Arıza Çözülene Kadar","ilk":"kh1-2-166"},{"baslik":"Kırılan Sehpanın Hesabı","ilk":"kh1-2-170"},{"baslik":"Sistem Arızayı Görüyor","ilk":"kh1-2-172"},{"baslik":"Odanın Küçük Buzdolabı","ilk":"kh1-2-174"},{"baslik":"Silmeden Önce Bak","ilk":"kh1-2-177"},{"baslik":"Fiş, Çek, İmza","ilk":"kh1-2-180"},{"baslik":"Çıkıştan Bir Gün Önce","ilk":"kh1-2-183"},{"baslik":"Manzaranın Vitrini","ilk":"kh1-2-185"},{"baslik":"Eşyaya Dokunma, Tepeden İndir","ilk":"kh1-2-189"},{"baslik":"Sallanan Korkuluk Kimin Sorunu?","ilk":"kh1-2-192"},{"baslik":"Zeminden Giderine","ilk":"kh1-2-195"},{"baslik":"Toz Nereden Başlar?","ilk":"kh1-2-199"},{"baslik":"Fişi Çek, Bezi Sık","ilk":"kh1-2-203"},{"baslik":"Kırmızı Bez Nereye Gider?","ilk":"kh1-2-206"},{"baslik":"Bulaşmayı Durdur, Sırayı Kur","ilk":"kh1-2-210"},{"baslik":"Odada Seni Bekleyenler","ilk":"kh1-2-213"},{"baslik":"Küçük Hediyelerin Büyük Etkisi","ilk":"kh1-2-221"},{"baslik":"Ferahlık ve Aile Seti","ilk":"kh1-2-225"},{"baslik":"Çay Hazır, Özel Konuk Unutulmaz","ilk":"kh1-2-229"},{"baslik":"Her Şeyin Bir Yeri Var","ilk":"kh1-2-232"},{"baslik":"Zemin Konuşur","ilk":"kh1-2-235"},{"baslik":"Süpürgenin Arkasındaki Teknik","ilk":"kh1-2-239"},{"baslik":"Son Bakış","ilk":"kh1-2-243"},{"baslik":"Konuğa Nasıl Davranılır?","ilk":"kh1-2-246"},{"baslik":"Sessiz Hizmet","ilk":"kh1-2-250"},{"baslik":"Koridorun Kuralı","ilk":"kh1-2-253"}],"kavramlar":[{"id":"kh1-2-001","konu":"2.1","terim":"Oda temizliğinde iş sağlığı ve güvenliği","ingilizce":"Occupational health and safety","tanim":"Çalışanın sağlığını ve iş güvenliğini korumak için işin her aşamasında alınan önlemlerin bütünüdür.","ornek":"Sabah 08.45’te oda görevlisi Elif, 312 numaralı odanın çöplerini toplamadan önce eldivenlerini ve maskesini takar, eğilmeden çalışabilmek için kat arabasını yatağa yakın çeker.","sektor":"Çöp toplama, balkon ve toz alma gibi işlerde eldiven ve maske işin başında takılır. Kendini koruyan görevli hem hasta kalmaz hem konuğa güvenli bir oda teslim eder.","iliskili":["kh1-2-002","kh1-2-073"],"kontrol":null},{"id":"kh1-2-002","konu":"2.1","terim":"Ergonomi","ingilizce":"Ergonomics","tanim":"İnsanın, makinenin ve çevrenin bir arada uyumlu ve verimli çalışmasını inceleyen, işi çalışana uygun hâle getirmeyi amaçlayan bilim dalıdır.","ornek":"Öğle arasında oda görevlisi Selin, kat arabasının üst rafına sürekli uzandığı için sırtından yakınır; kat şefi Hülya en çok kullanılan malzemeleri el hizasındaki rafa taşır.","sektor":"Ergonominin amacı verimi artırmak, gereksiz ve aşırı zorlanmayı önlemek, işi planlı düzenlemek, gereksiz hareketleri azaltmak ve insan, makine ve çevre uyumunu sağlamaktır. Doğru düzen hem yorgunluğu hem iş kazasını azaltır.","iliskili":["kh1-2-001","kh1-2-003"],"kontrol":null},{"id":"kh1-2-003","konu":"2.1","terim":"Kat arabasının oda önündeki yerleşimi","ingilizce":"Housekeeping trolley positioning","tanim":"Çalışılacak odaya en yakın yere, koridordaki geçişi engellemeyecek biçimde arabanın bırakılmasıdır.","ornek":"Öğleden sonra 3. katın dar koridorunda oda görevlisi Murat, arabasını 305 numaralı kapının yanında duvara paralel bırakır; konuklar ve bavullu bellboy rahatça geçer.","sektor":"Araba yakın olursa görevli malzeme için gereksiz yürümez; geçişi kapatmayan araba da konuğun ve personelin güvenliğini korur. Araba, görevlinin bütün malzemesini taşıdığı için odaya yakın olması iş yükünü azaltır.","iliskili":["kh1-2-002","kh1-2-040"],"kontrol":null,"gorsel":"t12b-koridor-kat-arabasi"},{"id":"kh1-2-004","konu":"2.1.1","terim":"İş planı","ingilizce":"Work plan","tanim":"Belirlenen hedeflere ulaşmak için eldeki kaynaklarla yapılacak işlerin önceden programlanmasıdır.","ornek":"Pazartesi sabahı 07.30’da kat şefi Hülya, bugün çok sayıda odanın çıkış yapacağını görür ve ekibine fazladan bir oda görevlisi ayırır.","sektor":"İyi bir iş planı için işletmenin kapasitesi, oda sayısı ve tipleri, iş yoğunluğu, iş sağlığı ve güvenliği kuralları, personel ihtiyacı, standart süreler, malzeme ve makine ihtiyacı ile ayrılan bütçe bilinmelidir.","iliskili":["kh1-2-005","kh1-2-006"],"kontrol":null},{"id":"kh1-2-005","konu":"2.1.1","terim":"Oda dağılımı","ingilizce":"Room assignment","tanim":"Kat şefinin vardiya başında her oda görevlisine hangi odaları temizleyeceğini bildirdiği iş listesidir.","ornek":"Sabah 08.00’de, meeting’den sonra kat şefi Hülya, Selin’e 301’den 308’e kadar olan odaları verir; listede üç odanın çıkış yaptığı, birinin de erişilebilir oda olduğu yazar.","sektor":"Dağılım yapılırken odanın durumu (giriş, çıkış, arızalı, erişilebilir), oda tipi ve yatak sayısı dikkate alınır; çünkü her odanın temizlik süresi bunlara göre değişir.","iliskili":["kh1-2-004","kh1-2-007","kh1-2-009"],"kontrol":null},{"id":"kh1-2-006","konu":"2.1.1","terim":"Giriş yapılmış oda","ingilizce":"Occupied (checked-in) room","tanim":"Konuğun otele girişinin yapıldığı, kayıt işlemi tamamlanmış odadır.","ornek":"Akşamüstü 17.00’de 214 numaralı oda bir aile için kayıt edilir; ertesi sabah kat şefi bu odayı dağılımda “konuk içeride” diye ayrı değerlendirir.","sektor":"Oda dağılımında giriş yapılmış odanın durumu bilinmelidir; temizlik süresi ve konuğun rahatsız edilmemesi buna göre planlanır.","iliskili":["kh1-2-005","kh1-2-023"],"kontrol":null,"gorsel":"h3b-valizli-oda"},{"id":"kh1-2-007","konu":"2.1.1","terim":"Çıkış yapılmış oda","ingilizce":"Check-out room","tanim":"Konuğun hesabını kapatıp otelden ayrıldığı, temizlenmeyi bekleyen odadır.","ornek":"Sabah 11.00’de 410 numaralı odanın konuğu resepsiyonda hesabını kapatır; kat hizmetleri bu odayı yeni konuk için hazırlanacaklar listesine alır.","sektor":"Çıkış yapılmış odalar dolu ve boş odalardan önce ele alınır; çünkü ön büro odayı yeniden satmak için temiz ve kontrollü olmasını bekler. VIP ve “odamı hemen temizleyin” odaları ise bunların da önüne geçer.","iliskili":["kh1-2-005","kh1-2-022"],"kontrol":null},{"id":"kh1-2-008","konu":"2.1.1","terim":"Arızalı oda","ingilizce":"Out-of-order room (OOO)","tanim":"Bir bozukluk nedeniyle konuğa verilemeyen odadır.","ornek":"Sabah 09.15’te 507 numaralı odada klima çalışmaz; oda görevlisi durumu kat şefine bildirir, oda arıza giderilene kadar OOO olarak işaretlenir.","sektor":"Arızası süren odalar ön büroya bildirilerek satışa kapatılır; arıza giderilince oda temizlenip yeniden satışa açılır.","iliskili":["kh1-2-005","kh1-2-022","kh1-2-165"],"kontrol":null},{"id":"kh1-2-009","konu":"2.1.1","terim":"Erişilebilir oda","ingilizce":"Accessible room","tanim":"Hareket kısıtı olan konukların rahat ve güvenle kullanabileceği biçimde düzenlenmiş odadır.","ornek":"Zemin kattaki 108 numaralı oda, tekerlekli sandalye kullanan bir konuk için hazırlanır; oda görevlisi eşyaları yolu daraltmayacak biçimde yerleştirir.","sektor":"Eski kaynaklarda “engelli odası” diye de geçer; bugün saygılı ve doğru kullanım erişilebilir oda şeklindedir. Kat şefi dağılımda bu odayı ayrıca düşünür.","iliskili":["kh1-2-005"],"kontrol":null,"gorsel":"t12b-erisilebilir-banyo"},{"id":"kh1-2-010","konu":"2.1.1","terim":"Kişisel bakım ve hijyen","ingilizce":"Personal grooming and hygiene","tanim":"Çalışanın işe başlamadan önce kendisini temiz, bakımlı ve hijyen kurallarına uygun hâle getirmesidir.","ornek":"Sabah 07.40’ta soyunma odasında Selin, kolundaki bileziği ve yüzüğünü çıkarıp dolabına koyar, ellerini yıkar ve üniformasını giyer.","sektor":"Oda görevlisi konuğun en özel alanına girer; temiz ve bakımlı görünmek güven verir. Mücevher ve takılar iş başlamadan çıkarılır.","iliskili":["kh1-2-011","kh1-2-012"],"kontrol":null,"gorsel":"t10b-el-yikama"},{"id":"kh1-2-011","konu":"2.1.1","terim":"Üniforma ve isimlik","ingilizce":"Uniform and name badge","tanim":"İşletmenin belirlediği iş kıyafetinin giyilmesi ve çalışanın adını gösteren kartın üniformaya takılmasıdır.","ornek":"Sabah toplantısına gelen Murat, isimliğini üniformasının göğsüne takmayı unutmuştur; kat şefi daha kapıdan girmeden onu uyarır.","sektor":"Üniforma konuğa kat hizmetleri personelini tanıtır, isimlik ise konuğun görevliye adıyla seslenmesini sağlar.","iliskili":["kh1-2-010","kh1-2-012","kh1-2-258"],"kontrol":null,"gorsel":"h3a-on-buro-personelinin-kisisel"},{"id":"kh1-2-258","konu":"2.1.2","terim":"Kat hizmetleri personelinin nitelikleri","ingilizce":"Qualities of housekeeping staff","tanim":"Mesleki eğitim almış, yabancı dil bilen, araç gereci doğru kullanan, sorumluluk sahibi, çözüm odaklı, ekibiyle uyumlu, temiz ve bakımlı olmak gibi bir kat hizmetleri çalışanından beklenen özelliklerdir.","ornek":"Kat şefi Hülya, yeni gelen oda görevlisinin hem Almanca bilmesini hem de elektrikli süpürgeyi doğru kullanabilmesini işe alımda artı sayar.","sektor":"Kat görevlisi konuğun en özel alanına girdiği için güven veren, düzenli ve görgü kurallarını bilen biri olmalıdır.","iliskili":["kh1-2-010","kh1-2-011"],"kontrol":null},{"id":"kh1-2-012","konu":"2.1.1","terim":"Meeting","ingilizce":"Daily briefing","tanim":"Kat hizmetleri müdürünün her sabah işe başlamadan önce personelle yaptığı günlük toplantıdır.","ornek":"Sabah 07.50’de kat hizmetleri müdürü ekibi toplar; personelin bakımı kontrol edilir, kat şefi dünkü şikâyet raporunu okur, VIP konuklar ve günün iş akışı duyurulur.","sektor":"Toplantıda kişisel bakım kontrol edilir, konuk geri bildirimleri ve şikâyet raporları okunur, memnun konuğun teşekkürü iletilir, problemli ve VIP konuklar bildirilir, iş akışı anlatılır ve çalışanların istekleri dinlenir. Sonra herkes iş planını alıp görevine gider.","iliskili":["kh1-2-013","kh1-2-014","kh1-2-010"],"kontrol":null,"gorsel":"f3d-otel-toplanti-odasi"},{"id":"kh1-2-013","konu":"2.1.1","terim":"Remark","ingilizce":"Guest remark","tanim":"Problemli ya da özel hassasiyeti olan bir konuk hakkında, bir sonraki gelişinde daha dikkatli davranılması için tutulan nottur.","ornek":"Geçen ay yastığından rahatsız olan bir konuk yeniden rezervasyon yaptırınca meeting’de adı okunur; oda görevlisi ona özel yastık seçeneğini hazır bulundurur.","sektor":"Remark sayesinde aynı hata tekrarlanmaz ve konuk, otelin kendisini hatırladığını görür. Konuğun hassasiyetleriyle ilgili gerekli önlemler önceden alınır.","iliskili":["kh1-2-012"],"kontrol":null},{"id":"kh1-2-014","konu":"2.1.1","terim":"Görev talimatı alma","ingilizce":"Receiving daily instructions","tanim":"Oda görevlisinin vardiya başında iş programını, oda durum raporunu ve pas anahtarını teslim alarak çalışmaya hazırlanmasıdır.","ornek":"Meeting’den sonra Selin, kat şefinden günlük iş programını öğrenir, sorumlu olduğu odaların raporunu alır ve bölüm pas anahtarını imza karşılığı teslim alır.","sektor":"Doğru sırayla alınan talimat, görevlinin hangi odada ne yapacağını bilerek işe başlamasını sağlar; rapor ve anahtar eksikse iş daha ilk saatte aksar.","iliskili":["kh1-2-012","kh1-2-015","kh1-2-030"],"kontrol":null},{"id":"kh1-2-015","konu":"2.1.1","terim":"Oda görevlisi durum raporu","ingilizce":"Room attendant’s status report","tanim":"Sorumlu olunan odaların durumunun sabah ve akşam oda görevlisince kaydedildiği formdur.","ornek":"Sabah oda kontrolünü bitiren Selin, 301’den 308’e kadar her odanın durumunu, kişi sayısını ve özel notlarını rapora yazar ve imzalayıp kat şefine verir.","sektor":"Rapor kat şefinin hazırladığı iş planına göre sabah oda kontrolünden sonra, akşam ise iş bitiminde hazırlanır; kat hizmetleri müdürü bu raporlardan ön büroya giden raporu çıkarır.","iliskili":["kh1-2-016","kh1-2-018","kh1-2-019"],"kontrol":null},{"id":"kh1-2-016","konu":"2.1.1","terim":"Kat hizmetleri raporu","ingilizce":"Housekeeping report","tanim":"Oda görevlilerinin raporlarına göre kat hizmetleri müdürünün hazırlayıp ön büroya gönderdiği, odaların durumunu gösteren rapordur.","ornek":"Sabah 10.30’da kat hizmetleri müdürü, boş, dolu, arızalı ve bagajsız odaları gösteren raporu hazırlar; bir nüshası ön büroya gider.","sektor":"Rapor üç nüsha düzenlenir: biri ön büroya, biri muhasebeye gönderilir, biri kat hizmetlerinde kalır. Ön büro satış ve giriş işlemlerini bu rapora göre yapar. Yoğun sezonda gün içinde birden fazla rapor gönderilebilir.","iliskili":["kh1-2-015","kh1-2-017"],"kontrol":null},{"id":"kh1-2-017","konu":"2.1.1","terim":"Ön büro ile kat hizmetleri iletişimi","ingilizce":"Front office and housekeeping communication","tanim":"Odaların temiz, kirli, dolu ya da arızalı olduğunun ön büro ile kat hizmetleri arasında sürekli paylaşılmasıdır.","ornek":"Öğleden sonra 14.00’te resepsiyondaki görevli, 412 numaralı odanın temiz olup olmadığını kat ofisini arayarak sorar ve konuğu odasına yönlendirir.","sektor":"Ön büro hangi odanın hazır olduğunu bilmeden konuğu yerleştiremez; kat hizmetleri de hangi odanın boşaldığını ön büro bildirmeden bilemez. İki bölüm birbirinin gözü kulağıdır.","iliskili":["kh1-2-016","kh1-2-015"],"kontrol":null},{"id":"kh1-2-018","konu":"2.1.1","terim":"Rapordaki kişi sayısını odayla karşılaştırma","ingilizce":"Checking occupancy against the report","tanim":"Raporda yazan konuk sayısı ile odadaki izlerden anlaşılan kişi sayısının karşılaştırılmasıdır.","ornek":"Raporda 1104 numaralı odada iki kişi görünür; Murat odada kullanılmış üç yatak ve üç kişiye ait eşya görür, durumu raporun açıklama bölümüne yazar.","sektor":"Görevli kullanılan yatakları, konuk kıyafetlerini ve diş fırçasını kontrol eder; fark varsa raporun açıklama kısmına yazılır, böylece ön büro gerçek kişi sayısını öğrenir.","iliskili":["kh1-2-015","kh1-2-019"],"kontrol":null},{"id":"kh1-2-019","konu":"2.1.1","terim":"Raporun açıklama bölümü","ingilizce":"Remarks section of the report","tanim":"Oda durum raporunda sembolle anlatılamayan özel durumların yazıldığı alandır.","ornek":"Selin, 1006 numaralı odanın konuğu geceyi otel dışında geçirdiği için S/O yazar ve açıklama kısmına “yatak kullanılmamış” diye not düşer.","sektor":"Konuğun otel dışında geceleyip gecelememesi, oda değişikliği, arızalı kullanım dışı oda gibi özel durumlar raporun açıklama kısmında mutlaka belirtilir. Semboller ve kısaltmalar doğru kullanılmalıdır.","iliskili":["kh1-2-015","kh1-2-018"],"kontrol":null},{"id":"kh1-2-020","konu":"2.1.1","terim":"Raporu kat şefine teslim etme","ingilizce":"Handing in the report","tanim":"Oda görevlisinin doldurduğu raporu imzalamadan önce kontrol edip tarihiyle birlikte kat şefine vermesidir.","ornek":"Öğleden sonra 16.30’da Murat, raporunda eksik kalan bir odayı fark eder, tamamlar, tarihi yazar, imzasını atar ve raporu zamanında kat şefine verir.","sektor":"Eksik ya da geç rapor ön büronun satış kararlarını yanlışlaştırabilir; bu yüzden teslimden önce kontrol, tarih ve imza birlikte yapılır.","iliskili":["kh1-2-015","kh1-2-016"],"kontrol":null},{"id":"kh1-2-021","konu":"2.1.1","terim":"V/C","ingilizce":"Vacant clean","tanim":"Raporda konuk bulunmayan, temizliği yapılmış odayı gösteren kısaltmadır.","ornek":"Sabah temizliğini bitiren Selin, 305 numaralı odayı durum raporunda V/C olarak gösterir.","sektor":"V/C temizliği bitmiş ama kat şefi kontrolünü bekleyebilen boş odadır; satışa hazır sayılması işletmeye göre değişir (bazı işletmeler kontrol edilmiş odayı ayrı gösterir).","iliskili":["kh1-2-022","kh1-2-025"],"kontrol":null,"gorsel":"h3b-hazir-oda"},{"id":"kh1-2-022","konu":"2.1.1","terim":"C/O","ingilizce":"Check-out","tanim":"Raporda çıkış yapılmış, henüz temizlenmemiş odayı gösteren kısaltmadır.","ornek":"Sabah 11.15’te kat şefi, rapordaki C/O odaları önce temizlenecekler olarak işaretler.","sektor":"C/O odalar yeniden satılacağı için dolu ve boş odalardan önce temizlenir (VIP ve “odamı hemen temizleyin” odalarından sonra); temizlenince V/C olur.","iliskili":["kh1-2-021","kh1-2-007"],"kontrol":null},{"id":"kh1-2-023","konu":"2.1.1","terim":"C/IN","ingilizce":"Check-in","tanim":"Raporda yeni giriş yapılmış odayı gösteren kısaltmadır.","ornek":"Akşam raporunda 214 numaralı oda C/IN yazılıdır; ertesi sabah aynı oda OCC olarak görünür.","sektor":"Yeni giriş yapılan odanın ilk günü konuk için önemlidir; oda görevlisi eksik malzeme olup olmadığına özellikle bakar.","iliskili":["kh1-2-024","kh1-2-006"],"kontrol":null},{"id":"kh1-2-024","konu":"2.1.1","terim":"OCC","ingilizce":"Occupied","tanim":"Raporda konuğun kaldığı dolu odayı gösteren kısaltmadır.","ornek":"Sabah 09.00’da 310 numaralı odada konuk vardır; Selin raporda bu odayı OCC olarak işaretler.","sektor":"Dolu odaya girmeden önce konuğun temizlik isteyip istemediği sorulur; OCC işareti görevliye bu dikkati hatırlatır.","iliskili":["kh1-2-025","kh1-2-023"],"kontrol":null},{"id":"kh1-2-025","konu":"2.1.1","terim":"OK","ingilizce":"Okay (OK)","tanim":"Raporda odanın temizliğinin tamamlandığını gösteren işarettir.","ornek":"Selin, 310 numaralı odanın temizliğini bitirince raporda OCC yazan odayı OK olarak değiştirir.","sektor":"Bu birimin örnek raporunda OK, dolu odanın günlük temizliği bittiğinde OCC’nin yerine yazılır; ders materyalinin başka bir yerinde aynı işaret boş ve satışa hazır oda için de geçer. Böylece kat şefi hangi odaya yeniden bakması gerektiğini bilir.","iliskili":["kh1-2-024","kh1-2-021"],"kontrol":null},{"id":"kh1-2-026","konu":"2.1.1","terim":"S/O","ingilizce":"Sleep-out","tanim":"Raporda dolu olduğu hâlde gece kullanılmayan, yani konuğun geceyi dışarıda geçirdiği odayı gösteren kısaltmadır.","ornek":"Sabah 08.30’da 1006 numaralı odanın yatağı dünkü düzeniyle, hiç yatılmamış hâlde durur; Selin odayı S/O olarak yazar.","sektor":"S/O bilgisi ön büroya önemlidir; konuğun gerçekten otelde kalıp kalmadığı buradan anlaşılır. Açıklama bölümüne de yazılır.","iliskili":["kh1-2-027","kh1-2-019"],"kontrol":null},{"id":"kh1-2-027","konu":"2.1.1","terim":"W/L","ingilizce":"Without luggage","tanim":"Raporda konuğun bagajı bulunmayan dolu odayı gösteren kısaltmadır.","ornek":"Selin, 502 numaralı odada hiç bavul görmediği için raporda odayı W/L olarak gösterir.","sektor":"Sıra dışı durumlar raporun açıklama kısmına yazılır; ön büro bu bilgiyle gerekli kontrolü kendisi yapar.","iliskili":["kh1-2-026","kh1-2-024"],"kontrol":null},{"id":"kh1-2-028","konu":"2.1.1","terim":"H/U","ingilizce":"House use","tanim":"Raporda otel personelinin kullandığı odayı gösteren kısaltmadır.","ornek":"4. kattaki 420 numaralı oda gece kalan bir yöneticiye ayrıldığı için raporda H/U yazar.","sektor":"H/U odalar konuğa satılmaz; oda görevlisi bu odaları konuk odası gibi hazırlamaz, kat şefinin verdiği talimata göre ilgilenir.","iliskili":["kh1-2-029","kh1-2-024"],"kontrol":null},{"id":"kh1-2-029","konu":"2.1.1","terim":"Rapor işareti VIP","ingilizce":"Very important person (VIP)","tanim":"Raporda önemli konuk odasını belirten işarettir.","ornek":"Akşam raporunda 601 numaralı oda VIP yazılıdır; sabah meeting’de bu konuğun gelişi duyurulur ve oda görevlisi hazırlığı özenle yapar.","sektor":"VIP işareti görevliyi uyarır: oda özel dikkatle kontrol edilir, eksik bırakılmaz. Konuk önemliyse beklentisi de yüksektir.","iliskili":["kh1-2-028","kh1-2-012"],"kontrol":null},{"id":"kh1-2-030","konu":"2.1.2","terim":"Pas anahtarı","ingilizce":"Master key","tanim":"Kat hizmetleri personelinin sorumlu olduğu oda ve alanların kapısını açan, tek başına birden fazla kapıyı açabilen metal ya da kart anahtardır.","ornek":"Sabah 08.05’te Selin, bölüm pas kartını imza karşılığı teslim alır ve 3. kattaki sekiz odayı tek kartla açabileceğini bilerek işe başlar.","sektor":"Pas anahtarı kat hizmetlerinin otele yayılan işini aksatmadan ve hızlı yürütmesi için kullanılır; bu yüzden güvenliği çok önemlidir.","iliskili":["kh1-2-031","kh1-2-038"],"kontrol":null},{"id":"kh1-2-031","konu":"2.1.2","terim":"Bölüm pas anahtarı","ingilizce":"Section master key","tanim":"Günlük oda hizmeti sırasında, sorumlu olunan bölümdeki odaları açan tek anahtardır.","ornek":"Murat’a 4. kattaki 401–410 arası odalar verilir; aldığı bölüm pas kartı yalnızca bu odaları açar.","sektor":"Oda temizleme görevlilerinin kullanımı için hazırlanır; böylece görevli yalnızca kendi sorumluluğundaki odalara girer.","iliskili":["kh1-2-032","kh1-2-030"],"kontrol":null},{"id":"kh1-2-032","konu":"2.1.2","terim":"Kat pas anahtarı","ingilizce":"Floor master key","tanim":"Yalnızca bir kattaki bütün odaları açan anahtardır.","ornek":"3. kat şefi Hülya’nın kartı 3. kattaki tüm odaları açar ama 4. kattaki hiçbir kapıyı açmaz.","sektor":"Kat pas anahtarı ilgili kat şefine verilir ve diğer katların odalarını açmayacak şekilde kodlanır.","iliskili":["kh1-2-031","kh1-2-033"],"kontrol":null},{"id":"kh1-2-033","konu":"2.1.2","terim":"Katlar anahtarı","ingilizce":"Grand master key","tanim":"Otelin bütün misafir odalarını açan tek anahtar ya da karttır.","ornek":"Kat hizmetleri müdürü, gece vardiyasında acil bir durum için kendisindeki katlar anahtarıyla 2. kattaki bir odayı açar.","sektor":"Güvenlik gerekçesiyle yalnızca kat hizmetleri yöneticisinde bulunur; sayısı sınırlı tutulur.","iliskili":["kh1-2-032","kh1-2-034"],"kontrol":null},{"id":"kh1-2-034","konu":"2.1.2","terim":"Genel otel anahtarı","ingilizce":"General master key","tanim":"Ofis, mutfak, depo, oda ve salon gibi otelin bütün bölümlerinin kapılarını açan tek anahtardır.","ornek":"Gece yarısı bir depoya girilmesi gerektiğinde otel yönetimi, genel otel anahtarıyla kapıyı açar.","sektor":"Emniyet anahtarı da denir ve otel idaresinde bulunur; oda görevlilerine verilmez.","iliskili":["kh1-2-033"],"kontrol":null},{"id":"kh1-2-035","konu":"2.1.2","terim":"Anahtar dolabı","ingilizce":"Key cabinet","tanim":"Kat ofisinde pas anahtarlarının kilitli olarak saklandığı dolaptır.","ornek":"Sabah 08.05’te kat ofisindeki dolap açılır, görevliler anahtarlarını imza karşılığı alır ve dolap tekrar kilitlenir.","sektor":"Anahtar dolabı açık bırakılmaz, her zaman kilitli tutulur; böylece anahtarların yetkisiz kişilerin eline geçmesi önlenir.","iliskili":["kh1-2-036","kh1-2-037"],"kontrol":null,"gorsel":"h6-anahtar-panosu"},{"id":"kh1-2-036","konu":"2.1.2","terim":"Anahtar dolabı vardiya sorumlusu","ingilizce":"Key cabinet attendant","tanim":"Anahtarların dolaba teslimini ve çıkışını yöneten, kayıt defterinin doğru doldurulmasını izleyen görevlidir.","ornek":"Kat ofisinde dolap sorumlusu Hülya, Murat’ın defterde tarih ve saati yazmadan anahtarı aldığını görür ve düzeltmesini ister.","sektor":"Sorumlu görevli teslim alan ile teslim edenin defteri doğru doldurup doldurmadığını izler ve kendisi de teslim verirken adını, soyadını, tarihi yazıp imzalar.","iliskili":["kh1-2-035","kh1-2-037"],"kontrol":null},{"id":"kh1-2-037","konu":"2.1.2","terim":"Pas anahtarı imza föyü","ingilizce":"Key sign-out sheet","tanim":"Anahtarı alan ve teslim eden kişinin adı, saati ve imzasının tek tek kaydedildiği tablodur.","ornek":"Sabah 08.05’te Selin föye adını, pas numarasını, aldığı saati, sorumlu olduğu katı yazar ve imzalar; akşam teslim saatini ekler.","sektor":"Föyde ad soyad, pas numarası, alınan saat, imza, bölge ve katlar, teslim saati ve şef kontrolü ile teslim alan imzası bulunur. Bir kayıp olursa kimde ne zaman olduğu defterden bellidir.","iliskili":["kh1-2-035","kh1-2-039"],"kontrol":null},{"id":"kh1-2-038","konu":"2.1.2","terim":"Pas anahtarı güvenliği","ingilizce":"Master key security","tanim":"Anahtarın başkasına verilmemesi, konuğa oda açmak için kullanılmaması ve kaybolursa hemen bildirilmesidir.","ornek":"Öğle arası bir konuk Selin’den “anahtarımı odada unuttum, açar mısınız?” diye ister; Selin pas anahtarını kullanmaz, konuğu resepsiyona yönlendirir.","sektor":"Görevli kendisine imzayla verilen anahtarı iyi saklar. Kaybederse kat şefine ve işletme güvenlik birimine bilgi verir; işletme prosedürüne göre gerekli disiplin kuralları uygulanabilir.","iliskili":["kh1-2-030","kh1-2-039"],"kontrol":null},{"id":"kh1-2-039","konu":"2.1.2","terim":"Pas anahtarını teslim etme","ingilizce":"Returning the master key","tanim":"Çalışma bitiminde anahtarın imza karşılığı, tarihi ve saati yazılarak şefe ya da yetkili personele geri verilmesidir.","ornek":"Öğleden sonra 16.30’da Murat anahtarını kat şefine verir, defterde teslim tarihini ve saatini yazıp imzalar.","sektor":"Anahtar işletmenin dışına çıkarılmaz. Olası bir kayıp durumunda defterdeki geriye dönük kayıtlar kanıt olarak kullanılır.","iliskili":["kh1-2-037","kh1-2-038"],"kontrol":null},{"id":"kh1-2-040","konu":"2.1.2","terim":"3x3 metodu","ingilizce":"3x3 knocking method","tanim":"Odaya girmeden önce kapıya üç kez nazikçe vurup “Housekeeping” diye seslenmek ve bu işlemi iki kez daha yinelemektir.","ornek":"Sabah 09.10’da Selin 306 numaralı odanın kapısına üç kez vurup “Housekeeping” der; yanıt gelmeyince aynı şeyi iki kez daha tekrarlar, sonra pas kartını kullanır.","sektor":"Konuk odada olabilir, uyuyor ya da banyoda olabilir; bu yöntem özel alanına saygının ve ani karşılaşmayı önlemenin standardıdır.","iliskili":["kh1-2-041","kh1-2-042"],"kontrol":null},{"id":"kh1-2-041","konu":"2.1.2","terim":"Oda Görevlisi kartı","ingilizce":"Room attendant card","tanim":"Odada çalışılırken kapıya asılan ve içeride görevli olduğunu bildiren karttır.","ornek":"Selin 308 numaralı odaya girince kapıya Oda Görevlisi kartını asar ve kapıyı çalıştığı süre boyunca açık tutar.","sektor":"Kart konuğa ve kat şefine odada işlem yapıldığını gösterir; açık kapı ise hem görevlinin hem konuğun güvenliğini sağlar.","iliskili":["kh1-2-040","kh1-2-042"],"kontrol":null},{"id":"kh1-2-042","konu":"2.1","terim":"Boş odaya giriş","ingilizce":"Entering a vacant room","tanim":"Rapora göre konuk bulunmayan odaya kapıyı çalıp yanıt gelmeyince pas anahtarıyla girme işlemidir.","ornek":"Sabah 09.30’da Selin boş görünen 305 numaralı odaya 3x3 yöntemiyle kapıyı çalar, ses gelmeyince pas kartıyla girer ve Oda Görevlisi kartını asar.","sektor":"Boş odada bile adım atlanmaz; rapor yanlış olabilir ve içeride konuk bulunabilir. Rapordaki bilgi ile odanın gerçek durumu uyuşmuyorsa fark rapora yazılır ve kat şefine bildirilir.","iliskili":["kh1-2-040","kh1-2-043"],"kontrol":null},{"id":"kh1-2-043","konu":"2.1","terim":"Konuk odadayken giriş","ingilizce":"Entering an occupied room","tanim":"Konuğun içeride olduğu odaya DND kartına bakıp kapıyı çalarak, temizlik isteyip istemediğini sorarak girme işlemidir.","ornek":"Sabah 10.20’de Murat 215 numaralı odanın kapısında DND kartı olmadığını görür, kapıyı çalar; konuk kapıyı açınca onu selamlayıp temizlik isteyip istemediğini sorar.","sektor":"Konuk temizlik istemezse başka bir saate bırakılır; isterse kapıya Oda Görevlisi kartı asılır ve konuğun rahatı ve huzuru bozulmadan, sessizce çalışılır.","iliskili":["kh1-2-044","kh1-2-050"],"kontrol":null},{"id":"kh1-2-044","konu":"2.1","terim":"Temizlik sırasında konuğun gelmesi","ingilizce":"Guest returning during cleaning","tanim":"Oda temizlenirken konuğun odaya gelmesi durumunda, temizliğin sakıncası olup olmadığının sorulup konuğun isteğine göre devam edilmesidir.","ornek":"Selin 304 numaralı odanın banyosunu temizlerken konuk gelir; Selin “Temizliğe devam etmemde sakınca var mı?” diye sorar, konuk istemeyince araç gereci toplayıp çıkar.","sektor":"Konuk sakınca olmadığını söylerse çalışma onu rahatsız etmeyecek şekilde sürdürülür; istemezse odanın başka bir saatte temizleneceği oda durum raporuna not edilir.","iliskili":["kh1-2-043","kh1-2-019"],"kontrol":null},{"id":"kh1-2-045","konu":"2.1","terim":"Oda değişimi","ingilizce":"Room change","tanim":"Konuğun bulunduğu odadan başka bir odaya geçirilmesi ve bu geçişte ona yardım edilmesidir.","ornek":"Öğleden sonra 14.30’da 218 numaralı odada klima bozulunca konuk 224 numaralıya alınır; Murat eşyaların toplanmasına yardımcı olur, bellboy ile birlikte yeni odaya taşır.","sektor":"Görevli konuğa yardıma geldiğini söyler, eşyaları özenle toplar, konuk isterse yeni odaya yerleşmesine de yardım eder. Eski oda sonra temizlenip satışa hazır hâle getirilir. Eşyalar bellboy ile birlikte yeni odaya taşınır.","iliskili":["kh1-2-044","kh1-2-046"],"kontrol":null},{"id":"kh1-2-046","konu":"2.1","terim":"Çıkış yapılmış odaya giriş","ingilizce":"Entering a check-out room","tanim":"Konuğun odayı boşaltmasından sonra, otelden ayrılmadan odaya girilip genel kontrolün yapılmasıdır.","ornek":"Sabah 11.00’de 410 numaralı oda boşalır; Murat konuk lobiden ayrılmadan odaya girer, genel kontrolü yapar ve unutulmuş eşya olup olmadığına bakar.","sektor":"Önce çıkış saatleri öğrenilir; konuk ayrılmadan odaya girilirse unutulan şey hâlâ ona ulaştırılabilir.","iliskili":["kh1-2-047","kh1-2-048"],"kontrol":null},{"id":"kh1-2-047","konu":"2.1","terim":"Çıkış odasında unutulmuş eşya","ingilizce":"Item left behind in a check-out room","tanim":"Konuk ayrıldıktan sonra odada kalan kişisel eşyanın bulunup konuğa ulaştırılmasının sağlanmasıdır.","ornek":"Murat 410 numaralı odada yatağın yanında bir şarj aleti bulur; vakit geçirmeden ön büroya götürür, konuk otelden ayrılmadan teslim edilir.","sektor":"Eşya vakit geçirmeden ön büroya götürülür ya da ön büro aranarak haber verilir; amaç, eşyanın konuk otelden ayrılmadan ona ulaşmasıdır. Konuk ayrılmışsa kayıp bulunmuş eşya formu doldurulup form, eşyayla birlikte kat şefine verilir.","iliskili":["kh1-2-046","kh1-2-048","kh1-2-160"],"kontrol":null},{"id":"kh1-2-048","konu":"2.1","terim":"Çıkış odasında hasar tespiti","ingilizce":"Damage check in a check-out room","tanim":"Konuk ayrıldıktan sonra demirbaşlarda konuktan kaynaklı hasar ya da eksik olup olmadığının kontrol edilmesidir.","ornek":"Murat 410 numaralı odada masa lambasının kırık olduğunu görür; kat şefine haber verir, kat şefi tutanağı düzenler ve ön büroyu bilgilendirir.","sektor":"Hasar ya da eksik varsa tutanak tutulur ve ön büro bilgilendirilir; tutanağı genellikle kat şefi düzenler. Böylece hasarın karşılanması sağlanır.","iliskili":["kh1-2-046","kh1-2-047"],"kontrol":null},{"id":"kh1-2-049","konu":"2.1.3","terim":"Konuk odası kapı kartları","ingilizce":"Guest-room door cards","tanim":"Konuğun odasından kat hizmetleriyle sessizce iletişim kurmasını sağlayan, kapı koluna asılan ya da odada bırakılan kartlardır.","ornek":"Otel odasında masanın üzerindeki dosyada DND, “Lütfen odamı temizleyin” ve oda bilgi kartları bulunur; konuk DND kartını kapı koluna asar, doldurduğu kartı da görevlinin göreceği yere bırakır.","sektor":"Kartlar konuğun isteğine zamanında cevap vermeyi sağlar. Kapı koluna asılan kart DND kartıdır; diğerleri gerektiğinde konuk tarafından doldurulup görevlinin görebileceği şekilde bırakılır.","iliskili":["kh1-2-050","kh1-2-051","kh1-2-259"],"kontrol":null,"gorsel":"t15ab-kapi-karti-koridor"},{"id":"kh1-2-050","konu":"2.1.3","terim":"DND kartı","ingilizce":"Do Not Disturb (DND) card","tanim":"Konuğun odasına girilmesini istemediğini kapı koluna asarak bildirdiği karttır.","ornek":"Sabah 10.00’da 406 numaralı odanın kapı kolunda DND kartı asılıdır; Selin kapıyı çalmaz ve odayı atlar.","sektor":"DND kartı asılı odaya girilmez, konuk rahatsız edilmez; konuğun isteği temizlik programının önündedir. Kart İngilizce “Do Not Disturb” yani “rahatsız etmeyiniz” anlamına gelir.","iliskili":["kh1-2-051","kh1-2-054"],"kontrol":null,"gorsel":"f3c-dnd-cokdilli"},{"id":"kh1-2-051","konu":"2.1.3","terim":"Lütfen odayı şimdi hazırlayınız kartı","ingilizce":"Please Make Up Room card","tanim":"DND kartının genellikle diğer yüzünde bulunan, konuğun odasının hemen temizlenmesini istediğini bildiren karttır.","ornek":"Öğleden sonra 13.00’te Murat 3. katta bir kapıda kartın “Lütfen odayı şimdi hazırlayınız” yüzünün asıldığını görür ve önce o odaya gider.","sektor":"Bu kart asılı odalar temizlikte önceliklidir; oda görevlisi sırasını buna göre değiştirir. Kart “Odamı temizleyin kartı” olarak da anılır.","iliskili":["kh1-2-050","kh1-2-052"],"kontrol":null},{"id":"kh1-2-052","konu":"2.1.3","terim":"Işıklı DND ve odamı temizleyin butonu","ingilizce":"DND and Make Up Room indicator lights","tanim":"Kapının yanında, konuğun odadan tuşla yaktığı kırmızı (rahatsız etmeyin) ve yeşil (odamı temizleyin) ışıklı göstergelerdir.","ornek":"Yeni açılmış bir otelde 506 numaralı odanın dışında kırmızı ışık yanar; Selin kapıya hiç dokunmadan yoluna devam eder.","sektor":"Yeni sistemlerde konuk, kart asmak yerine içerideki tuşla dışarıdaki lambayı yakarak kat personelini uyarabilir.","iliskili":["kh1-2-050","kh1-2-051"],"kontrol":null,"gorsel":"os-rahatsiz-etmeyin-karti"},{"id":"kh1-2-053","konu":"2.1.3","terim":"DND sırasında sessizlik ve telefon kuralı","ingilizce":"Silence and call rules during DND","tanim":"Rahatsız edilmek istemeyen konuğun huzurunu korumak için telefonların bağlanmaması ve çevredeki gürültünün önlenmesidir.","ornek":"Öğleden sonra 15.00’te 408 numaralı odada DND varken yan odada matkapla tamirat yapılması planlanmıştır; kat şefi işi erteletir.","sektor":"Konuk DND kartı sonrası resepsiyonu arayarak telefon istemediğini de söyleyebilir; bu durumda konuk hiç kimseyle görüştürülmez. Kart asılıyken yan odalarda gürültü yapılmaz ve gürültülü teknik işlere izin verilmez.","iliskili":["kh1-2-050","kh1-2-054"],"kontrol":null},{"id":"kh1-2-054","konu":"2.1.3","terim":"DND uyarı kartı","ingilizce":"DND notification card","tanim":"Temizlenemeyen odanın konuğuna, girilemediğini bildirmek için kapının altından atılan ya da koluna asılan bilgilendirme kartıdır.","ornek":"Selin 406 numaralı odaya giremeyince kapının altından “Kapınızda DND kartı vardı, odanıza girilemediğinden temizlik yapılamadı” yazılı kartı içeri atar.","sektor":"Kartta konuğa temiz havlu ya da başka bir ihtiyaç için resepsiyonu aramasını söyler; konuk temizlik isterse ön büroyu arar ve oda temizlenir.","iliskili":["kh1-2-050","kh1-2-055"],"kontrol":null,"gorsel":"t15ab-dnd-karti-kirmizi"},{"id":"kh1-2-055","konu":"2.1.3","terim":"DND kaydı ve akşam raporu","ingilizce":"Recording DND rooms","tanim":"Girilemeyen DND odalarının tarih ve saatiyle otel sistemine yazılması ve akşam raporunda belirtilmesidir.","ornek":"Öğleden sonra 16.30’da Selin, DND yüzünden giremediği 406 numaralı odayı raporuna yazar; kat şefi bunu sisteme işler.","sektor":"Bu kayıt konuk şikâyetlerinin önüne geçer; çünkü girilmeme nedeni açıkça bellidir.","iliskili":["kh1-2-054","kh1-2-056"],"kontrol":null},{"id":"kh1-2-056","konu":"2.1.3","terim":"DND uyarısının 24 saat kuralı","ingilizce":"24-hour DND rule","tanim":"Konuğun DND kartı ertesi gün de kapıda duruyorsa ön büronun konuğu arayıp sağlık durumunu ve bir ihtiyacı olup olmadığını sormasıdır.","ornek":"Salı sabahı 10.00’da 412 numaralı odada DND hâlâ asılıdır; ön büro konuğa telefon eder ve sağlık durumunu sorar.","sektor":"Ders materyaline göre DND uyarısı 24 saat geçerlidir. Ön büro konuğun sağlığı ve ihtiyacı olup olmadığını sorar; olumsuz bir durum yoksa konuğa temizlik için girilemediği, isterse yapılacağı söylenir.","iliskili":["kh1-2-055","kh1-2-057"],"kontrol":null},{"id":"kh1-2-057","konu":"2.1.3","terim":"Uzayan DND’de acil durum prosedürü","ingilizce":"Emergency procedure for prolonged DND","tanim":"DND uzun süre sürerse konuğun hasta ya da vefat etmiş olabileceği düşünülerek yetkililerle odaya girilmesidir.","ornek":"Pazartesi ve salı boyunca 412 numaralı odaya girilemez, konuk telefona çıkmaz; kat şefi bir güvenlik görevlisiyle ve yetkili bir kişiyle birlikte odaya girer.","sektor":"Konuk hastaysa doktor, hastaneye gitmesi gerekiyorsa ambulans (112) çağrılır. Vefat varsa konuğa müdahale edilmez, hiçbir yere dokunulmaz, hemen güvenlik güçlerine haber verilir, oda güvenlik şeridiyle korunur ve işletmenin acil durum prosedürü uygulanır.","iliskili":["kh1-2-056","kh1-2-058"],"kontrol":null},{"id":"kh1-2-058","konu":"2.1.3","terim":"Çıkış gününde DND kartı","ingilizce":"DND card on departure day","tanim":"Konuğun çıkış yapacağı gün oda kontrolünde kapıda DND kartı varsa kat şefinin konuğu telefonla araması ve ön büroya bilgi vermesidir.","ornek":"Çıkış günü sabah 10.30’da kat şefi Hülya, DND asılı 504 numaralı odayı arar; konuk ayrılmış olduğunu söylerse oda ancak sorun olmadığı anlaşılınca açılır.","sektor":"Konuk odadan ayrıldığında herhangi bir sorun olmadığından emin olunduktan sonra içeri girilir.","iliskili":["kh1-2-057","kh1-2-056"],"kontrol":null},{"id":"kh1-2-059","konu":"2.2","terim":"Odayı havalandırma","ingilizce":"Airing the room","tanim":"Temizliğe başlarken perde, balkon kapısı ve pencerenin açılıp odaya temiz hava alınmasıdır.","ornek":"Sabah 09.40’ta Selin 311 numaralı odaya girince önce perdeleri, sonra balkon kapısını ve pencereyi açar.","sektor":"İşletmeye gelen konuklar için sağlıklı ve hijyenik bir ortam oluşturmak kat hizmetlerinin hedefidir. Havalandırma temiz bir ortam havası sağlar ve odanın nem oranını dengeler; bu hem görevlinin hem konuğun sağlığı içindir.","iliskili":["kh1-2-060","kh1-2-062"],"kontrol":null},{"id":"kh1-2-060","konu":"2.2","terim":"Karşılıklı havalandırma","ingilizce":"Cross ventilation","tanim":"İki karşılıklı açıklıkla hava akımı oluşturup kullanılmış nemli havanın temiz havayla değiştirilmesidir.","ornek":"Öğle öncesi Murat, oda kapısını ve balkon penceresini karşılıklı açık tutarak odayı havalandırır.","sektor":"En iyi havalandırma hava akımıyla olur; karşılıklı açılan pencere ve kapıyla yapılır. Ders materyaline göre bunun için odayı yaklaşık on dakika havalandırmak yeterlidir. Pencereler kapanınca gelen temiz hava hemen oda sıcaklığına ısınır.","iliskili":["kh1-2-059","kh1-2-061"],"kontrol":null,"gorsel":"t12b-acik-pencere-orman"},{"id":"kh1-2-061","konu":"2.2","terim":"Odadaki havalandırma ünitesi","ingilizce":"Room ventilation unit","tanim":"Odanın içinde bulunan, havalandırma yapmak için açılabilen cihazdır.","ornek":"Öğleden sonra 14.00’te penceresi açılmayan 507 numaralı odada Selin, odanın içindeki havalandırma ünitesini çalıştırarak temiz hava sağlar.","sektor":"Konuk odaları pencereyle olduğu gibi odadaki havalandırma ünitesi açılarak da havalandırılabilir.","iliskili":["kh1-2-060","kh1-2-062"],"kontrol":null,"gorsel":"t10b-klima-ic-unite"},{"id":"kh1-2-062","konu":"2.2","terim":"Havalandırma ve enerji tasarrufu","ingilizce":"Ventilation and energy saving","tanim":"Doğru havalandırmanın gereksiz sıcak ya da soğuk hava kaybını önleyerek enerjiyi korumasıdır.","ornek":"Murat odayı havalandırdıktan sonra pencereyi hemen kapatır; böylece klima boşuna çalışmaz.","sektor":"Doğru zamanda ve doğru sürede havalandırma enerji tasarrufu da sağlar; işletme giderleri azalır.","iliskili":["kh1-2-059","kh1-2-065"],"kontrol":null},{"id":"kh1-2-063","konu":"2.2","terim":"Rüzgârlı havada havalandırma","ingilizce":"Ventilating on windy days","tanim":"Hava çok rüzgârlıysa odadaki kâğıt ve hafif eşyaların uçuşmaması için havalandırmanın çöpler toplandıktan sonra yapılmasıdır.","ornek":"Fırtınalı bir öğleden sonra Selin, önce odadaki çöpleri toplar, sonra pencereyi açar.","sektor":"Hava çok rüzgârlıysa havalandırma, odadaki çöpler toplandıktan sonra yapılır; böylece çöpler ve hafif eşyalar savrulmaz.","iliskili":["kh1-2-064","kh1-2-059"],"kontrol":null},{"id":"kh1-2-064","konu":"2.2","terim":"Yağmurlu havada havalandırma","ingilizce":"Ventilating on rainy days","tanim":"Pencere ve balkon kapısı yarım açılarak perde ve eşyaların ıslanmasının önlendiği, yağışlı havaya uygun yöntemdir.","ornek":"Sağanak yağışta Murat balkon kapısını yarım açar ve perdeyi içeri çekerek ıslanmasını önler.","sektor":"Odadaki eşya ve perde ıslanırsa hem hasar hem koku olur; bu yüzden yağmurda pencere tam açılmaz.","iliskili":["kh1-2-063","kh1-2-065"],"kontrol":null,"gorsel":"t11b-yagmurlu-pencere"},{"id":"kh1-2-065","konu":"2.2","terim":"Havalandırma sonrası kapatma","ingilizce":"Closing up after airing","tanim":"Temizlik bitince pencere ve balkon kapısının kapatılması, perdelerin düzgünce çekilmesidir.","ornek":"Selin 311 numaralı odanın temizliğini bitirince pencereyi ve balkon kapısını kapatır, perdeleri düzgünce ayarlar.","sektor":"Açık bırakılan pencere güvenlik ve enerji kaybı demektir; perdelerin düzgün durması da odanın bakımlı görünmesini sağlar.","iliskili":["kh1-2-062","kh1-2-064"],"kontrol":null,"gorsel":"t10e-tul-perde"},{"id":"kh1-2-066","konu":"2.3","terim":"Çöp","ingilizce":"Rubbish","tanim":"Yararsız, pis ya da zararlı olduğu için atılan ve geri dönüştürülemeyen artık maddedir.","ornek":"Sabah 09.10’da 305 numaralı odada Selin, çöp sepetinden çiğnenmiş sakız, kırık kürdan ve süpürülmüş toz çıkarır; bunların yeniden kullanılamayacağını bilerek çöp torbasına koyar.","sektor":"Çöp yeniden bir kaynak olarak kullanılamaz; kâğıt, cam, metal, plastik gibi maddeler ayrıldıktan sonra geride kalandır.","iliskili":["kh1-2-067","kh1-2-069"],"kontrol":null,"gorsel":"t15ab-cop-tasan-kutu"},{"id":"kh1-2-067","konu":"2.3","terim":"Atık","ingilizce":"Waste","tanim":"Kullanımı sona erip atılan maddedir; bunların geri dönüşümle yeniden kullanılabilenleri ayrı toplanır.","ornek":"Oda görevlisi Selin konuğun bıraktığı boş plastik su şişesini çöpe değil, plastik atıkların toplandığı bölmeye koyar.","sektor":"Üretim ve tüketim sonrası oluşan atıkların doğaya bırakılması insan sağlığına ve çevreye zarar verir.","iliskili":["kh1-2-066","kh1-2-068"],"kontrol":null,"gorsel":"t10e-cop-konteynerleri"},{"id":"kh1-2-068","konu":"2.3","terim":"Tehlikeli atık","ingilizce":"Hazardous waste","tanim":"İnsan ve çevre sağlığına zarar verebilecek atıklardır.","ornek":"Teknik servisteki boya ve çözücü artıkları tehlikeli atık olarak ayrı yönetilir; Selin bunlara dokunmaz, sıradan oda çöpüne de karıştırmaz.","sektor":"Ders materyalinde sanayi atıkları üzerinden anlatılır. Otelde atık pil gibi atıklar da ayrı toplanır.","iliskili":["kh1-2-067","kh1-2-069"],"kontrol":null,"gorsel":"m3-kontejner-na-nebezpecny-odpad-bate"},{"id":"kh1-2-069","konu":"2.3","terim":"Atık çeşitleri","ingilizce":"Types of waste","tanim":"Atıkların kaynağına ve niteliğine göre evsel, tıbbi, endüstriyel, tarımsal ve bahçe atıkları olarak ayrılmasıdır.","ornek":"Sabah 09.30’da Selin, 305 numaralı odanın çöp sepetinden çıkan yiyecek ambalajını evsel atık olarak ayırır; otelin revirinde kullanılan pansuman malzemesi ise tıbbi atık olarak ayrı toplanır.","sektor":"Atıkların çeşidini bilmek, hangisinin nereye atılacağını bilmeyi kolaylaştırır. Ders materyalinde ilk sınıf “evrensel atık” diye yazılmıştır; sektörde evde ve otel odasında biriken günlük atığa “evsel atık” denir.","iliskili":["kh1-2-067","kh1-2-068"],"kontrol":null,"gorsel":"m3-waste-bins-recyclable"},{"id":"kh1-2-070","konu":"2.3","terim":"Geri dönüşüm","ingilizce":"Recycling","tanim":"Atıkların işlenerek yeniden kullanılabilir hâle getirilmesidir.","ornek":"Selin odadaki kâğıt ve plastikleri ayrı poşetlere koyar; bunlar sonra geri dönüşüm tesisine gider.","sektor":"Geri dönüşümün amacı kaynakların gereksiz kullanımını önlemek ve atık çöp miktarını azaltmaktır.","iliskili":["kh1-2-071","kh1-2-072"],"kontrol":null,"gorsel":"m3-recycling-sign"},{"id":"kh1-2-071","konu":"2.3","terim":"Geri dönüşümün yararları","ingilizce":"Benefits of recycling","tanim":"Atıkların yeniden değerlendirilmesiyle üretimde daha az enerji, su ve ağaç kullanılmasının, karbon salımının azalmasının sağlanmasıdır.","ornek":"Geri dönüşüm kutularına atılan kâğıtlar, yeni kâğıt için ağaç kesilmesini azaltır.","sektor":"Ülkelerde atıkların depolanması ve taşınması gibi sorunlar azalır; ithal hurdaya ödenen döviz miktarı düşer, ülke ekonomisine katkı sağlar.","iliskili":["kh1-2-070","kh1-2-072"],"kontrol":null},{"id":"kh1-2-072","konu":"2.3","terim":"Çöpün özelliğine göre ayrıştırılması","ingilizce":"Waste segregation","tanim":"Çöplerin organik, kâğıt, plastik, cam, metal, tıbbi ve karışık gibi türlere göre ayrı torba ve kutularda toplanmasıdır.","ornek":"Selin odadaki çöpleri toplarken kâğıtları, plastik şişeleri ve camları ayrı ayrı poşetlere koyar.","sektor":"Odada masanın ve sehpanın üzerindeki çöpler de özelliğine göre uygun torbalara ayrılır; geri dönüşebilenler karışık çöp ile karışmaz.","iliskili":["kh1-2-070","kh1-2-074"],"kontrol":null,"gorsel":"t15ab-cop-ayristirma-konteyner"},{"id":"kh1-2-263","konu":"2.3","terim":"Geri dönüştürülmüş ürünler","ingilizce":"Products made from recycled materials","tanim":"Kullanılmış kâğıt ve plastik gibi atıkların yeniden işlenmesiyle üretilen yeni eşyalardır.","ornek":"Kat şefi Hülya eğitimde, atılan plastik şişelerden ceket ve uyku tulumu gibi ürünlerin yapılabildiğini anlatır; Selin bu yüzden şişeleri ayrı poşete koyar.","sektor":"Ders materyaline göre kâğıt ve plastiğin geri dönüşümü ağaç kesilmesini ve enerji tüketimini azaltır; oda atıklarının ayrı toplanması bu zincirin ilk adımıdır.","iliskili":["kh1-2-070","kh1-2-071"],"kontrol":null},{"id":"kh1-2-073","konu":"2.3","terim":"Çöp toplarken eldiven ve maske","ingilizce":"Gloves and mask for waste collection","tanim":"Kişisel korunma için, çöp toplamaya başlamadan önce eldiven ve koruyucu maskenin takılmasıdır.","ornek":"Sabah 09.20’de Selin, çöp sepetini boşaltmadan önce eldivenlerini ve maskesini takar.","sektor":"Çöplerin temizliğe başlamadan toplanması personelin ve konukların sağlığını korur; bu yüzden eldiven ve maske ilk adımdır.","iliskili":["kh1-2-001","kh1-2-075"],"kontrol":null,"gorsel":"t11b-tek-kullanimlik-eldiven"},{"id":"kh1-2-074","konu":"2.3","terim":"Kat arabasında atık bölmesi","ingilizce":"Waste compartment on the trolley","tanim":"Arabadaki atık bölmesinin kullanılması, bölme yoksa çöp özelliğine göre farklı poşetlerin hazırlanmasıdır.","ornek":"Murat’ın arabasında atık bölmesi olmadığı için Murat üç ayrı poşet hazırlar: kâğıt, plastik ve karışık atık için.","sektor":"Atıklar baştan doğru bölmeye ya da poşete konursa sonradan ayırmaya gerek kalmaz.","iliskili":["kh1-2-072","kh1-2-075"],"kontrol":null,"gorsel":"h3b-temizlik-arabasi"},{"id":"kh1-2-075","konu":"2.3","terim":"Çöp torbasının değiştirilmesi","ingilizce":"Replacing the rubbish bag","tanim":"Oda çöp sepetindeki torbanın ağzı bağlanıp kat arabasındaki torbaya konulması ve kovaya yeni poşet takılmasıdır.","ornek":"Selin 305 numaralı odada çöp torbasının ağzını bağlar, arabadaki çöp torbasına koyar ve kovaya yeni poşet takar.","sektor":"Boş kova yeni poşetle bırakılır; konuk odaya girdiğinde temiz ve hazır bir çöp kovası bulur.","iliskili":["kh1-2-073","kh1-2-074"],"kontrol":null,"gorsel":"t11b-pedalli-cop-kovasi"},{"id":"kh1-2-076","konu":"2.3","terim":"Atık pil","ingilizce":"Waste batteries","tanim":"Kullanılamaz hâle gelmiş pillerin ayrı toplanıp pil kutusuna atılmasıdır.","ornek":"Murat, bozuk bir kumandadan çıkan kullanılmış pilleri ayrı poşete koyar ve atık pil toplama kutusuna bırakır.","sektor":"Piller karışık çöpe atılmaz; ayrı poşette atık pil toplama kutusuna konur.","iliskili":["kh1-2-072","kh1-2-075"],"kontrol":null},{"id":"kh1-2-077","konu":"2.3","terim":"Emin olunmayan eşya","ingilizce":"Items not clearly rubbish","tanim":"Konuk için önemli olabileceği düşünülen ve çöp olduğundan emin olunmayan şeylerin atılmamasıdır.","ornek":"Selin masada buruşturulmuş bir kâğıt görür; çöp olup olmadığından emin olmadığı için atmaz.","sektor":"Önemli bir belge ya da kişisel eşya yanlışlıkla atılırsa konuk zor durumda kalır; bu yüzden emin olunmayan hiçbir şey çöp sayılmaz.","iliskili":["kh1-2-075","kh1-2-047"],"kontrol":null},{"id":"kh1-2-151","konu":"2.4","terim":"Günlük ve periyodik arıza kontrolü","ingilizce":"Routine defect inspection","tanim":"Konuk odalarında ve ortak alanlarda arızaları konuk fark etmeden yakalamak için her gün ve belirli aralıklarla yapılan denetimdir.","ornek":"Sabah 09.30’da Bodrum’daki otelin ikinci katında oda görevlisi Selin, odayı toplamadan önce prizleri ve lambaları dener.","sektor":"Arıza konuktan önce bulunursa şikâyete dönüşmez; konuk odasında bozuk bir şey bulduğunda otelin hizmet sözü zedelenir.","iliskili":["kh1-2-152","kh1-2-162"],"kontrol":null},{"id":"kh1-2-152","konu":"2.4","terim":"Oda donanım kontrolü","ingilizce":"Room equipment check","tanim":"Oda temizlenirken odadaki elektrikli araçların ve donanımların çalışıp çalışmadığına bakılmasıdır.","ornek":"Ayşe, temizliğe başlamadan önce telefon, televizyon, klima, mini buzdolabı ve kasayı sırayla denetler.","sektor":"Odayı en yakından gören kişi oda görevlisi olduğu için arızayı ilk o fark eder; kontrol temizliğin bir parçasıdır.","iliskili":["kh1-2-151","kh1-2-153","kh1-2-154"],"kontrol":null},{"id":"kh1-2-153","konu":"2.4","terim":"Priz ve aydınlatma kontrolü","ingilizce":"Socket and lighting check","tanim":"Odadaki prizlerin, lamba anahtarlarının ve lambaların çalışıp çalışmadığına bakılmasıdır.","ornek":"Okuma lambası yanmayan odada Mert, anahtarı iki kez açıp kapatır ve sorunu forma yazar.","sektor":"Yanmayan bir lamba küçük görünse de konuğun ilk akşam fark edeceği bir eksikliktir.","iliskili":["kh1-2-152","kh1-2-154"],"kontrol":null,"gorsel":"t11b-komodin-lamba"},{"id":"kh1-2-154","konu":"2.4","terim":"Televizyon ve kumanda kontrolü","ingilizce":"TV and remote control check","tanim":"Televizyonu açıp kanalların geldiğini ve kumandanın çalıştığını denemektir.","ornek":"Zeynep televizyonu açıp birkaç kanalı gezer; kumandanın tuşlarının tepki vermediğini görür.","sektor":"Konuğun odada en çok kullandığı cihazlardan biri çalışmıyorsa oda eksik teslim edilmiş olur.","iliskili":["kh1-2-152","kh1-2-153"],"kontrol":null,"gorsel":"t10b-tv-kumandasi"},{"id":"kh1-2-155","konu":"2.4","terim":"Isıtma ve soğutma sistemi kontrolü","ingilizce":"Heating and cooling check","tanim":"Klimanın ve kumanda panellerinin odayı ısıtıp soğutacak şekilde çalışıp çalışmadığına bakılmasıdır.","ornek":"Temmuzda Antalya’daki otelde Kerem, panelden soğutmayı açar ve havalandırmadan serin hava geldiğini elini tutarak kontrol eder.","sektor":"Yazın bozuk bir klima konuğun memnuniyetini ciddi biçimde etkiler; bu yüzden kontrolün en önemli maddelerindendir.","iliskili":["kh1-2-152","kh1-2-151"],"kontrol":null,"gorsel":"t10b-klima-kumandasi"},{"id":"kh1-2-156","konu":"2.4","terim":"Oda telefonu kontrolü","ingilizce":"In-room telephone check","tanim":"Odadaki telefonun çalışıp çalışmadığına bakılmasıdır.","ornek":"Ece, ahizeyi kaldırıp hat sesini dinler ve tuşların basıldığını görür.","sektor":"Konuk yardım istemek istediği anda telefon çalışmıyorsa otele ulaşamaz.","iliskili":["kh1-2-152","kh1-2-157"],"kontrol":null},{"id":"kh1-2-157","konu":"2.4","terim":"Emanet kasa kontrolü","ingilizce":"In-room safe check","tanim":"Odadaki emanet kasanın açılıp kapandığını ve düzgün çalıştığını denemektir.","ornek":"Burak, boş kasanın kapağını kapatıp açarak mekanizmanın takılmadığını görür.","sektor":"Konuk değerli eşyasını kasaya güvenle koyabilmelidir; bozuk kasa güveni sarsar.","iliskili":["kh1-2-152","kh1-2-158"],"kontrol":null,"gorsel":"t10h-kasa-tus-takimi"},{"id":"kh1-2-158","konu":"2.4","terim":"Mobilya, perde ve nevresim kontrolü","ingilizce":"Furniture and soft furnishings check","tanim":"Mobilyaların, perdenin, koltuğun ve nevresim grubunun kırık, yırtık, lekeli ya da eksik olup olmadığına bakılmasıdır.","ornek":"Dilek, perde halkasının koptuğunu ve koltuk kolunda yırtık olduğunu görür.","sektor":"Bu tür hasarlar yeni konuk gelmeden bildirilirse onarım ya da değişim için zaman kalır.","iliskili":["kh1-2-152","kh1-2-157"],"kontrol":null},{"id":"kh1-2-159","konu":"2.4","terim":"Dolu odada (OCC) arıza tespiti","ingilizce":"Occupied room defect check","tanim":"Konuğun kaldığı odada, konuğun rahatını bozmadan prizlerin, televizyonun, klimanın, mini buzdolabının, kasanın ve mobilyaların kontrol edilmesidir.","ornek":"Öğleden sonra 14.00’te dolu bir odaya kapıyı çalarak giren Hakan, sırayla prizleri, televizyonu ve klimayı dener.","sektor":"Dolu odada konuğun eşyasına dokunmadan çalışılır; odaya girmeden önce kapı nazikçe çalınır ve kat görevlisi olduğu söylenir.","iliskili":["kh1-2-160","kh1-2-152"],"kontrol":null},{"id":"kh1-2-160","konu":"2.4","terim":"Çıkış yapılmış odada (C/O) arıza tespiti","ingilizce":"Check-out room defect check","tanim":"Konuğun çıkış yaptığı odada, temizliğe başlamadan önce arıza ve donanım kontrolünün yapılmasıdır.","ornek":"Konuk resepsiyondan ayrılmadan Pelin odaya gider, temizliğe başlamadan önce mini buzdolabını, kasayı ve televizyonu inceler.","sektor":"Konuk çıkış yaptığı için arıza ve hasar yeni konuk gelmeden bulunur; kontrol temizlikten önce, ayrıntılı yapılır.","iliskili":["kh1-2-159","kh1-2-047"],"kontrol":null},{"id":"kh1-2-162","konu":"2.4","terim":"Arıza bildirim formu","ingilizce":"Defect report form","tanim":"Odada tespit edilen arızayı yazılı olarak teknik servise bildiren formdur.","ornek":"Oda görevlisi Nur, 214 numaralı odada banyo lambasının yanmadığını forma yazar ve bir nüshasını teknik servise gönderir.","sektor":"Yazılı bildirim arızanın unutulmasını önler ve kimin neyi ne zaman haber verdiğini gösterir.","iliskili":["kh1-2-163","kh1-2-164"],"kontrol":null},{"id":"kh1-2-163","konu":"2.4","terim":"Arıza formunun nüshaları","ingilizce":"Defect report copies","tanim":"Bir nüshanın teknik servise, bir nüshanın kat şefine verilmesi, bir nüshanın da oda görevlisinde kalması; teknik servisin doldurup geri verdiği formun ofisteki dosyada saklanmasıdır.","ornek":"Teknik servis arızayı giderip formu doldurunca Ceyda, bu formu kendi nüshasıyla birlikte kat ofisindeki ilgili dosyaya koyar.","sektor":"Nüshalar sayesinde hem teknik servis hem kat şefi hem de oda görevlisi aynı arızanın durumunu izleyebilir.","iliskili":["kh1-2-162","kh1-2-166"],"kontrol":null},{"id":"kh1-2-164","konu":"2.4","terim":"Teknik servis","ingilizce":"Maintenance department","tanim":"Otelde arızaları gideren ve bakım onarım işlerini yürüten bölümdür.","ornek":"Kat görevlisi Cem’in bildirdiği klima arızasına teknik servisten usta Serkan öğleden önce bakar.","sektor":"Kat hizmetleri arızayı bulur, teknik servis giderir; iki bölümün iyi haberleşmesi odanın satışa hızlı dönmesini sağlar.","iliskili":["kh1-2-162","kh1-2-165"],"kontrol":null,"gorsel":"t12u-alet-cantasi"},{"id":"kh1-2-165","konu":"2.4","terim":"Arızalı odanın satışa kapatılması","ingilizce":"Taking a faulty room out of order","tanim":"Arızası giderilemeyen odanın ön büroya bildirilerek konuğa verilmemesi, yani satış dışı bırakılmasıdır.","ornek":"Banyo gideri tıkalı olan 312 numaralı oda Elif’in bildirimiyle sistemde satışa kapatılır; yeni gelen konuğa başka oda verilir.","sektor":"Arızalı oda hiçbir koşulda konuk kullanımına sunulmaz; konuk giriş anında hayal kırıklığına uğramaz.","iliskili":["kh1-2-164","kh1-2-166","kh1-2-008"],"kontrol":null},{"id":"kh1-2-166","konu":"2.4","terim":"Arıza takibi","ingilizce":"Defect follow-up","tanim":"Bildirilen arızanın giderilip giderilmediğinin izlenmesi, giderildiyse odanın tekrar kontrol edilip düzenlenmesidir.","ornek":"Ertesi sabah Gül, dünkü klima arızasının giderildiğini görmek için odaya girer, paneli dener ve odayı düzenler.","sektor":"Bildirimle iş bitmez; arızanın gerçekten çözüldüğünü görmek oda görevlisinin işidir.","iliskili":["kh1-2-163","kh1-2-167"],"kontrol":null},{"id":"kh1-2-167","konu":"2.4","terim":"Arızanın vardiya devri","ingilizce":"Shift handover of open defects","tanim":"Vardiya bitiminde çözülmemiş arızaların bir sonraki vardiyadaki görevlilere bildirilmesidir.","ornek":"Tuğba vardiyasını bitirirken onarım bekleyen iki arızayı bir sonraki vardiyadaki Okan’a anlatır.","sektor":"Bilgi devredilmezse arıza unutulur ve aynı oda yeniden sorun çıkarır.","iliskili":["kh1-2-166"],"kontrol":null},{"id":"kh1-2-168","konu":"2.4","terim":"Konuk odadayken çıkan arıza","ingilizce":"Fault during the guest’s stay","tanim":"Kalmakta olan konuğun odasında ortaya çıkan arızanın, ne kadar sürede giderilebileceğine göre ele alınmasıdır.","ornek":"Öğle saatinde konuk, duşun suyunun ısınmadığını bildirir; Tuba teknik servisi arar ve konuğa durumu anlatır.","sektor":"Kısa sürede çözülecek arızada teknik servisle iletişime geçilip konuğa bilgi verilir; uzun sürecekse oda değişimi düşünülür.","iliskili":["kh1-2-169","kh1-2-164"],"kontrol":null},{"id":"kh1-2-169","konu":"2.4","terim":"Arıza nedeniyle oda değişimi","ingilizce":"Room move because of a fault","tanim":"Giderilmesi uzun sürecek bir arıza varsa konuğun başka bir odaya geçirilmesidir.","ornek":"Klimanın akşama kadar onarılamayacağı anlaşılınca ön büro konuğa aynı tipte başka bir oda verir.","sektor":"Oda değiştiğinde ön büroya rapor gönderilir ve arızalı oda giderilene kadar satışa kapatılır.","iliskili":["kh1-2-168","kh1-2-165"],"kontrol":null},{"id":"kh1-2-170","konu":"2.4","terim":"Hasarlı malzeme tutanağı","ingilizce":"Damage report","tanim":"Konuk yüzünden bozulan ya da kırılan malzemenin yazılı olarak kayda geçirildiği belgedir.","ornek":"Çıkıştan sonra Kerem odada kırık bir sehpa bulur ve kat şefi Aylin’e haber verir; tutanağı Aylin düzenler.","sektor":"Tutanağın nüshaları muhasebeye, ön büroya, teknik servise ve konuk ilişkileri bölümüne imza karşılığı teslim edilir.","iliskili":["kh1-2-171"],"kontrol":null},{"id":"kh1-2-171","konu":"2.4","terim":"Konuk kaynaklı hasarın işlenmesi","ingilizce":"Handling guest-caused damage","tanim":"Konuğun yanlış kullanımı yüzünden bozulan malzemenin kat şefine bildirilmesi ve işletme prosedürüne göre bedelinin konuktan istenmesi sürecidir.","ornek":"Banyo rafı kırılan odada Dicle durumu kat şefine bildirir; kat şefi ön büroyu arar ve konukla yüz yüze görüşür.","sektor":"Oda görevlisi konuğa kendisi suçlama yapmaz; tutanak ve konuk görüşmesi kat şefinin işidir. Hasar bedelinin konuktan istenmesi işletme prosedürüne göre yürür.","iliskili":["kh1-2-170"],"kontrol":null},{"id":"kh1-2-172","konu":"2.4","terim":"Sipariş alıcı","ingilizce":"Order taker (housekeeping control desk)","tanim":"Otomasyon kullanılan işletmede kat hizmetlerine gelen arıza bildirimlerini sisteme giren personeldir.","ornek":"Oda görevlisi arızayı telsizle bildirir; sipariş alıcı Sinem bunu sisteme yazar.","sektor":"Arıza bilgisi sistemde tutulunca teknik servis, kat şefi ve ön büro aynı kaydı görür.","iliskili":["kh1-2-173"],"kontrol":null},{"id":"kh1-2-173","konu":"2.4","terim":"Otomasyonda arıza kaydı","ingilizce":"Defect logging in the property management system (PMS)","tanim":"Arızanın otel otomasyon programına girilmesi, teknik servisin kaydı görüp giderince not düşmesiyle yürüyen süreçtir.","ornek":"Teknik servis giderdiği arızanın yanına not girer; sipariş alıcı bu notu görüp kat şefine haber verir.","sektor":"Giderilemeyen arızalar sistemden izlenir; arızalı oda sistemde OOO olarak görünür ve ön büro rapora kaydeder.","iliskili":["kh1-2-172","kh1-2-165"],"kontrol":null},{"id":"kh1-2-174","konu":"2.5","terim":"Mini buzdolabı","ingilizce":"Minibar fridge","tanim":"Konuk odasında yiyecek ve içeceklerin bozulmadan saklanması için bulunan küçük buzdolabıdır.","ornek":"Sabah 08.30’da 215 numaralı odanın gömme dolabını açan Hatice, mini buzdolabında su, gazlı içecek ve çikolata görür.","sektor":"Oda tipine göre her odada olur; içindekiler işletme prosedürüne göre oda ücretine dâhil olabilir ya da ayrıca ücretlendirilir.","iliskili":["kh1-2-175","kh1-2-176"],"kontrol":null,"gorsel":"t11b-minibar-masa-alti"},{"id":"kh1-2-175","konu":"2.5","terim":"Mini buzdolabı ücret bilgilendirmesi","ingilizce":"Informing the guest about minibar charges","tanim":"Dolaptaki ürünlerin oda ücretine dâhil mi yoksa ekstra ücretli mi olduğunun konuğa check-in sırasında anlatılmasıdır.","ornek":"Resepsiyon görevlisi Emre, konuğa suyun ücretsiz, atıştırmalıkların ücretli olduğunu giriş sırasında söyler.","sektor":"Konuk neyin ücretli olduğunu bilirse çıkışta faturayla karşılaşınca şaşırmaz.","iliskili":["kh1-2-174","kh1-2-181"],"kontrol":null},{"id":"kh1-2-176","konu":"2.5","terim":"Mini buzdolabı yüzeyleri","ingilizce":"Minibar fridge surfaces","tanim":"Dolabın paslanmaz metal gövdesinin üzerindeki toz boya ya da ahşap görünümlü kaplamadır. Her yüzey cinsine uygun malzemeyle temizlenir.","ornek":"Ahşap görünümlü kaplı dolabın kapağını Hatice, aşındırmayan bir temizlik maddesi ve yumuşak bezle siler.","sektor":"Yüzeye uygun olmayan kimyasal boyayı matlaştırabilir ya da lekeleyebilir; bu yüzden malzeme yüzeye göre seçilir.","iliskili":["kh1-2-174","kh1-2-177"],"kontrol":null},{"id":"kh1-2-177","konu":"2.5","terim":"Mini buzdolabı temizliği","ingilizce":"Minibar fridge cleaning","tanim":"Dolabın içinin ve dışının nemli bezle silinip kurulanması, lekeli yerlerin uygun kimyasalla temizlenmesidir.","ornek":"Dolu odada Hatice, buzdolabının içini ve dışını nemli bezle siler, kuruladıktan sonra lekeli köşeye uygun kimyasal uygular.","sektor":"Dolu ve boş odalarda aynı sıra izlenir; temizlik bezi ve yüzeye uygun kimyasalla hazırlanmış su önceden yanına alınır.","iliskili":["kh1-2-176","kh1-2-178"],"kontrol":null,"gorsel":"t10b-mini-buzdolabi-ic"},{"id":"kh1-2-178","konu":"2.5","terim":"Çıkış yapılmış odada mini buzdolabı kontrolü","ingilizce":"Checking the minibar in a departure room","tanim":"Konuk çıkış yaptığında mini buzdolabının içinin kontrol edilip konuktan kalan yiyecek ve içeceğin bir poşete konulmasıdır.","ornek":"Konuğun bıraktığı yarım içecek şişesini Demet bir poşete koyar.","sektor":"Konuğa ait kalan ürün buzdolabında bırakılmaz; temizlikten önce çıkarılır.","iliskili":["kh1-2-177","kh1-2-179"],"kontrol":null},{"id":"kh1-2-179","konu":"2.5","terim":"Son kullanma tarihi kontrolü","ingilizce":"Expiry date check","tanim":"Mini buzdolabındaki yiyecek ve içeceklerin tarihinin geçip geçmediğine ve ürünün hasarlı olup olmadığına bakılmasıdır.","ornek":"Çikolatanın tarihinin geçtiğini fark eden Bora ürünü kenara alır ve yenisini ister.","sektor":"Bozulmuş ya da hasarlı ürün konuğa sunulursa hem sağlık sorunu hem güven kaybı yaşanır.","iliskili":["kh1-2-178","kh1-2-182"],"kontrol":null},{"id":"kh1-2-180","konu":"2.5","terim":"Ambar talep fişi","ingilizce":"Store requisition slip","tanim":"Mini buzdolabına konulacak ürünleri depodan almak için doldurulan ve kat şefine imzalatılan fiştir.","ornek":"Seda eksilen su ve gazozları fişe yazar, kat şefi Orhan’a imzalatır ve ambar görevlisinden imza karşılığı teslim alır.","sektor":"İmza zinciri sayesinde hangi ürünün depodan kimin eline geçtiği kayıtlı kalır.","iliskili":["kh1-2-181","kh1-2-184"],"kontrol":null},{"id":"kh1-2-181","konu":"2.5","terim":"Mini buzdolabı çeki","ingilizce":"Minibar voucher","tanim":"Konuğun mini buzdolabından kullandığı yiyecek ve içeceğin işaretlenip imzalandığı, iki nüsha hazırlanan listedir.","ornek":"Konuk akşam iki içecek almıştır; Pelin bunları çekte işaretleyip imzalar ve bir nüshayı konuğun görmesi için odada bırakır.","sektor":"Bir nüsha odada konuğa kalır, diğeri hesap işlemleri için kat görevlisinde tutulur.","iliskili":["kh1-2-175","kh1-2-182","kh1-2-183"],"kontrol":null},{"id":"kh1-2-182","konu":"2.5","terim":"Mini buzdolabının günlük kontrolü","ingilizce":"Daily minibar check","tanim":"Konuk kaldığı süre boyunca mini buzdolabının her gün kontrol edilip kullanım olup olmadığına bakılmasıdır.","ornek":"Üç gecelik konaklamada Işıl her sabah buzdolabına bakar; ikinci gün eksilen bir içeceği çeke işler.","sektor":"Tüketim her gün çeke işlenirse çıkışta fatura doğru çıkar ve itiraz azalır.","iliskili":["kh1-2-181","kh1-2-179"],"kontrol":null},{"id":"kh1-2-183","konu":"2.5","terim":"Çekin ön büroya iletilmesi","ingilizce":"Passing the minibar voucher to the front office","tanim":"Mini buzdolabı çeklerinin konuk işletmeden ayrılmadan bir gün önce ön büroya verilmesidir.","ornek":"Konuk yarın sabah ayrılacağı için Sibel bu akşam çeki ön büroya götürür.","sektor":"Ön büro faturayı önceden hazırlayabilir; çıkış günü kullanım olursa çek doldurularak yine ön büroya iletilir.","iliskili":["kh1-2-181","kh1-2-184"],"kontrol":null},{"id":"kh1-2-184","konu":"2.5","terim":"Mini buzdolabının yeni konuk için hazırlanması","ingilizce":"Restocking the minibar","tanim":"Kullanılan ürünlerin yenilenip isimleri öne gelecek şekilde yerleştirilerek buzdolabının yeni konuğa hazır hâle getirilmesidir.","ornek":"Çıkış yapılan odada Gökhan eksik ürünleri tamamlar ve etiketlerini öne çevirerek dizer.","sektor":"Düzenli dizilmiş ürünler konuğun aradığını kolay bulmasını sağlar.","iliskili":["kh1-2-180","kh1-2-183"],"kontrol":null},{"id":"kh1-2-185","konu":"2.6","terim":"Balkon","ingilizce":"Balcony","tanim":"Konuk odasından çıkılan, konuğun açık havada oturup dinlenebildiği küçük açık alandır.","ornek":"Marmaris’te deniz manzaralı odada konuk, akşamüstü 18.00’de kahvesini balkondaki masada içer.","sektor":"Manzaralı odada konuk manzarayı balkondan görür; kirli bir balkon güzel manzarayı gölgede bırakır.","iliskili":["kh1-2-186"],"kontrol":null},{"id":"kh1-2-186","konu":"2.6","terim":"Balkon temizliği","ingilizce":"Balcony cleaning","tanim":"Balkondaki zeminin, mobilyanın, camın ve korkuluğun silinip yıkanarak konuk kullanımına hazır hâle getirilmesidir.","ornek":"Sabah 11.30’da çıkış yapılan odayı bitiren Gamze balkona geçer; zemini, camı ve mobilyayı odadaki kadar özenle temizler.","sektor":"Balkon, oda standardının bir parçasıdır; konuk odaya girer girmez balkon kapısını açabilir.","iliskili":["kh1-2-185","kh1-2-187"],"kontrol":null},{"id":"kh1-2-187","konu":"2.6","terim":"Balkon temizliğinde eldiven ve maske","ingilizce":"Gloves and mask for balcony cleaning","tanim":"Kimyasal ve tozdan korunmak için temizliğe başlamadan önce takılan eldiven ve maskedir.","ornek":"Selma, kimyasallı suyla zemini yıkamadan önce eldivenini ve maskesini takar.","sektor":"İş sağlığı ve güvenliği gereği koruyucu donanım işin başında takılır, işin ortasında değil.","iliskili":["kh1-2-188","kh1-2-186"],"kontrol":null},{"id":"kh1-2-188","konu":"2.6","terim":"Balkon temizlik araç gereci","ingilizce":"Balcony cleaning equipment","tanim":"Süpürge, faraş, bez, kova, cam çekeceği, su, kimyasal ve çöp poşetinin işe başlamadan önce hazırlanmasıdır.","ornek":"Furkan balkona çıkmadan önce kovayı ve cam çekeceğini kat arabasından alır.","sektor":"Eksik araçla balkona çıkmak, ikinci kez gidip gelmek demektir; hazırlık zaman kazandırır.","iliskili":["kh1-2-187","kh1-2-197"],"kontrol":null,"gorsel":"t13c-temizlik-takimi"},{"id":"kh1-2-189","konu":"2.6","terim":"Balkondaki konuk eşyaları","ingilizce":"Guest belongings on the balcony","tanim":"Konuğun balkonda bıraktığı eşyaların dikkatle kaldırılıp iş bitince aynı yerine konması, askıdaki çamaşıra ise dokunulmaması ilkesidir.","ornek":"Konuğun balkona astığı mayo askıda durmaktadır; Gamze askıyı kımıldatmadan çevresini siler.","sektor":"Konuğun eşyasını yerinden oynatmamak mahremiyete saygıdır ve güven verir.","iliskili":["kh1-2-190","kh1-2-195"],"kontrol":null,"gorsel":"t12b-balkon-masa-fener"},{"id":"kh1-2-190","konu":"2.6","terim":"Balkondaki çöp ve izmaritin toplanması","ingilizce":"Collecting balcony waste","tanim":"Küllükteki izmaritlerin ve diğer çöplerin çöp poşetine boşaltılıp poşetin ağzının kapatılmasıdır.","ornek":"Balkon masasındaki küllüğü Taner poşete boşaltır ve poşetin ağzını bağlar.","sektor":"Ağzı kapalı poşet kokuyu ve dağılmayı önler; temizlik ona göre yapılır.","iliskili":["kh1-2-189","kh1-2-191"],"kontrol":null,"gorsel":"t10b-kulluk-izmarit"},{"id":"kh1-2-191","konu":"2.6","terim":"Yukarıdan aşağıya temizlik ilkesi","ingilizce":"Top-to-bottom cleaning","tanim":"Balkon temizliğinde kapıdan uzak noktadan başlanıp yüzeylerin yukarıdan aşağıya doğru silinmesidir.","ornek":"Aysel önce korkuluğun üstünü, sonra masayı, en son zemini siler.","sektor":"Yukarıdan düşen toz ve damlalar aşağıyı kirletir; bu sıra temizlenmiş yüzeyin yeniden kirlenmesini önler.","iliskili":["kh1-2-190","kh1-2-197"],"kontrol":null},{"id":"kh1-2-192","konu":"2.6","terim":"Balkon donanımı kontrolü","ingilizce":"Balcony fixture check","tanim":"Balkondaki kapının, korkuluğun, aydınlatmanın ve mobilyanın sağlam ve çalışır durumda olup olmadığına bakılmasıdır.","ornek":"Murat, korkuluğun vidasının gevşediğini fark edip arızayı forma yazar ve teknik servise iletir.","sektor":"Balkon yüksekte olduğundan sallanan korkuluk gibi kusurlar güvenlik konusudur ve hemen bildirilir.","iliskili":["kh1-2-193","kh1-2-195"],"kontrol":null},{"id":"kh1-2-193","konu":"2.6","terim":"Balkon aydınlatması","ingilizce":"Balcony lighting","tanim":"Lambanın kapalıyken nemli bezle silinip kurulanması ve sonra çalıştığının kontrol edilmesidir.","ornek":"Cansu akşam kullanılacak balkon lambasını nemli bezle siler ve anahtarını dener.","sektor":"Akşam balkonda oturmak isteyen konuğa lamba hazır olmalıdır.","iliskili":["kh1-2-192","kh1-2-194"],"kontrol":null,"gorsel":"t10b-balkon-lambalari"},{"id":"kh1-2-194","konu":"2.6","terim":"Balkondaki çiçekler","ingilizce":"Balcony plants","tanim":"Çiçeklerin saksılarının, altlıklarının ve yapraklarının zarar verilmeden temizlenmesidir.","ornek":"Balkonda saksı gören Ece altlıkları yıkar ve yaprakları nemli bezle usulca siler.","sektor":"Çiçekler balkonun görünümünü tamamlar; kirli saksı genel izlenimi düşürür.","iliskili":["kh1-2-193","kh1-2-195"],"kontrol":null,"gorsel":"t10b-balkon-cicekligi"},{"id":"kh1-2-195","konu":"2.6","terim":"Balkon mobilyası ve korkuluğu","ingilizce":"Balcony furniture and railing","tanim":"Masa, sandalye ve çamaşır askısı gibi mobilyalarla korkuluğun nemli bezle silinip kurulanmasıdır.","ornek":"Hüseyin sandalyenin ayaklarını ve masanın alt kenarını nemli bezle siler, ardından kurular.","sektor":"Mobilyanın ayakları ve altı gözden kaçan yerlerdir; konuğun oturduğu yerin temiz olması beklenir.","iliskili":["kh1-2-192","kh1-2-196"],"kontrol":null,"gorsel":"t10b-balkon-masa-sandalye"},{"id":"kh1-2-196","konu":"2.6","terim":"Balkon kapısı ve camı","ingilizce":"Balcony door and glass","tanim":"Odanın balkon tarafındaki camın, çerçevenin ve balkon kapısının nemli bezle silinip kurulanmasıdır.","ornek":"Balkon kapısının camında parmak izleri gören Nisa, camı silip kurular.","sektor":"Cam temiz olunca manzara net görünür; konuk bunu odaya ilk girişte fark eder.","iliskili":["kh1-2-195","kh1-2-197"],"kontrol":null,"gorsel":"t10b-balkon-cami"},{"id":"kh1-2-197","konu":"2.6","terim":"Balkon zemini ve gider","ingilizce":"Balcony floor and drain","tanim":"Zeminin gözle görülen kirinin giderilip uygun kimyasallı suyla yıkanması ya da silinmesi, giderin tıkanmamasının sağlanmasıdır.","ornek":"Fırtınadan sonra Kübra, balkon giderinde biriken yaprakları alır ve zemini yıkar.","sektor":"Tıkalı gider yağmurda balkonda su birikmesine yol açar.","iliskili":["kh1-2-191","kh1-2-198"],"kontrol":null},{"id":"kh1-2-198","konu":"2.6","terim":"Balkonda son kontrol","ingilizce":"Final balcony check","tanim":"Temizlik bittikten sonra balkonun bir kez daha gözden geçirilip eksiklerin tamamlanması ve balkon kapısının kapatılmasıdır.","ornek":"Yusuf kapıyı kapatmadan önce zeminde unutulmuş bir bez ya da damla izi olup olmadığına bakar.","sektor":"Son kontrol, küçük kusurları konuktan önce yakalar.","iliskili":["kh1-2-197","kh1-2-186"],"kontrol":null,"gorsel":"h1a-otel-balkon"},{"id":"kh1-2-199","konu":"2.7.1","terim":"Toz alma","ingilizce":"Dusting","tanim":"Odadaki donanımların ve eşyaların üzerindeki tozun nemli bezle alınmasıdır.","ornek":"Çıkış yapılmış odada Esra, giriş kapısından başlayıp saat yönünde ilerleyerek tozu alır.","sektor":"Buklet malzemeleri yerleştirilmeden önce yüzeyler tozsuz olmalıdır.","iliskili":["kh1-2-200","kh1-2-201"],"kontrol":null,"gorsel":"t12b-mikrofiber-tozlama"},{"id":"kh1-2-200","konu":"2.7.1","terim":"Toz alma sırası","ingilizce":"Dusting route","tanim":"Yüzeylerin odanın giriş kapısının yanından başlayıp saat yönünde ilerlenerek atlanmadan silinmesi, giriş kapısının kendisinin ise en son nemli bezle silinmesidir.","ornek":"Rabia kapıdan girince önce kapının yanındaki dolaptan başlar ve odayı saat yönünde dolaşır.","sektor":"Hep aynı yönde ilerlemek hiçbir yüzeyin unutulmamasını sağlar.","iliskili":["kh1-2-199","kh1-2-202","kh1-2-257"],"kontrol":null},{"id":"kh1-2-201","konu":"2.7.1","terim":"Yüzeye uygun kimyasalın seçilmesi","ingilizce":"Choosing the right chemical for the surface","tanim":"Toz alırken silinecek yüzeyin cinsine göre uygun temizlik kimyasalının seçilmesidir.","ornek":"Cam sehpa için cam temizleyiciyi, ahşap komodin için ahşaba uygun ürünü seçen Okan, ikisini karıştırmaz.","sektor":"Yanlış kimyasal yüzeyi lekeleyebilir ya da bozabilir; seçim işe başlamadan yapılır.","iliskili":["kh1-2-199","kh1-2-203"],"kontrol":null,"gorsel":"t11b-sprey-ve-bez"},{"id":"kh1-2-202","konu":"2.7.1","terim":"Çıkış yapılmış odada ayrıntılı toz alma","ingilizce":"Detailed dusting in check-out rooms","tanim":"Konuğu ayrılan oda tamamen boşaltıldığı için gardırop içi, raflar, askılar, askı borusu, çekmeceler ve valiz yeri gibi yerlerin de silindiği daha ayrıntılı toz almadır.","ornek":"Çıkış yapan konuğun odasında Yasemin gardırobun raflarını ve valiz yerini de nemli bezle siler.","sektor":"Dolu odada konuğun eşyası yerinde durduğu için toz alma daha sınırlıdır; boş odada bütün iç yüzeylere ulaşılır.","iliskili":["kh1-2-200","kh1-2-203"],"kontrol":null},{"id":"kh1-2-255","konu":"2.7.1","terim":"Yatak başı aplik ve komodin","ingilizce":"Bedside lights and bedside tables","tanim":"Yatağın iki yanındaki apliklerin, yatak başının, komodinlerin ve çekmecelerinin toz alma sırasında nemli bezle silinip kurulanmasıdır.","ornek":"Sabah 10.15’te 508 numaralı odada Gül, komodinlerin üstünü, çekmece kenarlarını ve aplik kollarını nemli bezle silip kurular; yatak başında toz kalmadığını kontrol eder.","sektor":"Konuk geceyi yatağın hemen yanında geçirir; aplik ve komodinde kalan toz ya da leke ilk orada fark edilir. Aplik gibi ışık veren parçalarda bez iyice sıkılır.","iliskili":["kh1-2-203","kh1-2-256"],"kontrol":null,"gorsel":"os-single-room"},{"id":"kh1-2-256","konu":"2.7.1","terim":"Klima kumanda paneli ve ızgaraları","ingilizce":"Air-conditioning control panel and grilles","tanim":"Odadaki klima kumanda panelinin ve hava ızgaralarının toz alma sırasında nemli bezle silinip kurulanmasıdır.","ornek":"Öğleden sonra 14.20’de 312 numaralı odada Seda, duvardaki klima kumanda panelini ve ızgaraları nemli bezle silip kurular; ızgara aralarında toz birikmediğini kontrol eder.","sektor":"Kumanda paneline konuk sık dokunur, ızgaralarda biriken toz da kolay göze çarpar; ikisi de toz alma turunda atlanmaz.","iliskili":["kh1-2-255","kh1-2-204"],"kontrol":null,"gorsel":"t15ac-klima-kumanda"},{"id":"kh1-2-257","konu":"2.7.1","terim":"Giriş kapısının silinmesi","ingilizce":"Wiping the room entrance door","tanim":"Toz alma turunun sonunda odanın giriş kapısının nemli bezle silinip kurulanmasıdır.","ornek":"Sabah 11.00’de 204 numaralı odanın toz almasını bitiren Mert, en son giriş kapısını ve kol çevresini nemli bezle siler.","sektor":"Kapı konuğun odaya girerken ilk gördüğü ve dokunduğu yüzeydir; en sona bırakılması silme turunun kapıda tamamlanmasını sağlar.","iliskili":["kh1-2-200","kh1-2-256"],"kontrol":null},{"id":"kh1-2-203","konu":"2.7.1","terim":"Ayna, aplik ve makyaj masasının tozu","ingilizce":"Dusting the mirror, wall lights and dressing table","tanim":"Makyaj aynasının, apliklerin, makyaj masasının ve çekmecelerinin nemli bezle silinip kurulanmasıdır.","ornek":"Makyaj masasının çekmecesini de silen Tülin, aynada toz kalmadığını kurulayarak görür.","sektor":"Ayna ve aplik konuğun en çok baktığı yerlerdendir; kalan toz hemen fark edilir.","iliskili":["kh1-2-202","kh1-2-204"],"kontrol":null,"gorsel":"t11b-ayna-aplik"},{"id":"kh1-2-204","konu":"2.7.1","terim":"Elektrikli aletlerin tozunun alınması","ingilizce":"Dusting electrical items","tanim":"Televizyon ünitesinin elektrik bağlantısı kesilerek, elektrik düğmelerinin ve priz girişlerinin ise dikkatle ve az nemli bezle silinmesidir.","ornek":"Hande televizyon ünitesini silmeden önce fişi çeker; priz çevresini bezi iyice sıkarak siler.","sektor":"Islak bez ve elektrik bir araya gelirse hem kişi hem cihaz zarar görebilir; bu yüzden televizyon ünitesinin bağlantısı kesilir, düğme ve priz çevresi bezi iyice sıkarak silinir.","iliskili":["kh1-2-203","kh1-2-205"],"kontrol":null},{"id":"kh1-2-205","konu":"2.7.1","terim":"Toz bezinin yıkanması","ingilizce":"Rinsing dusting cloths","tanim":"Silme sırasında kirlenen bezin, tozu yaymadan almaya devam edebilmesi için sık sık durulanıp sıkılmasıdır.","ornek":"Odanın yarısında bezin grileştiğini gören Nergis, bezi yıkayıp sıkarak devam eder.","sektor":"Kirli bez tozu yüzeyden almak yerine yüzeye yayar.","iliskili":["kh1-2-204","kh1-2-199"],"kontrol":null},{"id":"kh1-2-260","konu":"2.7.1","terim":"Duvar tablosu, sehpa ve koltuk ayaklarının tozu","ingilizce":"Dusting wall pictures, coffee tables and chair legs","tanim":"Toz alma turunda duvar tablosunun ve apliğinin, sehpaların ve koltuk ayaklarının nemli bezle silinip kurulanmasıdır.","ornek":"Öğleden sonra 15.10’da 410 numaralı odada Elif, sehpanın kenarlarını ve koltuk ayaklarını nemli bezle siler; duvardaki tablonun çerçevesinde toz kalmadığını kontrol eder.","sektor":"Alçakta kalan ayaklar ve yüksekteki tablo çerçevesi gözden kaçmaya en yatkın yerlerdir; silme turunda atlanmaz.","iliskili":["kh1-2-199","kh1-2-203"],"kontrol":null},{"id":"kh1-2-261","konu":"2.7.1","terim":"Mini buzdolabının üstü ve çevresinin tozu","ingilizce":"Dusting the top of the minibar and its surroundings","tanim":"Toz alma turunda mini buzdolabının üstünün ve etrafının nemli bezle silinip kurulanmasıdır.","ornek":"Sabah 09.50’de 307 numaralı odada Ayşe, toz alma sırasında mini buzdolabının üstünü ve yanındaki rafı nemli bezle silip kurular.","sektor":"Dolabın içi ve dış yüzeyi mini buzdolabı temizliğinde ayrıca yapılır; toz alma turunda ise üstü ve çevresi atlanmaz.","iliskili":["kh1-2-199","kh1-2-174"],"kontrol":null},{"id":"kh1-2-206","konu":"2.7.1","terim":"Renk kodlu temizlik bezleri","ingilizce":"Colour-coded cloths","tanim":"Temizlenecek alanın cinsine göre farklı renkte bez kullanılması düzenidir.","ornek":"Kat ofisinden bezleri alan Sevgi, her rengin ayrı bir alan için olduğunu bildiği için bezleri karıştırmaz.","sektor":"Renk ayrımı mikrop bulaşını, hastalık ve salgın riskini azaltır; hangi rengin hangi alanda kullanılacağı işletmeye göre değişebilir ve oda görevlisi bez rengini kendisi seçmez.","iliskili":["kh1-2-207","kh1-2-208","kh1-2-211"],"kontrol":null,"gorsel":"t15ac-renkli-bezler"},{"id":"kh1-2-207","konu":"2.7.1","terim":"Kırmızı bez","ingilizce":"Red cloth","tanim":"Tuvalet klozet kapağı ve pisuar çevresi gibi hijyen riski yüksek alanların temizliği için ayrılan bezdir.","ornek":"Klozet çevresini silen Berk, işi bitince kırmızı bezi ayrı bir torbaya koyar.","sektor":"Kırmızı bez tuvalet dışında kullanılmaz; işletmedeki herkes aynı renk kodunu uygular.","iliskili":["kh1-2-206","kh1-2-208"],"kontrol":null},{"id":"kh1-2-208","konu":"2.7.1","terim":"Sarı bez","ingilizce":"Yellow cloth","tanim":"Lavabo, armatür ve küvet gibi ıslak alanların temizliği için ayrılan bezdir.","ornek":"Banyoda lavaboyu ve bataryayı sarı bezle silen Derya, aynı bezi klozete götürmez.","sektor":"Islak alan bezi ile tuvalet bezi karıştırılırsa mikrop yayılır.","iliskili":["kh1-2-207","kh1-2-209"],"kontrol":null,"gorsel":"t12r-sari-bez-lavabo"},{"id":"kh1-2-209","konu":"2.7.1","terim":"Mavi ve yeşil bez (işletmeye göre)","ingilizce":"Blue and green cloths","tanim":"Ders kitabına göre mavi (ya da pembe) bez cam ve toz alma gibi genel alanlarda, yeşil bez banyo zemininde kullanılan, hangi renge hangi alanın ayrıldığı işletmeye göre değişen bezlerdir.","ornek":"Yeni başladığı otelde Mine, hangi rengin hangi alana ayrıldığını ilk gün kat şefinden öğrenir.","sektor":"Kırmızı ve sarı gibi kesin bilinen kullanımların yanında mavi ve yeşilin anlamı işletmenin kendi renk kodu tablosuna bağlıdır.","iliskili":["kh1-2-206","kh1-2-210"],"kontrol":null,"gorsel":"t10b-mavi-bez"},{"id":"kh1-2-210","konu":"2.7.1","terim":"Tek kullanımlık havlu","ingilizce":"Disposable paper towel","tanim":"Hijyen riski yüksek alanlarda bez yerine tercih edilebilen, kullanıldıktan sonra atılan havludur.","ornek":"Odadaki bardakları Batuhan kâğıt havluyla siler ve havluyu çöpe atar.","sektor":"Bardaklar kâğıt havlu ile silinebilir; işletmeler yüksek riskli alanlarda bezden çok tek kullanımlık havluyu seçebilir.","iliskili":["kh1-2-209","kh1-2-211"],"kontrol":null,"gorsel":"os-kagit-havlu"},{"id":"kh1-2-211","konu":"2.7.1","terim":"Çapraz bulaşma","ingilizce":"Cross-contamination","tanim":"Mikropların bir alandan başka bir alana temizlik araçları ve bezlerle taşınmasıdır.","ornek":"Sabah 10.00’da Nur, kırmızı bezi yalnız klozet çevresinde kullanır ve bardakları ayrı bir bezle siler; böylece mikroplar tuvaletten bardağa taşınmaz.","sektor":"Renkli bezlerin ve tek kullanımlık havluların asıl amacı çapraz bulaşmayı önlemektir.","iliskili":["kh1-2-206","kh1-2-210"],"kontrol":null,"kitapDisi":true},{"id":"kh1-2-212","konu":"2.7.1","terim":"Oda temizliği öncelik sırası","ingilizce":"Room cleaning priority order","tanim":"Temizlenecek odaların hangi sırayla ele alınacağını belirleyen düzendir.","ornek":"Sabah vardiyasında Aslı, “odamı hemen temizleyin” kartı asılmış odayı sıradaki dolu odadan önce yapar.","sektor":"Genellikle sıra şöyledir: VIP ve erişilebilir oda, “odamı hemen temizleyin” yazılı oda, çıkış/giriş (C/O ve yeni giriş) odası, çıkış odası, dolu oda, boş oda.","iliskili":["kh1-2-199","kh1-2-211"],"kontrol":null},{"id":"kh1-2-213","konu":"2.7.2","terim":"Buklet malzemeleri","ingilizce":"Guest amenities","tanim":"Konuk odasında konuğun ihtiyaçlarını karşılayan kırtasiye, oda bilgi kartları, kapı kolu kartları ve eşantiyon gibi malzemelerin genel adıdır.","ornek":"Odaya giren konuk, TV masasında otel kartlarını, kalemi ve not kâğıdını hazır bulur.","sektor":"Buklet malzemeleri işletmenin saygınlık göstergesidir; kullanılan malzeme işletmenin standardına, hizmet çeşidine ve yıldızına göre değişir.","iliskili":["kh1-2-214","kh1-2-216"],"kontrol":null,"gorsel":"t12b-banyo-set-cam-raf"},{"id":"kh1-2-214","konu":"2.7.2","terim":"Kırtasiye malzemeleri","ingilizce":"Stationery","tanim":"Konuğun kullanması için odaya konulan dosya, zarf, faks kâğıdı, A4 kâğıdı, blok not ve kalem gibi malzemelerdir.","ornek":"Oda görevlisi Pınar, TV masasının üzerine dosyayı, blok notu ve kalemi konuğun hemen göreceği yere dizer.","sektor":"Kırtasiye malzemesi televizyon masasında en çok görünen yere konur.","iliskili":["kh1-2-213","kh1-2-215"],"kontrol":null,"gorsel":"h3b-malzeme-kutusu"},{"id":"kh1-2-215","konu":"2.7.2","terim":"Anket formu","ingilizce":"Guest comment card","tanim":"Konuğun işletmeyle ilgili memnuniyetini, önerisini ya da şikâyetini yazabilmesi için hazırlanan formdur.","ornek":"Odadaki anket formunu doldurup resepsiyona bırakan konuk, banyodaki sıcak suyun geç geldiğini yazar.","sektor":"Konuk düşüncelerini rahatça söylesin diye ad soyad istenmez; sonuçlara göre işletme değişiklik yapabilir.","iliskili":["kh1-2-213","kh1-2-216"],"kontrol":null},{"id":"kh1-2-216","konu":"2.7.2","terim":"Otel bilgi kartları","ingilizce":"Hotel information cards","tanim":"Konuğun otelin hizmetleri, telefon numaraları ve odadaki donanımlar hakkında bilgi alması ve özel isteklerini bildirmesi için odada bulunan kartlardır.","ornek":"Konuk kasa kullanım kartını okuyup kasayı ilk denemede kapatır.","sektor":"Kartlar arasında sigara içilmeyen oda, çevre, telefon, iyi geceler, welcome, mutluluklar, odanızı ben temizledim, bornoz, iste gelsin, kasa kullanım, klima kullanım, şezlong bilgilendirme ve nevresim değişim kartları sayılabilir.","iliskili":["kh1-2-213","kh1-2-049"],"kontrol":null},{"id":"kh1-2-259","konu":"2.7.2","terim":"Kahvaltı kartı","ingilizce":"Breakfast door hanger","tanim":"Konuğun kahvaltıyla ilgili isteğini kapı koluna asarak bildirdiği kapı kolu kartıdır.","ornek":"Konuk akşam kahvaltı kartını doldurup kapı koluna asar; sabah görevli kartı görür ve isteği ilgili bölüme iletir.","sektor":"DND ve “Lütfen odayı şimdi hazırlayınız” kartlarıyla birlikte kat hizmetleri ile konuk arasında sessiz iletişim sağlayan kapı kolu kartlarındandır.","iliskili":["kh1-2-049","kh1-2-050"],"kontrol":null},{"id":"kh1-2-220","konu":"2.7.2","terim":"Çamaşırhane listesi ve torbası","ingilizce":"Laundry list and bag","tanim":"Konuğun kirli giysilerini çamaşırhaneye göndermesi için hazırlanan, bütün giysi gruplarının yazılı olduğu liste ile torbadır.","ornek":"Konuk gömleklerini listede işaretleyip torbaya koyar; Esin torbayı konuktan belgeyle teslim alır.","sektor":"Çamaşır, oda temizleme görevlisi tarafından konuktan belgeyle teslim alınır; liste ve torba gardırobun içine konur.","iliskili":["kh1-2-213","kh1-2-221"],"kontrol":null},{"id":"kh1-2-221","konu":"2.7.2","terim":"Konuk eşantiyon malzemeleri","ingilizce":"Complimentary guest amenities","tanim":"Konuğun odada ihtiyaç duyabileceği, hatıra olarak da götürebileceği küçük hediyelerdir.","ornek":"Sabah 10.30’da Nehir banyoya şampuan ve diş fırçası setini koyar; konuk çıkışta setleri hatıra olarak valizine yerleştirir.","sektor":"Eşantiyonlar sayesinde konuğun gönlü kazanılır ve otelin reklamı yapılmış olur.","iliskili":["kh1-2-222","kh1-2-223"],"kontrol":null},{"id":"kh1-2-222","konu":"2.7.2","terim":"Ayakkabı bakım malzemeleri","ingilizce":"Shoe-care items","tanim":"Konuğun ayakkabısını silmesi ve giymesi için odada bulunan ayakkabı bezi ve çekeceği gibi eşantiyonlardır.","ornek":"Toplantıya giden konuk, ayakkabı bezini ve çekeceğini kapının yanındaki rafta bulur.","sektor":"Küçük bir eşantiyon bile konuğun düşünüldüğünü hissettirir.","iliskili":["kh1-2-221","kh1-2-224"],"kontrol":null,"gorsel":"t12r-ayakkabi-bakim"},{"id":"kh1-2-223","konu":"2.7.2","terim":"Dikiş seti","ingilizce":"Sewing kit","tanim":"Düğmesi kopan ya da dikişi sökülen giysiyi onarmak için odada bulunan küçük iğne iplik takımıdır.","ornek":"Gömleğinin düğmesi kopan konuk, dikiş setini komodinin çekmecesinde bulur.","sektor":"Acil küçük bir sorunu çözen set, konuğun resepsiyonu aramasına gerek bırakmaz.","iliskili":["kh1-2-221","kh1-2-224"],"kontrol":null},{"id":"kh1-2-224","konu":"2.7.2","terim":"Terlik (normal ve VIP)","ingilizce":"Slippers (standard and VIP)","tanim":"Konuğun odada ve banyoda kullanması için konulan, normal ve VIP konuklara özel olarak ayrılabilen terliklerdir.","ornek":"VIP konuk için Selen, normal terlik yerine otelin VIP terliğini yatağın yanına koyar.","sektor":"VIP konuk için kullanılan terlik, işletmenin özel konuklara ayrıcalık tanıdığını gösterir.","iliskili":["kh1-2-222","kh1-2-225"],"kontrol":null},{"id":"kh1-2-262","konu":"2.7.2","terim":"Eşantiyon listesindeki diğer küçük malzemeler","ingilizce":"Other small room amenities","tanim":"Ayakkabı bakımı, dikiş seti, mendil ve bardak kapağı dışında eşantiyon listesinde sayılan kibrit, takvim ve bardak gibi küçük malzemelerdir.","ornek":"Sabah 10.40’ta Nehir, komodinin üstüne otelin takvimini ve kibrit kutusunu yerleştirir.","sektor":"Eşantiyon listesi işletmenin düzeyine ve konseptine göre değişir; her otelde aynı kalemler bulunmaz.","iliskili":["kh1-2-221","kh1-2-224"],"kontrol":null},{"id":"kh1-2-225","konu":"2.7.2","terim":"Kolonya ve mendil","ingilizce":"Eau de cologne and tissues","tanim":"Konuğun ferahlaması ve temizlenmesi için odada bulunan kolonya, kutu mendil ve kolonyalı mendildir.","ornek":"Hava sıcak olduğu için Bülent kolonyalı mendili konuğun göreceği yere bırakır.","sektor":"Kolonyalı mendil sıcak havada ya da yolculuk sonrası konuğa ferahlık verir.","iliskili":["kh1-2-221","kh1-2-226"],"kontrol":null,"gorsel":"t10b-mendil-kutusu"},{"id":"kh1-2-226","konu":"2.7.2","terim":"Bardak kapağı","ingilizce":"Glass cover","tanim":"Odadaki bardakların üstünü örterek hijyenini koruyan kapaktır.","ornek":"Banyodaki bardağın üstünde kâğıt bardak kapağı durur; konuk bardağın temiz olduğunu anlar.","sektor":"Kapak, bardağın temizlendiğini ve kullanılmadığını gösterir.","iliskili":["kh1-2-225","kh1-2-227"],"kontrol":null},{"id":"kh1-2-227","konu":"2.7.2","terim":"Çocuklu aile seti","ingilizce":"Children’s amenity set","tanim":"Aile ve çocuk konuklara hizmet veren otellerde odaya konulan vücut losyonu, şampuan, güneş kremi, sabun, diş fırçası, bornoz, terlik ve plaj havlusu gibi malzemelerdir.","ornek":"Çocuklu ailenin odasında Ela, çocuk bornozunu ve plaj havlusunu yatağın üzerine hazırlar.","sektor":"Otelin kalitesine, hizmet çeşidine ve konseptine göre buklet malzemeleri çeşitlenir.","iliskili":["kh1-2-228","kh1-2-230"],"kontrol":null},{"id":"kh1-2-228","konu":"2.7.2","terim":"Plaj malzemeleri","ingilizce":"Beach items","tanim":"Lüks otellerde tüm konuklara verilebilen plaj havlusu gibi plajda kullanılan malzemelerdir.","ornek":"Sahildeki otelde Ela, plaj havlusunu oda görevlisinin yerleştirdiği malzemeler arasında bulur.","sektor":"Her otelde verilmez; işletmenin düzeyine ve konseptine göre sunulur.","iliskili":["kh1-2-227","kh1-2-230"],"kontrol":null,"gorsel":"t10c-plaj-havlusu"},{"id":"kh1-2-229","konu":"2.7.2","terim":"Su ısıtıcısı, poşet çay ve kahve","ingilizce":"Kettle, tea bags and coffee","tanim":"Buklet malzemesi sayılmayan ama işletmelerin konuğun kullanımı için odaya koyabildiği içecek hazırlama takımıdır.","ornek":"Akşam odasına çıkan konuk, su ısıtıcısıyla poşet çayını kendisi demler.","sektor":"Konuk resepsiyona telefon etmeden küçük bir içecek molası verebilir.","iliskili":["kh1-2-213","kh1-2-231"],"kontrol":null,"gorsel":"t11b-su-isitici-tepsi"},{"id":"kh1-2-230","konu":"2.7.2","terim":"Özel konuklar için ekstra malzeme","ingilizce":"Extra amenities for special guests","tanim":"VIP, erişim ihtiyacı olan, tekrar gelen ya da hasta konuk gibi özel durumu olan konukların odasına işletme prosedürüne göre ekstra malzeme konulmasıdır.","ornek":"İkinci kez gelen konuğun odasına Pelin, işletme prosedürüne göre ekstra bir hoş geldin kartı bırakır.","sektor":"Ekstra malzeme yalnız işletme prosedüründe varsa konulur; görevli kendi kendine karar vermez.","iliskili":["kh1-2-231","kh1-2-227"],"kontrol":null,"gorsel":"g3-karsilama-sepeti"},{"id":"kh1-2-231","konu":"2.7.2","terim":"Tekrar gelen konuk (repeat guest)","ingilizce":"Repeat guest","tanim":"Daha önce aynı otelde konaklamış olup yeniden gelen konuktur.","ornek":"Üçüncü kez gelen konuk için resepsiyon, odasına ekstra malzeme konmasını ister.","sektor":"Tekrar gelen konuğa gösterilen özen, onun otele bağlanmasını sağlar.","iliskili":["kh1-2-230","kh1-2-213"],"kontrol":null},{"id":"kh1-2-232","konu":"2.7.2","terim":"Buklet malzemesi yerleştirme kuralları","ingilizce":"Amenity placement rules","tanim":"Malzemelerin kullanım amacına göre yerleştirilmesi, konuğun aradığını aramadan bulması kuralıdır.","ornek":"Sabah odayı hazırlayan Aysu banyo malzemelerini banyoya, kırtasiyeyi TV masasına, çamaşırhane listesini gardırop içine koyar.","sektor":"Banyo malzemeleri banyoya, kırtasiye malzemeleri TV masasına, çamaşırhane listesi ve torbası gardırop içine, eşantiyonlar kullanım yerlerine konur.","iliskili":["kh1-2-233","kh1-2-234"],"kontrol":null,"gorsel":"t10a-banyo-seti"},{"id":"kh1-2-233","konu":"2.7.2","terim":"Amblemin görünür yerleştirilmesi","ingilizce":"Placing the hotel logo in view","tanim":"Buklet malzemeleri yerleştirilirken işletmenin adının ve amblemin üst kısımda ve görünür durmasıdır.","ornek":"Bilgi kartlarını TV masasına koyan Cem, otelin amblemi üstte ve okunur olacak şekilde çevirir.","sektor":"Amblem görünür olduğunda malzeme işletmenin imajını taşır.","iliskili":["kh1-2-232","kh1-2-234"],"kontrol":null},{"id":"kh1-2-234","konu":"2.7.2","terim":"Kişi sayısı kadar buklet malzemesi","ingilizce":"One set of amenities per guest","tanim":"Konuk odasında kalan kişi sayısı kadar buklet malzemesinin kat arabasından alınarak yerleştirilmesidir.","ornek":"İki kişilik odaya Burcu iki terlik ve iki set koyar.","sektor":"Eksik malzeme konuğun resepsiyonu aramasına yol açar; fazlası israftır.","iliskili":["kh1-2-232","kh1-2-233"],"kontrol":null},{"id":"kh1-2-235","konu":"2.7.3","terim":"Süpürme","ingilizce":"Sweeping and vacuuming","tanim":"Yüzeydeki görünen ve görünmeyen kirin araçlar kullanılarak ortamdan alınmasıdır.","ornek":"Odayı toparladıktan sonra Banu son iş olarak zemini süpürür.","sektor":"Görevlinin odaya son bakışı konuğun ilk bakışıdır; zemin temizliği bu bakışa dâhildir.","iliskili":["kh1-2-236","kh1-2-237"],"kontrol":null,"gorsel":"t12b-supurge-hali"},{"id":"kh1-2-236","konu":"2.7.3","terim":"Elektrikli süpürge","ingilizce":"Vacuum cleaner","tanim":"Zemindeki toz ve kiri emerek toplayan, kabloyla elektriğe bağlanan temizlik makinesidir.","ornek":"Banu süpürgeyi kullanma talimatına göre hazırlar ve çalıştırır.","sektor":"Makine talimatına göre kullanılırsa görevli yorulmaz ve zemin zarar görmez.","iliskili":["kh1-2-235","kh1-2-241"],"kontrol":null,"gorsel":"t15ac-elektrikli-supurge"},{"id":"kh1-2-237","konu":"2.7.3","terim":"Zemin çeşitleri","ingilizce":"Flooring types","tanim":"Konuk odalarında kullanılan halı, PVC, taş ve ahşap gibi zemin kaplama malzemeleridir.","ornek":"Sabah 09.00’da yeni açılan katı gezen kat şefi Hülya, oda zeminlerinin ahşap, banyo zeminlerinin taş olduğunu not eder.","sektor":"Zemin işletmenin konseptine göre seçilir; hijyen nedeniyle halı kullanımı azalmış, kaliteli PVC, taş ya da ahşap tercih edilmeye başlanmıştır.","iliskili":["kh1-2-235","kh1-2-238"],"kontrol":null,"gorsel":"t11b-parke-koridor"},{"id":"kh1-2-238","konu":"2.7.3","terim":"Halılı odalar","ingilizce":"Carpeted rooms","tanim":"Zemini halıyla kaplı olan, genellikle soğuk bölgelerdeki ve kış turizmine hitap eden işletmelerde bulunan odalardır.","ornek":"Soğuk bir dağ bölgesindeki kayak otelinde odaların zemini halıyla kaplıdır.","sektor":"Halı antialerjik, antibakteriyel, kolay temizlenebilir ve kir tutmayan türde olmalıdır; astım hastası ve ev akarı alerjisi olan konuklar için bu özellikle önemlidir.","iliskili":["kh1-2-237","kh1-2-241"],"kontrol":null,"gorsel":"t11b-halili-oda"},{"id":"kh1-2-239","konu":"2.7.3","terim":"Süpürmede doğru duruş","ingilizce":"Posture while vacuuming","tanim":"Süpürürken dik durulması, sağ ayağın önde tutulması ve yükün belde değil kollarda olmasıdır.","ornek":"Süpürürken Arda dizini hafifçe bükerek dik durur ve yükü kollarına verir.","sektor":"Doğru duruş yorgunluğu ve bel ağrısı riskini azaltır.","iliskili":["kh1-2-236","kh1-2-240"],"kontrol":null},{"id":"kh1-2-240","konu":"2.7.3","terim":"Süpürge kablosunun yönetimi","ingilizce":"Cable handling","tanim":"Elektrikli süpürge kablosunun odanın en uzak noktasına yetişecek kadar uzatılması ve süpürülürken kabloya ve ayağa zarar vermeden ilerlenmesidir.","ornek":"Banu kabloyu önce odanın en uzak köşesine yetişecek kadar açar, sonra kabloya basmamaya dikkat ederek ilerler.","sektor":"Yetersiz uzunluk süpürmeyi yarıda kestirir; kabloya basmak hem kabloya hem görevliye zarar verir.","iliskili":["kh1-2-239","kh1-2-236"],"kontrol":null},{"id":"kh1-2-241","konu":"2.7.3","terim":"Zemine uygun süpürge aparatı","ingilizce":"Floor attachment","tanim":"Zeminin halı mı yoksa sert zemin mi olduğuna göre süpürgeye takılan başlıktır.","ornek":"Ahşap zeminli odada Barış sert zemin aparatını takar; halılı odada halı aparatını kullanır.","sektor":"Yanlış aparat zeminin kirini almaz ya da zemini çizebilir.","iliskili":["kh1-2-236","kh1-2-242"],"kontrol":null,"gorsel":"t10b-supurge-basligi"},{"id":"kh1-2-242","konu":"2.7.3","terim":"Süpürme öncesi zemin hazırlığı","ingilizce":"Floor check before vacuuming","tanim":"Süpürmeden önce zeminde çivi, toka gibi süpürgeye zarar verecek parçaların ve sandalye, puf gibi taşınabilir eşyaların kaldırılmasıdır.","ornek":"Tolga halıda küçük bir toka bulur ve süpürgeye çekilmemesi için alır; sandalyeyi de kenara çeker.","sektor":"Süpürgeyi bozacak parçalar önceden alınırsa makine zarar görmez ve süpürme kesintisiz yapılır.","iliskili":["kh1-2-241","kh1-2-243"],"kontrol":null},{"id":"kh1-2-243","konu":"2.7.3","terim":"Süpürme yönü","ingilizce":"Vacuuming direction","tanim":"Süpürmeye odanın giriş kapısına en uzak yerden başlanması ve halıda dokunun tersi yönünde ilerlenmesidir.","ornek":"Banu önce balkon kapısının yanından başlar, süpürdüğü yerlere tekrar basmamak için girişe doğru ilerler.","sektor":"En uzak noktadan başlayıp kapıya doğru ilerlemek, temizlenmiş zemine yeniden basılmasını önler.","iliskili":["kh1-2-242","kh1-2-244"],"kontrol":null},{"id":"kh1-2-244","konu":"2.7.3","terim":"Süpürme sonrası toparlama","ingilizce":"Tidying up after vacuuming","tanim":"İş bitince süpürgenin toplanıp kat arabasına konması, odada son kontrolün yapılıp kapının kapatılmasıdır.","ornek":"Banu süpürgeyi toplar, son kez odaya bakar ve kapıyı kapatır; gün sonunda araç gereci temizleyip kat ofisine koyar.","sektor":"Araç gereç özelliğine göre temizlenip kat ofisindeki yerine konur; böylece ertesi gün hazır olur.","iliskili":["kh1-2-243","kh1-2-245"],"kontrol":null},{"id":"kh1-2-245","konu":"2.7.3","terim":"Odaya son bakış","ingilizce":"The final look","tanim":"Görevlinin odayı kapatmadan önce her yeri son kez gözden geçirmesidir.","ornek":"Burcu kapıyı kapatmadan önce yastıkları ve perdeyi bir kez daha gözden geçirir.","sektor":"Odaya son bakış, konuk girdiğinde gördüğü ilk manzaradır; küçük kusurlar son anda yakalanır.","iliskili":["kh1-2-244","kh1-2-235"],"kontrol":null},{"id":"kh1-2-246","konu":"2.7.3","terim":"Konukla samimi ama laubali olmayan iletişim","ingilizce":"Friendly but professional communication","tanim":"Görevlinin konuğa her zaman içten ve kibar davranıp asla laubali bir dile geçmemesi ilkesidir.","ornek":"Koridorda konukla karşılaşan Emel gülümseyerek selam verir, şakalaşmaya girmez.","sektor":"Kibar ama mesafeli dil, konuğa saygıyı ve güveni birlikte verir.","iliskili":["kh1-2-247","kh1-2-250"],"kontrol":null},{"id":"kh1-2-247","konu":"2.7.3","terim":"Konuğu dinleme ve kısa, net yanıt","ingilizce":"Listening and clear answers","tanim":"Konuğun sorusunu dikkatle ve saygıyla dinleyip kısa, açık ve net cevap vermek, uzun konuşmalardan kaçınmaktır.","ornek":"Konuk havlu istediğinde Kaan sözü kesmeden dinler ve “Hemen getiriyorum efendim” der.","sektor":"Kısa ve net cevap konuğun vaktine saygıdır.","iliskili":["kh1-2-246","kh1-2-248"],"kontrol":null},{"id":"kh1-2-248","konu":"2.7.3","terim":"Konuk haklıdır ilkesi","ingilizce":"“The guest is always right” principle","tanim":"Haksız bile olsa şikâyet eden konuk karşısında soğukkanlı ve kibar kalınıp sorunun giderilmeye çalışılması ilkesidir.","ornek":"Odası aslında temizlenmiş olan konuk “oda temizlenmedi” diye kızınca Sude tartışmaz, özür diler ve kat şefini çağırır.","sektor":"Görevli tartışmaz; sorunu çözmeye çalışır, çözemezse kat şefine iletir.","iliskili":["kh1-2-247","kh1-2-254"],"kontrol":null},{"id":"kh1-2-249","konu":"2.7.3","terim":"Oda telefonuna cevap verilmemesi","ingilizce":"Not answering the guest-room phone","tanim":"Oda temizleme görevlisinin çalıştığı odanın telefonunu hiçbir zaman açmamasıdır.","ornek":"Temizlik sırasında oda telefonu çalar; Kerime açmaz ve işine devam eder.","sektor":"Konuğa ait hatta görevlinin cevap vermesi mahremiyeti zedeler.","iliskili":["kh1-2-250","kh1-2-254"],"kontrol":null},{"id":"kh1-2-250","konu":"2.7.3","terim":"Hitap kuralları","ingilizce":"Forms of address","tanim":"Kişilere mümkün olduğunca adlarıyla ve “bey/hanım” diyerek hitap edilmesi, konuklara ve çalışma arkadaşlarına “sen” yerine “siz” denmesi, çağrıldığında “Efendim” diye karşılık verilmesidir.","ornek":"Koridorda adı seslenen Mehmet Bey’e Ceren “Efendim, buyurun” der.","sektor":"Saygılı hitap, otelin kalitesini yansıtır ve hem konuğa hem ekip arkadaşına güven verir.","iliskili":["kh1-2-246","kh1-2-249"],"kontrol":null},{"id":"kh1-2-251","konu":"2.7.3","terim":"İşletme sorunlarının konuğa anlatılmaması","ingilizce":"Not discussing hotel problems with guests","tanim":"İşletmeyle ilgili sorunların kesinlikle konuklara aktarılmamasıdır.","ornek":"Konuk sorunca Aylin, personel eksikliğinden söz etmez; “Bunu kat şefimize ileteyim” der.","sektor":"Konuğun bilmesi gerekmeyen iç sorunlar konuyu büyütür ve güveni zedeler.","iliskili":["kh1-2-248","kh1-2-254"],"kontrol":null},{"id":"kh1-2-252","konu":"2.7.3","terim":"Sessiz çalışma","ingilizce":"Working quietly","tanim":"Konuk oda kapılarının sessizce açılıp kapatılması, elektrikli süpürge gibi ses çıkaran araçların konuklar kattan ayrıldıktan sonra kullanılmasıdır.","ornek":"Erkenden kata çıkan Barış, konuklar kahvaltıya inene kadar süpürgeyi çalıştırmaz.","sektor":"Gürültü konuğun uykusunu ve dinlenmesini bozar; sessizlik hizmetin bir parçasıdır.","iliskili":["kh1-2-253","kh1-2-249"],"kontrol":null},{"id":"kh1-2-253","konu":"2.7.3","terim":"Koridorda profesyonel duruş","ingilizce":"Professional conduct in the corridor","tanim":"Koşmadan ve dik yürümek, konuşurken bir yere dayanmamak, konukla karşılaşınca selam vermektir.","ornek":"Koridorda konuğu gören Tuğçe yürümeyi bırakmaz ama gülümseyerek selam verir.","sektor":"Duruş ve davranış, konuğun kat görevlisine duyduğu güveni belirler.","iliskili":["kh1-2-252","kh1-2-246"],"kontrol":null},{"id":"kh1-2-254","konu":"2.7.3","terim":"İlk başvuru kişisi: kat sorumlusu","ingilizce":"First point of contact: floor supervisor","tanim":"Herhangi bir sorunda ilk başvurulacak kişinin kat sorumlusu (kat şefi) olduğunu bilmektir.","ornek":"Odada beklenmedik bir durumla karşılaşan Defne önce kat şefine haber verir.","sektor":"Kararı kendi başına vermek yerine yetkili kişiye ulaşmak hata riskini azaltır.","iliskili":["kh1-2-248","kh1-2-251"],"kontrol":null}],"sorular":[{"id":"kh1-2-s001","tur":"coktan-secmeli","soru":"Kat şefi, pazartesi sabahı çok sayıda odanın çıkış yapacağını görüyor. İş planını bu duruma göre nasıl değiştirir?","secenekler":["Standart temizlik sürelerini kısaltarak aynı ekiple yetişmeye çalışır","İş sağlığı ve güvenliği adımlarını azaltarak zaman kazanır","Odaların tiplerini değiştirerek dağılımı hafifletir","Personel ihtiyacını artırıp ekibe ek bir oda görevlisi ayırır"],"dogru":3,"aciklama":"İş planı iş yoğunluğuna ve personel ihtiyacına göre kurulur. Süreleri ya da güvenlik adımlarını kısaltmak planın dayandığı standartları bozar.","konu":"2.1.1"},{"id":"kh1-2-s002","tur":"coktan-secmeli","soru":"Sabah 07.45’te Selin’e 301’den 308’e kadar olan odalar ve bu odaların durumu yazılı bir listeyle veriliyor. Listeyi kim, hangi adla verir?","secenekler":["Kat şefi; oda dağılımı","Kat hizmetleri müdürü; kat hizmetleri raporu","Selin’in kendisi; oda görevlisi durum raporu","Ön büro; kat hizmetleri raporu"],"dogru":0,"aciklama":"Vardiya başında hangi odaların temizleneceğini kat şefi oda dağılımıyla bildirir. Kat hizmetleri raporu müdürden ön büroya, durum raporu görevliden kat şefine gider.","konu":"2.1.1"},{"id":"kh1-2-s003","tur":"coktan-secmeli","soru":"Kat şefi oda dağılımı yaparken odaların giriş, çıkış, arızalı ya da erişilebilir olmasına bakar. Bunun asıl nedeni nedir?","secenekler":["Her görevliye numarası ardışık odaların verilmesi zorunludur","Ön büro odaları satış fiyatına göre sıralamak ister","Durum, oda tipi ve yatak sayısına göre temizlik süresi değişir","Konuklar odalarını bu listeye bakarak seçer"],"dogru":2,"aciklama":"Süre odaya göre farklıdır; bu yüzden eşit sayıda değil, eşit iş yüküne göre dağıtılır. Oda numarasının ardışıklığı belirleyici değildir.","konu":"2.1.1"},{"id":"kh1-2-s004","tur":"coktan-secmeli","soru":"Sabah 11.00’de 410 numaralı odanın konuğu resepsiyonda hesabını kapatıp ayrılıyor. Oda yeni konuk için hazırlanacak. Bu oda hangi durumdadır?","secenekler":["Giriş yapılmış oda","Çıkış yapılmış oda","Arızalı oda","Boş, temizlenmiş oda"],"dogru":1,"aciklama":"Hesabını kapatıp ayrılan konuğun odası temizlenmeyi bekleyen çıkış odasıdır. Boş ve temiz oda, temizlik bittikten sonraki durumdur.","konu":"2.1.1"},{"id":"kh1-2-s005","tur":"dogru-yanlis","soru":"Arızası süren oda ön büroya bildirilir ve arıza giderilene kadar satışa kapalı kalır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Arızalı (OOO) oda konuğa verilmez; arıza giderilince temizlenip yeniden satışa açılır.","konu":"2.1.1"},{"id":"kh1-2-s006","tur":"coktan-secmeli","soru":"Zemin kattaki 108 numaralı oda, tekerlekli sandalye kullanan konuk için hazırlanıyor ve eşyalar yolu daraltmayacak biçimde yerleştiriliyor. Bu oda hangi türdendir?","secenekler":["Arızalı oda","Erişilebilir oda","Personelin kullandığı oda","Giriş yapılmış oda"],"dogru":1,"aciklama":"Hareket kısıtı olan konuğun rahat ve güvenle kullanması için düzenlenen oda erişilebilir odadır. Kat şefi dağılımda onu ayrıca düşünür.","konu":"2.1.1"},{"id":"kh1-2-s007","tur":"coktan-secmeli","soru":"Sabah 07.40’ta soyunma odasında üniformanı giydin. Kişisel bakım kuralına göre işe başlamadan önce başka neyi yapmalısın?","secenekler":["Kolundaki bileziği ve yüzüğü çıkarıp ellerini yıkamalısın","Kokulu bir parfüm sürerek odalarda ferah bir koku bırakmalısın","Takılarını üniformanın cebine koyup yanında taşımalısın","Kat arabasını koridora çıkarıp ilk odaya geçmelisin"],"dogru":0,"aciklama":"Oda görevlisi konuğun en özel alanına girer; temiz ve bakımlı olmalı, takılar iş başlamadan önce çıkarılmalıdır.","konu":"2.1.1"},{"id":"kh1-2-s008","tur":"coktan-secmeli","soru":"Sabah meeting’inde aşağıdakilerden hangisi yapılmaz?","secenekler":["Personelin kişisel bakımının kontrol edilmesi","Dünkü şikâyet raporunun okunması","Çıkış yapan konukların hesaplarının kapatılması","VIP ve problemli konukların bildirilmesi"],"dogru":2,"aciklama":"Meeting’de bakım kontrol edilir, şikâyetler okunur, problemli ve VIP konuklar duyurulur. Hesap kapatma ön büronun işidir.","konu":"2.1.1"},{"id":"kh1-2-s009","tur":"coktan-secmeli","soru":"Meeting’den sonra Selin kat şefinden hangi üç şeyi alarak çalışmaya hazırlanır?","secenekler":["Günlük iş programı, ambar talep fişi ve mini buzdolabı çeki","Oda dağılımı, arıza bildirim formu ve hasarlı malzeme tutanağı","Kat hizmetleri raporu, anahtar dolabı defteri ve kat pas anahtarı","Günlük iş programı, sorumlu olduğu odaların raporu ve bölüm pas anahtarı"],"dogru":3,"aciklama":"Program, durum raporu ve imza karşılığı bölüm pas anahtarı eksiksizse görevli ilk saatten ne yapacağını bilerek işe başlar.","konu":"2.1.1"},{"id":"kh1-2-s010","tur":"coktan-secmeli","soru":"Geçen ay yastığından rahatsız olan konuk yeniden rezervasyon yaptırdı ve meeting’de adı okundu. Bu remark’ın sağladığı yarar nedir?","secenekler":["Aynı hata tekrarlanmaz, gerekli önlem konuk gelmeden alınır","Konuğun odası her gelişinde farklı bir kata alınır","Konuğun hesabına özen bedeli olarak ek ücret yazılır","Konuğun şikâyeti oda görevlisinin disiplin kaydına eklenir"],"dogru":0,"aciklama":"Remark, konuğun hassasiyetini sonraki gelişe taşır; konuk otelin kendisini hatırladığını görür. Ceza ya da ek ücret amacı yoktur.","konu":"2.1.1"},{"id":"kh1-2-s011","tur":"coktan-secmeli","soru":"Oda görevlisinin durum raporu ile kat hizmetleri raporu arasındaki fark nedir?","secenekler":["İkisini de görevli hazırlar; fark yalnızca nüsha sayısındadır","Birini ön büro, ötekini muhasebe doldurur; ikisi de kat ofisinde kalır","Birini kat şefi bir kez hazırlar; ötekini görevli ay sonunda yazar","Birini görevli doldurur; ötekini müdür bunlardan derleyip ön büroya gönderir"],"dogru":3,"aciklama":"Durum raporu odaların sahadaki durumudur ve şefe gider. Müdür, bu raporlardan ön büroya giden kat hizmetleri raporunu çıkarır.","konu":"2.1.1"},{"id":"kh1-2-s012","tur":"coktan-secmeli","soru":"Sabah 10.30’da ön büro, hangi odaların boş, dolu, arızalı ya da bagajsız olduğunu gösteren raporu bekliyor. Bu raporu ön büroya kim gönderir?","secenekler":["Oda görevlisi doğrudan","Kat hizmetleri müdürü","Güvenlik müdürü","Muhasebe müdürü"],"dogru":1,"aciklama":"Müdür, görevlilerin raporlarını derleyip ön büroya gönderir; ön büro satış ve giriş işlemlerini bu rapora göre yapar.","konu":"2.1.1"},{"id":"kh1-2-s013","tur":"coktan-secmeli","soru":"Kat hizmetleri raporu üç nüsha düzenlenir. Nüshalar hangi bölümlere gider?","secenekler":["Ön büro, mutfak ve güvenlik","Muhasebe, teknik servis ve çamaşırhane","Ön büro, muhasebe ve kat hizmetleri","Ön büro, satış-pazarlama ve kat hizmetleri"],"dogru":2,"aciklama":"Biri ön büroya, biri muhasebeye gider, biri kat hizmetlerinde kalır. Mutfak ve güvenlik raporun kullanıcısı değildir.","konu":"2.1.1"},{"id":"kh1-2-s014","tur":"coktan-secmeli","soru":"Raporda 1104 numaralı odada iki kişi yazıyor; odada üç yatağın kullanıldığını ve üç kişiye ait eşya olduğunu görüyorsun. Ne yaparsın?","secenekler":["Raporu değiştirmeden bırakırsın, ön büro kişi sayısını zaten bilir","Kişi sayısını sessizce üç olarak düzeltip not düşmezsin","Farkı raporun açıklama bölümüne yazarsın","Odada beklerek konuğa kaç kişi kaldığını sorarsın"],"dogru":2,"aciklama":"Yatak, kıyafet ve diş fırçası gibi izler kişi sayısını gösterir. Fark açıklama bölümüne yazılır ki ön büro gerçeği öğrensin.","konu":"2.1.1"},{"id":"kh1-2-s015","tur":"coktan-secmeli","soru":"Gece oda değiştiren bir konuğun odasını raporlarken bu bilgiyi nereye yazarsın?","secenekler":["Raporun açıklama bölümüne","Oda numarası sütununa, eski numaranın üstünü çizerek","Kişi sayısı sütununa","Hiçbir yere; ön büro oda değişikliğini zaten bilir"],"dogru":0,"aciklama":"Sembolle anlatılamayan oda değişikliği, dışarıda geceleme gibi durumlar açıklama bölümünde belirtilir; böylece rapor eksiksiz olur.","konu":"2.1.1"},{"id":"kh1-2-s016","tur":"coktan-secmeli","soru":"Selin 305 numaralı odanın temizliğini bitirdi; odada konuk yok. Durum raporuna hangi kısaltmayı yazar?","secenekler":["C/O","OCC","S/O","V/C"],"dogru":3,"aciklama":"Konuğu olmayan ve temizliği yapılmış oda V/C’dir. C/O çıkış yapılmış, temizlenmemiş oda; S/O dolu ama gece kullanılmamış oda; OCC ise odada konuk bulunduğunu gösterir.","konu":"2.1.1"},{"id":"kh1-2-s017","tur":"coktan-secmeli","soru":"Kat şefi rapordaki C/O odaları dolu odalardan önce temizlenecekler olarak işaretliyor. Bunun nedeni nedir?","secenekler":["Konuk içeride olduğu için en az rahatsızlık veren odalardır","Bu odalar yeniden satılacağı için ön büro hazır olmalarını bekler","Arızalı oldukları için teknik servisle birlikte ele alınırlar","Yeni giriş yapılmış oldukları için ilk gün özen gerektirirler"],"dogru":1,"aciklama":"C/O, çıkış yapılmış temizlenmemiş odadır; yeniden satılacağı için dolu ve boş odalardan önce temizlenir. VIP ve “odamı hemen temizleyin” odaları bunların da önüne geçer.","konu":"2.1.1"},{"id":"kh1-2-s018","tur":"coktan-secmeli","soru":"Sabah 08.30’da 1006 numaralı oda dolu görünüyor, ama yatak dünkü düzeninde ve hiç yatılmamış. Bu oda için doğru kısaltma hangisidir?","secenekler":["S/O","W/L","H/U","OK"],"dogru":0,"aciklama":"Dolu olduğu hâlde gece kullanılmayan oda S/O’dur. W/L, konuğun bagajı olmayan odayı gösterir.","konu":"2.1.1"},{"id":"kh1-2-s019","tur":"coktan-secmeli","soru":"S/O ile W/L kısaltmaları arasındaki fark hangisinde doğru verilmiştir?","secenekler":["S/O’da odada bagaj yoktur; W/L’de konuk geceyi dışarıda geçirmiştir","S/O’da konuk geceyi dışarıda geçirmiştir; W/L’de odada konuğun bagajı yoktur","S/O personelin, W/L konuğun kullandığı odadır","İkisi aynı anlamdadır; yalnızca kat ofisi ile ön büro farklı kullanır"],"dogru":1,"aciklama":"İkisi de dolu oda için kullanılır ama ön büroya farklı uyarı verir: biri geceleme, öteki bagajsızlık.","konu":"2.1.1"},{"id":"kh1-2-s020","tur":"coktan-secmeli","soru":"420 numaralı oda, geceyi otelde geçirecek bir yöneticiye ayrıldı. Raporda nasıl gösterilir ve nasıl ele alınır?","secenekler":["VIP yazılır; en özenli konuk odası gibi hazırlanır","OCC yazılır; temizlik isteği sorularak girilir","H/U yazılır; konuk odası gibi hazırlanmaz, şefin talimatı uygulanır","OOO yazılır; satışa kapatılması için teknik servise bildirilir"],"dogru":2,"aciklama":"Otel personelinin kullandığı oda H/U’dur; konuğa satılmaz ve oda görevlisi onu konuk odası gibi hazırlamaz.","konu":"2.1.1"},{"id":"kh1-2-s021","tur":"coktan-secmeli","soru":"Selin’in bölüm pas kartı, 3. kattaki sekiz odayı tek başına açıyor. Pas anahtarının otelde kullanılma amacı en iyi hangisiyle anlatılır?","secenekler":["Konuğun kendi odasını anahtarsız ve kolayca açabilmesi","Ön büronun konuk giriş çıkışlarını sisteme kaydetmesi","Teknik servisin yalnızca depo ve ofis kapılarını açması","Kat hizmetlerinin birçok odaya hızla girip işini sürdürmesi"],"dogru":3,"aciklama":"Pas anahtarı tek başına birden fazla kapıyı açar; bu hız sağlar ama güvenliği de önemli kılar.","konu":"2.1.2"},{"id":"kh1-2-s022","tur":"coktan-secmeli","soru":"Murat’a 4. kattaki 401–410 arası odalar verildi. Günlük oda hizmeti için hangi anahtarı alır?","secenekler":["Kat pas anahtarı","Katlar anahtarı","Bölüm pas anahtarı","Genel otel anahtarı"],"dogru":2,"aciklama":"Bölüm pas anahtarı yalnızca görevlinin sorumlu olduğu bölümdeki odaları açar. Kat pas anahtarı kat şefindedir ve katın tamamını açar.","konu":"2.1.2"},{"id":"kh1-2-s023","tur":"coktan-secmeli","soru":"Kat pas anahtarı ile katlar anahtarı arasındaki fark hangisinde doğru verilmiştir?","secenekler":["Kat pas anahtarı yalnız bir katı açar ve kat şefindedir; katlar anahtarı bütün misafir odalarını açar ve yöneticidedir","Kat pas anahtarı bütün katları açar ve kat hizmetleri müdüründedir; katlar anahtarı yalnız bir kat içindir ve görevlide durur","İkisi de bütün katları açar; aralarındaki tek fark anahtarın kart ya da metal olmasıdır","Kat pas anahtarı yalnız bölümdeki odaları açar ve görevlidedir; katlar anahtarı tek bir katı açar ve ön büroda tutulur"],"dogru":0,"aciklama":"Yetki arttıkça anahtarı taşıyan kişi azalır: bölümde görevli, katta kat şefi, bütün odalarda kat hizmetleri yöneticisi.","konu":"2.1.2"},{"id":"kh1-2-s024","tur":"coktan-secmeli","soru":"Hangi anahtar yalnızca kat hizmetleri yöneticisinde bulunur ve sayısı güvenlik gerekçesiyle sınırlı tutulur?","secenekler":["Bölüm pas anahtarı","Kat pas anahtarı","Genel otel anahtarı","Katlar anahtarı"],"dogru":3,"aciklama":"Katlar anahtarı otelin bütün misafir odalarını açtığı için yöneticidedir. Genel otel anahtarı ise otel idaresinde bulunur.","konu":"2.1.2"},{"id":"kh1-2-s025","tur":"coktan-secmeli","soru":"Gece yarısı otelin deposuna girilmesi gerekiyor. Depoyu açabilecek anahtar hangisidir?","secenekler":["Katlar anahtarı","Genel otel anahtarı","Bölüm pas anahtarı","Kat pas anahtarı"],"dogru":1,"aciklama":"Ofis, mutfak, depo, oda ve salonu açan genel otel anahtarı (emniyet anahtarı) idarededir. Katlar anahtarı yalnızca misafir odalarını açar.","konu":"2.1.2"},{"id":"kh1-2-s026","tur":"dogru-yanlis","soru":"Anahtar dolabı gün boyu sık kullanıldığından vardiya boyunca açık bırakılması, teslim alma sırasını hızlandırdığı için uygundur.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Anahtar dolabı açık bırakılmaz, her zaman kilitli tutulur; böylece anahtarların yetkisiz kişilerin eline geçmesi önlenir.","konu":"2.1.2"},{"id":"kh1-2-s027","tur":"coktan-secmeli","soru":"Dolap sorumlusu Hülya, Murat’ın tarih ve saati yazmadan anahtarı aldığını görüyor. Ne yapmalıdır?","secenekler":["Tarihi ve saati kendisi yazıp anahtarı verir","Kayıt işini vardiya sonunda toplu tamamlatır","Defteri doğru doldurmasını ister","Anahtarı geri alıp başka bir görevliye devreder"],"dogru":2,"aciklama":"Sorumlunun görevi, teslim alan ve teslim edenin defteri doğru doldurmasını izlemektir; eksik kayıt kayıp durumunda izi bozar.","konu":"2.1.2"},{"id":"kh1-2-s028","tur":"coktan-secmeli","soru":"Bir pas anahtarı kayboldu. Anahtarın kimde olduğunu ve ne zaman alındığını hangi kayıttan öğrenirsin?","secenekler":["Oda görevlisi durum raporundan","İmza föyü kaydından","Arıza bildirim formundan","Kat hizmetleri raporundan"],"dogru":1,"aciklama":"İmza föyünde ad, pas numarası, alınan ve teslim saati, bölge ve imza vardır. Öteki belgeler odaların durumunu ya da arızaları anlatır.","konu":"2.1.2"},{"id":"kh1-2-s029","tur":"dogru-yanlis","soru":"Konuk anahtarını odada unuttuğunu söylerse oda görevlisi ona yardım etmek için pas anahtarıyla odayı açabilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Pas anahtarı konuğa oda açmak için kullanılmaz; konuk resepsiyona yönlendirilir.","konu":"2.1.2"},{"id":"kh1-2-s030","tur":"coktan-secmeli","soru":"Murat 16.30’da vardiyasını bitirdi. Pas anahtarıyla ne yapmalıdır?","secenekler":["Tarih ve saati yazıp imzayla şefe ya da yetkiliye teslim etmeli","Ertesi sabah getirmek üzere güvenli biçimde evine götürmeli","Anahtar dolabının önüne bırakıp hiçbir kayıt tutmamalı","Bir sonraki vardiyadaki arkadaşına sözlü olarak devretmeli"],"dogru":0,"aciklama":"Anahtar işletmenin dışına çıkmaz; kayıtlı teslim, olası kayıpta geriye dönük kanıt olur.","konu":"2.1.2"},{"id":"kh1-2-s031","tur":"coktan-secmeli","soru":"306 numaralı odanın kapısına üç kez vurup “Housekeeping” dedin, yanıt gelmedi. 3x3 metoduna göre bundan sonra ne yaparsın?","secenekler":["Bir kez daha vurup hemen pas kartıyla girersin","Ön büroyu arayıp konuğun odada olup olmadığını sorarsın","Kapının altına not bırakıp beklemeden sonraki odaya geçersin","İşlemi iki kez daha yinelersin; yanıt yoksa pas kartıyla girersin"],"dogru":3,"aciklama":"Üç vuruş ve seslenme toplam üç kez yapılır. Konuk uyuyor ya da banyoda olabilir; yöntem ani karşılaşmayı önler.","konu":"2.1.2"},{"id":"kh1-2-s032","tur":"coktan-secmeli","soru":"Selin 308 numaralı odaya giriyor. Kapıya ne asar ve kapıyı nasıl tutar?","secenekler":["Oda Görevlisi kartını asar, kapıyı açık tutar","DND kartını asar, kapıyı kapalı tutar","Oda Görevlisi kartını asar, kapıyı kilitler","Kart asmaz, kapıyı yalnızca aralık bırakır"],"dogru":0,"aciklama":"Kart odada işlem yapıldığını gösterir; açık kapı hem görevlinin hem konuğun güvenliğini sağlar. DND kartını konuk asar.","konu":"2.1.2"},{"id":"kh1-2-s033","tur":"coktan-secmeli","soru":"215 numaralı odanın kapısında DND kartı yok. Kapıyı çaldın, konuk açtı. Doğru sıra hangisidir?","secenekler":["Selam verir, odayı hemen temizler ve işin bitince Oda Görevlisi kartını asarsın","Selam verir, temizlik isteyip istemediğini sorarsın; isterse kartı asıp sessizce çalışırsın","Konuğun odadan çıkmasını bekleyip temizliğe başlamak için ondan izin istersin","Selam verir, temizlik isteyip istemediğini sormadan kapıyı kapatıp sonraki odaya geçersin"],"dogru":1,"aciklama":"Dolu odada konuğa sormadan temizlik yapılmaz. İsterse kart asılır ve konuğun rahatı bozulmadan çalışılır.","konu":"2.1"},{"id":"kh1-2-s034","tur":"dogru-yanlis","soru":"Temizlik sırasında odaya gelen konuk devam edilmesini istemezse görevli araç gerecini toplayıp çıkar ve odanın başka bir saatte temizleneceğini rapora not eder.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Konuğun isteği temizlik programının önündedir; yapılamayan temizlik raporda belirtilir ki şikâyet doğmasın.","konu":"2.1"},{"id":"kh1-2-s035","tur":"coktan-secmeli","soru":"218 numaralı odada klima bozulduğu için konuk 224 numaralı odaya alınıyor. Eşyaların yeni odaya taşınmasında oda görevlisi kimle çalışır?","secenekler":["Güvenlik görevlisi","Ön büro görevlisi","Kat şefi","Bellboy"],"dogru":3,"aciklama":"Eşyalar bellboy ile birlikte taşınır; görevli toplamaya yardım eder. Eski oda sonra temizlenip satışa hazırlanır.","konu":"2.1"},{"id":"kh1-2-s036","tur":"coktan-secmeli","soru":"Çıkış yapılmış odaya, konuk otelden ayrılmadan girilmesi neden önemlidir?","secenekler":["Çarşaflar konuk ayrılmadan yıkamaya gönderilebilir","Mini buzdolabı ücretleri konuğa anında kesilebilir","Odada unutulan eşya varsa konuğa hâlâ ulaştırılabilir","Oda fiyatı yeniden belirlenebilir"],"dogru":2,"aciklama":"Önce çıkış saatleri öğrenilir. Konuk ayrılmadan yapılan genel kontrol unutulan şeyi ona ulaştırma imkânı verir.","konu":"2.1"},{"id":"kh1-2-s037","tur":"coktan-secmeli","soru":"410 numaralı odada bir şarj aleti buldun, ama konuk otelden ayrılmış. Ne yaparsın?","secenekler":["Eşyayı ön büro masasına bırakıp form doldurmadan kendi işine dönersin","Eşyayı odada bir hafta saklayıp konuk telefon ederse haber verirsin","Eşyayı kaybolmasın diye kendi dolabında saklayıp konuk gelirse verirsin","Kayıp bulunmuş eşya formunu doldurup eşyayla birlikte kat şefine verirsin"],"dogru":3,"aciklama":"Konuk ayrılmışsa eşya kayıt altına alınır: form doldurulur ve eşya formla birlikte kat şefine teslim edilir.","konu":"2.1"},{"id":"kh1-2-s038","tur":"coktan-secmeli","soru":"Konuk akşam kahvaltı kartını doldurup kapı koluna astı. Sabah görevli ne yapar?","secenekler":["Kartı DND sayıp odaya girmez","Kartı görür ve isteği ilgili bölüme iletir","Kartı toplayıp çöpe atar, kahvaltı bölümü zaten bilir","Konuğu arayıp siparişi kendisi alır"],"dogru":1,"aciklama":"Kapı kolu kartları kat hizmetleri ile konuk arasında sessiz iletişim kurar; isteğin ilgili bölüme ulaştırılması görevlinin işidir.","konu":"2.7.2"},{"id":"kh1-2-s039","tur":"coktan-secmeli","soru":"Hangi eşleştirme doğrudur?","secenekler":["DND kartı: önce o odaya gidilir; “Lütfen odayı şimdi hazırlayınız” kartı: odaya girilmez","DND kartı: odaya girilir ama kapı çalınmaz; “Lütfen odayı şimdi hazırlayınız” kartı: oda atlanır","DND kartı: odaya girilmez; “Lütfen odayı şimdi hazırlayınız” kartı: önce o odaya gidilir","DND kartı: oda sıra dışı temizlenir; “Lütfen odayı şimdi hazırlayınız” kartı: sonraki güne bırakılır"],"dogru":2,"aciklama":"DND, konuğun girilmesini istemediğini gösterir; “Lütfen odayı şimdi hazırlayınız” kartı ise hemen temizlenmesini ister. Biri sırayı bozmaz, öteki öne alır.","konu":"2.1.3"},{"id":"kh1-2-s040","tur":"coktan-secmeli","soru":"Yeni açılmış otelde 506 numaralı odanın dışında kırmızı ışık yanıyor. Selin ne yapar?","secenekler":["Rahatsız edilmek istenmediğini anlar, kapıya dokunmadan geçer","Yeşil ışık yansın diye kapıyı hafifçe çalıp yanıt bekler","Işığın arızalı olduğunu düşünüp teknik servise form yazar","Temizlik istendiğini düşünüp pas kartıyla odaya hemen girer"],"dogru":0,"aciklama":"Kırmızı ışık DND, yeşil ışık “odamı temizleyin” anlamındadır; konuk bunu içerideki tuşla yakar.","konu":"2.1.3"},{"id":"kh1-2-s041","tur":"coktan-secmeli","soru":"408 numaralı odada DND varken yan odada matkapla tamirat planlanmış. Kat şefi ne yapar?","secenekler":["Yan oda boş olduğundan tamirata başlatır","Konuğun huzuru için işi erteletir","Tamirat için DND kartını kaldırtır","Konuğun odasına girip uyarı notu bırakır"],"dogru":1,"aciklama":"DND’de telefonlar bağlanmaz, yan odalarda gürültüyle çalışılmaz. Konuğun huzuru işin takviminden önce gelir.","konu":"2.1.3"},{"id":"kh1-2-s042","tur":"coktan-secmeli","soru":"Selin DND kartı yüzünden 406 numaralı odaya giremedi. Konuğa durumu nasıl bildirir?","secenekler":["Kapıdan yüksek sesle seslenerek konuğu uyandırmaya çalışır","Pas anahtarıyla girip yalnızca çöpleri toplayıp hemen çıkar","Hiçbir bilgi bırakmaz, durumu rapora da yazmaz, işine devam eder","Girilemediğini bildiren kartı kapı altından atar ya da asar"],"dogru":3,"aciklama":"DND uyarı kartı, konuğa neden temizlenmediğini söyler ve ihtiyaç hâlinde resepsiyonu aramasını sağlar.","konu":"2.1.3"},{"id":"kh1-2-s043","tur":"dogru-yanlis","soru":"DND yüzünden girilemeyen oda, tarih ve saatiyle sisteme işlenir ve akşam raporunda belirtilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Bu kayıt, odaya neden girilmediğini açıkça gösterir ve konuk şikâyetinin önüne geçer.","konu":"2.1.3"},{"id":"kh1-2-s044","tur":"coktan-secmeli","soru":"Salı sabahı 412 numaralı odada DND hâlâ asılı. Konuğu telefonla kim arar ve ne sorar?","secenekler":["Oda görevlisi; temizlik yaptırıp yaptırmayacağını sorar","Kat şefi; kartın neden hâlâ asılı olduğunu sorgular","Ön büro; sağlık durumunu ve bir ihtiyacı olup olmadığını sorar","Güvenlik; kimlik bilgilerini yeniden ister"],"dogru":2,"aciklama":"24 saati geçen DND’de ön büro konuğun sağlığını sorar. Olumsuz bir durum yoksa temizlik için girilemediği söylenir.","konu":"2.1.3"},{"id":"kh1-2-s045","tur":"coktan-secmeli","soru":"Uzayan DND üzerine yetkililerle girilen odada konuğun vefat ettiği görülüyor. Kat şefi ne yapmalıdır?","secenekler":["Hiçbir yere dokunmaz, güvenlik güçlerine haber verir ve odayı korur","Konuğun eşyalarını toplayıp yakınlarına ulaşmak için ön büroya götürür","Odayı havalandırıp yatağı düzelterek durumu daha sonra yöneticiye bildirir","Yakınlarına ulaşmak için odadaki belge ve telefon kayıtlarına bakar"],"dogru":0,"aciklama":"Vefat olduğunda müdahale edilmez, hiçbir yere dokunulmaz. İz ve delil korunur; hastalık hâlinde ise doktor ya da 112 çağrılır.","konu":"2.1.3"},{"id":"kh1-2-s046","tur":"coktan-secmeli","soru":"Penceresi açılabilen 311 numaralı odayı havalandıracaksın. En iyi hava akımını nasıl sağlarsın?","secenekler":["Oda kapısını ve balkon penceresini karşılıklı açık tutarak","Yalnızca perdeyi aralayıp klimayı çalıştırarak","Pencereyi sonuna kadar açıp oda kapısını kapalı tutarak","Yalnızca balkon kapısını açıp odadan uzaklaşarak"],"dogru":0,"aciklama":"Hava akımı iki karşılıklı açıklıkla oluşur; yaklaşık on dakika nemli havayı temiz havayla değiştirmeye yeter.","konu":"2.2"},{"id":"kh1-2-s047","tur":"dogru-yanlis","soru":"Yağmurlu havada odayı iyice havalandırmak için pencere ve balkon kapısı sonuna kadar açılır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yağmurda pencere ve balkon kapısı yarım açılır, perde içeri çekilir; yoksa eşya ve perde ıslanır, hasar ve koku olur.","konu":"2.2"},{"id":"kh1-2-s048","tur":"coktan-secmeli","soru":"Fırtınalı havada Selin pencereyi açmadan önce odadaki çöpleri topluyor. Bunun nedeni nedir?","secenekler":["Çöp kokusu pencereden dışarı çıksın diye","Yağmurdan perdelerin ıslanmaması için","Pencere açıkken çöp toplamanın yasak olduğu için","Rüzgâr çöpleri ve hafif eşyaları savurabilir"],"dogru":3,"aciklama":"Çok rüzgârlı havada havalandırma çöpler toplandıktan sonra yapılır; yağmurdaki önlem ise pencerenin yarım açılmasıdır.","konu":"2.2"},{"id":"kh1-2-s049","tur":"coktan-secmeli","soru":"Selin 311 numaralı odanın temizliğini bitirdi; pencere ve balkon kapısı açık duruyor. Ne yapmalıdır?","secenekler":["Odayı havalansın diye açık bırakmalı, konuk gelince kapatmalı","Kapatıp perdeleri düzeltmeli; açık pencere güvenlik riskidir","Yarım aralık bırakmalı, nem kalmasın ve oda kokmasın diye","Perdeleri açık bırakıp yalnızca pencereleri kapatıp çıkmalı"],"dogru":1,"aciklama":"Açık pencere hem güvenlik hem enerji sorunudur; düzgün perde de odanın bakımlı görünmesini sağlar.","konu":"2.2"},{"id":"kh1-2-s050","tur":"coktan-secmeli","soru":"Odada çiğnenmiş sakız, süpürülmüş toz ve boş bir plastik su şişesi var. Hangisi doğru sınıflandırılmıştır?","secenekler":["Sakız geri dönüşebilir, plastik şişe çöptür","Şişe ile sakız geri dönüşür, toz çöp sayılır","Sakız ve toz çöptür; plastik şişe geri dönüşebilir","Toz ile şişe çöptür, sakız geri dönüşebilir"],"dogru":2,"aciklama":"Çöp yeniden kullanılamayan artıktır. Geri dönüştürülebilen kâğıt, cam, metal ve plastikler ayrı toplanır.","konu":"2.3"},{"id":"kh1-2-s051","tur":"dogru-yanlis","soru":"Teknik servisteki boya ve çözücü artıkları tehlikeli atıktır; oda çöpüne karıştırılmaz.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"İnsan ve çevre sağlığına zarar verebilen atıklar ayrı yönetilir; oda görevlisi bunlara dokunmaz.","konu":"2.3"},{"id":"kh1-2-s052","tur":"coktan-secmeli","soru":"Selin odadaki kâğıt ve plastikleri ayrı poşetlere koyuyor. Bu davranış doğrudan hangi amaca hizmet eder?","secenekler":["Çöp miktarını ve kaynak israfını azaltır","Odanın temizlik süresini kısaltır","Atıkların odada saklanmasını sağlar","Çöp torbası kullanımını sıfırlar"],"dogru":0,"aciklama":"Geri dönüşebilen atıklar karışık çöpten ayrılırsa yeniden işlenebilir; bu da kaynak israfını önler.","konu":"2.3"},{"id":"kh1-2-s053","tur":"coktan-secmeli","soru":"Geri dönüşümün üretim ve ülke ekonomisi açısından yararı hangisinde doğru verilmiştir?","secenekler":["Ürün çeşitliliği artar; fabrikalarda çalışan sayısı ve enerji tüketimi yükselir","Atık depolama sorunu tamamen biter; ama karbon salımı daha da artar","Atık taşıma ihtiyacı kalkar; bunun karşılığında hurda ithalatı artar","Daha az enerji, su ve ağaç kullanılır; ithal hurdaya ödenen döviz azalır"],"dogru":3,"aciklama":"Atıkların yeniden değerlendirilmesi enerji, su ve ağaç tasarrufu sağlar ve karbon salımını azaltır.","konu":"2.3"},{"id":"kh1-2-s054","tur":"coktan-secmeli","soru":"Selin çöp sepetinden bir plastik şişe, bir gazete ve bir boş cam şişe çıkardı. Doğru işlem hangisidir?","secenekler":["Tümünü tek büyük torbaya doldurup arabaya götürür","Her birini türüne göre ayrı poşete koyar","Yalnızca cam şişeyi ayırır, kâğıt ve plastiği karışık torbaya atar","Üçünü de çöp kovasında bırakıp ertesi gün toplar"],"dogru":1,"aciklama":"Çöpler organik, kâğıt, plastik, cam, metal, tıbbi ve karışık gibi türlere ayrılır; geri dönüşebilenler karışık çöpe karışmaz.","konu":"2.3"},{"id":"kh1-2-s055","tur":"coktan-secmeli","soru":"Sabah 09.20’de Selin oda çöp sepetini boşaltacak. Doğru sıra hangisidir?","secenekler":["Sepeti boşaltır, sonra ellerini yıkayıp eldiven takar","Önce toz alır, sonra eldivenle çöpü toplar","Eldiven ve maskeyi takar, sonra sepeti boşaltır","Maskeyi yalnızca kokulu çöp gördüğünde takar"],"dogru":2,"aciklama":"Koruyucu donanım işin başında takılır. Çöplerin temizliğe başlamadan toplanması personeli ve konukları korur.","konu":"2.3"},{"id":"kh1-2-s056","tur":"coktan-secmeli","soru":"Murat’ın arabasında atık bölmesi yok. Kâğıt, plastik ve karışık atık toplayacak. Ne yapar?","secenekler":["Kâğıt, plastik ve karışık atık için üç ayrı poşet hazırlar","Her şeyi tek poşette toplayıp ayırmayı çamaşırhaneye bırakır","Atıkları arabanın yanında koridorda ayrı yığınlar yapar","Çöpü odada bırakıp temizlik sonunda alır"],"dogru":0,"aciklama":"Atık baştan doğru poşete ya da bölmeye konursa sonradan ayırmaya gerek kalmaz.","konu":"2.3"},{"id":"kh1-2-s057","tur":"coktan-secmeli","soru":"Oda çöp sepetini boşaltırken aşağıdakilerden hangisi yanlıştır?","secenekler":["Çöp torbasının ağzını bağlamak","Boş kovayı poşetsiz bırakıp işine devam etmek","Dolu torbayı kat arabasındaki torbaya koymak","Boşalan kovaya temiz ve yeni bir poşet takmak"],"dogru":1,"aciklama":"Konuk odaya girdiğinde temiz ve hazır bir çöp kovası bulmalıdır; bağlı torba ve yeni poşet bunun parçasıdır.","konu":"2.3"},{"id":"kh1-2-s058","tur":"coktan-secmeli","soru":"Murat bozuk bir kumandadan çıkan kullanılmış pilleri ne yapar?","secenekler":["Geri dönüşebilen plastik atıkların bölmesine koyar","Diğer oda çöpleriyle birlikte karışık çöp torbasına atar","Ayrı poşete koyup atık pil toplama kutusuna bırakır","Teknik servise bırakıp kayıt tutmadan işine döner"],"dogru":2,"aciklama":"Piller karışık çöpe ve geri dönüşen plastik atıkla birlikte atılmaz; ayrı poşette pil kutusuna gider.","konu":"2.3"},{"id":"kh1-2-s059","tur":"dogru-yanlis","soru":"Çöp olup olmadığından emin olunmayan buruşuk bir kâğıt, konuğu rahatsız etmesin diye çöp sayılıp atılır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Emin olunmayan şey çöp sayılmaz; önemli bir belge atılırsa konuk zor durumda kalır. Gerekirse kat şefine danışılır.","konu":"2.3"},{"id":"kh1-2-s060","tur":"coktan-secmeli","soru":"Selin kat arabasının üst rafına sürekli uzandığı için sırtından yakınıyor; kat şefi en çok kullanılan malzemeleri el hizasına taşıyor. Bu düzenlemenin amacı nedir?","secenekler":["Raf sayısını azaltarak arabayı hafifletmek","Malzeme tüketimini ve giderleri düşürmek","Görevlinin çalışma süresini kısaltmak","Aşırı zorlanmayı önleyip verimi artırmak"],"dogru":3,"aciklama":"Ergonomi, işi çalışana uygun hâle getirir; doğru düzen yorgunluğu ve iş kazasını azaltır.","konu":"2.1"},{"id":"kh1-2-s061","tur":"coktan-secmeli","soru":"3. katın dar koridorunda 305 numaralı odayı temizleyeceksin. Kat arabasını nereye bırakırsın?","secenekler":["Koridorun ortasına, malzemeye her yönden ulaşılsın diye","Kapının yanına, duvara paralel olacak biçimde","Asansörün önüne, kolay bulunsun diye","Koridorun sonuna, konuklar görmesin diye"],"dogru":1,"aciklama":"Araba odaya yakın olursa gereksiz yürünmez; geçişi kapatmadığı için konuk ve personel güvende kalır.","konu":"2.1"},{"id":"kh1-2-s062","tur":"dogru-yanlis","soru":"Oda görevlisi raporu kat şefine vermeden önce eksik oda olup olmadığına bakar, tarihi yazar ve imzalar.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Eksik ya da geç rapor ön büronun satış kararlarını yanlışlaştırabilir; bu yüzden kontrol, tarih ve imza birlikte yapılır.","konu":"2.1.1"},{"id":"kh1-2-s063","tur":"senaryo","durum":"Salı sabahı saat 10.00. 4. kattaki 412 numaralı odanın kapı kolunda DND kartı pazartesiden beri asılı. Ön büro konuğu aramış ama ulaşamamış; içeriden de ses gelmiyor.","soru":"Ne yaparsın?","secenekler":["Odayı atlayıp akşam raporuna yazarsın, ön büronun konuğa ulaşmasını beklersin.","Kapının altına yeni bir DND uyarı kartı bırakıp bir gün daha beklersin.","Pas anahtarınla girip konuğun durumuna bakar, sonra kat şefine anlatırsın.","Kat şefine haber verip yetkili kişi ve güvenlikle birlikte girilmesini istersin."],"dogru":3,"aciklama":"Uzayan DND’de konuk hasta olabilir. Odaya tek başına girilmez; kat şefi, güvenlik ve yetkili kişiyle girilir. Beklemek ya da yalnız girmek riski büyütür.","konu":"2.1.3"},{"id":"kh1-2-s064","tur":"senaryo","durum":"Sabah 10.30. 215 numaralı odanın kapısında DND yok. 3x3 yöntemiyle kapıyı çaldın; konuk uykulu bir sesle “Şimdi istemiyorum, öğleden sonra gelin” diyor.","soru":"Ne yaparsın?","secenekler":["Özür dileyip yatağı hızlıca toparlamayı önerip çalışmaya başlarsın.","Kapıyı kapatıp gider, odayı temizlenmiş gibi işaretlersin.","Özür dileyip öğleden sonra uğrayacağını söyler, rapora yazarsın.","Kapıyı açık bırakıp koridorda konuğun çıkmasını beklersin."],"dogru":2,"aciklama":"Konuğun isteği temizlik programının önündedir. Odanın başka saate kaldığı rapora yazılır ki ön büro ve kat şefi bilsin.","konu":"2.1"},{"id":"kh1-2-s065","tur":"senaryo","durum":"Öğleden sonra 14.00. Kat arabasının üzerinde bıraktığını sandığın pas kartını bulamıyorsun; birkaç oda önce yanındaydı.","soru":"Ne yaparsın?","secenekler":["Aramayı bırakıp hemen kat şefine ve güvenlik birimine haber verirsin.","Önceki odaları kısaca arar, bulamazsan akşam teslimde söylersin.","Başka bir görevliden kart ödünç alıp işine devam edersin.","Ön bürodan yedek kart istersin, kimseye söylemezsin."],"dogru":0,"aciklama":"Pas anahtarı birçok kapıyı açar; kayıp hemen bildirilmelidir ki güvenlik önlemi alınsın. İmza föyü anahtarın kimde olduğunu gösterir.","konu":"2.1.2"},{"id":"kh1-2-s066","tur":"senaryo","durum":"Sabah 11.00. Çıkış yapılmış 506 numaralı odayı kontrol ederken yatağın yanında bir şarj aleti buluyorsun. Konuk resepsiyonda hesabını kapatıyor.","soru":"Ne yaparsın?","secenekler":["Eşyayı kat şefine bırakıp kayıp bulunmuş eşya formunu doldurursun.","Eşyayı hemen ön büroya götürüp konuk ayrılmadan teslim ettirirsin.","Eşyayı odada bırakıp temizliği bitirdikten sonra ön büroya haber verirsin.","Temizliği bitirip eşyayı akşam raporuna yazarsın."],"dogru":1,"aciklama":"Konuk henüz otelden ayrılmadıysa eşya zaman kaybetmeden ona ulaştırılır. Form, konuk ayrıldıktan sonrası içindir.","konu":"2.1"},{"id":"kh1-2-s067","tur":"senaryo","durum":"Sabah 09.20. 305 numaralı odada çöpleri toplarken masanın üzerinde buruşturulmuş bir kâğıt ve içi dolu küçük bir kutu görüyorsun. Çöp olup olmadığından emin değilsin.","soru":"Ne yaparsın?","secenekler":["Kâğıdı açıp okuyarak önemli olup olmadığına karar verirsin.","Kâğıdı ve kutuyu çekmeceye koyup konuk sorarsa verirsin.","Olduğu gibi bırakıp gerekirse kat şefine danışırsın.","Kâğıdı çöpe atar, kutuyu masada bırakırsın."],"dogru":2,"aciklama":"Emin olunmayan şey çöp sayılmaz. Konuğun eşyasını okumak ya da yerini değiştirmek mahremiyeti ve düzeni bozar.","konu":"2.3"},{"id":"kh1-2-s101","tur":"coktan-secmeli","soru":"Selin odayı toplamadan önce prizleri ve lambaları deniyor. Günlük ve periyodik arıza kontrolünün asıl amacı nedir?","secenekler":["Teknik servisin işini oda görevlisine devretmek","Arızalı odanın sorumlusunu bulup kayda geçirmek","Odanın satış fiyatını donanım durumuna göre ayarlamak","Arızayı konuk fark etmeden yakalayıp şikâyeti önlemek"],"dogru":3,"aciklama":"Konuk odasında bozuk bir şey bulursa otelin hizmet sözü zedelenir. Arıza önceden bulunursa sorun şikâyete dönüşmez.","konu":"2.4"},{"id":"kh1-2-s102","tur":"coktan-secmeli","soru":"Donanım kontrolü temizliğin bir parçası sayılır. Bunun asıl nedeni nedir?","secenekler":["Odayı en yakından gören oda görevlisidir; arızayı ilk o fark eder","Teknik servis kat hizmetlerinin odalarına hiçbir zaman giremez","Kontrol temizlik süresini kısalttığı için işletmelerce tercih edilir","Kat şefi oda kontrolünü hiçbir zaman kendisi yapmaz"],"dogru":0,"aciklama":"Oda görevlisi her gün odada çalıştığı için telefon, televizyon, klima ve kasa gibi donanımın durumunu en erken görür.","konu":"2.4"},{"id":"kh1-2-s103","tur":"dogru-yanlis","soru":"Okuma lambası yanmayan odada anahtarı deneyip sorunu forma yazmak, oda görevlisinin donanım kontrolü kapsamındadır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Priz, anahtar ve lambaların çalışması kontrolün bir parçasıdır; yanmayan lamba küçük görünse de konuğun ilk akşam fark edeceği bir eksikliktir.","konu":"2.4"},{"id":"kh1-2-s104","tur":"coktan-secmeli","soru":"Temmuzda Antalya’daki otelde Kerem ısıtma ve soğutma sistemini kontrol ediyor. Hangisini yapar?","secenekler":["Perdeleri kapatıp odanın kendiliğinden serinlemesini bekler","Klima filtresini söküp yıkar","Panelin marka ve model bilgisini envanter listesiyle karşılaştırır","Panelden soğutmayı açıp havalandırmadan serin hava geldiğini kontrol eder"],"dogru":3,"aciklama":"Yazın bozuk bir klima konuk memnuniyetini ciddi biçimde etkiler. Görevli çalıştığını dener, arıza varsa forma yazar.","konu":"2.4"},{"id":"kh1-2-s105","tur":"coktan-secmeli","soru":"Dilek perde halkasının koptuğunu ve koltuk kolunda yırtık olduğunu görüyor. Bunu yeni konuk gelmeden bildirmenin yararı nedir?","secenekler":["Kusurun bedeli yeni konuğa yazılabilir","Odanın satış fiyatı kendiliğinden düşer","Onarım ya da değişim için zaman kalır","Bildirim teknik servis yerine ön büroya ulaşır"],"dogru":2,"aciklama":"Mobilya, perde ve nevresimdeki kırık, yırtık, leke ya da eksik yeni konuk gelmeden bildirilirse onarım için zaman kalır.","konu":"2.4"},{"id":"kh1-2-s106","tur":"coktan-secmeli","soru":"Çıkış yapılmış odada arıza kontrolü temizliğe başlamadan önce, ayrıntılı yapılır. Bunun nedeni nedir?","secenekler":["Konuktan kalan arıza ya da hasar, yeni konuk gelmeden bulunur","Dolu odada hiçbir kontrol yapılamadığı için tümü çıkışa bırakılır","Temizlikten sonra yapılan kontrol teknik servisçe kabul edilmediği için","Çıkış odalarında yalnızca televizyon ve kasa arızalanabildiği için"],"dogru":0,"aciklama":"Konuk ayrıldığı için oda boştur ve her şey rahatça denenebilir. Böylece arıza yeni konuğa ulaşmadan giderilir.","konu":"2.4"},{"id":"kh1-2-s107","tur":"coktan-secmeli","soru":"Öğleden sonra 14.00’te dolu bir odanın prizlerini, televizyonunu ve klimasını denemen gerekiyor. Doğru davranış hangisidir?","secenekler":["Konuk odada yoksa eşyalarını kenara alıp rahatça bakarsın","Kapıyı çalıp seslenir, konuğun eşyasına dokunmadan bakarsın","Kapıyı çalmadan girip konuk uykudaysa sessizce denersin","Dolu odada arıza kontrolünü konuk çıkana kadar ertelersin"],"dogru":1,"aciklama":"Dolu odada konuğun rahatı ve eşyası korunur; kapı nazikçe çalınır ve kat görevlisi olunduğu söylenir.","konu":"2.4"},{"id":"kh1-2-s108","tur":"coktan-secmeli","soru":"Nur, 214 numaralı odada banyo lambasının yanmadığını yazılı olarak teknik servise bildirecek. Hangi formu doldurur?","secenekler":["Hasarlı malzeme tutanağını","Ambar talep fişini","Mini buzdolabı çekini","Arıza bildirim formunu"],"dogru":3,"aciklama":"Odada tespit edilen arıza arıza bildirim formuyla bildirilir. Hasar tutanağı konuk kaynaklı bozulma içindir.","konu":"2.4"},{"id":"kh1-2-s109","tur":"coktan-secmeli","soru":"Arıza formunun nüshalarının teknik servis, kat şefi ve oda görevlisinde ayrı ayrı bulunması neyi sağlar?","secenekler":["Arıza bedelinin üç bölüm arasında paylaştırılmasını","Üç tarafın da aynı arızanın durumunu izleyebilmesini","Arızanın konuğa ayrıca bildirilmesini","Formun yalnızca teknik servisçe doldurulup saklanmasını"],"dogru":1,"aciklama":"Teknik servisin doldurup geri verdiği form, kat ofisindeki dosyada kendi nüshasıyla birlikte saklanır; arızanın durumu herkesçe görülebilir.","konu":"2.4"},{"id":"kh1-2-s110","tur":"coktan-secmeli","soru":"Arıza sürecinde kat hizmetleri ile teknik servisin görevleri hangisinde doğru verilmiştir?","secenekler":["Kat hizmetleri arızayı bulup bildirir; teknik servis giderir","Kat hizmetleri hem bulur hem onarır; teknik servis formu arşivler","Teknik servis arızayı bulur; kat hizmetleri onarır","Ön büro bulur ve giderir; kat hizmetleri yalnızca temizler"],"dogru":0,"aciklama":"İki bölümün iyi haberleşmesi odanın satışa hızlı dönmesini sağlar.","konu":"2.4"},{"id":"kh1-2-s111","tur":"dogru-yanlis","soru":"Arızası süren oda, temizlenmiş ve düzenlenmiş olduğu sürece konuğa verilebilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Arızalı oda hiçbir koşulda konuk kullanımına sunulmaz; konuk giriş anında hayal kırıklığına uğramasın diye satışa kapatılır.","konu":"2.4"},{"id":"kh1-2-s112","tur":"coktan-secmeli","soru":"312 numaralı odada banyo gideri tıkalı ve hemen onarılamıyor; akşam yeni konuk gelecek. Doğru işlem hangisidir?","secenekler":["Oda temizlenip konuğa “arızayı sonra bildiririz” denilerek verilir","Teknik servise haber verilmez, oda kapısı kilitli bırakılıp unutulur","Ön büroya bildirilir, oda satışa kapatılır, konuğa başka oda verilir","Konuğa önce oda gösterilir, beğenmezse başka bir odaya geçirilir"],"dogru":2,"aciklama":"Arızası giderilemeyen oda ön büroya bildirilerek satış dışı bırakılır; arıza giderilince yeniden satışa açılır.","konu":"2.4"},{"id":"kh1-2-s113","tur":"coktan-secmeli","soru":"Ertesi sabah Gül, dünkü klima arızasının giderildiği bildirilen odaya giriyor. Ne yapar?","secenekler":["Bildirim yapıldığı için bir şey yapmaz, iş bitmiştir","Arıza formunu baştan doldurur","Odayı kontrol etmeden satışa açılması için ön büroya haber verir","Odaya gidip paneli dener ve odayı düzenler"],"dogru":3,"aciklama":"Bildirimle iş bitmez; arızanın gerçekten çözüldüğünü görmek ve odayı yeniden düzenlemek oda görevlisinin işidir.","konu":"2.4"},{"id":"kh1-2-s114","tur":"coktan-secmeli","soru":"Çözülmemiş arızaların vardiya devrinde sonraki vardiyaya bildirilmemesinin sonucu ne olur?","secenekler":["Teknik servis arızayı kendiliğinden fark eder","Arıza unutulur ve aynı oda yeniden sorun çıkarır","Arıza formu geçersiz sayılır","Oda otomatik olarak OOO durumuna alınır"],"dogru":1,"aciklama":"Onarım bekleyen arızalar bir sonraki vardiyadaki görevlilere anlatılırsa iş zincirde kopmaz.","konu":"2.4"},{"id":"kh1-2-s115","tur":"coktan-secmeli","soru":"Öğle saatinde konuk, duşun suyunun ısınmadığını bildiriyor. Kısa sürede çözülebilecek bir arıza. Ne yaparsın?","secenekler":["Teknik servisi arar, konuğa durumu anlatırsın","Konuğa hemen odasını değiştirmesini önerirsin","Sorunun kendiliğinden geçeceğini söylersin","Konuğu resepsiyona yönlendirip işine dönersin"],"dogru":0,"aciklama":"Kısa sürede çözülecek arızada teknik servis aranır, konuk bilgilendirilir. Oda değişimi uzun sürecek arızalar içindir.","konu":"2.4"},{"id":"kh1-2-s116","tur":"coktan-secmeli","soru":"Klimanın akşama kadar onarılamayacağı anlaşıldı. Doğru işlem hangisidir?","secenekler":["Konuğa arızalı odada kalması için indirim önerilir","Konuğa oda verilir ama arızalı oda satışa açık bırakılır","Aynı tipte başka oda verilir; arızalı oda satışa kapatılır","Konuk arıza giderilene kadar lobide bekletilir"],"dogru":2,"aciklama":"Uzun sürecek arızada oda değişimi yapılır; arızalı oda giderilene kadar satışa kapalı kalır.","konu":"2.4"},{"id":"kh1-2-s117","tur":"coktan-secmeli","soru":"Hasarlı malzeme tutanağının nüshaları hangi bölümlere imza karşılığı teslim edilir?","secenekler":["Yalnızca ön büro, muhasebe ve güvenlik bölümlerine","Muhasebe, ön büro, teknik servis ve konuk ilişkileri","Çamaşırhane, ambar, teknik servis ve güvenlik birimi","Kat hizmetleri, mutfak, satış-pazarlama ve muhasebe"],"dogru":1,"aciklama":"Konuk kaynaklı hasarda tutanak, hasarın karşılanması için ilgili dört bölüme ulaşır.","konu":"2.4"},{"id":"kh1-2-s118","tur":"dogru-yanlis","soru":"Konuğun yanlış kullanımı yüzünden bozulan malzemenin bedelini oda görevlisi konuğa söyleyerek ister.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Oda görevlisi konuğa kendisi suçlama yapmaz; durumu kat şefine bildirir. Tutanak ve konuk görüşmesi kat şefinin işidir.","konu":"2.4"},{"id":"kh1-2-s119","tur":"coktan-secmeli","soru":"Hangi eşleştirme doğrudur?","secenekler":["Konuğun kırdığı sehpa: arıza bildirim formu; çalışmayan klima: hasarlı malzeme tutanağı","Konuğun kırdığı sehpa: ambar talep fişi; çalışmayan klima: mini buzdolabı çeki","Konuğun kırdığı sehpa: hasarlı malzeme tutanağı; çalışmayan klima: arıza bildirim formu","Her ikisi için de yalnızca sözlü bildirim yeterlidir"],"dogru":2,"aciklama":"Konuk kaynaklı hasar tutanakla, kullanımdan ya da eskimeden doğan arıza formla kayda geçer.","konu":"2.4"},{"id":"kh1-2-s120","tur":"coktan-secmeli","soru":"Otomasyon kullanılan bir otelde oda görevlisi arızayı telsizle bildirdi. Arızayı sisteme kim girer?","secenekler":["Sipariş alıcı","Kat şefi","Teknik servis ustası","Ön büro görevlisi"],"dogru":0,"aciklama":"Sipariş alıcı bildirimleri sisteme yazar; teknik servis, kat şefi ve ön büro aynı kaydı görür.","konu":"2.4"},{"id":"kh1-2-s121","tur":"coktan-secmeli","soru":"Teknik servis klima arızasını gideremedi. Oda otomasyonda nasıl görünür ve ön büro ne yapar?","secenekler":["V/C görünür; ön büro odayı satışa açar","C/O görünür; kat hizmetleri odayı temizler","H/U görünür; personel odayı kullanır","OOO görünür; ön büro rapora kaydeder"],"dogru":3,"aciklama":"Giderilemeyen arızalar sistemden izlenir; arızalı oda OOO olarak görünür ve satışa kapatılır.","konu":"2.4"},{"id":"kh1-2-s122","tur":"coktan-secmeli","soru":"Resepsiyon görevlisi Emre, mini buzdolabında suyun ücretsiz, atıştırmalıkların ücretli olduğunu check-in sırasında konuğa söylüyor. Bunun yararı nedir?","secenekler":["Oda görevlisi çek doldurmak zorunda kalmaz","Mini buzdolabı ürünlerinin tüketimi artar","Konuk çıkışta faturayla karşılaşınca şaşırmaz","Hasar tutanağına gerek kalmaz"],"dogru":2,"aciklama":"Ürünlerin ücretli olup olmadığı giriş sırasında anlatılırsa çıkıştaki itirazlar azalır.","konu":"2.5"},{"id":"kh1-2-s123","tur":"coktan-secmeli","soru":"Hatice, ahşap görünümlü kaplı mini buzdolabı kapağını silecek. Ne yapmalıdır?","secenekler":["Aşındırmayan temizlik maddesi ve yumuşak bez kullanmalıdır","Paslanmaz metal için kullandığı güçlü kimyasalı sürmelidir","Yüzeyi kuru fırçayla kazımalıdır","Dolabı su hortumuyla yıkamalıdır"],"dogru":0,"aciklama":"Yanlış kimyasal boyayı matlaştırabilir ya da lekeleyebilir; malzeme yüzey cinsine göre seçilir.","konu":"2.5"},{"id":"kh1-2-s124","tur":"coktan-secmeli","soru":"Dolu odada Hatice mini buzdolabını temizleyecek. Doğru yöntem hangisidir?","secenekler":["Ürünleri çıkarıp dolabı hortumla iyice yıkar ve kurutur","Yalnızca kuru bir bezle toz alıp bırakır","Ürünleri yenileriyle değiştirir, dolabı silmeden bırakır","İçini ve dışını nemli bezle silip kurular"],"dogru":3,"aciklama":"Dolu ve boş odalarda aynı sıra izlenir; bez ve yüzeye uygun kimyasalla hazırlanmış su önceden yanına alınır.","konu":"2.5"},{"id":"kh1-2-s125","tur":"coktan-secmeli","soru":"Çıkış yapılmış odanın mini buzdolabında konuktan kalan yarım bir içecek şişesi var. Bu şişeye ne yapılır?","secenekler":["Kapağı sıkılıp dolapta bırakılır","Poşete konulup dolaptan çıkarılır","Yeni konuk içsin diye dolapta saklanır","Doğrudan odanın çöp kutusuna atılır"],"dogru":1,"aciklama":"Konuğa ait kalan ürün buzdolabında bırakılmaz; temizlikten önce çıkarılır.","konu":"2.5"},{"id":"kh1-2-s126","tur":"coktan-secmeli","soru":"Mini buzdolabındaki çikolatanın son kullanma tarihi geçmiş. Bora ne yapar?","secenekler":["Etiketini değiştirip dolapta bırakır","Dolabın arkasına saklar","Yeni konuğa ikram olarak sunar","Ürünü kenara alır, yenisini ister"],"dogru":3,"aciklama":"Bozulmuş ya da tarihi geçmiş ürün sağlık sorunu ve güven kaybı yaratır.","konu":"2.5"},{"id":"kh1-2-s127","tur":"coktan-secmeli","soru":"Seda, eksilen su ve gazozları depodan almak istiyor. Doğru yol hangisidir?","secenekler":["Doğrudan ambara gidip sözlü olarak ister","Fişi yalnızca ambar görevlisine imzalatır, kat şefine bildirmez","Talep fişine yazar, kat şefine imzalatır, ambardan imza karşılığı alır","Mini buzdolabı çekine yazıp çeki ambara verir"],"dogru":2,"aciklama":"İmza zinciri sayesinde hangi ürünün depodan kimin eline geçtiği kayıtlı kalır.","konu":"2.5"},{"id":"kh1-2-s128","tur":"coktan-secmeli","soru":"Konuk akşam iki içecek aldı. Pelin çeki işaretleyip imzaladı. Çek kaç nüsha düzenlenir ve nüshalar nerede kalır?","secenekler":["İki nüsha: biri odada konukta, biri hesap için görevlide","İki nüsha: ikisi de hesap işlemleri için ön büroda","Tek nüsha: konuğa verilir, görevlide kayıt kalmaz","Üç nüsha: konukta, ön büroda ve muhasebede kalır"],"dogru":0,"aciklama":"Konuk tüketimini görür, görevli de hesap için kayıt tutar.","konu":"2.5"},{"id":"kh1-2-s129","tur":"coktan-secmeli","soru":"Mini buzdolabı çeki, konuk ayrılmadan bir gün önce ön büroya verilir. Bunun nedeni nedir?","secenekler":["Konuk çekteki yanlış işaretleri değiştirebilsin","Ön büro faturayı önceden hazırlayabilsin","Ürünler ambardan zamanında istenebilsin","Kat şefi çeki konuğa imzalatabilsin"],"dogru":1,"aciklama":"Çıkış günü kullanım olursa çek doldurularak yine ön büroya iletilir.","konu":"2.5"},{"id":"kh1-2-s130","tur":"coktan-secmeli","soru":"Mini buzdolabının konuk kaldığı süre boyunca her gün kontrol edilip tüketimin çeke işlenmesi neyi sağlar?","secenekler":["Ürünler günlük yenilendiği için tarih kontrolü gerekmez","Çıkışta fatura doğru çıkar, itirazlar azalır","Konuğun tüketimi sınırlanır","Çek ön büroya gitmeden kapanır"],"dogru":1,"aciklama":"Tüketim her gün kayda geçerse hesap sonradan tartışma konusu olmaz.","konu":"2.5"},{"id":"kh1-2-s131","tur":"dogru-yanlis","soru":"Mini buzdolabındaki ürünler, isimleri öne gelecek biçimde dizilerek yeni konuğa hazırlanır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Düzenli dizilmiş ürünler konuğun aradığını kolay bulmasını sağlar.","konu":"2.5"},{"id":"kh1-2-s132","tur":"coktan-secmeli","soru":"Selma kimyasallı suyla balkon zeminini yıkayacak. Eldiven ve maskeyi ne zaman takmalıdır?","secenekler":["Kimyasal kokusunu duymaya başlayınca","Yalnızca korkuluğa kimyasal sürülürken","Temizliğe başlamadan önce, işin başında","Zemini yıkadıktan sonra eller kirlenirse"],"dogru":2,"aciklama":"Koruyucu donanım işin başında takılır, işin ortasında değil; kimyasal ve toz baştan zarar verebilir.","konu":"2.6"},{"id":"kh1-2-s133","tur":"coktan-secmeli","soru":"Furkan balkona çıkmadan önce hangi araç gereçleri hazırlar?","secenekler":["Elektrikli süpürge, kablo uzatması, çamaşır sepeti ve kimyasal","Ambar talep fişi, anket formu, kova ve bez","Cam çekeceği, kova, mini buzdolabı çeki ve kimyasal","Süpürge, faraş, bez, kova, cam çekeceği, su, kimyasal ve çöp poşeti"],"dogru":3,"aciklama":"Eksik araçla balkona çıkmak ikinci kez gidip gelmek demektir; hazırlık zaman kazandırır.","konu":"2.6"},{"id":"kh1-2-s134","tur":"coktan-secmeli","soru":"Balkondaki eşyaları yerinden oynatmamak ve kaldırılan eşyayı iş bitince aynı yerine koymak neyi gösterir?","secenekler":["Konuğun mahremiyetine saygıyı ve güveni","Balkon temizliğinin zorunlu olmadığını","Teknik servisin onayını","Eşyanın tutanağa geçtiğini"],"dogru":0,"aciklama":"Konuğun eşyasının yerinde durması ona odasında güvende olduğunu hissettirir.","konu":"2.6"},{"id":"kh1-2-s135","tur":"coktan-secmeli","soru":"Taner balkon masasındaki küllükte izmaritler buldu. Doğru işlem hangisidir?","secenekler":["Küllüğü zemine silkeleyip süpürür","Küllüğü banyo lavabosunda yıkar","Küllüğü olduğu gibi bırakıp yalnızca masayı siler","Çöp poşetine boşaltıp poşetin ağzını bağlar"],"dogru":3,"aciklama":"Ağzı kapalı poşet kokuyu ve dağılmayı önler.","konu":"2.6"},{"id":"kh1-2-s136","tur":"coktan-secmeli","soru":"Aysel balkonu silecek: korkuluğun üstü, masa ve zemin. Doğru sıra hangisidir?","secenekler":["Önce korkuluğun üstü, sonra masa, en son zemin","Önce zemin, sonra masa, en son korkuluğun üstü","Önce masa, sonra zemin, en son korkuluğun üstü","Önce zemin, sonra korkuluğun üstü, en son masa"],"dogru":0,"aciklama":"Yukarıdan düşen toz ve damlalar aşağıyı kirletir; yukarıdan aşağıya silmek temizlenmiş yüzeyin yeniden kirlenmesini önler.","konu":"2.6"},{"id":"kh1-2-s137","tur":"coktan-secmeli","soru":"Murat balkon korkuluğunun vidasının gevşediğini fark etti. Bu kusur neden hemen bildirilmesi gereken bir kusurdur?","secenekler":["Korkuluk balkon mobilyası sayıldığı için","Balkon yüksekte olduğundan sallanan korkuluk güvenlik sorunudur","Boyası bozulan korkuluk görüntüyü bozduğu için","Teknik servis korkulukları yalnızca ayda bir kontrol ettiği için"],"dogru":1,"aciklama":"Balkon kapısı, korkuluk, aydınlatma ve mobilya sağlam olmalıdır. Güvenlik kusurları arıza formuyla teknik servise iletilir.","konu":"2.6"},{"id":"kh1-2-s138","tur":"coktan-secmeli","soru":"Ece balkondaki saksıların yapraklarını temizleyecek. Doğru yöntem hangisidir?","secenekler":["Yaprakları kimyasalla ovalar","Toz yaprağın doğal hâli olduğu için dokunmaz","Altlıkları yıkar, yaprakları nemli bezle usulca siler","Kuru yaprakları koparıp saksıyı zemine boşaltır"],"dogru":2,"aciklama":"Çiçekler balkonun görünümünü tamamlar; zarar vermeden temizlenir.","konu":"2.6"},{"id":"kh1-2-s139","tur":"dogru-yanlis","soru":"Fırtınadan sonra balkon giderinde biriken yaprakları almak, balkon temizliğinin bir parçasıdır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Tıkalı gider yağmurda balkonda su birikmesine yol açar; gider açık tutulur.","konu":"2.6"},{"id":"kh1-2-s140","tur":"coktan-secmeli","soru":"Okan, bir cam sehpayı ve bir ahşap komodini silecek. Kimyasal seçimini nasıl yapar?","secenekler":["İkisi için de aynı güçlü çok amaçlı kimyasalı kullanır","Cam sehpada ahşap ürününü, komodinde cam temizleyiciyi kullanır","Kimyasal kullanmadan kuru bezle ikisini de siler","Cam için cam temizleyiciyi, ahşap için ahşaba uygun ürünü seçer"],"dogru":3,"aciklama":"Yanlış kimyasal yüzeyi lekeleyebilir ya da bozabilir; seçim işe başlamadan, yüzeyin cinsine göre yapılır.","konu":"2.7.1"},{"id":"kh1-2-s141","tur":"coktan-secmeli","soru":"Rabia odaya girip toz almaya başlıyor. Doğru yol hangisidir?","secenekler":["Pencereden başlar, saat yönünün tersine ilerler, kapıyı en önce siler","Kapının yanından başlar, saat yönünde ilerler, giriş kapısını en son siler","Banyodan başlar, rastgele ilerler","Kapının yanından başlar ama giriş kapısını ilk siler"],"dogru":1,"aciklama":"Hep aynı yönde ilerlemek hiçbir yüzeyin atlanmamasını sağlar. Kapı son silinir.","konu":"2.7.1"},{"id":"kh1-2-s142","tur":"coktan-secmeli","soru":"Çıkış yapan konuğun odasında Yasemin gardırop raflarını, askı borusunu ve valiz yerini de siliyor. Dolu odada aynı ayrıntıya girilmemesinin nedeni nedir?","secenekler":["Eşya yerinde durduğu için iç yüzeylere ulaşılamaz","Dolu odalarda konuklar tozdan rahatsız olmaz","Dolu odalar çıkış odalarından daha az kirlenir","Kat şefi dolu odaların toz almasını denetlemez"],"dogru":0,"aciklama":"Boş odada bütün iç yüzeylere ulaşılır; dolu odada toz alma konuğun eşyasına dokunmadan sınırlı yapılır.","konu":"2.7.1"},{"id":"kh1-2-s143","tur":"coktan-secmeli","soru":"Hande, televizyon ünitesini silmeden önce fişi çekiyor ve bezi iyice sıkıyor. Bunun nedeni nedir?","secenekler":["Fiş çekilmezse toz ekrana yapışıp lekeler bırakır","Cihazın ayarları ve kayıtlı kanal listesi sıfırlanmasın diye","Islak bez elektrikle birleşirse kişi ve cihaz zarar görür","Ekran daha parlak görünsün ve leke bırakmasın diye"],"dogru":2,"aciklama":"Televizyon ünitesi bağlantısı kesilerek az nemli bezle silinir; düğme ve priz girişlerinde de bez iyice sıkılır.","konu":"2.7.1"},{"id":"kh1-2-s144","tur":"coktan-secmeli","soru":"Nergis odanın yarısında bezin grileştiğini görüp bezi yıkayıp sıkıyor. Bunun nedeni nedir?","secenekler":["Gri bez kimyasalın etkisini daha da artırır","Bez ağırlaşınca elde taşınamaz hâle gelir","Kirli bez tozu yüzeyden almak yerine yüzeye yayar","Kuru bez yüzeyi çizip zarar verir"],"dogru":2,"aciklama":"Bez sık sık durulanıp sıkılırsa toz alma işi gerçekten tozu uzaklaştırır.","konu":"2.7.1"},{"id":"kh1-2-s145","tur":"coktan-secmeli","soru":"Nur klozet çevresini kırmızı bezle, bardakları ayrı bir bezle siliyor. Bu düzenin asıl amacı nedir?","secenekler":["Mikropların alandan alana taşınmasını önlemek","Bezlerin daha uzun ömürlü olmasını sağlamak","Temizliği hızlandırmak","Bezleri kolay saymak"],"dogru":0,"aciklama":"Renk ayrımı hastalık ve salgın riskini azaltır; mavi ve yeşil bezin hangi alanda kullanılacağı ise işletmeye göre değişebilir.","konu":"2.7.1"},{"id":"kh1-2-s146","tur":"coktan-secmeli","soru":"Hangi eşleştirme doğrudur?","secenekler":["Kırmızı: lavabo ve armatür; sarı: klozet çevresi ve küvet","Kırmızı: tuvalet klozet çevresi; sarı: lavabo, armatür ve küvet","Kırmızı: cam ve toz alma; sarı: banyo zemini ve küvet","Kırmızı: toz alma; sarı: küvet ve klozet çevresi"],"dogru":1,"aciklama":"Kırmızı bez tuvalet için, sarı bez ıslak alanlar için ayrılır; yer değiştirirse mikrop yayılır.","konu":"2.7.1"},{"id":"kh1-2-s147","tur":"coktan-secmeli","soru":"Derya lavaboyu ve bataryayı sarı bezle sildi. Sıra klozete geldi. Ne yapmalıdır?","secenekler":["Sarı bezi iyice durulayıp klozette de kullanmalı","Sarı bezi ters çevirip temiz yüzeyiyle klozeti silmeli","Kırmızı bezi önce lavaboda kullanıp sonra klozete geçmeli","Klozet için kırmızı bezi kullanmalı, sarı bezi götürmemeli"],"dogru":3,"aciklama":"Islak alan bezi ile tuvalet bezi karıştırılırsa mikrop yayılır; bu yüzden her alanın rengi sabittir.","konu":"2.7.1"},{"id":"kh1-2-s148","tur":"dogru-yanlis","soru":"Kırmızı bez gerekirse tuvalet dışında da, örneğin lavabo silmek için kullanılabilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kırmızı bez tuvalet çevresi için ayrılır ve başka alanda kullanılmaz; hijyen riski yüksek alanın bezi başka yerde kullanılırsa mikrop yayılır. Mavi ve yeşil bezlerin anlamı ise işletmeye göre değişir.","konu":"2.7.1"},{"id":"kh1-2-s149","tur":"coktan-secmeli","soru":"Batuhan odadaki bardakları silecek ve hijyen riskini azaltmak istiyor. Bez yerine ne tercih edebilir?","secenekler":["Başka bir alanda kullanılan nemli bir bez","Yıkanıp kurutulmuş eski bir banyo bezi","Sert saplı küçük bir yıkama fırçası","Kullanıldıktan sonra atılan kâğıt havlu"],"dogru":3,"aciklama":"Yüksek riskli alanlarda işletmeler bezden çok tek kullanımlık havluyu seçebilir.","konu":"2.7.1"},{"id":"kh1-2-s150","tur":"coktan-secmeli","soru":"Sabah vardiyasında Aslı’nın listesinde VIP oda, “odamı hemen temizleyin” kartı asılı oda, çıkış odası, dolu oda ve boş oda var. Genel öncelik sırası hangisidir?","secenekler":["Çıkış odası, VIP oda, boş oda, dolu oda, “odamı hemen temizleyin” odası","“Odamı hemen temizleyin” odası, boş oda, çıkış odası, VIP oda, dolu oda","VIP oda, “odamı hemen temizleyin” odası, çıkış odası, dolu oda, boş oda","Dolu oda, çıkış odası, VIP oda, boş oda, “odamı hemen temizleyin” odası"],"dogru":2,"aciklama":"VIP ve erişilebilir odalar, konuğun hemen istediği oda ve çıkış odaları öne alınır; dolu ve boş odalar sonra gelir.","konu":"2.7.1"},{"id":"kh1-2-s151","tur":"coktan-secmeli","soru":"Buklet malzemeleri hangi etkenlere göre değişir?","secenekler":["İşletmenin standardına, hizmet çeşidine ve yıldızına göre","Konuğun uyruğuna, yaşına ve rezervasyon yoluna göre","Oda görevlisinin kişisel zevkine ve alışkanlığına göre","Odanın bulunduğu kata, yönüne ve manzarasına göre"],"dogru":0,"aciklama":"Buklet malzemeleri işletmenin saygınlık göstergesidir; kalitesi, hizmet çeşidi ve konsepti malzemeyi belirler.","konu":"2.7.2"},{"id":"kh1-2-s152","tur":"coktan-secmeli","soru":"Pınar TV masasına konuğun hemen göreceği malzemeleri dizecek. Hangi grup kırtasiye malzemesidir?","secenekler":["Dikiş seti, ayakkabı bezi, kolonya ve bardak kapağı","Dosya, zarf, blok not ve kalem","Anket formu, çamaşırhane listesi, terlik ve bornoz","Şampuan, diş fırçası, sabun ve havlu"],"dogru":1,"aciklama":"Kırtasiye malzemeleri konuğun yazı yazma ihtiyacı içindir ve televizyon masasında en çok görünen yere konur.","konu":"2.7.2"},{"id":"kh1-2-s153","tur":"coktan-secmeli","soru":"Odadaki anket formunu dolduran konuk banyodaki sıcak suyun geç geldiğini yazıyor. Formda ad soyad istenmemesinin amacı nedir?","secenekler":["Formun küçük kalması","Konuğun düşüncelerini rahatça yazabilmesi","Teknik servisin kimseyi aramak zorunda kalmaması","Konuğun imza atmak zorunda kalması"],"dogru":1,"aciklama":"Anket formu memnuniyet, öneri ve şikâyet içindir; sonuçlara göre işletme değişiklik yapabilir.","konu":"2.7.2"},{"id":"kh1-2-s154","tur":"coktan-secmeli","soru":"Konuk kasayı ilk denemede kapatabilmek için odadaki hangi karta bakar?","secenekler":["Nevresim değişim kartına","Şezlong bilgilendirme kartına","Kasa kullanım kartına","İyi geceler kartına"],"dogru":2,"aciklama":"Otel bilgi kartları konuğa otelin hizmetleri ve odadaki donanım hakkında bilgi verir; her kart bir konuya aittir.","konu":"2.7.2"},{"id":"kh1-2-s155","tur":"coktan-secmeli","soru":"Kapı kolu kartları hakkında aşağıdakilerden hangisi yanlıştır?","secenekler":["DND kartı kapı koluna asılır","Diğer kartlar gerektiğinde konuk tarafından doldurulup görevlinin görebileceği biçimde bırakılır","Kartlar konuğun isteğine zamanında cevap vermeyi sağlar","Konuk kapı koluna kart asabilmek için resepsiyonu aramak zorundadır"],"dogru":3,"aciklama":"Kartlar konuğun kat hizmetleriyle sessizce iletişim kurması içindir; arama gerekmez.","konu":"2.1.3"},{"id":"kh1-2-s156","tur":"coktan-secmeli","soru":"Çamaşırhane listesi ve torbası odada nereye konur ve çamaşırı konuktan kim nasıl teslim alır?","secenekler":["Gardırobun içine; oda temizleme görevlisi konuktan belgeyle teslim alır","Banyodaki havlu rafına; konuk çamaşırı çamaşırhaneye kendisi götürür","Balkondaki masaya; bellboy konuktan sözlü teslim alır","Gardırobun içine; ön büro konuktan belgesiz teslim alır"],"dogru":0,"aciklama":"Çamaşır, oda temizleme görevlisi tarafından konuktan belgeyle teslim alınır; liste ve torba gardırop içindedir.","konu":"2.7.2"},{"id":"kh1-2-s157","tur":"coktan-secmeli","soru":"Gömleğinin düğmesi kopan konuk odada ihtiyacını karşılayacak bir malzeme arıyor. Hangisine bakmalıdır?","secenekler":["Çamaşırhane torbasına","Ayakkabı çekeceğine","Dikiş setine","Bardak kapağına"],"dogru":2,"aciklama":"Dikiş seti düğme kopması gibi acil küçük sorunları çözen bir eşantiyondur; konuk resepsiyonu aramak zorunda kalmaz.","konu":"2.7.2"},{"id":"kh1-2-s158","tur":"coktan-secmeli","soru":"Çocuklu ailenin odasında Ela hangi malzemeleri hazırlar?","secenekler":["Su ısıtıcısı ve poşet çay","Dikiş seti ve ayakkabı çekeceği","Faks kâğıdı ve blok not","Çocuk bornozu ve plaj havlusu"],"dogru":3,"aciklama":"Çocuklu aile setinde losyon, şampuan, güneş kremi, bornoz, terlik ve plaj havlusu gibi malzemeler bulunabilir.","konu":"2.7.2"},{"id":"kh1-2-s159","tur":"coktan-secmeli","soru":"Hangi grup, “buklet malzemesi sayılmaz ama işletme isteğe bağlı olarak odaya koyabilir” diye tanımlanır?","secenekler":["Dosya, zarf, blok not ve kalem","Su ısıtıcısı, poşet çay ve kahve","Şampuan, sabun ve diş fırçası","Dikiş seti, ayakkabı bezi ve terlik"],"dogru":1,"aciklama":"İçecek hazırlama takımı konuğa resepsiyonu aramadan küçük bir mola verme imkânı sunar.","konu":"2.7.2"},{"id":"kh1-2-s160","tur":"coktan-secmeli","soru":"Oda görevlisi Pelin, ikinci kez gelen konuğun odasına ekstra malzeme bırakmak istiyor. Doğru yaklaşım hangisidir?","secenekler":["İşletme prosedüründe varsa bırakır; kendi başına karar vermez","Her konuk için kendi kararıyla, prosedüre bakmadan bırakır","Yalnız ilk kez gelen konuklar için ve her zaman bırakır","Ön büroya sormadan konuğa oda ücreti indirimi önerir"],"dogru":0,"aciklama":"VIP, tekrar gelen ve özel durumu olan konuklara ekstra malzeme yalnız prosedürde varsa konur.","konu":"2.7.2"},{"id":"kh1-2-s161","tur":"coktan-secmeli","soru":"Aysu, kırtasiyeyi, çamaşırhane listesini ve banyo malzemelerini yerleştiriyor. Doğru yerleştirme hangisidir?","secenekler":["Kırtasiye gardırop içine, çamaşırhane listesi TV masasına, banyo malzemeleri banyoya","Kırtasiye TV masasına, çamaşırhane listesi gardırop içine, banyo malzemeleri banyoya","Kırtasiye banyoya, çamaşırhane listesi TV masasına, banyo malzemeleri gardırop içine","Kırtasiye TV masasına, çamaşırhane listesi banyoya, banyo malzemeleri gardırop içine"],"dogru":1,"aciklama":"Malzemeler kullanım amacına göre yerleştirilir; konuk aradığını aramadan bulur.","konu":"2.7.2"},{"id":"kh1-2-s162","tur":"coktan-secmeli","soru":"Cem bilgi kartlarını TV masasına koyarken otelin amblemini nasıl çevirir ve neden?","secenekler":["Altta ve gizli; kartın asıl metni öne çıksın diye","Arkaya bakacak biçimde; kartlar birbirine karışmasın diye","Üstte ve okunur; malzeme işletmenin imajını taşısın diye","Fark etmez; amblem yalnızca fatura ve zarflar içindir"],"dogru":2,"aciklama":"İşletmenin adı ve amblemi üst kısımda ve görünür durursa malzeme işletmenin imajını yansıtır.","konu":"2.7.2"},{"id":"kh1-2-s163","tur":"coktan-secmeli","soru":"Üç kişinin kalacağı odaya buklet malzemeleri kaç set alınır ve neden?","secenekler":["İki set; üçüncü set istenirse sonradan getirilir","Beş set; yedek bulunsun diye fazladan konur","Dört set; çift sayıya tamamlansın diye fazladan alınır","Üç set; eksiği aramaya, fazlası israfa yol açar"],"dogru":3,"aciklama":"Konuk odasında kalan kişi sayısı kadar malzeme yerleştirilir.","konu":"2.7.2"},{"id":"kh1-2-s164","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi süpürmenin tanımına uyar?","secenekler":["Görünen ve görünmeyen kirin araçlarla ortamdan alınması","Yüzeylerdeki tozun nemli bezle silinerek alınması","Kirli bezin sık sık durulanıp yeniden kullanılması","Atıkların türüne göre ayrı poşetlere konulması"],"dogru":0,"aciklama":"Süpürme zemin temizliğidir; yüzeylerdeki toz ise toz alma işlemiyle alınır.","konu":"2.7.3"},{"id":"kh1-2-s165","tur":"coktan-secmeli","soru":"Sabah 09.00’da yeni açılan katı gezen kat şefi Hülya, hijyen nedeniyle halı kullanımının azaldığını biliyor. Yeni odalarda hangi zeminler tercih edilmeye başlanmıştır?","secenekler":["Kaliteli PVC, taş ya da ahşap","Kalın ve koyu renkli halı","Yünden dokunmuş el yapımı kilim","Cilasız çıplak beton zemin"],"dogru":0,"aciklama":"Zemin işletmenin konseptine göre seçilir; halının yerini hijyenik zeminler almaktadır.","konu":"2.7.3"},{"id":"kh1-2-s166","tur":"coktan-secmeli","soru":"Soğuk bir dağ bölgesindeki kayak otelinde odaların zemini halıyla kaplı. Halı, ev akarı alerjisi olan konuk için hangi özelliğiyle önem taşır?","secenekler":["Koyu renkli, desenli olup lekeyi gizlemesiyle","Çok kalın ve yumuşak olup ses yutmasıyla","Antialerjik ve antibakteriyel olmasıyla","Parlak ve kaygan olup kolay silinmesiyle"],"dogru":2,"aciklama":"Halı antialerjik, antibakteriyel, kolay temizlenebilir ve kir tutmayan türde olmalıdır.","konu":"2.7.3"},{"id":"kh1-2-s167","tur":"coktan-secmeli","soru":"Odaların halıyla kaplı olması en çok hangi koşula bağlıdır?","secenekler":["Sıcak bir bölgedeki plaj otelinde olmaya","Soğuk bölgede kış turizmine hizmet vermeye","Büyük bir şehirde iş seyahati oteli olmaya","Yalnızca yaz sezonunda açık olmaya"],"dogru":1,"aciklama":"Halılı odalar genellikle soğuk bölgelerdeki ve kış turizmine hitap eden işletmelerde bulunur.","konu":"2.7.3"},{"id":"kh1-2-s168","tur":"coktan-secmeli","soru":"Arda süpürürken sırtından yakınıyor. Doğru duruş hangisidir?","secenekler":["Öne eğilip yükü belinde taşımak","Sırtını bükerek süpürgeyi çok uzun saplı tutmak","Tek dizini yere koyup çömelerek süpürmek","Dik durup yükü belde değil kollarda taşımak"],"dogru":3,"aciklama":"Doğru duruş yorgunluğu ve bel ağrısı riskini azaltır.","konu":"2.7.3"},{"id":"kh1-2-s169","tur":"coktan-secmeli","soru":"Banu elektrikli süpürgeyi prize taktı. Kabloyu nasıl ayarlar?","secenekler":["En uzak noktaya yetişecek kadar açar, kabloya basmaz","Kısa tutar, prizi sık sık değiştirir","Kapı koluna bağlayıp sabitler","Prizi odanın ortasına alıp kabloyu kısa bırakır"],"dogru":0,"aciklama":"Yetersiz uzunluk süpürmeyi yarıda kestirir; kabloya basmak hem kabloya hem görevliye zarar verir.","konu":"2.7.3"},{"id":"kh1-2-s170","tur":"coktan-secmeli","soru":"Süpürmeden önce Tolga halıda küçük bir toka buluyor ve sandalyeyi kenara çekiyor. Bu hazırlığın amacı nedir?","secenekler":["Halının yeniden döşenmesini kolaylaştırmak","Eşyaların yerini kalıcı olarak değiştirmek","Toka ve sandalyeyi çöpe ayırıp odadan çıkarmak","Süpürgeyi korumak ve süpürmeyi kesintisiz yapmak"],"dogru":3,"aciklama":"Çivi, toka gibi parçalar makineye zarar verir; sandalye ve puf gibi taşınabilir eşyalar süpürmeyi engeller.","konu":"2.7.3"},{"id":"kh1-2-s171","tur":"coktan-secmeli","soru":"Banu odayı en uzak noktadan başlayıp kapıya doğru süpürüyor. Bunun nedeni nedir?","secenekler":["Kablonun kısa kalması","Kapının önünün en kirli yer olması","Temizlenmiş zemine yeniden basılmaması","Kat şefinin sıralamayı bu yönde istemesi"],"dogru":2,"aciklama":"En uzak noktadan kapıya doğru ilerlemek, süpürülmüş zemini yeniden kirletmeyi önler.","konu":"2.7.3"},{"id":"kh1-2-s172","tur":"coktan-secmeli","soru":"Barış ahşap zeminli bir odayı, sonra halılı bir odayı süpürecek. Aparatı nasıl seçer?","secenekler":["Ahşap zeminde halı aparatını, halılı odada sert zemin aparatını takar","Ahşap zeminde sert zemin aparatını, halılı odada halı aparatını takar","İki zeminde de aynı aparatı kullanır","Ahşap zeminde aparatsız, halılı odada sert zemin aparatıyla çalışır"],"dogru":1,"aciklama":"Yanlış aparat zeminin kirini almaz ya da zemini çizebilir.","konu":"2.7.3"},{"id":"kh1-2-s173","tur":"coktan-secmeli","soru":"“Sizin odaya son bakışınız, konuğun ilk bakışıdır” sözünü uygulayan Burcu kapıyı kapatmadan ne yapar?","secenekler":["Konuk gelince odayı birlikte kontrol etmek için bekler","Kat şefinin kontrol edeceğini düşünüp hemen çıkar","Yastıkları, perdeyi ve zemini bir kez daha gözden geçirir","Hızlıca kapıyı kapatıp sonraki odaya geçer"],"dogru":2,"aciklama":"Görevlinin son bakışı konuğun ilk izlenimidir; küçük kusurlar konuktan önce yakalanır.","konu":"2.7.3"},{"id":"kh1-2-s174","tur":"coktan-secmeli","soru":"Koridorda karşılaştığı konuk Emel’le şakalaşmak istiyor. Emel’in doğru tutumu hangisidir?","secenekler":["Konuğa uyum sağlayıp şakalaşır, samimiyet güven verir","Selam vermeden yürümeye devam eder","Uzun bir sohbete girişir","Gülümseyip selam verir, laubali olmadan yoluna devam eder"],"dogru":3,"aciklama":"Kibar ama mesafeli dil, konuğa saygıyı ve güveni birlikte verir.","konu":"2.7.3"},{"id":"kh1-2-s175","tur":"coktan-secmeli","soru":"Odası aslında temizlenmiş olan konuk “oda temizlenmedi” diye kızıyor. Sude ne yapar?","secenekler":["Odanın temiz olduğunu açıklayarak konuğu ikna etmeye çalışır","Tartışmadan özür diler, çözmeye çalışır; çözemezse şefe iletir","Sesini yükseltmeden odadan çıkar, kimseye söylemez","Konuğa haksız olduğunu nazikçe hatırlatır"],"dogru":1,"aciklama":"Haksız bile olsa şikâyet eden konuk karşısında soğukkanlı ve kibar kalınır; tartışmak sorunu büyütür.","konu":"2.7.3"},{"id":"kh1-2-s176","tur":"dogru-yanlis","soru":"Temizlik sırasında oda telefonu çalarsa oda görevlisi açıp konuğun odada olmadığını söyleyebilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Oda temizleme görevlisi çalıştığı odanın telefonunu açmaz; konuğa ait hatta cevap vermek mahremiyeti zedeler.","konu":"2.7.3"},{"id":"kh1-2-s177","tur":"coktan-secmeli","soru":"Konuklara ve ekip arkadaşlarına hitap için hangisi doğrudur?","secenekler":["Ad ve “bey/hanım” ile, “siz” diyerek hitap edilir; çağrılınca “Efendim” denir","Konuğa “siz”, ekip arkadaşına “sen” denir; çağrılınca “Efendim” denir","Herkese soyadıyla seslenilir; çağrılınca “Evet?” denir","Kısa olsun diye ilk adla “sen” denir; çağrılınca “Buyur” denir"],"dogru":0,"aciklama":"Saygılı hitap hem konuğa hem ekip arkadaşına güven verir.","konu":"2.7.3"},{"id":"kh1-2-s178","tur":"coktan-secmeli","soru":"Elektrikli süpürge gibi ses çıkaran araçlar için hangisi doğru uygulamadır?","secenekler":["Konuklar kattan ayrılınca çalıştırılır, kapılar sessiz kapanır","Sabah erken saatte, odalar boşalmadan çalıştırılır; kapılar açık kalır","Konuk odadayken kapı kapatılıp çalıştırılır","Gürültü sorun olmadığı için her saatte çalıştırılır"],"dogru":0,"aciklama":"Gürültü konuğun uykusunu ve dinlenmesini bozar; sessizlik hizmetin bir parçasıdır.","konu":"2.7.3"},{"id":"kh1-2-s179","tur":"coktan-secmeli","soru":"Defne temizlik sırasında odada beklenmedik bir durumla karşılaşıyor. Hata riskini azaltmak için ne yapar?","secenekler":["Çözüm için önce konuğa danışıp onun dediğini yapar","Ön büroya doğrudan bildirip şefi atlar","Kendi bildiği gibi çözüp sonradan raporlar","Kararı vermeden önce kat şefine haber verir"],"dogru":3,"aciklama":"Herhangi bir sorunda ilk başvurulacak kişi kat şefidir; yetkili kişiye ulaşmak hata riskini azaltır.","konu":"2.7.3"},{"id":"kh1-2-s180","tur":"dogru-yanlis","soru":"Konuk sorarsa personel eksikliği gibi işletme sorunlarını kısaca anlatmak dürüstlüğün gereğidir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"İşletmenin iç sorunları konuğa aktarılmaz; bu konuyu büyütür ve güveni zedeler. “Bunu kat şefimize ileteyim” denir.","konu":"2.7.3"},{"id":"kh1-2-s181","tur":"senaryo","durum":"Sabah 09.00. Çıkış yapılmış odayı hazırlarken klimanın soğutmadığını fark ediyorsun. Birkaç saat sonra bu odaya yeni konuk gelecek.","soru":"Ne yaparsın?","secenekler":["Arızayı teknik servise sözlü bildirir, formu yazmadan odayı teslim edersin.","Odayı hazırlar, formu vardiya sonunda doldurmak üzere not alırsın.","Arızayı forma yazıp teknik servise bildirir, kat şefine haber verirsin.","Odanın satışa kapatılmasını isteyip teknik servise haber vermezsin."],"dogru":2,"aciklama":"Arıza yazılı bildirilirse unutulmaz ve kimin ne zaman haber verdiği bellidir. Yeni konuk gelmeden giderilemezse oda satışa kapatılır.","konu":"2.4"},{"id":"kh1-2-s182","tur":"senaryo","durum":"Sabah 11.15. Çıkış yapılmış odada sehpanın kırık olduğunu görüyorsun. Konuk resepsiyondan henüz ayrılmamış.","soru":"Ne yaparsın?","secenekler":["Konuğa yetişip hasarın bedelini ödemesini istersin.","Sehpaya dokunmadan kat şefine haber verirsin.","Tutanağı kendin düzenleyip ön büroya imzalatırsın.","Sehpayı teknik servise gönderir, kimseye bildirmezsin."],"dogru":1,"aciklama":"Hasarı kat şefi saptar, tutanağı o düzenler ve ön büro bilgilendirilir. Konuğa suçlama yapmak oda görevlisinin işi değildir.","konu":"2.1"},{"id":"kh1-2-s183","tur":"senaryo","durum":"Öğleden sonra 15.00. Dolu odanın mini buzdolabını kontrol ederken konuğun iki içecek aldığını, ama çekte işaretli olmadığını görüyorsun.","soru":"Ne yaparsın?","secenekler":["İçecekleri yenileriyle değiştirir, çekte işaretlemezsin.","Konuğun tüketimini kendisinin yazmasını beklersin.","Çekte işaretleyip imzalar, bir nüshayı odada bırakırsın.","Çeki işaretler ama imzalamaz, nüshayı odada bırakmazsın."],"dogru":2,"aciklama":"Tüketim her gün çeke işlenirse çıkışta fatura doğru çıkar. Bir nüsha konuğun görmesi için odada kalır, öteki hesap için görevlide.","konu":"2.5"},{"id":"kh1-2-s184","tur":"senaryo","durum":"Sabah 10.40. Balkonu temizlerken askıda konuğun mayosunu görüyorsun; balkon zemini kirli.","soru":"Ne yaparsın?","secenekler":["Mayoyu kaldırıp banyoda asar, temizlik sonunda geri götürürsün.","Zemini kirli bırakıp yalnızca cam ve korkuluğu silersin.","Mayoyu yıkansın diye çamaşırhane torbasına koyarsın.","Mayoya dokunmadan çevresini temizlersin."],"dogru":3,"aciklama":"Konuğun eşyası yerinden oynatılmaz; özellikle askıdaki çamaşıra dokunulmaz. Temizlik çevresinden yapılır.","konu":"2.6"},{"id":"kh1-2-s185","tur":"senaryo","durum":"Öğleden sonra 14.10. Konuk odasını temizlerken oda telefonu çalmaya başlıyor.","soru":"Ne yaparsın?","secenekler":["Açıp konuğun şu an odada olmadığını söylersin.","Açmaz, işine devam edersin.","Açıp arayanın bıraktığı mesajı not alırsın.","Ahizeyi kaldırıp hemen kapatırsın."],"dogru":1,"aciklama":"Konuğa ait hatta görevlinin cevap vermesi mahremiyeti zedeler; oda temizleme görevlisi odanın telefonunu açmaz.","konu":"2.7.3"},{"id":"kh1-2-s186","tur":"senaryo","durum":"Sabah 10.00. Kırmızı bezle klozet çevresini temizledin. Şimdi odanın tozunu alacaksın.","soru":"Hangi bezi kullanırsın?","secenekler":["Genel alanlar için ayrılmış, temiz bezi kullanırsın.","Kırmızı bezi iyice yıkayıp sıkarak kullanırsın.","Banyodaki sarı bezi durulayıp kullanırsın.","Elindeki bezlerden en temizini seçersin."],"dogru":0,"aciklama":"Renkli bezlerin amacı çapraz bulaşmayı önlemektir. Tuvalet bezi başka alanda kullanılmaz; toz alma için genel alan bezi seçilir.","konu":"2.7.1"},{"id":"kh1-2-s187","tur":"coktan-secmeli","soru":"Selin 310 numaralı dolu odanın günlük temizliğini bitirdi. Raporda OCC yazan odayı nasıl gösterir ve bununla kat şefine ne bildirir?","secenekler":["V/C yazar; oda boşaldı ve satışa hazır.","OK yazar; o günkü temizlik bitti, odaya yeniden bakmak gerekmiyor.","C/O yazar; konuk çıkış yaptı, oda yeniden temizlenecek.","OCC olarak bırakır; temizlik ancak kat şefi kontrol edince işaretlenir."],"dogru":1,"aciklama":"OK, dolu odanın o günkü temizliğinin bittiğini gösterir. V/C konuksuz odaya, C/O çıkış yapılmış odaya aittir; konuk hâlâ odada olduğundan bu ikisi uymaz.","konu":"2.1.1"},{"id":"kh1-2-s188","tur":"coktan-secmeli","soru":"Akşam raporunda 214 numaralı odada C/IN yazıyor. Ertesi sabah aynı oda raporda hangi kısaltmayla görünür?","secenekler":["V/C","C/O","S/O","OCC"],"dogru":3,"aciklama":"C/IN yeni giriş yapılmış odadır; konuk kalmaya devam ettiğinden ertesi sabah oda OCC (dolu) olur. S/O yalnız konuğun geceyi dışarıda geçirdiği odada kullanılır.","konu":"2.1.1"},{"id":"kh1-2-s189","tur":"coktan-secmeli","soru":"Yeni işe başlayan bir oda görevlisinin güven veren, düzenli ve görgü kurallarını bilen biri olması neden özellikle beklenir?","secenekler":["Konuğun en özel alanına girdiği için","Oda sayısının her katta farklı olduğu için","Vardiya saatlerinin esnek tutulduğu için","Kat arabasını kendisinin seçtiği için"],"dogru":0,"aciklama":"Kat hizmetleri çalışanı konuğun en özel alanı olan odaya girer; bu yüzden konuğun ona güvenmesi gerekir. Kat arabası ya da vardiya düzeni bu beklentinin nedeni değildir.","konu":"2.1.2"},{"id":"kh1-2-s190","tur":"coktan-secmeli","soru":"Sabah toplantısına isimliğini takmadan gelen Murat uyarılıyor. İsimliğin konuk açısından asıl işlevi nedir?","secenekler":["Görevlinin hangi odalardan sorumlu olduğunu gösterir.","Görevlinin vardiya saatini belirtir.","Konuğun görevliye adıyla seslenmesini sağlar.","Görevlinin kat şefine bağlı olduğunu gösterir."],"dogru":2,"aciklama":"Üniforma personeli tanıtır, isimlik ise konuğun görevliye adıyla hitap etmesini sağlar. Sorumlu olunan odalar isimlikte değil, günlük iş programında yazılıdır.","konu":"2.1.1"},{"id":"kh1-2-s191","tur":"coktan-secmeli","soru":"Çıkış günü sabah 10.30’da kat şefi Hülya, 504 numaralı odanın kapısında DND kartı görüyor. Önce ne yapar?","secenekler":["Pas anahtarıyla girip odayı kontrol eder.","Kapıyı üç kez çalıp yanıt beklemeden içeri girer.","Kart kalkana kadar odayı listeden çıkarır.","Konuğu telefonla arar ve ön büroya bilgi verir."],"dogru":3,"aciklama":"Çıkış gününde DND varsa konuk telefonla aranır ve ön büro bilgilendirilir; konuğun ayrıldığı, bir sorun olmadığı anlaşılınca oda açılır. Hemen girmek DND’ye saygıyı ortadan kaldırır.","konu":"2.1.3"},{"id":"kh1-2-s192","tur":"coktan-secmeli","soru":"507 numaralı odanın penceresi hiç açılmıyor. Temiz hava sağlamak için en uygun yol hangisidir?","secenekler":["Odadaki havalandırma ünitesini çalıştırmak","Odaya güçlü kokulu oda spreyi sıkmak","Perdeleri sonuna kadar açıp güneş girmesini sağlamak","Klimayı en düşük dereceye alıp kapıyı kapatmak"],"dogru":0,"aciklama":"Pencere açılmıyorsa oda, içindeki havalandırma ünitesi çalıştırılarak havalandırılır. Sprey havayı yenilemez, yalnızca kokuyu örter; perdeyi açmak ya da klimayı kısmak da temiz hava getirmez.","konu":"2.2"},{"id":"kh1-2-s193","tur":"coktan-secmeli","soru":"Murat odayı havalandırdıktan sonra pencereyi hemen kapatıyor. Bu alışkanlığın işletmeye en doğrudan yararı hangisidir?","secenekler":["Odadaki bütün kokular kalıcı olarak yok olur.","Temizlik süresi kısalır, oda daha erken satılır.","Gereksiz ısı kaybı önlenir, enerji giderleri azalır.","Konuk odaya girer girmez klimayı açma gereği duymaz."],"dogru":2,"aciklama":"Doğru zamanda ve sürede havalandırma, gereksiz sıcak ya da soğuk hava kaybını önleyerek enerji tasarrufu sağlar. Süre kısalmasının enerjiyle bağı yoktur.","konu":"2.2"},{"id":"kh1-2-s194","tur":"coktan-secmeli","soru":"Hangi atık türü ve örneği doğru eşleştirilmiştir?","secenekler":["Bahçe atığı: tarla ve seralardan çıkan bitki artıkları","Evsel atık: otel odasında biriken günlük atıklar","Tıbbi atık: parkta ve bahçede biriken yapraklar","Tarımsal atık: hastane ve kliniklerde oluşan atıklar"],"dogru":1,"aciklama":"Evde ve otel odasında biriken günlük atıklar evsel atıktır. Tarla ve seradan çıkanlar tarımsal, parktaki yapraklar bahçe, hastanede oluşanlar tıbbi atık sınıfına girer.","konu":"2.3"},{"id":"kh1-2-s195","tur":"coktan-secmeli","soru":"Selin odayı toplamadan önce donanım kontrolü yapıyor. Aşağıdakilerden hangisi bu kontrolde yanlış bir uygulamadır?","secenekler":["Yanmayan okuma lambasını küçük sayıp forma yazmamak","Televizyonu açıp kanalların geldiğini kontrol etmek","Emanet kasanın açılıp kapandığını elle denemek","Priz ve lamba anahtarlarının çalıştığına bakmak"],"dogru":0,"aciklama":"Yanmayan lamba küçük görünse de konuğun ilk akşam fark edeceği bir eksikliktir; forma yazılıp bildirilmelidir. Diğer üç uygulama donanım kontrolünün parçasıdır.","konu":"2.4"},{"id":"kh1-2-s196","tur":"coktan-secmeli","soru":"Balkon temizliğiyle ilgili aşağıdakilerden hangisi yanlıştır?","secenekler":["Balkon kapısının camı silinip kurulanır.","Masa ve sandalyenin ayakları da silinip kurulanır.","Lamba silindikten sonra anahtarı denenir.","Balkon lambası yanıkken ıslak bezle silinir."],"dogru":3,"aciklama":"Balkon lambası kapalıyken nemli bezle silinir, kurulanır ve sonra çalıştığı denenir. Mobilyanın ayakları ve altı gözden kaçan yerlerdir; onlar da silinir.","konu":"2.6"},{"id":"kh1-2-s197","tur":"coktan-secmeli","soru":"Deniz manzaralı bir odanın balkonunda yaprak ve toz birikmiş. Balkon temizliği bu odada neden ayrıca önemlidir?","secenekler":["Balkon, konuğun odada en uzun süre kaldığı yerdir.","Balkon temizliği yalnızca manzaralı odalarda yapılır.","Kirli balkon, güzel manzarayı gölgede bırakır.","Balkonun temizliği konuk talebine bağlıdır."],"dogru":2,"aciklama":"Manzaralı odayı değerli kılan çoğu zaman balkondur; kirli balkon konuğun beklentisini düşürür. Balkon temizliği talebe bağlı değil, oda temizliğinin parçasıdır.","konu":"2.6"},{"id":"kh1-2-s198","tur":"coktan-secmeli","soru":"Seda klima kumanda panelini ve hava ızgaralarını toz alma turunda atlamıyor. Bunun nedeni nedir?","secenekler":["Izgaralar temizlenmezse klima mutlaka bozulur.","Panele konuk sık dokunur, ızgaradaki toz çabuk fark edilir.","Bu bölümleri başka hiçbir görevli temizleyemez.","Izgaralar temizlenmezse klima konuğa ek ücret yansıtır."],"dogru":1,"aciklama":"Kumanda paneline konuk sık dokunduğu, ızgaralardaki toz da çabuk fark edildiği için ikisi de toz almada atlanmaz. Bu iki yüzey nemli bezle silinip kurulanır.","konu":"2.7.1"},{"id":"kh1-2-s199","tur":"coktan-secmeli","soru":"Sabah 10.15’te Gül yatağın iki yanındaki aplik ve komodinleri siliyor. Bu bölgeye özel dikkat etmesinin nedeni nedir?","secenekler":["Konuk geceyi yanında geçirdiği için toz ve leke ilk orada görülür.","Komodinlere konuğun değerli eşyası konduğu için.","Aplikler odadaki tek ışık kaynağı olduğu için.","Komodin çekmecelerini her zaman kilitlemek gerektiği için."],"dogru":0,"aciklama":"Yatak başı konuğun gece en çok kaldığı yerdir; aplik ve komodinde kalan toz ya da leke hemen görülür. Aplik gibi ışık veren parçalarda bez ayrıca iyice sıkılır.","konu":"2.7.1"},{"id":"kh1-2-s200","tur":"coktan-secmeli","soru":"Aşağıdaki odada bulunan küçük malzemelerden hangisi, amacıyla doğru eşleştirilmiştir?","secenekler":["Dikiş seti: konuğun ayakkabısını silmesi içindir.","Ayakkabı bezi ve çekeceği: düğmesi kopan giysiyi onarmak içindir.","Bardak kapağı: bardağın temiz ve kullanılmamış olduğunu gösterir.","Kolonyalı mendil: bardağın hijyenini korumak içindir."],"dogru":2,"aciklama":"Bardak kapağı bardağın temizlendiğini ve kullanılmadığını gösterir. Dikiş seti giysi onarımı, ayakkabı bezi ayakkabı silme, kolonyalı mendil ferahlama içindir.","konu":"2.7.2"},{"id":"kh1-2-s201","tur":"coktan-secmeli","soru":"Odadaki konuk Kaan’dan havlu istiyor. Konuğun sözünü kesmeden dinleyen Kaan’ın, dinleme ve net yanıt ilkesine en uygun cevabı hangisidir?","secenekler":["“Havlu için kat ofisini aramanız daha hızlı olur.”","“Şu an çok yoğunuz, biraz beklemeniz gerekebilir.”","“Havlu isteklerini resepsiyona iletmeniz gerekir.”","“Elbette efendim, havluyu hemen getiriyorum.”"],"dogru":3,"aciklama":"Konuğu dikkatle dinleyip kısa, açık ve kibar yanıt vermek esastır. Diğer cevaplar konuğu başka birimlere yönlendirir ya da sorunu uzatır.","konu":"2.7.3"},{"id":"kh1-2-s202","tur":"coktan-secmeli","soru":"Koridorda profesyonel duruş için aşağıdakilerden hangisi yanlıştır?","secenekler":["Koşmadan ve dik bir duruşla yürümek","Arkadaşıyla konuşurken kat arabasına yaslanmak","Konukla karşılaşınca gülümseyip selam vermek","Konuşurken bir yere dayanmadan ayakta durmak"],"dogru":1,"aciklama":"Konuşurken bir yere dayanmamak, dik ve koşmadan yürümek, konukla karşılaşınca selam vermek profesyonel duruşun parçalarıdır. Yaslanmak konuğa özensiz görüntü verir.","konu":"2.7.3"},{"id":"kh1-2-s203","tur":"coktan-secmeli","soru":"Öğleden sonra 14.00’te ön büro, 412 numaralı odanın temiz olup olmadığını kat ofisinden soruyor. Bu bilgi paylaşımı neden gereklidir?","secenekler":["Kat ofisi konuğun odaya girişini onaylar.","Ön büro odanın temizliğini kendisi kontrol eder.","Ön büro hazır odayı bilmeden konuğu yerleştiremez.","Kat hizmetleri odanın satış fiyatını belirler."],"dogru":2,"aciklama":"Ön büro hangi odanın hazır olduğunu bilmeden konuğu yerleştiremez; kat hizmetleri de hangi odanın boşaldığını ön büro bildirmeden bilemez. İki bölüm bu bilgiyi sürekli paylaşır.","konu":"2.1.1"},{"id":"kh1-2-s204","tur":"coktan-secmeli","soru":"Pas anahtarı imza föyünde aşağıdakilerden hangisi yer almaz?","secenekler":["Konuğun adı ve soyadı","Anahtarı alanın pas numarası","Sorumlu olduğu bölge ve katlar","Teslim saati ve teslim alan imzası"],"dogru":0,"aciklama":"Föy, anahtarı alıp teslim eden personelin kaydıdır: ad soyad, pas numarası, alınan saat, imza, bölge ve katlar, teslim saati ve şef kontrolü. Konuk bilgisi föye yazılmaz.","konu":"2.1.2"},{"id":"kh1-2-s205","tur":"coktan-secmeli","soru":"Murat 410 numaralı çıkış odasında kırık bir masa lambası buldu. Doğru işlem hangisidir?","secenekler":["Lambayı kendi tutanağıyla kaydeder ve konuğu telefonla arar.","Lambayı depoya götürür, kimseye bir şey söylemeden devam eder.","Teknik servisten onarım ister ama ön büroya haber vermez.","Kat şefine haber verir; tutanağı o düzenler, ön büro bilgilendirilir."],"dogru":3,"aciklama":"Konuktan kaynaklı hasar ya da eksik tespit edilince kat şefine haber verilir; tutanağı genellikle kat şefi düzenler ve ön büro bilgilendirilir. Oda görevlisi konuğa kendisi gitmez.","konu":"2.1"},{"id":"kh1-2-s206","tur":"dogru-yanlis","soru":"Hijyen riski yüksek alanlarda bez yerine tek kullanımlık havlu tercih edilebilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Bardaklar gibi yüksek riskli yerlerde kâğıt havlu silinip atıldığı için bezden daha az bulaşma riski taşır.","konu":"2.7.1"},{"id":"kh1-2-s207","tur":"dogru-yanlis","soru":"Yeni giriş yapılmış odada oda görevlisi eksik malzeme olup olmadığına özellikle bakar.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Yeni giriş yapılan odanın ilk günü konuk için önemlidir; eksik malzeme ilk gün giderilir.","konu":"2.1.1"},{"id":"kh1-2-s208","tur":"dogru-yanlis","soru":"Konuktan kaynaklı bir hasar çıkış odasında bulunduğunda tutanağı genellikle kat şefi düzenler.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Oda görevlisi hasarı kat şefine bildirir; tutanak ve konuk görüşmesi kat şefinin işidir.","konu":"2.1"},{"id":"kh1-2-s209","tur":"dogru-yanlis","soru":"Kolonyalı mendil, sıcak havada ya da yolculuk sonrası konuğa ferahlık vermek için odaya konur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Kolonya ve mendil konuğun ferahlaması ve temizlenmesi içindir.","konu":"2.7.2"},{"id":"kh1-2-s210","tur":"dogru-yanlis","soru":"Balkon kapısının camı ve çerçevesi nemli bezle silinip kurulanır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Cam ve çerçeve nemli bezle silinip kurulanır; temiz cam manzarayı netleştirir ve konuk bunu odaya ilk girişte fark eder.","konu":"2.6"},{"id":"kh1-2-s211","tur":"dogru-yanlis","soru":"Kat şefi iş planını yalnızca günlük oda sayısına göre hazırlar; personel, süre ve malzeme ihtiyacı sonradan düşünülür.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"İyi iş planı; oda sayısı ve tipleri, iş yoğunluğu, personel ihtiyacı, standart süreler, malzeme ve makine ihtiyacı ile bütçe birlikte bilinerek hazırlanır.","konu":"2.1.1"},{"id":"kh1-2-s212","tur":"dogru-yanlis","soru":"Kâğıt ve cam gibi geri dönüşebilen maddeler de çöp sayılır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Çöp, geri dönüştürülemeyen artıktır; kâğıt, cam, metal, plastik gibi maddeler ayrıldıktan sonra geride kalandır.","konu":"2.3"},{"id":"kh1-2-s213","tur":"dogru-yanlis","soru":"Balkonu temizlerken kapıya en yakın noktadan başlanır ve yüzeyler aşağıdan yukarıya silinir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Balkonda kapıdan uzak noktadan başlanır ve yüzeyler yukarıdan aşağıya silinir; böylece temizlenmiş yüzey yeniden kirlenmez.","konu":"2.6"},{"id":"kh1-2-s214","tur":"dogru-yanlis","soru":"Plaj havlusu her otelde konuklara verilen standart bir malzemedir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Plaj havlusu gibi malzemeler her otelde verilmez; işletmenin düzeyine ve konseptine göre sunulur.","konu":"2.7.2"},{"id":"kh1-2-s215","tur":"dogru-yanlis","soru":"Terlik her konuk için aynı türden olmak zorundadır; VIP konuğa özel terlik ayrılamaz.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"İşletmeler normal terliğin yanında VIP konuklara özel terlik ayırabilir; bu özel konuklara ayrıcalık tanındığını gösterir.","konu":"2.7.2"},{"id":"kh1-2-s216","tur":"coktan-secmeli","soru":"Çıkış yapılmış bir odada toz alma turunda Tülin makyaj masasına geldi. Hangi uygulama doğrudur?","secenekler":["Yalnızca masanın üstünü siler; çekmeceler konuk eşyası taşıdığı için silinmez.","Ayna, aplikler, masa ve çekmeceleri nemli bezle silip kurular.","Ayna ve apliği siler, masayı konuk kullanır diye bırakır.","Çekmeceleri siler, ayna ve apliklerin tozunu üfleyerek alır."],"dogru":1,"aciklama":"Makyaj aynasının, apliklerin, masanın ve çekmecelerin nemli bezle silinip kurulanması gerekir; ayna ve aplik konuğun en çok baktığı yerlerdendir, kalan toz hemen fark edilir.","konu":"2.7.1"},{"id":"kh1-2-s217","tur":"dogru-yanlis","soru":"Süpürme bittiğinde elektrikli süpürge, ertesi sabah toplanmak üzere odada bırakılır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"İş bitince süpürge toplanıp kat arabasına konur, odada son kontrol yapılıp kapı kapatılır; araç gereç temizlenip kat ofisindeki yerine kaldırılır.","konu":"2.7.3"},{"id":"kh1-2-s218","tur":"senaryo","durum":"Sabah 10.10. Koridorda çalışırken 318 numaralı odanın konuğu terliğiyle yanına geliyor: kapıyı çekince kapandığını, kartının içeride kaldığını söylüyor. Elinde pas anahtarın var ve kapı iki adım ötede.","soru":"Ne yaparsın?","secenekler":["Konuk mağdur olmasın diye pas anahtarınla kapıyı hemen açarsın.","Anahtarı konuğa verip kapıyı kendisinin açmasını söylersin.","Konuğu kibarca ön büroya yönlendirir, kat şefine haber verirsin.","Kapıyı sonra açacağını söyleyip kendi işine devam edersin."],"dogru":2,"aciklama":"Pas anahtarı konuğa oda açmak için kullanılmaz; yetkisiz kullanım güvenliği bozar. Konuğu ön büroya yönlendirip kat şefini bilgilendirmek hem güvenli hem yardımseverdir. Diğer şıklar ya anahtarı kötüye kullanır ya da konuğu ortada bırakır.","konu":"2.1.2"},{"id":"kh1-2-s219","tur":"senaryo","durum":"Öğleden sonra 13.40. 224 numaralı odada çıkış sonrası kontrol yaparken banyoda duş bataryasının sürekli damladığını görüyorsun. Teknik servis ancak yarın sabah bakabileceğini söylemiş. Ön büro bu odayı akşam için satışa açmayı düşünüyor.","soru":"Ne yaparsın?","secenekler":["Arıza formunu yazar, odayı satışa kapatması için ön büroya söylerim.","Odayı temizleyip hazır gösterir, konuk şikâyet ederse bildiririm.","Bataryayı kendim sıkıştırmayı denerim, düzelirse kimseye söylemem.","Sorunu vardiya sonunda kat şefine bırakırım, ön büroya söylemem."],"dogru":0,"aciklama":"Arızası giderilemeyen oda konuğa verilmemelidir; bunun için yazılı arıza formu ve ön büroya bildirim gerekir. Arızalı odayı hazır göstermek ya da bildirimi geciktirmek konuğun şikâyetine yol açar.","konu":"2.4"},{"id":"kh1-2-s220","tur":"senaryo","durum":"Sabah 09.50. 410 numaralı odada çöp sepetini boşaltırken sepetin dibinde birkaç kullanılmış kalem pil görüyorsun. Kat arabanda genel çöp poşeti ve pil kutusu var.","soru":"Ne yaparsın?","secenekler":["Nasıl olsa aynı yere gideceği için pilleri genel çöp poşetine atarsın.","Pilleri alıp konuğa geri bırakmak üzere komodinin üstüne koyarsın.","Pilleri tuvalet kâğıdına sarıp lavaboya atarsın, ortalık temiz kalsın.","Pilleri ayırıp pil kutusuna, kalan çöpü de çöp torbasına atarsın."],"dogru":3,"aciklama":"Kullanılamaz hâle gelmiş piller ayrı toplanıp pil kutusuna atılır; çünkü çevreye ve insana zarar verebilir. Genel çöpe karıştırmak ya da lavaboya atmak yanlıştır; piller konuğa da geri bırakılmaz.","konu":"2.3"},{"id":"kh1-2-s221","tur":"senaryo","durum":"Öğleden sonra 16.20. Koridorda çalışırken 506 numaralı odanın konuğu yanına gelip istediği havlunun neden hâlâ gelmediğini soruyor. Çamaşırhanedeki makinenin bozulduğunu biliyorsun.","soru":"Ne yaparsın?","secenekler":["Çamaşırhanedeki makinenin bozulduğunu açıkça anlatırsın, durumu bilsin.","Özür dileyip havlunun getirilmesi için kat şefine bildirirsin.","Konuğa havlu için ek ücret çıkabileceğini söylersin.","Konuğa böyle bir gecikme olmadığını söyleyip yanından ayrılırsın."],"dogru":1,"aciklama":"İşletmenin iç sorunları konuğa anlatılmaz; konuğa kısa, net ve kibar yanıt verilir, sorun kat şefine iletilerek çözülür. Gerçeği saklamak için yalan söylemek de yanlıştır.","konu":"2.7.3"}],"siralamalar":[{"id":"kh1-2-r01","konu":"2.1.1","baslik":"Sabah raporu: işe hazırlıktan teslime","yonerge":"Oda görevlisi olarak güne başlayıp sabah raporunu teslim edene kadar adımları sıraya koy.","adimlar":["Takılarını çıkar, üniformanı giy ve isimliğini tak.","Kat hizmetleri müdürünün sabah toplantısına katıl.","Kat şefinden günlük iş programını öğren.","Sorumlu olduğun odaların oda durum raporunu kat şefinden, bölüm pas anahtarını imza karşılığı teslim al.","Odalara git; odadaki izlere bakarak kişi sayısını raporla karşılaştır.","Özel durumları açıklama bölümüne yaz ve raporunu imzalamadan önce kontrol et.","Tarihi yazıp imzanı at, raporu zamanında kat şefine teslim et."],"aciklama":"Önce kişi hazırlanır, sonra iş talimatı, rapor ve anahtar alınır; rapor ancak odalar görüldükten sonra yazılır ve teslimden önce kontrol edilir."},{"id":"kh1-2-r02","konu":"2.1.2","baslik":"Pas anahtarını almak, kullanmak, teslim etmek","yonerge":"Pas anahtarı işleminin adımlarını doğru sıraya koy.","adimlar":["Sorumlu olduğun bölüme ait bölüm pas anahtarını kat şefinden iste.","Defterde anahtarın ait olduğu yeri, tarihi ve saati yazıp imzalayarak anahtarı teslim al.","Aldığın anahtarın sorumlu olduğun bölüme ait doğru anahtar olduğunu kontrol et.","Çalışırken anahtarı yalnız kendi işin için kullan, kimseye verme ve başkasının anahtarına dokunma.","İş bitiminde teslim tarihini ve saatini deftere yazıp anahtarı şefe ya da yetkili personele imza karşılığı teslim et."],"aciklama":"Anahtar önce istenir, kayıtla teslim alınır ve doğru olup olmadığı kontrol edilir; kullanılırken korunur ve en son yine kayıtla geri verilir; böylece kaybolursa kimin elinde olduğu bellidir."},{"id":"kh1-2-r03","konu":"2.1","baslik":"Boş odaya giriş","yonerge":"Boş görünen odaya girerken adımları sıraya koy.","adimlar":["Kat arabanı hazırla.","Oda durum raporuna göre temizlenecek odaya git ve arabayı odaya en yakın yere, geçişi engellemeden yerleştir.","3x3 metoduyla kapıyı çal ve “Housekeeping” diye seslen.","Odadan ses gelmezse kapıyı pas anahtarıyla aç.","Kapıya Oda Görevlisi kartını as ve çalıştığın sürece kapıyı açık tut.","Oda durum raporunu doldur."],"aciklama":"Önce hazırlık ve yerleşim yapılır, sonra kapıda sırayla çalma, açma ve kart asma gelir; rapor işin en sonunda doldurulur."},{"id":"kh1-2-r04","konu":"2.1","baslik":"Konuk odadayken giriş","yonerge":"Konuğun içeride olabileceği odaya girerken adımları sıraya koy.","adimlar":["Kat arabanı hazırla.","Oda durum raporuna göre dolu olan odaya git ve arabayı odaya yakın, geçişi engellemeyen bir yere yerleştir.","Kapıda DND kartı olup olmadığına bak.","Kart yoksa 3x3 metoduyla kapıyı çal ve “Housekeeping” de.","Kapı açılınca konuğu kibarca selamla.","Konuğa temizlik isteyip istemediğini sor.","İstiyorsa kapıya Oda Görevlisi kartını as.","Konuğun rahatını bozmadan sessizce temizle."],"aciklama":"Önce DND kontrol edilir, sonra çalınır, selamlanır ve konuğun isteği sorulur; temizlik yalnız konuk isterse başlar."},{"id":"kh1-2-r05","konu":"2.1","baslik":"Çıkış yapılmış odaya giriş","yonerge":"Çıkış yapmış konuğun odasında adımları sıraya koy.","adimlar":["Çıkış yapılacak odaları raporda öğren.","Konukların çıkış saatini öğren.","Konuk odayı boşalttıktan sonra, otelden ayrılmadan odaya gir.","Odanın genel kontrolünü yap: unutulmuş eşya varsa vakit geçirmeden ön büroya ulaştır; konuktan kaynaklı hasar ya da eksik varsa kat şefine ve ön büroya bildir.","Odayı temizleyip yeni konuk için hazır hâle getir.","Odayı raporda V/C olarak göster."],"aciklama":"Önce çıkış bilgisi öğrenilir ve genel kontrol yapılır; konuk ayrılmadan ulaşılması gereken şeyler hızlı iletilir. Temizlik ve rapor en sona kalır."},{"id":"kh1-2-r06","konu":"2.1","baslik":"Temizlik sırasında konuk gelirse","yonerge":"Temizlik sürerken konuk odaya gelirse adımları sıraya koy.","adimlar":["Çalışmaya başlarken kapıya Oda Görevlisi kartını as ve çalıştığın sürece kapıyı açık tut.","Konuk gelince temizlikte sakınca olup olmadığını sor.","Konuk temizlik istemezse araç gerecini toplayıp odadan çık.","Odanın başka bir saatte temizleneceğini oda durum raporuna not et.","Gün sonunda raporu şefe teslim et."],"aciklama":"Kart ve açık kapı baştan vardır; konuğun isteği sorulur, istemiyorsa çıkılır ve durum kayda geçirilir."},{"id":"kh1-2-r07","konu":"2.1","baslik":"Oda değişimi","yonerge":"Konuğun oda değiştirmesine yardım ederken adımları sıraya koy.","adimlar":["Kat arabanı hazırla.","Oda durum raporuna göre oda değişimi yapılacak odaya git ve arabayı odaya yakın bir yere yerleştir.","3x3 metoduyla kapıyı çal ve “Housekeeping” de.","Konuk kapıyı açınca oda değişimi için yardıma geldiğini söyle.","Konuk isterse eşyalarını toplamasına dikkatli ve özenli biçimde yardım et.","Eşyaların yeni odaya taşınmasında bellboy ile birlikte yardımcı ol.","Konuk isterse yeni odasına yerleşmesine yardım et ve iyi günler dile.","Konuğun ayrıldığı odayı temizleyip satışa hazır hâle getir."],"aciklama":"Önce konuğa yardım teklif edilir, eşya taşınır ve konuk yerleştirilir; eski oda ancak konuk ayrıldıktan sonra hazırlanır."},{"id":"kh1-2-r08","konu":"2.1.3","baslik":"DND kartı olan odalarda işlem","yonerge":"DND kartı asılı odalarda gün boyunca izlenecek adımları sıraya koy.","adimlar":["Katındaki odaların kapı kollarını kontrol et.","DND asılı odaya girme; kapının altından bilgilendirme kartını içeri at.","Konuk sonradan ön büroyu arayıp temizlik isterse odayı temizle; vardiya bitene kadar odaları ara ara kontrol et.","Kart hâlâ asılıysa gün sonunda raporunda belirt.","Ertesi gün DND hâlâ asılıysa kat şefine bildir; ön büro konuğu arayıp sağlık durumunu ve bir ihtiyacı olup olmadığını sorar.","Konuğa ulaşılamazsa kat hizmetleri ve güvenlikten yetkili iki kişiyle gidip kapıyı çal.","Yanıt yoksa yetkililerle odaya girip konuğu kontrol et."],"aciklama":"Önce konuğun isteğine saygı gösterilir ve kayıt tutulur; endişe ancak bir gün sonra, yetkililerle birlikte ve aşama aşama büyütülür."},{"id":"kh1-2-r09","konu":"2.2","baslik":"Odayı havalandırma","yonerge":"Odayı havalandırırken adımları sıraya koy.","adimlar":["Kat arabanı hazırlayıp odaya yakın bir yere yerleştir.","3x3 metoduyla kapıyı çal; ses gelmezse pas anahtarıyla aç.","Kapıya Oda Görevlisi kartını as ve kapıyı açık tut.","Odanın perdelerini, balkon kapısını ve pencereleri aç.","Kapı ve pencereyi karşılıklı açık tutarak odayı havalandır.","Temizlik bitince pencere ve balkon kapısını kapat, perdeleri düzgünce ayarla.","Oda durum raporunu doldurup şefe teslim et."],"aciklama":"Havalandırma odaya girdikten sonra başlar ve iş bitince kapatma ile tamamlanır; rapor en sonda gelir."},{"id":"kh1-2-r10","konu":"2.3","baslik":"Odadan çöp toplama","yonerge":"Odadaki çöpleri toplarken adımları sıraya koy.","adimlar":["Kat arabanı hazırlayıp odaya yakın bir yere yerleştir.","3x3 metoduyla kapıyı çal; ses gelmezse pas anahtarıyla aç ve Oda Görevlisi kartını as.","Çöpleri toplamadan önce eldiven ve koruyucu maskeni tak.","Kat arabasındaki atık bölmesini kullan; yoksa çöpün özelliğine göre farklı poşetler hazırla.","Masa ve sehpa üzerindeki çöpleri özelliğine göre uygun torbalara koy.","Çöp sepetindeki torbanın ağzını bağlayıp arabadaki torbaya koy.","Kovaya yeni poşet tak.","Oda durum raporunu doldurup şefe teslim et."],"aciklama":"Koruyucu donanım çöpe dokunmadan önce takılır; önce masadaki çöpler özelliğine göre ayrılarak toplanır, sonra sepetteki torba bağlanıp arabaya konur, en son kovaya yeni poşet takılır; rapor sona kalır."},{"id":"kh1-2-r11","konu":"2.4","baslik":"Arıza formunu elle doldurma","yonerge":"Oda görevlisi olarak arızanın bildirilmesinden dosyalanmasına kadar adımları sıraya koy.","adimlar":["Odada tespit ettiğin arıza için arıza formunu doldur.","Formun bir nüshasını teknik servise gönder, bir nüshasını kat şefine ver; bir nüshası sende kalır.","Arızanın giderilip giderilmediğini takip et.","Giderilmişse odaya gidip kontrol et ve odayı düzenle.","Teknik servisin doldurup geri verdiği formu kendi nüshanla birlikte ofisteki dosyaya koy."],"aciklama":"Önce yazılı bildirim yapılır, sonra takip edilir; iş ancak arıza çözüldüğü görüldüğünde ve form dosyalandığında kapanır."},{"id":"kh1-2-r12","konu":"2.4","baslik":"Otomasyonla arıza bildirimi","yonerge":"Otomasyon kullanılan bir otelde arıza bildiriminin akışını sıraya koy.","adimlar":["Oda temizleme görevlisi sipariş alıcıya arızayı bildirir.","Sipariş alıcı arıza bilgilerini sisteme girer.","Teknik servis bildirimi görüp arızayı giderir ve sisteme not girer.","Sipariş alıcı arızanın giderildiği notunu görüp kat şefine haber verir.","Kat şefi ilgili oda temizleme görevlisini bilgilendirir.","Oda temizleme görevlisi odayı kontrol edip temizliği yapar."],"aciklama":"Bilgi önce sisteme girilir, sonra teknik servis giderir ve haber zincir hâlinde geri döner; oda görevlisi arızanın giderildiği haberini aldıktan sonra odayı kontrol edip temizler."},{"id":"kh1-2-r13","konu":"2.4","baslik":"Konuk kaynaklı hasar","yonerge":"Çıkış yapılmış odada hasarlı bir eşya bulundu. Süreci sıraya koy.","adimlar":["Odada konuğun yanlış kullanımından bozulan eşyayı fark et.","Kat şefine haber ver.","Kat şefi hasarlı malzeme tutanağını düzenler ve ön büroyu arayarak bilgi verir.","Kat şefi konukla yüz yüze görüşerek durumu açıklar.","Hasar bedeli işletme prosedürüne göre konuktan alınır ve tutanağın nüshaları ilgili bölümlere imza karşılığı teslim edilir."],"aciklama":"Oda görevlisi yalnız fark edip bildirir; tutanak, ön büro ve konuk görüşmesi kat şefi üzerinden yürür; bedel ve nüshaların teslimi en sonda gelir."},{"id":"kh1-2-r14","konu":"2.5","baslik":"Mini buzdolabını hazır hâle getirme","yonerge":"Mini buzdolabının ürünlerini depodan alıp yerleştirmeye kadar adımları sıraya koy.","adimlar":["Mini buzdolabında eksilen ürünleri belirle.","Ambar talep fişini doldurup kat şefine imzalat.","Ürünleri ambar görevlisinden imza karşılığı teslim al.","Ürünleri isimleri öne gelecek şekilde buzdolabına yerleştir.","Mini buzdolabı çekinin iki nüshasını hazırlayıp bir nüshayı konuk odasına bırak, diğerini hesap işlemleri için yanına al."],"aciklama":"Ürün önce kayıtlı biçimde depodan alınır, yerleştirilir; çek de ürünler yerindeyken hazırlanıp iki nüsha olarak dağıtılır."},{"id":"kh1-2-r15","konu":"2.5","baslik":"Mini buzdolabı çekinin yolculuğu","yonerge":"Konuk kaldığı süre boyunca mini buzdolabı çekinin akışını sıraya koy.","adimlar":["Çekin iki nüshasını hazırlayıp bir nüshayı konuk odasına bırak, diğerini hesap işlemleri için yanına al.","Konuk kaldığı günlerde buzdolabını her gün kontrol et.","Konuk ayrılmadan bir gün önce çekleri ön büroya ilet.","Çıkış yapınca dolabı yeniden kontrol edip kullanım varsa çeki doldurarak ön büroya ilet."],"aciklama":"Çek önce hazırlanır ve dağıtılır, konaklama boyunca günlük kontrolle güncellenir ve çıkışa yakın ön büroya verilir; çıkıştaki son kontrol en sondadır."},{"id":"kh1-2-r16","konu":"2.6","baslik":"Balkon temizliği","yonerge":"Balkon temizliğini sıraya koy.","adimlar":["Süpürge, faraş, bez, kova, cam çekeceği ve çöp poşetini hazırla; eldivenini ve maskeni tak.","Balkondaki konuk eşyalarını (askıdaki çamaşıra dokunmadan) dikkatle kaldır; iş bitince aynı yerine koy.","Çöpleri ve izmaritleri poşete boşaltıp ağzını kapat.","Kapıdan uzak yerden, yukarıdan aşağıya doğru yüzeyleri temizle.","Zemini yıka, gideri tıkanmasın diye kontrol et.","Son kontrolü yapıp balkon kapısını kapat."],"aciklama":"Hazırlık ve koruyucu donanım başta gelir; konuk eşyaları kaldırılır, çöp toplanıp yüzeyler yukarıdan aşağıya temizlenir ve iş son kontrolle biter."},{"id":"kh1-2-r17","konu":"2.7.1","baslik":"Toz alma","yonerge":"Konuk odasında toz almanın adımlarını sıraya koy.","adimlar":["Toz almadan önce eldiven ve maskeni tak.","Toz bezlerini, kovayı ve yüzeye uygun kimyasalı seçip hazırla.","Odanın giriş kapısının yanından başlayıp saat yönünde ilerleyerek yüzeyleri sil.","Odanın giriş kapısının kendisini nemli bezle sil."],"aciklama":"Koruyucu donanım ve hazırlık başta gelir; silme giriş kapısının yanından saat yönünde ilerler ve giriş kapısının kendisi en sonda silinir."},{"id":"kh1-2-r19","konu":"2.7.2","baslik":"Buklet malzemelerini yerleştirme","yonerge":"Buklet malzemelerini odaya yerleştirirken adımları sıraya koy.","adimlar":["Kat arabanı hazırlayıp odaya yakın bir yere, geçişi engellemeden yerleştir.","3x3 metoduyla kapıyı çal; ses gelmezse pas anahtarıyla aç, Oda Görevlisi kartını as ve kapıyı açık tut.","Odadaki kişi sayısı kadar buklet malzemesini kat arabasından al.","Kırtasiye malzemelerini, otel bilgi kartlarını ve çamaşırhane listesini belirlenen yerlerine yerleştir.","Eşantiyonları kullanım yerlerine koy; VIP ya da özel durumlu konuk varsa işletme prosedürüne göre ekstra malzeme ekle.","Oda durum raporunu doldurup şefe teslim et."],"aciklama":"Önce araba yerleştirilir ve odaya girilir; malzeme kişi sayısına göre alınıp yerlerine konur, gerekirse ekstra malzeme eklenir; rapor işin en sonunda doldurulur."},{"id":"kh1-2-r18","konu":"2.7.3","baslik":"Odayı süpürme","yonerge":"Elektrikli süpürge ile odayı süpürmeyi sıraya koy.","adimlar":["Elektrikli süpürgeni alıp odaya getir.","Süpürmeden önce kabloyu odanın en uzak noktasına yetişecek kadar uzat, zemine göre halı ya da sert zemin aparatını tak; zeminde çivi, toka gibi parçaları ve sandalye, puf gibi taşınabilir eşyaları kaldır.","Giriş kapısına en uzak yerden, halıda dokunun tersi yönünde süpür.","Bitirince süpürgeni toplayıp kat arabasına yerleştir.","Son kontrolleri yapıp oda kapısını kapat."],"aciklama":"Süpürmeden önce hazırlıklar (kablo, aparat, zemin) birlikte yapılır; süpürme uzak noktadan kapıya doğru ilerler, süpürge toplanır ve oda kapatılır."}],"acikSorular":[{"id":"kh1-2-y01","konu":"2.1.3","soru":"Sabah 10.00’da bir oda görevlisi 406 numaralı odanın kapı kolunda DND kartı görüyor. Görevlinin bu odada ne yapması gerektiğini yazınız; odaya girilemediğini nasıl kayda geçireceğini, konuğa nasıl bildireceğini ve bunu neden yaptığını açıklayınız.","olcut":[{"metin":"DND kartının konuğun odasına girilmesini istemediğini gösterdiğini belirtir.","puan":20},{"metin":"Odaya girmeyip odayı atladığını, konuğu rahatsız etmediğini yazar.","puan":20},{"metin":"Girilemeyen odayı, DND olduğunu ve girilemediğini tarih ve saat belirterek otel otomasyon sistemine yazdığını ve akşam kat hizmetleri raporunda da belirttiğini açıklar.","puan":25},{"metin":"Konuğa girilemediğini bildiren kartı kapının altından atar ya da kapı koluna asar.","puan":15},{"metin":"Kartın nedenini açıklar (konuk odasının neden temizlenmediğini öğrenir, isterse temizlik için ön büroyu arar; kayıt şikâyeti önler).","puan":20}],"ornek":"DND kartı, konuğun odasına girilmesini istemediğini bildirir. Görevli odaya girmez ve odayı atlar. Odaya giremediğini tarih ve saatiyle otel otomasyon sistemine yazar ve akşam kat hizmetleri raporunda belirtir. Ayrıca kapının altından ya da koluna “DND kartı olduğu için odanıza girilemedi” yazan bir kart bırakır. Böylece konuk odasının neden temizlenmediğini öğrenir, isterse temizlik ya da havlu için ön büroyu arayabilir; kayıt da şikâyet çıkmasını önler.","ipucu":"Konuğun isteğine saygı ile konuğun bilgilendirilmesi arasındaki dengeyi düşünün."},{"id":"kh1-2-y02","konu":"2.4","soru":"Bir oda görevlisi, çıkış yapılmış bir odada temizliğe başlamadan önce okuma lambasının yanmadığını fark ediyor. Görevlinin bu arızayı hangi belgeyle kime bildireceğini yazınız ve arızanın hemen giderilemediği durumda odaya ne yapılacağını nedeniyle açıklayınız.","olcut":[{"metin":"Arızayı yazılı olarak arıza bildirim formuna yazdığını belirtir.","puan":20},{"metin":"Formun teknik servise ve kat şefine ulaştırıldığını yazar.","puan":20},{"metin":"Arıza giderilemezse odanın ön büroya bildirilerek satışa kapatılacağını belirtir.","puan":25},{"metin":"Arızalı odanın konuğa verilmemesinin nedenini açıklar (konuğun odada rahat ve konforlu kalması gerekir; arızalı oda konuğun memnuniyetsizliğine yol açar).","puan":35}],"ornek":"Görevli arızayı arıza bildirim formuna yazar. Formun bir nüshası teknik servise, bir nüshası kat şefine gider; bir nüsha da görevlide kalır. Arıza giderilemezse oda ön büroya bildirilir ve satışa kapatılır. Çünkü arızalı odayı alan konuk giriş anında hayal kırıklığına uğrar; arızalı oda hiçbir koşulda konuk kullanımına sunulmaz.","ipucu":"Arızalı bir odaya giren konuğun yaşayacağı sorunu düşünün."}]},{"ders":"kat-hizmetleri-10","sinif":10,"unite":3,"baslik":"Yatak Hazırlama İşlemleri","onay":true,"kazanimlar":["İşletme prosedürüne uygun olarak yatak yapımı için ön hazırlık yapar.","Uluslararası standartlara ve işletme prosedürlerine uygun olarak yatak yapar.","Konuk odasındaki havluları, ulusal standartlara uygun olarak katlama işlemini (origami) yapar."],"soz":"Konuğun gece rahat uyuması, sabah özenle gerilmiş bir çarşafla başlar.","dersler":[{"baslik":"Konuk Odaya Girince Önce Neye Bakar?","ilk":"kh1-3-001"},{"baslik":"Yatağın İskeleti","ilk":"kh1-3-004"},{"baslik":"Çarşafın İki Yüzü","ilk":"kh1-3-009"},{"baslik":"Yorgan mı, Battaniye mi, Pike mi?","ilk":"kh1-3-013"},{"baslik":"Yastığın Giysisi ve Yatağın Süsü","ilk":"kh1-3-018"},{"baslik":"Kat Arabası Yatağa Hazır mı?","ilk":"kh1-3-022"},{"baslik":"Yatak Yapmanın Değişmez Sırası","ilk":"kh1-3-024"},{"baslik":"Yataktan Ne Çıkar?","ilk":"kh1-3-028"},{"baslik":"Leke mi, Eşya mı?","ilk":"kh1-3-031"},{"baslik":"Yatağın Görünmez Kalkanı","ilk":"kh1-3-034"},{"baslik":"Çarşaf Yatağa Nasıl Oturur?","ilk":"kh1-3-039"},{"baslik":"Zarf Köşenin Sırrı","ilk":"kh1-3-042"},{"baslik":"Üst Çarşaf Nereye Yatar?","ilk":"kh1-3-045"},{"baslik":"Battaniyenin Doğru Yeri","ilk":"kh1-3-048"},{"baslik":"Yastığa Kılıf Giydirmek","ilk":"kh1-3-053"},{"baslik":"Köşeler Tam Oturdu mu?","ilk":"kh1-3-056"},{"baslik":"Yorgan Nevresime Nasıl Girer?","ilk":"kh1-3-059"},{"baslik":"Yatağa Son Dokunuş","ilk":"kh1-3-063"},{"baslik":"Pikeyi Pürüzsüz Sermek","ilk":"kh1-3-067"},{"baslik":"Odaya Bir Yatak Daha","ilk":"kh1-3-071"},{"baslik":"Bebek İçin Güvenli Bir Yuva","ilk":"kh1-3-073"},{"baslik":"Katlanır Yatak Nereye Kurulur?","ilk":"kh1-3-078"},{"baslik":"Koltuk Geceye Dönüşürken","ilk":"kh1-3-081"},{"baslik":"Akşam Servisinin İncelikleri","ilk":"kh1-3-083"},{"baslik":"Yatak Nasıl Açılır?","ilk":"kh1-3-085"},{"baslik":"Gece İçin Son Dokunuşlar","ilk":"kh1-3-088"},{"baslik":"Peşkirden Havluya","ilk":"kh1-3-151"},{"baslik":"Bursa’dan Buckingham’a","ilk":"kh1-3-156"},{"baslik":"Hangi Havlu Nerede?","ilk":"kh1-3-160"},{"baslik":"Kaymayan Banyo","ilk":"kh1-3-164"},{"baslik":"Bornoz Ayrıcalığı","ilk":"kh1-3-167"},{"baslik":"Sahilde Havlu Kartı","ilk":"kh1-3-170"},{"baslik":"Lifin Sırrı","ilk":"kh1-3-174"},{"baslik":"Kâğıt Değil, Havlu","ilk":"kh1-3-178"},{"baslik":"Üç Katlama Tekniği","ilk":"kh1-3-183"},{"baslik":"Göz, Çiçek, Kurdele","ilk":"kh1-3-186"},{"baslik":"Kuğudan Hediye Paketine","ilk":"kh1-3-191"},{"baslik":"Havludan Hayvan Figürleri","ilk":"kh1-3-195"},{"baslik":"Figürün Başı ve Sonu","ilk":"kh1-3-199"},{"baslik":"On Dakikada Kaç Puan?","ilk":"kh1-3-203"}],"kavramlar":[{"id":"kh1-3-001","konu":"3.1","terim":"Yatağın konuk gözündeki yeri","ingilizce":"First impression of the bed","tanim":"Odaya giren konuğun ilk olarak yatağa bakması ve yatağın düzgünlüğüne göre otel hakkında fikir edinmesidir.","ornek":"Akşam 18.30’da Antalya’daki bir otele varan Demir ailesi odaya girer girmez yatağa bakar; çarşaflar gergin, yastıklar aynı hizada olunca anne “Burası bakımlı” der.","sektor":"Konuk temiz ve düzenli bir yatak görünce otelin geri kalanına da güvenir; yatak yapımında kullanılan malzemelerin göze hoş, hijyenik ve yeni olması da beklenir. Bu yüzden kat hizmetleri yatak yapımını özen isteyen bir iş sayar.","iliskili":["kh1-3-002","kh1-3-003"],"kontrol":null,"gorsel":"g1-otel-yatak-odasi"},{"id":"kh1-3-002","konu":"3.1","terim":"Mefruşat","ingilizce":"Soft furnishings","tanim":"Odada kullanılan yatak takımı ve perde gibi tekstil donanımının bütünüdür; dekorasyona uygun, dayanıklı, oda ve yatak tipine göre yapılmış olmalıdır.","ornek":"Sezon öncesi kat şefi Hülya, yeni yatak örtülerinin hem oda renklerine uyduğunu hem de sık yıkamaya dayandığını görünce siparişi onaylar.","sektor":"Mefruşat işletme için ciddi bir gider kalemidir; bu yüzden işletmeler dayanıklı ve ekonomik olanı seçer. Görevlinin özenli kullanımı malzemenin ömrünü uzatır.","iliskili":["kh1-3-001","kh1-3-003"],"kontrol":null},{"id":"kh1-3-003","konu":"3.1","terim":"Yatak takımı","ingilizce":"Bed linen set","tanim":"Bir yatağı hazırlamak için gereken alt ve üst çarşaf, nevresim, yastık kılıfı gibi tekstil parçalarının bütünüdür.","ornek":"Sabah 10.00’da 214 numaralı odaya geçen görevli Elif, bir takımın bütün parçalarını arabadan eksiksiz alır; bu sayede eksik parça için koridoru ikinci kez yürümez.","sektor":"Takımı bir arada hazırlamak zaman kazandırır ve yatağın bir parçasının eksik kalmasını önler.","iliskili":["kh1-3-002","kh1-3-001"],"kontrol":null,"gorsel":"t15ac-yatak-takimi"},{"id":"kh1-3-004","konu":"3.1.1","terim":"Yatak","ingilizce":"Mattress","tanim":"Uyumak ve dinlenmek için üzerine yatılan, pamuk, yün ya da elyaf gibi maddelerden yapılan döşektir.","ornek":"Sabah turunda kat şefi Hülya, 120 numaralı odanın yatağının çökmediğini ve koruyucusunun yerinde olduğunu gözle kontrol eder.","sektor":"Konuğun uyku kalitesi yatağa bağlıdır. Konuk odalarında yataklar yıkanamadığı için temiz kalmaları koruyucuya ve görevlinin özenine bağlıdır.","iliskili":["kh1-3-005","kh1-3-007"],"kontrol":null,"gorsel":"t11c-yatak"},{"id":"kh1-3-005","konu":"3.1.1","terim":"Yaylı yatak","ingilizce":"Spring mattress","tanim":"Kullanım kolaylığı ve dayanıklılığı nedeniyle konaklama işletmelerinde en çok tercih edilen, ortopedik yapılı yatak çeşididir.","ornek":"Marmaris’te yeni açılan bir otelin satın alma sorumlusu Kemal, her gün çok sayıda konuk ağırlanacağı için ortopedik yaylı yatak seçer.","sektor":"Yaylı yatak sık kullanımda şeklini korur; bu da şikâyeti ve yenileme giderini azaltır. Tek ve çift kişilik çeşitleri vardır.","iliskili":["kh1-3-004","kh1-3-007"],"kontrol":null,"gorsel":"t10c-yayli-yatak"},{"id":"kh1-3-006","konu":"3.1.1","terim":"Karyola","ingilizce":"Bedstead","tanim":"Üzerine yatak konulup yatılan, ahşap, metal ya da pirinç gibi malzemelerden yapılan ev eşyasıdır.","ornek":"Safranbolu’daki konak tarzı bir otelde odaların havasına uygun ahşap karyola kullanılır; görevli Murat çarşafı karyolanın kenarlarına özenle sıkıştırır.","sektor":"Bazı işletmeler mekânın havasına uygun ahşap ya da metal karyola kullanır; ancak temizlik ve kullanım kolaylığı bakımından çoğu otel baza tercih eder.","iliskili":["kh1-3-007","kh1-3-004"],"kontrol":null,"gorsel":"t13c-demir-karyola"},{"id":"kh1-3-007","konu":"3.1.1","terim":"Baza","ingilizce":"Bed base","tanim":"Ahşap ya da metal bir kasanın kumaş veya suni deriyle kaplanmasıyla yapılan, üzerine yatak konulan altlıktır.","ornek":"Kapadokya’daki otelin odalarının hepsinde baza vardır; görevli Murat bazanın kumaşındaki küçük lekeyi nemli bezle siler.","sektor":"Bazanın temizliği ve kullanımı kolay olduğundan konaklama işletmelerinde çoğunlukla baza tercih edilir.","iliskili":["kh1-3-006","kh1-3-008"],"kontrol":null,"gorsel":"t10c-baza"},{"id":"kh1-3-008","konu":"3.1.1","terim":"Sandıklı baza","ingilizce":"Storage bed base","tanim":"Yatağın altında eşya koymaya yarayan bir sandık bölümü bulunan bazadır.","ornek":"Küçük odaları olan bir pansiyonda konuk “Valizimi nereye koyabilirim?” diye sorunca görevli Ayşe, sandıklı bazanın altındaki sandığı gösterir.","sektor":"Sandık bölümü odada ek bir saklama alanı sağlar; küçük odalarda yer kazandırır.","iliskili":["kh1-3-007","kh1-3-006"],"kontrol":null,"gorsel":"t11c-sandikli-baza"},{"id":"kh1-3-009","konu":"3.1.2","terim":"Alt çarşaf","ingilizce":"Bottom sheet","tanim":"Yatak koruyucunun üzerine serilen, pamuk, keten, sentetik ya da bunların karışımından dokunmuş çarşaftır.","ornek":"Sabah 09.15’te 308 numaralı odada görevli Elif, alt çarşafı yatak koruyucunun üzerine kırışıksız ve gergin serer; üstüne gelecek katmanlar böylece düzgün oturur.","sektor":"Alt çarşaf yatağın temelidir; gergin ve temiz serilmesi üstüne gelen battaniye, yastık ve örtünün düzgün durmasını sağlar. Kırışık kalan çarşaf konuğun yatarken rahatsız olmasına yol açar.","iliskili":["kh1-3-010","kh1-3-012"],"kontrol":null,"gorsel":"t11c-alt-carsaf"},{"id":"kh1-3-010","konu":"3.1.2","terim":"Üst çarşaf","ingilizce":"Top sheet","tanim":"Battaniyenin altına serilen, yastık tarafındaki payı daha geniş dikilmiş çarşaftır.","ornek":"Akşam vardiyasında görevli Cem, 214 numaralı odada üst çarşafın geniş payını yastık tarafına getirerek serer; bu pay sonra battaniyenin üzerine katlanacaktır.","sektor":"Konuk battaniye ya da yorganla doğrudan temas etmez; üst çarşaf yıkanabildiği için hijyeni kolaylaştırır.","iliskili":["kh1-3-009","kh1-3-011"],"kontrol":null},{"id":"kh1-3-011","konu":"3.1.2","terim":"Kapak çarşafı","ingilizce":"Top cover (cover sheet)","tanim":"Bazı işletmelerde dekorasyon için battaniyenin üzerine serilen çarşaftır.","ornek":"Bodrum’daki butik bir otelde görevli Selin, kapak çarşafını battaniyenin üzerine, odanın beyaz düzenine uyacak şekilde serer.","sektor":"Her işletmede kullanılmaz; kullanılan yerde yatağın daha şık ve düzenli görünmesini sağlar.","iliskili":["kh1-3-010","kh1-3-013"],"kontrol":null},{"id":"kh1-3-012","konu":"3.1.2","terim":"Yatak koruyucu (alez)","ingilizce":"Mattress protector","tanim":"Yatağın kirlenmesini önlemek için pamuklu dokumadan yapılan, sıvı geçirmeyen ve alt çarşaftan önce yatağa serilen koruyucudur.","ornek":"Akşam bir çocuk yatağa su döker; ertesi sabah görevli Murat ıslanmanın alezde kaldığını, yatağa geçmediğini görür.","sektor":"Konuk odalarındaki yataklar yıkanamaz. Leke ya da ıslaklık koruyucuda kalır; yatak temiz ve uzun ömürlü olur.","iliskili":["kh1-3-009","kh1-3-004"],"kontrol":null,"gorsel":"t10c-yatak-koruyucu"},{"id":"kh1-3-013","konu":"3.1.2","terim":"Battaniye","ingilizce":"Blanket","tanim":"Yorgan yerine ya da yorganın üzerine örtmek için kullanılan, yün veya sentetik maddelerden yapılan dokuma örtüdür.","ornek":"Sonbahar akşamı Uludağ’daki otelde görevli Ayşe, serin havaya karşı odaların üst çarşafının üzerine battaniye serer.","sektor":"Tek kişilik, çift kişilik ve bebek battaniyesi çeşitleri vardır; yatağın ve odanın tipine göre seçilir.","iliskili":["kh1-3-014","kh1-3-015"],"kontrol":null,"gorsel":"t10c-battaniye"},{"id":"kh1-3-014","konu":"3.1.2","terim":"Yorgan","ingilizce":"Duvet","tanim":"Kış döneminde konuğun üşümesini önlemek için kullanılan, pamuk, yün veya elyaftan yapılmış yatak malzemesidir.","ornek":"Ocak ayında Erzurum’daki otelde görevli Murat, karlı bir akşam odalara elyaf yorgan hazırlar; sabah konuk geceyi üşümeden geçirdiğini söyler.","sektor":"Konaklama işletmelerinde temizlik ve kullanım kolaylığı nedeniyle elyaftan yapılmış yorganlar tercih edilir.","iliskili":["kh1-3-016","kh1-3-013"],"kontrol":null,"gorsel":"t15ac-yorgan"},{"id":"kh1-3-015","konu":"3.1.2","terim":"Pike","ingilizce":"Coverlet","tanim":"Yaz aylarında konukların yorgan yerine üzerine örttüğü, pamuklu bir yatak malzemesidir.","ornek":"Temmuz ayında Alanya’daki tatil otelinde görevli Elif, sıcak geceler için odalara yorgan yerine beyaz pike serer; konuk geceyi bunalmadan geçirir.","sektor":"Pikenin renk ve desen çeşitleri vardır; konaklama işletmelerinde daha çok beyaz pike tercih edilir. Tek ve çift kişilik çeşitleri bulunur.","iliskili":["kh1-3-013","kh1-3-014"],"kontrol":null,"gorsel":"t10c-pike"},{"id":"kh1-3-016","konu":"3.1.2","terim":"Nevresim","ingilizce":"Duvet cover","tanim":"Dekorasyonla uyumlu, pamuklu kumaştan dikilen, alt ucu açık dikdörtgen bir yorgan kılıfıdır.","ornek":"Sabah 11.00’de kat arabasını hazırlayan görevli Selin, çift kişilik odalar için çift kişilik nevresimleri ayırır.","sektor":"Nevresim yorganı kirlenmekten korur ve kolayca yıkanabilir. Tek ve çift kişilik çeşitlerinin yanında bebek yatakları için küçük ölçüleri de vardır.","iliskili":["kh1-3-014","kh1-3-015"],"kontrol":null,"gorsel":"t15ac-nevresim"},{"id":"kh1-3-017","konu":"3.1.2","terim":"Mevsime göre üst örtü seçimi","ingilizce":"Seasonal bedding choice","tanim":"Konuğun rahat uyuması için kışın yorgan, serin havalarda battaniye, sıcak havalarda pike hazırlanmasıdır.","ornek":"Ocak ayında Uludağ’daki otelde görevli Ayşe yorgan hazırlarken, Temmuz ayında Bodrum’daki otelde görevli Cem pike serer.","sektor":"İklimi sıcak olan tatil otellerinde pike çoğunlukla battaniye yerine kullanılır; yorgan ve battaniyeye göre hafif olduğundan sıcak iklimde konuk için daha uygundur. Doğru örtü konuğun konforunu ve şikâyet oranını etkiler.","iliskili":["kh1-3-014","kh1-3-015","kh1-3-013"],"kontrol":null,"gorsel":"t12r-ortu-yigini"},{"id":"kh1-3-018","konu":"3.1.2","terim":"Yastık kılıfı","ingilizce":"Pillowcase","tanim":"Konuğun yastıkla doğrudan temas etmemesi için yastığı tamamen saran, pamuklu kumaştan yapılmış kılıftır.","ornek":"Akşam 17.30’da görevli Selin, 405 numaralı odada çift kişilik yatak için iki yastığa dört kılıf hazırlar.","sektor":"Çoğunlukla çift kullanılır: alttaki kılıf yastığı korur, üstteki kılıf oda dekorasyonuna uygun seçilir ve konuğa görünür.","iliskili":["kh1-3-019","kh1-3-003"],"kontrol":null,"gorsel":"t10c-yastik-kilifi"},{"id":"kh1-3-019","konu":"3.1.2","terim":"Yatak örtüsü","ingilizce":"Bedspread","tanim":"Hazırlanmış yatağın üzerine tüm yatağı kaplayacak biçimde örtülen, görünümü güzelleştirip kirlenmesini önleyen örtüdür.","ornek":"Öğlen 12.00’de görevli Elif, 210 numaralı odadaki çift kişilik yatağa kendi ölçüsündeki örtüyü seçer; örtü iki yandan eşit sarkar ve yatak ilk bakışta toplu görünür.","sektor":"Örtünün ölçüsü ve modeli yatağın çeşidine göre değişir; yatağa ilk bakışta düzenli ve bakımlı görünüm kazandırır.","iliskili":["kh1-3-020","kh1-3-021"],"kontrol":null,"gorsel":"t10c-yatak-ortusu"},{"id":"kh1-3-020","konu":"3.1.2","terim":"Runner","ingilizce":"Bed runner","tanim":"Yatağın yalnızca ayak ucuna serilen, eni yatak örtüsünden daha dar ve kısa bir mefruşat ürünüdür.","ornek":"Bodrum’daki butik bir otelde görevli Cem, tam yatak örtüsü yerine yatağın ayak ucuna ince kırmızı bir runner serer; beyaz yatakta renkli bir çizgi oluşur.","sektor":"Bazı işletmeler kullanım kolaylığı nedeniyle runner tercih eder; yatak örtüsüne göre daha az malzeme kullanılır.","iliskili":["kh1-3-019","kh1-3-021"],"kontrol":null,"gorsel":"t10c-runner"},{"id":"kh1-3-021","konu":"3.1.2","terim":"Dekoratif şal","ingilizce":"Decorative throw","tanim":"Yatak örtüsü yerine yatağın üzerine serilebilen, süs amaçlı kullanılan bir örtüdür.","ornek":"Kapadokya’daki taş otelde görevli Ayşe, beyaz yatağın ayak ucuna el dokuması bir dekoratif şal bırakır; oda daha sıcak ve yerel görünür.","sektor":"Şal ve runner, yatak örtüsüne alternatif olarak odanın havasını değiştirir.","iliskili":["kh1-3-019","kh1-3-020"],"kontrol":null,"gorsel":"t12r-yatak-sal"},{"id":"kh1-3-022","konu":"3.1.2","terim":"Kat arabasını yatak yapımı için hazırlama","ingilizce":"Stocking the housekeeping trolley for bed making","tanim":"Yatak yapımında gereken çarşaf, nevresim, yastık kılıfı, yatak koruyucu ve diğer tekstil malzemesinin işe başlamadan kat arabasına eksiksiz yerleştirilmesidir.","ornek":"Sabah 08.30’da kat ofisinde görevli Selin, 3. kattaki odalar için mevsime uygun pikeyi ve yeterli çarşafı kat arabasına dizer.","sektor":"Eksik malzeme yüzünden odadan çıkıp depoya yürümek zaman kaybettirir; konuğun odasının geç hazırlanmasına yol açar.","iliskili":["kh1-3-023","kh1-3-003"],"kontrol":null,"gorsel":"h3b-camasir-arabalari"},{"id":"kh1-3-023","konu":"3.1.2","terim":"Malzeme ihtiyaç listesi kontrolü","ingilizce":"Linen requirement check","tanim":"Kat arabasına alınan malzemelerin, çalışılacak odaların yatak ihtiyacına yettiğini bir listeye bakarak denetlemektir.","ornek":"Sabah 08.40’ta görevli Murat, listesine bakarak arabasında çarşaf, nevresim, yastık kılıfı ve havlunun tamam olduğunu görür.","sektor":"Kontrol işe başlamadan yapılırsa oda yarıda bırakılmaz; konuk eksik malzeme beklemez.","iliskili":["kh1-3-022","kh1-3-003"],"kontrol":null},{"id":"kh1-3-024","konu":"3.2","terim":"Yatak yapım prosedürü","ingilizce":"Bed-making procedure","tanim":"Kullanılacak malzemeleri ve işlem basamaklarını işletmenin belirlediği sırayla uygulamayı sağlayan, yatak yapımına özgü iş kuralıdır.","ornek":"Yeni başlayan görevli Cem’e kat şefi Hülya, ilk haftasında işletmenin yatak yapım prosedürünü adım adım gösterir ve her adımı birlikte tekrarlarlar.","sektor":"Herkes aynı sırayı izlerse yataklar aynı kalitede görünür; konuk hangi odaya girerse girsin aynı standardı bulur. Kat hizmetleri görevlileri işletmeye ait prosedürü takip eder.","iliskili":["kh1-3-025","kh1-3-027"],"kontrol":null},{"id":"kh1-3-025","konu":"3.2","terim":"Yatak yapım sırası","ingilizce":"Bed-making sequence","tanim":"Koruyucudan başlayıp alt çarşaf, üst çarşaf, battaniye, yastık ve yatak örtüsüyle biten, malzemelerin belirli düzenle serilmesidir.","ornek":"Sabah 09.45’te görevli Elif, 312 numaralı odada önce koruyucuyu, sonra alt çarşafı, üst çarşafı ve battaniyeyi sererek işini sırasında yürütür.","sektor":"Yanlış sıra, çarşafı yeniden sökmeyi gerektirir; zaman kaybettirir ve yatağın görünümünü bozar.","iliskili":["kh1-3-024","kh1-3-012"],"kontrol":null},{"id":"kh1-3-026","konu":"3.2","terim":"Yorganlı (french) yatak yapımı","ingilizce":"Duvet-style bed making","tanim":"Alt çarşafın üzerine nevresimli yorgan serilerek hazırlanan, “french yatak” adıyla da anılan yatak yapma yöntemidir.","ornek":"Öğleden sonra 16.00’da görevli Ayşe, yorganlı yatak yapan bir odada alezi taktıktan sonra alt çarşafı serer, yorganı nevresime geçirir.","sektor":"Bu yöntemde yorganın yan tarafları içe katlanır, ayak ucu yatağın altına yerleştirilir.","iliskili":["kh1-3-025","kh1-3-016"],"kontrol":null},{"id":"kh1-3-027","konu":"3.2","terim":"Yatak yapımı sonrası kontrol ve teslim","ingilizce":"Post-service check and handover","tanim":"İşlemlerin gözden geçirilmesi, oda durum raporunun doldurulup kat şefine teslim edilmesi ve pas anahtarının imza karşılığı geri verilmesidir.","ornek":"Gün sonunda görevli Murat, 3. kattaki odaların raporunu doldurur, tarih ve saati yazar, raporu ve pas anahtarını kat şefine imza karşılığı teslim eder.","sektor":"Teslim tarihi ve saatinin yazılması, anahtarın ve raporun sorumluluğunun kimde olduğunu gösterir.","iliskili":["kh1-3-024","kh1-3-025"],"kontrol":null},{"id":"kh1-3-028","konu":"3.2.1","terim":"Kirli yatak malzemelerinin toplanması","ingilizce":"Stripping the bed","tanim":"Konuk odasında kullanılmış yatak takımlarının yataktan alınıp kat arabasındaki kirli çamaşır sepetine konulmasıdır.","ornek":"Sabah 10.30’da görevli Elif, 308 numaralı odada çıkış yapan konuğun yatak takımlarını toplayıp arabadaki kirli sepetine bırakır.","sektor":"Toplama temiz-kirli ayrımını korur: kirli tekstil temiz malzemeyle karışmaz. Kirli takımlar kat arabasındaki kirli çamaşır sepetine konulur.","iliskili":["kh1-3-029","kh1-3-030"],"kontrol":null,"gorsel":"h3b-dagnik-yatak"},{"id":"kh1-3-029","konu":"3.2.1","terim":"Çarşafı köşelerinden toplama","ingilizce":"Gathering the sheets by the corners","tanim":"Yatak çarşaflarının köşelerinden tutulup birleştirilerek toplanmasıdır.","ornek":"Sabah 10.50’de 214 numaralı odada görevli Selin, kirli çarşafı dört köşesinden tutup birleştirerek toplar ve tek hamlede arabadaki kirli sepetine koyar; çarşaf yere değmez.","sektor":"Köşelerden birleştirerek toplamak, kirli çarşafın dağılmadan tek seferde kirli çamaşır sepetine konulmasını sağlar.","iliskili":["kh1-3-028","kh1-3-031"],"kontrol":null},{"id":"kh1-3-030","konu":"3.2.1","terim":"Yastık kılıfı çıkarma","ingilizce":"Removing pillowcases","tanim":"Kılıfın kapak kısmı açılıp yastığın köşelerinden tutularak yastığın kılıftan çıkarılmasıdır.","ornek":"Sabah 10.40’ta görevli Cem, yastığı köşelerinden tutarak kılıfı çıkarır ve yastığı odadaki koltuğa bırakır; yastık biçimini korur.","sektor":"Kılıfı köşelerinden tutarak çıkarmak yastığın şeklini bozmaz ve kılıfın kolay çıkmasını sağlar.","iliskili":["kh1-3-028","kh1-3-033"],"kontrol":null},{"id":"kh1-3-031","konu":"3.2.1","terim":"Lekeli yatak takımlarının ayrılması","ingilizce":"Separating stained linen","tanim":"Kirli takımlar arasındaki lekeli parçaların diğerlerinden ayrılarak çamaşırhaneye gönderilmesidir.","ornek":"Sabah 11.10’da görevli Ayşe, 3. kattaki odada lekeli bir çarşafı diğerlerinden ayırarak kat arabasındaki ayrı torbaya koyar.","sektor":"Lekeli parçalar ayrı gönderilirse çamaşırhane onlara ayrıca bakabilir; temiz görünen takımlarla karışmaz.","iliskili":["kh1-3-028","kh1-3-032"],"kontrol":null},{"id":"kh1-3-032","konu":"3.2.1","terim":"Kirli takımdaki konuk eşyası","ingilizce":"Guest belongings in used linen","tanim":"Toplanan çarşaf, kılıf gibi parçaların arasında konuğa ait bir eşya olup olmadığının kontrol edilmesidir.","ornek":"Sabah 11.20’de görevli Murat, çarşafı toplarken içinde bir kol saati bulur. Konuk hâlâ konaklıyorsa saati komodinin üzerine, görülebilir yere bırakır; konuk otelden ayrıldıysa resepsiyona teslim eder.","sektor":"Konuğa ait eşya görülebilir yere bırakılır; konuk işletmeden ayrılmışsa eşya resepsiyon bölümüne teslim edilir. Böylece eşya kaybolmaz, sorumluluk net kalır.","iliskili":["kh1-3-031","kh1-3-028"],"kontrol":null},{"id":"kh1-3-033","konu":"3.2.1","terim":"Yatağın havalandırılması","ingilizce":"Airing the bedding","tanim":"Yatak toplanırken battaniye, yorgan ve yastığın temiz bir koltuk ya da sandalyeye alınarak havalanmasının sağlanmasıdır.","ornek":"Sabah 11.30’da görevli Elif, çıkardığı battaniyeyi ve yastığı odadaki koltuğun üzerine koyarak yatağı havalanmaya bırakır.","sektor":"Çıkarılan malzeme yere değmeden temiz bir yerde bekler; yatak da açıkken havalanır.","iliskili":["kh1-3-030","kh1-3-028"],"kontrol":null,"gorsel":"t11c-yatak-havalandirma"},{"id":"kh1-3-208","konu":"3.2.2","terim":"Temiz tekstilin odada koltuğa hazırlanması","ingilizce":"Laying out clean linen in the room","tanim":"Yatağı yapmadan önce odanın kategorisine ve yatak tipine uygun temiz tekstilin kat arabasından alınıp odadaki koltuğa konulmasıdır.","ornek":"Sabah 11.35’te görevli Elif, 310 numaralı çift kişilik odada gerekli çarşaf, nevresim ve yastık kılıflarını arabadan alıp koltuğa dizer; yatak yapılırken her parça elinin altındadır.","sektor":"Ders materyalindeki yorganlı yatak uygulamasında temiz tekstil odanın kategorisine göre arabadan alınıp koltuğun üzerine konur; böylece parçalar yatak yapımı sırasında eksiksiz ve elinin altında hazır bulunur.","iliskili":["kh1-3-022","kh1-3-033","kh1-3-034"],"kontrol":null},{"id":"kh1-3-034","konu":"3.2.2","terim":"Yatak koruyucunun kontrolü","ingilizce":"Checking the mattress protector","tanim":"Yapıma başlarken koruyucunun temiz olup olmadığına bakılması; kirli olanların köşe lastiklerinden çıkarılıp toplanmasıdır.","ornek":"Sabah 11.40’ta görevli Selin 310 numaralı odada koruyucunun kenarında leke görünce lastiklerinden çıkarıp kirliye atar.","sektor":"Kirli koruyucu temiz çarşafın altında kalırsa koku ve hijyen sorunu yaratır; kontrol bu yüzden her yatak yapımında yapılır.","iliskili":["kh1-3-035","kh1-3-036"],"kontrol":null},{"id":"kh1-3-035","konu":"3.2.2","terim":"Köşe lastikli yatak koruyucu","ingilizce":"Fitted mattress protector","tanim":"Köşelerindeki lastikler sayesinde yatağın köşelerine geçirilerek yerinde duran yatak koruyucudur.","ornek":"Görevli Cem, 215 numaralı odada lastikli koruyucuyu yatağın dört köşesine sırayla geçirir; koruyucu gece boyunca kaymaz ve kıvrılıp kalmaz.","sektor":"Lastikler sayesinde koruyucu kaymaz ve çarşafın altında buruşmaz; yatak düzgün görünür.","iliskili":["kh1-3-034","kh1-3-036","kh1-3-038"],"kontrol":null},{"id":"kh1-3-037","konu":"3.2.2","terim":"Yatak ve baza kontrolü","ingilizce":"Mattress and base check","tanim":"Yatağın ve bazanın kirli olup olmadığına bakılması; leke varsa silme işleminin yapılmasıdır.","ornek":"Öğleden sonra 16.20’de görevli Murat, koruyucuyu çıkardıktan sonra bazadaki küçük lekeyi fark eder ve nemli bezle siler; sonraki konuk gelmeden yüzey kurur.","sektor":"Yatak ve baza yıkanamadığı için leke fark edilir edilmez silinir; sonraki konuğa temiz bir yatak teslim edilir.","iliskili":["kh1-3-034","kh1-3-038"],"kontrol":null},{"id":"kh1-3-038","konu":"3.2.2","terim":"Koruyucu lastiklerinin sağlamlığı","ingilizce":"Checking elastic bands","tanim":"Yatak koruyucunun köşe lastiklerinin kopuk ya da gevşek olmadığının kontrol edilmesidir.","ornek":"Sabah 11.50’de görevli Elif, koruyucuyu takmadan önce köşe lastiklerini elle gererek sağlamlığını yoklar; bir lastik kopuk çıkınca koruyucuyu kirliye ayırıp yenisini alır.","sektor":"Lastiği gevşek koruyucu yatak üzerinde kayar; bu da çarşafın düzgün durmasını engeller.","iliskili":["kh1-3-037","kh1-3-035","kh1-3-036"],"kontrol":null},{"id":"kh1-3-036","konu":"3.2.2","terim":"Temiz yatak koruyucuyu takma","ingilizce":"Fitting a clean mattress protector","tanim":"Koruyucunun temiz hâlinin yatağa serilip lastikleriyle köşelere geçirilmesi ve bu işlemin yatağın üzerinde yapılmasıdır.","ornek":"Görevli Ayşe, 410 numaralı odada temiz koruyucuyu önce yatağa serer, sonra yatağın üzerindeyken köşelerini geçirir; koruyucu yere hiç değmez.","sektor":"İşlemi yatağın üzerinde yapmak koruyucunun yere değmesini önler ve doğru oturmasını kolaylaştırır.","iliskili":["kh1-3-035","kh1-3-038","kh1-3-034"],"kontrol":null,"gorsel":"t12r-yatak-koruyucu"},{"id":"kh1-3-039","konu":"3.2.3","terim":"Alt çarşaf açma","ingilizce":"Laying the bottom sheet","tanim":"Alt çarşafın yatak koruyucunun üzerine iki yana eşit sarkacak şekilde serilmesi, üste gelen bölümlerinin görevliye doğru çekilerek açılması ve köşelerinin yatak başından başlanarak zarf biçiminde katlanmasıdır.","ornek":"Öğleden sonra 12.10’da görevli Cem, alt çarşafı yatağın ortasına hizalayıp yatak başından başlayarak köşelere sırayla geçer.","sektor":"İki yana eşit sarkan çarşaf yatağa simetrik ve düzgün bir görünüm verir.","iliskili":["kh1-3-040","kh1-3-041"],"kontrol":null},{"id":"kh1-3-040","konu":"3.2.3","terim":"Orta kat çizgisi","ingilizce":"Centre fold line","tanim":"Çarşafın tam ortasından geçen, yatağın ortasına hizalanması gereken kat izidir.","ornek":"Görevli Selin, 305 numaralı odada çarşafın orta kat çizgisini yatağın tam ortasına getirir ve sonra çarşafı iki yana açar; iki yandaki sarkma eşit çıkar.","sektor":"Bu çizgi hizalanmazsa çarşaf bir yana fazla sarkar ve köşeler düzgün yapılamaz.","iliskili":["kh1-3-039","kh1-3-041"],"kontrol":null},{"id":"kh1-3-041","konu":"3.2.3","terim":"Çarşafın başucunda paketlenmesi","ingilizce":"Tucking the head of the sheet","tanim":"Yatak başucu tarafındaki çarşaf kenarının yatak ile baza arasına paket hâlinde yerleştirilmesidir.","ornek":"Yorganlı yatak yapan görevli Murat, alt çarşafı serdikten sonra başucu kenarını paket yaparak yatakla baza arasına sokar.","sektor":"Başucu kenarı sabitlenirse çarşaf kayarak yastık altında buruşmaz.","iliskili":["kh1-3-039","kh1-3-040","kh1-3-207"],"kontrol":null},{"id":"kh1-3-207","konu":"3.2.3","terim":"Çarşafın ayak ucundan gerilerek yerleştirilmesi","ingilizce":"Pulling the sheet taut at the foot","tanim":"Alt çarşafın ayak ucu tarafından hafifçe gerilip yatak ile baza arasına yerleştirilmesidir.","ornek":"Öğleden sonra 13.15’te görevli Ayşe, yorganlı yatakta çarşafın başucunu paketledikten sonra ayak ucuna geçer, çarşafı hafifçe gererek yatakla baza arasına sokar; çarşaf yatağın üzerinde düzgün durur.","sektor":"Ders materyalindeki yorganlı yatak uygulamasında alt çarşaf önce başucundan paketlenir, sonra ayak ucundan gerilerek yerleştirilir, en son yan taraflar zarf biçiminde katlanır. Bu sıra çarşafın yatakta düzgün kalmasına yardım eder.","iliskili":["kh1-3-041","kh1-3-042","kh1-3-044"],"kontrol":null},{"id":"kh1-3-042","konu":"3.2.3","terim":"Zarf köşe","ingilizce":"Hospital corner","tanim":"Çarşaf köşesinin zarf ağzı gibi katlanıp yatağın altına yerleştirilmesiyle elde edilen düzgün köşedir.","ornek":"Öğleden sonra 12.30’da görevli Elif, alt çarşafı yatak başından başlayarak köşelere zarf köşe yapar; yatak otel standardında görünür.","sektor":"Zarf köşe çarşafın kaymasını önler ve yatağa tam, düzgün bir köşe görünümü verir.","iliskili":["kh1-3-043","kh1-3-044"],"kontrol":null},{"id":"kh1-3-043","konu":"3.2.3","terim":"Zarf köşede çalışma duruşu","ingilizce":"Working position at the corner","tanim":"Kolların ve ellerin rahat çalışabilmesi için görevlinin katlanacak köşenin önünde durmasıdır.","ornek":"Görevli Cem, köşeyi yana dönerek katlamaya çalışırken omzunu zorlar; kat şefi Hülya ona köşenin önünde durmayı gösterir.","sektor":"Doğru duruş sırtı ve kolları yorgunluktan korur ve işi hızlandırır.","iliskili":["kh1-3-042","kh1-3-044"],"kontrol":null},{"id":"kh1-3-044","konu":"3.2.3","terim":"Köşenin yatağın altına yerleştirilmesi","ingilizce":"Tucking in the corner","tanim":"Yatak kenarlarından sarkan çarşafın yatak kaldırılarak altına yerleştirilmesi ve köşede kalan kısmın öne getirilip yatağın altına sıkıştırılmasıdır.","ornek":"Görevli Ayşe, 118 numaralı odada köşede kalan çarşaf kısmını öne getirir, yatağı hafifçe kaldırıp köşeyi altına sokar; köşe gün boyunca yerinde durur.","sektor":"Sıkı yerleştirilen köşe çarşafın gün boyunca yerinde kalmasını sağlar.","iliskili":["kh1-3-042","kh1-3-043"],"kontrol":null},{"id":"kh1-3-045","konu":"3.2.4","terim":"Üst çarşaf açma","ingilizce":"Laying the top sheet","tanim":"Üst çarşafın yatak başından belirli bir pay bırakılarak ve dikiş yerleri üste gelecek şekilde yatağa serilmesidir.","ornek":"Öğleden sonra 12.50’de görevli Selin, 312 numaralı odada üst çarşafı alt çarşafın üzerine yatak başından pay bırakarak ve dikiş yerleri üste gelecek biçimde serer.","sektor":"Doğru açılan üst çarşaf battaniyenin konuğa değmesini engeller ve yatağın düzenli görünmesini sağlar.","iliskili":["kh1-3-046","kh1-3-047"],"kontrol":null},{"id":"kh1-3-046","konu":"3.2.4","terim":"Üst çarşafta dikiş yerinin üste gelmesi","ingilizce":"Seam side up","tanim":"Üst çarşafın dikiş yerlerinin yatağın üst yüzüne gelecek şekilde serilmesidir.","ornek":"Görevli Murat, bir kattaki bütün odalarda üst çarşafın dikiş yerlerini aynı yöne çevirir; kat şefi koridor turunda tüm yatakları aynı düzende bulur.","sektor":"Ders materyaline göre dikiş yerleri üste gelir; işletme standardı farklı belirleyebilir. Dikiş yönü her odada aynı olursa bütün yataklar aynı düzende görünür.","iliskili":["kh1-3-045","kh1-3-047"],"kontrol":null},{"id":"kh1-3-047","konu":"3.2.4","terim":"Üst çarşafın başucu payı","ingilizce":"Top sheet turn-over allowance","tanim":"Üst çarşafın yatak başında battaniyenin ya da örtünün üzerine katlanmak üzere bırakılan fazla kısmıdır.","ornek":"Görevli Elif, üst çarşafı yatak başından pay bırakacak şekilde serer ve battaniyeyi serdikten sonra payı battaniyenin üstüne katlar.","sektor":"Ders materyaline göre bu pay yatak başından 10-20 cm kadardır. Pay katlanınca çarşafın düzgün kenarı görünür ve battaniye konuğa değmez.","iliskili":["kh1-3-045","kh1-3-046"],"kontrol":null},{"id":"kh1-3-048","konu":"3.2.5","terim":"Battaniye açma","ingilizce":"Placing the blanket","tanim":"Serin havalarda battaniyenin üst çarşafın üzerine, etiketi ayak ucuna gelecek şekilde serilmesidir.","ornek":"Akşam 17.15’te 207 numaralı odada görevli Ayşe, serin bir akşam için battaniyeyi üst çarşafın üzerine iki yana eşit sarkacak biçimde serer.","sektor":"Battaniye eşit sarkıtılırsa yatak iki yandan da düzgün görünür.","iliskili":["kh1-3-049","kh1-3-050"],"kontrol":null},{"id":"kh1-3-049","konu":"3.2.5","terim":"Battaniye etiketinin ayak ucunda olması","ingilizce":"Blanket label at the foot","tanim":"Battaniyenin etiketinin konuğun görmeyeceği ayak ucu tarafına gelecek biçimde serilmesidir.","ornek":"Görevli Cem, battaniyeyi sererken etiketin ayak ucuna döndüğünü kontrol eder; etiket konuğun başucundan görünse yatak özensiz durur.","sektor":"Etiket görünmediğinde yatak daha temiz ve profesyonel durur.","iliskili":["kh1-3-048","kh1-3-050"],"kontrol":null},{"id":"kh1-3-050","konu":"3.2.5","terim":"Battaniye ile başucu arasındaki boşluk","ingilizce":"Gap at the head","tanim":"Battaniyenin yatak başından biraz uzak serilmesi ve aradaki boşluğa üst çarşafın fazlalığının katlanmasıdır.","ornek":"Görevli Selin, 405 numaralı odada battaniyeyi yatak başından mesafe bırakarak serer; üst çarşafın fazlası sonra bu boşluğa katlanacaktır.","sektor":"Ders materyaline göre battaniye ile başucu arasına 10-15 cm kadar mesafe bırakılır. Boşluk, çarşaf kıvrımının oturacağı yeri oluşturur.","iliskili":["kh1-3-048","kh1-3-051"],"kontrol":null},{"id":"kh1-3-051","konu":"3.2.5","terim":"Çarşaf kıvrımı","ingilizce":"Sheet fold-over","tanim":"Battaniyenin altına serilen ve başucunda bırakılan üst çarşaf fazlasının battaniyenin üstüne katlanmasıdır.","ornek":"Görevli Murat, üst çarşafın başucundaki fazlasını battaniyenin üzerine katlayarak düzgün bir çizgi oluşturur; battaniye konuğun yüzüne değmez.","sektor":"Kıvrım battaniyenin yastığa ve konuğun yüzüne değmesini önler ve yatağa şık bir görünüm verir.","iliskili":["kh1-3-050","kh1-3-205","kh1-3-052"],"kontrol":null,"gorsel":"t12r-ust-carsaf-basucu"},{"id":"kh1-3-205","konu":"3.2.5","terim":"Yastık payı kadar geri katlama","ingilizce":"Folding back to pillow depth","tanim":"Çarşaf ve battaniyenin başucundan yaklaşık bir yastık sığabilecek kadar ayak ucuna doğru yeniden katlanmasıdır.","ornek":"Öğleden sonra 13.00’te 215 numaralı odada görevli Cem, başucundaki çarşaf kıvrımını yaptıktan sonra battaniyeyi ve çarşafı yastığın duracağı yer kadar ayak ucuna doğru geri katlar; yastıklar bu boşluğa yerleşecektir.","sektor":"Ders materyaline göre bu katlama yastığa yer açar; yastıklar başucunda düzenli ve toplu durur.","iliskili":["kh1-3-051","kh1-3-052","kh1-3-053"],"kontrol":null},{"id":"kh1-3-052","konu":"3.2.5","terim":"Ayak ucundan sıkıştırma","ingilizce":"Tucking at the foot","tanim":"Battaniye ve üst çarşafın ayak ucu tarafına geçilip yatağın altına sıkıştırılması ve köşelerinin zarf biçiminde katlanmasıdır.","ornek":"Görevli Elif, 308 numaralı odada yatağın ayak ucuna geçip battaniye ve üst çarşafı yatağın altına sıkıştırır, köşeleri zarf biçiminde katlar; çarşaf gece boyunca yerinde kalır.","sektor":"Sıkıştırılmış battaniye gün boyunca yerinde kalır ve kırışıklık oluşmasını önler.","iliskili":["kh1-3-205","kh1-3-051","kh1-3-042"],"kontrol":null},{"id":"kh1-3-053","konu":"3.2.6","terim":"Yastık kılıfı takma","ingilizce":"Putting on pillowcases","tanim":"Yastığın yatak üzerinde boyuna ikiye katlanıp kılıfa geçirilmesi ve köşelerinin kılıf köşelerine oturtulmasıdır.","ornek":"Öğleden sonra 13.10’da görevli Selin, 214 numaralı odada yastığı yatağın üzerinde boyuna ikiye katlar, tek eliyle tutup kılıfı geçirir; kılıf yastığa tam oturur.","sektor":"Doğru teknikle takılan kılıf yastığa tam oturur, buruşmaz.","iliskili":["kh1-3-054","kh1-3-055"],"kontrol":null,"gorsel":"t11c-yastik-kilifi-takili"},{"id":"kh1-3-054","konu":"3.2.6","terim":"Kılıfın açık tarafının görevliye dönük olması","ingilizce":"Pillowcase opening facing you","tanim":"Yastık konulacak bölüme serilen kılıfın açık tarafının görevliye gelecek şekilde çevrilmesidir.","ornek":"Görevli Cem, kılıfın açık tarafını kendine doğru çevirerek yatağa yayar; yastığı kılıfın içine kolayca sürer.","sektor":"Açık taraf kendine dönükse yastık kolayca içine yerleşir.","iliskili":["kh1-3-053","kh1-3-055"],"kontrol":null},{"id":"kh1-3-055","konu":"3.2.6","terim":"Yastığı boyuna ikiye katlama","ingilizce":"Folding the pillow lengthways","tanim":"Yastığın kılıfa geçirilmeden önce boyuna ikiye katlanıp bir elle tutulmasıdır.","ornek":"Görevli Ayşe, yastığı boyuna ikiye katlayıp bir eliyle tutar ve kılıfın ağzını diğer eliyle açar; yastığın köşeleri kılıfta sıkışmaz.","sektor":"Katlı yastık kılıftan kolay geçer; böylece yastığın köşeleri sıkışmaz.","iliskili":["kh1-3-053","kh1-3-056"],"kontrol":null},{"id":"kh1-3-056","konu":"3.2.6","terim":"Yastık ve kılıf köşelerinin denkliği","ingilizce":"Aligning pillow and case corners","tanim":"Yastığın köşelerinin kılıfın köşelerine ve açık uçtaki kat yerine oturmasıdır.","ornek":"Görevli Murat, yastığı kılıfa sokarken yastığın köşelerinin kılıfın köşelerine denk geldiğini kontrol eder; denk gelmeyince yastığı çıkarıp yeniden yerleştirir.","sektor":"Köşeler denk olunca yastık kabarık ve düzgün görünür.","iliskili":["kh1-3-053","kh1-3-057"],"kontrol":null},{"id":"kh1-3-057","konu":"3.2.6","terim":"Yastığın açık ucunun pencereye bakması","ingilizce":"Pillow opening facing the window","tanim":"Kılıf geçirilen yastığın açık uçlarının pencereye, yani konuğun görmeyeceği yöne bakacak şekilde yatağa konulmasıdır.","ornek":"Görevli Elif, kılıflı yastıkları yatağa koyarken açık uçların pencere yönüne baktığına dikkat eder; kapıdan giren konuk yalnızca düzgün kenarı görür.","sektor":"Kılıfın açık ucu görünmeyince yastık daha derli toplu durur.","iliskili":["kh1-3-053","kh1-3-058"],"kontrol":null},{"id":"kh1-3-058","konu":"3.2.6","terim":"İkinci yastığın yerleştirilmesi","ingilizce":"Placing the second pillow","tanim":"Yatakta kullanılacak ikinci yastıkların da kılıfa geçirilip yatağın üzerinde yerlerine yerleştirilmesidir.","ornek":"Görevli Selin, çift kişilik yatakta ilk yastığın yanına ikinci yastığı aynı yöne bakacak biçimde koyar; yatak başı simetrik görünür.","sektor":"İkinci yastıklar yatağa simetrik görünüm verir.","iliskili":["kh1-3-057","kh1-3-053"],"kontrol":null,"gorsel":"t11c-yastik-yerlestirme"},{"id":"kh1-3-059","konu":"3.2.7","terim":"Nevresim düzenleme","ingilizce":"Fitting the duvet cover","tanim":"Oda mefruşatına uygun nevresimin, iç tarafından iki el yardımıyla battaniyeye ya da yorgana geçirilmesidir.","ornek":"Öğleden sonra 13.30’da 3. kattaki yorganlı bir yatak için görevli Cem, kollarını nevresimin içine sokar, yorganın köşelerini yakalayıp nevresimi yorgana doğru çeker; nevresim buruşmadan yerine oturur.","sektor":"Nevresim sayesinde yorgan her konuktan sonra yıkanmak zorunda kalmaz; yalnız nevresim yıkanır. İçten geçirmek işlemi hızlandırır ve nevresimin buruşmasını azaltır.","iliskili":["kh1-3-061","kh1-3-016"],"kontrol":null,"gorsel":"h6-nevresim-yatak"},{"id":"kh1-3-061","konu":"3.2.7","terim":"Yorgan ve nevresim köşelerinin tutulması","ingilizce":"Matching duvet corners","tanim":"Nevresim geçirilirken yorgan ya da battaniyenin ve nevresimin köşelerinden el yardımıyla tutulmasıdır.","ornek":"Görevli Murat, nevresimi geçirirken yorgan ve nevresimin dört köşesini sırayla birbirine denkleştirir.","sektor":"Köşeler yerleşirse yorgan nevresim içinde kaymaz ve dolgu bir yerde toplanmaz.","iliskili":["kh1-3-059","kh1-3-062"],"kontrol":null},{"id":"kh1-3-062","konu":"3.2.7","terim":"Nevresim yoksa üst çarşafla kaplama","ingilizce":"Covering with a top sheet instead of a duvet cover","tanim":"Battaniye, yorgan ya da pikenin, nevresim bulunmadığında hijyen için üst çarşafla kaplanmasıdır.","ornek":"Akşam 19.30’da küçük bir pansiyonda görevli Elif, nevresimler çamaşırhaneden dönmediği için pikeyi temiz bir üst çarşafla kaplar; konuk pikeye değil çarşafa temas eder.","sektor":"Nevresim ya da çarşaf konuğun temas ettiği örtüyü korur ve daha hijyenik bir yatak sağlar.","iliskili":["kh1-3-059","kh1-3-016"],"kontrol":null},{"id":"kh1-3-063","konu":"3.2.8","terim":"Yatak örtüsü düzenleme","ingilizce":"Placing the bedspread","tanim":"Örtünün iki tarafa eşit sarkacak şekilde serilip yatağın üzerine kapatılması ve üst kısmının düzeltilmesidir.","ornek":"Öğleden sonra 13.50’de görevli Cem, örtünün iki yanını eşit sarkıtır, yastıkların üzerine kapatır ve üst kısmı düzeltir.","sektor":"Örtü yatağın tüm görünümünü belirler; düzgün serilmesi odanın ilk izlenimini güçlendirir.","iliskili":["kh1-3-064","kh1-3-065"],"kontrol":null,"gorsel":"t11c-yatak-ortusu-duzen"},{"id":"kh1-3-064","konu":"3.2.8","terim":"Oda rengine uygun örtü seçimi","ingilizce":"Choosing a bedspread to match the room","tanim":"Yatak örtüsünün genellikle oda rengine ve mefruşatına uygun seçilmesidir.","ornek":"Mavi tonlu odaların bulunduğu katta görevli Selin, aynı tonda yatak örtülerini seçer; perde, halı ve yatak uyum içinde görünür.","sektor":"Uyumlu örtü odanın bütünlüğünü korur; dekorasyonun bozulmasını önler.","iliskili":["kh1-3-063","kh1-3-065"],"kontrol":null,"gorsel":"t12c-oda-renginde-ortu"},{"id":"kh1-3-065","konu":"3.2.8","terim":"Runner’ın yatağın ayak ucuna serilmesi","ingilizce":"Laying the bed runner","tanim":"Bazı işletmelerde örtünün yerine kullanılan, eni daha kısa runner’ın yalnızca yatağın ayak ucuna serilmesidir.","ornek":"Görevli Murat, runner’ı yatağın ayak ucuna kırışmasın diye avucuyla düzelterek serer ve iki ucunun eşit sarktığını kontrol eder.","sektor":"Runner kullanımı kolay olduğundan bazı işletmeler tercih eder.","iliskili":["kh1-3-063","kh1-3-020"],"kontrol":null,"gorsel":"t15ad-yatak-runner"},{"id":"kh1-3-066","konu":"3.2.8","terim":"Yatak örtüsünün düzeltilip kontrol edilmesi","ingilizce":"Final check of the bedspread","tanim":"Kullanılan örtünün düzeltilmesi ve yatağın son hâlinin gözle denetlenmesidir.","ornek":"Öğleden sonra 14.00’te görevli Ayşe, odadan çıkmadan önce örtüde kırışıklık olup olmadığına bakar ve bir kıvrımı elle düzeltir.","sektor":"Son kontrol, yatağın konuğa teslim edilmeden önce eksiksiz olmasını güvenceye alır.","iliskili":["kh1-3-063","kh1-3-064"],"kontrol":null,"gorsel":"h5a-duzgun-yatak"},{"id":"kh1-3-067","konu":"3.2.9","terim":"Pike düzenleme","ingilizce":"Placing the coverlet","tanim":"Pikenin üst çarşafın üzerine serilip yatak üzerindeki pürüzlerin düzeltilmesidir.","ornek":"Temmuz sabahı Alanya’da görevli Elif, pikeyi üst çarşafın üzerine serer ve kırışıkları elle düzeltir.","sektor":"Düzenleme tekniği battaniyeye benzer. Pike hafif olduğu için tatil otellerinde sık kullanılır.","iliskili":["kh1-3-068","kh1-3-069"],"kontrol":null},{"id":"kh1-3-068","konu":"3.2.9","terim":"Pikenin başucu kıvrımı","ingilizce":"Coverlet fold-over","tanim":"Üst çarşafın başucu tarafında kalan fazla kısmın pikenin üzerine katlanmasıdır.","ornek":"Görevli Cem, 316 numaralı odada üst çarşafın başucu payını pikenin üzerine katlayıp çizgiyi düzeltir; pikenin yüzü konuğun yüzüne değmez.","sektor":"Ders materyaline göre bu kısım 10-20 cm kadardır. Kıvrım pikenin yüzüne değmeyi önler ve temiz görünüm sağlar.","iliskili":["kh1-3-067","kh1-3-047"],"kontrol":null},{"id":"kh1-3-069","konu":"3.2.9","terim":"Pikede pürüzlerin düzeltilmesi","ingilizce":"Smoothing the coverlet","tanim":"Pike yatağın üzerine serildikten sonra yatak üzerinde oluşan kırışıklıkların ve kabarıklıkların elle düzeltilmesidir.","ornek":"Görevli Ayşe, pikeyi serdikten sonra yatağın etrafında dolaşıp kırışıkları avuç içiyle düzeltir.","sektor":"Pürüzsüz yüzey yatağı bakımlı gösterir.","iliskili":["kh1-3-067","kh1-3-068"],"kontrol":null},{"id":"kh1-3-071","konu":"3.2.10","terim":"İlave yatak","ingilizce":"Extra bed","tanim":"Konuk odalarında ihtiyaç duyulduğunda kullanılan bebek karyolası, katlanabilir (portatif) yatak ve çekyat gibi ek yataklara verilen addır.","ornek":"Akşam 20.00’de resepsiyon, üç kişilik aile için 410 numaralı odaya ilave yatak istendiğini kat ofisine bildirir.","sektor":"İlave yatak, odanın yatak kapasitesini konuğun ihtiyacına göre artırır.","iliskili":["kh1-3-072","kh1-3-073"],"kontrol":null},{"id":"kh1-3-072","konu":"3.2.10","terim":"İlave yatak talebi","ingilizce":"Extra bed request","tanim":"Konuğun isteği üzerine odaya yatak eklenmesi için kat hizmetlerine iletilen taleptir.","ornek":"Çocuklu Yıldız ailesi resepsiyondan odalarına bir yatak daha ister; resepsiyon talebi kat ofisine iletir, kat şefi görevli Murat’ı yönlendirir.","sektor":"Talep geldiğinde kat görevlisi yatağı hazırlayıp odaya taşır; konuk beklemeden rahat eder.","iliskili":["kh1-3-071","kh1-3-078"],"kontrol":null},{"id":"kh1-3-073","konu":"3.2.10","terim":"Bebek karyolası","ingilizce":"Baby cot","tanim":"Küçük çocukların yatması için kullanılan, sabit ya da sallanabilir, çocuğun düşmesini engelleyen parmaklıklı yatak aracıdır.","ornek":"Akşam 19.00’da dört aylık bebeğiyle gelen Demir ailesi için görevli Selin, ebeveynlerin yatağının yanına sabit bir bebek karyolası kurar.","sektor":"Ders materyaline göre bebek karyolası 0-4 yaş aralığındaki çocuklar için kullanılır. Demir ya da ahşaptan yapılır ve güvenli uyku sağlar.","iliskili":["kh1-3-074","kh1-3-075","kh1-3-076"],"kontrol":null,"gorsel":"h5a-bebek-besigi"},{"id":"kh1-3-074","konu":"3.2.10","terim":"Park yatak","ingilizce":"Travel cot","tanim":"Konaklama işletmelerinde ahşap veya demir bebek karyolasının yerine de kullanılan, park tipi bebek yatağıdır.","ornek":"Bodrum’daki otelde görevli Cem, bebekli ailenin 112 numaralı odasında bebek karyolasının yerine park yatak kurar; yatak az yer kaplar.","sektor":"Park yatak, otelin bebek karyolası yerine kullandığı alternatiftir.","iliskili":["kh1-3-073","kh1-3-076"],"kontrol":null,"gorsel":"t15ad-park-yatak"},{"id":"kh1-3-075","konu":"3.2.10","terim":"Bebek takımı","ingilizce":"Baby bedding set","tanim":"Küçük ölçülü çarşaf, nevresim, yastık, yastık kılıfı, bebek battaniyesi veya yorganı ve yatak örtüsünden oluşan, karyola için ayrılmış tekstil takımıdır.","ornek":"Görevli Ayşe, bebek karyolasına gitmeden önce arabadan küçük ölçülü bebek takımını ve alezi ayırır; yetişkin çarşafı karyolaya uymaz.","sektor":"Bebek takımı küçük olduğundan yetişkin tekstili yerine özel olarak ayrılır.","iliskili":["kh1-3-073","kh1-3-076","kh1-3-077"],"kontrol":null},{"id":"kh1-3-076","konu":"3.2.10","terim":"Bebek karyolasının hazırlanması","ingilizce":"Preparing the baby cot","tanim":"Malzemelerin odaya getirilip karyolanın kurulması, ardından alez, alt çarşaf, üst çarşaf, battaniye ya da yorgan, yastık kılıfı ve örtünün sırayla serilmesidir.","ornek":"Görevli Murat, bebek karyolasını kurar, alezi serer, alt çarşafı yatağın altına sıkıştırır.","sektor":"Sıralı hazırlık karyolayı hijyenik ve güvenli hâle getirir.","iliskili":["kh1-3-073","kh1-3-075","kh1-3-077"],"kontrol":null,"gorsel":"t11c-bebek-karyolasi"},{"id":"kh1-3-077","konu":"3.2.10","terim":"Bebek yatağında sıvı geçirmez alez","ingilizce":"Waterproof protector for the cot","tanim":"Herhangi bir leke ya da ıslanmaya karşı bebek yatağını korumak için yatağın üzerine serilen sıvı geçirmez örtüdür.","ornek":"Görevli Elif, bebek karyolasında önce sıvı geçirmez alezi, sonra alt çarşafı serer.","sektor":"Bebek yatağı ıslanmaya yatkındır; alez yatağı korur ve temizliği kolaylaştırır.","iliskili":["kh1-3-075","kh1-3-076"],"kontrol":null,"gorsel":"t12q-bebek-yatagi"},{"id":"kh1-3-078","konu":"3.2.10","terim":"Portatif (katlanır) yatak","ingilizce":"Folding bed","tanim":"Odalarda sabit bulunmayan, katlanarak taşınabilen ve konuğun isteği üzerine kat görevlilerince odaya eklenen yatak çeşididir.","ornek":"Akşam 20.15’te görevli Cem, 308 numaralı odaya konuk isteği üzerine katlı portatif yatağı taşır; yatak asansörde katlı hâlde rahatça götürülür.","sektor":"Portatif yatağın taşınabilir olması en önemli özelliğidir; ihtiyaç olunca kolayca odaya getirilir.","iliskili":["kh1-3-079","kh1-3-080"],"kontrol":null,"gorsel":"t11c-portatif-yatak"},{"id":"kh1-3-079","konu":"3.2.10","terim":"Portatif yatağa yer açma","ingilizce":"Making room for the extra bed","tanim":"Yatağın konulacağı yerde eşya varsa kenara alınarak portatif yatak için yer açılması ve katlı yatağın düzgünce açılıp o yere sabitlenmesidir.","ornek":"Görevli Selin, 316 numaralı odada portatif yatağı kurmadan önce komodin ile sandalyeyi kenara çekip yer açar; yatağın etrafında geçiş alanı kalır.","sektor":"Yatağın yeri baştan belirlenirse odada geçiş alanı daralmaz.","iliskili":["kh1-3-078","kh1-3-080"],"kontrol":null},{"id":"kh1-3-080","konu":"3.2.10","terim":"Portatif yatağın hazırlanması","ingilizce":"Making up the folding bed","tanim":"Kurulmuş yatağa koruyucu, alt çarşaf, üst çarşaf, battaniye ya da pike, yastık ve örtünün sırayla yerleştirilmesidir.","ornek":"Görevli Ayşe, açtığı portatif yatağa önce temiz koruyucuyu, sonra alt çarşafı serer.","sektor":"Portatif yatak da sabit yatak kadar temiz ve düzenli hazırlanır.","iliskili":["kh1-3-078","kh1-3-079"],"kontrol":null},{"id":"kh1-3-081","konu":"3.2.10","terim":"Çekyat (oturma grubu koltuğu)","ingilizce":"Sofa bed","tanim":"Konuk odalarında koltuk olarak kullanılan, konuğun isteğine göre ilave yatağa dönüşebilen mobilyadır.","ornek":"Akşam 20.30’da çocuklu bir aile için görevli Elif, 5. kattaki odada çekyatı açıp yatak olarak hazırlar.","sektor":"Çekyat hem koltuk ihtiyacını karşılar hem de yatağa dönüşebildiği için çok tercih edilir; ayrıca işletmenin yatak kapasitesini artırır. Çocuklu aileler için ayrılan odalarda sık kullanılır.","iliskili":["kh1-3-082","kh1-3-071"],"kontrol":null,"gorsel":"t15ad-cekyat"},{"id":"kh1-3-082","konu":"3.2.10","terim":"Çekyatın yatağa dönüştürülmesi","ingilizce":"Converting the sofa bed","tanim":"Koltuk hâlindeki mobilyanın açılıp sabitlenmesi, koruyucu ve çarşafların serilmesi ve yapılan işlemlerin kontrol edilmesidir.","ornek":"Görevli Murat, çekyatı açıp sabitler, koruyucuyu serer, çarşafın köşelerini zarf biçiminde sıkıştırır.","sektor":"Çekyat yatağa çevrildikten sonra eksikliklerin giderilmesi için son kontrol yapılır.","iliskili":["kh1-3-081","kh1-3-062"],"kontrol":null,"gorsel":"t11c-cekyat"},{"id":"kh1-3-083","konu":"3.2.11","terim":"Yatak açma servisi (turn down service)","ingilizce":"Turn-down service","tanim":"Konuğun isteği doğrultusunda akşam saatlerinde housekeeping görevlisince yatağın açılıp odanın gece için hazırlanması ve “iyi geceler” notunun bırakılmasıdır.","ornek":"Akşam 20.30’da görevli Selin, konuk yemekteyken 405 numaralı odanın yatağını açar, ışıkları kısar ve perdeleri çeker.","sektor":"Bu hizmet her işletmede uygulanmayabilir; verildiğinde konuğa özen gösterildiğini hissettirir.","iliskili":["kh1-3-084","kh1-3-085","kh1-3-206"],"kontrol":null,"gorsel":"t10c-turndown-yatak"},{"id":"kh1-3-084","konu":"3.2.11","terim":"Turn down sırasında konuğun odada olması","ingilizce":"Turn-down with the guest in the room","tanim":"Yatak açma servisi yapılırken konuğun odada bulunması hâlinde kapı çalınıp izin istenerek, konuğu rahatsız etmeden hizmet verilmesidir.","ornek":"Akşam 21.00’de 305 numaralı odada konuk dinlenirken görevli Ayşe kapıyı çalar, izin ister ve işini hızlı ve sessizce yapar.","sektor":"Konuğun mahremiyetine saygı gösterilir; izin alınmadan odaya girilmez.","iliskili":["kh1-3-083","kh1-3-085"],"kontrol":null,"kitapDisi":true},{"id":"kh1-3-085","konu":"3.2.11","terim":"Yatak örtüsünün katlanıp kaldırılması","ingilizce":"Folding away the bedspread","tanim":"Turn down sırasında yatak örtüsünün başucundan ayak ucuna, sonra ortaya doğru ve enine birkaç kez ikiye katlanıp uygun bir dolaba kaldırılmasıdır.","ornek":"Akşam 20.35’te görevli Cem, 405 numaralı odada yatak örtüsünü birkaç kez ikiye katlayıp dolaba kaldırır; örtü yerde kirlenmez ve yatağın üzeri boşalır.","sektor":"Dolaba kaldırılan örtü konuğun yatağa girişini engellemez ve kirlenmez.","iliskili":["kh1-3-083","kh1-3-086"],"kontrol":null},{"id":"kh1-3-086","konu":"3.2.11","terim":"Battaniye ve üst çarşafın üçgen açılması","ingilizce":"Folding back the covers in a triangle","tanim":"Konuğun girişi için battaniye ve üst çarşafın yatağın üzerinden geriye doğru üçgen şeklinde katlanarak açılmasıdır.","ornek":"Akşam 20.40’ta görevli Elif, battaniye ile üst çarşafın bir köşesini üçgen biçiminde geriye katlar; konuk dönünce yatağa doğrudan girebilir.","sektor":"Ders materyaline göre battaniye ve üst çarşaf yatağın üzerinden 60-70 cm kadar geriye katlanır. Konuk yatağı hazır bulur.","iliskili":["kh1-3-085","kh1-3-087"],"kontrol":null},{"id":"kh1-3-087","konu":"3.2.11","terim":"Pijama ve gecelik bırakma","ingilizce":"Laying out nightwear","tanim":"Konuğun ya da konukların pijama ve gecelikleri yatağın üzerine bırakılmasıdır.","ornek":"Akşam 20.45’te görevli Murat, ailenin katlanmış pijamalarını yatağın üzerine bırakır; konuk yemekten dönünce giysilerini hazır bulur.","sektor":"Konuk kendi eşyasının düzenli bırakıldığını görür; özenle ilgilenildiğini hisseder.","iliskili":["kh1-3-086","kh1-3-088"],"kontrol":null,"gorsel":"t11c-pijama-takimi"},{"id":"kh1-3-088","konu":"3.2.11","terim":"Kahvaltı istek formu","ingilizce":"Breakfast order form","tanim":"Turn down sırasında yatağın üzerine bırakılan, konuğun ertesi sabah kahvaltısını önceden bildirmesini sağlayan formdur.","ornek":"Akşam 20.50’de görevli Selin, 412 numaralı odada yatağın üzerine kahvaltı istek formunu bırakır; konuk ertesi sabahın siparişini formda işaretler.","sektor":"Form, konuğun kahvaltı isteklerini önceden alarak sabah servisini kolaylaştırır.","iliskili":["kh1-3-089","kh1-3-086"],"kontrol":null},{"id":"kh1-3-089","konu":"3.2.11","terim":"Atıştırmalık ikram (lokum, çikolata)","ingilizce":"Turn-down sweets","tanim":"İşletmenin uygun gördüğü lokum, çikolata gibi atıştırmalık yiyeceklerin genellikle yastığın üzerine bırakılmasıdır.","ornek":"Akşam 21.00’de görevli Ayşe, yastığın üzerine bir lokum bırakır; konuk geceye küçük bir karşılamayla başlar.","sektor":"Küçük ikram, konuğa özel ilgi gösterildiğini hissettirir.","iliskili":["kh1-3-088","kh1-3-087"],"kontrol":null,"gorsel":"t15ad-lokum"},{"id":"kh1-3-206","konu":"3.2.11","terim":"İyi geceler notu","ingilizce":"Good night note","tanim":"Turn down sırasında konuğa nazik bir dilek iletmek için yatağın ya da yastığın üzerine bırakılan kısa nottur.","ornek":"Akşam 20.55’te görevli Elif, 405 numaralı odanın yatağını açtıktan sonra yastığın üzerine “İyi geceler dileriz” yazılı küçük bir not bırakır; konuk yemekten dönünce notu görür ve gülümser.","sektor":"Ders materyalinin sözlüğüne göre turn down hizmeti konuğa “iyi geceler” notu bırakmayı da kapsar. Not kısa, nazik ve işletmenin diliyle yazılır; hizmetin ayrıntısı işletmeden işletmeye değişir.","iliskili":["kh1-3-083","kh1-3-089","kh1-3-088"],"kontrol":null,"gorsel":"h5a-yatak-hazirligi"},{"id":"kh1-3-090","konu":"3.2.11","terim":"Pencere ve balkon kapısı kontrolü","ingilizce":"Checking windows and balcony door","tanim":"Turn down sonunda balkon kapısı ve pencerelerin kontrol edilip açık olanların kapatılmasıdır.","ornek":"Akşam 21.10’da görevli Cem, balkon kapısının ve pencerelerin kapalı olduğunu kontrol eder, açık kalan bir pencereyi kapatır.","sektor":"Kapalı pencere ve balkon kapısı konuğun gece güvenliğini ve konforunu sağlar.","iliskili":["kh1-3-091","kh1-3-092"],"kontrol":null,"gorsel":"t10c-balkon-kapisi"},{"id":"kh1-3-091","konu":"3.2.11","terim":"Perdelerin kapatılması","ingilizce":"Drawing the curtains","tanim":"Turn down sonunda perdelerin kapatılmasıdır.","ornek":"Akşam 21.15’te görevli Elif, pencereleri kapattıktan sonra perdeleri çeker; oda dışarıdan görünmez.","sektor":"Perdeler kapanınca konuk dışarıdan görünmez ve oda uykuya hazır olur.","iliskili":["kh1-3-090","kh1-3-092"],"kontrol":null,"gorsel":"t11c-perde"},{"id":"kh1-3-092","konu":"3.2.11","terim":"Turn down son kontrolü ve ışık","ingilizce":"Final check and leaving a light on","tanim":"Odadan çıkmadan önce son kontrollerin yapılması ve sensörlü ışık yoksa ışıklardan birinin açık bırakılmasıdır.","ornek":"Görevli Murat, odadan çıkarken sensörlü ışık olmadığını görür ve bir ışığı açık bırakır.","sektor":"Açık bırakılan ışık konuğun odaya dönünce yolunu rahat bulmasını sağlar.","iliskili":["kh1-3-090","kh1-3-091"],"kontrol":null,"gorsel":"t10c-yanik-lamba"},{"id":"kh1-3-151","konu":"3.3.1","terim":"Havlu","ingilizce":"Towel","tanim":"Vücudun ıslak kalan yerlerini kurulamak için kullanılan, suyu çabuk emen dokuma bezdir.","ornek":"Sabah 08.00’de Antalya’daki bir otelde duştan çıkan konuk, yüzünü yüz havlusuyla, vücudunu banyo havlusuyla kurular.","sektor":"Havlu konuk odasından sahile, havuz kenarından hamama ve saunaya kadar otelin her alanında kullanılır; konuk en çok dokunduğu tekstillerden biri olduğu için temizliği ve kalitesi hemen fark edilir.","iliskili":["kh1-3-152","kh1-3-153","kh1-3-154"],"kontrol":null,"gorsel":"t10c-havlu-yigini"},{"id":"kh1-3-152","konu":"3.3.1","terim":"Peşkir","ingilizce":"Peshkir (old Turkish word for towel)","tanim":"Havlunun eski adıdır; ders materyaline göre havlu (peşkir) sözcüğü ilk kez Anadolu Selçuklu dönemine ait kaynaklarda görülür.","ornek":"Hamam kültürünü anlatan bir rehber, müzedeki eski belgelerde “peşkir” diye geçen bezin bugünkü havlunun adı olduğunu öğrencilere açıklar.","sektor":"Otel hamamında ya da SPA’sında geleneksel peşkir ve peştamal sunan işletmeler, konuğa Türk banyo kültürünü yaşatmış olur.","iliskili":["kh1-3-151","kh1-3-155"],"kontrol":null,"gorsel":"t10c-peskir"},{"id":"kh1-3-153","konu":"3.3.1","terim":"Hav","ingilizce":"Pile","tanim":"Kadife benzeri kumaşların yüzeyindeki ince tüylerdir.","ornek":"Oda görevlisi Elif, yıkanmış havluyu katlarken avucunu yüzeyinde gezdirir ve havın yumuşak durduğunu kontrol eder.","sektor":"Havın bolluğu havlunun su emmesini ve yumuşaklığını etkiler; havı yıpranmış havlu konuğa özensiz bir izlenim bırakır.","iliskili":["kh1-3-154","kh1-3-151"],"kontrol":null,"gorsel":"t10c-hav"},{"id":"kh1-3-154","konu":"3.3.1","terim":"Havlu kumaş","ingilizce":"Terry towelling","tanim":"Yüzeyi havlarla kaplı, su emici olan ve havlu üretiminde kullanılan dokuma kumaştır.","ornek":"Denizli’deki bir tekstil atölyesini gezen öğrenciler, havlu kumaşın yüzeyindeki ince tüylerin suyu nasıl tuttuğunu elleriyle inceler.","sektor":"Otellerde havlu ve bornoz gibi ürünlerin çoğu havlu kumaştan yapılır; kumaşın kalitesi ürünün ömrünü belirler.","iliskili":["kh1-3-153","kh1-3-174"],"kontrol":null,"gorsel":"t10c-havlu-kumas"},{"id":"kh1-3-155","konu":"3.3.1","terim":"Peştamal","ingilizce":"Peshtemal (Turkish bath towel)","tanim":"Hamamda ve kurulanmada kullanılan, ince dokulu geleneksel Türk dokumasıdır.","ornek":"Bodrum’daki otelin hamamına giren konuğa kapıda temiz bir peştamal ve havlu verilir; peştamal hamamın sıcak ve nemli ortamında hafif kalır.","sektor":"Modal ve keten gibi hızlı kuruyan liflerden yapılan peştamallar SPA, hamam ve sauna bölümlerinde havlu ve bornozla birlikte sunulur.","iliskili":["kh1-3-152","kh1-3-176","kh1-3-177"],"kontrol":null,"gorsel":"t10c-pestamal"},{"id":"kh1-3-156","konu":"3.3.1","terim":"Havlunun tarihçesi","ingilizce":"History of the towel","tanim":"Türk hamam kültürüyle yayılan havlunun ilk üretim yerinin, ipek dokumada önde olan Bursa sayıldığını anlatan öyküdür.","ornek":"Bursa’yı gezen bir grup öğrenci, rehberden hamamların yayılmasıyla peştamal ve havluya olan ihtiyacın hızla arttığını öğrenir.","sektor":"Ders materyaline göre Bursa, ipek böceği yetiştiriciliği ve ipek dokumada önde olduğu için havlunun ilk üretim yeri kabul edilir; Anadolu’daki ilk dokuma atölyesi XV. yüzyılda Bursa’da bir tekkede kurulmuş, İstanbul’un fethinden sonra kentlerde hamamlar çoğalınca peştamal ve havlu talebi artmıştır. Otel, havlunun bu kültürel köküyle konuğa hikâye anlatabilir.","iliskili":["kh1-3-158","kh1-3-157","kh1-3-151"],"kontrol":null,"gorsel":"t10c-havlu-tarihce"},{"id":"kh1-3-157","konu":"3.3.1","terim":"Havlu dokumada makineleşme","ingilizce":"Mechanised towel weaving","tanim":"El tezgâhlarında yapılan dokumanın Sanayi Devrimi’yle birlikte makineli ve endüstriyel üretime geçmesidir.","ornek":"Bir fabrika gezisinde öğrenciler, geçmişte tezgâhta saatler süren bir işin bugün makinelerde kısa sürede yapıldığını görür.","sektor":"Ders materyaline göre XVIII. yüzyılda İngiltere’de dokuma makineleri geliştirilmiştir; otellerin yüzlerce havluyu aynı kalitede sürekli yenileyebilmesi bu sanayi üretimine dayanır.","iliskili":["kh1-3-156","kh1-3-158"],"kontrol":null,"gorsel":"t10c-dokuma-tezgahi"},{"id":"kh1-3-158","konu":"3.3.1","terim":"Bursa ve Denizli havlusu","ingilizce":"Bursa and Denizli towels","tanim":"Türkiye’de havlu ve türevi ürünlerin üretiminde öne çıkan, Bursa ile dünyaca ünlü havlularıyla Denizli olmak üzere iki ildir.","ornek":"Marmaris’te yeni açılan bir otelin satın alma sorumlusu, havlu tedarikçisini seçmek için Denizli’deki bir fabrikayı ziyaret eder.","sektor":"Ders materyaline göre bu illerde üretilen havlu ve türevi ürünler Türkiye’nin en çok ihraç ettiği ürünler arasındadır; otelde “Türk havlusu” sunmak ülkenin üretim gücünü konuğa göstermenin bir yoludur.","iliskili":["kh1-3-156","kh1-3-157"],"kontrol":null},{"id":"kh1-3-159","konu":"3.3.1","terim":"Kraliyet Türk Havlusu","ingilizce":"Royal Turkish Towel","tanim":"Osmanlı dokuması havluların İngiltere’ye götürülüp kraliyet ailesince beğenildiği anlatılan, havlunun dünyaya tanınmasıyla ilgili bir öyküdür.","ornek":"Otel eğitiminde kat şefi, havlu tarihine ilgi gösteren stajyerlere bu öyküyü anlatarak havlunun neden prestijli sayıldığını açıklar.","sektor":"Ders materyalindeki anlatıya göre havlular Buckingham Palace’da “Kraliyet Türk Havlusu” adıyla kullanılmış ve 1851’de Londra’daki bir sergide ödül almıştır. Öykü tek kaynaktan aktarıldığı için “anlatılır” kaydıyla verilir.","iliskili":["kh1-3-156","kh1-3-158"],"kontrol":null},{"id":"kh1-3-160","konu":"3.3.2","terim":"Havlu çeşitlerinin sınıflandırılması","ingilizce":"Towel classification","tanim":"Havluların kullanım alanına ve üretim malzemesine göre iki ayrı ölçütle gruplanmasıdır.","ornek":"Satın alma sorumlusu Murat, yeni sezon listesini hazırlarken önce havluları banyo, plaj ve SPA kullanımına, sonra pamuk ve bambu gibi malzemelerine göre ayırır.","sektor":"Otel her alan için doğru havluyu seçtiğinde hem konuk memnun kalır hem de çamaşırhane ve satın alma işi düzenli yürür.","iliskili":["kh1-3-161","kh1-3-174"],"kontrol":null,"gorsel":"t10c-havlu-siniflama"},{"id":"kh1-3-161","konu":"3.3.2","terim":"Yüz havlusu","ingilizce":"Face towel","tanim":"Konuk odasındaki banyoda eli ve yüzü kurulamak için buklet malzemeleriyle birlikte bulunan havludur.","ornek":"Sabah 08.15’te lavabonun yanındaki sabunla ellerini yıkayan konuk, lavabonun üstünde asılı yüz havlusuyla ellerini ve yüzünü kurular; havlu temiz ve kuru olduğu için rahat eder.","sektor":"Ders materyaline göre ölçüsü 50x90 cm’dir; bazı işletmelerde ayrıca küçük bir el havlusu da bulunur. Yüz havlusu her konuk için temiz olmalıdır.","iliskili":["kh1-3-162","kh1-3-166","kh1-3-163"],"kontrol":null,"gorsel":"t11c-yuz-havlusu"},{"id":"kh1-3-162","konu":"3.3.2","terim":"El havlusu","ingilizce":"Guest towel","tanim":"Bazı işletmelerde yüz havlusundan ayrı olarak lavabo yanında bulunan küçük havludur.","ornek":"Alanya’daki bir otelde konuk odasında büyük yüz havlusunun yanına küçük bir el havlusu da asılmıştır.","sektor":"Ders materyaline göre ölçüsü 30x50 ya da 40x60 cm olabilir; bu ayrımı yapıp yapmamak işletmeye bağlıdır.","iliskili":["kh1-3-161","kh1-3-166"],"kontrol":null,"gorsel":"t11c-el-havlusu"},{"id":"kh1-3-163","konu":"3.3.2","terim":"Baş havlusu","ingilizce":"Hand towel","tanim":"Banyo havlusuyla birlikte konuk yatağının üzerinde katlanmış ya da origami şeklinde bulunan havludur.","ornek":"Oda görevlisi, 303 numaralı odada yatağın ayak ucuna banyo havlusunun yanına katlanmış baş havlusunu bırakır; iki havlu da beyaz ve düzgündür.","sektor":"Ders materyaline göre ölçüsü 50x90 cm’dir. Figürlerde baş, kuyruk ya da sepet sapı gibi küçük parçaları oluşturduğu için origami işinde sık kullanılan havludur.","iliskili":["kh1-3-166","kh1-3-161","kh1-3-192"],"kontrol":null},{"id":"kh1-3-164","konu":"3.3.2","terim":"Ayak havlusu","ingilizce":"Bath mat","tanim":"Küvet ya da duştan çıkarken ayakları kurulamak için kullanılan, yere serilen havludur.","ornek":"Duştan çıkan konuk, duş kabininin önüne serilmiş ayak havlusuna basarak ayaklarını kurular; ıslak fayansa basmaz.","sektor":"Ders materyaline göre ölçüsü 50x70 cm’dir. Islak zeminde kaymayı önlediği için aynı zamanda bir güvenlik ürünüdür.","iliskili":["kh1-3-165","kh1-3-166"],"kontrol":null,"gorsel":"t11c-ayak-havlusu"},{"id":"kh1-3-165","konu":"3.3.2","terim":"Ayak havlusunu yere serme","ingilizce":"Placing the bath mat","tanim":"Küvet ya da duşun hemen çıkışında, konuğun ayağını basacağı yere havlunun yayılmasıdır.","ornek":"Oda görevlisi banyoyu bitirirken ayak havlusunu duş kabininin dışına, düz ve kırışıksız şekilde serer.","sektor":"Islak zeminde yaşanabilecek düşme ve kayma durumlarını önler; bu nedenle ayak havlusu asılmaz, yere serilir.","iliskili":["kh1-3-164"],"kontrol":null,"gorsel":"t11c-ayak-havlusu-serme"},{"id":"kh1-3-166","konu":"3.3.2","terim":"Banyo havlusu","ingilizce":"Bath towel","tanim":"Konuk odasında vücudu kurulamak için kullanılan, büyük ölçülü ve genellikle beyaz havludur.","ornek":"Akşam 21.00’de duşa girecek konuk, yatağın üzerinde katlanmış duran banyo havlusunu alıp banyoya götürür; duştan sonra onunla kurulanır ve askıya asar.","sektor":"Ders materyaline göre ölçüsü 70x140 ya da 90x150 cm’dir; genellikle beyaz tercih edilir. Beyaz havlu temizliğin görünür olmasını ve yüksek ısıda yıkamayı kolaylaştırır.","iliskili":["kh1-3-163","kh1-3-167","kh1-3-160"],"kontrol":null,"gorsel":"t10c-banyo-havlusu"},{"id":"kh1-3-167","konu":"3.3.2","terim":"Bornoz","ingilizce":"Bathrobe","tanim":"Suyu çabuk emen, havlu ya da pamuklu kumaştan yapılmış, belinde kuşak bulunan banyo giysisidir.","ornek":"Rezervasyon yapılırken bornoz isteyen konuğun 502 numaralı odasında görevli, kuşağı bağlı temiz bir bornozu dolaba asar; konuk odaya girince hazır bulur.","sektor":"Üst düzey hizmet veren bazı otellerde konuk odasında hem banyo havlusu hem bornoz bulunur; bu ek hizmet işletmenin konuk memnuniyetine verdiği önemi yansıtır. Bornoz konuğa evindeymiş gibi bir rahatlık hissi verir.","iliskili":["kh1-3-168","kh1-3-166"],"kontrol":null,"gorsel":"t10c-bornoz"},{"id":"kh1-3-168","konu":"3.3.2","terim":"Bornozun SPA ve havuzda kullanımı","ingilizce":"Bathrobe use at the spa and pool","tanim":"Konukların bornozu hamam, sauna, SPA ya da havuza inerken üstlerine giymesidir.","ornek":"Konuk, öğleden sonra SPA’ya inerken odasındaki bornozu giyer ve havuz çıkışında yine onu kullanır.","sektor":"Bornoz konuğun odasıyla SPA arasında rahat gitmesini sağlar; otel bu yüzden bornozu da temizlik ve stok planına katar.","iliskili":["kh1-3-167","kh1-3-166"],"kontrol":null,"gorsel":"h5a-bornozlar"},{"id":"kh1-3-170","konu":"3.3.2","terim":"Plaj havlusu","ingilizce":"Beach towel","tanim":"Konukların sahilde ve havuz kenarında kullanması için hazırlanan, genellikle renkli havludur.","ornek":"Öğleden sonra 14.00’te havuz kenarındaki konuk, şezlongun üstüne turuncu plaj havlusunu serer; akşam toplama sırasında görevli, turuncu havluları odalardan gelen beyaz banyo havlularından kolayca ayırır.","sektor":"Ders materyaline göre ölçüsü 70x140 ya da 75x150 cm’dir. Renkli olması, odadaki beyaz banyo havlusuyla karışmasını önler.","iliskili":["kh1-3-171","kh1-3-172","kh1-3-173"],"kontrol":null,"gorsel":"t10c-plaj-havlusu"},{"id":"kh1-3-171","konu":"3.3.2","terim":"Plaj havlusu standı","ingilizce":"Beach towel counter","tanim":"Konukların plaj havlusunu aldığı sahil ya da havuz kenarındaki istasyondur.","ornek":"Antalya’daki bir otelin plajında konuk, kartını göstererek standdan temiz bir plaj havlusu alır.","sektor":"Stand, havlu dağıtımını düzenli tutar ve odaya götürülen havlu sayısını azaltır.","iliskili":["kh1-3-172","kh1-3-170"],"kontrol":null,"gorsel":"t10c-plaj-havlu-standi"},{"id":"kh1-3-172","konu":"3.3.2","terim":"Havlu kartı","ingilizce":"Towel card","tanim":"Check-in sırasında oda kartıyla birlikte verilen, sahil ya da havuz kenarında plaj havlusu almaya yarayan karttır.","ornek":"Resepsiyonda check-in yapan konuğa oda kartıyla birlikte havlu kartı da verilir; konuk kartı plajda havlu almak için saklar.","sektor":"Sahil kenarındaki işletmelerde havlu kartı, havlu dağıtımını konuk bazında izlemeyi kolaylaştırır.","iliskili":["kh1-3-171","kh1-3-170"],"kontrol":null,"gorsel":"t10k-havuz-havlu-kulubesi"},{"id":"kh1-3-173","konu":"3.3.2","terim":"Şezlongdaki plaj havlusu","ingilizce":"Towel on the sunbed","tanim":"Bazı işletmelerde plaj havlusunun sahildeki ya da havuz kenarındaki şezlongların üzerine önceden serilmesi uygulamasıdır.","ornek":"Sabah 09.00’da plaj görevlisi Murat, şezlongların üzerine temiz plaj havlularını serer; plaja inen konuklar havlu sırası beklemeden yerlerine yerleşir.","sektor":"Konuk havlu için sıra beklemez; bu uygulama kart ve stand sistemine alternatif bir hizmettir.","iliskili":["kh1-3-170","kh1-3-171"],"kontrol":null,"gorsel":"t12s-sezlong-havlu"},{"id":"kh1-3-174","konu":"3.3.2","terim":"Pamuk","ingilizce":"Cotton","tanim":"Havlu üretiminde en çok tercih edilen, dayanıklı ve ekonomik temel malzemedir.","ornek":"Satın alma sorumlusu, yeni sezon için pamuk havlu siparişi vermeyi seçer; çünkü bu havlular sık yıkanır.","sektor":"Pamuk uzun süre kullanıma, yüksek ısıda yıkamaya ve ütülemeye uygun olduğundan otellerde havlu ve mefruşat ürünlerinde yaygın tercih edilir.","iliskili":["kh1-3-175","kh1-3-177","kh1-3-160"],"kontrol":null,"gorsel":"t10c-pamuk"},{"id":"kh1-3-175","konu":"3.3.2","terim":"Bambu elyafı","ingilizce":"Bamboo fibre","tanim":"Lifi bambu bitkisinin dilimlenip işlenmesiyle elde edilen, yumuşak yapılı ve havlu üretiminde pamukla karıştırılarak kullanılan liftir.","ornek":"Bir butik otel, konuklara yumuşak bir deneyim sunmak için pamukla karışık bambu havlular kullanır.","sektor":"Ders materyaline göre bambu bitkisi yetiştirilirken kimyasal kullanılmadığından çevre dostu sayılır; ancak elyafa dönüştürülürken kullanılan maddeler yüzünden elyaf organik değildir. Pamuktan daha gözenekli olduğu için ıslaklığı çabuk ve çok çeker; alerji yapmayan ve antibakteriyel olduğu söylenir, maliyeti pamuğa göre yüksektir.","iliskili":["kh1-3-174","kh1-3-176"],"kontrol":null},{"id":"kh1-3-176","konu":"3.3.2","terim":"Modal","ingilizce":"Modal","tanim":"Kayın ağacının selülozundan üretilen, nem tutma oranı yüksek ve yıpranmaya dayanıklı bir lif türüdür.","ornek":"Bir otelin SPA bölümü, bornoz ve peştamalları için modal lifli ürünleri tercih eder.","sektor":"Nemli ve rutubetli ortamlarda sık kullanıldığı için konaklama işletmelerinde çoğunlukla SPA, hamam ve sauna bölümlerinde havlu, bornoz ve peştamal olarak yer alır.","iliskili":["kh1-3-177","kh1-3-175","kh1-3-155"],"kontrol":null},{"id":"kh1-3-177","konu":"3.3.2","terim":"Keten","ingilizce":"Linen","tanim":"Lifleri keten bitkisinin gövdesinden elde edilen, nemi iyi çeken ve çabuk kuruyan doğal bir kumaş türüdür.","ornek":"Konuk, SPA’dan çıkarken kendisine verilen keten peştamalla vücudunu kurular; keten nemi iyi çeker ve çamaşırhanede kısa sürede kurur.","sektor":"Ders materyaline göre doğal yapısı nedeniyle alerji yapmaz, nem çekme gücü yüksektir ve kolay kurur; SPA, hamam ve sauna bölümlerinde havlu, bornoz ve peştamal olarak kullanılır.","iliskili":["kh1-3-176","kh1-3-155","kh1-3-174"],"kontrol":null,"gorsel":"t11c-keten"},{"id":"kh1-3-178","konu":"3.3.3","terim":"Origami","ingilizce":"Origami","tanim":"Japonca “oru” (katlamak) ve “kami” (kâğıt) sözcüklerinden gelen, bir malzemeyi araç kullanmadan yalnızca katlayarak şekillendirme sanatıdır.","ornek":"Öğretmen sınıfta önce bir kâğıt kuş katlar, sonra aynı mantıkla havlunun da şekle girebileceğini gösterir.","sektor":"Otellerde origami, konuk odalarında şık bir görüntü sağlamak için havluların farklı figürlere dönüştürülmesinde kullanılır.","iliskili":["kh1-3-179","kh1-3-180"],"kontrol":null,"gorsel":"t10c-origami"},{"id":"kh1-3-179","konu":"3.3.3","terim":"Havlu figürleri","ingilizce":"Towel art / towel animals","tanim":"Havluların katlanarak hayvan ya da geometrik şekle dönüştürülmesiyle konuk odasında oluşturulan süslemelerdir.","ornek":"Oda görevlisi Ayşe, çift kişilik odanın yatağının üzerine havludan iki fil figürü yerleştirir; odaya giren konuk yatakta onu karşılayan figürü fotoğraflar.","sektor":"Figürler çoğunlukla hayvanlardan ve geometrik şekillerden oluşur; konuğa özenle karşılandığını hissettirir ve personelin yaratıcılığıyla çeşitlendirilebilir.","iliskili":["kh1-3-178","kh1-3-191","kh1-3-181"],"kontrol":null,"gorsel":"t10c-havlu-figur"},{"id":"kh1-3-180","konu":"3.3.3","terim":"Figürde doğru katlama","ingilizce":"Precise folding","tanim":"Figürün şeklinin belirgin görünmesi için her katın düzgün, eşit ve sıkı yapılmasıdır.","ornek":"Kuğunun boynunu katlarken Mert, iki yan kenarı eşit tutmak için havluyu avucuyla düzeltir; kıvrım düzgün olunca boyun dik durur.","sektor":"Eğri ya da gevşek katlanmış figür dağılır veya ne olduğu anlaşılmaz; düzgün figür otelin özenini gösterir.","iliskili":["kh1-3-178","kh1-3-183"],"kontrol":null,"gorsel":"t10c-havlu-cicek"},{"id":"kh1-3-181","konu":"3.3.3","terim":"Figürü çeşitlendirme","ingilizce":"Customising the figure","tanim":"Temel katlama düzenini bozmadan figürün göz, kurdele, çiçek gibi eklerle personelin yaratıcılığıyla farklılaştırılmasıdır.","ornek":"Ayşe, aynı kuğu figürünü bir odada çiçekle, diğerinde kurdeleyle süsleyerek farklı gösterir.","sektor":"Figürler personelin yaratıcılığı ve el becerisiyle çeşitlendirilebilir; ancak temel katlama sırası değiştirilmez.","iliskili":["kh1-3-179","kh1-3-186"],"kontrol":null,"gorsel":"t11c-figur-cicek"},{"id":"kh1-3-182","konu":"3.3.3","terim":"Figürde temiz havlu kullanma","ingilizce":"Using clean towels","tanim":"Havlu figürlerinin yalnızca yıpranmamış, lekesiz ve temiz havlularla yapılmasıdır.","ornek":"Oda görevlisi Selin, kuğu için aldığı havlunun köşesinde leke görünce onu ayırır ve temiz bir havlu alır.","sektor":"Konuk figürü yatağın üzerinde ilk görür; lekeli ya da solmuş havlu en güzel katlamayı bile gölgeler.","iliskili":["kh1-3-179","kh1-3-180"],"kontrol":null,"kitapDisi":true},{"id":"kh1-3-183","konu":"3.3.3","terim":"Rulo katlama","ingilizce":"Rolling fold","tanim":"Havlunun bir kenarından başlayarak sıkıca ve eşit şekilde sarılmasıyla yapılan katlama tekniğidir.","ornek":"Kaplumbağa figürüne başlarken oda görevlisi banyo havlusunu serip kısa kenarından rulo yapar.","sektor":"Köpek, yengeç, kaplumbağa gibi figürlerde gövde ve ayaklar rulo katlamayla oluşur; iki rulonun eşit olması şeklin dengesini belirler.","iliskili":["kh1-3-184","kh1-3-185","kh1-3-180"],"kontrol":null,"gorsel":"t10c-rulo-havlu"},{"id":"kh1-3-184","konu":"3.3.3","terim":"Akordiyon katlama","ingilizce":"Accordion fold (concertina fold)","tanim":"Havlunun belirli aralıklarla ileri geri kıvrılarak körük gibi katlanmasıdır.","ornek":"Kuğu figürünün kuyruğunu yapan Elif, baş havlusunu düz bir zemine serip akordiyon gibi katlar.","sektor":"Kuğunun kuyruğu gibi dalgalı ve kabarık görünmesi istenen kısımlarda kullanılır.","iliskili":["kh1-3-183","kh1-3-191"],"kontrol":null,"gorsel":"t11c-akordiyon"},{"id":"kh1-3-185","konu":"3.3.3","terim":"Havluyu dışa doğru çevirme","ingilizce":"Turning the rolls outwards","tanim":"Rulo yapılmış havlunun uçlarından tutularak içten dışa doğru çevrilmesiyle gövde ve ayak şeklinin ortaya çıkarılmasıdır.","ornek":"Yengeç figüründe oda görevlisi iki ruloyu uçlarından parmaklarıyla tutar ve dışa doğru çevirir.","sektor":"Yengeç, köpek ve kaplumbağa figürlerinin gövdesi ve ayakları bu çevirmeyle oluşur.","iliskili":["kh1-3-183","kh1-3-197","kh1-3-198"],"kontrol":null},{"id":"kh1-3-186","konu":"3.3.3","terim":"Havlu figürü süsleme malzemeleri","ingilizce":"Decorative materials","tanim":"Figürü daha belirgin ve canlı kılmak için kullanılan keçe, oynar göz, kurdele, yapay çiçek gibi küçük malzemelerdir.","ornek":"Kat arabasında figür yapımı için küçük bir kutuda keçe parçaları, oynar gözler ve kurdele hazır bulunur.","sektor":"Kullanılacak süsleme malzemeleri figürün türüne göre değişir ve kat arabasına yerleştirilmeden önce listeden kontrol edilir.","iliskili":["kh1-3-187","kh1-3-188","kh1-3-189"],"kontrol":null,"gorsel":"t11c-figur-susleme"},{"id":"kh1-3-187","konu":"3.3.3","terim":"Oynar göz ve keçe göz","ingilizce":"Googly eyes and felt eyes","tanim":"Havlu hayvan figürlerine canlı bir ifade vermek için takılan, hazır oynar ya da keçeden kesilmiş gözlerdir.","ornek":"Fil figürüne göz takarken Ayşe önce iki oynar gözü yerine oturtup sabitler; gözler simetrik durunca fil yatakta canlı görünür.","sektor":"Göz takılan figür yatağın üzerinde bir karakter gibi görünür ve konuğu gülümsetir.","iliskili":["kh1-3-186","kh1-3-195"],"kontrol":null},{"id":"kh1-3-188","konu":"3.3.3","terim":"Kurdele","ingilizce":"Ribbon","tanim":"Hediye paketi ve sepet gibi figürleri bağlamak ve süslemek için kullanılan şerittir.","ornek":"Oda görevlisi, hediye paketi figürünün ruloları arasından kurdeleyi geçirip bir fiyonk yapar; paket dağılmadan yatağın ortasında durur.","sektor":"Kurdele figürün dağılmasını önleyen bağlayıcı bir malzeme olduğu kadar süslemenin de parçasıdır.","iliskili":["kh1-3-186","kh1-3-194","kh1-3-192"],"kontrol":null,"gorsel":"t15ad-kurdele"},{"id":"kh1-3-189","konu":"3.3.3","terim":"Canlı ve yapay çiçek","ingilizce":"Fresh and artificial flowers","tanim":"Kuğu ve fil gibi figürlerin üzerini süslemek için kullanılan gerçek ya da yapay çiçeklerdir.","ornek":"Balayı odasında Selin, kuğunun kuyruğuna ince bir yapay gül yerleştirir; yapay çiçek bakım istemediği için figür gün boyu aynı güzellikte kalır.","sektor":"Canlı çiçek daha kısa ömürlüdür ve kuruduğunda değiştirilmesi gerekir; yapay çiçek bakım gerektirmez.","iliskili":["kh1-3-186","kh1-3-191"],"kontrol":null,"gorsel":"t10c-yapay-cicek"},{"id":"kh1-3-190","konu":"3.3.3","terim":"Papyon ve fiyonk","ingilizce":"Bow tie and bow","tanim":"Köpek ve fil gibi figürlerin üzerine takılan, süsleme amaçlı küçük kurdele ya da kumaş bağdır.","ornek":"Kat şefi Hülya’nın isteğiyle görevli Cem, köpek figürünün boynuna küçük, kırmızı kumaştan bir papyon takar; papyon figürü şirin gösterir.","sektor":"Papyon figüre karakter katar; çok büyük ya da ağır bir parça figürün dengesini bozabilir.","iliskili":["kh1-3-186","kh1-3-196"],"kontrol":null,"gorsel":"t10c-papyon"},{"id":"kh1-3-191","konu":"3.3.3","terim":"Kuğu figürü","ingilizce":"Towel swan","tanim":"Havlunun üçgen forma getirilip boynunun kıvrılmasıyla yapılan, çoğunlukla balayı odalarında kullanılan figürdür.","ornek":"Balayı çiftinin gelişinden önce oda görevlisi Selin, yatağın üzerine birbirine gagalarından bağlı iki kuğu yerleştirir.","sektor":"Ders materyaline göre konaklama işletmelerinde en çok kullanılan figürdür; balayı odalarının tamamlayıcı süsüdür. İki kuğunun gagaları birleştirilerek kalp şekli oluşur. Kuğu çifti için iki banyo ve bir baş havlusu kullanılır; baş havlusu akordiyon katlanarak kuyruk olur, canlı ya da yapay çiçekle süslenebilir.","iliskili":["kh1-3-184","kh1-3-189","kh1-3-183"],"kontrol":null,"gorsel":"t10c-kugu"},{"id":"kh1-3-192","konu":"3.3.3","terim":"Sepet figürü","ingilizce":"Towel basket","tanim":"Banyo ve baş havlularının rulo yapılıp kurdeleyle bağlanmasıyla oluşturulan, içine buklet malzemeleri konabilen figürdür.","ornek":"Oda görevlisi, sepet figürünün içine sabun ve şampuan gibi buklet malzemelerini yerleştirir ve yatağın ayak ucuna bırakır.","sektor":"İsteğe bağlı olarak içine buklet malzemeleri konur; iki baş ve iki banyo havlusuyla kurdele gerekir.","iliskili":["kh1-3-188","kh1-3-163","kh1-3-183"],"kontrol":null},{"id":"kh1-3-193","konu":"3.3.3","terim":"Gömlek figürü","ingilizce":"Towel shirt","tanim":"Banyo havlusunun uzun kenarlarının içe doğru katlanıp köşelerinin geriye çevrilmesiyle gömlek şekli verildiği figürdür.","ornek":"Oda görevlisi Elif, banyo havlusundan gömlek yapıp yakasına bir keçe düğme takar.","sektor":"Yalnız bir banyo havlusu gerektirir; çift kişilik odalar için iki banyo havlusuna da uygulanır. Katlarken uçlarda pay bırakılmasına dikkat edilir.","iliskili":["kh1-3-186","kh1-3-166"],"kontrol":null},{"id":"kh1-3-194","konu":"3.3.3","terim":"Hediye paketi figürü","ingilizce":"Towel gift box","tanim":"Banyo ve baş havlularının ayrı ayrı rulo yapılıp kurdeleyle bağlanması ve üst üste yerleştirilmesiyle oluşan figürdür.","ornek":"Yıl dönümünü kutlayan çiftin odasında oda görevlisi hediye paketi figürünü yatağın ortasına yerleştirir.","sektor":"Özellikle çift kişilik odalar için yapılır; iki baş, iki banyo havlusu ve kurdele gerekir.","iliskili":["kh1-3-188","kh1-3-183","kh1-3-192"],"kontrol":null,"gorsel":"t15ad-havlu-kurdele"},{"id":"kh1-3-195","konu":"3.3.3","terim":"Fil figürü","ingilizce":"Towel elephant","tanim":"Banyo havlusundan gövde ve ayakları, baş havlusundan başı oluşturulan figürdür.","ornek":"Ayşe, banyo havlusunun iki ucunu sararak fil ayaklarını yapar, baş havlusunu ters çevirip gövdenin önüne koyar.","sektor":"Oda düzenlenirken kullanılır; bir banyo ve bir baş havlusu gerekir. Figür çiçek, göz, fiyonk ya da kurdeleyle süslenebilir ve çift olarak yatağa konur.","iliskili":["kh1-3-187","kh1-3-190","kh1-3-189"],"kontrol":null,"gorsel":"t11c-fil-figuru"},{"id":"kh1-3-196","konu":"3.3.3","terim":"Köpek figürü","ingilizce":"Towel dog","tanim":"Banyo havlusunun iki kısa kenarından rulolar yapılıp dışa çevrilmesiyle oluşan gövdeye, baş havlusundan yapılan başın yerleştirildiği figürdür.","ornek":"Çocuklu bir aileyi karşılayan Selin, yatağa iki küçük köpek figürü bırakır; çocuklar odaya girer girmez figürlere gülümser.","sektor":"Otellerde sıkça kullanılır; isteğe bağlı olarak yapay ya da canlı çiçek, göz ve papyon eklenir.","iliskili":["kh1-3-190","kh1-3-183","kh1-3-185"],"kontrol":null},{"id":"kh1-3-197","konu":"3.3.3","terim":"Yengeç figürü","ingilizce":"Towel crab","tanim":"Banyo havlusunun rulolanıp dışa çevrilmesiyle oluşan gövdeye, üçe katlanan baş havlusunun kafa olarak sarıldığı figürdür.","ornek":"Deniz kenarındaki otelde oda görevlisi, yengeç figürüne keçeden göz ve ağız yapıştırır.","sektor":"Bir banyo ve bir baş havlusu gerekir; kenarlar gövdenin altına katlanır ve ayaklar düzeltilir.","iliskili":["kh1-3-183","kh1-3-185","kh1-3-187"],"kontrol":null,"gorsel":"t12c-havlu-yengec"},{"id":"kh1-3-198","konu":"3.3.3","terim":"Kaplumbağa figürü","ingilizce":"Towel turtle","tanim":"İki banyo havlusundan ayaklar ve kabuk, bir baş havlusundan baş yapılarak oluşturulan figürdür.","ornek":"Ayşe, kaplumbağanın kabuğunu oluşturmak için ikinci banyo havlusunun dört ucunu ortada birleştirir.","sektor":"İki banyo ve bir baş havlusu gerekir; kafa ayakların altına yerleştirilir, göz keçe ya da düğmeden yapılır.","iliskili":["kh1-3-183","kh1-3-185","kh1-3-187"],"kontrol":null,"gorsel":"t12c-havlu-kaplumbaga"},{"id":"kh1-3-199","konu":"3.3.3","terim":"Figür çalışması öncesi kişisel hazırlık","ingilizce":"Personal preparation before towel art","tanim":"Havlu figürü yapmadan önce kişisel bakım ve hijyen kurallarının uygulanması, takıların çıkarılması, formanın giyilmesi ve isimliğin takılmasıdır.","ornek":"Vardiyaya başlayan Mert, ellerini yıkar, bileğindeki saati ve yüzüğünü çıkarır, formasını giyip isimliğini takar.","sektor":"Uygulama yapraklarında bu adımlar her figürün başında yinelenir; temiz ve düzenli personel, temiz bir figürün ilk şartıdır.","iliskili":["kh1-3-200","kh1-3-182"],"kontrol":null},{"id":"kh1-3-200","konu":"3.3.3","terim":"Figür malzeme listesi kontrolü","ingilizce":"Checking the materials list","tanim":"Figüre başlamadan önce iş programı, oda durum raporu, anahtar ve kat arabasının ardından gerekli havlu ve süsleme malzemelerinin listeye göre eksiksiz alınmasıdır.","ornek":"Elif, kuğu figürü için kat arabasına yeterli sayıda banyo havlusu, baş havlusu ve yapay çiçek koyar; listede eksik kalan bir şey olup olmadığına bakar.","sektor":"Eksik malzemeyle odaya gitmek zaman kaybettirir; liste figürün bir kez doğru yapılmasını sağlar.","iliskili":["kh1-3-199","kh1-3-186"],"kontrol":null},{"id":"kh1-3-201","konu":"3.3.3","terim":"Figürleri çift hazırlama","ingilizce":"Preparing figures in pairs","tanim":"Yatağın üzerine, bir çift olarak aynı türden iki figürün yerleştirilmesidir.","ornek":"Fil figürünü bitiren Ayşe, aynı işlemi ikinci banyo ve baş havlusuyla yapıp iki fili yan yana koyar.","sektor":"Gömlek figüründe uygulama iki banyo havlusuna da yapılır; filde figürler çift olarak yatağa yerleştirilir.","iliskili":["kh1-3-195","kh1-3-193","kh1-3-202"],"kontrol":null,"gorsel":"f3c-havlu-kuguler"},{"id":"kh1-3-202","konu":"3.3.3","terim":"Figürün yatağa yerleştirilmesi","ingilizce":"Placing the figure on the bed","tanim":"Tamamlanan figürün konuk yatağının üzerinde, dengede duracağı ve konuğun göreceği şekilde bırakılmasıdır.","ornek":"Oda görevlisi Selin, bitirdiği köpek figürlerini yatağın orta bölümüne, birbirine bakar şekilde yerleştirir.","sektor":"Figür yatağın üzerine konulunca oda bitmiş sayılır; dağınık bırakılan figür tüm emeğin etkisini azaltır.","iliskili":["kh1-3-201","kh1-3-199"],"kontrol":null,"gorsel":"t10c-figur-yatakta"},{"id":"kh1-3-203","konu":"3.3.3","terim":"Figür yapım süresi","ingilizce":"Time allowed for towel art","tanim":"Havlu figürü uygulamasında hedeflenen, ders materyalinde on dakika olarak verilen çalışma süresidir.","ornek":"Atölye dersinde öğretmen kronometreyi başlatır; öğrenciler kuğu figürünü on dakika içinde bitirmeye çalışır.","sektor":"Süre, atölyede “zamanı kullanma” ölçütüyle değerlendirilir; hızlı olmak kadar figürü düzgün bitirmek de önemlidir.","iliskili":["kh1-3-204","kh1-3-199"],"kontrol":null},{"id":"kh1-3-204","konu":"3.3.3","terim":"Figür uygulaması değerlendirme ölçütleri","ingilizce":"Assessment criteria for towel art","tanim":"Uygulamanın iş için hazırlık, uygulama, zamanı kullanma, iletişim ve olağan dışı durumlara hazır bulunuşluk ölçütlerine göre puanlanmasıdır.","ornek":"Öğretmen, Mert’in figürünü beş ölçüte göre değerlendirir ve her biri için ayrı puan verir.","sektor":"Bu ölçütler iyi bir oda görevlisinde de aranır: işe hazır gelmek, doğru ve zamanında iş yapmak, iletişim kurmak, beklenmedik durumlarda çözüm bulmak.","iliskili":["kh1-3-203","kh1-3-199"],"kontrol":null,"gorsel":"t12s-havlu-kugu"}],"sorular":[{"id":"kh1-3-s001","tur":"coktan-secmeli","soru":"Kat şefi, yatak yapımının özenle yapılmasını ister. Bu isteğin asıl gerekçesi hangisidir?","secenekler":["Yatak yapımı, oda temizliğinin en uzun süren basamağıdır","Çarşafın kırışık olması çamaşırhaneye ek iş çıkarır","Konuk odaya girince önce yatağa bakar ve ilk izlenimini ondan alır","Yatak odadaki en pahalı mefruşat olduğundan hata cezalandırılır"],"dogru":2,"aciklama":"Konuk odada ilk olarak yatağa bakar; düzgün ve temiz yatak otel hakkındaki düşünceyi olumlu etkiler. Yatak yapımının uzun sürmesi ya da maliyeti asıl gerekçe değildir.","konu":"3.1"},{"id":"kh1-3-s002","tur":"coktan-secmeli","soru":"Satın alma sorumlusu yeni sezon için yatak örtüsü seti seçiyor. Mefruşat ölçütüne göre hangi seti seçmelidir?","secenekler":["Yalnızca ilk bakışta en gösterişli görünen, pahalı set","Her sezon kolayca değiştirilebilen, en ucuz ve ince set","Oda dekorasyonuna uyan, sık yıkanmaya dayanan, ekonomik set","Konukların evden getirdiği örtülere benzeyen, sade set"],"dogru":2,"aciklama":"Mefruşat dekorasyona uygun ve dayanıklı olmalıdır; ciddi bir gider kalemi olduğundan ekonomik olanı tercih edilir. Yalnızca görünüşe ya da en düşük fiyata bakmak bu ölçütleri karşılamaz.","konu":"3.1"},{"id":"kh1-3-s003","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi yatak takımının parçası sayılmaz?","secenekler":["Nevresim","Baza","Yastık kılıfı","Üst çarşaf"],"dogru":1,"aciklama":"Yatak takımı, yatağı hazırlamak için gereken tekstil parçalarının bütünüdür. Baza bir mobilya altlığıdır, tekstil parçası değildir.","konu":"3.1"},{"id":"kh1-3-s004","tur":"coktan-secmeli","soru":"Konaklama işletmelerinde ortopedik yaylı yataklar neden çoğunlukla tercih edilir?","secenekler":["Yıkanabildiği için çarşafsız da kullanılabilir","Her konuktan sonra kolayca değiştirilebilir","Baza gerektirmeden doğrudan yere konulabilir","Kullanımı kolaydır ve sık kullanımda dayanıklıdır"],"dogru":3,"aciklama":"Yaylı yatak kullanım kolaylığı ve dayanıklılığı nedeniyle tercih edilir. Konuk odalarındaki yataklar yıkanamaz; bu yüzden koruyucu gerekir.","konu":"3.1.1"},{"id":"kh1-3-s005","tur":"coktan-secmeli","soru":"Otellerde karyola yerine çoğunlukla baza kullanılmasının nedeni hangisidir?","secenekler":["Yatağın yaylarını daha esnek hâle getirir","Karyolaya göre her zaman daha ucuzdur","Temizliği ve kullanımı daha kolaydır","Yıkanabildiği için leke bırakmaz"],"dogru":2,"aciklama":"Baza temizliği ve kullanımı daha kolay olduğu için tercih edilir. Bazı işletmeler yine de mekâna uygun ahşap ya da metal karyola kullanır.","konu":"3.1.1"},{"id":"kh1-3-s006","tur":"coktan-secmeli","soru":"Küçük bir pansiyonda konuk valizini nereye koyacağını soruyor. Odadaki hangi donanım bu soruya çözüm olur?","secenekler":["Yatak koruyucu","Dekoratif şal","Çekyat","Sandıklı baza"],"dogru":3,"aciklama":"Sandıklı baza, yatağın altında eşya koymaya yarayan bir sandık bölümüne sahiptir ve küçük odalarda ek saklama alanı sağlar.","konu":"3.1.1"},{"id":"kh1-3-s007","tur":"dogru-yanlis","soru":"Baza, kaplanmamış çıplak metal bir karyolanın başka adıdır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Baza, ahşap ya da metal bir kasanın kumaş veya suni deriyle kaplanmasıyla yapılan altlıktır; kaplama onu ayırt eder.","konu":"3.1.1"},{"id":"kh1-3-s008","tur":"coktan-secmeli","soru":"Alt çarşaf yatakta hangi iki malzemenin arasında yer alır?","secenekler":["Yatak koruyucu ile üst çarşaf","Yatak ile yatak koruyucu","Üst çarşaf ile battaniye","Battaniye ile yatak örtüsü"],"dogru":0,"aciklama":"Sıra alttan üste doğrudur: koruyucu, alt çarşaf, üst çarşaf. Alt çarşaf koruyucunun üzerine, üst çarşafın altına gelir.","konu":"3.1.2"},{"id":"kh1-3-s009","tur":"coktan-secmeli","soru":"Üst çarşafın yastık tarafındaki payının daha geniş dikilmesinin yararı hangisidir?","secenekler":["Çarşafın yastığın altına sıkıştırılarak sabitlenmesini sağlar","Yastık kılıfının dışarıdan görünmesini engelleyerek düzgün durur","Battaniye üzerine katlanan pay, battaniyenin konuğa değmesini önler","Çarşafın yıkama sırasında küçülüp kısalmasını önlemeyi sağlar"],"dogru":2,"aciklama":"Geniş pay battaniyenin üzerine katlanır; böylece battaniye konuğa değmez ve düzgün kenar görünür. Pay yastık altına sıkıştırılmaz.","konu":"3.1.2"},{"id":"kh1-3-s010","tur":"dogru-yanlis","soru":"Kapak çarşafı, battaniyenin altına serilen ve yastık tarafı daha geniş dikilen çarşaftır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Bu tanım üst çarşafa aittir. Kapak çarşafı bazı işletmelerde dekorasyon için battaniyenin üzerine serilir.","konu":"3.1.2"},{"id":"kh1-3-s011","tur":"coktan-secmeli","soru":"Bir çocuk gece yatağa su döküyor. Yatak koruyucu (alez) sayesinde ertesi sabah ne görülür?","secenekler":["Su alt çarşafın altından yatağa yayılır ama kurur","Islaklık koruyucuda kalır, yatağa geçmez","Koruyucu suyu emer ve yatak kokusunu giderir","Yatak yıkanarak temizlenmek zorunda kalır"],"dogru":1,"aciklama":"Koruyucu sıvı geçirmez olduğu için leke ve ıslaklık onda kalır. Konuk odası yatakları yıkanamaz; bu yüzden koruma yatağın kendisinde değil, koruyucudadır.","konu":"3.1.2"},{"id":"kh1-3-s012","tur":"dogru-yanlis","soru":"Görevli Elif, alt çarşafı serdikten sonra yatak koruyucuyu çarşafın üzerine geçirmiştir. Bu sıra doğrudur.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yatak koruyucu alt çarşaftan önce, yatağın hemen üzerine serilir. Çarşafın üstüne geçirilirse sıvı ve leke çarşaftan geçip yatağa ulaşır; koruyucunun görevi kalmaz.","konu":"3.1.2"},{"id":"kh1-3-s013","tur":"coktan-secmeli","soru":"Yün ya da sentetik maddelerden dokunan, yorgan yerine ya da yorganın üzerine örtülen malzeme hangisidir?","secenekler":["Battaniye","Pike","Nevresim","Dekoratif şal"],"dogru":0,"aciklama":"Battaniye yün veya sentetik maddelerden yapılan dokuma örtüdür. Pike pamukludur ve yaz için kullanılır; nevresim yorgan kılıfıdır.","konu":"3.1.2"},{"id":"kh1-3-s014","tur":"coktan-secmeli","soru":"Otellerde pamuk ya da yün yerine elyaf yorganın tercih edilmesinin sebebi hangisidir?","secenekler":["Temizliği ve kullanımı daha kolaydır","Konuğu diğer yorganlardan daha çok ısıtır","Nevresim geçirilmesine gerek bırakmaz","Rengi odanın mefruşatına her zaman uyar"],"dogru":0,"aciklama":"Konaklama işletmelerinde temizlik ve kullanım kolaylığı nedeniyle elyaf yorgan tercih edilir. Elyaf yorgana da hijyen için nevresim geçirilir.","konu":"3.1.2"},{"id":"kh1-3-s015","tur":"coktan-secmeli","soru":"Aşağıdaki eşleştirmelerden hangisi yanlıştır?","secenekler":["Yorgan: kışın üşümeyi önlemek","Pike: yaz aylarında yorgan yerine örtülmek","Runner: tüm yatağı baştan sona kaplamak","Battaniye: serin havalarda üst çarşafın üzerine serilmek"],"dogru":2,"aciklama":"Runner yatak örtüsünden daha dar ve kısadır, yalnızca yatağın ayak ucuna serilir. Diğer üç eşleştirme kartlardaki bilgiyle uyuşur.","konu":"3.1.2"},{"id":"kh1-3-s016","tur":"coktan-secmeli","soru":"Konuğun kirletmemesi için yorganın dışına geçirilen, alt ucu açık dikdörtgen kılıf hangisidir?","secenekler":["Yatak koruyucu","Nevresim","Yastık kılıfı","Kapak çarşafı"],"dogru":1,"aciklama":"Nevresim yorganı kirlenmekten korur ve kolayca yıkanır. Yatak koruyucu yatağı, yastık kılıfı yastığı korur.","konu":"3.1.2"},{"id":"kh1-3-s017","tur":"coktan-secmeli","soru":"Temmuzda Bodrum’daki bir tatil otelinde kat şefi battaniye yerine hangisini hazırlatır?","secenekler":["Elyaf yorgan","Kapak çarşafı","Pike","Bebek battaniyesi"],"dogru":2,"aciklama":"İklimi sıcak olan tatil otellerinde pike çoğunlukla battaniye yerine kullanılır; yorgan ve battaniyeye göre hafiftir.","konu":"3.1.2"},{"id":"kh1-3-s018","tur":"coktan-secmeli","soru":"Yastıklara çoğunlukla iki kılıf geçirilmesinin amacı hangisidir?","secenekler":["Alttaki kılıf yastığı korur, üstteki kılıf odaya uyum sağlar","Alttaki kılıf konuğa görünür, üstteki kılıf yastığı korur","Üstteki kılıf yıkanır, alttaki kılıf süs olarak kalır","İki kılıf yastığı daha kabarık tutar"],"dogru":0,"aciklama":"Alttaki kılıf yastığı korur; üstteki kılıf oda dekorasyonuna uygun seçilir ve konuk için kullanılır. Görünen kılıf üsttekidir.","konu":"3.1.2"},{"id":"kh1-3-s019","tur":"coktan-secmeli","soru":"Hazırlanmış yatağın tamamını kaplayan, hem görünümü güzelleştiren hem kirlenmeyi önleyen malzeme hangisidir?","secenekler":["Runner","Yatak örtüsü","Nevresim","Dekoratif şal"],"dogru":1,"aciklama":"Yatak örtüsü tüm yatağı kaplar. Runner yalnızca ayak ucuna serilir; dekoratif şal ise yatak örtüsü yerine kullanılabilen süs örtüsüdür.","konu":"3.1.2"},{"id":"kh1-3-s020","tur":"coktan-secmeli","soru":"Görevli Murat tam yatak örtüsü yerine yalnızca yatağın ayak ucuna ince bir parça serecek. Hangi ürünü kullanır?","secenekler":["Yatak örtüsü","Runner","Pike","Kapak çarşafı"],"dogru":1,"aciklama":"Runner, eni yatak örtüsünden dar ve kısa olan, yalnızca ayak ucuna serilen mefruşat ürünüdür.","konu":"3.1.2"},{"id":"kh1-3-s021","tur":"dogru-yanlis","soru":"Bazı otellerde yatak örtüsü yerine runner ya da dekoratif şal kullanılır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Runner ve dekoratif şal, yatak örtüsüne alternatif olarak kullanılabilir; ikisi de odanın görünümünü değiştirir.","konu":"3.1.2"},{"id":"kh1-3-s022","tur":"coktan-secmeli","soru":"Görevli Selin, 3. kattaki odaların yatakları için kat arabasını hazırlıyor. Hangisi doğru uygulamadır?","secenekler":["Arabaya yalnızca kirli sepetini koyup eksikleri depodan tek tek almak","Tekstili odaya girince yatağın üzerinde toplamak","Yarım yükle çıkıp eksik parçayı kat şefinden istemek","Tekstili odaların ihtiyacına göre işe başlamadan arabaya eksiksiz dizmek"],"dogru":3,"aciklama":"Eksik malzeme yüzünden odadan çıkıp depoya yürümek zaman kaybettirir ve odanın geç hazırlanmasına yol açar; bu nedenle her şey önceden arabaya konur.","konu":"3.1.2"},{"id":"kh1-3-s023","tur":"coktan-secmeli","soru":"Görevli Murat listesine bakmadan odalara çıkıyor ve dördüncü odada yastık kılıfı eksik çıkıyor. Bunun doğrudan sonucu ne olur?","secenekler":["Kat şefi gelip odanın yatağını baştan yeniden yapar","Eksik kılıf konuktan ödünç istenir ve iş sürdürülür","Odanın oda durum raporu geçersiz sayılır ve yenilenir","İş yarıda kalır ve eksik parça için odadan çıkılır"],"dogru":3,"aciklama":"Malzeme ihtiyaç listesi işe başlamadan kontrol edilirse oda yarıda bırakılmaz ve konuk eksik malzeme beklemez.","konu":"3.1.2"},{"id":"kh1-3-s024","tur":"coktan-secmeli","soru":"İki görevli aynı yatağı farklı sırayla yapıyor. Kat şefine göre doğru olan hangisidir?","secenekler":["Daha çabuk biten","Görevlinin alışkın olduğu","İşletmenin yatak yapım prosedürüne uyan","Konuğun daha çok beğeneceği düşünülen"],"dogru":2,"aciklama":"Kat hizmetleri görevlileri yatak yapımında işletmeye ait prosedürü izler; böylece her odada aynı standart bulunur.","konu":"3.2"},{"id":"kh1-3-s025","tur":"coktan-secmeli","soru":"Yatak yapımında malzemelerin alttan üste doğru serilme düzeni aşağıdakilerden hangisidir?","secenekler":["Alt çarşaf – koruyucu – üst çarşaf – battaniye","Koruyucu – alt çarşaf – battaniye – üst çarşaf","Koruyucu – alt çarşaf – üst çarşaf – battaniye","Koruyucu – üst çarşaf – alt çarşaf – battaniye"],"dogru":2,"aciklama":"Malzemeler alttan üste doğru serilir: koruyucu yatağa, alt çarşaf koruyucuya, üst çarşaf alt çarşafa, battaniye de üst çarşafa gelir. Koruyucu alt çarşafın altında olmazsa leke ve ıslaklık yatağa geçer; üst çarşaf battaniyenin altına serilir ki battaniye konuğa değmesin.","konu":"3.2"},{"id":"kh1-3-s026","tur":"coktan-secmeli","soru":"Gün sonunda görevli Murat pas anahtarı ve oda durum raporuyla kat ofisine dönüyor. Pas anahtarını nasıl teslim eder?","secenekler":["Anahtarı kutusuna bırakıp kat şefine sonradan sözlü haber vererek","Ertesi sabah yeniden kullanılmak üzere kat arabasında bırakarak","Resepsiyona kısa bir sözlü bilgi vererek teslim edilmiş sayarak","Kat şefine ya da görevli personele, imzayla ve tarih saatle birlikte"],"dogru":3,"aciklama":"Pas anahtarı imza karşılığı alınır ve iş bitince yine imza karşılığı teslim edilir; tarih ve saat sorumluluğun kimde olduğunu gösterir.","konu":"3.2"},{"id":"kh1-3-s027","tur":"coktan-secmeli","soru":"Çıkış yapan konuğun odasında toplanan çarşaf ve kılıflar nereye bırakılır?","secenekler":["Odadaki koltuğun üzerine","Temiz tekstilin bulunduğu kat arabası rafına","Kat arabasındaki kirli çamaşır sepetine","Koridordaki geçici bir yığına"],"dogru":2,"aciklama":"Kirli takımlar kat arabasındaki kirli çamaşır sepetine konur. Koltuk, battaniye gibi malzemenin havalanması içindir; temiz-kirli ayrımı korunur.","konu":"3.2.1"},{"id":"kh1-3-s028","tur":"coktan-secmeli","soru":"Yatak çarşafları toplanırken hangi yöntem doğrudur?","secenekler":["Ortasından tutulup silkelenerek","Yatağın ayak ucundan yuvarlanarak","Köşelerinden tutulup birleştirilerek","Yatağın üzerinde düzgünce katlanarak"],"dogru":2,"aciklama":"Çarşaflar köşelerinden birleştirilerek toplanır ve kirli çamaşır sepetine konur. Silkelemek kirli takımın toz ve mikroplarını odaya yayar; yatağın üzerinde katlamak da kirli çarşafı yatağa temas ettirip dağıtır.","konu":"3.2.1"},{"id":"kh1-3-s029","tur":"coktan-secmeli","soru":"Yastık kılıfı hangi biçimde çıkarılır?","secenekler":["Yastık yatağa birkaç kez vurularak ve sarsılarak","Yastığın tam ortasından tutulup kılıf aşağı çekilerek","Kılıfın ağzı yastığın üstüne kıvrılıp yastık çıkarılarak","Kapak kısmı açılıp yastığın köşelerinden tutularak"],"dogru":3,"aciklama":"Kılıfın kapak kısmı açılır ve yastığın köşelerinden tutularak çıkarılır; bu yastığın şeklini bozmaz.","konu":"3.2.1"},{"id":"kh1-3-s030","tur":"coktan-secmeli","soru":"Toplanan çarşaflardan birinde belirgin bir leke varsa nasıl işlem yapılır?","secenekler":["Odada nemli bezle silinip aynı yatakta yeniden kullanılır","Diğer çarşaflarla aynı sepete konup ayrıca işaretlenmez","Kat arabasının rafında ayrı bir yerde bekletilir","Diğerlerinden ayrılıp çamaşırhaneye ayrıca gönderilir"],"dogru":3,"aciklama":"Lekeli parçalar diğerlerinden ayrılarak çamaşırhaneye gönderilir; böylece çamaşırhane onlara ayrıca bakabilir.","konu":"3.2.1"},{"id":"kh1-3-s031","tur":"coktan-secmeli","soru":"Konuk hâlâ otelde kalırken çarşafın arasından bir kol saati çıkarsa ne yapılır?","secenekler":["Konuğun göreceği şekilde komodinin üzerine bırakılır","Resepsiyona kayıt tutularak hemen teslim edilir","Kat şefinin dolabında kayıt altında saklanır","Kirli sepetiyle birlikte çamaşırhaneye gönderilir"],"dogru":0,"aciklama":"Konuk işletmede kalıyorsa eşya görülebilir yere bırakılır. Resepsiyona teslim, konuk işletmeden ayrılmışsa yapılır.","konu":"3.2.1"},{"id":"kh1-3-s032","tur":"coktan-secmeli","soru":"Görevli, toplanan çarşafları sepete koymadan önce arasında konuk eşyası olup olmadığına bakar. Bu kontrolün asıl yararı hangisidir?","secenekler":["Çarşafların çamaşırhanede daha hızlı yıkanması","Eşyanın kaybolmaması ve sorumluluğun net kalması","Yatağın daha kısa sürede yeniden yapılması","Lekeli takımların diğerlerinden ayrılması"],"dogru":1,"aciklama":"Kirli takım çamaşırhaneye gitmeden eşya aranırsa konuğun eşyası kaybolmaz ve eşyadan kimin sorumlu olduğu belli kalır. Kontrol, yıkama hızını ya da yatak yapım süresini değiştirmez; lekeli parçaların ayrılması ise ayrı bir işlemdir.","konu":"3.2.1"},{"id":"kh1-3-s033","tur":"coktan-secmeli","soru":"Yatak toplanırken çıkarılan battaniye ve yastık nereye alınır?","secenekler":["Kirli sepetinin içine, çarşaf ve kılıfların arasına","Odadaki koltuk ya da sandalye gibi temiz bir yere","Yatağın altındaki baza ya da sandık bölümüne","Banyodaki sehpanın ya da küvetin kenarına"],"dogru":1,"aciklama":"Çıkarılan malzeme yere değmeden temiz bir yerde bekler; yatak da açıkken havalanır.","konu":"3.2.1"},{"id":"kh1-3-s034","tur":"coktan-secmeli","soru":"Yatak yapımına başlarken yatak koruyucuda leke görülüyorsa ne yapılır?","secenekler":["Üzerine temiz alt çarşaf serilip olduğu gibi bırakılır","Ters çevrilip temiz yüzü üstte kalacak şekilde takılır","Nemli bezle silinip yatağın üzerinde yerinde bırakılır","Köşe lastiklerinden çıkarılıp kirliler arasına konur"],"dogru":3,"aciklama":"Kirli koruyucu temiz çarşafın altında kalırsa koku ve hijyen sorunu yaratır; bu yüzden çıkarılıp toplanır.","konu":"3.2.2"},{"id":"kh1-3-s035","tur":"dogru-yanlis","soru":"Temiz yatak koruyucu yere serilerek köşe lastikleri geçirilir, sonra yatağın üzerine kaldırılır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Temiz koruyucu yatağa serilir ve köşe lastikleri geçirme işlemi yatağın üzerinde yapılır; böylece koruyucu yere değmez.","konu":"3.2.2"},{"id":"kh1-3-s036","tur":"coktan-secmeli","soru":"Koruyucu çıkarılınca yatakta ya da bazada leke görülürse ilk yapılacak işlem hangisidir?","secenekler":["Lekeli yüzeyin çarşafla örtülmesi","Yatağın ters çevrilerek kullanılması","Yeni koruyucu serilip beklenmesi","Lekenin nemli bezle hemen silinmesi"],"dogru":3,"aciklama":"Yatak ve bazanın kirli olup olmadığı kontrol edilir; leke varsa silinir, sonra temiz koruyucu takılır.","konu":"3.2.2"},{"id":"kh1-3-s037","tur":"coktan-secmeli","soru":"Koruyucuyu takmadan önce köşe lastiklerini elle germenin amacı hangisidir?","secenekler":["Kopuk ya da gevşek lastiği fark edip kaymayı önlemek","Koruyucunun ölçüsünü yatağın boyutuna tam uydurmak","Köşelerde buruşan kısımları önceden elle düzeltmek","Lastiğin sıvı geçirmezliğini önceden elle denemek"],"dogru":0,"aciklama":"Lastiği gevşek koruyucu yatak üzerinde kayar ve çarşafın düzgün durmasını engeller; bu yüzden sağlamlık kontrol edilir.","konu":"3.2.2"},{"id":"kh1-3-s038","tur":"coktan-secmeli","soru":"Alt çarşafı yatağın iki yanına eşit sarkıtmak için ilk adım hangisidir?","secenekler":["Çarşafı yatağın bir yanına çekmek","Orta kat çizgisini yatağın ortasına getirmek","Köşeleri önce yatağın altına sıkıştırmak","Çarşafı ayak ucundan başlayarak yaymak"],"dogru":1,"aciklama":"Orta kat çizgisi yatağın ortasına getirilir, sonra çarşaf iki yana açılır; çizgi kayarsa çarşaf bir yana fazla sarkar.","konu":"3.2.3"},{"id":"kh1-3-s039","tur":"coktan-secmeli","soru":"Alt çarşafın köşeleri nereden başlanarak ve nasıl katlanır?","secenekler":["Ayak ucundan başlanarak üçgen biçiminde","Yatağın ortasından başlanarak düz bastırılarak","Yatak başından başlanarak zarf biçiminde","Ayak ucundan başlanarak doğrudan altına itilerek"],"dogru":2,"aciklama":"Köşeler yatak başından başlanarak zarf biçiminde katlanır; zarf köşe çarşafın kaymasını önler.","konu":"3.2.3"},{"id":"kh1-3-s040","tur":"dogru-yanlis","soru":"Zarf köşe yapılırken görevli köşenin yan tarafında durup yatağı hiç kaldırmadan çarşafı yatağın altına itebilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Sarkan çarşaf, yatak kaldırılarak yatağın altına yerleştirilir ve köşe öne getirilip sıkıştırılır; görevli de kolları rahat çalışsın diye köşenin önünde durur.","konu":"3.2.3"},{"id":"kh1-3-s041","tur":"coktan-secmeli","soru":"Yatak kenarından sarkan çarşaf nasıl yerleştirilir?","secenekler":["Ayak ucundan çekilip yatağa sıkıştırılır","Kenarı yatak başlığına bir iple bağlanır","Yatak kaldırılıp çarşaf altına yerleştirilir","Sarkık bırakılıp üzeri yastıkla bastırılır"],"dogru":2,"aciklama":"Sarkan çarşaf, yatak kaldırılarak yatağın altına yerleştirilir; sıkı yerleşen köşe gün boyunca yerinde kalır.","konu":"3.2.3"},{"id":"kh1-3-s042","tur":"coktan-secmeli","soru":"Üst çarşaf serilirken yatak başında pay bırakılmasının amacı hangisidir?","secenekler":["Çarşafın ucunu yastığın altına sokup sabitlemek","Alt çarşafın başucu kenarını örterek paketlemek","Yastık kılıfının açık ucunu görünmeyecek biçimde gizlemek","Payı battaniyenin üzerine katlayıp düzgün kenar sağlamak"],"dogru":3,"aciklama":"Üst çarşaf yatak başından pay bırakılarak serilir; pay battaniye ya da örtü serildikten sonra onun üzerine katlanır.","konu":"3.2.4"},{"id":"kh1-3-s043","tur":"coktan-secmeli","soru":"Üst çarşafın başucu payı ne zaman katlanır?","secenekler":["Alt çarşaf serilir serilmez","Battaniye ya da örtü serildikten sonra, onun üzerine","Yastıklar yerleştirildikten sonra yastığın üzerine","Üst çarşaf serilmeden önce"],"dogru":1,"aciklama":"Başucundan sarkan kısım, battaniye ya da örtü serildikten sonra onun üzerine katlanır.","konu":"3.2.4"},{"id":"kh1-3-s044","tur":"coktan-secmeli","soru":"Battaniyenin etiketi neden ayak ucuna gelecek biçimde serilir?","secenekler":["Konuk bakım bilgisini başucundan okuyabilsin","Çamaşırhane battaniye cinsini kolay ayırt edebilsin","Konuğa görünmesin, yatak daha derli toplu dursun","Etiket yastığın altında kıvrılıp kaybolmasın"],"dogru":2,"aciklama":"Etiket ayak ucunda olduğunda görünmez; yatak daha temiz ve profesyonel durur.","konu":"3.2.5"},{"id":"kh1-3-s045","tur":"coktan-secmeli","soru":"Çarşaf kıvrımı hangi amaçla yapılır?","secenekler":["Battaniyenin başucu kenarını yastığın altına sokmak","Başucundaki fazla çarşafı battaniyenin üstüne katlamak","Üst çarşafı ortadan ikiye bölüp battaniyenin altına almak","Alt çarşafın başucu kenarını bazaya paketlemek"],"dogru":1,"aciklama":"Battaniyenin altına serilen üst çarşafın başucunda bırakılan fazlası battaniyenin üstüne katlanır; battaniye yastığa değmez.","konu":"3.2.5"},{"id":"kh1-3-s046","tur":"coktan-secmeli","soru":"Battaniye ve üst çarşaf yatakta hangi tarafta yatağın altına sıkıştırılır?","secenekler":["Ayak ucu tarafında, yatağın altına","Başucunda, yastıkların altında","Yan taraflarda, yatak başlığına","Ortada, alt çarşafın altına"],"dogru":0,"aciklama":"Görevli yatağın ayak ucu tarafına geçer; battaniye ve üst çarşaf orada yatağın altına sıkıştırılır, köşeler zarf biçiminde katlanır.","konu":"3.2.5"},{"id":"kh1-3-s047","tur":"coktan-secmeli","soru":"Yastık kılıfı yatağa serilirken açık tarafı nereye gelir?","secenekler":["Pencereye doğru","Yatağın ayak ucuna doğru","Kapıya doğru","Görevliye doğru"],"dogru":3,"aciklama":"Kılıfın açık tarafı görevliye gelecek şekilde serilir. Açık uçların pencereye bakması ise yastık yerleştirilirken yapılan ayrı bir adımdır.","konu":"3.2.6"},{"id":"kh1-3-s048","tur":"coktan-secmeli","soru":"Yastığı kılıfa geçirirken yastık nasıl tutulur?","secenekler":["Boyuna ikiye katlanıp bir elle","Açık hâlde iki elle ortadan","İki yastık üst üste iki elle","Yatağın altından itilerek tek elle"],"dogru":0,"aciklama":"Yastık boyuna ikiye katlanır ve bir elle tutulur; kılıfın içine yerleşene kadar katlı kalır, köşeler kılıf köşesine denk gelir.","konu":"3.2.6"},{"id":"kh1-3-s049","tur":"coktan-secmeli","soru":"Kılıflı yastıkların açık uçları yatakta nereye bakacak biçimde yerleştirilir?","secenekler":["Kapıya","Ayak ucuna","Başlığa","Pencereye"],"dogru":3,"aciklama":"Açık uçlar pencereye, yani konuğun görmeyeceği yöne bakar; yastık daha derli toplu görünür.","konu":"3.2.6"},{"id":"kh1-3-s050","tur":"coktan-secmeli","soru":"Nevresimi yorgana geçirirken hangi yöntem doğrudur?","secenekler":["Kolları nevresimin içine sokup yorganın köşelerini tutmak","Yorganı nevresimin üzerine serip köşelerini dışarıdan çekmek","Yorganı ikiye katlayıp nevresimin ağzından itmek","Nevresimi tek elle dışarıdan çekmek"],"dogru":0,"aciklama":"Nevresim iç tarafından iki el yardımıyla geçirilir ve köşelerden tutulur; böylece yorganın köşeleri nevresimin köşelerine yerleşir.","konu":"3.2.7"},{"id":"kh1-3-s051","tur":"coktan-secmeli","soru":"Nevresim yokken yorganın, battaniyenin ya da pikenin hijyeni nasıl sağlanır?","secenekler":["Alt çarşafın altına konarak","Üst çarşafla kaplanarak","Yastık kılıfına sarılarak","Yatak koruyucuyla örtülerek"],"dogru":1,"aciklama":"Nevresim bulunmadığında malzeme üst çarşafla kaplanır; konuk doğrudan malzemeye değil çarşafa temas eder.","konu":"3.2.7"},{"id":"kh1-3-s052","tur":"coktan-secmeli","soru":"Yatak örtüsü yatakta nasıl durmalıdır?","secenekler":["İki tarafa eşit sarkacak biçimde serilip yatağa kapatılmalıdır","Yalnızca ayak ucundan sarkacak biçimde serilip kapatılmalıdır","Başucuna sıkıştırılacak biçimde serilip yatağa kapatılmalıdır","Yastıkların altında kalacak biçimde serilip yatağa kapatılmalıdır"],"dogru":0,"aciklama":"Örtü iki tarafa eşit sarkacak şekilde serilir ve yatağın üzerine kapatılır; sonra üst kısmı düzeltilir.","konu":"3.2.8"},{"id":"kh1-3-s053","tur":"coktan-secmeli","soru":"Mavi tonlu odaların bulunduğu katta aynı tonda yatak örtüleri seçilmesinin sebebi hangisidir?","secenekler":["Örtüler daha kolay yıkansın","Odanın bütünlüğü bozulmasın","Kirlenme daha az görünsün","Örtülerin ömrü uzasın"],"dogru":1,"aciklama":"Yatak örtüleri genellikle oda rengine ve mefruşatına uygun seçilir; uyumlu örtü dekorasyonun bozulmasını önler.","konu":"3.2.8"},{"id":"kh1-3-s054","tur":"coktan-secmeli","soru":"Pike nasıl düzenlenir?","secenekler":["Alt çarşafın üzerine serilir, başucu payı pikenin altına alınır","Battaniyenin altına serilir, başucu payı yastığa sarılır","Yatak örtüsünün üzerine serilir, başucu payı katlanmaz","Üst çarşafın üzerine serilir, çarşaf payı pikenin üzerine katlanır"],"dogru":3,"aciklama":"Pike düzenleme tekniği battaniyeye benzer: üst çarşafın üzerine serilir ve çarşafın başucunda kalan payı üzerine katlanır.","konu":"3.2.9"},{"id":"kh1-3-s055","tur":"coktan-secmeli","soru":"Pike serildikten sonra yapılması gereken işlem hangisidir?","secenekler":["Yüzeydeki pürüzlerin elle düzeltilmesi","Üzerine ikinci bir pike serilmesi","Başucuna fazladan yastık eklenmesi","Pikenin yatak örtüsünün altına katlanması"],"dogru":0,"aciklama":"Pike yatağın üzerine serildikten sonra oluşan pürüzler düzeltilir; düzgün yüzey yatağı bakımlı gösterir.","konu":"3.2.9"},{"id":"kh1-3-s056","tur":"dogru-yanlis","soru":"Çekyat, odada sabit bulunmayan ve katlanarak taşınan ilave yatak çeşididir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Bu tanım portatif (katlanır) yatağa aittir. Çekyat ise koltuk olarak kullanılan, istenince yatağa dönüşen mobilyadır.","konu":"3.2.10"},{"id":"kh1-3-s057","tur":"coktan-secmeli","soru":"Bebek karyolasını diğer ilave yataklardan ayıran özellik hangisidir?","secenekler":["Çocuğun düşmesini engelleyen parmaklıklı olması","Koltuk olarak da kullanılabilen bir mobilya olması","Duvara sabitlenerek kalıcı biçimde kurulması","Yatak koruyucu ya da alez gerektirmemesi"],"dogru":0,"aciklama":"Bebek karyolası düşmeyi engelleyen parmaklıklı, güvenli uyku sağlayan bir yatak aracıdır; çekyat ise koltuğa dönüşen mobilyadır.","konu":"3.2.10"},{"id":"kh1-3-s058","tur":"coktan-secmeli","soru":"Bebek karyolası hazırlanırken hangi malzeme bebek takımının dışında, ayrıca odaya getirilir?","secenekler":["Bebek battaniyesi","Küçük ölçülü nevresim","Yastık kılıfı","Sıvı geçirmez alez"],"dogru":3,"aciklama":"Bebek takımı küçük çarşaf, nevresim, yastık, kılıf, battaniye ya da yorgan ve örtüden oluşur; sıvı geçirmez alez ayrıca getirilir.","konu":"3.2.10"},{"id":"kh1-3-s059","tur":"coktan-secmeli","soru":"Bebek karyolasında alt çarşaftan önce sıvı geçirmez alez serilmesinin nedeni hangisidir?","secenekler":["Çarşafın daha çabuk kurumasını sağlamak","Yatağı daha yumuşak hâle getirmek","Yatağı leke ve ıslanmaya karşı korumak","Bebeği soğuktan korumak"],"dogru":2,"aciklama":"Bebek yatağı ıslanmaya yatkındır; alez yatağı korur ve temizliği kolaylaştırır.","konu":"3.2.10"},{"id":"kh1-3-s060","tur":"coktan-secmeli","soru":"Odada sabit durmayan, katlanıp taşınabilen ve konuk isteğiyle kat görevlilerince eklenen yatak hangisidir?","secenekler":["Çekyat","Bebek karyolası","Sandıklı baza","Portatif yatak"],"dogru":3,"aciklama":"Portatif yatağın en önemli özelliği taşınabilir olmasıdır. Çekyat ise odadaki koltuğun yatağa dönüşmesidir.","konu":"3.2.10"},{"id":"kh1-3-s061","tur":"coktan-secmeli","soru":"Portatif yatağın konulacağı yerde eşya varsa kurulumdan önce ne yapılır?","secenekler":["Eşyalar kenara alınarak yer açılır","Yatak eşyaların üzerine kurulup sabitlenir","Eşyalar koridora çıkarılır","Yatak başka bir odaya taşınır"],"dogru":0,"aciklama":"Yatağın yeri baştan belirlenir; eşyalar kenara alınarak yer açılır, böylece odada geçiş alanı daralmaz.","konu":"3.2.10"},{"id":"kh1-3-s062","tur":"coktan-secmeli","soru":"Çekyat işletmeler tarafından neden çok tercih edilir?","secenekler":["Çarşaf ve koruyucu gerektirmediği için hazırlığı kısadır","Koltuk ihtiyacını karşılar, yatak kapasitesini de artırır","Bebek karyolasının yerini tam olarak tutar","Her otelde bulundurulması zorunludur"],"dogru":1,"aciklama":"Çekyat koltuk ihtiyacını karşılar ve yatağa dönüşebildiği için yatak kapasitesini artırır; çocuklu ailelerin odalarında sık kullanılır.","konu":"3.2.10"},{"id":"kh1-3-s063","tur":"coktan-secmeli","soru":"Konuğun isteğiyle akşam saatlerinde yatak açma servisini hangi bölüm verir?","secenekler":["Resepsiyon","Güvenlik","Housekeeping","Yiyecek içecek"],"dogru":2,"aciklama":"Turn down servisi konuğun isteği doğrultusunda housekeeping görevlisi tarafından verilir.","konu":"3.2.11"},{"id":"kh1-3-s064","tur":"dogru-yanlis","soru":"Turn down servisi her konaklama işletmesinde uygulanmayabilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Turn down, konuğun isteği doğrultusunda housekeeping tarafından verilen ve her konaklama işletmesinde uygulanmayabilen bir hizmettir; verildiğinde konuğa özen gösterildiğini hissettirir.","konu":"3.2.11"},{"id":"kh1-3-s065","tur":"coktan-secmeli","soru":"Turn down sırasında yatak örtüsüne ne yapılır?","secenekler":["Yatağın ayak ucuna yayılıp orada bırakılır","Katlanıp odadaki uygun bir dolaba kaldırılır","Yastıkların üzerine toplanıp öylece bırakılır","Kirli sepetine atılıp çamaşırhaneye gönderilir"],"dogru":1,"aciklama":"Örtü birkaç kez katlanıp dolaba kaldırılır; böylece konuğun yatağa girişini engellemez ve kirlenmez.","konu":"3.2.11"},{"id":"kh1-3-s066","tur":"coktan-secmeli","soru":"Turn down servisinde hangi eşleştirme doğrudur?","secenekler":["Kahvaltı istek formu: yatak başı komodinine","Lokum ya da çikolata: banyo rafına","Pijama ya da gecelik: yatağın üzerine","Pijama ya da gecelik: dolabın rafına"],"dogru":2,"aciklama":"Pijama ve gecelikler yatağın üzerine bırakılır; kahvaltı istek formu da yatağın üzerine, ikram ise genellikle yastığın üzerine konur.","konu":"3.2.11"},{"id":"kh1-3-s067","tur":"coktan-secmeli","soru":"Turn down servisiyle ilgili hangisi yanlıştır?","secenekler":["Battaniye ve üst çarşaf üçgen biçiminde geriye katlanır","Yatak örtüsü açılmaz, ayak ucunda yayılı bırakılır","Pijama ve gecelikler yatağın üzerine bırakılır","Perdeler pencere kontrolünden sonra kapatılır"],"dogru":1,"aciklama":"Turn down’da yatak örtüsü katlanıp dolaba kaldırılır; yatak açılarak konuğa hazır hâle getirilir.","konu":"3.2.11"},{"id":"kh1-3-s068","tur":"coktan-secmeli","soru":"Turn down sırasında yastığın üzerine bir lokum bırakılmasının amacı hangisidir?","secenekler":["Konuğun gece yemek istemesini engellemek","Yastığın yerinden kaymasını önlemek","Mini bar satışlarını artırmak","Konuğa özel ilgi gösterildiğini hissettirmek"],"dogru":3,"aciklama":"Küçük ikram konuğa özel ilgi gösterildiğini hissettirir; işletmenin uygun gördüğü yiyecekler genellikle yastığın üzerine konur.","konu":"3.2.11"},{"id":"kh1-3-s069","tur":"coktan-secmeli","soru":"Turn down bittiğinde odada sensörlü ışık yoksa ışıklar için ne yapılır?","secenekler":["Işıkların tümü söndürülür; konuk döndüğünde kendisi açar","Işıkların tümü açık bırakılır; konuk dönene kadar yanar","Yarıya kadar kısılır; perdeler açık bırakılır","Biri açık bırakılır; konuk yolunu rahat bulur"],"dogru":3,"aciklama":"Odadan çıkarken sensörlü ışık yoksa ışıklardan biri açık bırakılır; böylece konuk odaya girince karanlıkta kalmaz.","konu":"3.2.11"},{"id":"kh1-3-s070","tur":"dogru-yanlis","soru":"Konuk odadayken yapılacak turn down’da kapı çalınıp izin istenir ve hizmet konuğu rahatsız etmeden verilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Konuk odadayken kapı çalınır ve izin alınır; işlem hızlı ve sessiz yapılır, konuğun mahremiyeti korunur.","konu":"3.2.11"},{"id":"kh1-3-s071","tur":"coktan-secmeli","soru":"Turn down sonunda balkon kapısı açık bulunursa ne yapılır?","secenekler":["Açık bırakılıp perdeler çekilir","Kapatılır, pencereler de aynı şekilde kontrol edilir","Konuk dönene kadar beklenir","Açık kalıp kalmayacağı konuğa not bırakılarak sorulur"],"dogru":1,"aciklama":"Balkon kapısı ve pencereler kontrol edilir, açıksa kapatılır; kapalı pencere konuğun gece güvenliğini ve konforunu sağlar.","konu":"3.2.11"},{"id":"kh1-3-s072","tur":"senaryo","durum":"Sabah 11.00. 308 numaralı odadan çıkış yapan konuğun çarşafını toplarken içinden küçük bir mücevher kutusu çıkıyor. Konuk bir saat önce otelden ayrıldı.","soru":"Ne yaparsın?","secenekler":["Kutuyu resepsiyon bölümüne teslim edersin","Kutuyu komodinin üzerinde görülür yere bırakırsın","Kutuyu sepetteki çarşafla birlikte çamaşırhaneye bırakırsın","Kutuyu kat arabasının çekmecesinde saklarsın"],"dogru":0,"aciklama":"Konuk işletmeden ayrılmışsa eşya resepsiyon bölümüne teslim edilir. Komodine bırakılan eşya, sahibi gitmişken kaybolabilir.","konu":"3.2.1"},{"id":"kh1-3-s073","tur":"senaryo","durum":"Öğleden sonra 16.00. Bir odada yatak koruyucuyu çıkarırken yatağın üzerinde küçük bir leke fark ediyorsun. Yeni konuğun gelmesine az kaldı.","soru":"Ne yaparsın?","secenekler":["Temiz çarşafı serip lekeyi altta bırakırsın","Yatağı ters çevirip lekeli yüzü alta alırsın","Lekeyi silip temiz bir koruyucu takarsın","Durumu kat şefine bildirmeden eski koruyucuyu geri takarsın"],"dogru":2,"aciklama":"Yatak yıkanamadığı için leke fark edilir edilmez silinir ve temiz koruyucu takılır. Lekeyi örtmek hijyen sorununu çözmez.","konu":"3.2.2"},{"id":"kh1-3-s074","tur":"senaryo","durum":"Akşam 19.00. Bebekle gelen bir ailenin odasına karyola kuruyorsun. Malzemeleri odaya getirdin ve karyolayı kurdun.","soru":"Sıradaki adımın ne olur?","secenekler":["Yatağın üzerine sıvı geçirmez alezi serersin","Alt çarşafı doğrudan karyolanın yatağına serersin","Yastık kılıfını takıp örtüyü düzeltirsin","Üst çarşafı yerleştirip nevresimi geçirirsin"],"dogru":0,"aciklama":"Bebek karyolasında karyola kurulduktan sonra önce sıvı geçirmez alez serilir, ardından alt çarşaf gelir; alez yatağı lekeye ve ıslanmaya karşı korur.","konu":"3.2.10"},{"id":"kh1-3-s075","tur":"senaryo","durum":"Akşam 21.15. Turn down servisini bitirdin. Balkon kapısı açık, perdeler açık, odada sensörlü ışık yok ve odadan çıkmak üzeresin.","soru":"Ne yaparsın?","secenekler":["Balkon kapısını kapatır, perdeleri çeker, bir ışığı açık bırakırsın","Balkon kapısını açık bırakıp perdeleri çeker, ışıkları söndürürsün","Her şeyi olduğu gibi bırakıp kapıyı kilitlersin","Balkon kapısını kapatır, perdeleri çeker, bütün ışıkları söndürürsün"],"dogru":0,"aciklama":"Balkon kapısı ve pencereler kapatılır, perdeler çekilir; sensörlü ışık yoksa konuk dönünce yolunu bulsun diye bir ışık açık bırakılır.","konu":"3.2.11"},{"id":"kh1-3-s076","tur":"senaryo","durum":"Öğleden sonra 14.30. Çocuklu bir aile için çekyatı yatağa çeviriyorsun; arabanda kullanılacak nevresim kalmamış.","soru":"Ne yaparsın?","secenekler":["Battaniyeyi çıplak hâliyle üst çarşafın altına koyarsın","Yatağı nevresim gelene kadar hazırlamayı ertelersin","Battaniyeyi üst çarşafla kaplayıp yatağa serersin","Çarşafsız hazırladığın yatağa yalnızca pike serersin"],"dogru":2,"aciklama":"Nevresim bulunmadığında battaniye, yorgan ya da pike üst çarşafla kaplanır; böylece konuk doğrudan örtüye değil çarşafa temas eder.","konu":"3.2.7"},{"id":"kh1-3-s101","tur":"coktan-secmeli","soru":"Havlunun suyu iyi emmesi ve yumuşak durması hangisinin bolluğuna bağlıdır?","secenekler":["Peşkir","Hav","Peştamal","Bornoz"],"dogru":1,"aciklama":"Hav, kumaş yüzeyindeki ince tüylerdir; bolluğu havlunun su emmesini ve yumuşaklığını etkiler, havı yıpranmış havlu özensiz izlenim bırakır.","konu":"3.3.1"},{"id":"kh1-3-s102","tur":"coktan-secmeli","soru":"“Peşkir” sözcüğü için hangisi doğrudur?","secenekler":["Hamamda kullanılan ince dokulu örtünün eski adıdır","Havlunun eski adıdır; Selçuklu kaynaklarında geçer","Havlu yüzeyindeki ince tüylere verilen addır","Bursa’da kurulan ilk dokuma atölyesinin adıdır"],"dogru":1,"aciklama":"Peşkir havlunun eski adıdır. Hamamda kullanılan ince dokulu örtü peştamaldır; tüylere ise hav denir.","konu":"3.3.1"},{"id":"kh1-3-s103","tur":"coktan-secmeli","soru":"Bursa’nın havlunun ilk üretim yeri sayılmasının gerekçesi hangisidir?","secenekler":["Dünyaca ünlü havluların orada üretilmiş olması","Hamamların Türkiye’de ilk kez orada kurulması","İpek böceği yetiştiriciliği ve ipek dokumada önde olması","İstanbul’un fethinden sonra hamamların orada çoğalması"],"dogru":2,"aciklama":"Bursa ipek dokuma alanında önde olduğundan havlunun ilk üretim yeri kabul edilir. Dünyaca ünlü havlular ise Denizli ile anılır.","konu":"3.3.1"},{"id":"kh1-3-s104","tur":"coktan-secmeli","soru":"Bursa ve Denizli ile ilgili hangisi doğrudur?","secenekler":["Havlunun ilk üretim yeri Denizli’dir; dünyaca ünlü havlular Bursa’da üretilir","Havlunun ilk üretim yeri Bursa’dır; dünyaca ünlü havlular Denizli’de üretilir","İki il de yalnızca peştamal üretiminde öne çıkar","İki ilin havluları yalnızca iç piyasada satılır"],"dogru":1,"aciklama":"Bursa havlunun ilk üretim yeri sayılır; Denizli havlularıyla dünyaca ünlüdür. Bu illerin ürünleri Türkiye’nin en çok ihraç ettiği ürünler arasındadır.","konu":"3.3.1"},{"id":"kh1-3-s105","tur":"coktan-secmeli","soru":"Satın alma sorumlusu havluları önce kullanım alanına, sonra malzemesine göre gruplandırıyor. Bu ikili sınıflandırmanın yararı hangisidir?","secenekler":["Her alana uygun havlu seçilir, stok düzenli yürür","Bütün havlular tek ölçü ve tek renge getirilir","Havlular yıkanmadan birkaç konukta kullanılabilir","Pamuk dışındaki lifler otellerden tamamen çıkarılır"],"dogru":0,"aciklama":"Sınıflandırma hangi alanda hangi havlunun ve malzemenin kullanılacağını netleştirir; konuk memnun kalır, satın alma ve çamaşırhane düzenli çalışır.","konu":"3.3.2"},{"id":"kh1-3-s106","tur":"coktan-secmeli","soru":"Konuk odası banyosunda buklet malzemeleriyle birlikte bulunan ve el-yüz kurulamaya yarayan havlu hangisidir?","secenekler":["Ayak havlusu","Plaj havlusu","Yüz havlusu","Bornoz"],"dogru":2,"aciklama":"Yüz havlusu banyoda buklet malzemeleriyle birlikte bulunur ve el-yüz kurulamak içindir.","konu":"3.3.2"},{"id":"kh1-3-s107","tur":"coktan-secmeli","soru":"Ayak havlusu asılmaz, duş çıkışına yere serilir. Bunun nedeni hangisidir?","secenekler":["Banyo havlusunun ıslanmasını önlemesi","Çamaşırhaneye daha az gitmesi","Zeminin daha az kirlenmesi","Islak zeminde kayma ve düşmeyi önlemesi"],"dogru":3,"aciklama":"Ayak havlusu ıslak zeminde yaşanabilecek düşme ve kaymayı önler; bu yüzden aynı zamanda bir güvenlik ürünüdür.","konu":"3.3.2"},{"id":"kh1-3-s108","tur":"coktan-secmeli","soru":"Banyo havlusu için genellikle beyaz rengin tercih edilmesinin otel açısından yararı hangisidir?","secenekler":["Havlu daha az yıpranır ve ömrü uzar","Su emme gücü diğer renklere göre belirgin artar","Kirlilik fark edilir, sıcak yıkama kolaylaşır","Ütü gerektirmeden kullanılabilir hâle gelir"],"dogru":2,"aciklama":"Beyaz havlu temizliğin görünür olmasını sağlar ve yüksek ısıda yıkamayı kolaylaştırır. Renk, havlunun su emmesini, ütü ihtiyacını ya da yıpranmasını değiştirmez.","konu":"3.3.2"},{"id":"kh1-3-s109","tur":"coktan-secmeli","soru":"Yatağın üzerinde banyo havlusuyla birlikte katlanmış ya da origami hâlinde bırakılan, figürlerde baş ya da kuyruk gibi küçük parçaları oluşturan havlu hangisidir?","secenekler":["Baş havlusu","Ayak havlusu","Plaj havlusu","El havlusu"],"dogru":0,"aciklama":"Baş havlusu yatağın üzerinde banyo havlusuyla birlikte bulunur; figürlerde küçük parçaları oluşturduğu için origamide sık kullanılır.","konu":"3.3.2"},{"id":"kh1-3-s110","tur":"coktan-secmeli","soru":"Belinde kuşağı bulunan, hamam, sauna, SPA ya da havuza inerken de giyilebilen banyo giysisi hangisidir?","secenekler":["Bornoz","Peştamal","Plaj havlusu","Banyo havlusu"],"dogru":0,"aciklama":"Bornoz kuşaklı banyo giysisidir. Peştamal ve havlular kurulanmak içindir, giyilen bir giysi değildir.","konu":"3.3.2"},{"id":"kh1-3-s111","tur":"coktan-secmeli","soru":"Bir otel bornozu neden temizlik ve stok planına dâhil eder?","secenekler":["Bornoz plaj havlusunun yerine plajda dağıtılır","Konuk bornozla odasından SPA ya da havuza rahatça gider","Bornoz havluya göre daha ucuz olduğundan stok yapılır","Bornoz yalnızca beyaz alınabildiğinden ayrı yıkanır"],"dogru":1,"aciklama":"Konuk bornozu hamam, sauna, SPA ya da havuza giderken giyer; bu yüzden otel bornozu da temizlik ve stok planına katar.","konu":"3.3.2"},{"id":"kh1-3-s112","tur":"coktan-secmeli","soru":"Plaj havlusunun genellikle renkli seçilmesinin otel açısından yararı hangisidir?","secenekler":["Odadaki banyo havlusuyla karışmasını önler","Yüksek ısıda yıkamayı daha da kolaylaştırır","Güneşte diğer havlulardan daha çabuk kurur","Beyaz havluya göre çok daha fazla su emer"],"dogru":0,"aciklama":"Renkli plaj havlusu odadaki beyaz banyo havlusundan kolayca ayırt edilir. Yüksek ısıda yıkama kolaylığı ise beyaz havlunun avantajıdır.","konu":"3.3.2"},{"id":"kh1-3-s113","tur":"coktan-secmeli","soru":"Konuğa check-in sırasında oda kartıyla birlikte verilen havlu kartı ne işe yarar?","secenekler":["Sahilde ya da havuz kenarında plaj havlusu almaya","Odadaki banyo havlularını ücretsiz yeniletmeye","SPA bölümüne ücretsiz giriş hakkı kazandırmaya","Hamama girerken peştamal ve havlu teslim almaya"],"dogru":0,"aciklama":"Havlu kartı sahil kenarındaki işletmelerde plaj havlusu almak içindir ve dağıtımı konuk bazında izlemeyi kolaylaştırır.","konu":"3.3.2"},{"id":"kh1-3-s114","tur":"coktan-secmeli","soru":"Bazı işletmelerde plaj havlusu sabah şezlongların üzerine önceden serilir. Bu uygulamanın kart ve stand sistemine göre farkı hangisidir?","secenekler":["Konuk havluyu odasından getirir","Konuk havlu için sıra beklemez","Havlu yalnızca resepsiyonda verilir","Havlu her sabah kapının altından atılır"],"dogru":1,"aciklama":"Şezlongdaki havlu uygulaması kart ve stand sistemine alternatiftir; konuk havlu için beklemez.","konu":"3.3.2"},{"id":"kh1-3-s115","tur":"coktan-secmeli","soru":"Aşağıdaki liflerden hangisi otellerde havlu üretiminde kullanılan temel malzemedir?","secenekler":["Bambu","Pamuk","Keten","Modal"],"dogru":1,"aciklama":"Havlu üretiminde kullanılan temel malzeme pamuktur; bambu, keten ve modal tamamlayıcı ya da özel bölümler için kullanılır.","konu":"3.3.2"},{"id":"kh1-3-s116","tur":"coktan-secmeli","soru":"Pamuğun otel havluları için avantajı hangisidir?","secenekler":["Hiç kırışmadığı için ütüye ihtiyaç bırakmaması","Suyu çok az emdiği için çabucak kuruması","Yıkanmadan aylarca temiz kalarak kullanılabilmesi","Uzun kullanıma ve yüksek ısıda yıkamaya uygun olması"],"dogru":3,"aciklama":"Pamuk uzun süre kullanıma, yüksek ısıda yıkanmaya ve ütülemeye uygun olduğundan otel havluları için yaygın tercihtir.","konu":"3.3.2"},{"id":"kh1-3-s117","tur":"coktan-secmeli","soru":"Nem tutma oranı yüksek olan ve kayın ağacından üretilen lif hangisidir?","secenekler":["Keten","Bambu elyafı","Modal","Pamuk"],"dogru":2,"aciklama":"Modal, kayın ağacından üretilen, nem tutma oranı yüksek ve yıpranmaya dayanıklı bir liftir.","konu":"3.3.2"},{"id":"kh1-3-s118","tur":"coktan-secmeli","soru":"Hangi eşleştirme doğrudur?","secenekler":["Modal: bambu bitkisi","Bambu elyafı: kayın ağacı","Pamuk: keten bitkisinin gövdesi","Keten: keten bitkisinin gövdesi"],"dogru":3,"aciklama":"Keten lifi keten bitkisinin gövdesinden elde edilir. Modal kayın ağacından, bambu elyafı ise bambu bitkisinden üretilir.","konu":"3.3.2"},{"id":"kh1-3-s119","tur":"coktan-secmeli","soru":"Modal ve keten ürünler ağırlıkla hangi bölümlerde kullanılır?","secenekler":["Mutfak ve bulaşıkhane","SPA, hamam ve sauna","Çamaşırhane ve depo","Restoran ve bar"],"dogru":1,"aciklama":"Nemli ve rutubetli ortamlarda sık kullanıldıkları için modal ve keten havlu, bornoz ve peştamallar SPA, hamam ve sauna bölümlerinde yer alır.","konu":"3.3.2"},{"id":"kh1-3-s120","tur":"dogru-yanlis","soru":"Bambu bitkisi kimyasalsız yetişse bile elyafa dönüştürülürken kullanılan maddeler nedeniyle bambu elyafı organik sayılmaz.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Bambu yetiştirilirken kimyasal kullanılmaması çevre dostu görünmesini sağlar; ama işleme maddeleri yüzünden elyaf organik değildir.","konu":"3.3.2"},{"id":"kh1-3-s121","tur":"dogru-yanlis","soru":"Bambu havlular pamuk havlulara göre genellikle daha ucuzdur.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Bambu havluların maliyeti pamuktan üretilenlere göre daha yüksektir.","konu":"3.3.2"},{"id":"kh1-3-s122","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi origami sayılır?","secenekler":["Havluyu araçsız, yalnızca katlayarak kuğuya dönüştürmek","Havluyu keçe parçalarıyla dikerek kuğuya dönüştürmek","Havluyu kalıpla kesip kuğu biçimine dönüştürmek","Havluyu boyayarak üzerinde kuğu deseni oluşturmak"],"dogru":0,"aciklama":"Origami, malzemeyi araç kullanmadan yalnızca katlayarak şekillendirme sanatıdır; dikmek, kesmek ve boyamak bu tanımın dışındadır.","konu":"3.3.3"},{"id":"kh1-3-s123","tur":"coktan-secmeli","soru":"Aşağıdaki havlu figürlerinden hangisi hayvan figürü değildir?","secenekler":["Fil","Köpek","Gömlek","Kaplumbağa"],"dogru":2,"aciklama":"Gömlek hayvan değil, giysi biçimli bir figürdür. Fil, köpek ve kaplumbağa hayvan figürleridir.","konu":"3.3.3"},{"id":"kh1-3-s124","tur":"coktan-secmeli","soru":"Balayı çiftinin odası için gagaları birleştirilerek kalp biçimi verilebilen figür hangisidir?","secenekler":["Köpek","Kaplumbağa","Gömlek","Kuğu"],"dogru":3,"aciklama":"Ders materyaline göre kuğu en çok kullanılan figürdür ve balayı odalarında tamamlayıcı süs olur; iki kuğunun gagaları birleştirilerek kalp biçimi oluşur.","konu":"3.3.3"},{"id":"kh1-3-s125","tur":"coktan-secmeli","soru":"Hangi havlu figürünün içine isteğe bağlı olarak buklet malzemeleri konabilir?","secenekler":["Hediye paketi","Sepet","Kaplumbağa","Gömlek"],"dogru":1,"aciklama":"Sepet figürünün içine buklet malzemeleri yerleştirilebilir; hediye paketi ise rulo havluların kurdeleyle bağlanıp üst üste konmasıdır.","konu":"3.3.3"},{"id":"kh1-3-s126","tur":"coktan-secmeli","soru":"Yalnız banyo havlusuyla yapılan, baş havlusu gerektirmeyen figür hangisidir?","secenekler":["Fil","Yengeç","Köpek","Gömlek"],"dogru":3,"aciklama":"Gömlek figürü yalnız bir banyo havlusu gerektirir. Fil, yengeç ve köpek için banyo havlusunun yanında bir de baş havlusu gerekir.","konu":"3.3.3"},{"id":"kh1-3-s127","tur":"coktan-secmeli","soru":"Rulo yapılan banyo ve baş havlularının kurdeleyle bağlanıp üst üste konmasıyla oluşan, özellikle çift kişilik odalar için yapılan figür hangisidir?","secenekler":["Yengeç","Köpek","Hediye paketi","Kuğu"],"dogru":2,"aciklama":"Hediye paketi figürü iki baş, iki banyo havlusu ve kurdele ile çift kişilik odalar için yapılır.","konu":"3.3.3"},{"id":"kh1-3-s128","tur":"coktan-secmeli","soru":"Kaplumbağa figürü için hangi havlu sayısı ve çeşidi gerekir?","secenekler":["Bir banyo ve bir baş havlusu","Bir banyo ve iki baş havlusu","İki banyo ve iki baş havlusu","İki banyo ve bir baş havlusu"],"dogru":3,"aciklama":"Kaplumbağa için iki banyo havlusu ayaklar ve kabuk için, bir baş havlusu da baş için kullanılır.","konu":"3.3.3"},{"id":"kh1-3-s129","tur":"coktan-secmeli","soru":"Kuğu figüründe kuyruk hangi havludan ve nasıl katlanarak yapılır?","secenekler":["Baş havlusundan, rulo yapılarak","Banyo havlusundan, akordiyon biçiminde katlanarak","Banyo havlusundan, dışa çevrilerek","Baş havlusundan, akordiyon biçiminde katlanarak"],"dogru":3,"aciklama":"Baş havlusu akordiyon katlanır, ortasından katlanarak kuğunun kuyruğu olur; rulo ve dışa çevirme başka figürlerin tekniğidir.","konu":"3.3.3"},{"id":"kh1-3-s130","tur":"dogru-yanlis","soru":"Havlu figürüne oynar göz ve kurdele eklenmesi, şeklin yalnızca katlayarak verilmesi ilkesiyle çelişmez.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Origamide şekil araç kullanmadan katlayarak verilir; göz, kurdele gibi süsler figürü canlandıran ek malzemelerdir.","konu":"3.3.3"},{"id":"kh1-3-s131","tur":"dogru-yanlis","soru":"Kuğunun boynunu katlarken kıvrımın eşit ve sıkı olması gerekmez; figür süslerle zaten belirginleşir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Eğri ya da gevşek katlanmış figür dağılır veya ne olduğu anlaşılmaz; süsler yanlış katlamayı kurtarmaz. Her kat düzgün, eşit ve sıkı yapılınca şekil belirgin olur.","konu":"3.3.3"},{"id":"kh1-3-s132","tur":"coktan-secmeli","soru":"Öğretmen havlu figürü uygulamasını beş ölçüte göre puanlıyor. Hangisi bu ölçütlerden biridir?","secenekler":["Kullanılan süsleme malzemesinin çokluğu","Figürün yatakta kapladığı alanın genişliği","Olağan dışı durumlara hazır bulunuşluk","Odadaki havlu sayısının fazlalığı"],"dogru":2,"aciklama":"Değerlendirme iş için hazırlık, uygulama, zamanı kullanma, iletişim ve olağan dışı durumlara hazır bulunuşluk ölçütlerine göre yapılır. Süsleme malzemesinin çokluğu, figürün genişliği ya da havlu sayısı ölçüt değildir.","konu":"3.3.3"},{"id":"kh1-3-s133","tur":"coktan-secmeli","soru":"Köpek ya da fil figürünü süslemek için takılan kurdele ya da kumaş bağ hangisidir?","secenekler":["Papyon ya da küçük fiyonk","Oynar göz ya da keçe göz","Yapay ya da canlı çiçek","Keçeden yapılmış göz ve ağız"],"dogru":0,"aciklama":"Papyon ve fiyonk, figüre takılan küçük kurdele ya da kumaş bağdır; figüre karakter katar.","konu":"3.3.3"},{"id":"kh1-3-s134","tur":"coktan-secmeli","soru":"Havlu figürü yapmadan önce takıların çıkarılması hangi hazırlığın parçasıdır?","secenekler":["Kişisel bakım ve hijyen kurallarına uyma","Malzeme ihtiyaç listesini kontrol etme","İş programını kat şefinden öğrenme","Kat arabasını alıp malzemeyi yükleme"],"dogru":0,"aciklama":"Figür çalışmasından önce kişisel bakım ve hijyen kurallarına uyulur, takılar çıkarılır, forma giyilir ve isimlik takılır.","konu":"3.3.3"},{"id":"kh1-3-s135","tur":"senaryo","durum":"Sabah 10.00’da plajda bir konuk sana yaklaşıp odasından plaj havlusu getirmeyi unuttuğunu söylüyor. Yanında oda kartı ve check-in’de aldığı havlu kartı var.","soru":"Ne yaparsın?","secenekler":["Odasına gidip kendi havlusunu getirmesini istersin","Banyo havlusunu plajda kullanmasını önerirsin","Kartla standa ya da şezlongdaki havluya yönlendirirsin","Kartını alıp ön büroda havlu istemesini söylersin"],"dogru":2,"aciklama":"Havlu kartı plaj havlusu almak içindir; konuğu standa ya da şezlongdaki havluya yönlendirmek onu bekletmez.","konu":"3.3.2"},{"id":"kh1-3-s136","tur":"senaryo","durum":"Kuğu figürü için aldığın banyo havlusunun bir köşesinde silinmeyecek bir leke fark ediyorsun. Kat şefi yakında değil, vakit de dar.","soru":"Hangisi doğru davranıştır?","secenekler":["Lekeli köşeyi içe katlayıp aynı havluyu kullanırsın","Lekenin üstüne yapay çiçek koyarak figürü tamamlarsın","Figür yapmadan odayı olduğu gibi bırakırsın","Lekeli havluyu ayırıp temiz havlu alırsın"],"dogru":3,"aciklama":"Konuk figürü yatakta ilk görür; lekeli ya da solmuş havlu en güzel katlamayı bile gölgeler. Bu yüzden figür yalnızca temiz havluyla yapılır.","konu":"3.3.3"},{"id":"kh1-3-s137","tur":"senaryo","durum":"Bir konuk, dün akşam duştan çıkarken ıslak zeminde az kalsın düşeceğini söyleyip şikâyet ediyor. Bugün aynı banyoyu hazırlıyorsun.","soru":"Banyo düzeninde ne yaparsın?","secenekler":["Ayak havlusunu banyo kapısının arkasına asarsın","Ayak havlusunu duş çıkışına düz serersin","Ayak havlusunu duşun içine bırakıp çıkarsın","Ayak havlusunu dolaba kaldırırsın"],"dogru":1,"aciklama":"Ayak havlusu ıslak zeminde kayma ve düşmeyi önlemek için küvet ya da duş çıkışına, düz biçimde yere serilir.","konu":"3.3.2"},{"id":"kh1-3-s138","tur":"senaryo","durum":"Vardiyaya başladın ve bugün balayı çiftinin odasına kuğu figürü yapacaksın. Bileğinde saat, parmağında yüzük var; kat şefi hazırlığını soruyor.","soru":"Figüre başlamadan önce ilk olarak ne yaparsın?","secenekler":["Takılarını çıkarıp kişisel bakımını kontrol edersin","Doğrudan odaya girip havluları katlamaya başlarsın","Havluları saymadan kat arabasını odaya götürürsün","Kuğuları katlayıp işin bitince ellerini yıkarsın"],"dogru":0,"aciklama":"Uygulamanın ilk adımı kişisel bakım ve hijyen kurallarına uymak, takıları çıkarmak ve formayı giymektir.","konu":"3.3.3"},{"id":"kh1-3-s139","tur":"senaryo","durum":"Akşam 20.30. Turn down servisi için 412 numaralı odaya geldin; kapıyı çalmadan önce içeriden televizyon sesi duyuyorsun. Konuğun odada olduğunu anlıyorsun.","soru":"Ne yaparsın?","secenekler":["Servis kartıyla içeri girip yatağı sessizce açarsın","Kapıyı çalıp izin ister, uygunsa servisi yaparsın","Konuk odadayken servisi atlayıp sabaha bırakırsın","Kapıyı aralayıp içeriye bakar, sonra girersin"],"dogru":1,"aciklama":"Konuk odadayken kapı çalınıp izin istenir ve konuk rahatsız edilmeden hizmet verilir. Habersiz girmek konuğun mahremiyetine zarar verir; servisi hiç yapmamak ise hizmeti eksik bırakır.","konu":"3.2.11"},{"id":"kh1-3-s140","tur":"senaryo","durum":"Sabah 11.30. Çıkış yapılmış bir odanın yatağını toplarken alt çarşafta ve nevresimde çıkmayacak gibi duran büyük bir leke görüyorsun. Arabada kirli çamaşır sepeti dolu.","soru":"Ne yaparsın?","secenekler":["Lekeli parçaları diğer takımlarla sepete karıştırırsın","Lekeyi ıslak bezle silip çarşafı yatağa geri serersin","Lekeli parçaları ayırıp çamaşırhaneye gönderirsin","Lekeli parçaları katlayıp oda dolabına kaldırırsın"],"dogru":2,"aciklama":"Lekeli takımlar diğerlerinden ayrılarak çamaşırhaneye gönderilir; böylece leke özel işlem görür. Karıştırmak lekeyi gözden kaçırtır, leke bulunan çarşafı yeniden sermek ise hijyen kuralına aykırıdır.","konu":"3.2.1"},{"id":"kh1-3-s141","tur":"senaryo","durum":"Öğleden sonra 15.00. Bir aile için 305 numaralı odaya portatif yatak kuracaksın; yatağın konulacağı köşede bir koltuk ve küçük bir masa var.","soru":"Ne yaparsın?","secenekler":["Yatağı koltuğun yanına sıkıştırıp açılabildiği kadar açarsın","Portatif yatak koymaktan vazgeçip aileyi resepsiyona yollarsın","Yatağı koridorda açıp odaya hazır hâlde taşırsın","Eşyaları kenara alıp yeri açar, yatağı sabitlersin"],"dogru":3,"aciklama":"Portatif yatağın konulacağı yerde eşya varsa kenara alınarak yer açılır, yatak düzgünce açılıp sabitlenir. Sıkıştırılmış yatak güvenli ve rahat olmaz; talebi geri çevirmek ise konuğun isteğini karşılamaz.","konu":"3.2.10"},{"id":"kh1-3-s142","tur":"senaryo","durum":"Sabah 10.45. Bir odanın yatağını yaparken battaniyeyi serdin ve etiketinin başucu tarafında kaldığını fark ettin. Odaya yeni konuk yarım saat sonra gelecek.","soru":"Ne yaparsın?","secenekler":["Etiketi içeri katlayıp kimse görmez diye düşünürsün","Battaniyeyi çevirip etiketi ayak ucuna serersin","Yastığı etiketin üzerine koyup örtersin","Etiket küçük diye olduğu gibi bırakırsın"],"dogru":1,"aciklama":"Battaniye çevrilerek etiketi konuğun görmeyeceği ayak ucuna gelecek şekilde serilir. Etiketi katlamak, örtmek ya da olduğu gibi bırakmak başucundaki düzeni bozar; sorun serme aşamasında giderilir.","konu":"3.2.5"}],"siralamalar":[{"id":"kh1-3-r01","konu":"3.1.2","baslik":"Kat arabasını yatak yapımına hazırlama","yonerge":"Oda görevlisi olarak işe başlarken arabanı hazırlama adımlarını sıraya koy.","adimlar":["Kat şefinden günlük iş programını öğren.","Sorumlu olduğun odaların oda durum raporunu al.","Kat arabanı al.","Yatak yapımı için gereken tekstil malzemesini arabaya yerleştir.","Malzeme ihtiyaç listesine bakarak arabanın eksiksiz olduğunu kontrol et."],"aciklama":"Önce hangi odalarda çalışacağını öğrenirsin, sonra arabayı o odaların ihtiyacına göre doldurursun ve en son listeyle eksik olmadığını doğrularsın."},{"id":"kh1-3-r02","konu":"3.2","baslik":"Yatak yapımının sırası","yonerge":"Konuk odasında bir yatağı baştan sona hazırlama sırasını kur.","adimlar":["Temiz yatak koruyucuyu yatağa ser.","Alt çarşafı ser ve köşeleri zarf şeklinde katla.","Üst çarşafı ser.","Battaniyeyi ya da pikeyi ser.","Yastıkları kılıflarına geçirip yerlerine yerleştir; yatak örtüsünü ser ve düzelt."],"aciklama":"Malzemeler alttan üste doğru serilir: koruyucu en altta, ardından alt çarşaf, üst çarşaf ve battaniye ya da pike gelir; yastık ve örtü işlemleri en sonda tamamlanır."},{"id":"kh1-3-r03","konu":"3.2","baslik":"Yorganlı yatak yapımı","yonerge":"Yorganlı (french) yatağı yaparken adımları sıraya koy.","adimlar":["Yataktaki kirli çarşafları topla; yorganı ve yastığı koltuğa koyarak yatağı havalandır.","Yatağı ve bazayı kontrol edip lekeleri sil.","Yatak koruyucuyu lastiklerinden geçirerek tak.","Alt çarşafı ser; başucunu paketle, köşeleri zarf şeklinde katla.","Nevresimli yorganı ser ve yastıkları yerleştir."],"aciklama":"Önce kirli takım çıkarılır ve yatak havalanırken kontrol edilir; sonra alttan üste doğru koruyucu, alt çarşaf ve nevresimli yorgan gelir."},{"id":"kh1-3-r04","konu":"3.2.1","baslik":"Kirli yatak takımını toplama","yonerge":"Çıkış yapılan odada yatağı soymaya kadar olan adımları sıraya koy.","adimlar":["Kat arabanı geçişi engellemeyecek şekilde oda kapısına yakın bırak.","Kapıya üç kez nazikçe vurup “Housekeeping” diye seslen; bu işlemi iki kez daha yinele.","Ses gelmezse kapıyı pas anahtarıyla aç, kapıya “Oda Görevlisi” kartını as ve kapıyı açık tut.","Kirli yatak takımını topla; arasında konuk eşyası kalıp kalmadığına bak.","Kirlileri kirli çamaşır sepetine koy, lekeli olanları ayır."],"aciklama":"Önce araba yerleştirilir; kapıda üç vuruş ve seslenme iki kez daha yinelenerek konuğa haber verilir. Yanıt gelmezse kapı pas anahtarıyla açılır, odaya girince önce yatak takımı toplanır, eşya kontrolü yapılır, kirliler en son sepete gider."},{"id":"kh1-3-r05","konu":"3.2.6","baslik":"Yastık kılıfı takma","yonerge":"Yastığa kılıf geçirme adımlarını sıraya koy.","adimlar":["Kılıfın açık tarafı sana gelecek şekilde yatağa ser.","Yastığı kılıfın üzerine koyup boyuna ikiye katla; bir elinle tut ve kılıfı aç.","Yastığı kılıfın içine yerleştir; köşelerini kılıfın köşelerine ve açık uçtaki kat yerine oturt.","Açık uçları pencereye bakacak şekilde yastığı yerine koy."],"aciklama":"Önce kılıf serilir ve yastık katlanır; yastık kılıfa girince köşeleri kılıfa oturtulur ve yastık, açık ucu pencereye bakacak biçimde yerleştirilir."},{"id":"kh1-3-r06","konu":"3.2.10","baslik":"Bebek karyolası hazırlama","yonerge":"Bebek karyolasını kurup hazırlama adımlarını sıraya koy.","adimlar":["Karyolayı, yatağı, bebek takımını ve sıvı geçirmez alezi odaya getir.","Bebek karyolasını kur.","Yatağın üzerine sıvı geçirmez alezi ser.","Alt çarşafı alezin üzerine yerleştir, yan tarafı yatağın altına sıkıştır.","Üst çarşafı yerleştir ve düzelt.","Mevsime göre battaniye, yorgan ya da pike ser; hijyen için nevresim geçir ya da üst çarşafla kapla.","Yastık kılıfını yastığa geçirip yerine koy.","Yatak örtüsü kullanıldıysa düzeltip kontrol et."],"aciklama":"Karyola önce kurulur; sonra alttan üste doğru alez, çarşaflar ve örtüler gelir; yastık ve örtü kontrolü en sona kalır."},{"id":"kh1-3-r07","konu":"3.2.10","baslik":"Portatif yatak hazırlama","yonerge":"Odaya ilave edilen portatif yatağı hazırlama adımlarını sıraya koy.","adimlar":["Yatağın konulacağı yerdeki eşyaları kenara alarak yer aç.","Katlı yatağı düzgünce aç ve belirlenen yere sabitle.","Temiz yatak koruyucuyu yerleştir.","Alt çarşafı ser; köşeleri zarf şeklinde katlayıp yatağın altına sıkıştır.","Üst çarşafı ser ve düzelt.","Battaniye, yorgan ya da pikeyi ser; köşeleri üst çarşafla birlikte katla ve sıkıştır.","Yastığı kılıfına geçirip yerine yerleştir.","Yatak örtüsünü ser ve düzelt."],"aciklama":"Önce yer açılır ve yatak kurulur; sonra normal yatakta olduğu gibi alttan üste doğru malzeme serilir."},{"id":"kh1-3-r08","konu":"3.2.10","baslik":"Çekyatı yatağa dönüştürme","yonerge":"Çekyatı yatak olarak hazırlama adımlarını sıraya koy.","adimlar":["Odadaki çekyatı (kanepeyi) açarak sabitle.","Temiz yatak koruyucuyu ser.","Alt çarşafı ser; köşeleri zarf şeklinde katlayıp çekyatın köşelerine sıkıştır.","Üst çarşafı ser.","Battaniye ya da pikeyi ser; köşeleri üst çarşafla birlikte katla ve sıkıştır.","Yastık kılıfını yastığa geçirip yerine yerleştir.","Yatak örtüsünü ser ve yatağın üzerini düzelt.","Hazırlığı kontrol edip eksiklikleri gider."],"aciklama":"Çekyat önce yatak hâline getirilir; sonra alttan üste malzeme serilir ve son kontrolle iş tamamlanır."},{"id":"kh1-3-r09","konu":"3.2.11","baslik":"Turn down servisi","yonerge":"Yatak açma servisinde odayı akşam için hazırlama adımlarını sıraya koy.","adimlar":["Yatak örtüsünü katlayıp odadaki uygun bir dolaba kaldır.","Battaniye ve üst çarşafı geriye doğru üçgen biçiminde katla; konuğun pijama ya da geceliğini yatağın üzerine bırak.","Balkon kapısını ve pencereleri kontrol edip açıksa kapat, ardından perdeleri kapat.","Son kontrolü yap; sensörlü ışık yoksa bir ışığı açık bırakarak odadan çık."],"aciklama":"Önce örtü kaldırılıp yatak açılır ve pijama bırakılır; pencere ve perde işi odanın güvenliğini sağlar, ışık kontrolü odadan çıkarken en sonda yapılır."},{"id":"kh1-3-r10","konu":"3.3.3","baslik":"Havludan kuğu","yonerge":"Havludan kuğu çifti yapmak için adımları sıraya koy.","adimlar":["Banyo havlusunu düz bir zemine ser.","Uzun kenarları köşelerinden ortaya doğru eşit ve sıkı şekilde yuvarla.","İki köşesinden katlayarak havluya üçgen şeklini ver.","Sivri uçtan yukarı doğru havluyu kıvırarak kuğunun boynunu oluştur.","Sivri ucu öne doğru kıvırarak kuğunun başını tamamla.","Diğer banyo havlusuyla aynı yöntemi uygulayıp ikinci kuğuyu yap.","Kuğuları gagalarından birleştirip başlarıyla kalp şekli ver.","Baş havlusunu düz bir zemine ser ve akordiyon şeklinde katla.","Ortasından katlayarak kuğunun kuyruğunu oluştur; istersen çiçekle süsle."],"aciklama":"Önce gövde şekillenir, sonra boyun ve baş yapılır; ikinci kuğu birincinin aynısıdır. Kuğular birleştirildikten sonra baş havlusu akordiyon katlanıp kuyruk olur."},{"id":"kh1-3-r11","konu":"3.3.3","baslik":"Havludan sepet","yonerge":"Banyo ve baş havlularından sepet figürü yapmak için adımları sıraya koy.","adimlar":["Baş havlularını uzun kenarlarından sıkıca yuvarla; banyo havlularını uzun kenarlarından ortaya doğru katla.","Katlanan iki banyo havlusunu üst üste koy.","Yuvarlanmış baş havlularını banyo havlularının uç kısmına yerleştir.","Banyo havlularını rulo şeklinde sar.","Ruloyu kurdeleyle bağla; baş havlularının sivri uçlarını birleştirip kıvırarak sepet sapını oluştur."],"aciklama":"Gövde (banyo havluları) hazırlanmadan baş havluları yerleştirilemez; sap ancak rulo bağlandıktan sonra sabit durur."},{"id":"kh1-3-r12","konu":"3.3.3","baslik":"Havludan yengeç","yonerge":"Banyo ve baş havlusundan yengeç yapmak için adımları sıraya koy.","adimlar":["Banyo havlusunu düz bir zemine ser ve kısa kenarından rulo yap.","Diğer kısa kenarı da havlunun ortasına doğru eşit rulo yap.","Havlunun uçlarından tutup dışa doğru çevirerek gövdeyi ve ayakları oluştur.","Baş havlusunu üç kat şeklinde katla ve ayaklara sararak yengecin kafasını oluştur.","Baş havlusunun kenarlarını gövdenin altına katla.","Ayakları düzeltip keçeden göz ve ağız yap."],"aciklama":"Önce gövde ve ayaklar çıkar; kafa onların üzerine sarıldığı için sonra gelir, göz ve ağız en son eklenir."},{"id":"kh1-3-r13","konu":"3.3.3","baslik":"Havludan kaplumbağa","yonerge":"Kaplumbağa figürünü yapmak için adımları sıraya koy.","adimlar":["Banyo havlusunun kısa kenarından rulo yap.","Havlunun uçlarından tutup dışa çevirerek gövdeyi ve ayakları oluştur.","İkinci banyo havlusunun dört ucunu ortada birleştirip dışa çevirerek kabuğu yap.","Kabuğu ayakların üzerine yerleştir.","Baş havlusundan yapılan kafayı ayakların oluştuğu bölümün alt kısmına yerleştir.","Kafa ve kuyruğu düzeltip keçe ya da düğmeden göz yap."],"aciklama":"Kabuk ayakların üzerine oturduğu için önce ayaklar, sonra kabuk gelir; kafa en sonda altına yerleşir."},{"id":"kh1-3-r14","konu":"3.3.3","baslik":"Figüre hazırlanma","yonerge":"Havlu figürü uygulamasına başlamadan önceki hazırlık adımlarını sıraya koy.","adimlar":["Kişisel bakım ve hijyen kurallarına uy, takılarını çıkar.","İşletmenin belirlediği formayı giy ve isimliğini tak.","Kat şefinden iş programını öğren.","Sorumlu olduğun odaların oda durum raporunu al.","Kat pas anahtarını imza karşılığı teslim al.","Kat arabanı al ve yeterli havlu ile süsleme malzemesini yükle.","Figür için malzeme listesini kontrol et."],"aciklama":"Önce kişisel hazırlık, sonra iş bilgisi, ardından anahtar ve araç; malzeme kontrolü yola çıkmadan önceki son bakıştır."}],"acikSorular":[{"id":"kh1-3-y01","konu":"3.2.3","soru":"Kat görevlisi Elif, bir konuk odasında alt çarşafı serdi ancak köşeler buruşuk kaldı ve çarşaf yatağın ortasına oturmadı. Alt çarşaf açma işleminde çarşafın ortası ve köşeleri için yapılması gerekenleri yazınız; zarf köşenin yatağın düzgün görünmesine nasıl katkı sağladığını açıklayınız.","olcut":[{"metin":"Alt çarşafın yatak koruyucunun üzerine iki yana eşit sarkacak şekilde serildiğini belirtir.","puan":20},{"metin":"Orta kat çizgisinin yatağın ortasına hizalanması gerektiğini yazar.","puan":20},{"metin":"Köşelerin yatak başından başlanarak zarf biçiminde katlandığını açıklar.","puan":25},{"metin":"Zarf köşenin, köşelerin yatağın altına yerleştirilmesiyle çarşafı yerinde tuttuğunu ve yatağın düzgün görünmesini sağladığını açıklar.","puan":35}],"ornek":"Alt çarşaf yatak koruyucunun üzerine iki yana eşit sarkacak biçimde serilir. Çarşafın orta kat çizgisi yatağın ortasına hizalanır. Köşeler yatak başından başlanarak zarf biçiminde katlanır ve yatağın altına yerleştirilir. Zarf köşe çarşafın kaymasını önler ve yatağa düzgün bir köşe görünümü verir; böylece yatak toplu ve bakımlı görünür.","ipucu":"Çarşafın ortasının ve köşelerinin ne işe yaradığını düşünün; köşelerin yatağın altına nasıl yerleştirildiğini ve bunun çarşafa ne kazandırdığını bulun."},{"id":"kh1-3-y02","konu":"3.3.2","soru":"Bir otelin müdürü, konukların hem odada hem havuz kenarında rahat etmesini istiyor. Banyo havlusu ile plaj havlusunun kullanım yerlerini karşılaştırınız; plaj havlusunun konuğa ulaştırılması için işletmelerde uygulanan iki yöntemi, konuğun havluyu nasıl aldığını göstererek yazınız ve iki havlu türünde genellikle hangi rengin tercih edildiğini belirtiniz.","olcut":[{"metin":"Banyo havlusunun konuk odasında vücudu kurulamak için kullanıldığını belirtir.","puan":20},{"metin":"Plaj havlusunun sahil ve havuz kenarında kullanıldığını belirtir.","puan":20},{"metin":"Plaj havlusunun konuğa ulaştırılması için iki yöntemi, konuğun havluyu nasıl aldığını belirterek yazar: check-in sırasında oda kartıyla birlikte verilen havlu kartıyla sahilde ya da havuz kenarındaki standdan havlu almak; havluların şezlongların üzerinde hazır bulundurulması.","puan":35},{"metin":"İki havlu türünün genellikle tercih edilen rengini karşılaştırır: banyo havlusunda genellikle beyaz, plaj havlusunda genellikle renkli.","puan":25}],"ornek":"Banyo havlusu konuk odasında vücudu kurulamak için kullanılır ve genellikle beyaz tercih edilir. Plaj havlusu ise sahilde ve havuz kenarında kullanılır, genellikle renklidir. Plaj havlusunu konuğa ulaştırmanın bir yolu, check-in sırasında oda kartıyla birlikte havlu kartı vermektir; konuk bu kartla sahilde ya da havuz kenarındaki standdan havlusunu alır. Bazı işletmelerde ise havlular şezlongların üzerinde hazır bulunur.","ipucu":"Önce iki havlunun kullanım yerini yan yana yazın; sonra sahilde konuğun havluya hangi iki yolla ulaştığını düşünün."}]},{"ders":"kat-hizmetleri-10","sinif":10,"unite":4,"baslik":"Banyo Temizlik İşlemleri","onay":true,"kazanimlar":["İş sağlığı ve güvenliği standartlarına uygun olarak konuk odasındaki banyoyu temizler.","Ulusal standartlara ve işletme prosedürüne uygun olarak konuk banyosuna buklet malzemelerini yerleştirir."],"soz":"Banyo, odanın risklerin en yoğun olduğu yeridir; temizliği ve bukleti konuğun güvenini belirler.","dersler":[{"baslik":"Konuk Banyoya Girdiğinde","ilk":"kh1-4-001"},{"baslik":"Banyonun Donanımı","ilk":"kh1-4-005"},{"baslik":"Banyo Neden Risklidir?","ilk":"kh1-4-011"},{"baslik":"Doğru Yüzeye Doğru Araç","ilk":"kh1-4-015"},{"baslik":"Bezin Rengi Ne Söyler?","ilk":"kh1-4-020"},{"baslik":"Çekçek, Kazıyıcı ve Diğerleri","ilk":"kh1-4-025"},{"baslik":"Şişenin Üzerindeki Etiket","ilk":"kh1-4-031"},{"baslik":"Sıçrama Anında İlk Hamle","ilk":"kh1-4-037"},{"baslik":"Kaymadan Önce Topla","ilk":"kh1-4-042"},{"baslik":"Küçük Arızanın Büyük Bedeli","ilk":"kh1-4-049"},{"baslik":"Dolu Oda, Boş Oda","ilk":"kh1-4-055"},{"baslik":"Hasarın Kaydı","ilk":"kh1-4-229"},{"baslik":"Duvardaki Küçük Cihazlar","ilk":"kh1-4-059"},{"baslik":"Elektrik ve Su Bir Arada","ilk":"kh1-4-064"},{"baslik":"Doğru Ürün, Boşa Geçmeyen Süre","ilk":"kh1-4-070"},{"baslik":"Üç Yüzey, Üç Yöntem","ilk":"kh1-4-073"},{"baslik":"Küvetten Klozete","ilk":"kh1-4-077"},{"baslik":"Duvar, Lavabo ve Gider","ilk":"kh1-4-082"},{"baslik":"Camın Parıltısı","ilk":"kh1-4-086"},{"baslik":"Metal Parlasın, Kireç Tutmasın","ilk":"kh1-4-091"},{"baslik":"Görünmeyen Risk: Legionella","ilk":"kh1-4-097"},{"baslik":"Boş Odada Musluk Açmak","ilk":"kh1-4-103"},{"baslik":"Buharla Temizlik","ilk":"kh1-4-110"},{"baslik":"Zeminde Son Söz","ilk":"kh1-4-117"},{"baslik":"Su Her Zaman Bulunmaz","ilk":"kh1-4-124"},{"baslik":"Banyoda Evinde Hissetmek","ilk":"kh1-4-151"},{"baslik":"Banyo Listesinde Neler Var?","ilk":"kh1-4-157"},{"baslik":"Duşa Girmeden Önce","ilk":"kh1-4-161"},{"baslik":"Lavabo ve Küvet Kenarı","ilk":"kh1-4-166"},{"baslik":"Sabah Hazırlığı Kutusu","ilk":"kh1-4-170"},{"baslik":"Küçük Ama Hijyenik","ilk":"kh1-4-175"},{"baslik":"Banyodaki Kartlar Ne Diyor?","ilk":"kh1-4-180"},{"baslik":"Bütçe ve Küçük Ayrıntılar","ilk":"kh1-4-231"},{"baslik":"Hangi Odaya Hangi Set?","ilk":"kh1-4-186"},{"baslik":"Eksik Ne, Ekstra Kime?","ilk":"kh1-4-191"},{"baslik":"Uygulama Günü Hazırlığı","ilk":"kh1-4-196"},{"baslik":"Göze Hoş, Ele Yakın","ilk":"kh1-4-199"},{"baslik":"Logo Kime Bakıyor?","ilk":"kh1-4-204"},{"baslik":"Son Dokunuş, Son Bakış","ilk":"kh1-4-209"},{"baslik":"Havlu Nereye Gider?","ilk":"kh1-4-213"},{"baslik":"Logolu Havlu Nasıl Katlanır?","ilk":"kh1-4-218"},{"baslik":"Bornoz ve Havlunun Uyumu","ilk":"kh1-4-223"}],"kavramlar":[{"id":"kh1-4-001","konu":"4.1","terim":"Banyo","ingilizce":"Bathroom","tanim":"Konuğun kişisel temizlik ve tuvalet ihtiyacını giderdiği, nemli ve ıslak zeminli oda bölümüdür.","ornek":"Sabah 08.00’de Bodrum’daki otelin 214 numaralı odasında kahvaltıya hazırlanan konuk önce banyoya girer; duş alma, diş fırçalama ve tıraş burada biter.","sektor":"Banyo, konuk odasının vazgeçilmez bölümüdür ve konaklama süresinin sağlıklı tamamlanmasına hizmet eder. Bu yüzden tasarımına ve temizliğine özel önem verilir.","iliskili":["kh1-4-002"],"kontrol":null,"gorsel":"t10d-otel-banyosu-mermer"},{"id":"kh1-4-002","konu":"4.1","terim":"Banyonun işletme kalitesine etkisi","ingilizce":"Bathroom as a quality indicator","tanim":"Konuk odasındaki banyonun bakımına bakılarak işletmenin genel kalitesi hakkında yargıya varılmasıdır.","ornek":"Kapadokya’daki bir otelde sabah 07.30’da duş alan konuk, banyo aynasında su lekesi görür ve kahvaltıda resepsiyona “Odamın temizliği özensiz” diye not bırakır.","sektor":"Konaklama tesisine ait konuk odaları işletmenin kalitesini gösterir. Banyodaki tek bir leke bile konuğun otel hakkındaki izlenimini bozabilir.","iliskili":["kh1-4-001","kh1-4-003"],"kontrol":null,"gorsel":"t11d-banyo-kalite"},{"id":"kh1-4-003","konu":"4.1","terim":"Tesise göre değişen banyo","ingilizce":"Bathroom types","tanim":"Tesisin fiziki koşullarına ve oda tipine göre banyo donanımının değişmesidir.","ornek":"Fethiye’deki butik otelde aile odasının banyosunda küvet varken tek kişilik odalarda yalnızca duş kabini vardır; görevli temizliğe başlamadan önce odanın banyo tipine bakar.","sektor":"Standart bir banyo küvet ya da duş kabini, lavabo ve klozetten oluşur; bazı banyolarda hidromasajlı küvet de bulunur. Teknoloji ve yapı sektörü geliştikçe banyo donanımlarının türü, kalitesi ve çeşitliliği artmıştır; temizlik yöntemi ve malzeme seçimi banyo tipine göre belirlenir.","iliskili":["kh1-4-002","kh1-4-004"],"kontrol":null,"gorsel":"t11d-banyo-sade"},{"id":"kh1-4-004","konu":"4.1","terim":"Nemli ve ıslak alan","ingilizce":"Wet area","tanim":"Su ve buhar nedeniyle sürekli nemli kalan, bakteri ve mantarın kolay çoğaldığı banyo ortamıdır.","ornek":"Alanya’da yaz sezonunda penceresi kapalı kalan bir banyonun kapısını açan görevli küf kokusu alır; pencereyi açıp banyoyu havalandırır.","sektor":"Bakteri, mantar ve kötü koku oluşmasın diye banyolar sık sık havalandırılır ve bu alanların temizliğine daha fazla özen gösterilir.","iliskili":["kh1-4-003"],"kontrol":null},{"id":"kh1-4-005","konu":"4.1","terim":"Küvet","ingilizce":"Bathtub","tanim":"İçinde uzanarak ya da oturarak yıkanılan, sabit banyo donanımıdır.","ornek":"Marmaris’te çocuklu bir ailenin kaldığı 305 numaralı odada küvetin gideri, çıkış sabahı saç ve sabun artıklarıyla doludur.","sektor":"Küvetin giderinde biriken sabun ve kir kalıntıları temizliğe başlamadan önce alınır. Küvet ve hidromasajlı küvetin temizlik adımları aynıdır.","iliskili":["kh1-4-006"],"kontrol":null,"gorsel":"t10d-kuvet-otel"},{"id":"kh1-4-006","konu":"4.1","terim":"Duş kabini","ingilizce":"Shower cubicle","tanim":"Cam ya da benzeri yüzeylerle çevrilmiş, duşun yapıldığı kapalı bölmedir.","ornek":"Kuşadası’ndaki bir otelin 120 numaralı odasında duş alan konuğun ardından kabinin camı sabun ve su lekesiyle buğulu kalır.","sektor":"Geniş cam yüzeylere sahip olduğu için kireç ve yağ artıkları kolay birikir; bu yüzden duş kabini itina ile temizlenir.","iliskili":["kh1-4-005","kh1-4-007"],"kontrol":null,"gorsel":"t11d-dus-kabini"},{"id":"kh1-4-007","konu":"4.1","terim":"Jakuzi (hidromasajlı küvet)","ingilizce":"Whirlpool bath","tanim":"Suyu jetlerle hareket ettiren, bazı banyolarda küvet yerine bulunan küvet türüdür.","ornek":"Bodrum’daki bir suit odada görevli, hidromasajlı küvetin giderindeki saç ve sabun artıklarını temizliğe başlamadan önce alır.","sektor":"Bu donanım gündelik dilde jakuzi adıyla da anılır. Hidromasaj gibi sıcak ve nemli su sistemleri legionella takibinin konusudur.","iliskili":["kh1-4-006","kh1-4-008"],"kontrol":null,"gorsel":"t10f-suit-jakuzi-kuvet"},{"id":"kh1-4-008","konu":"4.1","terim":"Lavabo","ingilizce":"Washbasin","tanim":"Elleri ve yüzü yıkamak için kullanılan, musluklu banyo donanımıdır.","ornek":"Sabah 09.30’da Çeşme’de bir odayı temizleyen görevli, lavabo süzgecinde toplanan saç tellerini temizliğe başlamadan alır.","sektor":"Lavabo banyonun en sık kullanılan donanımıdır; giderindeki sabun ve kir artıkları her temizlikte alınır.","iliskili":["kh1-4-007","kh1-4-009"],"kontrol":null,"gorsel":"lavabo"},{"id":"kh1-4-009","konu":"4.1","terim":"Klozet","ingilizce":"Toilet (WC)","tanim":"Tuvalet ihtiyacının giderildiği, su rezervuarlı banyo donanımıdır.","ornek":"Trabzon’daki bir otelde öğle 12.00’de odayı yenileyen görevli, banyoya girer girmez klozetin sifonunu çekerek işe başlar.","sektor":"Klozet, WC temizliğinin merkezindeki donanımdır; banyoda en yüksek hijyen dikkati burada gösterilir.","iliskili":["kh1-4-008","kh1-4-010"],"kontrol":null,"gorsel":"t11d-klozet-otel"},{"id":"kh1-4-010","konu":"4.1","terim":"Bide","ingilizce":"Bidet","tanim":"Klozet kullanımından sonra belden aşağı bölgenin yıkanarak kişisel temizliğin yapıldığı, klozetin yanındaki donanımdır.","ornek":"Bursa’daki bir otelde 408 numaralı odanın banyosunda bide olduğunu fark eden görevli, WC temizliğini klozetle birlikte bide için de yapar.","sektor":"Kullanım alanının az olması ve banyoların yeterli genişlikte olmaması nedeniyle çoğu işletmede bide bulunmaz. Bulunduğu odada klozetle birlikte temizlenir ve dezenfekte edilir.","iliskili":["kh1-4-009"],"kontrol":null,"gorsel":"t10d-bide-musluklu"},{"id":"kh1-4-011","konu":"4.1","terim":"Banyoda iş sağlığı ve güvenliği","ingilizce":"Occupational health and safety in the bathroom","tanim":"Banyodaki kayma, yaralanma ve zehirlenme risklerine karşı çalışanı korumak için alınan önlemlerin bütünüdür.","ornek":"Antalya’da öğleden sonra banyoya giren Selin, zeminde şampuan artıkları görünce önce eldivenini giyer, kayma tehlikesini ortadan kaldırmadan temizliğe başlamaz.","sektor":"Banyo, kayma, yaralanma ve zehirlenme riskinin en yoğun olduğu alandır. Bu yüzden kimyasal ve suyla çalışırken iş sağlığı ve güvenliği tedbirlerine mutlaka uyulur.","iliskili":["kh1-4-012"],"kontrol":null},{"id":"kh1-4-012","konu":"4.1","terim":"Banyo temizliğinde KKD","ingilizce":"Personal protective equipment (PPE) in bathroom cleaning","tanim":"Çalışanı kimyasal ve su temasından, enfeksiyon riskinden koruyan eldiven ve maske gibi kişisel koruyucu donanımların bütünüdür.","ornek":"Sabah 08.15’te kireç çözücü kullanacak Burak, banyoya girmeden önce eldiven giyer ve maskesini takar.","sektor":"Eldiven enfeksiyon riskine ve kimyasalla temasa karşı, maske yoğun kimyasalın solunum yollarını etkilemesine karşı kullanılır. Oda temizlik görevlisi KKD’sini temizliğe başlamadan önce takar.","iliskili":["kh1-4-011","kh1-4-013"],"kontrol":null},{"id":"kh1-4-013","konu":"4.1","terim":"Banyoda hijyen","ingilizce":"Hygiene in the bathroom","tanim":"Bakteri, mantar ve kokuyu önleyen temizlik koşullarının banyoda sağlanmasıdır.","ornek":"Muğla’daki bir otelde kat şefi, havasız kalan banyolarda bakteri oluşmasın diye temizlik sonrası havalandırmanın yapılıp yapılmadığını kontrol eder.","sektor":"Hijyene önem verilen bir banyoda personel ve konuk için tehlikeli sonuçların ortaya çıkma ihtimali azalır. Yeterince temiz olmayan nemli banyolarda bazı bakteriler ciddi hastalıklara yol açabilir.","iliskili":["kh1-4-012","kh1-4-014"],"kontrol":null,"gorsel":"h1a-sabunla-el-yikama"},{"id":"kh1-4-014","konu":"4.1","terim":"Sanitasyon","ingilizce":"Sanitation","tanim":"Yüzeylerdeki mikroorganizma sayısını sağlığa zarar vermeyecek düzeye indiren temizlik uygulamalarıdır.","ornek":"Kuşadası’nda sabah brifinginde kat şefi, “Klozeti yalnız silmek yetmez; kimyasalın bekleme süresini de tamamlayın” diyerek ekibine sanitasyon kuralını hatırlatır.","sektor":"Banyo temizliği doğru araç gereçle ve belli bir sıraya göre yapılır; bu sırada hijyen kurallarının yanında sanitasyon kurallarına da uyulur. Kimyasalın etki süresini beklemek bu uygulamanın parçasıdır.","iliskili":["kh1-4-013"],"kontrol":null},{"id":"kh1-4-015","konu":"4.1.1","terim":"Banyo temizliğinde araç gereç seçimi","ingilizce":"Selecting bathroom cleaning equipment","tanim":"Temizlenecek alana ve kire uygun araç gerecin işe başlamadan önce belirlenmesidir.","ornek":"Datça’daki bir otelde Kemal, duş kabininin camı için çizmeyen sünger ve çekçek seçer; fayans derzleri için ise fırçayı ayırır.","sektor":"Araç gereçleri tanımayan görevli emek, zaman ve malzeme kaybına neden olur. Başarılı bir temizlik, doğru alanda doğru araç gerecin kullanılmasıyla oluşur.","iliskili":["kh1-4-016"],"kontrol":null},{"id":"kh1-4-016","konu":"4.1.1","terim":"Temizlik yönteminin belirlenmesi","ingilizce":"Choosing the cleaning method","tanim":"Kullanılacak yöntemin, temizlik maddelerinin içeriğine ve kullanılan makine ile gereçlerin özelliklerine göre kararlaştırılmasıdır.","ornek":"Alanya’daki bir otelin VIP odasında derz araları kararmıştır; görevli Murat, kimyasalın etiketini okuyup fırçalı yöntemi seçer.","sektor":"Temizlik yöntemi, kullanılan madde ve gereçlerin özelliklerinin bilinmesine bağlıdır. Bilmeden seçilen yöntem yüzeye zarar verebilir.","iliskili":["kh1-4-015","kh1-4-017"],"kontrol":null,"gorsel":"t12d-banyo-zemin-makinesi"},{"id":"kh1-4-017","konu":"4.1.1","terim":"Banyo temizlik malzemeleri","ingilizce":"Bathroom cleaning supplies and equipment","tanim":"Renkli bez, fırça, eldiven, maske, sünger, kâğıt havlu, kimyasal, kova, mop, çekçek, faraş-fırça seti, cam peluşu ve kazıyıcı gibi, banyo temizliğinde kullanılan araç gereçlerin tümüdür.","ornek":"Sabah 08.00’de Selin, kat deposundan eksik kalan cam peluşunu ve kazıyıcıyı alıp temizlik basketine ekler.","sektor":"Bu listeye elektrikli süpürge de girer. Eksik malzeme işe başlamadan önce kat deposundan tamamlanır.","iliskili":["kh1-4-016","kh1-4-018"],"kontrol":null,"gorsel":"t11b-sprey-ve-bez"},{"id":"kh1-4-018","konu":"4.1.1","terim":"Banyo temizlik basketi","ingilizce":"Bathroom cleaning caddy","tanim":"Görevlinin banyo için gereken bez, kimyasal ve küçük gereçleri düzenli biçimde taşıdığı sepettir.","ornek":"Kuşadası’nda sabah 08.20’de Elif, kırmızı ve sarı bezlerini basketine yerleştirip banyoya girer.","sektor":"Basket banyoya girmeden hazırlanır; böylece temizlik sırasında odadan çıkıp malzeme aramak gerekmez.","iliskili":["kh1-4-017","kh1-4-019"],"kontrol":null,"gorsel":"t12s-kova-eldiven"},{"id":"kh1-4-019","konu":"4.1.1","terim":"Kat arabasının oda sonrası düzeni","ingilizce":"Restocking the housekeeping trolley","tanim":"Görevlinin oda temizliği bittiğinde kat arabasını ve temizlik basketini düzenli bırakıp eksiklerini kat deposundan tamamlamasıdır.","ornek":"Akşam 16.30’da son odayı bitiren Mustafa, arabadaki kirli bezleri ayırır ve bitmiş kimyasalı kat deposundan yenisiyle değiştirir.","sektor":"Düzenli bırakılan kat arabası ertesi gün işe hızlı başlamayı sağlar ve eksik malzeme yüzünden temizliğin aksamasını önler.","iliskili":["kh1-4-018"],"kontrol":null},{"id":"kh1-4-020","konu":"4.1.1","terim":"Banyoda renk koduna göre bez seçimi","ingilizce":"Colour-coded cloths in the bathroom","tanim":"Banyonun farklı alanlarında hijyen için hangi renkte bezin kullanılacağını belirleyen düzendir.","ornek":"Sabah 09.00’da Burak, klozet çevresini silmek için kırmızı bezi, lavabo tezgâhını silmek için sarı bezi ayırır.","sektor":"Banyoda kırmızı bez tuvalet alanı, sarı bez lavabo ve banyo yüzeyleri için kullanılır. Mavi ve yeşil bezlerin işi işletmeye göre değişir; bu yüzden görevli işletmenin renk tablosunu uygular.","iliskili":["kh1-4-021"],"kontrol":null,"gorsel":"t12s-renkli-bezler"},{"id":"kh1-4-021","konu":"4.1.1","terim":"Mikrofiber bez","ingilizce":"Microfibre cloth","tanim":"Çok ince liflerden dokunmuş, kiri ve nemi iyi tutan, yüzeyleri çizmeden silip kurulayan temizlik bezidir.","ornek":"Çeşme’de banyo aynasını cam sille temizleyen Derya, ardından aynayı renk koduna uygun mikrofiber bezle kurular.","sektor":"Ayna, armatür ve duş başlığı gibi parlaması beklenen yüzeyler renk koduna uygun mikrofiber bezle kurulanır.","iliskili":["kh1-4-020","kh1-4-022"],"kontrol":null,"gorsel":"t15ac-mikrofiber-bez"},{"id":"kh1-4-022","konu":"4.1.1","terim":"Banyoda çapraz bulaşma","ingilizce":"Cross-contamination in the bathroom","tanim":"Bir alandaki kirin ve mikropların aynı bez, sünger ya da eldivenle başka bir alana taşınmasıdır.","ornek":"Muğla’da bir görevli klozeti sildiği kırmızı bezle lavabo tezgâhını silince mikrop, konuğun elini yıkadığı yüzeye taşınmış olur; kat şefi bezlerin renk kodunu hatırlatır.","sektor":"Temizlik sırasında çapraz bulaşmaya karşı hijyen kurallarına uygun hareket edilir: renk kodlu bezler, alana ayrılmış süngerler ve gerektiğinde eldiven değişimi bunun araçlarıdır.","iliskili":["kh1-4-021","kh1-4-023"],"kontrol":null},{"id":"kh1-4-023","konu":"4.1.1","terim":"Temizlik süngeri","ingilizce":"Cleaning sponge","tanim":"Kimyasalı yüzeye sürmek ve yüzeyi ovmak için kullanılan, renk koduna göre ayrılan temizlik gereçidir.","ornek":"Antalya’daki bir otelde görevli, lavabo için ayrılmış süngeri klozet çevresinde kullanmaz; her alanın süngerini kendi rengine göre alır.","sektor":"Yüzeye kimyasal sürülüp süngerle ovulduktan sonra yüzey beklenir ve durulanır. Renk kodlarına uymak çapraz bulaşmayı azaltır.","iliskili":["kh1-4-022","kh1-4-024"],"kontrol":null,"gorsel":"t11d-sunger"},{"id":"kh1-4-024","konu":"4.1.1","terim":"Fırça çeşitleri","ingilizce":"Scrubbing brushes (hard and soft)","tanim":"Sert ve yumuşak kıllı türleri bulunan, süngerin yetmediği yerlerde kiri ovarak çıkaran temizlik gereçleridir.","ornek":"Bodrum’daki bir otelde fayans derzlerindeki sarı lekeler süngerle çıkmayınca Kemal sert kıllı fırçaya geçer; armatürü ise yumuşak fırçayla ovar.","sektor":"Yoğun yağ ve kir birikimlerinde sünger yerine uygun fırça kullanılır. Fırçanın sertliği yüzeyin cinsine göre seçilir.","iliskili":["kh1-4-023"],"kontrol":null,"gorsel":"t11d-firca-uc"},{"id":"kh1-4-025","konu":"4.1.1","terim":"Çekçek","ingilizce":"Squeegee","tanim":"Cam, ayna, duş kabini ve duvardaki fazla suyu lastikli kenarıyla sıyırıp alan temizlik gereçidir.","ornek":"Sabah 10.30’da Aylin, duş kabinini durulayınca camdaki suyu çekçekle sıyırır.","sektor":"Çekçek fazla suyu alarak kurulama süresini kısaltır ve cam yüzeyde su lekesi kalmasını azaltır.","iliskili":["kh1-4-026"],"kontrol":null,"gorsel":"h3b-cam-silici"},{"id":"kh1-4-026","konu":"4.1.1","terim":"Cam peluşu","ingilizce":"Glass cloth","tanim":"Ayna ve cam yüzeyleri çizmeden temizlemek için kullanılan yumuşak yüzeyli bezdir.","ornek":"Kuşadası’nda Burak, banyo aynasını cam peluşuyla temizler ve ardından çekçekle “S” çizerek siler.","sektor":"Ayna büyüklüğüne göre cam peluşu ya da cam bezi seçilir; ikisi de çekçekle birlikte kullanılır.","iliskili":["kh1-4-025","kh1-4-027"],"kontrol":null},{"id":"kh1-4-027","konu":"4.1.1","terim":"Kazıyıcı","ingilizce":"Scraper","tanim":"Yüzeyde yapışmış kiri kazıyarak sökmek için kullanılan düz kenarlı el aletidir.","ornek":"Fethiye’de lavabo kenarında kuruyup yapışan diş macunu lekesini Mustafa, yüzeyi çizmemeye dikkat ederek kazıyıcıyla söker.","sektor":"Kazıyıcı yalnızca yapışıp kuruyan kirde kullanılır; yüzeyin cinsine uygunluğu önceden düşünülür.","iliskili":["kh1-4-026","kh1-4-028"],"kontrol":null,"gorsel":"t11d-kaziyici"},{"id":"kh1-4-028","konu":"4.1.1","terim":"Kova ve mop","ingilizce":"Bucket and mop","tanim":"Temizlik suyunu taşımaya yarayan kova ile zemini silmek için kullanılan, çeşitli boy ve özellikte moplardır.","ornek":"Akşam 17.00’de banyo zeminine geçen Aylin, dar banyo için küçük boy mopu seçer.","sektor":"Moplar banyonun boyutuna ve zemin türüne göre seçilir; temiz tutulan mop zemine kir taşımaz.","iliskili":["kh1-4-027","kh1-4-029"],"kontrol":null,"gorsel":"t11d-kova-mop"},{"id":"kh1-4-029","konu":"4.1.1","terim":"Faraş ve fırça seti","ingilizce":"Dustpan and brush set","tanim":"Zemindeki kuru kiri ve küçük atıkları süpürüp toplamaya yarayan el aletidir.","ornek":"Çıkış yapılan bir odada banyo zeminine düşüp kırılmış küçük bir tarağın parçalarını Burak, eldiveniyle ve faraşla toplar.","sektor":"Zemindeki küçük atıklar elle değil faraşla toplanır; böylece hem el korunur hem zemin tek hamlede temizlenir.","iliskili":["kh1-4-028","kh1-4-030"],"kontrol":null,"gorsel":"t11e-sari-faras-fircasi"},{"id":"kh1-4-030","konu":"4.1.1","terim":"Kâğıt havlu","ingilizce":"Paper towel","tanim":"Yüzey ve donanımların hızla silinmesi için kullanılan, tek kullanımlık emici kâğıttır.","ornek":"Sabah 10.50’de Muğla’daki otelin 214 numaralı odasında banyoyu bitiren Elif, musluktaki son su damlalarını kâğıt havluyla alır ve havluyu çöp torbasına atar.","sektor":"Tek kullanımlık olduğu için bez gibi yıkanıp tekrar kullanılmaz; kullanıldıktan sonra çöp torbasına atılır.","iliskili":["kh1-4-029"],"kontrol":null,"gorsel":"t11d-kagit-havlu-kutusu"},{"id":"kh1-4-031","konu":"4.1.1","terim":"Doğru yüzeye doğru kimyasal","ingilizce":"Right chemical for the right surface","tanim":"Kirin ve yüzeyin türüne göre farklı temizlik maddesinin seçilmesi ilkesidir.","ornek":"Bodrum’da bir otelde pirinç kaplı armatürü fayans temizleyicisiyle silen yeni görevli Kerem, armatürün mat kaldığını görünce kat şefinden doğru ürünü öğrenir.","sektor":"Yanlış kimyasal hem insan sağlığını tehdit edebilir hem de kullanım alanlarına büyük zarar verebilir. Doğru kimyasal bile yanlış uygulanırsa istenen verim alınamaz.","iliskili":["kh1-4-032"],"kontrol":null,"gorsel":"t11d-sprey-temizleyici"},{"id":"kh1-4-032","konu":"4.1.1","terim":"Banyoda kimyasal kullanım kuralları","ingilizce":"Chemical safety rules","tanim":"Temizlik maddelerinin kazasız ve etkili kullanılması için uyulan kurallar bütünüdür.","ornek":"Antalya’daki bir otelin eğitiminde kat şefi, kimyasal kurallarını duvara asılı panodan tek tek okuyarak anlatır.","sektor":"Kurallara uyulduğunda iş sağlığı ve güvenliği sağlanır, kazaların önüne geçilir. Kurallar talimata uyma, karıştırmama, doğru miktar, deneme, KKD, havalandırma, sıçrama ve etiket konularında toplanır.","iliskili":["kh1-4-031","kh1-4-033"],"kontrol":null},{"id":"kh1-4-033","konu":"4.1.1","terim":"Banyoda kimyasalları karıştırmama ve kapağı kapatma","ingilizce":"Never mix cleaning chemicals and always close the lids","tanim":"Farklı temizlik maddelerinin birbirine karıştırılmaması ve kullanımdan sonra kapaklarının sıkıca kapatılması kuralıdır.","ornek":"Sabah 08.50’de Kemal, WC temizleyiciyle kireç çözücüyü aynı kovada karıştırmaz; her birini kendi şişesinde bırakır ve kapağını sıkıca kapatır.","sektor":"Karıştırılan ürünler beklenmedik tepkime verebilir ve zehirli gaz çıkarabilir. Bu yüzden her ürün yalnızca kendi talimatına göre ve ayrı kullanılır.","iliskili":["kh1-4-032","kh1-4-034"],"kontrol":null,"gorsel":"t12s-kimyasal-siseler"},{"id":"kh1-4-034","konu":"4.1.1","terim":"Doğru miktar ve doğrudan dökmeme","ingilizce":"Correct dosage and application","tanim":"Kimyasalın yüzeye doğrudan dökülmeyip doğru yüzeyde ve doğru miktarda kullanılması kuralıdır.","ornek":"Kuşadası’nda Aylin, banyo duvarına kimyasalı dökmek yerine ürünü süngere sıkıp yüzeye süngerle sürer.","sektor":"Gereğinden fazla ürün israf olur ve durulamayı güçleştirir; ürün süngere ya da beze uygulanır.","iliskili":["kh1-4-033","kh1-4-035"],"kontrol":null},{"id":"kh1-4-035","konu":"4.1.1","terim":"Kimyasalı gizli köşede deneme","ingilizce":"Spot test","tanim":"İlk defa kullanılacak bir kimyasalın tüm yüzeye uygulanmadan önce göze en uzak ve en az kullanılan köşede denenmesidir.","ornek":"Fethiye’deki otel yeni bir kireç çözücü almıştır; Derya ürünü önce banyo kapısının arkasındaki fayans köşesinde dener.","sektor":"Ürün yüzeyi lekelerse ya da matlaştırırsa zarar küçük bir alanda kalır.","iliskili":["kh1-4-034","kh1-4-036"],"kontrol":null},{"id":"kh1-4-036","konu":"4.1.1","terim":"Asidik ürünler","ingilizce":"Acidic cleaners","tanim":"Kireç ve pas gibi birikimleri çözmek için kullanılan, asit içerikli temizlik ürünleridir.","ornek":"Çeşme’de penceresiz bir banyoda kireç çözücü kullanacak Burak, önce eldiven giyip maskesini takar, sonra kapıyı açıp havalandırma sistemini çalıştırır.","sektor":"Asidik ürünler kapalı ortamlarda maskesiz kesinlikle kullanılmaz. Çalışırken eldiven giyilir, maske takılır ve banyonun havalandığından emin olunur.","iliskili":["kh1-4-035"],"kontrol":null},{"id":"kh1-4-037","konu":"4.1.1","terim":"Kimyasal sıçramasında ilk müdahale","ingilizce":"First response to a chemical splash","tanim":"Tene ya da göze kimyasal sıçradığında o bölgenin önce bol ve akan suyla yıkanması, ardından doktora gidilmesidir.","ornek":"Sabah 10.10’da ayna temizleyicisini sıkan Mustafa’nın gözüne bir damla sıçrar; arkadaşı onu hemen lavaboya götürür, bol suyla yıkatır ve sonra doktora yönlendirir.","sektor":"Sıralama önemlidir: önce yıkama, sonra doktor. Olay amire de bildirilir.","iliskili":["kh1-4-038"],"kontrol":null},{"id":"kh1-4-038","konu":"4.1.1","terim":"Etiket ve şişe kuralı","ingilizce":"Labelling and original containers","tanim":"Temizlik maddelerinin etiketli olması ve hiçbirinin kendi özel şişesi dışında bir kaba, örneğin su şişesine konmamasıdır.","ornek":"Kuşadası’nda depoda su şişesine doldurulmuş sarı bir sıvı gören kat şefi Hülya, şişeyi toplatır ve ürünü etiketli kabına geri koydurur.","sektor":"Etiketsiz ya da su şişesine konmuş ürün, yanlış içilme veya yanlış yüzeyde kullanılma riski doğurur.","iliskili":["kh1-4-037","kh1-4-039"],"kontrol":null},{"id":"kh1-4-039","konu":"4.1.1","terim":"Temizlik sırasında banyonun havalandırılması","ingilizce":"Ventilating the bathroom","tanim":"Nemin ve kimyasal buharın dışarı atılması için temizlik sırasında ve sonrasında banyoda hava akımı sağlanmasıdır.","ornek":"Alanya’da kimyasalla çalışacak Selin, işe başlamadan banyo penceresini açar; temizlik bitince de havalandırmayı sürdürür.","sektor":"Kimyasalların kullanıldığı banyoda yeterli havalandırma hem görevliyi hem sonraki konuğu korur; nem de bakteri ve küf oluşumunu azaltır.","iliskili":["kh1-4-038","kh1-4-040"],"kontrol":null},{"id":"kh1-4-040","konu":"4.1.1","terim":"Kimyasal kullanım eğitimi","ingilizce":"Chemical training","tanim":"Temizlik personeline kimyasalların nasıl kullanılacağının, işletmenin belirlediği ilgili firma yetkilileri tarafından öğretilmesidir.","ornek":"Sezon başında Bodrum’daki otelde tedarikçi firmanın uzmanı tüm oda görevlilerine yeni ürünlerin kullanımını gösterir.","sektor":"Her firmanın yüzey ve kir çeşitliliğine göre ürünü olduğundan eğitim, kimyasallardan en yüksek verimi almanın yoludur.","iliskili":["kh1-4-039","kh1-4-041"],"kontrol":null},{"id":"kh1-4-041","konu":"4.1.1","terim":"Banyoda ergonomi","ingilizce":"Ergonomics in bathroom cleaning","tanim":"Temizlik sırasında görevlinin bedenini yormayan ve zarar vermeyen duruş ve hareketleri kullanmasıdır.","ornek":"Öğleden sonra küveti ovan Aylin, belini zorlamamak için dizlerini bükerek çalışır.","sektor":"Uygulama yapraklarında “çalışırken ergonomi kurallarına uyduğunuzdan emin olunuz” adımı her temizlikte yer alır; yanlış duruş uzun vadede bel ve omuzu yorar.","iliskili":["kh1-4-040"],"kontrol":null},{"id":"kh1-4-042","konu":"4.1.2","terim":"Banyodan çöp toplama","ingilizce":"Removing bathroom waste","tanim":"Temizliğe başlamadan önce banyodaki çöpün, kirli tekstilin ve kullanılmış buklet malzemelerinin toplanıp kat arabasında ilgili bölümlere konmasıdır.","ornek":"Sabah 08.30’da çıkış yapılmış 410 numaralı odanın banyosuna giren Derya, önce eldivenini ve maskesini takar, sonra çöpleri ve kirli havluları toplar.","sektor":"Kat arabasında atıklar için ayrı bölme varsa o kullanılır; yoksa çöpün özelliğine göre farklı renkte poşetler hazırlanır. Kâğıt, cam, plastik gibi geri dönüşebilen atıklar ayrı bölmeye ya da renkli poşete konur; atık pil çıkarsa ayrı poşette pil toplama kutusuna atılır. Konuk için önemli olabileceğinden emin olunmayan hiçbir eşya çöp sayılıp atılmaz.","iliskili":["kh1-4-043"],"kontrol":null},{"id":"kh1-4-043","konu":"4.1.2","terim":"Zemindeki sabun artıkları","ingilizce":"Soap residue on the floor","tanim":"Konuğun bıraktığı sabun, şampuan gibi kaygan maddelerin zeminde kalmasıdır.","ornek":"Akşam 18.00’de Trabzon’daki bir otelde Mustafa, duş çıkışındaki şampuan köpüğünü temizliğe başlamadan alır.","sektor":"Kaymalara neden olan bu artıklar iş sağlığı ve güvenliğini tehlikeye attığı için temizliğe başlamadan toplanır.","iliskili":["kh1-4-042","kh1-4-044"],"kontrol":null},{"id":"kh1-4-044","konu":"4.1.2","terim":"Kirli banyo tekstili","ingilizce":"Soiled bathroom linen","tanim":"Konuğun kullandığı havlu, bornoz ve ayak havlusu gibi banyo tekstillerinin temizlikte ayrı toplanan grubudur.","ornek":"Alanya’da Selin, küvetin kenarındaki üç havluyu ve bornozu toplayıp kat arabasındaki kirli tekstil bölmesine koyar.","sektor":"Kirli tekstil temiz tekstille karışmaz; kat arabasında her biri kendi bölümünde tutulur.","iliskili":["kh1-4-043","kh1-4-045"],"kontrol":null,"gorsel":"t11a-kirli-camasir-sepetleri"},{"id":"kh1-4-045","konu":"4.1.2","terim":"Bornoz ve havlu ceplerinin denetimi","ingilizce":"Checking robe pockets","tanim":"Kirli havlu ve bornozlar toplanırken içlerine ve ceplerine bakılarak konuğa ait eşya kalıp kalmadığının kontrol edilmesidir.","ornek":"Muğla’da bornozu torbaya koymadan cebini yoklayan Kemal, içinden çıkan küçük bir kolye kutusunu hemen kat şefine bildirir.","sektor":"Konuk ayrılmışsa bulunan eşya forma yazılarak kat şefine teslim edilir; kontrol edilmeden yıkamaya giden tekstilde eşya kaybolabilir.","iliskili":["kh1-4-044","kh1-4-046"],"kontrol":null},{"id":"kh1-4-046","konu":"4.1.2","terim":"Kullanılmış buklet malzemeleri","ingilizce":"Used bathroom amenities","tanim":"Konuğun kullandığı, bittiği için boş kalan sabun, şampuan gibi tek kullanımlık banyo malzemelerinin ambalajlarıdır.","ornek":"Sabah 09.10’da Kemal, lavabo kenarındaki boş şampuan şişesini ve açılmış sabun ambalajını toplar.","sektor":"Kullanılmış olanlar zeminden ve tezgâhtan toplanır; yerlerine sonradan yeni malzeme yerleştirilir.","iliskili":["kh1-4-045","kh1-4-047"],"kontrol":null},{"id":"kh1-4-047","konu":"4.1.2","terim":"Tıkalı giderin açılması","ingilizce":"Unblocking the drain","tanim":"Temizliğe başlamadan önce suyun akışını engelleyen giderdeki tıkanıklığın giderilmesidir.","ornek":"Çeşme’de duş giderinde biriken saç yüzünden suyun durduğunu gören Burak, eldiven takarak gideri açar.","sektor":"Tıkalı gider su birikmesine ve kokuya yol açar; enfeksiyon riskine karşı eldiven ve maske takılır.","iliskili":["kh1-4-046","kh1-4-048"],"kontrol":null,"gorsel":"t15ad-gider-pompa"},{"id":"kh1-4-048","konu":"4.1.2","terim":"Banyo çöp torbasının taşınması","ingilizce":"Bagging and transferring waste","tanim":"Çöp kutusundaki torbanın ağzının bağlanıp kat arabasındaki çöp torbasına yerleştirilmesi ve kutuya yeni poşet takılması işlemidir.","ornek":"Antalya’da Elif, banyo kovasındaki torbanın ağzını bağlayarak taşır; torba koridorda dökülmez.","sektor":"Ağzı bağlı torba taşıma sırasında kokuyu ve sızıntıyı önler. Kova boş bırakılmaz, yeni poşet takılır.","iliskili":["kh1-4-047"],"kontrol":null},{"id":"kh1-4-049","konu":"4.1.3","terim":"Banyo arıza kontrolü","ingilizce":"Bathroom fault check","tanim":"Oda görevlisinin banyodaki donanımların çalışıp çalışmadığını ve zarar görüp görmediğini temizlikle birlikte denetlemesidir.","ornek":"Sabah 09.20’de Fethiye’de 118 numaralı odanın banyosuna giren Aylin, armatürü açıp suyun aktığından ve rezervuarın çalıştığından emin olur.","sektor":"Kontrol sırasında bir arıza görülürse ilgili form doldurulur, arızanın giderilmesi ve takibi sağlanır.","iliskili":["kh1-4-050"],"kontrol":null},{"id":"kh1-4-050","konu":"4.1.3","terim":"Banyo kontrol noktaları","ingilizce":"Bathroom inspection points","tanim":"Arıza kontrolünde banyoda sırayla bakılan priz, lamba, ısıtma-soğutma, telefon, armatür, duş, aydınlatma ve rezervuar gibi noktalardır.","ornek":"Öğleden önce Selin, banyoda lamba anahtarını, duş başlığını, rezervuarı ve telefonu sırayla kontrol eder.","sektor":"Hangi noktalara bakılacağı işletmeden işletmeye değişebilir; amaç bu noktaların hepsinin çalıştığından emin olmaktır.","iliskili":["kh1-4-049","kh1-4-051"],"kontrol":null},{"id":"kh1-4-051","konu":"4.1.3","terim":"Küçük arızanın bedeli","ingilizce":"Why small faults matter","tanim":"Büyük konuk memnuniyetsizliğine ya da konuğun can güvenliğinin tehlikeye girmesine, küçük görünen bir arızanın da yol açabilmesidir.","ornek":"Gece 23.00’te Bodrum’daki bir otelde banyo lambası yanmayan konuk, kaygan zeminde karanlıkta kalır ve sabah resepsiyona şikâyet eder.","sektor":"Bu yüzden görevli küçük arızayı da bildirir; “sonra bakarız” demek konuk güvenliğini riske atar.","iliskili":["kh1-4-050","kh1-4-052"],"kontrol":null,"gorsel":"t4-damlayan-musluk"},{"id":"kh1-4-052","konu":"4.1.3","terim":"Banyo arıza tespit formu","ingilizce":"Fault report form","tanim":"Banyoda bulunan arızanın yerinin ve türünün yazılarak teknik servise iletilmesini sağlayan formdur.","ornek":"Alanya’da lavabo armatüründen su sızdığını gören Kemal, oda numarasını ve arızayı forma yazar.","sektor":"Form kat şefine ve teknik servise iletilir; arıza giderilene kadar takip edilir.","iliskili":["kh1-4-051","kh1-4-053"],"kontrol":null},{"id":"kh1-4-053","konu":"4.1.3","terim":"Banyoda eşya hasar formu","ingilizce":"Item damage report","tanim":"Çıkış yapılan odada zarar görmüş bir donanım ya da eşya tespit edildiğinde, hasarı kayda geçirmek için arıza tespit formuyla birlikte doldurulan formdur.","ornek":"Sabah 11.00’de Alanya’daki otelde check-out yapılmış odanın banyosunda kırık bir bardak ve çatlamış bir sabunluk gören Derya, eşya hasar formunu doldurur.","sektor":"Hasar durumunda arıza tespit formu ile eşya hasar formu birlikte doldurulur. Konuğa ait unutulmuş eşya için ise kayıp bulunmuş eşya formu kullanılır.","iliskili":["kh1-4-052","kh1-4-054"],"kontrol":null},{"id":"kh1-4-054","konu":"4.1.3","terim":"Kayıp ve hasarın bildirilmesi","ingilizce":"Reporting loss or damage","tanim":"Bulunan kayıp eşyanın ya da tespit edilen hasarın kat şefine ve resepsiyona haber verilerek takibinin sağlanmasıdır.","ornek":"Kuşadası’nda 12.10’da Mustafa, banyoda unutulan bir tıraş makinesi için resepsiyonu arar ve kat şefine de bilgi verir.","sektor":"Bildirim geciktikçe eşyanın sahibine ulaşma olasılığı azalır, hasar da zamanında kayda geçmez.","iliskili":["kh1-4-053"],"kontrol":null},{"id":"kh1-4-055","konu":"4.1.3","terim":"Dolu odada banyo kontrolü","ingilizce":"Checking an occupied room’s bathroom","tanim":"Konuğun kaldığı odada banyo arıza ve donanım kontrolünün temizliğe başlamadan önce yapılmasıdır.","ornek":"Öğleden sonra 14.30’da Muğla’da Selin, konuk odada değilken banyoda prizi, lambayı ve duşu kontrol eder; telefon arızalı çıkınca form doldurur.","sektor":"Arıza temizlikten önce kayda geçer; dolu odada bulunan arıza için arıza formu doldurulur.","iliskili":["kh1-4-056"],"kontrol":null},{"id":"kh1-4-056","konu":"4.1.3","terim":"Çıkış yapılmış odada banyo kontrolü","ingilizce":"Checking a departed guest’s bathroom","tanim":"Konuğun check-out yapmasının ardından banyodaki arıza, hasar ve unutulan eşya kontrolünün temizliğe başlamadan önce yapılmasıdır.","ornek":"Sabah 11.20’de check-out yapılmış 205 numaralı odada Burak, temizliğe başlamadan banyodaki bardağın kırık olduğunu fark eder ve hasar formunu doldurur.","sektor":"Oda durum raporunda o güne ait check-out odalarının bilgisi bulunur. Bu odalara konuk işletmeden ayrılmadan önce gidilir; böylece unutulan eşya varsa konuğa hemen ulaştırılabilir.","iliskili":["kh1-4-055","kh1-4-057"],"kontrol":null},{"id":"kh1-4-057","konu":"4.1.3","terim":"Banyoda unutulan eşya","ingilizce":"Item left behind in the bathroom","tanim":"Çıkış yapan konuğun banyoda bıraktığı kişisel eşyadır.","ornek":"Sabah 11.40’ta Bursa’da Derya, lavabo kenarında unutulmuş bir saç düzleştiriciyi görür ve hemen ön büroyu arar.","sektor":"Konuk hâlâ işletmedeyse ön büroya hemen haber verilir; ayrılmışsa kayıp bulunmuş eşya formu doldurulur ve eşya kat şefine teslim edilir.","iliskili":["kh1-4-056","kh1-4-058"],"kontrol":null},{"id":"kh1-4-058","konu":"4.1.3","terim":"Giderilen arızanın kontrolü ve dosyalanması","ingilizce":"Closing a fault report","tanim":"Teknik servis arızayı giderdikten sonra görevlinin banyoyu yeniden kontrol edip düzenlemesi ve formu kendi nüshasıyla birlikte dosyalamasıdır.","ornek":"Ertesi sabah 08.40’ta Çeşme’de Aylin, bildirdiği lavabo sızıntısının onarıldığını banyoda kontrol eder; teknik servisin geri verdiği formu kendi nüshasıyla dosyalar.","sektor":"Arızanın gerçekten kapandığı kayda geçer. Giderilemeyen arıza için teknik servisle yeniden iletişime geçilir; sonuçlanmayan arıza vardiya sonunda bir sonraki vardiyaya bildirilir ve arızalı oda, oda durum raporunda gösterilir.","iliskili":["kh1-4-057"],"kontrol":null},{"id":"kh1-4-229","konu":"4.1.3","terim":"Banyoda hasarlı malzeme tutanağı","ingilizce":"Damaged item report (bathroom)","tanim":"Konuğun hasarı karşılaması gereken durumlarda, kırılan ya da bozulan banyo malzemesinin kat şefince yazılı olarak kayda geçirilmesini sağlayan belgedir.","ornek":"Sabah 11.40’ta Alanya’daki otelde check-out yapılmış 316 numaralı odanın banyosunda kırık bir aynalı dolap gören Derya, durumu kat şefine bildirir; kat şefi işletme prosedürüne göre tutanağı hazırlar.","sektor":"Kat şefi konukla yüz yüze görüşüp durumu açıklar; düzenlenen tutanağın her bölüme birer nüshası imza karşılığı teslim edilir. Hasar bedelinin tahsili işletme prosedürüne göre ilgili bölümlerce yürütülür.","iliskili":["kh1-4-054","kh1-4-053"],"kontrol":null},{"id":"kh1-4-230","konu":"4.1.3","terim":"Banyo arızasının otomasyonda kaydı","ingilizce":"Logging a bathroom fault in the PMS","tanim":"Otomasyon kullanılan işletmelerde banyodaki arızanın sipariş alıcıya (order taker) bildirilerek sisteme işlenmesi ve giderilene kadar odanın arızalı oda (OOO) görünmesidir.","ornek":"Sabah 09.50’de Marmaris’teki otelin 227 numaralı odasında duş başlığının çalışmadığını gören Seda, durumu sipariş alıcıya bildirir; oda sistemde OOO görünür ve konuk odasına verilmez.","sektor":"Teknik servis arızayı giderince sipariş alıcı sisteme not girer ve kat şefine haber verir; kat şefi odayı temizleyen görevliyi bilgilendirir, görevli banyoyu yeniden kontrol eder. Giderilemeyen arızalar ön büro bölümüne gönderilen rapora kaydettirilir.","iliskili":["kh1-4-058","kh1-4-052"],"kontrol":null},{"id":"kh1-4-059","konu":"4.1.4","terim":"Banyo donanımları","ingilizce":"Bathroom fittings and equipment","tanim":"Banyoda genellikle bulunan alarm butonu, saç kurutma makinesi, ayna, telefon, bardak ve yangın ya da ilk yardım alarm cihazı gibi araçlardır.","ornek":"Antalya’da bir banyoya yeni giren Elif, donanım listesine bakarak alarm butonunun, telefonun ve saç kurutma makinesinin yerinde olduğunu kontrol eder.","sektor":"Temizlikte kullanılacak kimyasalı banyo donanımının cinsi belirler.","iliskili":["kh1-4-060"],"kontrol":null,"gorsel":"t11d-banyo-donanim"},{"id":"kh1-4-060","konu":"4.1.4","terim":"Alarm butonu","ingilizce":"Emergency call button","tanim":"Banyoda acil durumda konuğun yardım çağırmak için bastığı düğmedir.","ornek":"Gece 02.00’de banyoda kendini kötü hisseden bir konuk alarm butonuna basar ve ekip hemen odaya yönlendirilir.","sektor":"Acil durum donanımı olduğu için yerinde, sağlam ve erişilebilir durumda olup olmadığı kontrol edilir.","iliskili":["kh1-4-059","kh1-4-061"],"kontrol":null},{"id":"kh1-4-061","konu":"4.1.4","terim":"Banyo telefonu","ingilizce":"Bathroom telephone","tanim":"Konuğun banyodan çıkmadan resepsiyonu ya da diğer bölümleri arayabildiği, genellikle duvara monte telefondur.","ornek":"Akşam 21.30’da Marmaris’teki otelin 306 numaralı odasında duştan çıkmak üzere olan konuk, banyodaki telefondan oda servisini arayıp sıcak çay ister.","sektor":"Telefonun çalışıp çalışmadığı banyo arıza kontrolünde bakılan noktalardandır.","iliskili":["kh1-4-060","kh1-4-062"],"kontrol":null},{"id":"kh1-4-062","konu":"4.1.4","terim":"Banyo bardağı","ingilizce":"Bathroom glass","tanim":"Diş fırçalama ve ağız çalkalama için lavabo kenarında bulunan bardaktır.","ornek":"Sabah 09.50’de Bodrum’da Kemal, lavabonun yanındaki bardağı alır ve uygun renk kodundaki süngerle kimyasal kullanarak temizler.","sektor":"Konuğun doğrudan kullandığı bir eşya olduğundan bardağın temizliğine hijyen için ayrıca özen gösterilir.","iliskili":["kh1-4-061","kh1-4-063"],"kontrol":null,"gorsel":"dis-fircalari"},{"id":"kh1-4-063","konu":"4.1.4","terim":"Yangın ya da ilk yardım alarm cihazı","ingilizce":"Fire or first-aid alarm device","tanim":"Banyoda bulunabilen, tehlike anında uyarı veren ya da yardım çağıran cihazdır.","ornek":"Kapadokya’daki bir kat denetiminde şef, banyodaki alarm cihazının yerinde ve sağlam olduğunu kontrol eder.","sektor":"Hasarlı ya da çalışmayan cihaz arıza formuyla bildirilir.","iliskili":["kh1-4-062"],"kontrol":null,"gorsel":"t15ad-yangin-alarm"},{"id":"kh1-4-064","konu":"4.1.4","terim":"Saç kurutma makinesi","ingilizce":"Hairdryer","tanim":"Banyoda ıslak saçı kurutmak için bulunan elektrikli alettir.","ornek":"Çeşme’de sabah 10.00’da Derya, saç kurutma makinesinin kablosunun sıyrıldığını görür ve arıza formu doldurur.","sektor":"Elektrikli aletler banyoda suyla yan yana olduğundan hasarlı kablo ve çalışmayan cihaz hemen bildirilir.","iliskili":["kh1-4-065"],"kontrol":null,"gorsel":"t15ad-sac-kurutma"},{"id":"kh1-4-065","konu":"4.1.4","terim":"Saç kurutma makinesinin temizliği","ingilizce":"Cleaning the hairdryer","tanim":"Elektrik bağlantısının kapalı olduğu kontrol edildikten sonra makinenin genel temizlik maddesi ve nemli bezle silinip kurulanmasıdır.","ornek":"Sabah 10.20’de Bodrum’da Aylin, fişin prizden çekili olduğunu görür, makineyi nemli bezle siler ve işletmenin belirlediği yere yerleştirir.","sektor":"Temizlenen makineler işletmenin belirlediği kurala göre yerleştirilir. Elektrikli aletlerin temizliğine başlamadan önce bağlantının kapalı olduğundan emin olunur.","iliskili":["kh1-4-064","kh1-4-066"],"kontrol":null},{"id":"kh1-4-066","konu":"4.1.4","terim":"Makyaj aynası","ingilizce":"Make-up mirror (magnifying mirror)","tanim":"Yakından makyaj ve tıraş için kullanılan, çerçevesi genellikle krom, pirinç ya da altın kaplama olan banyo aynasıdır.","ornek":"Alanya’da Murat, makyaj aynasının çerçevesini malzemesine uygun temizleyiciyle siler; cam bölümünü cam sille temizleyip renk kodlu mikrofiber bezle kurular.","sektor":"Çerçeve ve cam ayrı ürünlerle temizlenir; kimyasalın kullanımında talimata mutlaka uyulur.","iliskili":["kh1-4-065","kh1-4-067"],"kontrol":null,"gorsel":"t12d-makyaj-aynasi"},{"id":"kh1-4-067","konu":"4.1.4","terim":"Banyoda elektrik düğmesi ve prizler","ingilizce":"Switches and sockets in the bathroom","tanim":"Banyodaki ışık ve cihaz bağlantılarını sağlayan, elektrik akımı taşıyan düğme ve soket yüzeyleridir.","ornek":"Öğlen 12.30’da Kuşadası’nda Burak, banyodaki priz çerçevesini hafif nemli bezle siler ve hemen kurular.","sektor":"Yoğun kir ve lekelerde elektrik bağlantıları kesilerek uygulama yapılır.","iliskili":["kh1-4-066","kh1-4-068"],"kontrol":null,"gorsel":"t11d-tiras-prizi"},{"id":"kh1-4-068","konu":"4.1.4","terim":"Islak temizlikte elektrik güvenliği","ingilizce":"Electrical safety in wet cleaning","tanim":"Banyoda suyla çalışılırken priz ve elektrikli araçlara su sıçratılmaması için alınan dikkat ve önlemlerdir.","ornek":"Muğla’da duvar fayansını yıkayan Elif, yakındaki priz çerçevesini sudan uzak tutar.","sektor":"Banyolar elektrik akımının bulunduğu alanlardır; ıslak ve nemli temizlikte düğme, priz ve elektrikli araçların çevresinde özellikle dikkatli olunur.","iliskili":["kh1-4-067","kh1-4-069"],"kontrol":null},{"id":"kh1-4-069","konu":"4.1.4","terim":"Kırık camın toplanması","ingilizce":"Disposing of broken glass","tanim":"Temizlik sırasında bulunan kırık cam, ayna gibi kesici malzemelerin kurala uygun toplanıp uygun çöp kutusuna konmasıdır.","ornek":"Sabah 08.50’de çıkış yapılmış odada kırık bardak parçaları bulan Selin, parçaları eldivenle faraşa alır ve uygun çöp kutusuna koyar.","sektor":"Kırık parçalar yaralanma riski taşıdığı için kurala uygun toplanır.","iliskili":["kh1-4-068"],"kontrol":null,"gorsel":"t11d-kirik-cam-lavabo"},{"id":"kh1-4-070","konu":"4.1.4","terim":"Donanıma göre kimyasal ve yöntem","ingilizce":"Matching chemical and method to the fitting","tanim":"Her banyo donanımının cinsine göre uygun temizlik maddesinin ve yönteminin seçilmesidir. Yanlış seçim, insan sağlığını tehdit ettiği gibi donanıma geri dönülmez zarar verebilir.","ornek":"Sabah 10.00’da Çeşme’de altın kaplama armatürü aşındırıcı bir ürünle ovan Kerem, kaplamanın soyulduğunu görür; armatür yenilenmek zorunda kalır. Ertesi gün aynı otelde Kemal, pirinç çerçeveli makyaj aynasını malzemesine uygun temizleyiciyle siler.","sektor":"Temizlik sırasında kullanılan kimyasalı banyo donanımının cinsi belirler; kimyasal talimatına göre uygulanır ve KKD kullanılır. Doğru kimyasala rağmen yanlış uygulama verimi düşürür, hasarlı donanımın değiştirilmesi işletmeye maliyet çıkarır.","iliskili":["kh1-4-031","kh1-4-059"],"kontrol":null},{"id":"kh1-4-072","konu":"4.1.4","terim":"Çöp kovası ve kül tablası temizliği","ingilizce":"Cleaning the waste bin and ashtray","tanim":"Banyodaki çöp kovasının ve kül tablasının yıkanarak temizlenmesidir.","ornek":"Sabah 09.30’da Antalya’da Elif, klozete kimyasalı sıkıp beklemeye bıraktıktan sonra çöp kovasını ve kül tablasını yıkar.","sektor":"Klozetin dezenfekte olması beklenirken bu işler yapılır; böylece bekleme süresi boşa geçmez.","iliskili":["kh1-4-079"],"kontrol":null},{"id":"kh1-4-073","konu":"4.1.5","terim":"Banyo yüzeylerinin sınıflandırılması","ingilizce":"Bathroom surface types","tanim":"Temizliğin, kullanılan malzemeye göre fayans, cam ve metal yüzeylerin temizliği olarak ayrılmasıdır.","ornek":"Alanya’da kat şefi Murat, yeni görevliye banyoyu üç yüzey grubuna bölerek anlatır: fayans, cam ve metal.","sektor":"Her yüzey grubunun kimyasalı ve kurulama yöntemi farklıdır; ayrım doğru ürünü seçmeyi kolaylaştırır.","iliskili":["kh1-4-074"],"kontrol":null,"gorsel":"t11d-banyo-yuzey"},{"id":"kh1-4-074","konu":"4.1.5","terim":"Temiz yüzeylerin önemi","ingilizce":"Why clean surfaces matter","tanim":"Banyo yüzeylerini toz, kir ve çöpten arındırmanın konuk memnuniyetini artırması ve sağlık riskini düşürmesidir.","ornek":"Kapadokya’daki bir konuk yorum kartına “Banyosu pırıl pırıldı” yazar; kat şefi kartı ekibine okur.","sektor":"Yeterince temiz olmayan ve nemli banyolarda bakteri oluşabilir; bazı bakteriler can kaybına bile neden olabilir. Bu yüzden temizlik kurallarına azami dikkat gösterilir.","iliskili":["kh1-4-073","kh1-4-075"],"kontrol":null},{"id":"kh1-4-075","konu":"4.1.5","terim":"Fayans","ingilizce":"Ceramic tile","tanim":"Banyoda klozet, lavabo, duvar ve bide çevresinde sık kullanılan, temizlenmesi kolay yapı malzemesidir.","ornek":"Bodrum’daki bir otelde fayans duvarları Derya sünger ve kimyasalla siler, çekçekle kurutunca duvarlar parlar.","sektor":"Fayansın kullanımı ve temizliği kolaydır; ancak derz araları kirlenince fırça gerekir.","iliskili":["kh1-4-074","kh1-4-076"],"kontrol":null,"gorsel":"t10d-banyo-fayans-mermer"},{"id":"kh1-4-076","konu":"4.1.5","terim":"Derz araları","ingilizce":"Grout lines","tanim":"Fayansların arasında kalan, kir ve yağ birikimine açık dar çizgilerdir.","ornek":"Muğla’da duş duvarının derz aralarındaki sararmayı Kemal, sünger yerine uygun fırçayla temizler.","sektor":"Birikmiş yağ ve kir artıklarında yüzey ve derz araları fırçalanır; buharlı temizlik de derz aralarında hijyenik sonuç verir.","iliskili":["kh1-4-075"],"kontrol":null,"gorsel":"t15ad-derz"},{"id":"kh1-4-077","konu":"4.1.5","terim":"Küvet ve jakuzi temizliği","ingilizce":"Cleaning the bath and whirlpool","tanim":"Giderdeki sabun ve kirin alınması, yüzeyin ıslatılıp kimyasalla ovulması, beklenip durulanması ve kurulanması sırasıyla yapılan temizliktir.","ornek":"Sabah 10.00’da Çeşme’de Aylin, küvetin giderindeki saç tellerini alır, yüzeyi ıslatır ve renk kodlu süngerle kimyasalı ovar.","sektor":"Ders materyaline göre kimyasal yüzeyde 2-3 dakika bekletilip durulanır; ardından uygun renk tonundaki bezle kurulanır.","iliskili":["kh1-4-078"],"kontrol":null,"gorsel":"t11d-jakuzi-oda"},{"id":"kh1-4-078","konu":"4.1.5","terim":"WC ve bide temizliği","ingilizce":"Cleaning the WC and bidet","tanim":"Rezervuarın çekilip alanın yıkanması, genel temizleyicinin sıkılıp bekletilmesi, fırçalama ve çevrenin silinip kurulanmasıyla yapılan temizliktir.","ornek":"Öğleden önce Alanya’da Selin eldivenlerini takar, rezervuarı çalıştırıp klozetin iç kısmına temizleyiciyi sıkar.","sektor":"Eldiven, temizlik öncesi iş sağlığı ve güvenliği için takılır; bide varsa klozetle birlikte aynı özenle temizlenir.","iliskili":["kh1-4-077","kh1-4-079"],"kontrol":null,"gorsel":"t10d-klozet-temiz"},{"id":"kh1-4-079","konu":"4.1.5","terim":"Klozete temizleyici sıkma","ingilizce":"Applying WC cleaner","tanim":"Sifonu çekilmiş klozetin iç yüzeyine daire çizerek temizleyici kimyasalın sıkılması ve fırçanın klozetin ortasına bırakılmasıdır.","ornek":"Trabzon’da Burak, klozetin iç kenarına daire çizerek temizleyiciyi sıkar ve fırçayı tam ortaya bırakır.","sektor":"Sifon, klozet kapağı kapalıyken çekilir. Kimyasalın dezenfekte etmesi için beklenir; bu bekleme süresi çöp kovası ve kül tablası gibi işlerle değerlendirilir.","iliskili":["kh1-4-078","kh1-4-080"],"kontrol":null,"gorsel":"t11d-klozet-temizleyici"},{"id":"kh1-4-080","konu":"4.1.5","terim":"Klozet çevresini dıştan içe silme","ingilizce":"Wiping the toilet surround from outside in","tanim":"Çevrenin ve kapakların uygun renkteki bezle dış kenardan içe doğru silinerek kurulanmasıdır.","ornek":"Bursa’da Derya, klozet çevresini ve kapaklarını bezle dıştan içe doğru siler ve kurular.","sektor":"Bu kural silme yönünü standartlaştırır; klozetin altı ve çevresi de iyice temizlenir, kapaklar ve çevre sonunda kurulanarak su lekesi kalmaz.","iliskili":["kh1-4-079","kh1-4-081"],"kontrol":null,"gorsel":"t11d-klozet-cevresi"},{"id":"kh1-4-081","konu":"4.1.5","terim":"Klozetten sonra eldiven değiştirme","ingilizce":"Changing gloves after the WC","tanim":"Klozet temizliği bittikten sonra eldivenlerin çıkarılıp yenisinin takılmasıdır.","ornek":"Sabah 09.40’ta Fethiye’de Kemal, klozet işi bitince eldivenlerini atar ve yeni eldivenle aynayı silmeye geçer.","sektor":"Böylece tuvalet bölgesindeki mikroplar ayna ve lavabo gibi yüzeylere taşınmaz; çapraz bulaşma önlenir. Eldiven, ayna ve lavabo gibi yüzeylere geçmeden önce değiştirilir.","iliskili":["kh1-4-080"],"kontrol":null},{"id":"kh1-4-082","konu":"4.1.5","terim":"Banyo duvarı temizliği","ingilizce":"Cleaning the bathroom walls","tanim":"Duvarın ıslatılıp kimyasal ve süngerle ovulması, talimattaki süre kadar beklenip durulanması ve kurulanmasıdır.","ornek":"Öğleden sonra 15.00’te Kuşadası’nda Murat, duvarı ıslatıp süngerle ovar, durular, çekçekle fazla suyu alır.","sektor":"Günlük temizlikte sünger yeterlidir; fazla su çekçekle alınıp renk koduna uygun bezle kurulanır.","iliskili":["kh1-4-083"],"kontrol":null},{"id":"kh1-4-083","konu":"4.1.5","terim":"Lavabo temizliği","ingilizce":"Cleaning the washbasin","tanim":"Giderdeki sabun ve kirin alınması, süzgecin temizlenmesi, yüzeyin ıslatılıp kireç ve yağ çözücüyle ovulması, beklenip durulanması ve kurulanmasıyla yapılan temizliktir.","ornek":"Sabah 10.40’ta Datça’da Aylin, lavabonun süzgecini temizler, kireç ve yağ çözücü kimyasalı sarı süngerle ovar.","sektor":"Ders materyaline göre kimyasal 2-3 dakika bekledikten sonra alan durulanıp kurulanır.","iliskili":["kh1-4-082","kh1-4-084"],"kontrol":null,"gorsel":"t11d-lavabo"},{"id":"kh1-4-084","konu":"4.1.5","terim":"Gider ve süzgeç temizliği","ingilizce":"Cleaning the plughole and strainer","tanim":"Lavabo, küvet ve duş zemininde suyun aktığı noktalardaki saç, sabun ve kir artıklarının alınmasıdır.","ornek":"Marmaris’te Mustafa, banyo zemininin giderindeki saç tellerini almadan zemin temizliğine geçmez; zeminde suyun bir köşede toplandığını gören Burak da gideri kontrol edip açar.","sektor":"Her temizliğin başında gider ve süzgeç temizlenir; böylece su birikmez, koku oluşmaz. Zemin temizliği sırasında da giderin her türlü atıktan arındırılmış olduğu kontrol edilir; tıkalı gider suyun akmasını engeller.","iliskili":["kh1-4-083","kh1-4-085"],"kontrol":null,"gorsel":"t15ad-gider-suzgec"},{"id":"kh1-4-085","konu":"4.1.5","terim":"Kireç ve yağ çözücü","ingilizce":"Descaler and degreaser","tanim":"Birikmiş kireç ve yağı çözen, lavabo gibi yüzeylerde kullanılan kimyasal temizleyicidir.","ornek":"Bodrum’da lavabonun çevresindeki beyaz kireç lekelerini Kemal, kireç ve yağ çözücüyle temizler.","sektor":"Çözücü, süngerle sürüldükten sonra talimattaki süre beklenir ve iyice durulanır.","iliskili":["kh1-4-084"],"kontrol":null},{"id":"kh1-4-086","konu":"4.1.5","terim":"Duş kabini temizliği","ingilizce":"Cleaning the shower cubicle","tanim":"Kabinin cam yüzeylerine çizmeyen süngerle kimyasalın sürülüp birkaç dakika bekletildikten sonra durulanması ve çekçekle kurulanmasıdır.","ornek":"Fethiye’de Selin, duş kabininin camını çizmeyen süngerle temizler, bekletip durular ve çekçekle fazla suyu alır.","sektor":"Çok fazla kireç ve yağ artığı birikebildiği için duş kabini itina ile temizlenir.","iliskili":["kh1-4-087"],"kontrol":null},{"id":"kh1-4-087","konu":"4.1.5","terim":"Duş kabininin sürgülü kısımları","ingilizce":"Cleaning the sliding track","tanim":"Sürgülü kısımlara spreyle temizlik malzemesinin sıkılıp duş fıskiyesiyle durulanması ve kurulanmasıdır.","ornek":"Kuşadası’nda Aylin, duş kabininin sürgüsünün rayındaki kiri spreyle çözer, fıskiyeyle durular ve kurular.","sektor":"Rayda kalan su ve kir kireçlenmeye yol açabildiği için sürgülü kısımlar ayrıca ele alınır.","iliskili":["kh1-4-086","kh1-4-088"],"kontrol":null,"gorsel":"t12s-dus-kabini"},{"id":"kh1-4-088","konu":"4.1.5","terim":"Banyo aynası temizliği","ingilizce":"Cleaning the bathroom mirror","tanim":"Aynanın çerçevesinin türüne uygun kimyasalla temizlenmesi, camın cam peluşu ya da cam bezi ve çekçekle silinmesi, kurulanmasıdır.","ornek":"Sabah 11.00’de Çeşme’de Murat, ayna çerçevesini çerçeve türüne uygun ürünle siler, camı çekçekle temizler.","sektor":"Ayna silme işinde ürün seçimi çerçeveyi ve camı ayrı düşünerek yapılır.","iliskili":["kh1-4-087","kh1-4-089"],"kontrol":null},{"id":"kh1-4-089","konu":"4.1.5","terim":"Aynayı “S” çizerek silme","ingilizce":"S-shaped wiping pattern","tanim":"Aynanın büyüklüğüne göre çekçek ya da bezle “S” biçiminde hareketlerle silinmesi tekniğidir.","ornek":"Öğlen 12.00’de Alanya’da Derya, ayna camını yukarıdan aşağıya “S” çizerek siler.","sektor":"“S” şeklinde silmek su ve temizleyicinin yüzeyde iz bırakmadan toplanmasına yardımcı olur.","iliskili":["kh1-4-088","kh1-4-090"],"kontrol":null},{"id":"kh1-4-090","konu":"4.1.5","terim":"Cam görevlisi","ingilizce":"Window cleaner","tanim":"Bazı konaklama tesislerinde banyodaki cam yüzeylerin temizliğini oda görevlileri yerine üstlenen personeldir.","ornek":"Alanya’daki büyük bir otelde banyo camlarını cam ekibinden Hasan siler; oda görevlisi Selin banyonun geri kalanını temizler.","sektor":"Cam yüzey daha fazla alan kapladığı için zaman ve emek kaybetmemek amacıyla bu iş cam görevlilerine bırakılır.","iliskili":["kh1-4-089"],"kontrol":null,"gorsel":"t2-oda-hizmetlisi"},{"id":"kh1-4-091","konu":"4.1.5","terim":"Metal yüzeyler","ingilizce":"Metal surfaces","tanim":"Banyoda armatür, askı ve duş başlığı gibi, nem ve su lekesi kalırsa paslanabilen yapı malzemelerinin yüzeyleridir.","ornek":"Sabah 08.50’de Çeşme’de Kemal, nemli kalan krom askıda pas lekesinin başladığını fark eder ve doğru kimyasalla temizleyip iyice kurular.","sektor":"Doğru kimyasal talimata uygun kullanılır ve yüzey yeterince kurulanır; nem kalırsa leke ve pas başlar.","iliskili":["kh1-4-092"],"kontrol":null},{"id":"kh1-4-092","konu":"4.1.5","terim":"Banyo askı çeşitleri","ingilizce":"Towel rails and hooks","tanim":"El havlusu, banyo havlusu ve tuvalet kâğıdı gibi eşyaları asmak için kullanılan, genellikle krom kaplama araçlardır.","ornek":"Muğla’da bir banyodaki krom havlu askısını Elif uygun bezle silip kurutur.","sektor":"Askılar uygun temizlik bezi ve kimyasalıyla silinir ve kurutulur.","iliskili":["kh1-4-091","kh1-4-093"],"kontrol":null,"gorsel":"t10d-havlu-askisi-koyu-fayans"},{"id":"kh1-4-093","konu":"4.1.5","terim":"Rezervuar kontrol paneli","ingilizce":"Flush plate","tanim":"Klozet rezervuarının çalıştırıldığı, hijyenik olması önem taşıyan panel ya da düğmedir.","ornek":"Sabah 10.15’te Bursa’da Aylin, paneli kimyasalla temizler, nemli renk kodlu bezle siler ve üzerinde leke kalmadığını kontrol eder.","sektor":"Konuğun eliyle sık temas ettiği yüzeylerden biri olduğundan hijyenik tutulur.","iliskili":["kh1-4-092","kh1-4-094"],"kontrol":null,"gorsel":"t12s-rezervuar-paneli"},{"id":"kh1-4-094","konu":"4.1.5","terim":"Duş başlığı","ingilizce":"Shower head","tanim":"Suyun duşta ince damlalarla yağmasını sağlayan, kireçlenmeye açık donanımdır.","ornek":"Alanya’da sert sulu bölgedeki bir otelde Murat, duş başlığını renk kodlu süngere sıkılan kimyasalla ovar ve mikrofiber bezle kurular.","sektor":"Kimyasal talimata göre uygulanır; başlık kurulanıp parlatıldıktan sonra donanımın yapısına uygun biçimde yerine takılır.","iliskili":["kh1-4-093","kh1-4-095"],"kontrol":null,"gorsel":"t10d-dus-basligi-su"},{"id":"kh1-4-095","konu":"4.1.5","terim":"Armatür","ingilizce":"Tap and mixer","tanim":"Lavabo, küvet ya da duvara monte edilen, soğuk ve sıcak su akışını sağlayan, genellikle metalden yapılmış musluklardır.","ornek":"Kuşadası’nda Derya, lavabo armatürünü duş başlığıyla aynı yöntemle temizler: kimyasalı süngerle uygular, mikrofiber bezle kurular.","sektor":"Armatürler lavabo, banyo ve bide armatürü olarak ayrılır; krom, nikel, pirinç ya da altın kaplama olabilir.","iliskili":["kh1-4-094","kh1-4-096"],"kontrol":null,"gorsel":"t10d-armatur-tek-kol"},{"id":"kh1-4-096","konu":"4.1.5","terim":"Kireçlenme","ingilizce":"Limescale","tanim":"Suyun yüzeyde bıraktığı sert, beyazımsı mineral tabakasıdır.","ornek":"Alanya’da sert suyun bulunduğu bölgede duş başlığının delikleri kireçlenince su akışı bozulur.","sektor":"Kireç çözücüyle düzenli temizlik ve iyi kurulama kireçlenmeyi azaltır.","iliskili":["kh1-4-095"],"kontrol":null,"gorsel":"t11d-kirec-musluk"},{"id":"kh1-4-097","konu":"4.1.5","terim":"Lejyoner hastalığı","ingilizce":"Legionnaires’ disease","tanim":"Legionella bakterisinin neden olduğu nadir görülen ama ciddi bir akciğer enfeksiyonudur.","ornek":"Eylül ayında İzmir’deki bir otelin müdürü, kat şefine boş odalarda neden su akıtılması gerektiğini bu hastalığı anlatarak açıklar.","sektor":"Bakteri otel, hastane, ofis gibi toplu kullanım alanlarında bulunabilir; bu yüzden konaklama tesisleri düzenli takip yapar.","iliskili":["kh1-4-098"],"kontrol":null},{"id":"kh1-4-098","konu":"4.1.5","terim":"Legionella bakterisi","ingilizce":"Legionella bacteria","tanim":"Lejyoner hastalığına neden olan, su ve havalandırma sistemleriyle yayılabilen bakteridir.","ornek":"Muğla’daki bir otelde teknik müdür, klima ve havalandırma sistemlerinin legionella yönünden takip edildiğini kat şefine hatırlatır.","sektor":"Hastalığa neden olan bakterinin takibi ve kontrolü yönetmelikle zorunlu hâle getirilmiştir.","iliskili":["kh1-4-097","kh1-4-099"],"kontrol":null},{"id":"kh1-4-099","konu":"4.1.5","terim":"Legionella’nın bulaşma yolu","ingilizce":"Route of transmission","tanim":"Bakterinin klima, jakuzili havuz ve havalandırma sistemleri gibi sistemlerden yayılan su damlacıklarının solunmasıyla bulaşmasıdır.","ornek":"Bodrum’daki otelin teknik servisi, sıcak ve nemli ortamda kullanılan hidromasajlı küvetlerin düzenli dezenfekte edilmesi gerektiğini görevlilere anlatır.","sektor":"Hastalığa ev tesisatı yoluyla yakalanma ihtimali olsa da bulaşma çoğunlukla konaklama işletmeleri gibi toplu yaşam alanı olan büyük binalarda olur.","iliskili":["kh1-4-098","kh1-4-100"],"kontrol":null,"gorsel":"t4-dus-basligi"},{"id":"kh1-4-100","konu":"4.1.5","terim":"Legionella takibinin zorunluluğu","ingilizce":"Mandatory Legionella control","tanim":"Konaklama tesislerinde belirli aralıklarla yapılan legionella takibinin yönetmelikle zorunlu hâle getirilmesidir.","ornek":"Sezon açılışında Çeşme’deki otelin teknik müdürü, takip planını kat şefiyle paylaşır.","sektor":"Takip kayıtları il halk sağlığı denetimlerinde gösterilebilecek biçimde tutulur.","iliskili":["kh1-4-099","kh1-4-101"],"kontrol":null,"gorsel":"t12d-legionella-tem"},{"id":"kh1-4-101","konu":"4.1.5","terim":"Lejyoner sözcüğü ve ilk salgın","ingilizce":"Origin of the name","tanim":"Hastalığın adını, ilk salgının görüldüğü toplantıya katılan eski askerlerden, yani lejyonerlerden aldığını anlatan bilgidir.","ornek":"Derste öğretmen hastalığın neden “lejyoner” diye anıldığını sorar; Elif, ilk salgının bir lejyoner toplantısında görüldüğünü anlatır.","sektor":"Ders materyaline göre hastalık ilk kez 1976’da Amerikan lejyonerlerinin katıldığı bir toplantıda salgın olarak görülmüş ve adını buradan almıştır. Lejyoner sözcüğü asker ve yabancı uyruklu sporcu anlamlarına da gelir.","iliskili":["kh1-4-100","kh1-4-102"],"kontrol":null,"gorsel":"t12d-bellevue-stratford"},{"id":"kh1-4-102","konu":"4.1.5","terim":"Lejyoner hastalığı yönetmeliği","ingilizce":"Regulation on Legionnaires’ disease control","tanim":"“Lejyoner Hastalığı Kontrol Usul ve Esasları Hakkında Yönetmelik”; korunma, tanı, bildirim, temizlik, dezenfeksiyon, numune alımı ve laboratuvar görevlerini düzenleyen yönetmeliktir.","ornek":"Denetim günü il halk sağlığından gelen uzmanlara kat şefi, yönetmeliğe göre tutulan takip dosyasını gösterir.","sektor":"Ders materyaline göre yönetmelik 2015 tarihli Resmî Gazete’de yayımlanmıştır; güncel hükümleri resmî kaynaktan kontrol edilir.","iliskili":["kh1-4-101"],"kontrol":null},{"id":"kh1-4-103","konu":"4.1.5","terim":"Legionella takip standardı","ingilizce":"Legionella control standard","tanim":"Boş odalarda suyun akıtılmasını, kayıt tutulmasını ve dezenfeksiyonu içeren, işletmenin kendi belirlediği yazılı uygulamadır.","ornek":"İzmir’deki otelin kat şefi, işletmenin takip standardını yeni görevlilere her sezon başında okur.","sektor":"Örnek bir işletme standardında şunlar yer alır: boş odalarda su akıtma, imzalı kayıt ve düzenli dezenfeksiyon.","iliskili":["kh1-4-104"],"kontrol":null},{"id":"kh1-4-104","konu":"4.1.5","terim":"Boş odada su akıtma","ingilizce":"Flushing taps in vacant rooms","tanim":"Kullanılmayan odalarda küvet ve lavabo armatürleri açılarak sıcak ve soğuk suyun akıtılmasıdır.","ornek":"Sabah 08.30’da Alanya’da üç gündür boş duran 312 numaralı odada Selin, lavabo ve küvet musluklarını açıp sıcak ve soğuk suyu akıtır.","sektor":"Ders materyalindeki örnek standartta işlem her gün yapılır ve en az 1 dakika sürer. Durgun su bakteri riskini artırır.","iliskili":["kh1-4-103","kh1-4-105"],"kontrol":null,"gorsel":"t15ad-musluk-su"},{"id":"kh1-4-105","konu":"4.1.5","terim":"İmzalı takip listesi","ingilizce":"Signed control log","tanim":"Suyu akıtılan odaların işaretlenip kat şefi tarafından imzalanarak dosyalanmasıdır.","ornek":"Gün sonunda Datça’daki otelde kat şefi, suyu akıtılan odaların listesini imzalayıp dosyaya koyar.","sektor":"Dosya il halk sağlığı tarafından yapılan denetimlerde gösterilmek üzere saklanır.","iliskili":["kh1-4-104","kh1-4-106"],"kontrol":null},{"id":"kh1-4-106","konu":"4.1.5","terim":"Otomasyonda legionella kontrol listesi","ingilizce":"Legionella control list on the PMS screen","tanim":"Otel otomasyonunda boş odaların günlük listelendiği ve legionella işlemi yapılanların işaretlendiği ekrandır.","ornek":"Sabah 08.00’de Çeşme’deki otelde kat ofisi görevlisi, otomasyonda boş odaların listesini açar ve görevlilere dağıtır.","sektor":"Bazı işletmeler takibi otomasyon programı üzerinden yürütür; ekranda tarih, oda numarası, kat hizmetleri durumu, son çıkış ve işaret sütunları bulunur.","iliskili":["kh1-4-105","kh1-4-107"],"kontrol":null},{"id":"kh1-4-107","konu":"4.1.5","terim":"Düzenli kireç giderme ve dezenfeksiyon","ingilizce":"Regular descaling and disinfection","tanim":"Duş başlıkları ve musluk başı süzgeçlerindeki kireç birikiminin kireç çözücüyle temizlenip dezenfektan sıvısıyla dezenfekte edilmesidir.","ornek":"Ay sonu Bodrum’daki otelde Burak, duş başlıklarını kireç çözücüyle temizler ve dezenfektan sıvısıyla dezenfekte eder.","sektor":"Ders materyalindeki örnek standartta bu uygulama tüm alanlar için ayda bir yapılır ve eldiven kullanılır.","iliskili":["kh1-4-106","kh1-4-108"],"kontrol":null,"gorsel":"t11d-kirli-dus-basligi"},{"id":"kh1-4-108","konu":"4.1.5","terim":"Su akıtma süresi ve teknik servis talimatı","ingilizce":"Flushing time set by technical service","tanim":"Odanın boş kalma süresine göre değişen su akıtma süresinin, teknik servis bölümünün talimatıyla belirlenmesidir.","ornek":"Uzun süredir boş kalan bir odayı gören Mustafa, su akıtma süresini teknik servisin yazılı talimatına göre ayarlar.","sektor":"Süre odaların boş kalma süresine göre değişebilir; belirlemek oda görevlisinin değil teknik servisin işidir.","iliskili":["kh1-4-107","kh1-4-109"],"kontrol":null},{"id":"kh1-4-109","konu":"4.1.5","terim":"Havalandırma sisteminin legionella takibi","ingilizce":"Ventilation system Legionella check","tanim":"Banyo ve odanın havalandırma sisteminin legionella yönünden günlük takibinin oda görevlisince yapılmasıdır.","ornek":"Sabah 09.00’da Selin, odanın havalandırma sistemini kontrol eder ve bir sorun görürse teknik servise haber verir.","sektor":"Isıtma ve soğutma filtrelerinin legionella bakımı teknik servisle iletişime geçilerek yürütülür.","iliskili":["kh1-4-108"],"kontrol":null},{"id":"kh1-4-110","konu":"4.1.5","terim":"Buharlı temizlik","ingilizce":"Steam cleaning","tanim":"Profesyonel makinelerle yapılan, az kimyasalla inatçı kir, leke, kireç ve bakteriyle mücadelede etkili temizlik yöntemidir.","ornek":"Bodrum’da bir VIP odanın banyosunda derzlerdeki kararmayı Kemal, buharlı makineyle temizler; çok az kimyasal kullanır.","sektor":"Buharlı temizlik büyük işlem kolaylığı sağlar; daha fazla kimyasala gerek kalmadan inatçı kire karşı tercih edilir. Ders materyaline göre makineler doğru kullanıldığında yaygın ev bakterilerinin yüzde 99,99’unu sert yüzeylerden yok ettiği belirtilir.","iliskili":["kh1-4-111"],"kontrol":null},{"id":"kh1-4-111","konu":"4.1.5","terim":"Buharlı temizlik makinesi","ingilizce":"Steam cleaner","tanim":"Suyu ısıtıp buhar hâlinde yüzeye veren, uçlarına aparat takılabilen profesyonel temizlik makinesidir.","ornek":"Sabah 09.30’da Çeşme’de Aylin, buharlı makinenin deposunu kontrol eder ve uygun aparatı seçer.","sektor":"Makine kullanım talimatında belirtildiği şekilde ve uzaklıktan buhar sıkılır; kullanımdan sonra bakımı yapılır.","iliskili":["kh1-4-110","kh1-4-112"],"kontrol":null,"gorsel":"t11d-buharli-mop"},{"id":"kh1-4-112","konu":"4.1.5","terim":"Buharlı temizlikte uygulama alanları","ingilizce":"Areas suitable for steam cleaning","tanim":"Hijyenik temizlik için makinenin fayans, cam, ayna, pencere, armatür, duş kabini ve derz aralarında kullanılabilmesidir.","ornek":"Alanya’da Murat, buharlı makineyle duş kabinini ve armatürü temizler.","sektor":"Yüzeye uygun aparat takılır; hangi alanda hangi aparatın kullanılacağı talimatta yazılıdır.","iliskili":["kh1-4-111","kh1-4-113"],"kontrol":null},{"id":"kh1-4-113","konu":"4.1.5","terim":"Buharlı temizliğin tercih edildiği yerler","ingilizce":"Where steam cleaning is preferred","tanim":"Özellikle VIP konuk odalarında ve periyodik temizlikte buharlı yöntemin kullanılmasıdır.","ornek":"Büyük bir VIP konuğun gelişinden önce Muğla’daki otelde banyo buharlı makineyle temizlenir.","sektor":"Buharlı temizlik mevcut banyonun daha parlak görünmesine yardım eder.","iliskili":["kh1-4-112","kh1-4-114"],"kontrol":null},{"id":"kh1-4-114","konu":"4.1.5","terim":"Buharlı makineyi hazırlama","ingilizce":"Preparing the steam cleaner","tanim":"Makinenin deposunun işaretli alana kadar suyla doldurulması, fişinin prize takılması ve ısındığının uyarı ışığından anlaşılmasıdır.","ornek":"Sabah 09.00’da Burak, makinenin deposunu işaretli seviyeye kadar doldurur ve ışık yanana kadar bekler.","sektor":"Hazırlık tamamlandıktan sonra temizlenecek yüzeye ya da donanıma uygun aparat makineye takılır.","iliskili":["kh1-4-113","kh1-4-115"],"kontrol":null},{"id":"kh1-4-115","konu":"4.1.5","terim":"Buharlı temizlikte çalışma sırası","ingilizce":"Work sequence in steam cleaning","tanim":"Temizliğin yukarıdan aşağıya ve kapıya en uzak noktadan kapıya doğru yapılmasıdır.","ornek":"Öğleden sonra Datça’da Derya, buharı önce duvardan başlayarak aşağıya doğru uygular ve kapıya doğru ilerler.","sektor":"Buhar yukarıdan aşağıya uygulanır; yüzey ve donanımlarda kirin yumuştuğundan emin olunduktan sonra renk koduna uygun bezle kurulamaya geçilir. Zemin uygun başlıkla buharlanır, sonra kuru mopla silinir.","iliskili":["kh1-4-114","kh1-4-116"],"kontrol":null},{"id":"kh1-4-116","konu":"4.1.5","terim":"Buharlı makinenin kullanım sonrası bakımı","ingilizce":"After-use care of the steam cleaner","tanim":"Güvenlik tedbirleri alınarak fişin çekilmesi, aparatların çıkarılıp temizlenmesi, deponun boşaltılması ve parçaların depolanmasıdır.","ornek":"Gün sonunda Kuşadası’nda Mustafa, fişi çeker, aparatları temizler, depodaki suyu boşaltır ve makineyi talimata uygun saklar.","sektor":"Her parça kullanım talimatında belirtilen şekilde temizlenerek depolanır.","iliskili":["kh1-4-115"],"kontrol":null},{"id":"kh1-4-117","konu":"4.1.5","terim":"Banyo zemini temizliği","ingilizce":"Bathroom floor cleaning","tanim":"Banyonun zeminini en son, zemin cinsine uygun araç gereçle ve çıkışa en uzak yerden başlayarak temizleme işlemidir.","ornek":"Akşam 17.20’de Alanya’da Selin, tüm yüzeyleri bitirdikten sonra banyo zeminine geçer.","sektor":"Zemin cinsine göre duruma bakarak vakumlama, paspaslama, ovma ve parlatma yapılır. Yüzeylerden damlayan su ve kir zemine kaldığı için zemin son adımda temizlenir.","iliskili":["kh1-4-118"],"kontrol":null,"gorsel":"t11d-islak-zemin-kova"},{"id":"kh1-4-118","konu":"4.1.5","terim":"Zeminde yabancı maddeler","ingilizce":"Foreign objects on the floor","tanim":"Temizlikte kullanılacak araç gerece zarar verebilecek toplu iğne, çivi, toka gibi küçük nesnelerdir.","ornek":"Datça’da banyo zemininde bir toka bulan Aylin, mopu sürmeden önce tokayı alır.","sektor":"Bu nesneler zemin temizliğinden önce toplanır; aksi hâlde araç gereç zarar görebilir.","iliskili":["kh1-4-117","kh1-4-084"],"kontrol":null},{"id":"kh1-4-120","konu":"4.1.5","terim":"Zemindeki lekelerin tespiti","ingilizce":"Stain identification","tanim":"Zemin temizliğine başlamadan önce zemindeki lekelerin görülüp çıkarılmasıdır.","ornek":"Sabah 11.30’da Fethiye’de Kemal, zeminde kalan bir boya lekesini görür ve temizliğe başlamadan önce çıkarır.","sektor":"Lekeler tespit edilip çıkarıldıktan sonra zemin türüne uygun yöntemle temizlenir.","iliskili":["kh1-4-084","kh1-4-121"],"kontrol":null},{"id":"kh1-4-121","konu":"4.1.5","terim":"Çıkışa en uzak yerden başlama","ingilizce":"Working towards the exit","tanim":"Zemin temizliğinin kapıya en uzak noktadan başlayıp kapıya doğru ilerlemesi kuralıdır.","ornek":"Öğleden sonra Kuşadası’nda Elif, zemini banyonun en iç köşesinden başlayıp kapıya doğru siler.","sektor":"Böylece temizlenmiş alana basmadan banyodan çıkılır.","iliskili":["kh1-4-120","kh1-4-122"],"kontrol":null},{"id":"kh1-4-122","konu":"4.1.5","terim":"Banyo kapısı ve kolunun silinmesi","ingilizce":"Wiping the door and handle","tanim":"Temizlik bitiminde banyo kapısının ve kapı kolunun silinmesidir.","ornek":"Akşam 17.45’te Çeşme’de Murat, temizlik sonunda banyo kapısını ve kolunu silip banyodan çıkar.","sektor":"Kapı kolu konuğun eliyle sık temas ettiği yerdir; bu yüzden son adımlarda silinir.","iliskili":["kh1-4-121","kh1-4-123"],"kontrol":null,"gorsel":"t11d-kapi-kolu"},{"id":"kh1-4-123","konu":"4.1.5","terim":"Banyoda son kontrol","ingilizce":"Final check of the bathroom","tanim":"Silinen tüm donanım ve yüzeylerin temiz olduğundan, banyonun temizliğinin ve malzemelerinin tam olduğundan emin olunmasıdır.","ornek":"Öğleden sonra Marmaris’te Aylin, banyodan çıkmadan önce aynayı, armatürleri ve zemini son kez gözden geçirir.","sektor":"Eksik ya da lekeli bir yer varsa kapıdan çıkmadan düzeltilir.","iliskili":["kh1-4-122"],"kontrol":null},{"id":"kh1-4-124","konu":"4.1.5","terim":"Su kaynaklarının korunması","ingilizce":"Protecting water resources","tanim":"Temiz su ve atık su ayrıştırmaları, sanayi atıklarının filtrelenmesi, yağmur sularının depolanması ve su tasarrufuyla var olan su kaynaklarının korunmasıdır.","ornek":"Sezon başında Muğla’daki bir otelde yönetici, personele su tasarrufunun önemini anlatır.","sektor":"Su, evlerde ve iş yerlerinde uygulanabilecek basit tasarruf yöntemleriyle korunur.","iliskili":["kh1-4-125"],"kontrol":null},{"id":"kh1-4-125","konu":"4.1.5","terim":"Banyoda su tasarrufu","ingilizce":"Water-saving practices","tanim":"Musluğu açık bırakmama, sızdıran muslukları onartma ve temizlikte kova kullanma gibi uygulamalardır.","ornek":"Sabah 10.00’da Alanya’da Selin, lavabo musluğunun damlattığını fark eder, arıza formu doldurur ve zemini kova ile siler.","sektor":"Küçük sızıntılar bile zamanla büyük su kaybına dönüşür; bu yüzden sızdıran musluk arızası bildirilir.","iliskili":["kh1-4-124","kh1-4-126"],"kontrol":null,"gorsel":"h1a-su-tasarruflu-klozet"},{"id":"kh1-4-126","konu":"4.1.5","terim":"Tatlı suyun azlığı","ingilizce":"Scarcity of fresh water","tanim":"Dünyadaki toplam suyun yalnızca küçük bir bölümünü tatlı suyun oluşturmasıdır.","ornek":"Ders sırasında öğretmen, dünyadaki suyun büyük kısmının tatlı su olmadığını anlatır ve öğrenciler tasarruf yollarını tartışır.","sektor":"Ders materyaline göre tatlı su dünyadaki suyun yüzde 2,5’lik kısmını oluşturur ve bunun büyük bölümü buzul ve buz tabakaları altında olduğundan erişimi güçtür.","iliskili":["kh1-4-125"],"kontrol":null,"gorsel":"t11d-kuru-nehir"},{"id":"kh1-4-151","konu":"4.2.1","terim":"Banyo buklet malzemeleri","ingilizce":"Bathroom amenities","tanim":"Konuğun banyoda kişisel bakım ihtiyaçlarını karşılaması için konan, çoğu küçük boy ve tek kullanımlık ürünlerin genel adıdır.","ornek":"Öğleden sonra saat 14.00’te Antalya’daki otelin 312 numaralı odasına giren konuk, lavabonun yanında sabun, şampuan ve duş jelini hazır bulur.","sektor":"Konuğun otelde kendini evindeymiş gibi hissetmesini ve ihtiyaç duyduğu ürüne anında ulaşmasını sağlar; hijyen açısından da değerlidir.","iliskili":["kh1-4-152","kh1-4-154"],"kontrol":null,"gorsel":"t15ae-havuz-amenity-seti"},{"id":"kh1-4-152","konu":"4.2.1","terim":"Kişisel bakım ürünleri","ingilizce":"Personal care products","tanim":"Sabun, şampuan, krem ve duş jeli gibi konuğun banyoda kendi bakımı için kullandığı ürünlerdir.","ornek":"Akşam 20.00’de Antalya’daki otelin 410 numaralı odasında duştan çıkan konuk, lavabonun yanında hazır duran vücut losyonunu sürer; çantasındaki ürünleri açmasına gerek kalmaz.","sektor":"Bu ürünler konuğa konforlu bir konaklama sağlar ve işletmeden memnuniyetini artırır.","iliskili":["kh1-4-151","kh1-4-153"],"kontrol":null},{"id":"kh1-4-153","konu":"4.2.1","terim":"İşletme logolu tek kullanımlık ürünler","ingilizce":"Branded single-use amenities","tanim":"Üzerinde işletmenin logosu bulunan, tek konuğun kullanması için hazırlanmış küçük boy sabun, şampuan, saç kremi ve losyonlardır.","ornek":"Bodrum’daki bir otelin mini şampuan şişesinde otelin logosu görünür; konuk ayrılınca kullanılan şişe atılır, odaya yenisi konur.","sektor":"Ürünün boyutu, kalitesi ve çeşidi otelin sunduğu hizmetin fiyatına ve çeşitliliğine göre değişir.","iliskili":["kh1-4-152","kh1-4-154"],"kontrol":null},{"id":"kh1-4-154","konu":"4.2.1","terim":"Buklet malzemeleri ve işletmenin saygınlığı","ingilizce":"Amenities as a sign of quality","tanim":"Konuğa sunulan buklet malzemelerinin beğenilmesinin, konuk memnuniyetini ve işletmenin saygınlığını artırdığını anlatan ilkedir.","ornek":"Konya’dan gelen bir aile banyodaki ürünleri kaliteli bulur ve çıkışta resepsiyondaki memnuniyet formuna olumlu not yazar.","sektor":"Maliyeti düşük ama iyi seçilmiş ürünler, konuğun işletmeyi tekrar tercih etmesine katkı sağlar.","iliskili":["kh1-4-151","kh1-4-155","kh1-4-156"],"kontrol":null},{"id":"kh1-4-155","konu":"4.2.1","terim":"Logolu hediye malzemeler","ingilizce":"Promotional giveaways","tanim":"Konuğun yanında götürebileceği kalem, kibrit ya da ayakkabı çekeceği gibi düşük maliyetli hediyelerdir.","ornek":"Sabah 09.30’da Antalya’daki otelin 205 numaralı odasında valizini toplayan konuk, masadaki kalemi hatıra olarak çantasına koyar; kalemin üzerinde otelin adı yazılıdır.","sektor":"Konuk bu hediyeleri kullandıkça işletmenin adını görür; bu da işletmeye ek bir tanıtım imkânı sunar.","iliskili":["kh1-4-154","kh1-4-153"],"kontrol":null},{"id":"kh1-4-156","konu":"4.2.1","terim":"Konuk deneyiminin derecelendirilmesi","ingilizce":"Guest rating of facilities","tanim":"Konukların kendilerine sunulan hizmetin ve olanakların kalitesini değerlendirerek konaklama deneyimine not vermesidir.","ornek":"Pazar sabahı 10.00’da Bodrum’daki otelden ayrılan bir çift, resepsiyonda doldurduğu formda odanın temizliğini ve banyo ürünlerinin kalitesini ayrı ayrı puanlar.","sektor":"Buklet malzemelerinin kalitesi, konuğun verdiği notu doğrudan etkileyen olanaklardan biridir.","iliskili":["kh1-4-154","kh1-4-151"],"kontrol":null},{"id":"kh1-4-157","konu":"4.2.1","terim":"Banyo buklet listesi","ingilizce":"Amenity list","tanim":"Bir konaklama işletmesinin banyoda kullanabileceği malzemelerin sıralandığı listedir.","ornek":"Kat şefi Pınar, yaz sezonu öncesinde banyo buklet listesini gözden geçirir ve eksik ürünler için depodan talep verir.","sektor":"Hangi ürünün hangi odaya konacağı işletmeye ve oda kategorisine göre değişir; listede bornoz kartından güneş kremine kadar çok sayıda kalem bulunur.","iliskili":["kh1-4-158","kh1-4-159"],"kontrol":null},{"id":"kh1-4-158","konu":"4.2.1","terim":"Sınıfa göre asgari buklet malzemeleri","ingilizce":"Minimum amenities by hotel class","tanim":"Konaklama tesisinin sınıfına göre oda ve banyoda bulunması gereken en az buklet malzemelerini belirleyen yönetmelik hükmüdür.","ornek":"Dört yıldızlı bir otelin müdürü, banyolarda bornoz ve diş seti gibi yönetmelikte sayılan malzemelerin eksiksiz olup olmadığını kontrol ettirir.","sektor":"Ders materyaline göre Turizm Tesislerinin Belgelendirilmesine ve Niteliklerine İlişkin Yönetmeliğe uygun olarak dört yıldızlı otellerin oda ve banyolarında bornoz, diş seti, tıraş seti ve tırnak törpüsü gibi malzemelerden en az on çeşit bulunur; güncel liste yönetmelikten kontrol edilir.","iliskili":["kh1-4-157","kh1-4-159"],"kontrol":null},{"id":"kh1-4-159","konu":"4.2.1","terim":"Oda kategorisine göre buklet miktar tablosu","ingilizce":"Amenity matrix by room category","tanim":"İşletmenin her oda kategorisi için hangi buklet malzemesinden kaç adet konacağını gösteren tablodur.","ornek":"Kat görevlisi Elif, balayı odası için hazırlanan tabloya bakar ve standart odadakinden farklı olarak bir de vanity set yerleştirir.","sektor":"Örnek bir işletme tablosunda standart oda, VIP odalar, balayı ve kışlık konsept için sabun, diş seti, tıraş seti, törpü ve pamuk gibi kalemlerin sayıları farklıdır; her işletme kendi tablosunu hazırlar.","iliskili":["kh1-4-157","kh1-4-160"],"kontrol":null},{"id":"kh1-4-160","konu":"4.2.1","terim":"Vanity set","ingilizce":"Vanity set","tanim":"Küçük kişisel bakım malzemelerinin tek pakette toplandığı settir.","ornek":"Akşam 18.00’de Çeşme’deki otelin balayı odasına giren çift, lavabonun yanında hazırlanmış vanity seti görür.","sektor":"İçeriği işletmeye göre değişir; çoğunlukla pamuk, kulak çubuğu ve tırnak törpüsü gibi küçük kalemlerden oluşur. Örnek işletme tablosunda balayı kategorisi için ayrılmış bir kalemdir.","iliskili":["kh1-4-159","kh1-4-157"],"kontrol":null},{"id":"kh1-4-161","konu":"4.2.1","terim":"Duş jeli","ingilizce":"Shower gel","tanim":"Vücudu duşta yıkamak için kullanılan sıvı temizleyicidir.","ornek":"Sabah 07.00’de antrenmandan dönen konuk, Alanya’daki otelin duş kabininin yanındaki küçük şişede duş jelini bulur ve hemen yıkanır.","sektor":"Banyo bukletinin temel kalemlerindendir; şişenin üzerinde çoğunlukla işletmenin logosu bulunur.","iliskili":["kh1-4-162","kh1-4-163"],"kontrol":null},{"id":"kh1-4-162","konu":"4.2.1","terim":"Şampuan","ingilizce":"Shampoo","tanim":"Saçı yıkamak için kullanılan temizleyicidir.","ornek":"Akşam 19.30’da Kuşadası’ndaki otelin 112 numaralı odasında saçını yıkamak isteyen konuk, duşa girince şampuanı duş jelinin yanında bulur.","sektor":"Kişisel bakım ürünlerindendir; odada kalan kişi sayısı kadar yerleştirilir.","iliskili":["kh1-4-161","kh1-4-165"],"kontrol":null},{"id":"kh1-4-163","konu":"4.2.1","terim":"Vücut losyonu","ingilizce":"Body lotion","tanim":"Duştan sonra cildi nemlendirmek için sürülen bakım ürünüdür.","ornek":"Kış akşamı 21.00’de Bursa’daki otelin 305 numaralı odasında duştan çıkan konuk, lavabonun yanındaki küçük losyon şişesini açıp ellerine ve kollarına sürer.","sektor":"Küçük boy ve çoğunlukla logolu tek kullanımlık şişelerle sunulur.","iliskili":["kh1-4-161","kh1-4-162"],"kontrol":null,"gorsel":"t12s-losyon"},{"id":"kh1-4-164","konu":"4.2.1","terim":"Banyo kesesi ve lif","ingilizce":"Bath mitt and loofah","tanim":"Duşta vücudu ovarak temizlemeye yarayan kese, lif eldiveni ve lif gibi gereçlerdir.","ornek":"Akşam 20.30’da Antalya’daki otelin banyosunda duş alan konuk, cildini canlandırmak için lif eldivenini sabunla birlikte kullanır.","sektor":"Banyo bukletinin kişisel bakım gereçlerindendir; duşta ovma amacıyla kullanılır.","iliskili":["kh1-4-161","kh1-4-165"],"kontrol":null,"kitapDisi":true,"gorsel":"h1a-banyo-lifi"},{"id":"kh1-4-165","konu":"4.2.1","terim":"Duş bonesi","ingilizce":"Shower cap","tanim":"Duş alırken saçın ıslanmaması için başa takılan koruyucu başlıktır.","ornek":"Sabah 07.45’te Muğla’daki otelin 220 numaralı odasında saçını ıslatmak istemeyen konuk, banyodaki duş bonesini takarak duşa girer.","sektor":"Buklet listesinde yer alan kalemlerdendir; ayrı bir tekstil değil, tek kullanımlık buklet malzemesidir.","iliskili":["kh1-4-162","kh1-4-164"],"kontrol":null,"gorsel":"t10d-dus-bonesi-otel"},{"id":"kh1-4-166","konu":"4.2.1","terim":"Mini el sabunu","ingilizce":"Guest soap","tanim":"El ve yüz yıkamak için lavabonun yanına konan küçük boy katı sabundur.","ornek":"Sabah 08.15’te Çeşme’deki otelin lavabosuna yaklaşan konuk, kutudaki mini sabunu alıp ellerini yıkar.","sektor":"Kişiye özel ve tek kullanımlık olduğu için hijyen açısından değerlidir.","iliskili":["kh1-4-167","kh1-4-151"],"kontrol":null,"gorsel":"t10d-otel-sabunu"},{"id":"kh1-4-167","konu":"4.2.1","terim":"Sıvı el sabunu","ingilizce":"Liquid hand soap","tanim":"Şişe içinde sunulan, elleri yıkamak için kullanılan akışkan sabundur.","ornek":"Gece 23.00’te Bodrum’daki otele kalabalık bir akşam yemeğinden dönen konuk, lavabonun yanındaki şişeden sıvı sabun alıp ellerini yıkar.","sektor":"Mini el sabunuyla birlikte buklet listesinde ayrı kalem olarak yer alır.","iliskili":["kh1-4-166","kh1-4-151"],"kontrol":null,"gorsel":"t11d-sivi-sabun"},{"id":"kh1-4-168","konu":"4.2.1","terim":"Banyo tuzu","ingilizce":"Bath salts","tanim":"Küvet suyuna eklenerek rahatlatıcı bir banyo sağlayan tuzdur.","ornek":"Akşam 22.00’de İstanbul’dan uzun bir uçuşla Antalya’daki otele gelen konuk, küvetin suyuna banyo tuzunu ekleyip dinlenir.","sektor":"Rahatlama sunan buklet kalemlerindendir; oda kategorisine ve işletmenin standardına göre bulunur.","iliskili":["kh1-4-169","kh1-4-151"],"kontrol":null,"gorsel":"t10d-banyo-tuzu-sise"},{"id":"kh1-4-169","konu":"4.2.1","terim":"Banyo köpüğü","ingilizce":"Bubble bath","tanim":"Küvet suyuna eklenerek köpük oluşturan temizleyicidir.","ornek":"Akşam 21.30’da Fethiye’deki otelin küvetli suit odasında kalan konuk, suya banyo köpüğünü dökerek uzun bir banyo yapar.","sektor":"Banyo tuzuyla aynı gruptadır; küvet bulunan odalarda anlam kazanır.","iliskili":["kh1-4-168","kh1-4-151"],"kontrol":null,"gorsel":"t10d-banyo-kopugu-el"},{"id":"kh1-4-170","konu":"4.2.1","terim":"Diş seti","ingilizce":"Dental kit","tanim":"Diş macunu ve diş fırçasından oluşan tek kullanımlık bakım setidir.","ornek":"Sabah 06.45’te valizi gelmediği için diş fırçası yanında olmayan konuk, Alanya’daki otelin banyosundaki diş setiyle dişlerini fırçalar.","sektor":"Odada kalan kişi sayısı kadar konur.","iliskili":["kh1-4-171","kh1-4-172"],"kontrol":null,"gorsel":"os-dis-macunu"},{"id":"kh1-4-171","konu":"4.2.1","terim":"Tıraş seti","ingilizce":"Shaving kit","tanim":"Konuğun banyoda tıraş olabilmesi için hazırlanan, tıraş kremi, tıraş bıçağı ve tıraş losyonundan oluşan settir.","ornek":"Sabah 07.30’da Ankara’daki otelin 612 numaralı odasında toplantıya hazırlanan konuk, banyodaki sette tıraş kremini, bıçağı ve losyonu birlikte bulur.","sektor":"Diş seti gibi tek kullanımlıktır; oda kategorisine göre sayısı değişir.","iliskili":["kh1-4-170","kh1-4-172"],"kontrol":null,"gorsel":"t11d-tiras-seti"},{"id":"kh1-4-172","konu":"4.2.1","terim":"Tırnak törpüsü","ingilizce":"Nail file","tanim":"Tırnakları düzeltmek için kullanılan küçük törpüdür.","ornek":"Akşam 19.00’da Bodrum’daki otelin banyosunda tırnağı kırılan konuk, banyodaki törpüyle tırnağını düzeltir.","sektor":"Asgari buklet listesinde bornoz ve diş seti ile birlikte sayılan kalemlerdendir.","iliskili":["kh1-4-170","kh1-4-171"],"kontrol":null,"gorsel":"t12s-tirnak-torpusu"},{"id":"kh1-4-173","konu":"4.2.1","terim":"Makyaj temizleme pamuğu","ingilizce":"Cotton pads","tanim":"Makyajı silmek için kullanılan yumuşak pamuktur.","ornek":"Gece 23.15’te Antalya’daki otelin 408 numaralı odasına yemekten dönen konuk, banyodaki pamukla makyajını siler.","sektor":"Banyo bukletinin kişisel bakım kalemlerindendir.","iliskili":["kh1-4-174","kh1-4-170"],"kontrol":null,"gorsel":"t11d-pamuk-makyaj"},{"id":"kh1-4-174","konu":"4.2.1","terim":"Kulak temizleme çubuğu","ingilizce":"Cotton buds","tanim":"Kulağın dışını temizlemek için kullanılan, ucu pamukla kaplı küçük çubuktur.","ornek":"Öğleden sonra 15.30’da havuzdan çıkıp duş alan konuk, Marmaris’teki otelin banyosundaki çubukla kulağını temizler.","sektor":"Pamuk ve diş seti gibi küçük bakım malzemeleriyle aynı grupta düşünülür.","iliskili":["kh1-4-173","kh1-4-160"],"kontrol":null,"gorsel":"t11d-kulak-cubugu"},{"id":"kh1-4-175","konu":"4.2.1","terim":"Kutu mendil","ingilizce":"Tissue box","tanim":"Kutunun içinde dizili hâlde sunulan, tek tek çekilerek kullanılan kâğıt mendildir.","ornek":"Sabah 08.00’de nezle olan konuk, Konya’daki otelin lavabosunun yanındaki kutudan mendil çeker.","sektor":"Banyo bukletinin kâğıt ürünlerindendir; konuğun kolay ulaşacağı yere konur.","iliskili":["kh1-4-176","kh1-4-177"],"kontrol":null,"gorsel":"t11d-kutu-mendil"},{"id":"kh1-4-176","konu":"4.2.1","terim":"Kolonyalı mendil","ingilizce":"Cologne wipe","tanim":"Elleri ve yüzü ferahlatmak için kullanılan, kolonya emdirilmiş küçük mendildir.","ornek":"Akşam 18.30’da uzun bir otobüs yolculuğundan sonra Trabzon’daki otele gelen konuk, kolonyalı mendille yüzünü ferahlatır.","sektor":"Türkiye’de misafirperverlik geleneğinin bir parçası olan kolonya, buklet listesinde mendil olarak da yer alır.","iliskili":["kh1-4-175","kh1-4-177"],"kontrol":null},{"id":"kh1-4-177","konu":"4.2.1","terim":"Gözlük temizleme mendili","ingilizce":"Lens cleaning wipe","tanim":"Gözlüğün camlarını çizmeden silmek için hazırlanmış, tek kullanımlık küçük mendildir.","ornek":"Sabah 07.15’te Alanya’daki otelin banyosunda buharlanan gözlüğünü gören konuk, mendili açıp camlarını siler.","sektor":"Buklet listesinde konuğun küçük ihtiyaçlarını düşünen bir kalem olarak yer alır.","iliskili":["kh1-4-175","kh1-4-176"],"kontrol":null,"gorsel":"t12s-gozluk-bezi"},{"id":"kh1-4-178","konu":"4.2.1","terim":"Banyoda bardak kapağı","ingilizce":"Glass cover (bathroom)","tanim":"Banyodaki bardağın üzerini örterek temiz kalmasını sağlayan kapaktır.","ornek":"Sabah 10.00’da Bodrum’daki otelin 215 numaralı odasında lavabonun yanındaki bardağın üstünde kapak durduğunu gören konuk, bardağın kullanılmamış olduğunu anlar.","sektor":"Banyo buklet listesinde yer alır; bardağı toz ve bulaşmadan korur.","iliskili":["kh1-4-179","kh1-4-151"],"kontrol":null},{"id":"kh1-4-179","konu":"4.2.1","terim":"Hijyen poşeti","ingilizce":"Sanitary bag","tanim":"Hijyenik atıkların atılmadan önce kapatılıp ayrı toplanmasını sağlayan küçük poşettir.","ornek":"Akşam 21.45’te Çeşme’deki otelin banyosunda hijyen poşetini gören konuk, kullandığı ürünü poşete koyup ağzını kapatır.","sektor":"Buklet listesinde yer alan kalemlerdendir; kullanılan ürün poşete konup kapatıldığı için hijyen sağlanır.","iliskili":["kh1-4-178","kh1-4-151"],"kontrol":null},{"id":"kh1-4-180","konu":"4.2.1","terim":"Bornoz kartı","ingilizce":"Bathrobe card","tanim":"Odadaki bornozla ilgili konuğu bilgilendiren karttır.","ornek":"Banyoya giren konuk, askıdaki bornozun yanında bornoz kartını görür ve okur.","sektor":"Otel bilgi kartları arasında yer alır; kartın içeriği işletmeden işletmeye değişir.","iliskili":["kh1-4-181","kh1-4-182"],"kontrol":null},{"id":"kh1-4-181","konu":"4.2.1","terim":"Havlu değişim kartı","ingilizce":"Towel change card","tanim":"Konuğun havlularının değiştirilmesini isteyip istemediğini bildirdiği karttır.","ornek":"Sabah 08.30’da Antalya’daki otelin 204 numaralı odasında kahvaltıya inmeden önce havlu değişim kartını gören konuk, tercihini işaretler.","sektor":"Konuğun tercihini sorarak hizmeti kişiselleştirir; çevre kartıyla birlikte uygulanabilir.","iliskili":["kh1-4-180","kh1-4-182"],"kontrol":null},{"id":"kh1-4-182","konu":"4.2.1","terim":"Çevre kartı","ingilizce":"Environment card","tanim":"Konuğu işletmenin çevre dostu uygulamalarına katılmaya davet eden bilgi kartıdır.","ornek":"Sabah 09.00’da Muğla’daki otelin banyosunda çevre kartını okuyan konuk, havlularının her gün yenilenmesini istemeyeceğini düşünür.","sektor":"Otel bilgi kartları arasında yer alır; havlu kullanımı gibi çevre uygulamaları bu kartla duyurulur.","iliskili":["kh1-4-181","kh1-4-180"],"kontrol":null},{"id":"kh1-4-183","konu":"4.2.1","terim":"WC kartı","ingilizce":"WC card","tanim":"Tuvalet kullanımıyla ilgili konuğa kısa bilgi ve hatırlatma veren karttır.","ornek":"Banyoya giren konuk, tuvaletin yanındaki WC kartını okuyarak işletmenin hatırlatmasını görür.","sektor":"Banyo buklet listesinde yer alan kartlardan biridir; içeriği işletmeye göre değişir.","iliskili":["kh1-4-180","kh1-4-182"],"kontrol":null},{"id":"kh1-4-184","konu":"4.2.1","terim":"Banyo çiçeği","ingilizce":"Bathroom flowers","tanim":"Banyoyu güzelleştirmek için lavabo ya da tezgâh üstüne konan çiçektir.","ornek":"Akşam 17.00’de Çeşme’deki otelin balayı odasına gelen çift, lavabo tezgâhındaki küçük vazoda çiçek görür.","sektor":"Buklet listesinin son kalemlerindendir; yerleştirmede banyonun dekorasyonuna uyumu önemlidir.","iliskili":["kh1-4-185","kh1-4-151"],"kontrol":null,"gorsel":"t11c-temiz-havlu"},{"id":"kh1-4-185","konu":"4.2.1","terim":"Güneş kremi","ingilizce":"Sun cream","tanim":"Cildi güneşin zararlı etkilerinden korumak için sürülen kremdir.","ornek":"Sabah 10.00’da plaja inmeden önce Alanya’daki otelin banyosundan çıkan konuk, güneş kremini yüzüne ve koluna sürer.","sektor":"Buklet listesinde yer alır; işletme bu ürünü koyup koymayacağına kendi standardına göre karar verir.","iliskili":["kh1-4-184","kh1-4-163"],"kontrol":null,"gorsel":"t15ae-gunes-kremi"},{"id":"kh1-4-231","konu":"4.2.1","terim":"Otel seçiminde bütçe ve olanaklar","ingilizce":"Budget and facilities in choosing a hotel","tanim":"Bir turistin otel tercihini, ayırabildiği bütçe ile işletmenin sunduğu olanakların belirlemesidir.","ornek":"Haziran ayında Antalya’da otel arayan bir aile, hem ayırdığı bütçeye uyan hem de odada banyo ürünleri ve bornoz sunan bir oteli seçer.","sektor":"Rekabetin yüksek olduğu sektörde işletmeler yüksek doluluğu korumak için kaliteli tesis ve olanak sunar; buklet malzemeleri bu olanakların konuğun hemen gördüğü parçalarıdır.","iliskili":["kh1-4-154","kh1-4-186"],"kontrol":null},{"id":"kh1-4-232","konu":"4.2.1","terim":"Saç kremi","ingilizce":"Hair conditioner","tanim":"Şampuanla yıkanan saçı yumuşatmak ve taramayı kolaylaştırmak için kullanılan bakım ürünüdür.","ornek":"Akşam 20.15’te Fethiye’deki otelin 208 numaralı odasında saçını yıkayan konuk, duştan çıkmadan önce şampuanın yanındaki saç kremini kullanır.","sektor":"Ders materyaline göre dört yıldızlı otellerin asgari buklet listesinde yer alır; güncel liste kontrol edilir. Küçük boy ve çoğunlukla logolu şişelerle sunulur.","iliskili":["kh1-4-162","kh1-4-158"],"kontrol":null},{"id":"kh1-4-233","konu":"4.2.1","terim":"Cımbız ve tırnak makası","ingilizce":"Tweezers and nail scissors","tanim":"Konuğun kaş, tüy ve tırnak bakımını yapması için banyoda bulunabilen küçük bakım gereçleridir.","ornek":"Sabah 08.00’de Çeşme’deki otelin 312 numaralı odasında toplantıya hazırlanan konuk, banyodaki cımbızla kaşını düzeltir.","sektor":"Ders materyaline göre dört yıldızlı otellerin asgari buklet listesinde tırnak törpüsüyle birlikte yer alır; güncel liste kontrol edilir.","iliskili":["kh1-4-172","kh1-4-158"],"kontrol":null,"gorsel":"os-tirnak-makasi"},{"id":"kh1-4-234","konu":"4.2.1","terim":"Uyku gözlüğü","ingilizce":"Eye mask","tanim":"Işıktan rahatsız olan konuğun gözünü örterek uyumasına yardım eden, yumuşak kumaştan göz bandıdır.","ornek":"Sabah 07.00’de perdeden süzülen ışık yüzünden uyuyamayan konuk, Bodrum’daki otelin 118 numaralı odasındaki uyku gözlüğünü takar.","sektor":"Ders materyaline göre dört yıldızlı otellerin oda ve banyolarında bulunması beklenen kalemlerden biridir; güncel liste kontrol edilir. Konuk konforuna yönelik küçük bir ayrıntıdır.","iliskili":["kh1-4-158","kh1-4-185"],"kontrol":null,"gorsel":"t11d-uyku-gozlugu"},{"id":"kh1-4-235","konu":"4.2.1","terim":"Bloknot ve kalem","ingilizce":"Notepad and pen","tanim":"Konuğun not alması ya da isteklerini yazması için odada bulundurulan kâğıt ve yazı gerecidir.","ornek":"Sabah 08.00’de Konya’daki otelin 401 numaralı odasında konuk, o günkü randevusunu masadaki bloknota yazar.","sektor":"Ders materyaline göre dört yıldızlı otellerin asgari buklet listesinde yer alır; güncel liste kontrol edilir. Kalemin üzerinde çoğunlukla işletmenin adı bulunur.","iliskili":["kh1-4-155","kh1-4-158"],"kontrol":null,"gorsel":"t11k-defter-kalemler"},{"id":"kh1-4-186","konu":"4.2.2","terim":"Buklet malzemesinin sayısı, çeşidi ve kalitesi","ingilizce":"Amenity quantity, range and quality","tanim":"Banyodaki buklet malzemelerinin kaç tane, hangi türde ve hangi kalitede olacağının işletmenin hizmetine ve maliyetine göre değiştiğini anlatan ilkedir.","ornek":"Şehir otelindeki sade odanın bukleti ile aynı otelin süit odasındaki zengin set farklıdır; ikisi de işletmenin belirlediği standartla hazırlanır.","sektor":"Sayı, çeşit ve kalite işletmenin sunduğu hizmete ve ortaya çıkan maliyete göre belirlenir.","iliskili":["kh1-4-187","kh1-4-189"],"kontrol":null,"gorsel":"t12d-banyo-buklet-kuvet"},{"id":"kh1-4-187","konu":"4.2.2","terim":"Konuk türüne göre buklet farkı","ingilizce":"Amenities by guest type","tanim":"Aynı işletmede konuğun türüne göre banyoya konan malzemenin değişebildiği uygulamadır.","ornek":"Aynı otelde VIP bir konuğun odasındaki set, standart odadaki setten daha zengindir.","sektor":"Görevli, odanın kategorisinden emin olmadan malzeme seçmez.","iliskili":["kh1-4-186","kh1-4-188"],"kontrol":null},{"id":"kh1-4-188","konu":"4.2.2","terim":"VIP konuk için buklet seçimi","ingilizce":"Amenity selection for VIP guests","tanim":"VIP olarak kabul edilen konukların odalarında, işletmenin belirlediği seviyeye göre daha özel malzeme seçilmesidir.","ornek":"Üst düzey bir konuğun odasında standart sabun yerine işletmenin VIP listesindeki ürünler bulunur.","sektor":"Ders materyaline göre VIP 1 olan konuk odasına havlu bırakılırken VIP 5 için bornoz tercih edilir; hangi seviyeye ne konacağını her işletmenin kendi VIP prosedürü belirler.","iliskili":["kh1-4-187","kh1-4-193"],"kontrol":null},{"id":"kh1-4-189","konu":"4.2.2","terim":"Oda kategorisinden emin olma","ingilizce":"Checking the room category","tanim":"Buklet malzemesi yerleştirilmeden önce odanın hangi kategoride olduğunun kontrol edilmesidir.","ornek":"Kat görevlisi Cem, temizlenmiş banyoya set koymadan önce odanın kategorisini kontrol eder.","sektor":"Yanlış kategoriye göre seçilen malzeme konuğun beklentisini karşılamaz; kontrol yerleştirme aşamasından önce yapılır.","iliskili":["kh1-4-187","kh1-4-186"],"kontrol":null},{"id":"kh1-4-190","konu":"4.2.2","terim":"Terlik ve havlu seti","ingilizce":"Slipper and towel set","tanim":"Konuk banyosunda birlikte sunulabilen terlik ve havlu takımıdır.","ornek":"Akşam 21.00’de Kuşadası’ndaki otelin banyosunda duştan çıkan konuk, terliğini ve havlusunu aynı rafta hazır bulur.","sektor":"Konuk türüne göre banyoda havlu ya da bornoz tercih edilebilir; terlik de çoğunlukla havluyla birlikte hazır konur.","iliskili":["kh1-4-187","kh1-4-188"],"kontrol":null},{"id":"kh1-4-191","konu":"4.2.2","terim":"Eksik buklet malzemesini belirleme","ingilizce":"Identifying missing amenities","tanim":"Banyoda hangi buklet malzemesinin eksik olduğunun kontrol edilerek tespit edilmesidir.","ornek":"Oda görevlisi Seda, banyoda şampuan ve duş bonesinin bittiğini fark eder ve kat arabasından alacaklarını belirler.","sektor":"Seçimin ilk adımıdır; ne eksikse ona göre malzeme alınır.","iliskili":["kh1-4-192","kh1-4-193"],"kontrol":null},{"id":"kh1-4-192","konu":"4.2.2","terim":"Banyo için kişi sayısına göre seçim","ingilizce":"Selecting by occupancy","tanim":"Odada kalan kişi sayısı kadar buklet malzemesinin kat arabasından seçilmesidir.","ornek":"İki kişinin kaldığı odada Seda, kat arabasından iki diş seti ve iki şampuan seçer.","sektor":"Seçilen malzeme sayısı odadaki kişi sayısıyla uyumlu olmalıdır.","iliskili":["kh1-4-191","kh1-4-193"],"kontrol":null},{"id":"kh1-4-193","konu":"4.2.2","terim":"Banyoda özel durumlu konuk için ekstra malzeme seçimi","ingilizce":"Choosing extra bathroom amenities for special guests","tanim":"VIP, engelli, tekrar gelen ya da hasta gibi özel durumu olan konuklar için işletme prosedürüne göre ek malzeme ayrılmasıdır.","ornek":"Daha önce üç kez gelen konuğun odasında Seda, prosedürde yazılan ek ürünü seçer.","sektor":"Ekstra malzeme yalnız işletme prosedüründe öngörülmüşse seçilir.","iliskili":["kh1-4-194","kh1-4-191"],"kontrol":null},{"id":"kh1-4-194","konu":"4.2.2","terim":"Banyo bukletinde tekrar gelen konuk","ingilizce":"Repeat guest (bathroom amenities)","tanim":"Daha önce aynı işletmede konaklamış olup banyo malzemesi seçiminde özel durumlu sayılabilen konuktur.","ornek":"Temmuz ayında Çeşme’deki otele üçüncü kez gelen bir aile için kat şefi karşılama notu hazırlar; Seda banyo malzemesini de işletme prosedürüne göre seçer.","sektor":"Sadakati takdir etmek için bazı işletmeler bu konuklara özel malzeme ayırır.","iliskili":["kh1-4-193","kh1-4-187"],"kontrol":null},{"id":"kh1-4-195","konu":"4.2.2","terim":"Buklet standı","ingilizce":"Amenity tray / stand","tanim":"Banyodaki küçük malzemelerin düzenli biçimde gösterildiği stand ya da tepsidir.","ornek":"Sabah 09.30’da Antalya’daki otelin 301 numaralı odasında lavabonun yanındaki standda sabun, şampuan ve duş jeli düzgünce sıralanmıştır.","sektor":"Malzemeleri toplu ve düzgün göstererek banyonun şık görünmesine yardım eder.","iliskili":["kh1-4-191","kh1-4-192"],"kontrol":null,"gorsel":"t15ae-amenity-tepsi"},{"id":"kh1-4-196","konu":"4.2.2","terim":"Buklet uygulamasında araç gereç","ingilizce":"Equipment for amenity tasks","tanim":"Uygulamada üniforma, isimlik, bölüm ve kat pas anahtarı, kat ofisi anahtarı, anahtar kayıt defteri, kalem, oda durum raporu ve kat arabasından oluşan donanımdır.","ornek":"Uygulama sabahı Zeynep önlüğünü giyer, isimliğini takar, pas anahtarını imza karşılığı alır ve kat arabasını hazırlar.","sektor":"Buklet seçme ve yerleştirme uygulamaları kat hizmetleri atölyesinde yapılır; araç gerecin tamamı işe başlamadan hazır bulunur.","iliskili":["kh1-4-197","kh1-4-198"],"kontrol":null},{"id":"kh1-4-197","konu":"4.2.2","terim":"Buklet uygulamasının değerlendirme ölçütleri","ingilizce":"Assessment criteria for the task","tanim":"İşe hazırlık, uygulama becerisi, zamanı kullanma, iletişim becerisi ve olağan dışı durumlara hazır bulunuşluk ölçütleriyle yapılan puanlamadır.","ornek":"Öğretmen, Zeynep’in buklet uygulamasını yalnız adımlara göre değil, hazırlığına, zamanına ve iletişimine göre de puanlar.","sektor":"Uygulama başarısı yalnız adımların doğru yapılmasına değil, hazırlığa, zamana ve iletişime de bağlıdır.","iliskili":["kh1-4-196","kh1-4-198"],"kontrol":null},{"id":"kh1-4-198","konu":"4.2.2","terim":"Buklet turunda oda durum raporu","ingilizce":"Room status report during amenity rounds","tanim":"Hangi odaya gidileceğini gösteren ve buklet işi bittiğinde doldurularak teslim edilen rapordur.","ornek":"Zeynep, rapora göre temizlenecek odaya gider; işi bitirince raporu doldurup kat şefine teslim eder.","sektor":"Raporun doldurulması ve teslimi uygulamanın son adımlarındandır.","iliskili":["kh1-4-196","kh1-4-197"],"kontrol":null},{"id":"kh1-4-199","konu":"4.2.3","terim":"Banyo buklet yerleştirme kuralları","ingilizce":"Bathroom amenity placement rules","tanim":"Buklet malzemelerinin banyoda dekorasyona uygun, kolay ulaşılır ve düzenli yerleştirilmesini sağlayan kurallardır.","ornek":"Zeynep, mini sabunu lavabonun yanına, duş jelini ve şampuanı küvetin kenarındaki rafa yerleştirir.","sektor":"Yerleştirme güzel görünmenin yanında konuğun ihtiyacı anında malzemeye ulaşmasını da sağlar.","iliskili":["kh1-4-200","kh1-4-201"],"kontrol":null,"gorsel":"t12d-otel-banyosu-paris"},{"id":"kh1-4-200","konu":"4.2.3","terim":"Dekorasyona uygun yerleştirme","ingilizce":"Placement in keeping with the decor","tanim":"Malzemelerin banyonun renk ve düzenine uyacak biçimde konmasıdır.","ornek":"Bej fayanslı banyoda krem renkli kutular lavabonun yanında yan yana düzgünce dizilir.","sektor":"Buklet malzemeleri konuğun ihtiyacını karşılamasının yanında banyonun şık görünmesine de katkı sağlar.","iliskili":["kh1-4-199","kh1-4-201"],"kontrol":null},{"id":"kh1-4-201","konu":"4.2.3","terim":"Konuğun kolay ulaşacağı yer","ingilizce":"Easy-to-reach placement","tanim":"Malzemelerin, konuğun ihtiyaç duyduğu anda kolayca uzanabileceği bir alana yerleştirilmesidir.","ornek":"Duştan çıkan konuk, losyonu aramadan lavabonun yanında bulur.","sektor":"İşletmenin uygun gördüğü alan seçilir; göze hoş görünmesi ve kolay ulaşılması birlikte aranır.","iliskili":["kh1-4-199","kh1-4-202"],"kontrol":null},{"id":"kh1-4-202","konu":"4.2.3","terim":"Kullanım sırasına göre yerleştirme","ingilizce":"Placement in order of use","tanim":"Malzemelerin, kendilerine ayrılmış yere özel kap ya da kutu içinde, kullanım sırasına ve amacına göre dizilmesidir.","ornek":"Duş jeli ve şampuan duş alanında, diş seti lavabonun yanında durur; her ürün kendi kutusundadır.","sektor":"Sıralı yerleşim, konuğun aradığını hemen bulmasını sağlar.","iliskili":["kh1-4-201","kh1-4-203"],"kontrol":null},{"id":"kh1-4-203","konu":"4.2.3","terim":"Malzemelerin boyutunu gözetme","ingilizce":"Considering item size","tanim":"Yerleştirmede malzemelerin büyük ya da küçük olmasının dikkate alınmasıdır.","ornek":"Zeynep küçük tırnak törpüsü kutusunu büyük şişelerin arkasında kaybolmayacak biçimde öne yerleştirir.","sektor":"Boyut gözetilmezse küçük ürünler görünmez olur ve düzen bozulur.","iliskili":["kh1-4-202","kh1-4-200"],"kontrol":null},{"id":"kh1-4-204","konu":"4.2.3","terim":"Buklet malzemesinde logo görünürlüğü","ingilizce":"Logo placement","tanim":"Malzemelerin üzerinde işletmenin logosu varsa logonun konuğa dönük, görünecek biçimde yerleştirilmesidir.","ornek":"Zeynep, logolu mini şampuanları logo ön tarafta kalacak biçimde standa dizer.","sektor":"Logo işletmenin tanıtımını yapar ve banyoya düzenli bir görünüm kazandırır.","iliskili":["kh1-4-203","kh1-4-205"],"kontrol":null},{"id":"kh1-4-205","konu":"4.2.3","terim":"Kişi sayısına göre banyo malzemesi miktarı","ingilizce":"Quantity by number of guests","tanim":"İki kişilik odayla üç dört kişilik odanın banyosuna konan malzemenin aynı olmamasıdır.","ornek":"Dört kişilik aile odasında lavabonun yanına dört diş seti, iki kişilik odada iki diş seti konur.","sektor":"Az konması konuğu mağdur eder, fazla konması israf olur; bu yüzden miktar odadaki kişiye göre belirlenir.","iliskili":["kh1-4-204","kh1-4-192"],"kontrol":null},{"id":"kh1-4-206","konu":"4.2.3","terim":"Otel bilgi kartlarının yerleştirilmesi","ingilizce":"Placing information cards","tanim":"Çevre ve havlu değişim kartı gibi bilgi kartlarının konuğun görüp okuyabileceği bir yere konmasıdır.","ornek":"Sabah 10.30’da Antalya’daki otelin 410 numaralı odasında Zeynep, çevre ve havlu değişim kartlarını lavabonun yanına dik koyar; konuk banyoya girer girmez görür.","sektor":"Karta ulaşamayan konuk, kartın anlattığı isteği iletemez.","iliskili":["kh1-4-205","kh1-4-207"],"kontrol":null},{"id":"kh1-4-207","konu":"4.2.3","terim":"Kişisel bakım ve kâğıt ürünlerinin yerleştirilmesi","ingilizce":"Placing personal care and paper items","tanim":"Sabun, losyon gibi bakım ürünleri ile kutu mendil gibi kâğıt ürünlerinin işletmenin uygun gördüğü yerlere konmasıdır.","ornek":"Zeynep, kutu mendili lavabo tezgâhının üstüne, losyonu küvet kenarındaki bölmeye koyar; ikisi de işletme standardındaki yerlerdir.","sektor":"Ürünün yeri işletmenin standardına göre belirlenir; görevli bu standart içinde konuğun ihtiyaç duyduğu anda kolay ulaşacağı yeri seçer.","iliskili":["kh1-4-206","kh1-4-208"],"kontrol":null},{"id":"kh1-4-208","konu":"4.2.3","terim":"Eşantiyonların banyoda yerleştirilmesi","ingilizce":"Placing complimentary items in the bathroom","tanim":"Konuğa hediye olarak sunulan malzemelerin kullanım yerleri gözetilerek konmasıdır.","ornek":"Zeynep, hediye sabunu odanın bir köşesine değil, kullanılacağı lavabonun yanına koyar.","sektor":"Malzeme kullanılacağı yerde durmazsa konuk onu fark etmeyebilir.","iliskili":["kh1-4-207","kh1-4-204"],"kontrol":null},{"id":"kh1-4-209","konu":"4.2.3","terim":"Buklet turunda çöp kovasına yeni poşet","ingilizce":"Fitting a new bin liner","tanim":"Banyodaki çöp kovasına temiz bir poşet takılmasıdır.","ornek":"Zeynep, kovanın içindeki torbayı çıkarıp ağzını bağlar ve yeni poşeti takar.","sektor":"Buklet uygulamasında ilk adımlardan biridir; banyonun düzenli ve hazır görünmesini sağlar.","iliskili":["kh1-4-210","kh1-4-212"],"kontrol":null,"gorsel":"t11b-pedalli-cop-kovasi"},{"id":"kh1-4-210","konu":"4.2.3","terim":"Eksik malzemeleri tamamlama","ingilizce":"Topping up missing amenities","tanim":"Banyoda bitmiş ya da az kalmış malzemelerin kat arabasından alınarak yerlerine konmasıdır.","ornek":"Zeynep, banyoda diş setinin bittiğini görür; arabadan alıp yerine koyar.","sektor":"Eksik malzeme konuğun şikâyetine dönüşebileceği için yerleştirmede eksiksizlik aranır.","iliskili":["kh1-4-209","kh1-4-212"],"kontrol":null},{"id":"kh1-4-211","konu":"4.2.3","terim":"Banyoda özel durumlu konuk için ekstra yerleştirme","ingilizce":"Placing extra bathroom amenities for special guests","tanim":"VIP gibi özel durumlu konukların odasında prosedürde belirtilen ek malzemelerin banyoya konmasıdır.","ornek":"VIP konuk odasında Zeynep, standart sete ek olarak prosedürde yazılan ekstra seti banyoya yerleştirir.","sektor":"Prosedürde olmayan malzeme konmaz; yalnız işletme belirlediğinde eklenir.","iliskili":["kh1-4-210","kh1-4-212"],"kontrol":null},{"id":"kh1-4-212","konu":"4.2.3","terim":"Buklet yerleştirme sonrası kontrol","ingilizce":"Post-placement check","tanim":"Malzemelerin yeterli sayıda ve doğru yerlere konup konmadığının işlem bittikten sonra gözden geçirilmesidir.","ornek":"Zeynep banyodan çıkmadan önce sabun, şampuan ve diş setinin hepsinin yerinde olup olmadığına bakar.","sektor":"Kontrolün amacı eksikleri tespit edip zamanında gidermek ve konuk memnuniyetini sağlamaktır.","iliskili":["kh1-4-211","kh1-4-210"],"kontrol":null},{"id":"kh1-4-213","konu":"4.2.4","terim":"Banyo tekstilleri","ingilizce":"Bathroom linen","tanim":"Konuğun kullanımı için el, ayak ve banyo havluları ile bornozdan oluşan tekstil ürünleridir.","ornek":"Sabah 10.00’da Bodrum’daki otelin 302 numaralı odasına giren konuk, banyoda el havlusunu, banyo havlusunu ve bornozu hazır bulur.","sektor":"Banyo tekstilleri konukların kendilerini evlerinde hissetmelerini sağlayan temel ihtiyaçlardandır.","iliskili":["kh1-4-214","kh1-4-216"],"kontrol":null,"gorsel":"t11d-banyo-tekstil"},{"id":"kh1-4-214","konu":"4.2.4","terim":"Havluların banyoya bırakılması","ingilizce":"Towels left in the bathroom","tanim":"Konukların kullanımı için havluların genellikle konuk banyosuna konmasıdır.","ornek":"Sabah 10.45’te Kuşadası’ndaki otelin 118 numaralı odasında Elif, el havlusunu ve banyo havlusunu banyodaki askılığa yerleştirir.","sektor":"Banyoya konmak havluların en yaygın yerleştirme biçimidir.","iliskili":["kh1-4-213","kh1-4-215"],"kontrol":null,"gorsel":"t11c-yuz-havlusu"},{"id":"kh1-4-215","konu":"4.2.4","terim":"Havlu ve bornozun yatağa ya da dolaba konması","ingilizce":"Towels and robes on the bed or in the wardrobe","tanim":"Bazı işletmelerde havlu ve bornozların banyo yerine yatağın üstüne ya da elbise dolabına bırakılmasıdır.","ornek":"Sabah 11.00’de Alanya’daki otelde Elif, işletmenin standardı gereği bornozu yatağın üzerine bırakır; konuk odaya girer girmez görür.","sektor":"Hangi yere konacağı işletmenin standardına bağlıdır.","iliskili":["kh1-4-214","kh1-4-213"],"kontrol":null},{"id":"kh1-4-216","konu":"4.2.4","terim":"Tesise göre havlu çeşidi","ingilizce":"Towel range by property","tanim":"Havlu çeşidinin, tesisin küçüklüğüne ya da büyüklüğüne ve sunduğu hizmetin çeşidine göre değişmesidir.","ornek":"Küçük bir butik otelde yalnız el ve banyo havlusu varken, büyük bir tatil otelinde bornoz ve ayak havlusu da konabilir.","sektor":"Her işletme kendi tesisinin büyüklüğüne ve hizmet çeşidine uygun havlu standardı belirler.","iliskili":["kh1-4-213","kh1-4-217"],"kontrol":null},{"id":"kh1-4-217","konu":"4.2.4","terim":"Kişi sayısı kadar havlu alma","ingilizce":"Taking towels per guest count","tanim":"Odada kalan kişi sayısı kadar havlunun kat arabasından alınıp yerleştirilmesidir.","ornek":"İki kişinin kaldığı odada Elif, kat arabasından iki banyo havlusu alır.","sektor":"Havlu sayısı odadaki kişiye göre belirlenir; eksik havlu konuğun ek istekte bulunmasına yol açar.","iliskili":["kh1-4-216","kh1-4-213"],"kontrol":null},{"id":"kh1-4-218","konu":"4.2.4","terim":"İşletme logolu havlu","ingilizce":"Branded towel","tanim":"Üzerinde işletmenin logosu bulunan havludur.","ornek":"Sabah 11.15’te Marmaris’teki otelin banyosuna giren konuk, havluların üzerine işlenmiş otel logosunu görür.","sektor":"Bazı işletmeler logolu havlu tercih eder; bu durumda havlular tesisin uygun gördüğü yerlere konur.","iliskili":["kh1-4-219","kh1-4-213"],"kontrol":null},{"id":"kh1-4-219","konu":"4.2.4","terim":"Logoyu gösterecek katlama","ingilizce":"Folding to show the logo","tanim":"Havlunun logosu göze hoş görünecek biçimde katlanmasıdır.","ornek":"Elif, banyo havlusunu otelin logosu ön yüzde kalacak şekilde ikiye bölüp katlar.","sektor":"Katladıktan sonra logonun gerçekten görünüp görünmediğinden emin olunur.","iliskili":["kh1-4-218","kh1-4-220"],"kontrol":null},{"id":"kh1-4-220","konu":"4.2.4","terim":"Havlu standı","ingilizce":"Towel stand","tanim":"Havluların düzenli biçimde yerleştirildiği donanımdır.","ornek":"Elif, katlanmış havluları banyodaki standa üst üste dizer.","sektor":"Havlu standı, havlu askılığı ve bornoz askısı havluların yerleştirildiği donanımlardır.","iliskili":["kh1-4-221","kh1-4-222"],"kontrol":null,"gorsel":"t13f-havlu-askisi"},{"id":"kh1-4-221","konu":"4.2.4","terim":"Havlu askılığı","ingilizce":"Towel rack","tanim":"Havluların asılarak yerleştirildiği banyo donanımıdır.","ornek":"Sabah 11.30’da Datça’daki otelin banyosunda Elif, el havlusunu lavabonun yanındaki askılığa asar.","sektor":"Askılık, konuğun havluyu kolay alıp geri asmasını sağlar.","iliskili":["kh1-4-220","kh1-4-222"],"kontrol":null,"gorsel":"t10d-havlupan-radyator"},{"id":"kh1-4-222","konu":"4.2.4","terim":"Bornoz askısı","ingilizce":"Robe hook","tanim":"Bornozun asılarak durduğu askıdır.","ornek":"Elif, bornozu banyonun kapısındaki askıya asar.","sektor":"Bornozu askıda tutmak, konuğun onu kolayca bulmasını sağlar.","iliskili":["kh1-4-221","kh1-4-223"],"kontrol":null,"gorsel":"h5a-bornozlar"},{"id":"kh1-4-223","konu":"4.2.4","terim":"Bornozun yerleştirilmesi","ingilizce":"Placing the bathrobe","tanim":"Konuğun kolayca alabileceği bir yere bornozun özenle bırakılması ya da asılmasıdır.","ornek":"Elif, bornozu askıya asıp ön yüzünü konuğa dönük bırakır.","sektor":"Bornoz bazı işletmelerde banyoda, bazılarında yatak üzerinde ya da elbise dolabında sunulur.","iliskili":["kh1-4-222","kh1-4-224"],"kontrol":null,"gorsel":"t10d-bornoz-dolap"},{"id":"kh1-4-224","konu":"4.2.4","terim":"Bornoz ve havluyu banyoda düzenleme","ingilizce":"Arranging the robe and towel","tanim":"Konuğun ikisini aynı yerde bulması için bornoz ile havlunun yan yana ve uyumlu düzende konmasıdır.","ornek":"Elif, bornozun yanına banyo havlusunu katlayıp koyar; ikisi birlikte düzenli durur.","sektor":"Konuğun bornozu ve havluyu aynı yerde bulması, banyonun düzenli görünmesini sağlar.","iliskili":["kh1-4-223","kh1-4-225"],"kontrol":null,"gorsel":"t10d-bornoz-banyo-otel"},{"id":"kh1-4-225","konu":"4.2.4","terim":"Farklı havlu yerleşim biçimleri","ingilizce":"Towel arrangement styles","tanim":"Havluların banyoda standa, askıya ya da bornozla birlikte farklı düzenlerde konabilmesidir.","ornek":"Bir otelde havlular standa katlanırken, başka bir otelde askılıkta asılıdır.","sektor":"İşletme kendi standardını belirler; görevli o standarda uyar.","iliskili":["kh1-4-224","kh1-4-226"],"kontrol":null,"gorsel":"t15ae-havlu-kugu"},{"id":"kh1-4-226","konu":"4.2.4","terim":"Havlu ve bornoz için ekstra malzeme","ingilizce":"Extra linen for special guests","tanim":"Özel durumu olan konuk için prosedürde varsa ek havlu ya da bornoz konmasıdır.","ornek":"VIP konuğun odasında Elif, standart takıma ek olarak prosedürde yazılan ikinci bornozu da yerleştirir.","sektor":"Ek malzeme yalnız prosedürde öngörülmüşse konur.","iliskili":["kh1-4-225","kh1-4-227"],"kontrol":null},{"id":"kh1-4-227","konu":"4.2.4","terim":"Çevre kartı uygulamasında havlu","ingilizce":"Towel reuse programme","tanim":"Kartla bildirilen tercihe göre, konuk istemediği sürece havlusunun değiştirilmeden yerinde bırakılmasıdır.","ornek":"Odada çevre kartını gören Elif, konuk havlusunu değiştirmek istememişse onu yerinde bırakır.","sektor":"Kart, konuğun tercihini ve işletmenin çevre duyarlılığını birlikte gösterir.","iliskili":["kh1-4-226","kh1-4-228"],"kontrol":null},{"id":"kh1-4-228","konu":"4.2.4","terim":"Havlu yerleştirmeden önce odanın durumunu kontrol etme","ingilizce":"Checking the room before placing linen","tanim":"Havlular yerleştirilmeden önce odada konuk olup olmadığına ve oda durumuna bakılmasıdır.","ornek":"Elif, kapıyı çaldıktan sonra odada konuk olup olmadığına bakar ve ancak ondan sonra havluları yerleştirir.","sektor":"Odadaki duruma bakmak konuğun mahremiyetine saygıdır.","iliskili":["kh1-4-227","kh1-4-226"],"kontrol":null}],"sorular":[{"id":"kh1-4-s001","tur":"coktan-secmeli","soru":"Banyo temizliğine neden ayrıca özen gösterilir?","secenekler":["Konuğun odada en uzun süreyi geçirdiği bölüm olduğu için hızlı kirlenir","Donanımları odanın en pahalı eşyaları olduğu için dikkatle silinir","Nemli ve ıslak olduğu için bakteri, mantar ve kötü koku oluşumuna açıktır","Yalnızca kimyasalla çalışılabilen tek oda bölümü olduğu için yöntemleri sınırlıdır"],"dogru":2,"aciklama":"Su ve buhar bakteri, mantar ve kokunun oluşmasına zemin hazırlar; bu yüzden hijyen ve havalandırma ön plandadır. Donanımın pahalı olması özenin gerekçesi değildir.","konu":"4.1"},{"id":"kh1-4-s002","tur":"dogru-yanlis","soru":"Bide, çoğu işletmede yer darlığı ve az kullanım nedeniyle bulunmaz.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Kullanım alanının az olması ve banyoların yeterince geniş olmaması bidenin çoğu işletmede bulunmama nedenidir.","konu":"4.1"},{"id":"kh1-4-s003","tur":"coktan-secmeli","soru":"Bir odanın banyosunda küvet yerine hidromasaj jetli bir donanım bulunuyor. Bu donanım hangisidir?","secenekler":["Jakuzi","Duş kabini","Bide","Armatür"],"dogru":0,"aciklama":"Hidromasajlı küvet gündelik dilde jakuzi adıyla da anılır; duş kabini ise cam bölmeli, kapalı bir duş alanıdır.","konu":"4.1"},{"id":"kh1-4-s004","tur":"coktan-secmeli","soru":"Hangisi banyoda iş sağlığı ve güvenliği açısından yanlış bir uygulamadır?","secenekler":["Eldiven giyip maske takarak banyoya girmek","Zemindeki kaygan artıkları temizliğe başlamadan önce toplamak","Kimyasalla çalışırken pencereyi açıp banyonun nem ve buharını dışarı atmak","Temizlik ürünlerini daha güçlü olsun diye aynı kovada karıştırmak"],"dogru":3,"aciklama":"Ürünler karıştırılınca zehirli gaz gibi risklere yol açabilir. Diğer üç uygulama banyodaki kayma, enfeksiyon ve zehirlenme risklerini azaltır.","konu":"4.1"},{"id":"kh1-4-s005","tur":"coktan-secmeli","soru":"Eldiven ile maske arasındaki görev farkı hangisidir?","secenekler":["Maske ellerin kimyasalla temasını, eldiven solunum yollarını korur","Eldiven eli enfeksiyondan ve kimyasaldan, maske solunum yollarını korur","İkisi de yalnızca temizlik bezini ve kimyasal kabını kirden koruyan donanımlardır","Eldiven yalnız asidik ürünlerde, maske yalnız hafif ürünlerde gerekir"],"dogru":1,"aciklama":"Eldiven cilt ve enfeksiyon korumasıdır, maske ise solunum yollarını korur; işlevleri birbirine karıştırılmaz.","konu":"4.1"},{"id":"kh1-4-s006","tur":"dogru-yanlis","soru":"Banyo temizliği belli bir sıraya bağlı olmadan, görevlinin istediği sırayla yapılabilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Banyo temizliği doğru araç gereçle ve belli bir sıraya göre yapılır; sıra hijyeni ve çapraz bulaşmanın önlenmesini sağlar.","konu":"4.1"},{"id":"kh1-4-s007","tur":"coktan-secmeli","soru":"Duş kabininin camı çizilmemeli, fayans derzleri ise kararmıştır. Araç gereç seçimi nasıl olmalıdır?","secenekler":["Cam ve derz araları için aynı sert kıllı fırçayı kullanmak","Cam için kazıyıcıyı, derz araları için çekçeği ana araç yapmak","Cam ve derz araları için yalnızca kuru bez kullanmak","Cam için çizmeyen sünger ve çekçek, derz için fırça seçmek"],"dogru":3,"aciklama":"Araç gereç yüzeye ve kire göre seçilir: cam çizilmemeli, derzdeki kir için fırça gerekir. Araç gereci tanımayan görevli emek, zaman ve malzeme kaybına neden olur.","konu":"4.1.1"},{"id":"kh1-4-s008","tur":"coktan-secmeli","soru":"Fayans derzlerindeki birikmiş yağ ve kir süngerle çıkmıyor. Hangisi doğru yaklaşımdır?","secenekler":["Süngeri daha sert bastırarak aynı işlemi tekrarlamak","Uygun fırçayla fırçalayıp ürünün yeterince beklemesini sağlamak","Kimyasalı derzlere doğrudan döküp durulamadan bırakmak","Yüzeyi kuru bezle silip kirin kendiliğinden çözülmesini beklemek"],"dogru":1,"aciklama":"Birikmiş yağ ve kir artıklarında yüzey ve derz araları sünger yerine uygun fırçayla fırçalanır. Kimyasalı doğrudan dökmek ise kuralara aykırıdır.","konu":"4.1.1"},{"id":"kh1-4-s009","tur":"coktan-secmeli","soru":"Otele yeni bir kireç çözücü geldi. Banyoda ilk kullanımda hangisi doğrudur?","secenekler":["Ürünü tüm duvara dökerek etkisini hemen görmek","Ürünü eski ürünle karıştırıp ikisinin etkisini toplamak","Ürünü göze en uzak ve az kullanılan bir köşede denemek","Ürünü etiketsiz küçük bir şişeye aktarıp kolay taşımak"],"dogru":2,"aciklama":"İlk kullanılan kimyasal gizli köşede denenir; yüzeyi lekelerse zarar küçük kalır. Diğer seçenekler kimyasal kullanım kurallarına aykırıdır.","konu":"4.1.1"},{"id":"kh1-4-s010","tur":"coktan-secmeli","soru":"Hangisi kimyasal kullanım kurallarına aykırıdır?","secenekler":["Temizlik ürününü su şişesine boşaltıp kat arabasına koymak","Ürünü kullanım talimatına göre kullanmak","Kullanımdan sonra kapağı sıkıca kapatıp kaldırmak","Ürünü doğrudan dökmek yerine süngere sıkıp yüzeye süngerle sürmek"],"dogru":0,"aciklama":"Temizlik ürünleri etiketsiz bırakılmaz ve kendi özel şişesi dışında bir kaba konmaz; su şişesindeki ürün yanlışlıkla içilebilir.","konu":"4.1.1"},{"id":"kh1-4-s011","tur":"coktan-secmeli","soru":"Göze kimyasal sıçradı. Doğru sıra hangisidir?","secenekler":["Önce doktora gitmek, yolda gözü kuru bezle silmek","Önce bol suyla yıkamak, ardından doktora gitmek","Önce başka bir temizleyiciyle etkisini azaltmaya çalışmak, sonra yıkamak","Önce olayı yazılı olarak kat şefine bildirmek, sonra yıkamak"],"dogru":1,"aciklama":"Zarar sürmesin diye önce bol suyla yıkama yapılır, ardından doktora gidilir. Başka bir kimyasalla müdahale etmek durumu ağırlaştırabilir.","konu":"4.1.1"},{"id":"kh1-4-s012","tur":"dogru-yanlis","soru":"Asidik ürünler kapalı ortamlarda maskesiz kesinlikle kullanılmamalıdır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Asidik ürünlerle çalışırken eldiven giyilir, maske takılır ve banyo havalandırılır.","konu":"4.1.1"},{"id":"kh1-4-s013","tur":"coktan-secmeli","soru":"Banyoda renk kodlu bez kullanmanın başlıca amacı nedir?","secenekler":["Bezlerin daha geç aşınmasını sağlamak","Bezleri depoda saymayı ve istiflemeyi kolaylaştırmak","Kimyasalın etkisini artırmak","Çapraz bulaşmayı önleyerek hijyeni sağlamak"],"dogru":3,"aciklama":"Renkler hangi bezin hangi alanda kullanılacağını gösterir; böylece tuvaletteki mikrop lavabo gibi alanlara taşınmaz.","konu":"4.1.1"},{"id":"kh1-4-s014","tur":"coktan-secmeli","soru":"Banyoda klozet çevresi ve lavabo tezgâhı için bez renkleri hangi eşleşmeyle doğru verilmiştir?","secenekler":["Klozet çevresi kırmızı, lavabo tezgâhı sarı","Klozet çevresi sarı, lavabo tezgâhı kırmızı","Klozet çevresi mavi, lavabo tezgâhı yeşil","Klozet çevresi yeşil, lavabo tezgâhı mavi"],"dogru":0,"aciklama":"Banyoda kırmızı bez tuvalet alanı, sarı bez lavabo ve banyo yüzeyleri için kullanılır; mavi ve yeşil işletmeye göre değişir.","konu":"4.1.1"},{"id":"kh1-4-s015","tur":"coktan-secmeli","soru":"Görevli klozeti sildiği bezle lavabo tezgâhını silerse ne olur?","secenekler":["Tezgâhta kireç birikimi belirgin biçimde hızlanır","Klozetin dezenfeksiyonu için gereken bekleme süresi uzar","Tuvalet alanındaki mikroplar lavabo yüzeyine taşınır","Bezin rengi solar ve başka alanlarda kullanılamaz"],"dogru":2,"aciklama":"Bu hata çapraz bulaşmadır; bezlerin renk kodu tam da bunu önlemek için vardır.","konu":"4.1.1"},{"id":"kh1-4-s016","tur":"coktan-secmeli","soru":"Banyo aynasında su lekesi bırakmadan kurulama için hangi araç ikilisi kullanılır?","secenekler":["Sert kıllı fırça ile yüzey kazıyıcısı birlikte","Faraş ve fırça seti","Mop ve temizlik kovası ile süpürge","Çekçek ve cam peluşu ya da cam bezi"],"dogru":3,"aciklama":"Cam ve ayna yüzeyleri çizmeden temizlenir ve çekçekle fazla suyu alınır; fırça, kazıyıcı ve mop cama uygun değildir.","konu":"4.1.1"},{"id":"kh1-4-s017","tur":"coktan-secmeli","soru":"Lavabo kenarında kuruyup yapışmış diş macunu lekesi var ve sünger çıkaramıyor. Yüzeyi çizmemeye dikkat ederek hangi gereci kullanırsın?","secenekler":["Kazıyıcı","Çekçek","Cam peluşu","Faraş"],"dogru":0,"aciklama":"Yapışıp kuruyan kir, yüzeyin cinsi düşünülerek kazıyıcıyla sökülür. Çekçek fazla suyu alır, cam peluşu cam yüzeyleri siler, faraş ise kuru kiri toplar.","konu":"4.1.1"},{"id":"kh1-4-s018","tur":"dogru-yanlis","soru":"Mop seçiminde yalnızca zemin türü dikkate alınır, banyonun boyutu önemli değildir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Moplar çeşitli boy ve özelliktedir; hem banyonun boyutuna hem zemin türüne göre seçilir. Dar bir banyoda küçük boy mop işi kolaylaştırır.","konu":"4.1.1"},{"id":"kh1-4-s019","tur":"coktan-secmeli","soru":"Görevli temizlik bitince kat arabasını düzenleyip eksikleri kat deposundan tamamlar. Bunun nedeni nedir?","secenekler":["Kat arabasının envanterinin gün sonunda muhasebeye teslim edilmesi","Sonraki temizliğe eksiksiz ve hızlı başlanabilmesi","Kimyasalların son kullanma tarihlerinin dolmaması","Banyo malzemelerinin ikinci kez sayılmaya gerek kalmaması"],"dogru":1,"aciklama":"Düzenli kat arabası ertesi gün işe hızlı başlamayı sağlar ve eksik malzeme yüzünden temizliğin aksamasını önler.","konu":"4.1.1"},{"id":"kh1-4-s020","tur":"coktan-secmeli","soru":"Kimyasal kullanım eğitimi neden işletmenin belirlediği ilgili firma yetkililerince verilir?","secenekler":["Kimyasalların fiyatını belirleme yetkisinin firmada olması","Her kimyasalın her yüzeyde aynı sonucu vermesi","Her firmanın yüzey ve kir çeşitliliğine göre ürünü olması","Kat şeflerinin kimyasal kullanımını denetleme yetkisinin bulunmaması"],"dogru":2,"aciklama":"Ürünün yüzey ve kir çeşitliliğine göre en yüksek verimle nasıl kullanılacağını üreten firma bilir; eğitim bunu personele aktarır.","konu":"4.1.1"},{"id":"kh1-4-s021","tur":"coktan-secmeli","soru":"Banyodan çöp toplarken ilk yapılması gereken hangisidir?","secenekler":["Eldiven giymek ve maske takmak","Kirli tekstili kat arabasına koymak","Çöp torbasının ağzını sıkıca bağlamak","Zemini paspaslamak"],"dogru":0,"aciklama":"Kişisel koruyucu donanım temizliğe başlamadan önce takılır; sonraki adımlar bunun ardından gelir.","konu":"4.1.2"},{"id":"kh1-4-s022","tur":"coktan-secmeli","soru":"Zemindeki sabun ve şampuan artıkları neden temizliğe başlamadan toplanır?","secenekler":["Çekçeğin lastiğini kısa sürede bozup yıprattıkları için","Klozetin dezenfeksiyonunu engelledikleri için","Kimyasalın renginin ve kokusunun değişmesine, etkisinin azalmasına neden oldukları için","Kaymaya yol açıp iş sağlığı ve güvenliğini tehlikeye attıkları için"],"dogru":3,"aciklama":"Banyo kayma riskinin yüksek olduğu bir alandır; kaygan artıklar önce alınır ki görevli ve konuk düşmesin.","konu":"4.1.2"},{"id":"kh1-4-s023","tur":"coktan-secmeli","soru":"Kirli havlu ve bornozlar toplanırken ayrıca ne yapılmalıdır?","secenekler":["Kirli tekstil temiz tekstille aynı torbaya konmalıdır","Cepler kontrol edilmeden yıkamaya gönderilmelidir","İçleri ve cepleri kontrol edilip konuğa ait eşya aranmalıdır","Etiketleri sökülüp ayrı bir torbada saklanmalı ve işleme alınmalıdır"],"dogru":2,"aciklama":"Cepte unutulmuş eşya yıkamada kaybolabilir. Kirli tekstil temiz tekstille karıştırılmaz.","konu":"4.1.2"},{"id":"kh1-4-s024","tur":"coktan-secmeli","soru":"Duş giderinde saç birikmiş ve su akmıyor. Doğru yaklaşım hangisidir?","secenekler":["Gidere kimyasal döküp kendiliğinden açılmasını beklemek","Eldiven ve maske takıp gideri açmak","Zemini silip gideri bırakmak","Gideri bezle kapatıp diğer yüzeylere geçmek"],"dogru":1,"aciklama":"Tıkalı gider açılmalıdır; bu sırada enfeksiyon riskine karşı eldiven ve maske takılır.","konu":"4.1.2"},{"id":"kh1-4-s025","tur":"dogru-yanlis","soru":"Banyo çöp torbası taşındıktan sonra kovaya yeni poşet takılmasına gerek yoktur.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Torbanın ağzı bağlanıp taşındıktan sonra kovaya yeni poşet takılır; kova boş bırakılmaz.","konu":"4.1.2"},{"id":"kh1-4-s026","tur":"coktan-secmeli","soru":"Çıkış yapılmış odada banyoda kırık bir bardak ve çatlamış bir sabunluk bulundu. Hangi form doldurulur?","secenekler":["Yalnızca kayıp bulunmuş eşya formu","Yalnızca oda durum raporuna not düşülür","Yalnızca konuk şikâyet formu doldurulur","Arıza tespit formu ve eşya hasar formu"],"dogru":3,"aciklama":"Zarar gören donanım için arıza tespit formu ve eşya hasar formu birlikte doldurulur; kayıp bulunmuş eşya formu konuğa ait unutulan eşya içindir.","konu":"4.1.3"},{"id":"kh1-4-s027","tur":"coktan-secmeli","soru":"Küçük bir banyo arızası neden bildirilmeden bırakılmamalıdır?","secenekler":["Memnuniyetsizliğe ya da can güvenliğinin tehlikeye girmesine yol açabilir","Teknik servisin iş yükünü azaltmak ve yazışmaları kısaltmak gerektiği için","Yalnızca zeminin ıslak kalmasına neden olacağı için","Kat şefinin imza yetkisini ve işletme yetki sırasını geçersiz kılacağı için"],"dogru":0,"aciklama":"Küçük bir arıza büyük bir şikâyete ya da kazaya dönüşebilir; bu yüzden görevli bildirmeyi sonraya bırakmaz.","konu":"4.1.3"},{"id":"kh1-4-s028","tur":"coktan-secmeli","soru":"Banyoda unutulmuş bir şarj aleti buldun ve konuk hâlâ işletmede. İlk adımın ne olur?","secenekler":["Eşyayı kat arabasında saklayıp vardiya sonunda kat şefine vermek","Eşyayı oda durum raporuna not edip konuğun gelmesini beklemek","Hemen ön büroyu arayıp konuğun hâlâ işletmede olduğunu bildirmek","Eşyayı lavabo kenarında bırakıp temizliğe devam etmek"],"dogru":2,"aciklama":"Konuk işletmedeyse ön büroya hemen haber verilir ki eşya ona ulaştırılsın. Konuk ayrılmışsa kayıp bulunmuş eşya formu doldurulur.","konu":"4.1.3"},{"id":"kh1-4-s029","tur":"coktan-secmeli","soru":"Check-out yapılan odalara konuk işletmeden ayrılmadan önce gidilmesinin nedeni nedir?","secenekler":["Konuğun hasar bedelini yerinde tahsil etmek","Unutulan eşya varsa konuğa hemen ulaştırılabilmesi","Pas anahtarını konuktan imza karşılığı teslim almak","Oda durum raporunu konukla birlikte doldurmak"],"dogru":1,"aciklama":"Oda durum raporunda check-out odaları bellidir; erken gidilirse unutulan eşya konuk hâlâ işletmedeyken bulunur.","konu":"4.1.3"},{"id":"kh1-4-s030","tur":"dogru-yanlis","soru":"Dolu odada banyo arıza kontrolü, temizliğe başladıktan sonra yapılır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Dolu odada banyo arıza ve donanım kontrolü temizliğe başlamadan önce yapılır; arıza temizlikten önce kayda geçer.","konu":"4.1.3"},{"id":"kh1-4-s031","tur":"coktan-secmeli","soru":"Teknik servis lavabo sızıntısını onardı. Görevlinin yapacağı son adım hangisidir?","secenekler":["Banyoyu kontrol edip formu kendi nüshasıyla dosyalamak","Formu teknik servise geri verip dosyalama işini onlara bırakmak","Formu konuğa teslim edip arızanın giderildiğini bildirmek","Banyoyu kontrol etmeden odayı hazır ilan etmek"],"dogru":0,"aciklama":"Giderilen arıza yerinde kontrol edilir ve teknik servisin geri verdiği form kendi nüshasıyla birlikte dosyalanır.","konu":"4.1.3"},{"id":"kh1-4-s032","tur":"coktan-secmeli","soru":"Vardiyan bitti, bildirdiğin bir banyo arızası hâlâ giderilmedi. Ne yaparsın?","secenekler":["Arıza formunu iptal edip yeni bir form açarak süreci baştan başlatırsın","Konuğa arızanın giderildiğini söyleyip dosyayı kapatırsın","Arızalı banyoyu rapora yazmadan bırakırsın","Sonuçlanmayan arızayı sonraki vardiya görevlilerine bildirirsin"],"dogru":3,"aciklama":"Vardiya sonunda sonuçlanmamış arızalar bir sonraki vardiyaya bildirilir; arızalı oda oda durum raporunda gösterilir.","konu":"4.1.3"},{"id":"kh1-4-s033","tur":"coktan-secmeli","soru":"Saç kurutma makinesinin temizliğinde, silme işleminden önce güvenlik açısından ilk kontrol hangisidir?","secenekler":["Makinenin yüzeyinde leke ya da kir olup olmadığına bakmak","Elektrik bağlantısının kapalı olduğundan emin olmak","Makinenin parçalarını tek tek sökerek içini temizlemek","Kablosunu önceden nemli bezle ıslatarak yumuşatmak"],"dogru":1,"aciklama":"Elektrikli aletlerin temizliğine başlamadan önce bağlantının kapalı olduğu kontrol edilir; sonra nemli bezle silinir.","konu":"4.1.4"},{"id":"kh1-4-s034","tur":"coktan-secmeli","soru":"Banyoda elektrik düğmesi ve priz temizliğiyle ilgili hangisi yanlıştır?","secenekler":["Hafif nemli bezle silip kurulamak","Yoğun kirde elektrik bağlantısını kesmek","Yoğun lekede bağlantıyı kesmeden bol suyla yıkamak","Silme sonrasında yüzeyi iyice kurulayıp kuru bırakmak"],"dogru":2,"aciklama":"Banyo elektrik akımının bulunduğu bir alandır; yoğun kirde bağlantı kesilir. Bol su düğme ve prizler için tehlikelidir.","konu":"4.1.4"},{"id":"kh1-4-s035","tur":"coktan-secmeli","soru":"Makyaj aynasının çerçevesi pirinç kaplı. Hangisi doğru yaklaşımdır?","secenekler":["Çerçeveyi uygun ürünle, camı da cam sille temizlemek","Çerçeveyi ve camı aynı kimyasalla birlikte silmek","Çerçeveyi aşındırıcı ovma maddesiyle kuvvetle ovmak","Camı temizleyip çerçeveye ve diğer kısımlara hiç dokunmamak"],"dogru":0,"aciklama":"Çerçeve ve cam ayrı ürünlerle temizlenir; çerçevenin malzemesine uygun temizleyici kullanılır ve talimata uyulur.","konu":"4.1.4"},{"id":"kh1-4-s036","tur":"coktan-secmeli","soru":"Temizlik sırasında bulunan kırık cam parçaları neden eldivenle ve kurala uygun toplanır?","secenekler":["Geri dönüşüme ayrı gönderilmeleri gerektiği için","Keskin kenarları yaralanma riski taşıdığı için","Konuğun tazminat talebine karşı kanıt oluşturmak için","Kat arabasında daha az yer kaplamaları için"],"dogru":1,"aciklama":"Kırık cam ve ayna parçaları keskindir ve yaralanma riski taşır; bu yüzden kurala uygun toplanıp uygun çöp kutusuna konur.","konu":"4.1.4"},{"id":"kh1-4-s037","tur":"coktan-secmeli","soru":"Banyoda temizlikte kullanılacak kimyasalı ne belirler?","secenekler":["Kat şefinin kişisel tercihi ve alışkanlığı","Odanın bulunduğu katın numarası","Banyoda pencere olup olmadığı","Banyodaki donanımın cinsi ve malzemesi"],"dogru":3,"aciklama":"Donanımın malzemesi hangi ürünün güvenle kullanılacağını belirler; ürün talimatına göre uygulanır.","konu":"4.1.4"},{"id":"kh1-4-s038","tur":"coktan-secmeli","soru":"Çöp kovası ve kül tablası neden klozet dezenfekte olurken yıkanır?","secenekler":["Kimyasal onlara bulaşmasın diye","Aynı fırçayla temizlendikleri için","Bekleme süresi boşa geçmesin diye","Kül tablası klozetin parçası olduğu için"],"dogru":2,"aciklama":"Kimyasalın etki süresi beklenirken başka bir işi yapmak zaman kazandırır.","konu":"4.1.4"},{"id":"kh1-4-s039","tur":"dogru-yanlis","soru":"Banyoda genellikle alarm butonu, telefon ve yangın ya da ilk yardım alarm cihazı gibi donanımlar bulunabilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Bunlar banyoda genellikle bulunan donanımlar arasında sayılır; temizlik sırasında yerinde ve sağlam olup olmadıklarına da bakılır.","konu":"4.1.4"},{"id":"kh1-4-s040","tur":"coktan-secmeli","soru":"Banyo temizliği kullanılan malzemeye göre hangi üç yüzey grubuna ayrılır?","secenekler":["Fayans, ahşap ve cam yüzeyler","Metal, plastik ve cam","Fayans, metal ve tekstil yüzeyler","Fayans, cam ve metal yüzeyler"],"dogru":3,"aciklama":"Banyo temizliği fayans, cam ve metal yüzeylerin temizliği olarak ayrılır; ahşap ve tekstil bu sınıflamada yoktur.","konu":"4.1.5"},{"id":"kh1-4-s041","tur":"coktan-secmeli","soru":"Küvet temizliğinde hangi sıra doğrudur?","secenekler":["Yüzeyi kuru bırakıp kimyasal sürmek, hemen durulamak, giderdeki kiri en sona bırakmak","Kimyasalı sürüp durulamak, giderdeki kiri almak, sonra yüzeyi ıslatmak","Gider kirini almak, yüzeyi ıslatmak, kimyasalla ovmak, beklemek, durulayıp kurulamak","Yüzeyi ıslatıp durulamak, kimyasalı sürüp kurulamak, kiri en sonda almak"],"dogru":2,"aciklama":"Önce gider temizlenir, yüzey ıslatılıp kimyasalla ovulur; ürün beklenip durulanır ve kurulanır. Kiri sona bırakmak temizliği eksik kılar.","konu":"4.1.5"},{"id":"kh1-4-s042","tur":"coktan-secmeli","soru":"Klozetin iç kısmına temizleyiciyi nasıl uygular, fırçayı nereye bırakırsın?","secenekler":["Tek noktaya yoğun dökerim, fırçayı kenarda kuru tutarım","Daire çizerek sıkar, fırçayı klozetin ortasına bırakırım","Kapak kapalıyken kapağın üstüne sıkarım, fırçayı kovaya koyarım","Rezervuarı çekmeden duvarlara sıkarım, fırçayı bırakmam"],"dogru":1,"aciklama":"Temizleyici daire çizilerek sıkılır ve fırça klozetin ortasında bırakılır; böylece ürün dezenfekte olurken fırçalamaya hazır olunur.","konu":"4.1.5"},{"id":"kh1-4-s043","tur":"coktan-secmeli","soru":"Klozet temizliği bittikten sonra eldivenlerin değiştirilmesinin nedeni nedir?","secenekler":["Mikropların ayna ve lavabo gibi yüzeylere taşınmasını önlemek","Eldivenin kimyasal etkisini yenilemek ve dayanıklılığını artırmak","Eldivenin ıslanıp kaymasını önleyerek işi hızlandırmak","Aynayı daha parlak hâle getirmek"],"dogru":0,"aciklama":"Tuvalet bölgesindeki mikroplar eldivenle diğer yüzeylere bulaşabilir; değiştirmek çapraz bulaşmayı önler.","konu":"4.1.5"},{"id":"kh1-4-s044","tur":"coktan-secmeli","soru":"Klozet çevresi ve kapaklarının silinmesiyle ilgili hangisi yanlıştır?","secenekler":["İçten dışa doğru, rastgele bir bezle silmek","Dıştan içe doğru silmek ve kurulamak","Uygun renkteki bezi seçip kullanmak ve silmek","Silinen yüzeyi iyice kurulayarak bitirmek"],"dogru":0,"aciklama":"Çevre ve kapaklar uygun renkteki bezle dıştan içe doğru silinir ve kurulanır.","konu":"4.1.5"},{"id":"kh1-4-s045","tur":"dogru-yanlis","soru":"Duvar temizliğinde kimyasal sürüldükten hemen sonra, beklenmeden durulanır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kimyasal, kullanma talimatında belirtildiği kadar beklenir; sonra duvar durulanıp kurulanır.","konu":"4.1.5"},{"id":"kh1-4-s046","tur":"coktan-secmeli","soru":"Duş kabininin sürgülü rayında kir birikmiş. Hangi yöntem doğrudur?","secenekler":["Rayı kuru bezle silip bırakmak ve temizliğe kaldığı yerden devam etmek","Kimyasalı rayın içine doğrudan dökmek ve kendi hâline bırakmak","Spreyle temizleyici sıkıp duş fıskiyesiyle durulamak, sonra kurulamak","Rayı kazıyıcıyla kazıyıp durulamadan ve kurulamadan bırakmak"],"dogru":2,"aciklama":"Sürgülü kısımlara sprey temizlik malzemesi sıkılır, duş fıskiyesiyle durulanır ve kurulanır.","konu":"4.1.5"},{"id":"kh1-4-s047","tur":"coktan-secmeli","soru":"Duş kabininin camı ve ayna çekçekle neden kurutulur?","secenekler":["Cam yüzeyi çizerek parlatmak için","Fazla suyu alıp lekesiz, hızlı kurulama sağlamak için","Kimyasalın etkisini kalıcı hâle getirmek ve süreyi uzatmak için","Bezlerin yıpranmasını azaltmak için"],"dogru":1,"aciklama":"Çekçek fazla suyu alır; su lekesi kalmaz ve kurulama kısalır.","konu":"4.1.1"},{"id":"kh1-4-s048","tur":"coktan-secmeli","soru":"Bazı konaklama tesislerinde banyo camları kim tarafından temizlenir?","secenekler":["Teknik servis personeli","Çamaşırhane çalışanları","Ön büro görevlileri","Cam görevlileri ekibi"],"dogru":3,"aciklama":"Cam yüzey geniş alan kapladığı için bazı tesislerde bu iş cam görevlilerine bırakılır; oda görevlisi banyonun geri kalanını temizler.","konu":"4.1.5"},{"id":"kh1-4-s049","tur":"coktan-secmeli","soru":"Duş başlığını kireçlenmeye karşı temizlerken hangi yöntem doğrudur?","secenekler":["Başlığı kuru bırakıp yalnız ayna bezi ile silmek","Kimyasalı renk kodlu süngerle ovup mikrofiber bezle kurulamak","Kimyasalı başlığa döküp durulamadan yerine takmak","Başlığı yerinden sökmeden yalnız kâğıt havluyla hafifçe silip geçmek"],"dogru":1,"aciklama":"Başlık renk koduna uygun süngerle ovulur, mikrofiber bezle kurulanır ve leke kalmadığından emin olunduktan sonra yerine takılır.","konu":"4.1.5"},{"id":"kh1-4-s050","tur":"coktan-secmeli","soru":"Hangisi banyoda metal yüzey grubunda temizlenir?","secenekler":["Armatürler ve askılar","Duvardaki fayans yüzeyler","Aynanın cam kısmı","Duş kabininin cam kapısı"],"dogru":0,"aciklama":"Metal yüzeyler arasında armatür, askı ve duş başlığı yer alır; fayans, ayna ve duş kabini farklı yüzey gruplarındadır.","konu":"4.1.5"},{"id":"kh1-4-s051","tur":"coktan-secmeli","soru":"Metal yüzeyler temizlendikten sonra neden iyice kurulanır?","secenekler":["Kireç çözücünün etkisini artırdığı için","Sürgülü rayların takılmasını önlediği için","Çekçeğin lastiğini ve bezlerin ömrünü koruduğu için","Nem kalırsa leke bırakıp paslanabildikleri için"],"dogru":3,"aciklama":"Metal yüzeyler nem kaldığında lekelenir ve paslanabilir; bu yüzden yeterince kurulandığından emin olunur.","konu":"4.1.5"},{"id":"kh1-4-s052","tur":"coktan-secmeli","soru":"Rezervuar kontrol paneli temizliğiyle ilgili hangisi yanlıştır?","secenekler":["Panelde yüzeye uygun kimyasal kullanmak ve beklemek","Renk koduna uygun nemli bezle silmek","Üzerinde leke kalsa da temizliği tamam saymak","Silip kurulandığından emin olmak"],"dogru":2,"aciklama":"Panel hijyenik olması gereken bir yüzeydir; temizlik sonrası leke kalmadığından emin olunur.","konu":"4.1.5"},{"id":"kh1-4-s053","tur":"dogru-yanlis","soru":"Banyo askıları temizlendikten sonra kurutulmadan nemli bırakılabilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Askılar uygun temizlik bezi ve kimyasalıyla silinir ve kurutulur; nemli kalan metal paslanabilir.","konu":"4.1.5"},{"id":"kh1-4-s054","tur":"coktan-secmeli","soru":"Hangisi banyoda kullanılan armatür çeşitlerindendir?","secenekler":["Duvar, zemin ve tavan armatürü","Klozet, askı ve çekçek armatürü","Ayna, cam ve sürgü armatürü","Lavabo, banyo ve bide armatürü"],"dogru":3,"aciklama":"Armatürler lavabo, banyo ve bide armatürü olarak adlandırılır.","konu":"4.1.5"},{"id":"kh1-4-s055","tur":"coktan-secmeli","soru":"Banyodaki alarm butonu ne işe yarar?","secenekler":["Duş suyunun sıcaklığını ve akış gücünü otomatik ayarlar","Acil durumda konuğun yardım çağırmasını sağlar","Odanın temizlendiğini kat şefine bildirir","Havalandırmayı otomatik olarak çalıştırır"],"dogru":1,"aciklama":"Alarm butonu acil durumda yardım çağırmak içindir; bu yüzden yerinde ve sağlam olup olmadığı kontrol edilir.","konu":"4.1.4"},{"id":"kh1-4-s056","tur":"dogru-yanlis","soru":"Banyoda hasar ya da kayıp eşya bulunduğunda yalnızca kat şefine haber vermek yeterlidir; resepsiyona bildirmek gerekmez.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kayıp veya hasar kat şefine ve resepsiyona bildirilerek takibi sağlanır.","konu":"4.1.3"},{"id":"kh1-4-s057","tur":"dogru-yanlis","soru":"Lejyoner hastalığı nadir görülen ama ciddi bir akciğer enfeksiyonudur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Hastalığa Legionella bakterisi neden olur; bakteri sistemlerden solunum yoluyla bulaştığı için konaklama tesislerinde takip yapılır.","konu":"4.1.5"},{"id":"kh1-4-s058","tur":"coktan-secmeli","soru":"Boş odalarda neden düzenli olarak sıcak ve soğuk su akıtılır?","secenekler":["Durgun suda legionella riskini azaltmaya yardımcı olmak için","Musluk contalarının kurumasını ve çatlamasını önlemek ve kokuyu gidermek için","Su sayacındaki değeri güncel tutmak için","Yatak takımlarının nem almasını sağlamak için"],"dogru":0,"aciklama":"Kullanılmayan odalarda su beklerse bakteri riski artar; düzenli akıtma bu riski azaltır.","konu":"4.1.5"},{"id":"kh1-4-s059","tur":"coktan-secmeli","soru":"Üç gündür boş olan 318 numaralı odada legionella takibi için ne yaparsın?","secenekler":["Odanın kapısını kilitleyip odayı satış listesinden çıkarıp geçerim","Yalnızca klozetin sifonunu bir kez çekerim","Küvet ve lavabo armatürlerinden sıcak ve soğuk su akıtırım","Yatağı havalandırıp perdeleri açık bırakırım"],"dogru":2,"aciklama":"Boş odaların küvet ve lavabo armatürleri açılarak su akıtılır; sonuç işaretlenip kat şefi tarafından imzalanır.","konu":"4.1.5"},{"id":"kh1-4-s060","tur":"coktan-secmeli","soru":"Legionella takibinde su akıtılan odalarla ilgili hangi kayıt tutulur?","secenekler":["Odalarda konaklayan konukların isim listesi","Kullanılan kimyasalların sipariş ve stok formu","Odaların işaretlenip kat şefince imzalanarak dosyalanması","Çıkış yapan konukların doldurduğu memnuniyet anketi cevapları"],"dogru":2,"aciklama":"İşaretli ve imzalı liste il halk sağlığı denetimlerinde gösterilmek üzere dosyalanır.","konu":"4.1.5"},{"id":"kh1-4-s061","tur":"coktan-secmeli","soru":"Su akıtma süresini belirlerken teknik servis talimatı neden esas alınır?","secenekler":["Teknik servis su faturasını ve su sayacını yönettiği için","Süre odanın boş kalma süresine göre değişebildiği için","Süre her odada sabit tutulduğu için","Su akıtmayı yalnız teknik servis yapabildiği için"],"dogru":1,"aciklama":"Boş kalma süresi uzadıkça ihtiyaç değişir; bunu belirlemek teknik servis bölümünün işidir.","konu":"4.1.5"},{"id":"kh1-4-s062","tur":"dogru-yanlis","soru":"Örnek standartta duş başlıkları ve musluk başı süzgeçleri kireç çözücüyle temizlenir, dezenfektan sıvısıyla dezenfekte edilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Kireç giderme ve dezenfeksiyon uygulaması örnek standartta düzenli olarak yapılır ve temizlik sırasında eldiven kullanılır.","konu":"4.1.5"},{"id":"kh1-4-s063","tur":"coktan-secmeli","soru":"Lejyoner hastalığının solunum yoluyla bulaştığı sistemler hangileridir?","secenekler":["Çamaşır makinesi, ütü ve kurutma sistemleri","Asansör ve merdiven aydınlatması","Kat arabası, çöp kovası ve diğer temizlik malzemeleri","Klima, jakuzili havuz ve havalandırma sistemleri"],"dogru":3,"aciklama":"Bakteri su ve hava sistemlerinden solunumla bulaşır; kat arabası ve çöp kovası bulaş kaynağı sayılmaz.","konu":"4.1.5"},{"id":"kh1-4-s064","tur":"dogru-yanlis","soru":"Lejyoner hastalığı, ilk kez Amerikan lejyonerlerinin katıldığı bir toplantıda salgın hâlinde görüldüğü için bu adı almıştır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Hastalığın adı, 1976’daki ilk salgının görüldüğü toplantıya katılan Amerikan lejyonerlerinden gelir.","konu":"4.1.5"},{"id":"kh1-4-s065","tur":"coktan-secmeli","soru":"Buharlı temizliğin başlıca avantajı hangisidir?","secenekler":["Az kimyasalla inatçı kir, leke, kireç ve bakteriye karşı etkili olması","Hiç su kullanılmadan çalışabilmesi","Zeminde kurulama ihtiyacını tamamen ortadan kaldırması","Elektrik bağlantısı olmadan kullanılabilmesi ve her yere taşınabilir olması"],"dogru":0,"aciklama":"Buharlı makine daha az kimyasalla inatçı kire karşı etkili olduğu için VIP odalarda ve periyodik temizlikte tercih edilir. Elektrik ve su ise gerekir.","konu":"4.1.5"},{"id":"kh1-4-s066","tur":"coktan-secmeli","soru":"Buharlı makinenin hazırlanmasında hangisi yanlıştır?","secenekler":["Depoyu işaretli alana kadar doldurmak","Makinenin fişini prize takıp ısındığını gösteren uyarı ışığını beklemek","Depoyu işaretli alanın üstüne taşacak kadar doldurmak","Yüzeye uygun aparatı makineye takmak"],"dogru":2,"aciklama":"Depo işaretli alana kadar doldurulur; fazlası güvensizdir. Fişi prize takma, ısınma ışığı ve uygun aparat hazırlık adımlarıdır.","konu":"4.1.5"},{"id":"kh1-4-s067","tur":"coktan-secmeli","soru":"Buharlı makinenin kullanım sonrası bakımıyla ilgili hangisi yanlıştır?","secenekler":["Güvenlik tedbirleri alınarak fişi çekmek","Deposundaki suyu boşaltmadan parçaları kaldırmak","Aparatları çıkarıp temizlemek ve kurulamak","Parçaları kullanım talimatına uygun biçimde depolamak"],"dogru":1,"aciklama":"Fiş çekilir, aparatlar temizlenir, depodaki su boşaltılır ve parçalar talimata uygun depolanır.","konu":"4.1.5"},{"id":"kh1-4-s068","tur":"coktan-secmeli","soru":"Buharlı temizlikte çalışma sırası hangisidir?","secenekler":["Aşağıdan yukarıya ve kapıya en yakın noktadan uzağa","Rastgele, kirli görünen yerden başlayarak ilerleyerek","Önce zeminden başlayıp duvarlara, sonra tavana doğru çıkarak ilerlemek","Yukarıdan aşağıya ve kapıya en uzak noktadan kapıya doğru"],"dogru":3,"aciklama":"Temizlik yukarıdan aşağıya ve kapıya en uzak noktadan kapıya doğru yapılır; böylece temizlenen alana basılmaz.","konu":"4.1.5"},{"id":"kh1-4-s069","tur":"coktan-secmeli","soru":"Zemin temizliği neden banyo temizliğinin en sonunda yapılır?","secenekler":["Üstteki yüzeylerden damlayan su ve kir zemine kaldığı için","Zemin kimyasalı en geç kuruyan ve en pahalı sarf malzemesi olduğu için","Mopların temizliği çok uzun sürdüğü için","Kat şefi zemini her zaman en son denetlediği için"],"dogru":0,"aciklama":"Yüzeyler önce temizlenir ve zemin son adımda temizlenir; böylece zemin tekrar kirlenmez.","konu":"4.1.5"},{"id":"kh1-4-s070","tur":"coktan-secmeli","soru":"Banyo zemininde toka ve toplu iğne buldun. Zemin temizliğinden önce ne yaparsın?","secenekler":["Mopla birlikte tokayı da süpürerek geçerim","Araç gerece zarar vermemesi için toplarım","Gideri açıp içine atarım","Bırakıp zemini kurulamaya geçerim"],"dogru":1,"aciklama":"Toplu iğne, çivi, toka gibi nesneler araç gerece zarar verebilir; zemin temizliğinden önce toplanır.","konu":"4.1.5"},{"id":"kh1-4-s071","tur":"coktan-secmeli","soru":"Banyo zemini temizliğiyle ilgili hangisi yanlıştır?","secenekler":["Zemin cinsine uygun araç gereçle temizlik yapmak ve kontrol etmek","Çıkışa en uzak yerden başlamak","Kapıya yakın yerden başlayıp en uzak noktaya ilerlemek","Giderin atıktan arındığından emin olmak"],"dogru":2,"aciklama":"Zemin temizliğine çıkışa en uzak yerden başlanır; böylece temizlenen alana basılmadan çıkılır.","konu":"4.1.5"},{"id":"kh1-4-s072","tur":"dogru-yanlis","soru":"Zemin temizliği sırasında giderin her türlü atıktan arındırılmış olduğundan emin olunur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Tıkalı gider suyun akışını engeller; zemin temizliğinde giderin açık olması kontrol edilir.","konu":"4.1.5"},{"id":"kh1-4-s073","tur":"coktan-secmeli","soru":"Banyoda su tasarrufu için hangi uygulama doğrudur?","secenekler":["Sızdıran musluğu arıza formuyla bildirip onarılmasını sağlamak","Temizlikte musluğu sürekli açık tutup durulama yapmak","Zemini kova yerine hortumla yıkamak","Küçük damlatmaları temizliğe zarar vermediği için görmezden gelmek"],"dogru":0,"aciklama":"Sızdıran muslukları onartmak, musluğu açık bırakmamak ve kova ile temizlik yapmak su tasarrufu yöntemleridir; küçük sızıntılar zamanla büyük su kaybına dönüşür.","konu":"4.1.5"},{"id":"kh1-4-s074","tur":"coktan-secmeli","soru":"Su kaynaklarının korunması neden önemlidir?","secenekler":["Tatlı su bol olduğu için israf edilmesi de sorun değildir","Su kaynakları yalnızca sanayide kullanıldığı için önemlidir","Yağmur suları hiçbir şekilde depolanamadığı ve kullanılamadığı için tasarruf gerekir","Tatlı su dünyadaki suyun küçük bir kısmıdır ve büyük bölümüne ulaşmak güçtür"],"dogru":3,"aciklama":"Tatlı su sınırlıdır ve önemli kısmı buzul ve buz tabakaları altındadır; bu yüzden korunması ve tasarruf gerekir.","konu":"4.1.5"},{"id":"kh1-4-s075","tur":"dogru-yanlis","soru":"Hidromasajlı küvet gibi sıcak ve nemli su sistemleri legionella takibinin konusudur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Klima, jakuzili havuz ve havalandırma gibi sistemlerden solunum yoluyla bulaşma riski vardır; bu yüzden takip yapılır.","konu":"4.1.5"},{"id":"kh1-4-s076","tur":"coktan-secmeli","soru":"Hijyene önem verilen bir banyoda hangi sonuç beklenir?","secenekler":["Kimyasal kullanımı ve hijyen kuralları tamamen gereksizleşir","Havalandırma yapılmasına hiç gerek kalmaz","Personel ve konuk için tehlikeli sonuç ihtimali azalır","Arıza kontrolüne ayrıca hiç gerek kalmaz"],"dogru":2,"aciklama":"Hijyen, bakteri ve mantar kaynaklı riskleri azaltır; ama havalandırma ve arıza kontrolü gibi diğer adımların yerini tutmaz.","konu":"4.1"},{"id":"kh1-4-s077","tur":"coktan-secmeli","soru":"Görevli temizliğe başlamadan önce neden kullanılacak malzemeyi ve yöntemi belirler?","secenekler":["Malzemeyi konuğa göstermek gerektiği için","Yöntem, madde ve gereçlerin özelliklerine bağlı olduğu için","Yöntem her odada aynı kaldığı ve değişmediği için","Kat şefi malzemeyi odada tek tek kontrol edip onayladığı için"],"dogru":1,"aciklama":"Temizlik yöntemi madde ve gereçlerin özelliklerine göre belirlenir; bilmeden seçilen yöntem yüzeye zarar verebilir.","konu":"4.1.1"},{"id":"kh1-4-s078","tur":"senaryo","durum":"Sabah 09.15. Oda durum raporuna göre 412 numaralı oda check-out olmuş. Banyoda lavabo kenarında bir tıraş makinesi ve çocuk diş fırçası unutulmuş görünüyor. Konuk resepsiyonda hesabını kapatıyor.","soru":"Ne yaparsın?","secenekler":["Hemen ön büroyu arayıp unutulan eşyaları bildirirsin","Eşyaları kat arabasına koyup temizliğe devam edersin","Eşyaları çöp torbasına koyup banyoyu bitirirsin","Eşyaları komodine bırakıp odanın kapısını kilitlersin"],"dogru":0,"aciklama":"Konuk hâlâ işletmedeyken ön büroya haber verilirse eşya ona ulaştırılabilir. Eşyayı saklamak ya da atmak konuğun eşyasını kaybettirir.","konu":"4.1.3"},{"id":"kh1-4-s079","tur":"senaryo","durum":"Öğleden sonra 14.00. 305 numaralı odanın banyosunda duş zemininde şampuan köpüğü var ve lavabonun altından su damlıyor. Eldivenini giymiş, maskeni takmışsın.","soru":"Ne yaparsın?","secenekler":["Sızıntıyı görmezden gelip kaygan zemini silmeden doğrudan banyo yüzeylerine geçersin","Sızıntıyı kendi başına bantla kapatır, kimseye bildirmezsin","Sızıntının kuruyup kaybolacağını düşünerek temizliğe kaldığın yerden devam edersin","Kaygan artıkları alır, sızıntı için arıza formu doldurup kat şefine bildirirsin"],"dogru":3,"aciklama":"Kayma riskini azaltmak için artıklar önce alınır, arıza ise formla bildirilir. Bildirilmeyen küçük arıza büyük şikâyete ya da kazaya yol açabilir.","konu":"4.1.3"},{"id":"kh1-4-s080","tur":"senaryo","durum":"Sabah 10.30. Otel yeni bir kireç çözücü almış; etiketinde asidik olduğu yazıyor. Penceresiz banyoda duş kabininin camında kireç birikmiş.","soru":"Ne yaparsın?","secenekler":["Hızlı sonuç için ürünü WC temizleyiciyle karıştırıp camı silersin","Eldiven ve maskeni takar, ürünü gizli köşede dener, kapıyı açıp havalandırırsın","İş kısa sürecek diye maskeni takmadan, yalnız eldivenle hemen çalışmaya başlarsın","Ürünü doğrudan cama döküp banyonun kapısını kapatırsın"],"dogru":1,"aciklama":"Asidik ürün maskesiz kullanılmaz, ilk kullanımda gizli köşede denenir ve ortam havalandırılır. Ürünleri karıştırmak ve doğrudan dökmek kurallara aykırıdır.","konu":"4.1.1"},{"id":"kh1-4-s081","tur":"senaryo","durum":"Sabah 08.45. 118 numaralı oda üç gündür boş. Kat şefi boş odalarda legionella takibinin yapılmasını istiyor.","soru":"Ne yaparsın?","secenekler":["Küvet ve lavabo armatürlerini açıp sıcak ve soğuk suyu akıtır, odayı işaretletirsin","Odaya girmeden kapıdan geçip su akıtılmış gibi listeye imza atarsın","Yalnızca klozetin sifonunu çekip armatürlere dokunmadan odadan çıkarsın ve listeye yazarsın","Havalandırmayı kapatıp odayı kilitli hâlde bırakırsın"],"dogru":0,"aciklama":"Boş odalarda armatürlerden su akıtılır, oda işaretlenir ve kat şefince imzalanır. Yalnız sifon çekmek ya da hiç girmemek takibi eksik bırakır.","konu":"4.1.5"},{"id":"kh1-4-s082","tur":"senaryo","durum":"Akşam 17.30. Klozeti ve bideyi temizledin. Şimdi banyo aynasını silmeye geçeceksin; eldivenlerin klozet temizliğinden kirli.","soru":"Ne yaparsın?","secenekler":["Aynı eldivenle aynayı silmeye hemen devam edersin","Eldivenleri yalnız lavaboda durulayıp aynı eldivenle çalışırsın","Eldivenleri çıkarıp çıplak elle aynayı silersin","Eldivenleri çıkarıp yenisini takarak aynaya geçersin"],"dogru":3,"aciklama":"Klozet bölgesinden gelen mikroplar eldivenle ayna ve lavabo gibi yüzeylere bulaşabilir; eldiven değiştirmek çapraz bulaşmayı önler.","konu":"4.1.5"},{"id":"kh1-4-s101","tur":"coktan-secmeli","soru":"Konuğun banyoda kullanması için bırakılan, çoğu küçük boy ve tek kullanımlık ürünlerin genel adı hangisidir?","secenekler":["Banyo temizlik malzemeleri","Otel bilgi kartları","Banyo buklet malzemeleri","Banyo tekstil ürünleri"],"dogru":2,"aciklama":"Sabun, şampuan ve krem gibi kişisel bakım ürünleri buklet malzemesidir; havlu ve bornoz ise banyo tekstili grubundadır.","konu":"4.2.1"},{"id":"kh1-4-s102","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi banyo tekstili değil, tek kullanımlık buklet malzemesidir?","secenekler":["Ayak havlusu","Duş bonesi","Bornoz","El havlusu"],"dogru":1,"aciklama":"Banyo tekstilleri el, ayak ve banyo havluları ile bornozdur; duş bonesi ise buklet listesindeki bir kalemdir.","konu":"4.2.1"},{"id":"kh1-4-s103","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi mendil çeşidi değildir?","secenekler":["Kulak temizleme çubuğu","Kutu mendil","Kolonyalı mendil","Gözlük temizleme mendili"],"dogru":0,"aciklama":"Kulak temizleme çubuğu pamuklu küçük bir çubuktur; kutu, kolonyalı ve gözlük temizleme mendilleri ise mendil çeşididir.","konu":"4.2.1"},{"id":"kh1-4-s104","tur":"coktan-secmeli","soru":"Oda görevlisi, banyodaki malzemeleri odada kalan kişi sayısı kadar yerleştirir. Bunun asıl nedeni nedir?","secenekler":["Kat arabasını daha hafif taşıyarak zaman kazanmak","Kontrol işlemini ortadan kaldırarak süreyi kısaltmak","Eksik bırakıp konuğu mağdur etmemek, israfı önlemek","Banyoda daha fazla boş alan bırakıp düzeni korumak"],"dogru":2,"aciklama":"Malzeme az olursa konuk ihtiyacını karşılayamaz, fazla olursa israf olur; sayı odadaki kişiye göre belirlenir.","konu":"4.2.3"},{"id":"kh1-4-s105","tur":"coktan-secmeli","soru":"İki kişilik bir oda ile dört kişilik bir aile odasının banyo bukleti için hangisi doğrudur?","secenekler":["Dört kişilik odaya daha fazla malzeme konur","Her iki odaya da aynı miktar konur","Kişi sayısı yalnız havlu için dikkate alınır","Miktar oda numarasına göre belirlenir"],"dogru":0,"aciklama":"Odada kalan kişi sayısı yerleştirmede dikkate alınır; bu yüzden büyük odanın banyosuna daha fazla malzeme bırakılır.","konu":"4.2.3"},{"id":"kh1-4-s106","tur":"coktan-secmeli","soru":"Aynı otelde VIP konuğun banyosunda standart konuğunkinden farklı bir set bulunması hangi duruma dayanır?","secenekler":["Bukletin her odada aynı olmak zorunda olmasına","Seçimin yalnız konuğun kendi isteğine bırakılmasına","Malzemenin görevlinin kişisel tercihine göre seçilmesine","Malzemenin konuk türüne göre farklılaşabilmesine"],"dogru":3,"aciklama":"Aynı tesiste bile konuk türüne göre banyoya konan malzeme değişebilir; seçimi işletmenin standardı belirler.","konu":"4.2.2"},{"id":"kh1-4-s107","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi buklet malzemesi seçerken yapılan yanlış bir uygulamadır?","secenekler":["Kategoriyi bilmeden her odaya aynı seti almak","Odadaki kişi sayısı kadar malzeme seçmek","Eksik olan malzemeleri belirleyip arabadan almak","Prosedürde yazan ekstra malzemeyi seçmek"],"dogru":0,"aciklama":"Seçim odanın kategorisine ve kişi sayısına göre yapılır; kategori bilinmeden aynı set almak yanlış malzemeye yol açar.","konu":"4.2.2"},{"id":"kh1-4-s108","tur":"coktan-secmeli","soru":"Kat görevlisi, temizlenmiş banyoya buklet yerleştirmeden önce odanın kategorisini neden kontrol eder?","secenekler":["Kat arabasındaki ürünlerin sayısını saymak için","Uygun seti seçip yanlış malzeme koymamak için","Banyonun temizlik süresini önceden hesaplamak için","Hangi odanın boş olduğunu anlamak için"],"dogru":1,"aciklama":"Kategoriye göre malzeme değiştiği için görevli önce odanın kategorisinden emin olur, sonra setini seçer.","konu":"4.2.2"},{"id":"kh1-4-s109","tur":"coktan-secmeli","soru":"Konaklama tesislerinde odada bulunması gereken asgari buklet malzemeleri neye göre belirlenir?","secenekler":["Odanın bulunduğu kata ve manzarasına göre","Konuğun kalış süresine göre","Görevlinin iş deneyimine göre","Tesisin sınıfına ve niteliklerine göre"],"dogru":3,"aciklama":"Yönetmelik asgari malzemeleri tesisin sınıfına göre belirler; kat, süre ya da personel deneyimi bu listeyi değiştirmez.","konu":"4.2.1"},{"id":"kh1-4-s110","tur":"dogru-yanlis","soru":"Konuğa sunulan buklet malzemelerinin kalitesi, işletmenin saygınlığı hakkındaki izlenimi etkileyebilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Buklet malzemeleri işletmenin saygınlık göstergesidir; konuk beğenirse işletmeden memnuniyeti artar.","konu":"4.2.1"},{"id":"kh1-4-s111","tur":"dogru-yanlis","soru":"Banyodaki buklet malzemelerinin çeşidi ve kalitesi, işletmenin maliyetinden bağımsız olarak belirlenir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Malzemelerin sayısı, çeşidi ve kalitesi işletmenin sunduğu hizmete ve ortaya çıkan maliyete göre değişir.","konu":"4.2.2"},{"id":"kh1-4-s112","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi kat arabasından malzeme almadan önce yapılan işlemdir?","secenekler":["Malzemeleri kullanım yerlerine dizmek","Banyoda eksik olan malzemeleri belirlemek","Yerleştirme sonrası kontrol yapmak","Oda durum raporunu kat şefine teslim etmek"],"dogru":1,"aciklama":"Önce eksik belirlenir, ona göre malzeme alınır; dizme, kontrol ve rapor teslimi bu işlemden sonra gelir.","konu":"4.2.2"},{"id":"kh1-4-s113","tur":"coktan-secmeli","soru":"VIP ya da tekrar gelen konuk gibi özel durumlu konuklara ekstra malzeme ne zaman konur?","secenekler":["Görevli uygun gördüğünde","Kat arabasında fazla malzeme kaldığında","İşletme prosedüründe öngörülmüşse","Konuk odaya girdikten sonra istediğinde"],"dogru":2,"aciklama":"Ekstra malzeme görevlinin kişisel kararı değildir; yalnız işletme prosedüründe öngörülmüşse seçilir ve yerleştirilir.","konu":"4.2.2"},{"id":"kh1-4-s114","tur":"coktan-secmeli","soru":"Özel durumlu konuk için ekstra malzeme seçerken aşağıdakilerden hangisi doğru değildir?","secenekler":["İşletme prosedürünü dikkate almak","Konuğun özel durumunu rapordan öğrenmek","Ekstra malzemeyi arabadan alıp banyoya koymak","Prosedürde olmayanı kendi isteğiyle eklemek"],"dogru":3,"aciklama":"Ekstra malzeme prosedürde yazıyorsa eklenir; kişisel inisiyatifle eklenen malzeme işletmenin standardını bozar.","konu":"4.2.2"},{"id":"kh1-4-s115","tur":"coktan-secmeli","soru":"Bir otele her yaz gelen aile için kat şefi karşılama notu hazırlıyor. Bu aile banyo malzemesi seçiminde hangi konuk grubunda değerlendirilir?","secenekler":["Rezervasyonsuz gelen konuk","Grup lideri olan konuk","Erken varış yapan konuk","Tekrar gelen konuk"],"dogru":3,"aciklama":"Daha önce aynı işletmede konaklamış konuk tekrar gelen konuktur; işletmeler sadakati takdir etmek için prosedüre göre ek malzeme ayırabilir.","konu":"4.2.2"},{"id":"kh1-4-s116","tur":"coktan-secmeli","soru":"Bazı işletmeler tekrar gelen konuk için ekstra malzeme ayırır. Bunun asıl nedeni nedir?","secenekler":["Sadakati takdir edip özel hissettirmek","Stoktaki malzemeyi daha çabuk tüketmek için","Kat arabasının yükünü azaltıp rahatlamak","Oda fiyatını konuğa göre yükseltmek"],"dogru":0,"aciklama":"Tekrar gelen konuk işletmeye bağlılığını göstermiştir; ekstra malzeme bu sadakate verilen değerin bir göstergesidir.","konu":"4.2.2"},{"id":"kh1-4-s117","tur":"coktan-secmeli","soru":"Buklet standı ne amaçla kullanılır?","secenekler":["Malzemelerin düzenli gösterilmesi için","Kirli tekstillerin toplanması için","Konuk eşyalarının güvenle saklanması için","Atık pillerin ayrı biriktirilmesi için"],"dogru":0,"aciklama":"Buklet standı ya da tepsisi malzemeleri düzenli gösterir ve banyonun şık görünmesine yardım eder.","konu":"4.2.2"},{"id":"kh1-4-s118","tur":"coktan-secmeli","soru":"Buklet malzemeleri banyoda hangi alana yerleştirilmelidir?","secenekler":["Konuğun görmeyeceği, dolap içindeki bir rafa","Kat arabasının üzerine, görevlinin yanına","Odanın girişindeki küçük sehpanın üstüne","Dekorasyona uygun, kolay ulaşılır bir alana"],"dogru":3,"aciklama":"Malzemeler göze hoş görünmeli ve konuğun ihtiyaç duyduğu anda kolayca ulaşabileceği yere konmalıdır.","konu":"4.2.3"},{"id":"kh1-4-s119","tur":"coktan-secmeli","soru":"Banyoya buklet yerleştirirken aşağıdakilerden hangisi yanlıştır?","secenekler":["Logolu ürünlerin logosunu görünmez dizmek","Malzemeleri kendi kutusuna koymak","Küçük ve büyük ürünlerin boyutunu gözetmek","Malzemeleri kullanım sırasına göre dizmek"],"dogru":0,"aciklama":"Logo işletmeyi tanıtır; logolu ürünün logosu görünecek biçimde yerleştirilir.","konu":"4.2.3"},{"id":"kh1-4-s120","tur":"coktan-secmeli","soru":"Logolu buklet malzemeleri neden logo görünecek şekilde yerleştirilir?","secenekler":["Konuk ürünü yanlış kullanmasın diye","Logo işletmeyi tanıtır ve düzenli görünüm sağlar","Ürünlerin hangi sırayla kullanılacağını göstermek için","Stok sayımı kolaylaşsın diye"],"dogru":1,"aciklama":"Görünen logo işletmenin tanıtımına katkı sağlar; stok sayımı ya da kullanım sırası ile ilgisi yoktur.","konu":"4.2.3"},{"id":"kh1-4-s121","tur":"coktan-secmeli","soru":"Zeynep, banyoya sabun, şampuan ve duş jelini kendi kutusuna koyup kullanım sırasına göre dizdi. Bu uygulamanın faydası nedir?","secenekler":["Ürünler daha uzun süre bozulmaz","Konuk aradığı ürünü aramadan hemen bulur","Kat görevlisi ürünleri kolayca sayabilir","Konuk ürünlerin çeşidini karşılaştırarak seçer"],"dogru":1,"aciklama":"Kendi kutusunda ve kullanım sırasına göre dizilen ürünleri konuk aramadan bulur.","konu":"4.2.3"},{"id":"kh1-4-s122","tur":"coktan-secmeli","soru":"Buklet yerleştirme bittikten sonra kontrol yapılmasının amacı nedir?","secenekler":["Kat şefinin imzasını almak için gerekli adımı yapmak","Kat arabasını daha çabuk boşaltmak","Çalışma süresini kısaltmak","Eksikleri gidermek ve konuk memnuniyetini sağlamak"],"dogru":3,"aciklama":"Kontrol, yeterli sayıda ve uygun yerlere konup konmadığına bakarak eksikleri konuk fark etmeden tamamlamayı sağlar.","konu":"4.2.3"},{"id":"kh1-4-s123","tur":"dogru-yanlis","soru":"Yerleştirme sonrası kontrol, yalnız konuk şikâyet ettiğinde yapılır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kontrol yerleştirmenin ardından her odada yapılır; amaç eksikleri konuk fark etmeden gidermektir.","konu":"4.2.3"},{"id":"kh1-4-s124","tur":"dogru-yanlis","soru":"Banyoya konan malzeme sayısı, odada kalan kişi sayısına göre belirlenir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Kişi sayısı yerleştirmede dikkate alınır; iki kişilik odayla dört kişilik oda aynı miktarda malzeme almaz.","konu":"4.2.3"},{"id":"kh1-4-s125","tur":"coktan-secmeli","soru":"Zeynep, eşantiyon sabunu odanın uzak bir köşesine koymuş. Aşağıdakilerden hangisi doğru düzeltmedir?","secenekler":["Sabunu kullanılacağı lavabonun yanına taşımak","Sabunu odadaki dolabın içine kaldırıp kapatmak","Sabunu yatağın üstünde bırakmak","Sabunu kat arabasında bırakıp rapora yazmak"],"dogru":0,"aciklama":"Eşantiyon malzemeler kullanım yerleri dikkate alınarak yerleştirilir; kullanılacağı lavabonun yanı doğru yerdir.","konu":"4.2.3"},{"id":"kh1-4-s126","tur":"coktan-secmeli","soru":"El, ayak ve banyo havluları ile bornozdan oluşan gruba ne ad verilir?","secenekler":["Buklet ürünleri","Bilgi kartları","Kat arabası malzemeleri","Banyo tekstilleri"],"dogru":3,"aciklama":"Havlu ve bornoz banyo tekstilleridir; sabun, şampuan ve benzeri ürünler ise buklet malzemesidir.","konu":"4.2.4"},{"id":"kh1-4-s127","tur":"coktan-secmeli","soru":"Bazı işletmelerde havlu ve bornoz banyo yerine nereye bırakılabilir?","secenekler":["Çamaşırhane torbasının içine","Kat arabasının alt rafına","Yatağın üstüne ya da dolaba","Mini bar rafının üstüne"],"dogru":2,"aciklama":"Havlu ve bornoz genellikle banyoya bırakılır; ancak bazı işletmeler bunları yatağın üstüne ya da elbise dolabına koyar.","konu":"4.2.4"},{"id":"kh1-4-s128","tur":"coktan-secmeli","soru":"Havlu çeşidi hangi duruma göre değişir?","secenekler":["Tesisin büyüklüğüne ve hizmet çeşidine","Konuğun geldiği ülkeye ve yaşına","Mevsimin sıcaklığına ve nemine","Havluların renk kodlarına ve boyutlarına"],"dogru":0,"aciklama":"Havlular tesisin küçüklüğüne ya da büyüklüğüne ve sunduğu hizmetin çeşidine göre değişir.","konu":"4.2.4"},{"id":"kh1-4-s129","tur":"coktan-secmeli","soru":"Logolu havlu yerleştiren görevli hangi noktaya özellikle dikkat eder?","secenekler":["Logonun bornoz askısına denk gelmesine ve asılmasına","Katlanmış havlunun logosunun göze hoş görünmesine","Havluların lavabonun içinde bekletilmesine","Bütün havluların aynı renkte ve boyda olmasına"],"dogru":1,"aciklama":"Logolu havlularda katlama sonrası logonun görünüp görünmediğinden emin olunur.","konu":"4.2.4"},{"id":"kh1-4-s130","tur":"coktan-secmeli","soru":"Havlu yerleştirmede aşağıdakilerden hangisi yanlıştır?","secenekler":["Havluları odada kalan kişi sayısı kadar almak","Bornozu işletmenin belirlediği yere koymak","Logolu havluyu logo içe gelecek biçimde katlamak","Katlama sonrası logonun görünmesini kontrol etmek"],"dogru":2,"aciklama":"Logolu havlu logo görünecek şekilde katlanır; logoyu içe çevirmek bu kurala aykırıdır.","konu":"4.2.4"},{"id":"kh1-4-s131","tur":"coktan-secmeli","soru":"Kat görevlisi 214 numaralı odada çevre kartı uygulaması olduğunu görüyor. Kartta konuğun tercihi işaretlenmiş. Ne yapar?","secenekler":["Havluların tamamını kartı okumadan yeniler","Konuğun bildirdiği tercihe uygun davranır","Kartı kaldırıp çöpe atar","Havlu yerleştirmeyi baştan atlar"],"dogru":1,"aciklama":"Çevre kartı uygulamasında havlu konuğun kartla bildirdiği tercihe göre değiştirilir; kartı yok saymak bu uygulamayı bozar.","konu":"4.2.4"},{"id":"kh1-4-s132","tur":"coktan-secmeli","soru":"Havlu değişim kartı neden bulunur?","secenekler":["Havlu sayısını önceden belirleyebilmek için","Oda numarasını kayda geçirebilmek için","Çamaşırhaneye sipariş verebilmek için","Konuğun değişim isteğini bildirmesi için"],"dogru":3,"aciklama":"Kart konuğun tercihini sormayı sağlar; havlu sayısı ya da oda numarası kaydıyla ilgisi yoktur.","konu":"4.2.1"},{"id":"kh1-4-s133","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi havlu yerleştirmeden önce yapılması gereken kontroldür?","secenekler":["Havluların fiyatını öğrenmek","Çamaşırhane sipariş formunu doldurmak","Odada konuk olup olmadığına bakmak","Kat arabasını boşaltmak"],"dogru":2,"aciklama":"Havlu yerleştirmeden önce odadaki duruma bakılır; böylece konuğun mahremiyetine saygı gösterilir.","konu":"4.2.4"},{"id":"kh1-4-s134","tur":"coktan-secmeli","soru":"Çevre kartının amacı hangisidir?","secenekler":["Konuğa temizlik randevusu vermek","Konuğun şikâyetini kat şefine iletmek","Konuğu çevre dostu uygulamalara davet etmek","Otel hizmetlerinin güncel fiyatlarını duyurmak"],"dogru":2,"aciklama":"Çevre kartı otel bilgi kartlarından biridir ve çevre dostu uygulamaları duyurur.","konu":"4.2.1"},{"id":"kh1-4-s135","tur":"coktan-secmeli","soru":"Çevre kartı ve havlu değişim kartı hangi tür buklet malzemesidir?","secenekler":["Kişisel bakım ürünleri ve gereçleri","Konuğu bilgilendiren ve yönlendiren kartlar","Banyo tekstilleri ve donanımları","Hediye olarak verilen eşantiyon malzemelerinin tümü"],"dogru":1,"aciklama":"Her iki kart da banyo buklet listesinde yer alan, konukla iletişim kuran kartlardır.","konu":"4.2.1"},{"id":"kh1-4-s136","tur":"coktan-secmeli","soru":"Hijyenik atıkların atılmadan önce kapatılıp ayrı toplanması için buklet listesinde hangi kalem bulunur?","secenekler":["Bardak kapağı","Duş bonesi","Hijyen poşeti","Kutu mendil"],"dogru":2,"aciklama":"Hijyen poşeti hijyenik atıkların ayrı toplanmasını sağlar; bardak kapağı bardağı örter, duş bonesi saçı korur.","konu":"4.2.1"},{"id":"kh1-4-s137","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi diş setinin içinde yer alır?","secenekler":["Tıraş kremi ve tıraş bıçağı","Diş macunu ve diş fırçası","Sabun ve şampuan","Pamuk ve kulak çubuğu"],"dogru":1,"aciklama":"Diş seti diş macunu ve diş fırçasından oluşur; tıraş kremi ve bıçağı ise tıraş setinin içindedir.","konu":"4.2.1"},{"id":"kh1-4-s138","tur":"coktan-secmeli","soru":"Banyodaki bardağın üzerinde kapak bulunmasının asıl nedeni hangisidir?","secenekler":["Bardağı toz ve bulaşmadan korumak","Bardağı daha uzun süre sıcak tutmak","Bardağın çalınmasını önlemek","Bardağı lavaboya sabitlemek"],"dogru":0,"aciklama":"Bardak kapağı hijyen için kullanılır; bardağın temiz kalmasını sağlar.","konu":"4.2.1"},{"id":"kh1-4-s139","tur":"coktan-secmeli","soru":"Zeynep, küçük bir kutuyu büyük şişelerin arkasında görünmez hâlde bırakmış. Hangi düzeltme doğrudur?","secenekler":["Küçük kutuyu kat arabasına geri koymak","Büyük şişeleri konuk odasına taşımak","Ürünleri kutudan çıkarıp açıkta bırakmak","Boyutlara bakarak dizilimi değiştirmek"],"dogru":3,"aciklama":"Yerleştirmede malzemelerin büyüklük ve küçüklüğü gözetilir; böylece küçük ürünler de görünür kalır.","konu":"4.2.3"},{"id":"kh1-4-s140","tur":"coktan-secmeli","soru":"Banyodaki buklet malzemelerinin sayısı ve kalitesi neye göre değişir?","secenekler":["Oda numarasına ve bulunduğu kat sayısına","İşletmenin hizmetine ve maliyetine","Görevlinin vardiya saatine","Konuğun giriş yaptığı günün durumuna"],"dogru":1,"aciklama":"Sayı, çeşit ve kalite işletmenin hizmet düzeyine ve maliyetine bağlıdır.","konu":"4.2.2"},{"id":"kh1-4-s141","tur":"coktan-secmeli","soru":"Zeynep, iki kişinin kaldığı odanın banyosunda yalnız bir diş seti olduğunu görüyor. Sonraki adımı hangisi olmalıdır?","secenekler":["Eksik malzemeyi arabadan tamamlamak","Mevcut seti ikiye bölüp yerleştirmek","Konuğun resepsiyondan istemesini beklemek","Tamamlamayı sonraki vardiyaya bırakmak"],"dogru":0,"aciklama":"Odada iki kişi kaldığı için iki set gerekir; görevli eksiği kat arabasından tamamlar.","konu":"4.2.3"},{"id":"kh1-4-s142","tur":"dogru-yanlis","soru":"Havlu ve bornoz her işletmede yalnız banyoya bırakılır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Bazı işletmeler havlu ve bornozu yatağın üstüne ya da elbise dolabına da bırakır.","konu":"4.2.4"},{"id":"kh1-4-s143","tur":"dogru-yanlis","soru":"Özel durumlu konuk için ekstra malzeme yalnız işletme prosedürü öngörüyorsa konur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Ekstra malzeme görevlinin kişisel tercihine değil, işletmenin prosedürüne bağlıdır.","konu":"4.2.2"},{"id":"kh1-4-s144","tur":"coktan-secmeli","soru":"Oda kategorisine göre buklet miktar tablosu neyi gösterir?","secenekler":["Konukların ürün tercihlerini ve beğeni puanlarını","Ürünlerin satın alma fiyatlarını ve stok miktarını","Her kategoriye hangi malzemeden kaç adet konacağını","Kat görevlilerinin haftalık vardiya çizelgesini ve planını"],"dogru":2,"aciklama":"Tablo, işletmenin oda kategorisine göre belirlediği malzeme miktarlarını verir; satın alma fiyatları ya da vardiyalar bu tabloda yer almaz.","konu":"4.2.1"},{"id":"kh1-4-s145","tur":"senaryo","durum":"Sabah 09.30’da 218 numaralı odanın banyosundasın. Oda durum raporuna göre odada iki kişi kalıyor; banyoda yalnız bir diş seti ve bir şampuan var. Kat arabanda yeterli malzeme var.","soru":"Ne yaparsın?","secenekler":["Yalnız şampuanı tamamlarım, diş setini konuk isterse getiririm","Eksikleri sonraki vardiyada tamamlanmak üzere rapora yazarım","Başka bir odadan fazla seti alıp buraya getiririm","Eksikleri belirleyip kişi sayısı kadar malzemeyi alırım"],"dogru":3,"aciklama":"Kişi sayısı kadar malzeme konmalı ve eksikler yerleştirme sırasında tamamlanmalıdır; eksiği konuğun istemesini beklemek konuğu mağdur eder.","konu":"4.2.2"},{"id":"kh1-4-s146","tur":"senaryo","durum":"Öğleden sonra saat 15.00’te banyoya buklet yerleştiriyorsun. Logolu mini şampuanların logosu duvara dönük, küçük bir kutu da büyük şişelerin arkasında kalmış.","soru":"Ne yaparsın?","secenekler":["Yalnız logoları çevirir, küçük kutuyu arkada bırakırım","Logoları görünür biçimde çevirir, küçük kutuyu öne alırım","Kutuyu kat arabasına geri koyar, logoya dokunmadan çıkarım","Düzeni konuğun kendisinin değiştireceğini düşünüp olduğu gibi bırakırım"],"dogru":1,"aciklama":"Logo görünür olmalı ve malzemelerin boyutu gözetilerek küçük ürünler de görünür bırakılmalıdır; yalnız logo düzeltilirse düzen eksik kalır.","konu":"4.2.3"},{"id":"kh1-4-s147","tur":"senaryo","durum":"VIP olarak kayıtlı bir konuğun odasındasın. İşletme prosedüründe VIP odalara standart sete ek olarak ekstra buklet seti konuyor. Kat arabanda ekstra set var.","soru":"Ne yaparsın?","secenekler":["Prosedürdeki ekstra seti seçip standart setle birlikte yerleştiririm","Yalnız standart seti yerleştirir, ekstra için konuğun istemesini beklerim","Kendi seçtiğim farklı ürünleri ekstra olarak koyarım","Ekstra seti kat şefine sormadan hiç yerleştirmem"],"dogru":0,"aciklama":"Prosedürde öngörülen ekstra malzeme yerleştirilir; prosedürde olmayan ürün eklemek ya da seti hiç koymamak işletmenin standardına aykırıdır.","konu":"4.2.2"},{"id":"kh1-4-s148","tur":"senaryo","durum":"Çevre kartı uygulaması olan bir odanın banyosundasın. Konuk, kartla havluların değiştirilmesini istemediğini bildirmiş; havlular kullanılmış.","soru":"Ne yaparsın?","secenekler":["Kuralı bilmediğim için tüm havluları yenisiyle değiştiririm","Havluları kaldırıp yerine bornoz koyarım","Konuğun bildirdiği tercihe uyar, havluları değiştirmem","Kartı kaldırıp odayı standart prosedürle hazırlarım"],"dogru":2,"aciklama":"Çevre kartı konuğun tercihini bildirir; tercihe uymak hem konuğa saygıdır hem de çevre dostu uygulamanın gereğidir.","konu":"4.2.4"},{"id":"kh1-4-s149","tur":"senaryo","durum":"Sabah 11.25. Çıkış yapılmış 407 numaralı odanın banyosunda arkadaşın cam temizleyici spreyini sıkarken bir damla gözüne sıçrıyor ve gözünün acıdığını söylüyor.","soru":"Ne yaparsın?","secenekler":["Önce doktora götürür, yıkamayı orada yapsınlar diye beklerim","Lavaboda bol suyla yıkatır, sonra doktora yollarım","Gözünü kuru kâğıt havluyla silip biraz beklemesini isterim","Ürün etiketini okuyup ne yapacağıma buna göre karar veririm"],"dogru":1,"aciklama":"Kimyasal göze sıçradığında önce bol ve akan suyla yıkamak gerekir, sonra doktora gidilir. Doktoru beklemek, silmek ya da etiket aramak yıkamayı geciktirir; olay ayrıca amire bildirilir.","konu":"4.1.1"},{"id":"kh1-4-s150","tur":"senaryo","durum":"Öğleden sonra 13.40. Kat arabasının yanındaki arkadaşın, cam spreyi bitince depodaki kireç çözücüyü boş bir su şişesine boşaltmayı öneriyor ve bunun daha pratik olacağını söylüyor.","soru":"Ne yaparsın?","secenekler":["Su şişesini yalnızca depoda tutması koşuluyla, ürünün adını üstüne yazdırıp kabul ederim","Su şişesine koymasına izin veririm ama kapağını sıkıca kapatmasını isterim, sorun görmem","Şişeyi kullanıp üzerine ürünün adını kalemle yazarım, böylece karışmadığından emin olurum","Ürünün yalnızca kendi etiketli şişesinde kalmasını, başka kaba konmamasını da söylerim"],"dogru":3,"aciklama":"Temizlik maddeleri etiketli olmalı ve kendi özel şişesi dışında bir kaba, örneğin su şişesine konmamalıdır. Aksi hâlde yanlış içilme ya da yanlış yüzeyde kullanılma riski doğar; el yazısı not ya da kapak bu riski ortadan kaldırmaz.","konu":"4.1.1"},{"id":"kh1-4-s151","tur":"senaryo","durum":"Sabah 10.20. Çıkış yapılmış 221 numaralı odanın banyosunda saç kurutma makinesini temizleyeceksin. Makine tezgâhın üstünde duruyor ve kablosunun prize takılı olup olmadığını henüz görmedin.","soru":"Ne yaparsın?","secenekler":["Fişin çekili olduğunu kontrol eder, nemli bezle silip kurularım","Makineyi lavaboda musluk suyuyla iyice yıkar, sonra havluyla kurularım","Fişi takılı bırakır, yalnızca kuru bezle hızlıca silip yerine koyarım","Makineyi sıvı temizleyiciye batırıp bir süre bekletir, sonra kurularım"],"dogru":0,"aciklama":"Elektrikli aletin temizliğine başlamadan önce elektrik bağlantısının kapalı olduğundan emin olunur; sonra genel temizlik maddesi ve nemli bezle silinip kurulanır. Suya tutmak ya da batırmak elektrik riski doğurur.","konu":"4.1.4"},{"id":"kh1-4-s152","tur":"senaryo","durum":"Öğleden sonra 15.30. Konuk çıkış yapmış; 326 numaralı odanın banyosunu buharlı temizlik makinesiyle temizleyeceksin. Duvarlar, ayna ve zemin kirli; kapı banyonun bir ucunda.","soru":"Temizliğe nasıl başlarsın?","secenekler":["Zeminden başlarım, sonra duvarlara geçerim, kapı yanını en sona bırakırım","Kapıya yakın köşeden başlarım, banyonun içine doğru ilerleyerek buharlarım","Duvardan başlayıp aşağı inerim, kapıya en uzak yerden kapıya ilerlerim","Önce aynayı buharlarım, sonra duvarı atlayıp doğrudan zemine geçerim"],"dogru":2,"aciklama":"Buharlı temizlikte çalışma sırası yukarıdan aşağıya ve kapıya en uzak noktadan kapıya doğrudur. Zeminden başlamak ya da içeri doğru ilerlemek, temizlediğin yere tekrar basmana ve damlayan suyun temiz alanı kirletmesine yol açar.","konu":"4.1.5"}],"siralamalar":[{"id":"kh1-4-r01","konu":"4.1.1","baslik":"Banyo temizliğine hazırlık","yonerge":"Oda görevlisi olarak banyo temizliğine başlamadan önceki hazırlık adımlarını sıraya koy.","adimlar":["Kişisel bakım ve hijyen kurallarını uygula.","İş başı toplantısına (meeting) katıl.","Kat şefinden iş programını öğren.","Sorumlu olduğun odaların durum raporunu al.","Temizlik yöntemine göre kullanılacak malzemeleri belirle.","Temizlik basketini ve renk kodlu bezleri hazırla."],"aciklama":"Önce kendini ve görevini hazırlarsın, sonra odaların durumunu öğrenirsin, en son o duruma uygun malzemeleri belirleyip basketi doldurursun."},{"id":"kh1-4-r02","konu":"4.1.2","baslik":"Banyodan çöp toplama","yonerge":"Oda görevlisi olarak banyodaki çöpleri toplama adımlarını sıraya koy.","adimlar":["Eldiven giy ve maske tak.","Zeminde kayma tehlikesi yaratan sabun artıklarını topla.","Kirli banyo tekstilini ve kullanılmış buklet malzemelerini topla.","Banyo çöplerini topla.","Çöp torbasının ağzını bağlayıp kat arabasındaki torbaya yerleştir."],"aciklama":"Önce kendini korur, kaygan artıkları alırsın; sonra kirli tekstil ve çöpleri toplarsın, torbayı bağlayıp kat arabasında ilgili bölüme koyarsın."},{"id":"kh1-4-r03","konu":"4.1.3","baslik":"Banyoda arıza takibi","yonerge":"Banyoda arıza tespit eden bir oda görevlisi olarak adımları sıraya koy.","adimlar":["Banyoda tespit ettiğin arıza için arıza formunu doldur.","Formun nüshalarını teknik servise ve kat şefine ilet.","Arızanın giderilip giderilmediğini takip et.","Arıza giderildiyse banyoya gidip kontrol et ve banyoyu düzenle.","Teknik servisin geri verdiği formu kendi nüshanla birlikte dosyala."],"aciklama":"Arıza önce kayda geçer, sonra ilgililere iletilir ve takip edilir; giderilince yerinde kontrol edilip form dosyalanarak süreç kapatılır."},{"id":"kh1-4-r04","konu":"4.1.4","baslik":"Saç kurutma makinesinin temizliği","yonerge":"Banyodaki saç kurutma makinesini temizleme adımlarını sıraya koy.","adimlar":["Cihazın elektrik bağlantısının kapalı olduğunu kontrol et.","Makineyi genel temizlik maddesi ve nemli bezle sil.","Makineyi renk koduna uygun bezle kurula.","Makineyi işletmenin belirlediği yere yerleştir."],"aciklama":"Elektrikli alette önce güvenlik gelir; bağlantı kapalıyken silinir, kurulanır ve en son yerine konur."},{"id":"kh1-4-r05","konu":"4.1.5","baslik":"WC ve bide temizliği","yonerge":"Oda görevlisi olarak klozet temizliğinin adımlarını sıraya koy.","adimlar":["Eldiven giy ve maske tak.","Temizliğe başlamadan rezervuarı çalıştırarak alanı suyla yıka.","Klozetin iç kısmına daire çizerek WC temizleyici sık ve fırçayı ortaya bırak.","Kimyasalın dezenfekte etmesini bekle; bu sırada çöp kovasını ve kül tablasını yıka.","Klozeti fırçala.","Klozet çevresini ve kapaklarını renk koduna uygun bezle dıştan içe doğru sil."],"aciklama":"Kimyasal ancak bekletilirse işe yarar, fırçalama bekleme sonrası yapılır ve silme en sonda gelir; silmeyi öne almak temizlenmiş yüzeyi yeniden kirletir."},{"id":"kh1-4-r06","konu":"4.1.5","baslik":"Banyo yüzeylerinin temizliği","yonerge":"Banyo yüzeylerinin temizliğini adım adım sıraya koy.","adimlar":["Eldiven giy ve maske tak.","Klozetin iç kısmına WC temizleyiciyi sık.","Klozet dezenfekte olurken lavabo, küvet ya da duşu ve duvarları kimyasal ve süngerle ov.","Klozeti fırçala ve dış yüzeyini ov.","Eldivenleri çıkarıp yenisini tak.","Aynayı uygun kimyasalla sil.","Lavabo, tezgâh ve küveti kurula.","Zemini çıkışa en uzak yerden başlayarak temizle.","Banyo kapısını ve kolunu sil, banyodan çık."],"aciklama":"Kimyasalın beklediği sürede diğer yüzeyler ovulur; klozet bitince eldiven değişir ki mikrop taşınmasın. Zemin ve kapı en sonda gelir, çünkü üstteki işler zemini ıslatıp kirletebilir."},{"id":"kh1-4-r07","konu":"4.1.5","baslik":"Boş odada legionella takibi","yonerge":"Boş bir odada legionella takibini sırayla uygula.","adimlar":["Otomasyon sisteminden günün boş odalarını listele.","Eldiven giy ve maske tak.","Küvet ve lavabo armatürlerini açıp sıcak ve soğuk suyu belirlenen süre akıt.","Yüzey ve donanımları renk koduna uygun bezle kurula.","Suyu akıtılan odanın listede işaretlenmesini sağla.","Listeyi kat şefine imzalat; liste denetimlerde gösterilmek üzere dosyalanır."],"aciklama":"Önce hangi odalarda çalışacağını bilirsin, sonra suyu akıtıp yüzeyleri kurularsın; işaretleme ve kat şefinin imzası işlem bittikten sonra, dosyalama en sonda gelir."},{"id":"kh1-4-r08","konu":"4.1.5","baslik":"Buharlı temizlik","yonerge":"Buharlı makineyle banyo temizliği adımlarını sıraya koy.","adimlar":["Makinenin deposunu işaretli alana kadar suyla doldur.","Makineyi prize tak.","Isındığını uyarı ışığından anla.","Temizlenecek yüzeye uygun aparatı makineye tak.","Buharı yukarıdan aşağıya ve kapıya en uzak noktadan kapıya doğru uygula.","Yumuşayan kiri renk koduna uygun bezle kurula.","Güvenlik önlemlerini alarak fişi prizden çek.","Aparatları çıkarıp temizle.","Deponun kalan suyunu boşaltıp parçaları depola."],"aciklama":"Makine önce suyla doldurulup ısıtılır, sonra çalışılır; bitişte önce fiş çekilir, sonra aparatlar ve depo temizlenir. Fişi çekmeden parçalara dokunmak güvenli değildir."},{"id":"kh1-4-r09","konu":"4.1","baslik":"Check-out yapılmış odada banyo temizliği","yonerge":"Check-out yapılmış odada banyo temizliğinin genel akışını sıraya koy.","adimlar":["Banyo temizliği için malzemeleri belirle; basketi ve renk kodlu bezleri hazırla.","Kirli banyo tekstilini ve çöpleri topla.","Banyodaki arızaları ve unutulan eşyaları kontrol et.","Donanım ve yüzeyleri temizle ve kurula.","Zemini çıkışa en uzak yerden başlayarak temizle.","Banyo kapısını ve kolunu sil, banyodan çık.","Oda durum raporunu doldurup kat şefine teslim et."],"aciklama":"Önce hazırlık ve toplama, sonra kontrol ve temizlik gelir. Zemin ve çıkış en sonda yapılır; rapor teslimi ise işi kayda geçirerek bitirir."},{"id":"kh1-4-r10","konu":"4.2.2","baslik":"Buklet seçimine hazırlık","yonerge":"Oda görevlisi olarak banyo bukleti seçiminin adımlarını sıraya koy.","adimlar":["Pas anahtarını kat şefinden imza karşılığı teslim al.","Kat arabanı hazırla.","Arabayı çalışacağın odaya yakın, geçişi engellemeyecek yere yerleştir.","Oda durum raporuna göre odaya git ve 3x3 metoduyla kapıyı çal.","Odadan ses gelmezse kapıyı pas anahtarıyla aç.","Banyoda eksik olan buklet malzemelerini belirle.","Odada kalan kişi sayısı kadar malzemeyi arabadan seç.","Özel durumlu konuk varsa prosedürdeki ekstra malzemeyi seç."],"aciklama":"Önce anahtar ve araba hazırlanır, sonra odaya girilir; malzeme seçimi ancak eksik belirlendikten sonra, kişi sayısı ve özel duruma göre yapılır."},{"id":"kh1-4-r11","konu":"4.2.3","baslik":"Banyoya buklet yerleştirme","yonerge":"Oda görevlisi olarak banyoya buklet yerleştirme adımlarını sıraya koy.","adimlar":["Oda durum raporuna göre odaya git ve 3x3 metoduyla kapıyı çal.","Odadan ses gelmezse kapıyı pas anahtarıyla aç.","Kapıya Oda Görevlisi kartını as.","Odadaki kişi sayısı kadar buklet malzemesini kat arabasından al.","Malzemeleri kullanım yerine ve amacına göre banyoya yerleştir.","Prosedürde varsa özel durumlu konuk için ekstra malzemeyi koy.","Yerleştirmenin yeterli ve eksiksiz olup olmadığını kontrol et.","Oda durum raporunu doldurup kat şefine teslim et."],"aciklama":"Odaya girişten sonra malzeme alınır, yerleştirilir ve en son kontrol edilir; rapor ancak iş tamamlandığında doldurulup teslim edilir."},{"id":"kh1-4-r12","konu":"4.2.4","baslik":"Banyoya havlu yerleştirme","yonerge":"Oda görevlisi olarak banyoya havlu yerleştirme adımlarını sıraya koy.","adimlar":["Oda durum raporuna göre odaya git ve 3x3 metoduyla kapıyı çal.","Odadan ses gelmezse kapıyı pas anahtarıyla aç ve Oda Görevlisi kartını as.","Odadaki konuk durumunu kontrol et.","Odadaki kişi sayısı kadar havluyu kat arabasından al.","Havluları ve bornozları, varsa logosu görünecek şekilde işletmenin belirlediği yerlere yerleştir.","Prosedürde varsa özel durumlu konuk için ekstra malzemeyi koy.","Oda durum raporunu doldur.","Pas anahtarını iş bitiminde imza karşılığı şefe teslim et."],"aciklama":"Odaya girilir, durum kontrol edilir, havlu alınıp yerleştirilir; rapor ve anahtar teslimi işin sonunda yapılır."}],"acikSorular":[{"id":"kh1-4-y01","konu":"4.1.1","soru":"Penceresiz bir otel banyosunda kireç çözücüyle çalışacak yeni bir kat görevlisi, elindeki WC temizleyicisini de aynı kovaya katıp işi hızlandırmayı düşünüyor. Bu uygulamanın neden yanlış olduğunu açıklayınız ve görevlinin işe başlamadan önce alması gereken en az üç önlemi yazınız.","olcut":[{"metin":"Farklı kimyasalların karıştırılmaması gerektiğini belirtir.","puan":20},{"metin":"Karışımın beklenmedik tepkime verip zehirli gaz çıkarabileceğini açıklar.","puan":30},{"metin":"Eldiven ve maske kullanımını yazar.","puan":15},{"metin":"Banyonun havalandırılmasını yazar.","puan":15},{"metin":"Ürünü kullanım talimatına uygun ve doğru miktarda uygulamayı belirtir.","puan":20}],"ornek":"Farklı temizlik maddeleri birbirine karıştırılmaz, çünkü karışan ürünler beklenmedik tepkime verir ve zehirli gaz çıkarabilir; penceresiz banyoda bu risk daha da büyüktür. Görevli önce eldiven giymeli ve maske takmalı, asidik kireç çözücü kapalı ortamda maskesiz kullanılmaz. Kapıyı açıp havalandırma sistemini çalıştırarak banyoyu havalandırmalı, ürünü kullanım talimatına uygun ve doğru miktarda uygulamalıdır.","ipucu":"Önce iki ürünü bir arada kullanmanın ne gibi bir tehlike doğurduğunu, sonra kapalı bir ortamda kendini nasıl koruyacağını düşünün."},{"id":"kh1-4-y02","konu":"4.1.5","soru":"Bir otelde üç gündür boş duran odanın banyosunda su kullanılmamıştır. Lejyoner hastalığına neden olan etkeni ve bulaşma yolunu yazınız, işletmenin takip standardında yer alan iki uygulamayı belirtiniz ve suyu akıtılan odaların imzalı listeye işlenmesinin neden gerekli olduğunu açıklayınız.","olcut":[{"metin":"Lejyoner hastalığının legionella bakterisinden kaynaklandığını belirtir.","puan":15},{"metin":"Bulaşmanın klima, jakuzili havuz, havalandırma sistemleri gibi sistemlerden solunum yoluyla olduğunu açıklar.","puan":25},{"metin":"Boş odada su akıtma uygulamasını yazar.","puan":15},{"metin":"Duş başlığı ve süzgeçlerin kireç giderme ve dezenfeksiyonunu yazar.","puan":15},{"metin":"Suyu akıtılan odaların imzalı listesinin, denetimlerde gösterilmek üzere gerekli olduğunu açıklar.","puan":30}],"ornek":"Lejyoner hastalığı legionella bakterisinden kaynaklanır; bakteri klima, jakuzili havuz ve havalandırma sistemleri gibi sistemlerden solunum yoluyla bulaşır. İşletmenin takip standardında boş odalarda küvet ve lavabo musluklarını açıp sıcak ve soğuk suyu akıtmak ve duş başlıkları ile musluk başı süzgeçlerindeki kireci çözüp dezenfekte etmek yer alır. Suyu akıtılan odalar kat şefince işaretlenip imzalanır ve il halk sağlığı denetimlerinde gösterilmek üzere dosyalanır; böylece işletme takibi yaptığını belgeleyebilir. Takibin yapılması yönetmelikle zorunludur.","ipucu":"Önce bakterinin hangi sistemlerden nasıl bulaştığını hatırlayın; sonra boş odalarda yapılan işlemin neden yazılı kayda geçirildiğini düşünün."}]},{"ders":"kat-hizmetleri-10","sinif":10,"unite":5,"baslik":"Genel Alan Temizliği","onay":true,"kazanimlar":["Ulusal standartlara ve işletme prosedürüne uygun şekilde iç mekân temizliğini yapar.","Ulusal standartlara ve işletme prosedürüne uygun olarak dış mekânların temizliğini yapar."],"soz":"Lobiden bahçeye genel alanlar otelin yüzüdür; meydancı onu her gün yeniden parlatır.","dersler":[{"baslik":"Otelin Vitrini Nerede Başlar?","ilk":"kh1-5-001"},{"baslik":"Gece Çalışan Makine","ilk":"kh1-5-006"},{"baslik":"Genel Alanların Sorumlusu","ilk":"kh1-5-009"},{"baslik":"Meydancı Kimdir, Ne Yapar?","ilk":"kh1-5-014"},{"baslik":"Meydancılık Bir Tutumdur","ilk":"kh1-5-020"},{"baslik":"Konuk Varken Temizlik","ilk":"kh1-5-026"},{"baslik":"Önce Kendini Koru","ilk":"kh1-5-030"},{"baslik":"Etiketi Oku, Planla, Hazırlıklı Ol","ilk":"kh1-5-035"},{"baslik":"Lobi: İlk Sahne","ilk":"kh1-5-039"},{"baslik":"Toz Almada Renkler Konuşur","ilk":"kh1-5-044"},{"baslik":"Mermer Zemin Nasıl Silinir?","ilk":"kh1-5-049"},{"baslik":"Zemin Neden Parlıyor?","ilk":"kh1-5-052"},{"baslik":"Koridorda Kir Taşınır","ilk":"kh1-5-057"},{"baslik":"Halının Görünmeyen Misafiri","ilk":"kh1-5-061"},{"baslik":"Halı: Köpükten Kuruyana Kadar","ilk":"kh1-5-066"},{"baslik":"Ahşap Suyu Sevmez","ilk":"kh1-5-070"},{"baslik":"Koltuk, Tül ve Perde","ilk":"kh1-5-073"},{"baslik":"Parlayan Her Şey Dikkat İster","ilk":"kh1-5-075"},{"baslik":"Asansörde Sessiz Temizlik","ilk":"kh1-5-080"},{"baslik":"Panel, Metal ve Bez Disiplini","ilk":"kh1-5-085"},{"baslik":"Mesai Bitti, Ofis Sırası Bende","ilk":"kh1-5-090"},{"baslik":"Toplantı, Fuaye ve Restoranda İş Bölümü","ilk":"kh1-5-096"},{"baslik":"Ter, Nem ve Bakteri","ilk":"kh1-5-102"},{"baslik":"İzsiz Cam, Parlak Ayna","ilk":"kh1-5-108"},{"baslik":"Genel Tuvalette Hijyen","ilk":"kh1-5-112"},{"baslik":"Tuvalette Kurallar","ilk":"kh1-5-117"},{"baslik":"Renk, Kimyasal, Güvenlik","ilk":"kh1-5-122"},{"baslik":"Görünmeyen Tehlike: Mikroplar","ilk":"kh1-5-125"},{"baslik":"Meydan Arabasında Neler Var?","ilk":"kh1-5-132"},{"baslik":"Uygulama Yaprağını Okumak","ilk":"kh1-5-137"},{"baslik":"Altı Uygulama, Altı Beceri","ilk":"kh1-5-141"},{"baslik":"Uygulama Bitti, İş Bitti mi?","ilk":"kh1-5-147"},{"baslik":"Otelin İlk Selamı Dışarıda Başlar","ilk":"kh1-5-151"},{"baslik":"Her Gün, Her Hafta, Her Sezon","ilk":"kh1-5-156"},{"baslik":"Haftalık Listenin Ayrıntıları","ilk":"kh1-5-159"},{"baslik":"Yılda Birkaç Kez Gelen İşler","ilk":"kh1-5-164"},{"baslik":"Resort mu, Şehir Oteli mi?","ilk":"kh1-5-166"},{"baslik":"Dışarıda Çalışırken Kendini Koru","ilk":"kh1-5-171"},{"baslik":"Hangi Köşeleri Temizliyoruz?","ilk":"kh1-5-185"},{"baslik":"Bahçede Bir Tur","ilk":"kh1-5-192"},{"baslik":"Yürüyüş Yolu ve Otopark","ilk":"kh1-5-199"},{"baslik":"Sahada Spor Var","ilk":"kh1-5-205"},{"baslik":"Plajın Sabahı","ilk":"kh1-5-210"},{"baslik":"Şezlongdan Şemsiyeye","ilk":"kh1-5-215"},{"baslik":"Kabinler ve Havlular","ilk":"kh1-5-220"},{"baslik":"Havuz Sadece Su Değil","ilk":"kh1-5-226"},{"baslik":"Havuza Girmeden Önce","ilk":"kh1-5-232"},{"baslik":"Güneşlenme ve Havlu Düzeni","ilk":"kh1-5-237"},{"baslik":"Araba Hazır, Yola Çıkıyoruz","ilk":"kh1-5-242"},{"baslik":"Arabanın Sepetinde Neler Var?","ilk":"kh1-5-247"},{"baslik":"Makineler Devreye Giriyor","ilk":"kh1-5-252"},{"baslik":"Merdiven, Kablo ve Dönüş Yolu","ilk":"kh1-5-256"},{"baslik":"Doğru Araç, Doğru Yer, Doğru Zaman","ilk":"kh1-5-261"},{"baslik":"Uygulama 7: Bahçe ve Otopark","ilk":"kh1-5-270"},{"baslik":"Uygulama 8: Plaj","ilk":"kh1-5-275"},{"baslik":"Uygulama 9: Havuz Çevresi","ilk":"kh1-5-281"},{"baslik":"İşi Bitirmek de İştir","ilk":"kh1-5-284"}],"kavramlar":[{"id":"kh1-5-001","konu":"5.1","terim":"Genel alan","ingilizce":"Public area","tanim":"Konuk odaları dışında kalan, konukların kullandığı alanlar ile personelin kullandığı ofis ve servis alanlarına verilen addır.","ornek":"Sabah 08.00’de bir otelde lobi, asansör, havuz başı ve personel soyunma odası genel alandır; dördüncü kattaki konuk odaları ise genel alan sayılmaz.","sektor":"Kat hizmetleri yalnız konuk odalarını değil genel alanları da temizler; bu yüzden bölümün işi odalardan çok daha geniştir.","iliskili":["kh1-5-002"],"kontrol":null,"gorsel":"t10h-lobi-oturma"},{"id":"kh1-5-002","konu":"5.1","terim":"Genel alan türleri","ingilizce":"Types of public areas","tanim":"Konukların ve personelin kullandığı koridor, tuvalet, havuz, idare ofisi, bölüm deposu, çamaşırhane, salon, garaj, bahçe, spor salonu ve asansör gibi alanların oluşturduğu listedir.","ornek":"Genel alanlar şefi Hülya sabah toplantısında listeye bakarak garajı, spor salonunu ve idare ofislerini günün iş planına yazar.","sektor":"Liste uzun olduğu için her alanın temizlik yöntemi, sıklığı ve sorumlusu çizelgede ayrı ayrı yazılır.","iliskili":["kh1-5-001","kh1-5-003"],"kontrol":null},{"id":"kh1-5-003","konu":"5.1","terim":"Genel alanlarda ilk izlenim","ingilizce":"First impression in public areas","tanim":"Konuğun otelle ilgili ilk kanaatini genel alanlarda gördüklerinden edinmesi nedeniyle bu alanların temizliğinin konuk odası kadar önemli sayılmasıdır.","ornek":"Akşam 19.00’da kapıdan giren bir aile, lobinin mermerinin parlaklığını görünce odasını görmeden otelden memnun kalır.","sektor":"Genel alanları yalnız odada kalan konuklar değil, kalıp kalmamaya henüz karar vermeye çalışan ziyaretçiler de kullanır; bu alanlardaki bir aksaklık konaklama kararını doğrudan etkiler.","iliskili":["kh1-5-002","kh1-5-004"],"kontrol":null,"gorsel":"g3-luks-otel-lobisi-cicek"},{"id":"kh1-5-004","konu":"5.1","terim":"Genel alanlarda anında müdahale","ingilizce":"Immediate response","tanim":"Kapısı kapatılıp temizlenemeyen alanlarda dökülme, kırılma ve kirlenmeye fark edildiği anda yapılan müdahaledir.","ornek":"Öğleden sonra 14.30’da lobide bir bardak meyve suyu devrilir; meydancı Kemal hemen uyarı levhasını koyar ve zemini siler.","sektor":"Genel alanlar insan trafiği nedeniyle daha çabuk kirlenir ve yıpranır; beklemek konuğun düşmesine ve otelin imajının zedelenmesine yol açar.","iliskili":["kh1-5-003","kh1-5-005"],"kontrol":null},{"id":"kh1-5-005","konu":"5.1","terim":"Sakin saatte temizlik, yoğun saatte kontrol","ingilizce":"Off-peak cleaning, peak-hour checks","tanim":"Genel alan temizliğinin konukların az olduğu saatlerde yapılması, yoğun saatlerde ise alanın sürekli kontrol edilmesi ilkesidir.","ornek":"Sabah 06.00’da lobiyi silen ekip, kahvaltı yoğunluğunda 09.00’da yalnızca girişi ve tuvaletleri kontrol eder.","sektor":"Böylece konuk rahatsız edilmez ve alan her saat sunuma hazır kalır.","iliskili":["kh1-5-004"],"kontrol":null},{"id":"kh1-5-006","konu":"5.1","terim":"Genel alan temizlik işlemleri","ingilizce":"Public area cleaning tasks","tanim":"Toz alma, leke çıkarma, süpürme, paspaslama, parlatma, yıkama, cilalama ve ovma gibi genel alanlarda yapılan işlemlerin bütünüdür.","ornek":"Lobi mermerinde toz alma ve paspaslama, halılı koridorda vakumlama ve leke çıkarma, metal tırabzanda parlatma yapılır.","sektor":"Hangi yüzeye hangi işlemin uygulanacağını bilmek, yanlış yöntemden doğan hasarı ve gereksiz maliyeti önler.","iliskili":["kh1-5-007"],"kontrol":null},{"id":"kh1-5-007","konu":"5.1","terim":"Ağır bakımın gece yapılması","ingilizce":"Night-time deep cleaning","tanim":"Yoğun kullanılan genel alanların cilalama ve yıkama gibi ağır bakım ve temizlik işlerinin konukların az bulunduğu gece saatlerinde yapılmasıdır.","ornek":"Gece 01.30’da lobi mermerini cilalayan ekip işi bitirir; sabah 07.00’de zemin parlak ve kuru hâlde konukları karşılar.","sektor":"Bu işler özel araç gereç ister; gündüz yapılsa hem gürültü hem kayma tehlikesi konuğu rahatsız ederdi.","iliskili":["kh1-5-006","kh1-5-008"],"kontrol":null},{"id":"kh1-5-008","konu":"5.1","terim":"Oturularak kullanılan zemin makinesi","ingilizce":"Ride-on scrubber dryer","tanim":"Geniş genel alan zeminlerini yıkamak ve cilalamak için üzerine oturularak sürülen temizlik makinesidir.","ornek":"Gece vardiyasında Zeynep, geniş balo salonunun zeminini zemin makinesiyle kısa sürede yıkar ve kurulayarak sabaha hazırlar.","sektor":"Büyük alanlarda zaman kazandırır; makineyi kullanan kişi eğitimli olmalı ve çalıştığı yerde konuk bulunup bulunmadığını kontrol etmelidir.","iliskili":["kh1-5-007"],"kontrol":null,"kitapDisi":true,"gorsel":"t15ae-oturmali-zemin-makinesi"},{"id":"kh1-5-009","konu":"5.1","terim":"Genel alanlar şefi","ingilizce":"Public area supervisor","tanim":"Konaklama işletmesinde genel alanların temizlik, bakım ve düzenlemesini planlayan ve organize eden personeldir.","ornek":"Sabah 07.30’da genel alanlar şefi Murat, hangi ekibin lobide, hangisinin spor salonunda çalışacağını çizelgeye yazar.","sektor":"Ekip onun planıyla yönlendirilir; plan iyi kurulursa her alan zamanında ve eksiksiz temizlenir. Meydan şefi olarak da anılır ve çalışmasını housekeeper’ın hazırladığı programa göre yürütür.","iliskili":["kh1-5-010"],"kontrol":null},{"id":"kh1-5-010","konu":"5.1","terim":"Günlük ve periyodik temizlik planı","ingilizce":"Daily and periodic cleaning plan","tanim":"Salon, restoran, lobi, merdiven ve koridor gibi konuk alanları ile soyunma odası, banyo ve tuvalet gibi personel alanlarının günlük ve periyodik temizlik işlerinin düzenlenmesidir.","ornek":"Şef Ayşe, koridor halılarının her gün vakumlanmasını, soyunma odası banyolarının ise haftalık derin temizliğe alınmasını plana yazar.","sektor":"Konuk ve personel alanlarının ikisi de şefin planındadır; çizelge, unutulan bir alanın kalmasını engeller.","iliskili":["kh1-5-009","kh1-5-011"],"kontrol":null},{"id":"kh1-5-011","konu":"5.1","terim":"Genel alan arızalarının bildirilmesi","ingilizce":"Reporting faults in public areas","tanim":"Koridor, lobi, salon gibi alanlardaki arıza, bakım ve onarım ihtiyaçlarının teknik servise iletilip giderilmesinin denetlenmesidir.","ornek":"Giriş kapısındaki otomatik cam kapı açılmıyorsa şef Ayşe teknik servise bildirir ve ertesi sabah onarıldığını kontrol eder.","sektor":"Bildirimle kalmak yetmez; arıza giderilene kadar takip etmek konuk güvenliği ve işletme imajı için gereklidir.","iliskili":["kh1-5-010","kh1-5-012"],"kontrol":null},{"id":"kh1-5-012","konu":"5.1","terim":"Malzeme ve araç gereç temini","ingilizce":"Supplies and equipment","tanim":"Genel alan ekibinin ihtiyaç duyduğu temizlik malzemelerinin belirlenip sağlanması ve ofislerin araç gereçlerinin temiz, düzenli saklanmasının sağlanmasıdır.","ornek":"Şef Murat ay sonunda cam silme sıvısı ve yedek paspasların azaldığını görür ve satın alma talebini hazırlar.","sektor":"Ders materyaline göre iş gücünden sonra kat hizmetlerinin en büyük maliyeti malzemedir; tükenmeden tedarik etmek hem maliyeti hem hizmet kalitesini korur.","iliskili":["kh1-5-011","kh1-5-013"],"kontrol":null},{"id":"kh1-5-013","konu":"5.1","terim":"Şefin raporlaması ve denetimi","ingilizce":"Reporting and supervision","tanim":"Yaptırdığı işleri yöneticisine raporlaması, ekibinin hijyen ile iş sağlığı ve güvenliği kurallarına uyup uymadığını denetlemesi ve personelin özlük haklarına ilişkin görüşlerini iletmesidir.","ornek":"Akşam 17.00’de şef, gün sonu raporunu housekeeper’a verir ve bir görevlinin eldiven kullanmadığını not edip uyarır.","sektor":"Denetim yapılmazsa hijyen ve güvenlik kuralları zamanla gevşer; rapor ise yöneticinin doğru karar vermesini sağlar.","iliskili":["kh1-5-012"],"kontrol":null},{"id":"kh1-5-014","konu":"5.1","terim":"Genel alan temizleme ve düzenleme görevlisi (meydancı)","ingilizce":"Public area attendant (houseman)","tanim":"Konaklama işletmesinde genel alanların temizliğini, düzenini ve bakımını yapan, genel alanlar şefine bağlı personeldir.","ornek":"Sabah 06.30’da vardiyaya gelen meydancı Kemal, şefinden aldığı programa göre önce lobi ve asansörlere gider.","sektor":"Sektörde public area attendant ya da houseman olarak da anılır; işletmeye göre farklı unvanlar kullanılabilir.","iliskili":["kh1-5-015"],"kontrol":null},{"id":"kh1-5-015","konu":"5.1","terim":"Meydancının sorumlu olduğu mekânlar","ingilizce":"Areas covered by the attendant","tanim":"Restoran, kafeterya, yüzme havuzu, spor salonu, bahçe, genel kullanıma açık tuvalet, salon ve ofis gibi alanlardır.","ornek":"Meydancı Kemal öğle arasında ofis koridorunu, öğleden sonra ise havuz çevresini kontrol eder.","sektor":"Görev alanı geniştir; bu nedenle günlük plan ve öncelik sırası iyi bilinmelidir.","iliskili":["kh1-5-014","kh1-5-016"],"kontrol":null},{"id":"kh1-5-016","konu":"5.1","terim":"İşe başlamadan kişisel hazırlık","ingilizce":"Personal preparation before work","tanim":"Meydancının üniformasını giymesi, kişisel bakım ve hijyen kurallarını uygulaması gibi işe başlamadan önce yaptığı hazırlıktır.","ornek":"Kemal vardiyaya başlamadan önce takılarını çıkarır, üniformasını giyer ve isimliğini takar.","sektor":"Konukla göz göze gelen bir görevlinin düzenli görünümü, işletmenin kalitesini de yansıtır.","iliskili":["kh1-5-015","kh1-5-017"],"kontrol":null,"gorsel":"t11e-el-yikama-eldivensiz"},{"id":"kh1-5-017","konu":"5.1","terim":"Yüzey bakımı: ahşap, mermer, metal","ingilizce":"Care of wood, marble and metal surfaces","tanim":"Meydancının genel alanlardaki ahşap ve mermer yüzeylerin tozunu alması ve cilalaması, metal aksamı parlatmasıdır.","ornek":"Öğleden önce Kemal, resepsiyon karşısındaki ahşap sehpayı siler, lobinin mermer zeminini kontrol eder ve asansör çevresindeki metal paneli parlatır.","sektor":"Her yüzeyin kendine özgü malzemesi vardır; yanlış ürün yüzeyi matlaştırabilir ya da çizebilir.","iliskili":["kh1-5-016","kh1-5-018"],"kontrol":null},{"id":"kh1-5-018","konu":"5.1","terim":"Çöp kovası ve kül tablası boşaltma","ingilizce":"Emptying bins and ashtrays","tanim":"Genel alanlardaki çöp kovalarının ve kül tablalarının düzenli olarak boşaltılıp temizlenmesidir.","ornek":"Kemal sabah ve akşam turunda lobideki çöp kovasını boşaltır, kül tablasını yıkayıp yerine koyar.","sektor":"Dolu bir çöp kovası görüntüyü ve kokuyu bozar; konuk bunu ilk fark ettiği şeyler arasında sayar.","iliskili":["kh1-5-017","kh1-5-019"],"kontrol":null},{"id":"kh1-5-019","konu":"5.1","terim":"Perde ve tül değişimi","ingilizce":"Replacing curtains and net curtains","tanim":"Genel alanlarda ve idari ofislerde kirlenen perde ve tüllerin çıkarılıp yerine temizlerinin takılması işlemidir.","ornek":"Toplantı odasının perdesi kahve lekesi alınca Kemal, yedek perdeyi takar ve kirli olanı yıkanmak üzere çamaşırhaneye gönderir.","sektor":"Yedekli çalışmak alanın uzun süre bakımsız görünmesini engeller.","iliskili":["kh1-5-018"],"kontrol":null},{"id":"kh1-5-020","konu":"5.1","terim":"Arıza ve hasarı amire bildirme","ingilizce":"Reporting faults and damage","tanim":"Meydancının gördüğü teknik arıza ve hasarı kendisi gidermeye çalışmadan amirine bildirmesidir.","ornek":"Koridordaki aplik yanıp sönüyorsa Kemal şefine haber verir, şef de teknik servise iletir.","sektor":"Teknik arızaya yetkisiz müdahale hem iş güvenliği riski hem de garanti sorunu doğurur.","iliskili":["kh1-5-021"],"kontrol":null},{"id":"kh1-5-021","konu":"5.1","terim":"Genel alanda unutulan eşya","ingilizce":"Lost property in public areas","tanim":"Konuklar tarafından genel alanlarda unutulan eşyanın amire haber verilerek ilgili birime teslim edilmesidir.","ornek":"Akşam 22.00’de lobide unutulmuş bir telefon bulan Kemal, bunu şefine bildirir ve ilgili birime teslim eder.","sektor":"Eşya bulunduğu gibi bırakılmaz, gizlice saklanmaz; kayıt ve teslim, konuğun güvenini korur.","iliskili":["kh1-5-020","kh1-5-022"],"kontrol":null,"gorsel":"t10a-kayip-esya-kutusu"},{"id":"kh1-5-022","konu":"5.1","terim":"Araç gereç temizliği ve istif","ingilizce":"Cleaning and storing equipment","tanim":"Kullanılan temizlik malzemelerinin ve araç gereçlerin işten sonra temizlenip bakımı yapılarak depoya ya da kendi yerine düzenli yerleştirilmesidir.","ornek":"Kemal iş bitiminde mopları yıkar, sileceği kurutur ve hepsini meydan ofisindeki yerine dizer; havuz çevresinde çalışan Murat da makineyi toplayıp temizlemeden ofise dönmez.","sektor":"Temiz ve düzenli saklanan malzeme uzun ömürlüdür ve ertesi gün eksiksiz bulunur; kirli bırakılan cihaz kısa sürede bozulur.","iliskili":["kh1-5-021","kh1-5-023","kh1-5-259"],"kontrol":null,"gorsel":"h3b-temizlik-dolabi"},{"id":"kh1-5-023","konu":"5.1","terim":"İyi bir meydancının görünümü ve tutumu","ingilizce":"Grooming and attitude of a good attendant","tanim":"Meydancının kıyafetlerinin ütülü, ayakkabılarının temiz olması, kişisel temizliğe özen göstermesi, amirlerine ve arkadaşlarına saygılı ve güler yüzlü davranmasıdır.","ornek":"Kemal sabah işe gelirken üniformasının ütülü olduğuna ve ayakkabılarının temiz olduğuna bakar, koridorda herkese selam verir.","sektor":"Görünüm ve tutum, konuğun otel hakkındaki izlenimini doğrudan etkiler; güler yüz ve selam da mesleğin parçasıdır.","iliskili":["kh1-5-022","kh1-5-024"],"kontrol":null},{"id":"kh1-5-024","konu":"5.1","terim":"Yedekli çalışma","ingilizce":"Working with a spare kit","tanim":"Meydancının yanında bir çöp poşeti, bir temizlik bezi ve bir eldiven taşıması, bölgesinde gereken tüm gereçleri ve yedek paspası bulundurmasıdır.","ornek":"Kemal koridorda yere dökülen içeceği fark edince cebindeki bezle hemen siler, ihtiyaç olursa bölgesindeki yedek paspası kullanır.","sektor":"Anında müdahalenin temeli hazırlıklı olmaktır; malzeme aramak süreyi uzatır.","iliskili":["kh1-5-023","kh1-5-025"],"kontrol":null},{"id":"kh1-5-025","konu":"5.1","terim":"Görevi sahiplenme ve mesai sonu teslim","ingilizce":"Taking ownership and end-of-shift handover","tanim":"Meydancının görev yerindeki sorunlara müdahale edip çözebildiklerini çözmesi, çözemediklerini şefine bildirmesi ve mesai sonunda ofisi düzenli, ekipmanı eksiksiz teslim etmesidir.","ornek":"Akşam 21.30’da Kemal ofisi toparlar, makineleri temizleyip depoya kaldırır ve arıza varsa şefine yazılı bildirir.","sektor":"Görevini sahiplenen personel, kendi başına çözemediği durumu geciktirmeden amirine bildiren personeldir.","iliskili":["kh1-5-024"],"kontrol":null},{"id":"kh1-5-026","konu":"5.1.1","terim":"İç mekân","ingilizce":"Interior area","tanim":"Konukların vakit geçirip yeme içme, dinlenme ve eğlence hizmeti alabildiği ya da toplantılarını yürütebildiği, kullanımı sürekli olduğu için kapatılamayan alanlardır.","ornek":"Lobi, restoran, SPA ve toplantı salonu bir otelin iç mekânlarıdır; gece 02.00’de bile lobide konuk bulunabilir.","sektor":"İç mekânların temizliği genel alan temizlik görevlileri tarafından yürütülür.","iliskili":["kh1-5-027"],"kontrol":null},{"id":"kh1-5-027","konu":"5.1.1","terim":"Konuk varken temizlik","ingilizce":"Cleaning in guests’ presence","tanim":"İç mekânlardaki temizlik ve bakımın, alan kapatılmadan konuklar kullanırken, onları rahatsız etmeden yapılmasıdır.","ornek":"Öğleden sonra 15.00’te lobide oturan konukların yanında Kemal sessizce ve seri biçimde toz alır, yürüyüş yolunu kapatmaz.","sektor":"Konuk çalışan görevliyi görür; bu yüzden hareketler sakin, araçlar toplu ve yöntem düzenli olmalıdır.","iliskili":["kh1-5-026","kh1-5-028"],"kontrol":null},{"id":"kh1-5-028","konu":"5.1.1","terim":"Detaylı temizliğin kullanım dışı zamanda yapılması","ingilizce":"Timing periodic cleaning","tanim":"Periyodik ya da daha detaylı temizlik işlemlerinin, alanın kullanımını etkilediği için konukların alanı kullanmadığı zamanlarda yapılmasıdır.","ornek":"Toplantı salonunun halı yıkaması, salonda etkinlik olmayan bir gece planlanır.","sektor":"Aksi hâlde alan kullanıma kapanır ya da konukların rahatı bozulur.","iliskili":["kh1-5-027","kh1-5-029"],"kontrol":null},{"id":"kh1-5-029","konu":"5.1.1","terim":"Uyarı levhaları","ingilizce":"Warning signs","tanim":"“Dikkat Kaygan Zemin”, “Servis Dışı”, “Kullanım Dışı” ve “Sizin İçin Temizleniyor” levhalarından oluşan, konuğu temizlik sırasındaki tehlikelere karşı uyaran işaretlerdir.","ornek":"Kemal ıslak paspasa başlamadan önce lobinin girişine “Dikkat Kaygan Zemin” levhasını koyar.","sektor":"Levha olmadan ıslak zemin bırakmak düşme kazasına ve tazminat riskine yol açar; levha konuğa bilgi verir ve onu korur.","iliskili":["kh1-5-028"],"kontrol":null,"gorsel":"t15ae-islak-zemin-levhasi"},{"id":"kh1-5-030","konu":"5.1.1","terim":"İşe uygun kıyafet ve kaymaz tabanlı ayakkabı","ingilizce":"Suitable clothing and non-slip shoes","tanim":"Genel alan görevlisinin işe uygun kıyafet giymesi ve ıslak zeminde kaymayan tabanlı ayakkabı kullanmasıdır.","ornek":"Kemal ıslak mermer zeminde paspaslarken kaymaz tabanlı ayakkabısını giyer.","sektor":"Kendi güvenliğini düşünmeyen görevli, hem kendini hem çevresindeki konukları tehlikeye atar; ıslak zeminde yanlış ayakkabı sık görülen kaza nedenlerindendir. Havuz çevresi ve plaj kabini gibi dış mekânın ıslak alanlarında da aynı kural geçerlidir.","iliskili":["kh1-5-031"],"kontrol":null,"gorsel":"os-kaymaz-is-ayakkabisi"},{"id":"kh1-5-031","konu":"5.1.1","terim":"Kimyasalla çalışırken eldiven ve maske","ingilizce":"Gloves and mask when handling chemicals","tanim":"Kimyasal temizleyicilerle çalışırken mutlaka eldiven ve maske takılmasıdır.","ornek":"Kemal tuvaletin lavabo armatürüne yapışmış kireç lekesine kireç çözücü sürerken eldiven ve maske takar.","sektor":"Cildi ve solunum yollarını korur; kural dış mekânda da aynıdır: ürün kullanılmadan önce eldiven ve maske takılır, sonradan değil.","iliskili":["kh1-5-030","kh1-5-032"],"kontrol":null,"gorsel":"t12s-maske-gozluk"},{"id":"kh1-5-032","konu":"5.1.1","terim":"Ağır eşya taşıma pozisyonu","ingilizce":"Safe lifting position","tanim":"Temizlik sırasında eşyaların yeri değiştirilirken uygun bir pozisyon alınarak omuriliğe fazla yük binmesinin önlenmesi, gerekirse ağır eşyaların yardım alarak taşınmasıdır.","ornek":"Zeynep ağır bir sehpayı çekmeden önce dizlerini bükerek durur ve yanındaki arkadaşından yardım ister.","sektor":"Yanlış kaldırma bel ve omurga sakatlığına yol açar; bu da iş kaybı ve maliyet demektir. Dış mekânda saksı ya da şezlong gibi ağır eşyalar için de aynı kural geçerlidir; yardım istemek zayıflık değil güvenlik kuralıdır.","iliskili":["kh1-5-031","kh1-5-033"],"kontrol":null},{"id":"kh1-5-033","konu":"5.1.1","terim":"Kablo ve priz güvenliği","ingilizce":"Cable and socket safety","tanim":"Elektrikli temizlik araçlarının kablo ve prizlerinin sık kontrol edilmesi, uzun kabloların ortalığa yayılmaması ve elektrik, su ve gaz bağlantılarına dikkat edilmesidir.","ornek":"Kemal vakum makinesinin kablosunu omzuna toplar; konuklar kabloya takılmaz.","sektor":"Kabloya takılan konuk düşer; su ve gaz bağlantılarına yakın alanlarda ayrıca dikkat edilir. Dış mekânda kablo yalnızca gerektiği kadar açılır, hortumla yıkama yapılırken aydınlatma prizlerine su tutulmaz.","iliskili":["kh1-5-032","kh1-5-034"],"kontrol":null,"gorsel":"t11e-uzatma-kablosu-prizi"},{"id":"kh1-5-034","konu":"5.1.1","terim":"Yüksekte çalışma güvenliği","ingilizce":"Safety when working at height","tanim":"Yüksek ya da ulaşılması zor yerlerin, camların temizliğinde ve perdelerin sökülüp asılmasında sağlam merdiven kullanılması ve çalışana destek olarak bir personelin yanında bulunmasıdır.","ornek":"Tavandaki bir aplik silinirken Zeynep sağlam bir merdivende çalışır, Kemal de merdiveni tutarak yanında bekler.","sektor":"Düşme, sık görülen iş kazalarındandır; refakat eden kişi gerektiğinde yardım da çağırabilir. Dış mekânda tabela ya da aydınlatma silerken de aynı önlem alınır.","iliskili":["kh1-5-033"],"kontrol":null},{"id":"kh1-5-035","konu":"5.1.1","terim":"Kimyasal ürün etiketi ve talimatı","ingilizce":"Product label and instructions","tanim":"Temizlik ürünlerinin içeriklerini ve kullanım talimatlarının görevli tarafından bilinmesi ve uyarılara uyulmasıdır.","ornek":"Kemal yeni bir cam sıvısını kullanmadan önce etiketi okur ve seyreltme talimatını uygular.","sektor":"Etiket okumak yanlış kullanımı ve zehirlenmeyi önler; tüm kimyasalların kullanım bilgisi görevlinin sorumluluğundadır. Dış mekânda yeni bir yüzey temizleyici kullanmadan önce de seyreltme ve uyarı bölümü okunur.","iliskili":["kh1-5-036"],"kontrol":null},{"id":"kh1-5-036","konu":"5.1.1","terim":"Kimyasalları karıştırmama","ingilizce":"Never mixing chemicals","tanim":"Belirli temizlik ürünlerinin bir arada kullanılmasının zehirli gaz oluşturması nedeniyle kimyasalların birbirine karıştırılmamasıdır.","ornek":"Zeynep tuvalette asidik temizleyiciyi ve çamaşır suyunu aynı yüzeye birlikte sıkmaz, aynı kovada da karıştırmaz; hangisini kullanacağını şefinin talimatına ve ürün etiketine göre seçer ve alanı havalandırır.","sektor":"Zehirli gaz solunum yollarına zarar verir; personel eğitimi ve havalandırma bu riski azaltır. Aynı kovada iki farklı ürün karıştırmak da yasaktır.","iliskili":["kh1-5-035","kh1-5-037"],"kontrol":null,"gorsel":"t12s-kimyasal-siseler"},{"id":"kh1-5-037","konu":"5.1.1","terim":"Planlı çalışma ve iş yükü","ingilizce":"Planned work and workload","tanim":"Temizlik işlerinin bir plana göre yapılması ve personele kapasitesinin üzerinde iş yükünün yüklenmemesidir.","ornek":"Şef Ayşe vardiyada tek kişilik lobi, asansör ve tuvalet işini üç kişiye böler.","sektor":"Aşırı yüklenen personel yorulur, acele eder ve kaza riski artar. Dış mekânda da plaj ve bahçe işleri aynı sabaha yığılmaz, gün içine bölünür.","iliskili":["kh1-5-036","kh1-5-038"],"kontrol":null},{"id":"kh1-5-038","konu":"5.1.1","terim":"İlk yardım bilgisi","ingilizce":"First-aid knowledge","tanim":"Personelin iç ve dış mekânlarda oluşabilecek kazalara karşı ilk yardım bilgisine sahip olmasıdır.","ornek":"Merdivende düşen bir çalışanın yanına giden Kemal yardım çağırır ve şefine haber verir; plajda kayıp düşüp dizini yaralayan bir konuk için görevli Elif de sakin kalıp yetkili kişiyi çağırır.","sektor":"Kazada ilk dakikalar önemlidir; ilk yardım bilen çalışan müdahale edebilir ya da doğru yardımı çağırabilir. Ciddi durumda 112 aranır ve amire haber verilir.","iliskili":["kh1-5-037"],"kontrol":null,"gorsel":"t11e-ilk-yardim-kutusu"},{"id":"kh1-5-039","konu":"5.1.2","terim":"Lobi","ingilizce":"Lobby","tanim":"Bir yapının kapısından girildiğinde görülen ilk boş alandır; konaklama işletmelerinde konuğun karşılandığı ve ilk izlenimin bırakıldığı geniş alandır.","ornek":"Gece yarısı otele giren bir konuğu önce göz alıcı lambalar ve parlak mermer zemin karşılar; bu yüzden lobi temizliğine özel önem verilir.","sektor":"Lobide genellikle kaliteli malzemeler ve oturma grupları bulunur; yirmi dört saat açık olması temizlik planını da etkiler.","iliskili":["kh1-5-040"],"kontrol":null,"gorsel":"h3b-lobi-resepsiyon"},{"id":"kh1-5-040","konu":"5.1.2","terim":"Lounge","ingilizce":"Lounge","tanim":"Lobide konukların dinlendiği ya da misafirleri ile görüştüğü, günümüzde bu adla da anılan salon alanıdır.","ornek":"Akşam 18.00’de iş görüşmesi yapan iki konuk lounge’daki koltuklarda oturur; kahve fincanları kalkınca görevli masaları siler.","sektor":"Salon düzeni konuğun bekleme deneyimini belirler; oturma gruplarının düzeni ve temizliği her an hazır olmalıdır.","iliskili":["kh1-5-039","kh1-5-041"],"kontrol":null,"gorsel":"f3b-luks-otel-oturma-salonu"},{"id":"kh1-5-041","konu":"5.1.2","terim":"Ambiyans","ingilizce":"Ambience","tanim":"Bir ortamın atmosferini, konuğa verdiği genel havayı anlatan sözcüktür.","ornek":"Lobide yumuşak ışık, temiz koku ve düzenli mobilya otelin ambiyansını oluşturur.","sektor":"Temizlik yalnız kiri gidermek değil, ortamın havasını da korumaktır.","iliskili":["kh1-5-040","kh1-5-042"],"kontrol":null},{"id":"kh1-5-289","konu":"5.1.2","terim":"Concierge","ingilizce":"Concierge","tanim":"Ön büroda konukların yönlendirilmesinden eşyalarının taşınmasına kadar çeşitli hizmetleri yerine getiren bölümdür.","ornek":"Sabah 08.00’de resepsiyonun yanındaki concierge masasında görevli, yeni gelen bir konuğa şehir haritası verip yakındaki restoranı anlatır; temizlik ekibi masanın çevresini konuk ayrıldıktan sonra siler.","sektor":"Concierge masası lobide konuklara hizmet verdiği için temizlik ekibi masanın çevresini konukları ve görevliyi rahatsız etmeden siler.","iliskili":["kh1-5-042","kh1-5-039"],"kontrol":null},{"id":"kh1-5-042","konu":"5.1.2","terim":"Lobide concierge ile iş birliği","ingilizce":"Cooperation with the concierge","tanim":"Konaklama işletmesinin organizasyon yapısına göre lobinin temizliğinde housekeeping ile concierge servisinin birlikte çalışabilmesidir.","ornek":"Sabah 06.30’da lobide bavul bekleyen konuk varsa concierge görevlisi bavulları kenara alır, temizlik ekibi o alanı sonra siler.","sektor":"Bu iş birliği işletmenin organizasyon yapısına göre değişir; bavul ve konuk trafiği olan alanda iki bölümün planı birbirini bozmamalıdır.","iliskili":["kh1-5-041","kh1-5-043"],"kontrol":null},{"id":"kh1-5-043","konu":"5.1.2","terim":"Lobi temizliğinin zamanı","ingilizce":"Timing of lobby cleaning","tanim":"Lobinin genel temizliğinin konukların henüz yoğun olarak bulunmadığı saatlerde ya da gece yapılmasıdır.","ornek":"Lobinin ana temizliği sabah 05.30’da, konuklar kahvaltıya inmeden önce tamamlanır.","sektor":"Gündüz yoğun saatlerde yalnız kontrol ve küçük müdahale yapılır; böylece konuk rahatsız edilmez.","iliskili":["kh1-5-042"],"kontrol":null},{"id":"kh1-5-044","konu":"5.1.2","terim":"Lobide toz alma","ingilizce":"Dusting in the lobby","tanim":"Lobideki yüzeylerin tozunun uygun kuru ya da nemli bezle her gün alınmasıdır.","ornek":"Sabah 06.00’da Kemal resepsiyon tezgâhını, sehpaları ve koltuk kenarlarını önce kuru bezle, gerekirse nemli bezle siler.","sektor":"Günlük yapılan temizlik işidir; toz biriken yüzey otelin bakımsız göründüğü ilk yerlerdendir.","iliskili":["kh1-5-045"],"kontrol":null,"gorsel":"t11e-tuy-toz-bezi"},{"id":"kh1-5-045","konu":"5.1.2","terim":"Yüzeye göre bez rengi","ingilizce":"Colour of cloth by surface","tanim":"Toz almada kullanılan bezlerin renklerinin yüzeye göre farklı seçilmesi ve her yüzey için belirlenen renk dışında bir bezin kullanılmamasıdır.","ornek":"Kemal, işletmenin belirlediği renk kuralına göre cam yüzeyler için ayrı, ahşap yüzeyler için ayrı renkte bez kullanır.","sektor":"Bez renkleri işletme prosedürüne göre belirlenir; kural karışırsa kir bir yüzeyden diğerine taşınır.","iliskili":["kh1-5-044","kh1-5-046"],"kontrol":null,"gorsel":"t12s-mikrofiber-bezler"},{"id":"kh1-5-046","konu":"5.1.2","terim":"Temizleyiciyle nemlendirerek toz alma","ingilizce":"Dampening before dusting","tanim":"Temizlenecek yüzeye temizleyici sıvı püskürtülerek yüzeyin nemlendirilmesi ve ardından toz alma işleminin yapılmasıdır.","ornek":"Zeynep tezgâha püskürtme şişesinden bir miktar temizleyici sıkar ve tozu bezle toplar.","sektor":"Nemli yüzey tozu havaya savurmaz, bezde toplar; konuğun solunumunu da rahatsız etmez.","iliskili":["kh1-5-045","kh1-5-047"],"kontrol":null},{"id":"kh1-5-047","konu":"5.1.2","terim":"Kirli bezlerin kendi poşetine konması","ingilizce":"Soiled cloths in their own bags","tanim":"Toz alma bittikten sonra her renk bezin genel alan temizlik arabasındaki kendi kirli poşetine konmasıdır.","ornek":"Kemal iş bitince kırmızı, mavi ve sarı bezleri üç ayrı poşete koyar.","sektor":"Bezlerin karışmaması çapraz bulaşmayı önler; çamaşırhane de bezleri renklerine göre ayrı yıkar.","iliskili":["kh1-5-046","kh1-5-048"],"kontrol":null},{"id":"kh1-5-048","konu":"5.1.2","terim":"Lobide detaylı toz alma","ingilizce":"Detailed dusting in the lobby","tanim":"Kapalı dolap, yangın dolabı ve radyatör araları gibi günlük yapılmayan yerlerin tozunun iş planına göre belirli aralıklarla alınmasıdır.","ornek":"Cuma gecesi iş planında yazdığı için Zeynep lobideki radyatör aralarını ve yangın dolabının üstünü siler.","sektor":"Günlük temizlikte atlanan ama zamanla toz biriken noktalar planlı temizlikle yakalanır.","iliskili":["kh1-5-047"],"kontrol":null},{"id":"kh1-5-049","konu":"5.1.2","terim":"Mermer ve taş yüzeylerin günlük temizliği","ingilizce":"Daily care of marble and stone floors","tanim":"Zemin olarak kullanılan mermer ve taşın her gün geniş mopla kuru paspaslanması, temizliğe kapıya en uzak köşeden başlanmasıdır.","ornek":"Gece 23.30’da Kemal lobinin zeminini geniş mopla kuru siler ve kapıya doğru ilerler.","sektor":"Günlük kuru paspas, zemini çizen kum ve tozu toplayarak cilanın ömrünü uzatır.","iliskili":["kh1-5-050"],"kontrol":null,"gorsel":"t10e-mermer-kakma"},{"id":"kh1-5-050","konu":"5.1.2","terim":"Islak paspasta uyarı levhası","ingilizce":"Warning sign for wet mopping","tanim":"Zemin ıslak silinirken “Dikkat Kaygan Zemin” levhasının işe başlamadan önce konukların görebileceği yere konmasıdır.","ornek":"Zeynep ıslak paspasa başlamadan önce levhayı giriş kapısının ortasına koyar.","sektor":"Levha olmadan başlamak, kayıp düşen konuğun sorumluluğunu işletmeye yükler.","iliskili":["kh1-5-049","kh1-5-051"],"kontrol":null},{"id":"kh1-5-051","konu":"5.1.2","terim":"S çizerek paspaslama","ingilizce":"Mopping in an S pattern","tanim":"Paspas işleminin yerdeki toz ve çöpleri sürekli önünde biriktirecek şekilde S harfi çizerek çıkış kapısına doğru yapılmasıdır.","ornek":"Kemal paspası ileri geri “S” çizerek sürer, çıkış kapısına doğru ilerler ve geride ayak izi bırakmaz.","sektor":"Önce zemin süpürülür ve kuru mopla tozdan arındırılır, sonra ıslak paspas yapılır; yöntem hem hızlı hem düzgün sonuç verir.","iliskili":["kh1-5-050"],"kontrol":null},{"id":"kh1-5-052","konu":"5.1.2","terim":"Cilalama uygulaması","ingilizce":"Floor polishing","tanim":"Taş ve mermer yüzeylerin daha parlak ve gösterişli görünmesi ve korunması için periyodik olarak yapılan uygulamadır.","ornek":"Cumartesi gecesi 01.00’de ekip lobi mermerini cila makinesiyle yeniler; sabah 07.00’de konuklar parlak zemini görür.","sektor":"Cila yüzeyi çiziklerden korur; periyodik uygulanmazsa zemin matlaşır.","iliskili":["kh1-5-053"],"kontrol":null},{"id":"kh1-5-053","konu":"5.1.2","terim":"Eski cilanın sökülmesi","ingilizce":"Stripping old polish","tanim":"Yeni cila sürülmeden önce zeminde bulunan eski cilanın cila sökücü kimyasalla hazırlanmış su ve siyah sert ped yardımıyla ovalanarak temizlenmesidir.","ornek":"Zeynep makineye siyah sert ped takar, sökücü katılmış suyla zemini ovalar ve zemin matlaşınca suyu vakumla çeker.","sektor":"Eski cila sökülmeden yeni cila sürülürse katlar birikir, zemin lekeli ve kirli görünür. Sökme bittikten sonra zemin temiz suyla durulanıp paspasla kurulanır, ped kimyasaldan arındırılır; yeni cila ancak bundan sonra sürülür.","iliskili":["kh1-5-052","kh1-5-054"],"kontrol":null},{"id":"kh1-5-054","konu":"5.1.2","terim":"Cilanın ince katlarla sürülmesi","ingilizce":"Applying polish in thin coats","tanim":"Kuru zemine kalın bir tabaka yerine ince katlar hâlinde cila sürülmesidir.","ornek":"Kemal temiz ve kuru zemine püskürtücüyle cilayı ince tabaka hâlinde sürer, kat kat ilerler.","sektor":"Ders materyaline göre mermer zeminlere en az üç kat cila uygulanır; ince katlar eşit kurur ve parlak sonuç verir.","iliskili":["kh1-5-053","kh1-5-055"],"kontrol":null},{"id":"kh1-5-055","konu":"5.1.2","terim":"Cila makinesi kontrolü ve bakımı","ingilizce":"Checking and maintaining the polishing machine","tanim":"Makinenin çalışıp çalışmadığının, kablo ve fişinde kaçak olup olmadığının çalışmadan önce kontrol edilmesi, iş sonunda kirli parçaların yıkanıp yerine konması ve arızanın şefe bildirilmesidir.","ornek":"Zeynep makineyi alana götürmeden önce fişini ve kablosunu kontrol eder, iş sonunda ped ve tankı yıkar.","sektor":"Kaçak akım iş kazasına yol açabilir; bakımlı makine hem güvenli hem uzun ömürlüdür.","iliskili":["kh1-5-054","kh1-5-056"],"kontrol":null},{"id":"kh1-5-056","konu":"5.1.2","terim":"Cilayı yedirme","ingilizce":"Buffing the polish in","tanim":"Cila sürüldükten sonra mermer yüzeyin cila makinesiyle ovalanması ve sürtünmeden oluşan ısıyla cilanın zemine yedirilmesidir.","ornek":"Kemal cila makinesini zemin üzerinde düzenli hareketlerle gezdirir; zemin parlayınca detaylı olarak mopla siler.","sektor":"Ders materyaline göre makine, cilayı kurutmayacak biçimde çalıştırılır; sürtünmeden oluşan ısı cilanın zemine yedirilmesini sağlar. İşlem sonunda zemin detaylı olarak mopla silinir.","iliskili":["kh1-5-055"],"kontrol":null},{"id":"kh1-5-057","konu":"5.1.2","terim":"Koridorlar ve merdivenler","ingilizce":"Corridors and stairs","tanim":"Konaklama işletmesinin tüm alanları arasında bağlantıyı sağlayan önemli geçiş yollarıdır.","ornek":"Bir konuk lobiden asansöre, oradan katlara giderken koridor ve merdivenlerden geçer; geçtiği her yer temiz değilse otel hakkındaki izlenimi bozulur.","sektor":"Temizlenmeyen koridorlar hem kötü görünür hem de temiz alanlara toz ve kir taşır.","iliskili":["kh1-5-058"],"kontrol":null,"gorsel":"h3b-merdiven-paspas"},{"id":"kh1-5-058","konu":"5.1.2","terim":"Taş ve mermer koridor temizliği","ingilizce":"Cleaning stone and marble corridors","tanim":"Taş ya da mermer yüzeyli koridor ve merdivenlerde kirlerin süpürülerek ya da elektrikli süpürgeyle tozdan arındırılması, ardından nemli mopla temizlenmesidir.","ornek":"Zeynep merdiven basamaklarını süpürür, sonra nemli mopla siler.","sektor":"Önce kuru, sonra nemli temizlik yöntemi çizilmeyi ve çamurlaşmayı önler; ihtiyaç olursa cilalama yapılır.","iliskili":["kh1-5-057","kh1-5-059"],"kontrol":null},{"id":"kh1-5-059","konu":"5.1.2","terim":"Tırabzan temizliği","ingilizce":"Cleaning handrails","tanim":"Tırabzanların yapıldıkları malzemeye göre metal ya da ahşap temizleyicisiyle silinmesi, gerektiğinde metal bölümlerin parlatılmasıdır.","ornek":"Kemal ahşap tırabzanı ahşap temizleyiciyle, metal korkuluğu ise metal parlatıcıyla temizler.","sektor":"Tırabzan konuğun eli sürekli temas ettiği yüzeydir; hem hijyen hem görünüm açısından önemlidir.","iliskili":["kh1-5-058","kh1-5-060"],"kontrol":null},{"id":"kh1-5-060","konu":"5.1.2","terim":"Halılı koridor ve merdiven","ingilizce":"Carpeted corridors and stairs","tanim":"Konuk odalarının bulunduğu katlar arasındaki merdiven ve koridorların ses yalıtımı sağlamak amacıyla halıyla kaplanmasıdır.","ornek":"Gece 22.00’den sonra odalara dönen konukların adımları, halı sayesinde diğer konukları rahatsız etmez.","sektor":"Halı sesi yutar ama kolay kirlenir; bu yüzden düzenli vakumlama ve yıkama gerekir.","iliskili":["kh1-5-059"],"kontrol":null,"gorsel":"h3b-mavi-halili-koridor"},{"id":"kh1-5-061","konu":"5.1.2","terim":"Halı ve akar","ingilizce":"Carpets and dust mites","tanim":"Halının tüylü bir tekstil ürünü olduğundan sürekli tozlanmaya ve astıma yol açabilen akar oluşumuna elverişli olmasıdır.","ornek":"Uzun süre vakumlanmayan halıda toz ve deri parçacıkları birikir; hassas bir konuk burada nefes almakta zorlanabilir.","sektor":"Akar, halı, koltuk ve yatak gibi yerlerde nemli ortamda yaşar; düzenli vakum ve yıkama bu riski azaltır.","iliskili":["kh1-5-062"],"kontrol":null,"gorsel":"t11e-ev-tozu-akarlari"},{"id":"kh1-5-062","konu":"5.1.2","terim":"Halının günlük vakumlanması","ingilizce":"Daily vacuuming of carpets","tanim":"Genel alanlardaki tüm halıların her gün elektrikli süpürgeyle vakumlanmasıdır.","ornek":"Sabah 06.30’da Kemal, kat koridorunun halısını konuklar kahvaltıya inmeden vakumlar.","sektor":"Günlük vakum toz ve akarı sürekli azaltır; yıkama ise kirlilik durumuna göre yapılır.","iliskili":["kh1-5-061","kh1-5-063"],"kontrol":null,"gorsel":"t10b-supurge-basligi"},{"id":"kh1-5-063","konu":"5.1.2","terim":"Yıkamadan önce hazırlık ve leke çıkarma","ingilizce":"Preparation and stain removal before washing","tanim":"Halı yıkamadan önce halının elektrikli süpürgeyle tozdan arındırılması ve varsa lekelerin leke çıkarıcı kimyasalla dıştan merkeze doğru uygulanarak çıkarılmasıdır.","ornek":"Zeynep halı yıkamadan önce halıyı vakumlar, kahve lekesine kimyasalı dış kenardan merkeze doğru sürer.","sektor":"Dıştan merkeze sürmek lekenin yayılmasını önler.","iliskili":["kh1-5-062","kh1-5-064"],"kontrol":null},{"id":"kh1-5-064","konu":"5.1.2","terim":"Yeni ürünü görünmeyen yerde deneme","ingilizce":"Spot-testing a new product","tanim":"Halı yıkamada ilk defa kullanılacak bir ürünün, önce halının görünmeyen bir bölümünde denenmesidir.","ornek":"Yeni şampuanı Kemal, mobilyanın arkasında kalan bir köşede dener.","sektor":"Ürün rengi solduruyorsa görünür alan zarar görmeden fark edilir.","iliskili":["kh1-5-063","kh1-5-065"],"kontrol":null},{"id":"kh1-5-065","konu":"5.1.2","terim":"Halı şampuanı ve yıkama makinesi","ingilizce":"Carpet shampoo and carpet cleaning machine","tanim":"Halıların halı yıkama makinesi ile halı şampuanı kullanılarak yıkanmasıdır.","ornek":"Zeynep makine tankına belirlenen ölçüde su ve şampuan koyar, halının dokuma yönüne dikkat ederek makineyi sürer.","sektor":"Şampuan köpürtülerek halının derinlerine kadar işlemesi sağlanır; böylece yalnız yüzey değil içerideki kir de çıkar.","iliskili":["kh1-5-064"],"kontrol":null},{"id":"kh1-5-066","konu":"5.1.2","terim":"Köpüğü ve fazla suyu vakumla çekme","ingilizce":"Extracting foam and excess water","tanim":"Halıya uygulanan şampuanlı köpüğün ve fazla suyun vakumla çekilmesi işlemidir.","ornek":"Kemal yıkamadan sonra köpüğü vakumlayarak halıyı hızlı kuruyacak hâle getirir.","sektor":"Halıda kalan nem koku yapar ve akar oluşumunu kolaylaştırır.","iliskili":["kh1-5-067"],"kontrol":null,"gorsel":"t12s-vakumlu-makine"},{"id":"kh1-5-067","konu":"5.1.2","terim":"Kurumadan eşya konmaması","ingilizce":"No furniture before the carpet is dry","tanim":"Yıkanan halı tam kurumadan üzerine eşya yerleştirilmemesi ve alanın kullanıma kapatılmasıdır.","ornek":"Gece yıkanan koridor halısı kuruyana dek şef Murat alanı levhayla kapatır.","sektor":"Islak halıya basmak lekeyi yayar, ayağa yapışan kiri halıya geri taşır.","iliskili":["kh1-5-066","kh1-5-068"],"kontrol":null},{"id":"kh1-5-068","konu":"5.1.2","terim":"Açık renkli halı","ingilizce":"Light-coloured carpet","tanim":"Koyu renkli halılara göre kiri daha çabuk gösterdiği ve ders materyaline göre daha zor temizlendiği için temizliğinde daha fazla özen gerektiren halı türüdür.","ornek":"Kemal, krem rengi lobi halısını koyu koridor halısından daha sık kontrol eder.","sektor":"Görünen leke konuk izlenimini bozar; açık renk daha dikkatli bakım ister.","iliskili":["kh1-5-067","kh1-5-069"],"kontrol":null},{"id":"kh1-5-069","konu":"5.1.2","terim":"Halı temizleme yöntemleri","ingilizce":"Carpet cleaning methods","tanim":"Halıların ıslak-kuru, kuru köpük ve sabunlu temizleme olmak üzere üç şekilde temizlenmesidir.","ornek":"Şef Murat kirliliğe göre halıyı bazen kuru köpük, bazen sabunlu yöntemle temizletir.","sektor":"Yöntem halının cinsine ve kirlilik durumuna göre seçilir; hepsinde önce vakumlama yapılır.","iliskili":["kh1-5-068"],"kontrol":null,"gorsel":"t11e-hali-yikama-koridor"},{"id":"kh1-5-070","konu":"5.1.2","terim":"Ahşap yüzey temizliği","ingilizce":"Cleaning wooden surfaces","tanim":"Suya karşı hassas, gözenekli, yumuşak ve çizilmeye elverişli ahşap yüzeylerin kuru mopla süpürülüp tozdan arındırılarak temizlenmesidir.","ornek":"Kemal ahşap parke zemini kuru mopla süpürür, lekeyi ahşap temizleyicisiyle siler.","sektor":"Ahşap suyla fazla temas ederse kabarır; bu yüzden temizlik nemli değil kuru ağırlıklıdır.","iliskili":["kh1-5-071"],"kontrol":null},{"id":"kh1-5-071","konu":"5.1.2","terim":"Ahşapta yasak malzemeler","ingilizce":"Prohibited materials on wooden surfaces","tanim":"Ahşap yüzeylerde sert fırça ve çalı süpürgesinin, asit bazlı ve petrol ürünü kimyasalların kullanılmamasıdır.","ornek":"Zeynep ahşap zemini çalı süpürgeyle değil yumuşak mopla süpürür.","sektor":"Sert fırça çizer, asit ve petrol ürünleri ahşabı bozar; hasarlı ahşap kolay onarılmaz.","iliskili":["kh1-5-070","kh1-5-072"],"kontrol":null},{"id":"kh1-5-072","konu":"5.1.2","terim":"Ahşap cilası ve parlatma","ingilizce":"Wood polish and buffing","tanim":"Cila ihtiyacı olan ahşap yüzeylere ahşap cilasının temiz bezle sürülüp dairesel hareketlerle yedirilmesi ve ardından cila makinesine beyaz yumuşak ped takılarak parlatılmasıdır.","ornek":"Kemal ahşap tezgâha cilayı dairesel hareketlerle yedirir, kuruyunca beyaz pedli makineyle parlatır.","sektor":"Beyaz yumuşak ped ahşabı çizmeden parlatır.","iliskili":["kh1-5-071","kh1-5-073"],"kontrol":null,"gorsel":"t10e-ahsap-masa-vazo"},{"id":"kh1-5-073","konu":"5.1.2","terim":"Kumaş kaplı mobilya bakımı","ingilizce":"Care of upholstered furniture","tanim":"Lobi ve koridorlardaki oturma gruplarının her gün elektrikli süpürgeyle vakumlanması ve kullanım yoğunluğuna göre yıkanmasıdır.","ornek":"Zeynep lobi koltuklarının oturma yüzeylerini ve kenarlarını her sabah süpürgeyle vakumlar.","sektor":"Kumaş koltuk toz ve akar biriktirdiği için günlük vakum şarttır.","iliskili":["kh1-5-072","kh1-5-074"],"kontrol":null,"gorsel":"t10e-kirmizi-koltuklar"},{"id":"kh1-5-074","konu":"5.1.2","terim":"Tül ve perde bakımı","ingilizce":"Care of nets and curtains","tanim":"Tül ve perdelerde günlük olarak kir, leke, hasar ve koku kontrolü yapılması ve kirlilik durumuna göre sökülerek yıkanmasıdır.","ornek":"Kemal sabah turunda toplantı odasının perdesindeki lekeyi fark eder ve şefine bildirir.","sektor":"Perde dekorasyonu tamamlar; bakımsız perde alanın tamamını bakımsız gösterir.","iliskili":["kh1-5-073"],"kontrol":null,"gorsel":"t10e-tul-perde"},{"id":"kh1-5-075","konu":"5.1.2","terim":"Metal alan temizliği","ingilizce":"Cleaning metal surfaces","tanim":"Asansör düğmeleri, tırabzanlar, sehpalar, koltuk ve masa ayakları ile kapı kolları gibi metal parçaların tozunun alınıp cilalanmasıdır.","ornek":"Kemal her sabah merdiven tırabzanının tozunu alır, ardından parlatır.","sektor":"Metal kiri ve yağı diğer yüzeylere göre daha fazla gösterir; toz alınmadan metal temizliği yapılmaz.","iliskili":["kh1-5-076"],"kontrol":null,"gorsel":"t10e-pirinc-tirabzan"},{"id":"kh1-5-076","konu":"5.1.2","terim":"Metal cinsine göre malzeme","ingilizce":"Choosing products by metal type","tanim":"Çelik, alüminyum, pirinç ve bakır gibi metal yüzeylere farklı temizleme malzemeleri kullanıldığı için metalin cinsinin bilinmesidir.","ornek":"Zeynep pirinç tırabzana çelik için kullandığı ürünü sürmez; önce metalin cinsine bakar.","sektor":"Yanlış ürün metali matlaştırır ya da çizer.","iliskili":["kh1-5-075","kh1-5-077"],"kontrol":null},{"id":"kh1-5-077","konu":"5.1.2","terim":"Tablo ve çerçeve temizliği","ingilizce":"Cleaning pictures and frames","tanim":"Tabloların tozunun günlük olarak nemli bezle alınması ve ahşap çerçevelerine ahşap bakımı ve cilası yapılmasıdır.","ornek":"Kemal lobideki tablonun tozunu nemli bezle alır, ahşap çerçeveyi cilalar.","sektor":"Tablo dekorasyonun parçasıdır; toz konuğun ilk bakışta fark ettiği bir detaydır.","iliskili":["kh1-5-076","kh1-5-078"],"kontrol":null,"gorsel":"t10e-tablolar-galeri"},{"id":"kh1-5-078","konu":"5.1.2","terim":"Aydınlatma ve aplik temizliği","ingilizce":"Cleaning light fittings and wall lights","tanim":"Aydınlatmaların tozunun günlük olarak nemli bezle alınması, ahşap ve metal kısımların cilalanması ve temizlikten önce elektriğin kesilmesidir.","ornek":"Zeynep apliği silmeden önce şefin onayıyla elektriği kapatır.","sektor":"Elektrik çarpmasına karşı önlem şarttır; aplik, duvar şamdanı ya da duvar lambası demektir.","iliskili":["kh1-5-077","kh1-5-079"],"kontrol":null,"gorsel":"t10e-aplik-lambasi"},{"id":"kh1-5-079","konu":"5.1.2","terim":"Antika ve vazoların temizliği","ingilizce":"Cleaning antiques and vases","tanim":"Lobide dekorasyonu tamamlayan aksesuar, antika, vazo ve antika görünümlü nesnelerin her gün tozunun alınması ve değerli eşyaların zarar görmemesi için dikkat edilmesidir.","ornek":"Kemal vazoyu iki elle tutarak kaldırır ve tabanını silip yerine koyar.","sektor":"Değerli ya da kırılgan nesnelerde acele etmek, kırılma ve değer kaybı demektir.","iliskili":["kh1-5-078"],"kontrol":null,"gorsel":"t10e-porselen-vazolar"},{"id":"kh1-5-080","konu":"5.1.2","terim":"Konuk ve personel asansörü","ingilizce":"Guest lift and service lift","tanim":"Konukların kullandığı gösterişli konuk asansörü ile personelin hizmet için kullandığı personel asansörü olmak üzere iki türden oluşan asansör ayrımıdır.","ornek":"Konuk asansörü cam ve parlak panellerle, personel asansörü daha sade tasarlanır.","sektor":"Konuk asansörleri gösterişli olduğu için temizliği daha sık ve daha titiz yapılır; iç duvarlar paslanmaz çelik, alüminyum, cam veya aynayla kaplanır, tabanlar parke, halı, granit ya da mermer olabilir. Açık koridorlu otellerde konuk asansörleri lobiyi gören panoramik cam yapıda da tasarlanır.","iliskili":["kh1-5-081"],"kontrol":null,"gorsel":"t10e-asansor-kabini"},{"id":"kh1-5-081","konu":"5.1.2","terim":"Asansör temizliğinin sıklığı ve yeri","ingilizce":"Frequency and place of lift cleaning","tanim":"Temizlik sıklığının kullanım yoğunluğuna göre değişmesi ve temizliğin odaların bulunduğu katlarda değil lobide yapılmasından oluşan uygulamadır.","ornek":"Sabah 10.00’da otel doluyken Kemal, asansörü odaların bulunduğu katta değil lobi katında bekletip temizler.","sektor":"Ders materyaline göre otel doluyken asansörler saat başı temizlenir; lobide temizlik, katlardaki konukların rahatsız edilmemesini sağlar.","iliskili":["kh1-5-080","kh1-5-082"],"kontrol":null,"gorsel":"t10g-asansor-holu"},{"id":"kh1-5-082","konu":"5.1.2","terim":"Asansörleri sırayla temizleme","ingilizce":"Cleaning lifts one at a time","tanim":"Birden fazla asansör varsa tümünü aynı anda kullanım dışı bırakmayıp sırayla temizlemektir.","ornek":"Dolu bir cumartesi öğleden sonra 14.00’te dört asansörden ikisi temizlenirken diğer ikisi konuklara açık kalır; iş bitince sıra diğerlerine geçer.","sektor":"Konuklar bavullarıyla beklemek zorunda kalmaz.","iliskili":["kh1-5-081","kh1-5-083"],"kontrol":null},{"id":"kh1-5-083","konu":"5.1.2","terim":"Yukarıdan aşağıya silme","ingilizce":"Wiping from top to bottom","tanim":"Asansör temizliğine mümkün olduğunca yukarıdan ya da tavandan başlanıp aşağıya doğru devam edilmesidir.","ornek":"Zeynep önce aynanın üst kenarını, sonra panel ve zemini temizler.","sektor":"Yukarıdan akan kir aşağıya düşer; tersi sırada temizlenmiş yer yeniden kirlenir.","iliskili":["kh1-5-082","kh1-5-084"],"kontrol":null},{"id":"kh1-5-084","konu":"5.1.2","terim":"Asansör zemini ve rayları","ingilizce":"Lift floor and door tracks","tanim":"Kabin zemininin tozunun elektrikli süpürgeyle alınmasını ve kapı raylarının vakumlanıp havlu bezle silinmesini içeren bakımdır.","ornek":"Kemal ray aralarındaki tozu süpürgenin dar ucuyla çeker, sonra bezle siler.","sektor":"Rayda biriken kir kapının tıkanmasına yol açabilir.","iliskili":["kh1-5-083"],"kontrol":null},{"id":"kh1-5-085","konu":"5.1.2","terim":"Asansör kontrol paneli","ingilizce":"Lift control panel","tanim":"Konukların çoğunun dokunduğu, ancak elektrik akımı ve elektronik kontrol kartları bulunduğu için fazla ıslak bezle silinmeyen paneldir.","ornek":"Zeynep paneli hafif nemli bezle siler; su damlatmaz.","sektor":"Ders materyaline göre hemen hemen tüm konuklar panele dokunur; sürekli dokunulduğu için hijyen önemlidir, ama aşırı nem arızaya yol açar.","iliskili":["kh1-5-086"],"kontrol":null,"gorsel":"t10e-asansor-dugmeleri"},{"id":"kh1-5-086","konu":"5.1.2","terim":"Metal parlatıcının kullanımı","ingilizce":"Using metal polish","tanim":"Parlatıcının metale doğrudan değil, havlu beze uygulanarak kullanılmasıdır.","ornek":"Kemal önce havlu beze parlatıcı sıkar, sonra metal yüzeyi siler.","sektor":"Parlatıcıyı doğrudan metale sıkmak yüzeye zarar verebilir ve durulama için fazla su kullanılmasına yol açar.","iliskili":["kh1-5-085","kh1-5-087"],"kontrol":null},{"id":"kh1-5-087","konu":"5.1.2","terim":"Parlatmada iki bez ve yön","ingilizce":"Two cloths and wiping direction","tanim":"Metal parlatma uygulamasında iki adet havlu bez kullanılması, bezin yukarıdan aşağıya doğru çekilmesi, daire çizilmemesi ve diğer kuru bezle yüzeyin yine yukarıdan aşağıya kurulanmasıdır.","ornek":"Zeynep ilk bezle parlatıcıyı yukarıdan aşağıya yayar, ikinci kuru bezle izleri alır.","sektor":"Dairesel hareket iz bırakır; kuru bezle kurulamak parlatıcının yüzeyde kalmamasını sağlar.","iliskili":["kh1-5-086","kh1-5-088"],"kontrol":null},{"id":"kh1-5-088","konu":"5.1.2","terim":"Asansör bezlerinin ayrılması","ingilizce":"Keeping lift cloths separate","tanim":"Temizlikte kullanılan bezlerin başka bir asansörde ya da yüzeyde kullanılmaması, iş bitince kirli torbaya konması ve mesai sonunda çamaşırhaneye teslim edilmesidir.","ornek":"Kemal birinci asansörde kullandığı bezi ikinci asansörde kullanmaz.","sektor":"Aynı bezin iki yerde kullanılması kir ve mikrop taşır.","iliskili":["kh1-5-087","kh1-5-089"],"kontrol":null},{"id":"kh1-5-089","konu":"5.1.2","terim":"Asansörün gece detaylı temizliği","ingilizce":"Night-time detailed lift cleaning","tanim":"Asansörlerin detaylı temizliğinin konukların yoğun kullanmadığı gece vardiyasında yapılmasıdır.","ornek":"Gece 02.00’de metal iç duvarlar, iç ve dış kapı yüzeyleri temizlenip parlatılır.","sektor":"Gündüz yapılan genel temizliğe ek olarak gece detaylı temizlik yapılır.","iliskili":["kh1-5-088"],"kontrol":null},{"id":"kh1-5-090","konu":"5.1.2","terim":"Büro ve çalışma ofisleri","ingilizce":"Offices and work areas","tanim":"Genel müdürün, departman yöneticilerinin ve resepsiyon, rezervasyon, satış, muhasebe, satın alma gibi bölümlerde çalışan personelin kullandığı çalışma alanlarıdır.","ornek":"Rezervasyon, satış ve muhasebe ofisleri ile genel müdür odası otelin büro ve çalışma ofisleridir; bu odaların temizliği çalışanlar gittikten sonra yapılır.","sektor":"İdari ofisler genellikle ofis çalışanlarının mesai saatinden sonra akşam vardiyası tarafından temizlenir.","iliskili":["kh1-5-091"],"kontrol":null,"gorsel":"t11e-ofis-masasi"},{"id":"kh1-5-091","konu":"5.1.2","terim":"Ofis temizliğinin saati","ingilizce":"Timing of office cleaning","tanim":"İdari ofislerin, aksi belirtilmedikçe ofis çalışanlarının mesaisi bittikten sonra akşam vardiyası tarafından temizlenmesidir.","ornek":"Akşam 21.30’dan sonra Zeynep, satış ofisini temizler.","sektor":"Ders materyaline göre idari ofisler 21.30’dan sonra temizlenir; çalışanları rahatsız etmemek için mesai saatinden sonra yapılır.","iliskili":["kh1-5-090","kh1-5-092"],"kontrol":null},{"id":"kh1-5-092","konu":"5.1.2","terim":"Masadaki evraklara dokunmama","ingilizce":"Not disturbing papers on desks","tanim":"Ofis temizliği sırasında masadaki evrakların kesinlikle karıştırılmamasıdır.","ornek":"Kemal masadaki evrak dosyalarının yerini değiştirmeden çevresini siler.","sektor":"Evrak ofis çalışanının işine aittir; karıştırmak güven kaybına yol açar.","iliskili":["kh1-5-091","kh1-5-093"],"kontrol":null},{"id":"kh1-5-093","konu":"5.1.2","terim":"Ofiste toz alma yönü","ingilizce":"Direction of dusting in offices","tanim":"Toz alma işleminin kapıdan başlayarak saat yönünde yukarıdan aşağıya doğru yapılmasıdır.","ornek":"Zeynep ofise kapıdan girer, duvardaki çerçeveden başlar, sonra mobilyalara geçer.","sektor":"Düzenli bir yön izlemek hiçbir yerin atlanmamasını sağlar. Ofiste ayrıca vazoların suyu değiştirilir; bilgisayar klavyeleri, masa ve sandalye ayakları ve masa altı komodinin tozu alınır. Zeminin ve mobilyanın cinsine göre parkeye mobilya cilası uygulanır.","iliskili":["kh1-5-092","kh1-5-094"],"kontrol":null},{"id":"kh1-5-094","konu":"5.1.2","terim":"Ofis çıkış kontrolü","ingilizce":"Office exit check","tanim":"Temizlik bittikten sonra pencerelerin, ısıtıcı, fan ve klimanın kapatılması, yanan lambaların söndürülmesi, araç gerecin unutulup unutulmadığına bakılması, oda parfümü sıkılması ve kapının kilitlenmesinden oluşan kontroldür.","ornek":"Kemal ofisten çıkarken kapıya sırtını döner ve son kez göz taramasıyla içeriyi kontrol eder, ışıkları kapatır.","sektor":"Açık unutulan cihaz yangın ve enerji kaybına yol açabilir.","iliskili":["kh1-5-093","kh1-5-095"],"kontrol":null},{"id":"kh1-5-095","konu":"5.1.2","terim":"Ofis zemini ve havalandırma","ingilizce":"Office floors and ventilation","tanim":"Ofiste temizlik sırasında kapı ve pencerelerin açık bırakılarak havalandırılması, zeminlerin süpürülmesinde çalı süpürgesi ve sert fırçanın kullanılmamasıdır.","ornek":"Zeynep ofisin penceresini açar, halıyı elektrikli süpürgeyle temizler.","sektor":"Çalı süpürgesi ve sert fırça parke ve cilalı yüzeyleri çizer.","iliskili":["kh1-5-094"],"kontrol":null},{"id":"kh1-5-096","konu":"5.1.2","terim":"Toplantı odası ve toplantı salonu","ingilizce":"Meeting room and meeting hall","tanim":"İş amacıyla insanların bilgi alışverişi için bir araya geldiği küçük alan toplantı odası, daha kalabalık toplantılar için kullanılan ve kapasitesi daha yüksek alan toplantı salonudur.","ornek":"Dört kişilik bir yönetim toplantısı odada, elli kişilik bir tanıtım toplantısı salonda yapılır.","sektor":"Ders materyaline göre toplantı odaları genellikle 8-10 kişilik kapasitelidir; masa ve sandalyelerle donatılır.","iliskili":["kh1-5-097"],"kontrol":null,"gorsel":"h3b-toplanti-masasi"},{"id":"kh1-5-097","konu":"5.1.2","terim":"Seminer salonu ve kongre merkezi","ingilizce":"Seminar hall and congress centre","tanim":"Yüzlerce kişinin iş amacıyla bir araya gelebildiği, yalnızca sandalye ya da sinema tipi koltuklarla donatılmış alanlardır.","ornek":"Kapadokya’daki bir kongre merkezinde üç yüz kişilik oturma düzeni kurulur.","sektor":"Bu alanlar işletmenin gelir getiren önemli bölümleri arasındadır; temizliği hem salon hem fuaye kalitesini yansıtır.","iliskili":["kh1-5-096","kh1-5-098"],"kontrol":null,"gorsel":"t15af-kongre-salonu"},{"id":"kh1-5-098","konu":"5.1.2","terim":"Fuaye ve coffee break","ingilizce":"Foyer and coffee break","tanim":"Toplantı alanlarının hemen önünde bulunan ve toplantı aralarında aperatif yiyecek ve içecek servisinin (coffee break) yapıldığı ara alandır.","ornek":"Toplantı arası saat 15.30’da fuayede kahve ve kurabiye servisi yapılır.","sektor":"Fuaye, katılımcıların toplantı arasında dinlendiği alandır; servisin hazırlanması ve toplanması yiyecek içecek ekibine aittir, alanın temizliği ise genel alan ekibine.","iliskili":["kh1-5-097","kh1-5-099"],"kontrol":null},{"id":"kh1-5-099","konu":"5.1.2","terim":"Toplantı alanında iş bölümü","ingilizce":"Division of work in meeting areas","tanim":"Düzen ve servis işlerinin yiyecek içecek personeline, toplantı öncesi ve sonrası temizlik ile periyodik işlerin genel alan personeline ait olması düzenidir.","ornek":"Servis ekibi bardakları toplar; genel alan görevlisi toplantı sonrasında halıyı süpürür.","sektor":"Net iş bölümü hem eksik hem tekrar iş yapılmasını önler.","iliskili":["kh1-5-098","kh1-5-100"],"kontrol":null},{"id":"kh1-5-100","konu":"5.1.2","terim":"Toplantı salonu temizlik işleri","ingilizce":"Cleaning tasks for meeting halls","tanim":"Halıların elektrikli süpürgeyle süpürülmesi, mobilyaların tozunun alınması, camların silinmesi ve fuaye alanının temizlenmesinden oluşan işlerdir.","ornek":"Toplantı sonrası Kemal halıyı süpürür, masaların tozunu alır, camları siler ve fuayeyi toparlar.","sektor":"Toplantı sonrası temizlik bir sonraki toplantıya hazırlık anlamına gelir.","iliskili":["kh1-5-099"],"kontrol":null},{"id":"kh1-5-101","konu":"5.1.2","terim":"Restoran ve kafeterya temizliğinde iş bölümü","ingilizce":"Division of cleaning in food and beverage areas","tanim":"Mutfak bölümünün temizliğinin mutfak personeli, restoran bölümünün temizliğinin servis personeli tarafından, perde ve cam silme gibi işlerin ise genel alan temizlik personeli tarafından yapılmasıdır.","ornek":"Restoranda masaları servis personeli siler, camları ise Kemal temizler.","sektor":"Ders materyaline göre konaklama işletmelerinde genellikle konaklama gelirinden sonra ikinci büyük gelir yiyecek içecek alanlarından elde edilir; temizliği bu yüzden özen ister.","iliskili":["kh1-5-102"],"kontrol":null,"gorsel":"t11e-restoran-bos-masalar"},{"id":"kh1-5-102","konu":"5.1.2","terim":"Fitness","ingilizce":"Fitness centre","tanim":"Konaklama işletmelerinde konukların ve üyelerin spor ihtiyacını karşılayan, sağlıklı yaşam için egzersiz yapılan alandır.","ornek":"Sabah 07.00’de spor yapmaya gelen konuklar fitness salonundaki aletleri kullanır.","sektor":"Spor aletlerinin temizliği ve hijyeni alanın kendi personeline aittir; zemin, cam ve ayna ise genel alan ekibinin işidir.","iliskili":["kh1-5-101","kh1-5-103"],"kontrol":null,"gorsel":"h1a-kosu-bantlari"},{"id":"kh1-5-103","konu":"5.1.2","terim":"SPA","ingilizce":"Spa","tanim":"Konukların ruhsal ve bedensel olarak rahatlaması için konaklama işletmelerinde hamam, sauna, buhar odası, sıcak ve soğuk su havuzu ile masaj odalarının bulunduğu alandır.","ornek":"Akşam üstü SPA’ya gelen konuk sauna ve masaj odalarını kullanır.","sektor":"SPA’nın genel temizliği alanın kendi personeli tarafından yapılır; giyinme odaları ve zemin gibi yerleri genel alan personeli temizler.","iliskili":["kh1-5-102","kh1-5-104"],"kontrol":null,"gorsel":"h5a-termal-spa"},{"id":"kh1-5-104","konu":"5.1.2","terim":"Sanitas Per Aquam","ingilizce":"Sanitas Per Aquam","tanim":"SPA sözcüğünün yaygın olarak anlatılan, Latince “sudan gelen sağlık” anlamındaki açılımıdır.","ornek":"Kemal, SPA girişindeki bilgi panosunda “sudan gelen sağlık” yazısını görür.","sektor":"Romalılardan bugüne uygulanan su terapilerine verilen ad olarak anlatılır; sıcak ve soğuk su akıtma, duşlama, püskürtme gibi yöntemlerle ruhsal ve bedensel rahatlama sağlanır. Sözcüğün kökeni konusunda başka görüşler de vardır.","iliskili":["kh1-5-103","kh1-5-105"],"kontrol":null,"gorsel":"t11l-spa-kapali-havuz"},{"id":"kh1-5-105","konu":"5.1.2","terim":"Spor alanında hijyen","ingilizce":"Hygiene in sports areas","tanim":"Nem, sıcaklık ve havaya bağlı olarak bakteri, mantar ve virüslerin kolayca üreyebildiği spor salonlarında, diğer alanlardan daha özenli yürütülmesi gereken hijyendir.","ornek":"Fitness salonunda aletlere birçok konuk dokunur; temizlik yetersiz kalırsa hastalık riski artar.","sektor":"Spor yapan kişi bu ortamda birçok yere temas eder; temizlik yeterince iyi yapılmazsa konuk sağlığı tehlikeye girer.","iliskili":["kh1-5-104","kh1-5-106"],"kontrol":null},{"id":"kh1-5-106","konu":"5.1.2","terim":"Spor ve SPA’da iş bölümü","ingilizce":"Division of work in sports and spa areas","tanim":"Aletlerin temizlik, bakım ve hijyeninin alanın kendi personeline; zemin, cam, ayna, giyinme odası ve dolapların temizliğinin genel alan personeline ait olması düzenidir.","ornek":"Kemal fitness salonunda aletlere dokunmaz, giyinme odası dolaplarını ve aynaları temizler.","sektor":"Her görevlinin alanı net bilinirse iş atlanmaz ve tekrar edilmez.","iliskili":["kh1-5-105","kh1-5-107"],"kontrol":null},{"id":"kh1-5-107","konu":"5.1.2","terim":"SPA ve spor alanı temizlik kuralları","ingilizce":"Cleaning rules for spa and sports areas","tanim":"Islak paspas öncesi levha konulması, giyinme odaları ile duş ve tuvaletlerin sık temizlenip dezenfekte edilmesi, zemindeki fazla suyun çekilmesi ve eksik havlu, peştamal, sabunun tamamlanması gibi uygulamalardır.","ornek":"Zeynep duş alanını temizlerken levhayı koyar, zemindeki suyu çeker ve eksik sabun, havlu ve peştamalları tamamlar.","sektor":"Kapalı olunan saatlerde yukarıdan aşağıya detaylı temizlik yapılır; kimyasalla çalışırken iş sağlığı ve güvenliği kurallarına uyulur.","iliskili":["kh1-5-106"],"kontrol":null},{"id":"kh1-5-108","konu":"5.1.2","terim":"Cam temizliği","ingilizce":"Glass cleaning","tanim":"İşletme içindeki ve ulaşılabilir yerlerdeki camların genel alan temizlik personeli tarafından silinerek her zaman temiz tutulmasıdır.","ornek":"Kemal lobinin giriş camını sabah ve akşam kontrol eder.","sektor":"Cam kir ve yağı çok belli ettiği için sürekli temiz olması gerekir.","iliskili":["kh1-5-109"],"kontrol":null,"gorsel":"t10b-balkon-cami"},{"id":"kh1-5-109","konu":"5.1.2","terim":"Dış cephe cam temizliği","ingilizce":"External façade glass cleaning","tanim":"Bina üstünden sarkıtılan asansör ya da bina dışına getirilen vinç yardımıyla endüstriyel dağcılık eğitimi almış personelin yaptığı, sık yapılmayan ve periyodik plana giren cam temizliğidir.","ornek":"Sezon açılışından önce otelin yüksek cephe camlarını işletme dışından hizmet alınan uzman bir firma güvenlik önlemleriyle temizler.","sektor":"Modern binalarda camlar havalandırma sistemleri sayesinde açılıp kapanmayabilir, bu yüzden dışarıdan temizlik gerekir. İşletmede bu nitelikte personel yoksa dış hizmet alınır; kullanılan ürünler camda kir tutmayacak şekilde geliştirilmiş özel temizlik ürünleridir.","iliskili":["kh1-5-108","kh1-5-110","kh1-5-158"],"kontrol":null,"gorsel":"t15af-cephe-cam-platform"},{"id":"kh1-5-110","konu":"5.1.2","terim":"Cam silme tekniği","ingilizce":"Window-cleaning technique","tanim":"Cam yüzeyine temizlik sıvısı sıkıldıktan sonra lastikli cam silme aletiyle “S” şeklinde boşluk bırakmadan dışarıdan içeriye ve yukarıdan aşağıya doğru silme işlemidir.","ornek":"Zeynep camın üst köşesinden başlar, “S” çizerek aşağı iner, çerçeveyi de camla birlikte siler, sonra iplik bırakmayan bezle kurular.","sektor":"Çerçeveler camlarla birlikte yıkanır ve silinir; kullanılan bez ve aletler sıkça yıkanır.","iliskili":["kh1-5-109","kh1-5-111"],"kontrol":null,"gorsel":"t15af-cam-cekcek"},{"id":"kh1-5-111","konu":"5.1.2","terim":"Ayna temizliği","ingilizce":"Mirror cleaning","tanim":"Temizlik yöntemi camlarla aynı olan, ancak arka yüzeyi duvara sabitlendiği için temizliği yalnız ön yüze uygulanan aynaların silinmesidir.","ornek":"Kemal lobideki büyük aynanın ön yüzünü cam silme sıvısıyla temizler.","sektor":"Dekorasyon amaçlı aynalar doğru yerleştirildiğinde alanı geniş ve ferah gösterir; leke ve iz bırakılmadan silinmelidir.","iliskili":["kh1-5-110"],"kontrol":null,"gorsel":"t11b-ayna-aplik"},{"id":"kh1-5-112","konu":"5.1.2","terim":"Genel tuvalet hijyeni","ingilizce":"Hygiene in public toilets","tanim":"Bakteri oluşumuna elverişli oldukları için tuvaletlerde hijyen kurallarına diğer alanlardan daha fazla özen gösterilmesidir.","ornek":"Akşam yemeği saatinde yoğun kullanılan lobideki tuvaleti Zeynep sık sık kontrol eder.","sektor":"Tuvalet teçhizatı seramikten yapılır; seramik kolay temizlenir ve kir tutmaz.","iliskili":["kh1-5-113"],"kontrol":null,"gorsel":"t15af-genel-tuvalet"},{"id":"kh1-5-113","konu":"5.1.2","terim":"Alaturka tuvalet","ingilizce":"Squat toilet","tanim":"Zemine yerleştirilmiş, üzerine çömelerek kullanılan ve taharet musluğu yan duvarda bulunan tuvalet türüdür.","ornek":"Havalimanı yakınındaki bir otelin genel tuvaletinde kabinlerden biri alaturkadır; Zeynep bu kabinde zeminde biriken suya ve yan duvardaki taharet musluğuna ayrıca bakar.","sektor":"Ders materyaline göre alaturka tuvalet Türkiye, Hindistan, Japonya, Çin ve İran gibi ülkelerde yaygındır ve vücutla temas olmadığı için hijyenik kabul edilir. Türünü bilmek temizlik yöntemini ve malzemesini seçmeyi kolaylaştırır.","iliskili":["kh1-5-112","kh1-5-114"],"kontrol":null,"gorsel":"t10e-alaturka-tuvalet"},{"id":"kh1-5-114","konu":"5.1.2","terim":"Alafranga tuvalet","ingilizce":"Western-style toilet","tanim":"Batı ülkelerinde yaygın olarak kullanılan, oturularak kullanılan tuvalet türüdür.","ornek":"Dizinden rahatsız yaşlı bir konuk lobi katındaki tuvalette alafranga kabini tercih eder; Zeynep bu kabinin klozet kapağını ve çevresini ayrıca siler.","sektor":"Ders materyaline göre alafranga tuvaletin taharet musluğu tuvaletin içinde yer alır, alaturkada ise yan duvardadır; uygulamada taharet donanımının olup olmadığı tesise göre değişir. Hastalık ya da ameliyat sonrası, yaşlılık ve hareket kısıtlılığı olan konuklar için daha kullanışlıdır.","iliskili":["kh1-5-113","kh1-5-115"],"kontrol":null,"gorsel":"t11e-alafranga-klozet-kabin"},{"id":"kh1-5-115","konu":"5.1.2","terim":"Pisuvar","ingilizce":"Urinal","tanim":"Erkekler tuvaletinde duvar kenarına yerleştirilmiş, aralarında paneller bulunan ve ayakta kullanılan tuvalet teçhizatıdır.","ornek":"Akşam yemeği öncesi 18.00’de Kemal, erkekler tuvaletindeki yan yana pisuvarların sifonunu çalıştırıp koku olup olmadığına bakar.","sektor":"Kapak mekanizması olmadığı için sifon sistemi çalışmadığında kötü koku yayar; bu yüzden sifonu düzenli kontrol edilir.","iliskili":["kh1-5-114","kh1-5-116"],"kontrol":null,"gorsel":"t10e-pisuvarlar"},{"id":"kh1-5-116","konu":"5.1.2","terim":"Tüketim malzemelerinin tükenmeden tamamlanması","ingilizce":"Restocking consumables before they run out","tanim":"Sabun, kâğıt havlu ve tuvalet kâğıdı gibi tüketim malzemelerinin genel alan temizlik görevlisi tarafından tükenmeden yerine konmasıdır.","ornek":"Kemal her turda sıvı sabunu, kâğıt havluyu ve tuvalet kâğıdını kontrol eder, azalanı tamamlar.","sektor":"Tüketim malzemesi biten tuvalet hem konuğu memnun etmez hem de hijyeni bozar.","iliskili":["kh1-5-115"],"kontrol":null,"gorsel":"t11a-kagit-havlu-wc"},{"id":"kh1-5-291","konu":"5.1.2","terim":"Klozet ve pisuvar temizlik sırası","ingilizce":"Cleaning order for toilets and urinals","tanim":"Klozetin içine temizleyiciyi dairesel biçimde sıkıp fırçalamak, kapağı ve dış yüzeyi kırmızı kenarlı bezle silmek, pisuvarın içini fırçalayıp dışını ayrı bir bezle temizlemek gibi tuvalet teçhizatında izlenen sıradır.","ornek":"Sabah 08.15’te Zeynep klozetin içine temizleyiciyi dairesel biçimde sıkıp fırçalar, kapağı kırmızı kenarlı bezle siler; pisuvarın dışını ise ayrı bir bezle temizler ve bezleri birbirine karıştırmaz.","sektor":"Ders materyaline göre önce iç kısım temizlenir, sonra dış yüzeyler silinir; klozet bezi lavabo ya da cam için kullanılmaz. Klozet fırçalanmadan önce ve sonra sifon çekilir, kullanılan bezler renklerine göre ayrı poşetlere konur.","iliskili":["kh1-5-123","kh1-5-144"],"kontrol":null,"gorsel":"t11d-klozet-temizleyici"},{"id":"kh1-5-294","konu":"5.1.2","terim":"Tuvalette son dokunuşlar","ingilizce":"Finishing touches in public toilets","tanim":"Genel tuvalette çöp kovaları ve metal bölümlerin metal parlatıcıyla parlatılması, kabin içleri ile lavabo önüne oda parfümü sıkılması, kapı kasalarının ve kapıların ahşap temizleyiciyle silinmesidir.","ornek":"Sabah 08.40’ta Zeynep lavabo ve aynaları bitirdikten sonra çöp kovasının metal kapağını parlatır, kabin içlerine oda parfümü sıkar, kapı kasasını ve kapıyı ahşap temizleyiciyle siler.","sektor":"Ders materyaline göre bu adımlar, eksik malzemelerin tamamlanması ve zeminin paspaslanmasıyla birlikte tuvalet temizliğinin son kısmında yapılır; ana metin ile uygulama yaprağı sırayı biraz farklı verir, işletme prosedürü esastır.","iliskili":["kh1-5-291","kh1-5-144"],"kontrol":null},{"id":"kh1-5-117","konu":"5.1.2","terim":"Genel tuvalette eldiven ve temiz bez","ingilizce":"Gloves and clean cloths in public toilets","tanim":"Islak alanların temizliği ve çöp toplama sırasında eldiven giyilmesi, uygun olmayan malzeme ya da kirli bez kullanılmamasıdır.","ornek":"Zeynep tuvalet temizliğine başlamadan önce eldivenlerini giyer ve temiz bez alır.","sektor":"Kirli bezle temizlik bulaşma riskini artırır; temizlik bezleri gün sonunda ayrı poşetlerle çamaşırhaneye teslim edilir.","iliskili":["kh1-5-118"],"kontrol":null,"gorsel":"t11d-sprey-temizleyici"},{"id":"kh1-5-118","konu":"5.1.2","terim":"Aşındırıcı kimyasal ve derz dolgu","ingilizce":"Abrasive chemicals and grout","tanim":"Fayans aralarındaki derz dolgusunu zamanla söken aşındırıcı ve kireç çözücü ürünlerin zemin temizliğinde kullanılmamasıdır.","ornek":"Kemal tuvalet zemininde aşındırıcı bir ürün kullanmak yerine zemine uygun hafif ürün seçer.","sektor":"Derz dolgu fayans ve seramik aralarını dolduran harçtır; sökülürse biriken su alt katlara akabilir.","iliskili":["kh1-5-117","kh1-5-119"],"kontrol":null},{"id":"kh1-5-119","konu":"5.1.2","terim":"Çamaşır suyuyla dezenfeksiyon","ingilizce":"Disinfection with bleach","tanim":"Tuvalet zemini, klozet ve pisuvarların bir oranda, lavabo, musluk, batarya başlıkları ve kapı kollarının ise daha seyreltik hazırlanan çamaşır suyuyla sıkça temizlenip dezenfekte edilmesidir.","ornek":"Öğleden sonra turunda Zeynep, kapı kollarını ve musluk başlıklarını seyreltilmiş çamaşır suyuyla siler.","sektor":"Ders materyaline göre zemin, klozet ve pisuvarlar 1/10, lavabo, musluk ve kapı kolları 1/100 oranında sulandırılmış çamaşır suyuyla temizlenir; çamaşır suyu başka kimyasalla karıştırılmaz.","iliskili":["kh1-5-118","kh1-5-120"],"kontrol":null},{"id":"kh1-5-120","konu":"5.1.2","terim":"Haşere görülürse rapor","ingilizce":"Reporting pests","tanim":"Tuvalette herhangi bir haşere görüldüğünde hemen rapor edilmesidir.","ornek":"Kemal kabin köşesinde böcek görünce şefine ve ilaçlama sorumlusuna bildirir.","sektor":"Haşere hijyen ve işletme imajı için ciddi bir risktir; zamanında bildirmek ilaçlamanın hızlı başlamasını sağlar.","iliskili":["kh1-5-119","kh1-5-121"],"kontrol":null,"gorsel":"t12e-hamamboceg"},{"id":"kh1-5-121","konu":"5.1.2","terim":"Temizlik saatlerinin kaydı ve WC kontrol fişi","ingilizce":"Cleaning log and toilet check slip","tanim":"Tuvalet ve lavabo temizlik saatlerinin kayıt edilip asılması, WC kontrol fişine saat ve personel adının yazılıp imzalanması ve dolan fişlerin yenileriyle değiştirilip şefe teslim edilmesidir.","ornek":"Kemal temizliği bitirince fişe saati yazar ve imzalar.","sektor":"Ders materyaline göre gece görevlisi dolan fişleri sabah 07.30’a kadar yenileriyle değiştirir; fiş sorumluluğu gösterir ve konuk temizliğin takip edildiğini görür.","iliskili":["kh1-5-120"],"kontrol":null},{"id":"kh1-5-122","konu":"5.1.2","terim":"Tuvalette KKD ve el hijyeni","ingilizce":"PPE and hand hygiene in toilet cleaning","tanim":"Temizlik yapan personelin eldiven, maske gibi kişisel koruyucu donanım (KKD) kullanması, kullanılan tek kullanımlık maske ve eldiveni iş yeri çöpüne atması ve su ve sabunla kendi el temizliğini sağlamasıdır.","ornek":"Zeynep temizliği bitirince eldiven ve maskeyi çöpe atar, ellerini sabunla yıkar.","sektor":"Ders materyaline göre eller en az 20 saniye yıkanır; el hijyeni hem personeli hem sonraki konuğu korur.","iliskili":["kh1-5-123"],"kontrol":null,"gorsel":"h1a-sabunla-el-yikama"},{"id":"kh1-5-290","konu":"5.1.2","terim":"Overlok","ingilizce":"Overlocking","tanim":"Kumaş kenarının dağılmaması için makineyle yapılan sıkı zikzaklı dikiştir.","ornek":"Zeynep, kenarı overlokla dikilmiş havlu bezi lavabo silmek için alır; bezin kenarından iplik çıkıp yüzeye bulaşmaz.","sektor":"Tuvalet temizliğinde bezler hem kumaş türüne hem renk koduna göre ayrılır; overlok bezin kenarını dağılmaktan korur ve bezin ömrünü uzatır.","iliskili":["kh1-5-123","kh1-5-047"],"kontrol":null,"gorsel":"t11e-overlok-makinesi"},{"id":"kh1-5-123","konu":"5.1.2","terim":"Tuvalette renk kodlu bez","ingilizce":"Colour-coded cloths in toilets","tanim":"Tuvalet temizliğinde hijyeni sağlamak için farklı yüzeylerde farklı renkte bezlerin kullanılmasıdır.","ornek":"Zeynep lavabo silmek için havlu bezi, klozet çevresi için kırmızı kenarlı ayrı bir havlu bezi alır; ikisini hiçbir zaman değiş tokuş etmez.","sektor":"Ders materyalinde örnek düzende ayna ve cam silmek için mavi, klozet çevresi için kırmızı kenarlı bez anılır; renk kodu işletmeye göre değişebilir ve bir yüzey için belirlenen renk dışında bez kullanılmaz. Kenarı overlokla dikilmiş bezler kullanılır.","iliskili":["kh1-5-122","kh1-5-124"],"kontrol":null},{"id":"kh1-5-124","konu":"5.1.2","terim":"Tuvalet kimyasalları","ingilizce":"Toilet cleaning chemicals","tanim":"Klozet ve pisuvar, banyo-fayans-plastik, pencere-cam-ayna, hava temizleyici, asidik banyo, ahşap temizleyici, kireç çözücü ve hoş kokulu zemin temizleyicisi gibi farklı yüzeyler için kullanılan kimyasallardır.","ornek":"Zeynep klozet için klozet temizleyicisini, aynalar için cam silme sıvısını kullanır.","sektor":"Her yüzeyin kimyasalı farklıdır; etiket okunur ve kimyasallar karıştırılmaz.","iliskili":["kh1-5-123"],"kontrol":null,"gorsel":"t11a-klozet-jeli"},{"id":"kh1-5-125","konu":"5.1.2","terim":"Mikroorganizma","ingilizce":"Microorganism","tanim":"Mikroskopla görülebilen, bakteri, virüs ve mantar gibi çok küçük canlıların genel adıdır.","ornek":"Sabah 07.30’da Kemal, kapalı ve nemli fitness salonunda yüzeylere neden bu kadar özen gösterildiğini sorar; şef, gözle görülmeyen canlıların nemli ve sıcak ortamda hızla üreyebildiğini anlatır.","sektor":"Dezenfeksiyon bu canlılara karşı yapılır; gözle görülmedikleri için yüzey temiz görünse de temizlik ve dezenfeksiyon gerekir.","iliskili":["kh1-5-126"],"kontrol":null,"gorsel":"t11e-bakteri-kolonileri"},{"id":"kh1-5-126","konu":"5.1.2","terim":"Dezenfeksiyon","ingilizce":"Disinfection","tanim":"Cansız yüzeylerdeki hastalık yapıcı mikroorganizmaların öldürülmesi ya da üremelerinin durdurulması işlemidir.","ornek":"Zeynep tuvalet kapı kollarını temizledikten sonra dezenfektanla siler.","sektor":"Temizlik kiri giderir, dezenfeksiyon mikrobu etkisiz hâle getirir; ikisi birlikte yapılır.","iliskili":["kh1-5-125","kh1-5-127"],"kontrol":null},{"id":"kh1-5-127","konu":"5.1.2","terim":"Dezenfektan","ingilizce":"Disinfectant","tanim":"Dezenfeksiyonu sağlamak için kullanılan kimyasal maddedir.","ornek":"Kemal tuvaletlerde etiketine uygun dezenfektan kullanır.","sektor":"Dezenfektanlar genellikle kuvvetli zehirdir; bu yüzden yalnız talimata uygun kullanılır. İnsanın doğrudan kullandığı eşyalarda dezenfektan artıkları denetlenir.","iliskili":["kh1-5-126","kh1-5-128"],"kontrol":null,"gorsel":"t12r-dezenfektan-sprey"},{"id":"kh1-5-128","konu":"5.1.2","terim":"Dezenfektan türleri: gaz, sıvı, katı","ingilizce":"Gaseous, liquid and solid disinfectants","tanim":"Dezenfektanların gaz, sıvı ve katı ya da kıvamlı olmak üzere üç hâlde kullanılmasıdır.","ornek":"Eğitim toplantısında şef Ayşe, depodaki dezenfektanları hâllerine göre üç gruba ayırıp etiketlerindeki talimatı ekibe okutur.","sektor":"Ders materyaline göre gaz olarak klor ve formol buharı, sıvı olarak fenol, oksijenli su ve tentürdiyot, katı ya da kıvamlı olarak kireç gibi maddeler örnek verilir. Bu maddelerin çoğu tehlikelidir; kat hizmetleri personeli ürünü kendisi seçmez, işletmenin verdiği ürünü talimatına göre kullanır.","iliskili":["kh1-5-127","kh1-5-129"],"kontrol":null},{"id":"kh1-5-129","konu":"5.1.2","terim":"Sterilizasyon","ingilizce":"Sterilisation","tanim":"Cansız ortamdaki patojen olan ya da olmayan tüm mikroorganizmaların yok edilmesi işlemidir.","ornek":"Şef Ayşe eğitimde dezenfeksiyon ile sterilizasyon arasındaki farkı tahtada gösterir.","sektor":"Dezenfeksiyonda mikroorganizmaların öldürülmesi ya da üremesinin durdurulması hedeflenir; sterilizasyonda hepsi yok edilir.","iliskili":["kh1-5-128","kh1-5-130"],"kontrol":null,"gorsel":"t11e-kuru-sterilizator"},{"id":"kh1-5-130","konu":"5.1.2","terim":"Ultraviyole (UV) ışınlı sterilizasyon","ingilizce":"Ultraviolet (UV) sterilisation","tanim":"Özel florsan lambaların yüksek dozda yaydığı ultraviyole ışınlarıyla çevredeki bakteri, virüs, mantar ve diğer mikroorganizmaların öldürülmesi yöntemidir.","ornek":"Gece vardiyasında spor salonunda UV cihazıyla sterilizasyon yapılır.","sektor":"Kimyasal madde gerektirmez; ancak ışınların göze ve cilde doğrudan temasını önlemek gerekir.","iliskili":["kh1-5-129","kh1-5-131"],"kontrol":null,"gorsel":"t10e-uv-sterilizasyon"},{"id":"kh1-5-131","konu":"5.1.2","terim":"UV cihazı güvenliği","ingilizce":"UV device safety","tanim":"Ultraviyole ışığa uzun süre maruz kalmanın insan sağlığı açısından tehlikeli olması nedeniyle işlemi yapan personelin koruyucu ekipman ve gözlük kullanması, işlemin konukların yoğun bulunmadığı gece saatlerinde yapılmasıdır.","ornek":"Zeynep UV cihazını kurarken gözlüğünü takar, alanda kimse olmadığını kontrol eder ve cihazı çalıştırıp alandan çıkar.","sektor":"Işın gözü ve cildi yaralayabilir; bu yüzden cihazla çalışan personel koruyucu ekipman ve gözlük kullanır, cihaz çalışırken konuk ve personel alanda bulunmaz.","iliskili":["kh1-5-130"],"kontrol":null},{"id":"kh1-5-132","konu":"5.1.3","terim":"Meydan arabasındaki malzemeler","ingilizce":"Contents of the public area trolley","tanim":"Genel alan temizliği için gereken süpürge, fırça, mop, çöp torbası, havlu, tuvalet kâğıdı, bez, paspas, eldiven, maske, farklı yüzeylere uygun kimyasallar, kova ve cam silme aletinin taşındığı arabadaki donanımdır.","ornek":"Kemal vardiya başında arabasını kontrol eder; cam silme aleti, mop ve kimyasallar yerinde.","sektor":"Genel alan görevlisi elektrikli araçlar dışındaki malzemeleri araçla temizlenecek alana taşır.","iliskili":["kh1-5-133"],"kontrol":null,"gorsel":"h3b-temizlik-arabasi"},{"id":"kh1-5-133","konu":"5.1.3","terim":"Meydan ofisi","ingilizce":"Public area office","tanim":"Genel alan temizliği için gereken araç gereç ve malzemelerin saklandığı, görevlilerin işe başlamadan önce uğrayıp arabalarını yükledikleri ve iş bitince geri getirdikleri ofistir.","ornek":"Zeynep sabah 06.00’da meydan ofisinden arabasını ve anahtarlarını alır; iş bitince arabayı yine buraya getirir, eksikleri tamamlar.","sektor":"Malzeme tek yerde saklandığında hangi ürünün tükendiği kolayca görülür; ofisin anahtarı genel alanlar şefindedir ve görevliye teslim edilir.","iliskili":["kh1-5-132","kh1-5-134","kh1-5-242"],"kontrol":null,"gorsel":"t11a-servis-lavabosu"},{"id":"kh1-5-134","konu":"5.1.3","terim":"Elektrikli araçların ayrı taşınması","ingilizce":"Carrying electrical equipment separately","tanim":"Araba içinde değil, görevli tarafından ayrıca alana getirilen elektrikli süpürge gibi temizlik araç gereçlerinin taşınma biçimidir.","ornek":"Kemal elektrikli süpürgeyi arabanın yanında ayrıca taşır.","sektor":"Elektrikli araçlar arabaya konmaz; görevli bunları ayrıca getirir ve kablo ile priz bağlantılarını ayrıca kontrol eder.","iliskili":["kh1-5-133","kh1-5-135"],"kontrol":null},{"id":"kh1-5-135","konu":"5.1.3","terim":"Araç gerecin kalitesi ve malzeme stoku","ingilizce":"Equipment quality and stock levels","tanim":"Hizmetin standartlara uygun yapılabilmesi için araç gerecin kaliteli olması ve malzemelerin aksamadan elde edilip her zaman yeterli miktarda stokta bulunmasıdır.","ornek":"Şef Murat, kritik malzemeler azalınca erkenden sipariş verir.","sektor":"Ders materyaline göre iş gücünden sonra kat hizmetlerinin en büyük maliyeti malzemedir; stoksuzluk işin durmasına yol açar.","iliskili":["kh1-5-134","kh1-5-136"],"kontrol":null},{"id":"kh1-5-136","konu":"5.1.3","terim":"Temizlik sepeti (basket)","ingilizce":"Cleaning caddy","tanim":"Küçük işlerde temizlik malzemelerinin elde taşındığı sepettir.","ornek":"Öğle 13.00’te Zeynep, konferans fuayesindeki küçük tuvaleti arabasız bir sepetle temizlemeye gider; sepette bez, kimyasal ve eldiven vardır.","sektor":"Küçük işlerde araba yerine sepet kullanılabilir; asansör temizliğinde ekipman araba ya da sepetle alana getirilir.","iliskili":["kh1-5-135"],"kontrol":null,"gorsel":"t12s-kova-eldiven"},{"id":"kh1-5-137","konu":"5.1.4","terim":"İç mekân temizliğinin yapılması","ingilizce":"Carrying out interior cleaning","tanim":"Genel alanların temizliğinin konukların görebileceği şekilde yapılması ve işlemler sırasında konukların rahatsız edilmemesine özen gösterilmesidir.","ornek":"Kemal öğleden sonra lobide çalışırken hareketlerini sakin tutar, araçları geçiş yolundan uzakta bırakır.","sektor":"Her uygulama yaprağı bu ilkeye dayanır: önce konuk, sonra iş.","iliskili":["kh1-5-138"],"kontrol":null},{"id":"kh1-5-138","konu":"5.1.4","terim":"Uygulama yaprağı","ingilizce":"Practical worksheet","tanim":"Bir temizlik uygulamasının amacını, süresini, araç gerecini, yönergesini, adımlarını ve değerlendirme ölçütlerini bir arada gösteren ders çalışma yaprağıdır.","ornek":"Öğrenci Elif, lobi uygulamasına başlamadan önce yaprağın üstündeki amacı ve araç gereç listesini okur.","sektor":"Her yaprak “Amaç, Süre, Araç gereç, Yönerge” başlıklarıyla başlar; uygulama kat hizmetleri atölyesinde yapılır.","iliskili":["kh1-5-137","kh1-5-139"],"kontrol":null},{"id":"kh1-5-139","konu":"5.1.4","terim":"İşe başlamadan önce kişisel bakım ve hijyen adımları","ingilizce":"Personal care steps before work","tanim":"Uygulamaya başlamadan önce kişisel bakım ve hijyen kurallarını dikkatli uygulama, takıları çıkarma, işletmenin belirlediği üniformayı giyme ve isimliği üniformaya takma adımlarıdır.","ornek":"Öğrenci Elif atölyeye girmeden önce yüzüğünü çıkarır, üniformasını giyer ve isimliğini takar.","sektor":"Her uygulama yaprağının ilk dört adımı aynıdır; bu adımlar mesleğe hazırlığın temelidir. Bahçe, plaj ve havuz gibi dış mekân uygulamalarında bunlara güneş ve hava koşullarına karşı önlem (örneğin şapka) eklenir.","iliskili":["kh1-5-138","kh1-5-140","kh1-5-172"],"kontrol":null,"gorsel":"t11e-el-yikama-sabun"},{"id":"kh1-5-140","konu":"5.1.4","terim":"Görev talimatı: toplantı, iş programı, anahtar","ingilizce":"Task briefing: meeting, schedule, key","tanim":"Kat hizmetlerinin düzenlediği toplantıya katılma, genel alanlar şefinden iş programını öğrenme ve meydan ofisinin anahtarını genel alanlar şefinden teslim alma adımlarından oluşan hazırlıktır.","ornek":"Öğrenci Elif atölyede şef rolündeki öğretmenden iş programını alır ve ofis anahtarını teslim alır.","sektor":"Uygulama sahada nasıl işliyorsa o düzende yapılır; işe önce planı öğrenmekle başlanır. Dış mekân uygulamalarında da aynı üç adım izlenir: toplantıya katılınır, iş programı genel alanlar şefinden öğrenilir, meydan ofisinin anahtarı şeften teslim alınır.","iliskili":["kh1-5-139"],"kontrol":null},{"id":"kh1-5-141","konu":"5.1.4","terim":"Meydan arabasının hazırlanması uygulaması","ingilizce":"Public area trolley preparation task","tanim":"Uluslararası standartlara ve işletme prosedürüne göre genel alan temizleme görevlisi tarafından meydan arabasının hazırlanması ve hazırlanan arabanın temizliği yapılacak alana götürülmesi uygulamasıdır.","ornek":"Öğrenci Elif ofisten arabayı alır, çöp torbasını değiştirir, kimyasalları ve temiz bezleri yerleştirir, tuvalet kâğıdı, kâğıt havlu ve sabunu tamamlar.","sektor":"Ders materyaline göre uygulama süresi 20 dakikadır; araç gereç olarak üniforma, isimlik, meydan arabası ve gerekli temizlik araç gereçleri kullanılır.","iliskili":["kh1-5-142"],"kontrol":null,"gorsel":"t15af-meydan-arabasi"},{"id":"kh1-5-293","konu":"5.1.4","terim":"Meydan arabasını alana götürme","ingilizce":"Taking the trolley to the work area","tanim":"Hazırlanan arabanın temizlenecek alana dikkatle götürülmesi, servis asansörü kullanılacaksa asansörde arabanın yan tarafında durulması ve arabanın konukları rahatsız etmeyecek bir yere bırakılmasıdır.","ornek":"Sabah 07.45’te Zeynep, hazırladığı arabayı servis asansörüne yerleştirir ve asansörde arabanın yan tarafında durur; plaj kabinlerinin önüne varınca arabayı konukların geçişini kapatmayacak bir köşeye bırakır.","sektor":"Ders materyaline göre ıslak toz alma için kullanılacak su kovaları yarısına kadar doldurularak arabaya konur; araba bırakıldığı yerde konukların geçişini engellememelidir.","iliskili":["kh1-5-141","kh1-5-132"],"kontrol":null},{"id":"kh1-5-142","konu":"5.1.4","terim":"Lobi temizliği uygulaması","ingilizce":"Lobby cleaning task","tanim":"Konaklama işletmesi içindeki lobinin günlük temizlik işlerini yapma uygulamasıdır.","ornek":"Öğrenci Elif, lobide oturma grubunun ve mobilyaların tozunu alır, çöpleri boşaltır, uyarı levhasını yerleştirir, zemini temizler ve camları siler.","sektor":"Halı varsa elektrikli süpürge alana getirilir; uygulama sonunda kirli bezler renklerine göre ayrılır.","iliskili":["kh1-5-141","kh1-5-143"],"kontrol":null},{"id":"kh1-5-143","konu":"5.1.4","terim":"Asansör temizliği uygulaması","ingilizce":"Lift cleaning task","tanim":"Konaklama işletmesindeki konuk asansörlerinin günlük temizlik işlerini yapma uygulamasıdır.","ornek":"Öğrenci Elif asansör çevresine uyarı levhasını koyar, asansörü lobide temizler, düğmeleri temizleyip dezenfekte eder.","sektor":"Duvarlar ve aynalar uygun bezle silinir; zemin halıysa süpürgeyle vakumlanır, çağrı düğmeleri ve dış kapılar dezenfekte edilir.","iliskili":["kh1-5-142","kh1-5-144"],"kontrol":null},{"id":"kh1-5-144","konu":"5.1.4","terim":"Genel tuvalet temizliği uygulaması","ingilizce":"Public toilet cleaning task","tanim":"Konaklama işletmesi içinde yer alan genel alanlardaki tuvaletlerin günlük temizlik işlerini yapma uygulamasıdır.","ornek":"Öğrenci Elif tuvalet kapısını çalıp “Housekeeping” der, içeri girer ve ardından maskesini ve eldivenlerini takar.","sektor":"Araba tuvaletin önüne getirilir; ders materyaline göre kapı üç kez çalınıp “Housekeeping” diye seslenilir, çünkü içeride konuk olabilir ve habersiz girilmez. Lavabolar, aynalar, klozetler ve pisuvarlar ilgili bezlerle temizlenir, eksik sarf malzemeleri tamamlanır, WC kontrol fişi imzalanır.","iliskili":["kh1-5-143","kh1-5-145"],"kontrol":null,"gorsel":"t11d-klozet-cevresi"},{"id":"kh1-5-145","konu":"5.1.4","terim":"Halı yıkama uygulaması","ingilizce":"Carpet washing task","tanim":"Konaklama işletmesi içinde yer alan halı kaplı zeminleri yıkama uygulamasıdır.","ornek":"Öğrenci Elif elektrikli süpürgeyle halıyı tozdan arındırır, lekeleri çıkarır, makineye su ve şampuan koyar, yıkar ve köpüğü vakumlar.","sektor":"Elektrik bağlantıları ve prizler kontrol edilir; halı tam kuruyana kadar alan kullanıma kapatılır; makinenin tankı ve fırçaları temizlenir.","iliskili":["kh1-5-144","kh1-5-146"],"kontrol":null,"gorsel":"t13d-hali-yikama-hortum"},{"id":"kh1-5-146","konu":"5.1.4","terim":"Cam ve ayna temizliği uygulaması","ingilizce":"Glass and mirror cleaning task","tanim":"Konaklama işletmesi içinde yer alan aynalar ve camların günlük temizliğini yapma uygulamasıdır.","ornek":"Öğrenci Elif cam yüzeyine sprey sıkar, silme aletiyle “S” çizerek yukarıdan aşağıya siler, çerçeve ve cam kenarlarındaki tozu alır.","sektor":"Cam silme sırasında perdelerin ıslanmaması için tedbir alınır; kullanılan bez rengine göre ayrı poşete konur.","iliskili":["kh1-5-145"],"kontrol":null,"gorsel":"t12s-cam-silme-lastik"},{"id":"kh1-5-147","konu":"5.1.4","terim":"Uygulama sonu toplama","ingilizce":"Closing steps after a task","tanim":"Çöp torbasının değiştirilmesi, kovaların boşaltılıp yıkanması, araç gereçlerin temizlenip kurutulması ve kirli malzemenin ayrı torbalarla çamaşırhaneye hazırlanmasından oluşan uygulama sonu işlemleridir.","ornek":"Öğrenci Elif lobi uygulamasını bitirince çöp torbasını değiştirir, kovaları boşaltır, mopları yıkar ve kirli bezleri çamaşırhane torbasına koyar.","sektor":"Kirli bezler çamaşırhaneye ayrı poşetlerde gönderilir; araç gereç temiz ve kuru saklanır.","iliskili":["kh1-5-148"],"kontrol":null},{"id":"kh1-5-148","konu":"5.1.4","terim":"Uygulamanın değerlendirme formu","ingilizce":"Task assessment form","tanim":"Öğretmenin öğrencinin uygulama becerisini puanlamak için kullandığı; tarih, öğrencinin ve öğretmenin adı soyadı, numara ve imza alanları bulunan değerlendirme formudur.","ornek":"Atölyede lobi uygulaması bitince öğretmen formdaki tarih, ad soyad ve numara alanlarını doldurur, puanı işleyip imzalar; öğrenci Elif kendi puanını görür.","sektor":"Uygulama becerisi, uygulama adımlarının ne kadar doğru yapıldığını gösterir; puanlama uygulamanın türüne göre öğretmen tarafından belirlenir.","iliskili":["kh1-5-147","kh1-5-149"],"kontrol":null},{"id":"kh1-5-149","konu":"5.1.4","terim":"Genel alan uygulaması değerlendirme kriterleri","ingilizce":"Practical assessment criteria","tanim":"İş için ön hazırlık, uygulama becerisi, zamanı kullanma, iletişim ve olağan dışı durumlara hazır bulunuşluk olmak üzere beş başlıktan oluşan, öğrencinin uygulama becerisinin değerlendirildiği ölçütlerdir.","ornek":"Öğretmen lobi uygulamasında Elif’in iş için ön hazırlığını, zaman kullanımını ve iletişimini ayrı ayrı puanlar; plaj uygulamasında da aynı beş başlığa bakar.","sektor":"Her kriterin ayrı puanı vardır; hazırlıklı gelmek ve zamanı iyi kullanmak da puanı etkiler. Puanlama yalnızca sonuca değil sürece de bakar; aynı ölçütler iç mekândaki ve dış mekândaki bütün uygulamalarda kullanılır.","iliskili":["kh1-5-148","kh1-5-270","kh1-5-275"],"kontrol":null},{"id":"kh1-5-151","konu":"5.2","terim":"Dış mekân","ingilizce":"Exterior area","tanim":"Konaklama işletmesinin binası dışında kalan; giriş, bahçe, yürüyüş yolu, otopark, spor alanı, plaj ve havuz çevresi gibi açık alanlardır.","ornek":"Sabah 08.30’da Bodrum’daki bir otelin önüne taksiyle gelen konuk, resepsiyona varmadan önce giriş yolunu, bahçeyi ve otoparkı görür.","sektor":"Konuk resepsiyona varmadan işletme hakkında fikir edinir; dışarıdaki dağınıklık içerideki hizmetin de aynı olacağı izlenimi verir.","iliskili":["kh1-5-152","kh1-5-153","kh1-5-155"],"kontrol":null,"gorsel":"g3-plajdaki-otel-avlusu"},{"id":"kh1-5-152","konu":"5.2","terim":"Dış mekânda ilk izlenim","ingilizce":"First impression of the exterior","tanim":"Konuğun işletmeye girmeden önce gördüklerinden zihninde oluşan ilk düşüncedir.","ornek":"Antalya’da otel arayan bir aile, rezervasyon yapmadan önce arabayla otelin önünden geçip bahçenin bakımlı olup olmadığına bakar.","sektor":"Bakımlı bir giriş işletmeye yeni konuk kazandırır; izmaritle dolu, yaprak yığılmış bir giriş otelin geri kalanına da güveni azaltır.","iliskili":["kh1-5-151","kh1-5-153"],"kontrol":null,"gorsel":"h4-antalya-resort"},{"id":"kh1-5-153","konu":"5.2","terim":"Dış mekân bakımı","ingilizce":"Exterior upkeep","tanim":"Açık alanların bakımlı görünmesi ve oradaki etkinliklerin sağlıklı bir ortamda yapılması için yürütülen temizlik ve düzenleme çalışmalarının tümüdür.","ornek":"Alanya’daki bir otelde akşamki açık hava gösterisinden önce sahne çevresi süpürülür, oturma yerlerinin tozu alınır.","sektor":"İş yalnızca güzel görünmek için değildir; kirli ve düzensiz bir alan konuğun etkinliğe katılma isteğini ve sağlığını da etkiler.","iliskili":["kh1-5-151","kh1-5-154"],"kontrol":null,"gorsel":"t11f-havuzlu-villa"},{"id":"kh1-5-154","konu":"5.2","terim":"Dış mekân temizlik planı","ingilizce":"Exterior cleaning schedule","tanim":"Dış mekân işlerinin günlük, haftalık, aylık ve periyodik aralıklara bölünerek önceden belirlenmesidir.","ornek":"Genel alanlar şefi pazartesi sabahı 07.30’da ekibe haftanın planını verir: bugün yürüyüş yolları, perşembe açık alan mobilyaları.","sektor":"Plan olmadan işler konukların en yoğun olduğu saate kalır; planlı temizlikte alanlar hem bakımlı hem boş olduğu saatte temizlenir.","iliskili":["kh1-5-156","kh1-5-157","kh1-5-158"],"kontrol":null},{"id":"kh1-5-155","konu":"5.2","terim":"Kat hizmetlerinin dış mekân sorumluluğu ve iş bölümü","ingilizce":"Housekeeping responsibility for exterior areas","tanim":"Dış mekân temizliğinin planlanıp uygulanmasının kat hizmetleri bölümünün görevi olması, donanımların bakımının ise diğer bölümlere dağılmasıdır.","ornek":"Marmaris’teki bir tatil otelinde bahçe ve plaj çöplerini toplamak için sabah meydan arabasıyla yola çıkan ekip kat hizmetleri bölümüne bağlıdır.","sektor":"Havuz ve spor aleti gibi donanımın temizlik ve bakımını yiyecek içecek, teknik servis, eğlence ve bahçıvan bölümlerindeki görevliler üstlense de dış mekânın asıl genel temizliği kat hizmetlerinde toplanır. İş bölümü işletmeden işletmeye değişir; yeni başlayan çalışan kime hangi işin ait olduğunu bilirse sorunu doğru kişiye iletir.","iliskili":["kh1-5-151","kh1-5-154","kh1-5-231"],"kontrol":null},{"id":"kh1-5-156","konu":"5.2","terim":"Günlük dış mekân temizliği","ingilizce":"Daily exterior cleaning","tanim":"Toz alma, kül tablası ve çöp kutularını boşaltma, çöp poşetini değiştirme, sert yüzeyleri süpürüp paspaslama ve tuvalet ile giyinme kabinlerini temizleme gibi her gün tekrarlanan işlerdir.","ornek":"Sabah 08.00’de Kemer’deki bir otelde görevli, bahçedeki çöp kutularını boşaltır, havuz yanındaki kabinlerin kontrolünü yapar.","sektor":"Günlük işler konuğun gün boyu gördüğü yüzeyleri taze tutar; atlandığında kir ertesi gün birikerek ağır işe dönüşür.","iliskili":["kh1-5-157","kh1-5-158"],"kontrol":null},{"id":"kh1-5-157","konu":"5.2","terim":"Haftalık ve aylık dış mekân temizliği","ingilizce":"Weekly and monthly exterior cleaning","tanim":"Yüzeyleri detaylı temizleme, yıkama ve parlatma; bitki, duvar ve ahşap bakımı gibi her gün yapılmayan ama düzenli aralıkla tekrarlanan işlerdir.","ornek":"Cuma günü Çeşme’deki bir otelde görevliler teras duvarını yıkar, saksı çiçeklerinin yapraklarını siler.","sektor":"Günlük işle görünmeyen birikmiş kiri bu temizlik alır; atlanırsa yüzeyler erken yıpranır.","iliskili":["kh1-5-156","kh1-5-158","kh1-5-162"],"kontrol":null},{"id":"kh1-5-158","konu":"5.2","terim":"Periyodik dış mekân temizliği","ingilizce":"Periodic exterior cleaning","tanim":"Bina cam kaplamasının temizliği, cila sökme ve yeniden cilalama, boyama gibi uzun aralıklarla yapılan büyük işlerdir.","ornek":"Sezon başında Fethiye’deki bir otelin giriş zemini cila sökülerek yenilenir ve yeniden cilalanır.","sektor":"Büyük işler genellikle konuk az olan dönemde planlanır; işletme yenilenmiş görünümle sezona girer.","iliskili":["kh1-5-156","kh1-5-157","kh1-5-109"],"kontrol":null,"gorsel":"h6-cam-silme-platformu"},{"id":"kh1-5-159","konu":"5.2","terim":"Açık alan mobilyasının yıkanması","ingilizce":"Washing outdoor furniture","tanim":"Dışarıdaki masa, sandalye ve banklarda günlük tozdan fazlasını gideren, yıkayarak yapılan detaylı temizliktir.","ornek":"Salı sabahı Side’deki bir otelde bahçe masaları hortumla yıkanır, ayakları ve altları da silinir.","sektor":"Güneş, kuş pisliği ve toz mobilyada birikir; yıkanmamış mobilyada oturan konuk dışarıdaki temizlik düzeyini hemen fark eder.","iliskili":["kh1-5-157","kh1-5-162"],"kontrol":null},{"id":"kh1-5-160","konu":"5.2","terim":"Çiçek ve bitki temizliği","ingilizce":"Cleaning flowers and plants","tanim":"Dış mekândaki saksı ve süs bitkilerinin yapraklarındaki toz ve kirin giderilmesi işlemidir.","ornek":"Giriş holünün önünde duran saksıların yaprakları cuma günü 09.00’da nemli bezle silinir.","sektor":"Tozlu bitki, bakımlı bir girişin görüntüsünü bozar; bitkinin kendisinin bakımı ise bahçıvanın işidir.","iliskili":["kh1-5-157","kh1-5-159"],"kontrol":null},{"id":"kh1-5-161","konu":"5.2","terim":"Duvarların yıkanması","ingilizce":"Washing exterior walls","tanim":"Giriş ve bahçe çevresindeki duvarlarda biriken toz ve lekelerin yıkanarak temizlenmesidir.","ornek":"Kuşadası’ndaki bir otelde, sezon öncesi hafta sonu giriş duvarının tozu ve su lekeleri yıkanır.","sektor":"Duvarlar konuğun gözünün hizasında olduğundan lekeli bir duvar bütün girişin bakımsız görünmesine neden olur.","iliskili":["kh1-5-157","kh1-5-158"],"kontrol":null,"gorsel":"t12e-cephe-basincli-yikama"},{"id":"kh1-5-162","konu":"5.2","terim":"Ahşap yüzeylerin yıkanması ve cilalanması","ingilizce":"Washing and polishing wooden surfaces","tanim":"Teras, köprü ve bank gibi dış mekân ahşaplarının yıkanıp cilalanarak korunmasıdır.","ornek":"Bodrum’daki bir otelde deniz kenarındaki ahşap iskelenin tahtaları ayda bir yıkanıp cilalanır.","sektor":"Cila ahşabı nem ve güneşe karşı korur; ihmal edilen ahşap çabuk çürür ve yenileme maliyeti büyür.","iliskili":["kh1-5-157","kh1-5-159"],"kontrol":null,"gorsel":"t12e-cilali-ahsap-teras"},{"id":"kh1-5-164","konu":"5.2","terim":"Cila sökme ve yeniden cilalama","ingilizce":"Stripping and re-polishing","tanim":"Dış mekân periyodik planında yer alan, zeminde birikmiş eski cila tabakasının kaldırılıp yüzeyin yeniden cilalanması işidir.","ornek":"Sezon başında otel girişindeki mermer zemin kirlenmiş cilasından arındırılır ve yeni cila uygulanır.","sektor":"Eski cila üstüne yeni cila sürmek kiri hapseder; bu nedenle önce söküm, sonra yeniden cilalama yapılır.","iliskili":["kh1-5-053","kh1-5-158","kh1-5-165"],"kontrol":null},{"id":"kh1-5-165","konu":"5.2","terim":"Dış mekân yüzeylerinin boyanması","ingilizce":"Repainting exterior surfaces","tanim":"Duvar, korkuluk ve bank gibi dış yüzeylerin eskiyip solduğunda yenilenmesi işlemidir.","ornek":"Kış kapanışında Alanya’daki bir otelin bahçe korkulukları temizlenir, eskiyen boyası yenilenir.","sektor":"Boya yüzeyi korurken görünümü de tazeler; periyodik temizliğin en seyrek yapılan işlerinden biridir.","iliskili":["kh1-5-158","kh1-5-164"],"kontrol":null,"gorsel":"t12e-dis-mekan-banki"},{"id":"kh1-5-166","konu":"5.2.1","terim":"Şehir otelinde açık alan","ingilizce":"Open areas of a city hotel","tanim":"Kent merkezinde iş amacıyla kullanılan konaklama işletmelerinde bahçe gibi dış mekânın sınırlı kalması durumudur.","ornek":"Ankara’da iş seyahati için kalan konuk, otelin yalnızca küçük bir giriş alanını ve küçük otoparkını kullanır.","sektor":"Açık alan az olduğundan temizliği kısa sürer; ama giriş küçük olduğu için her ayrıntı daha çok fark edilir.","iliskili":["kh1-5-167","kh1-5-168"],"kontrol":null},{"id":"kh1-5-167","konu":"5.2.1","terim":"Resort otel","ingilizce":"Resort hotel","tanim":"Uzun süreli konaklama, dinlenme ve eğlence amacıyla coğrafi güzelliklere yakın yerlerde kurulan tatil otelidir.","ornek":"Fethiye’de denize yakın bir resort otelde konuk bir hafta boyunca plajı, havuzları ve spor alanlarını kullanır.","sektor":"Konuk zamanının çoğunu dışarıda geçirdiği için resort otelde dış mekân temizliği işin büyük kısmını oluşturur.","iliskili":["kh1-5-166","kh1-5-168"],"kontrol":null,"gorsel":"h3b-resort-havuzlari"},{"id":"kh1-5-168","konu":"5.2.1","terim":"Resort otelde geniş dış mekân düzeni","ingilizce":"Large outdoor layout in resorts","tanim":"Konukların farklı etkinliklere katılabilmesi için resort otellerde dış mekânların geniş tutulması ve çevresinin özenle düzenlenmesidir.","ornek":"Kemer’deki büyük bir tatil tesisinde havuz, bahçe, tenis kortu ve plaj arasında yürüyüş yolları döşenmiştir.","sektor":"Alan ne kadar genişse temizlik ekibi, araç ve plan ihtiyacı da o kadar artar.","iliskili":["kh1-5-167","kh1-5-169"],"kontrol":null,"gorsel":"t11e-resort-kusbakisi"},{"id":"kh1-5-169","konu":"5.2.1","terim":"Aktivite alanı","ingilizce":"Activity area","tanim":"Konukların dinlenmek, eğlenmek, beslenmek veya spor yapmak için kullandığı dış mekân bölümüdür.","ornek":"Öğleden sonra 15.00’te konuklar plajda yüzer, bahçede dinlenir ya da kortta tenis oynar.","sektor":"Her aktivite alanının kullanımı farklı olduğundan temizlik yöntemi ve sıklığı da alana göre değişir.","iliskili":["kh1-5-168","kh1-5-151"],"kontrol":null},{"id":"kh1-5-171","konu":"5.2.1","terim":"Dış mekân iş sağlığı ve güvenliği","ingilizce":"Exterior health and safety measures","tanim":"Açık alanda temizlik yapan görevlinin kendisini ve konukları korumak için aldığı önlemlerin bütünüdür.","ornek":"Sabah 09.00’da plaj temizliğine çıkmadan önce görevli güneşten korunma, eldiven ve kaymayan ayakkabı kontrolünü yapar.","sektor":"Önlemlerin çoğu iç mekândakilerle aynıdır: eldiven ve maske, doğru kaldırma duruşu, kablo ve priz kontrolü, sağlam merdiven ve refakatçi, etiket okuma, ürün karıştırmama, makul iş yükü ve ilk yardım bilgisi. Dışarıya özgü olanlar güneşten korunma, alanı kapatma ve konukların yoğun olmadığı saatte çalışmadır; güvenlik önlemi alınmadan çalışan personel kazaya ve hastalığa daha açıktır.","iliskili":["kh1-5-172","kh1-5-174","kh1-5-178"],"kontrol":null},{"id":"kh1-5-172","konu":"5.2.1","terim":"İşe uygun kıyafet ve hava koşullarına karşı korunma","ingilizce":"Suitable workwear and weather protection","tanim":"Dış mekânda çalışan personelin hava koşullarına uygun giyinmesi ve güneş, sıcak ya da soğuk gibi etkilere karşı gerekli önlemi almasıdır.","ornek":"Temmuz sabahı 09.00’da Antalya’daki bir otelde görevli Serkan, plaja çıkmadan şapka takar ve yanına su alır.","sektor":"Uzun süre güneşte kalan personel çabuk yorulur; koruyucu önlem hem sağlığı hem verimi korur. Kış koşullarında kalın giysi gerekir; etkiler önceden düşünülerek önlem alınır.","iliskili":["kh1-5-171","kh1-5-174"],"kontrol":null,"gorsel":"t11e-reflektorlu-is-kiyafeti"},{"id":"kh1-5-174","konu":"5.2.1","terim":"Konukları rahatsız etmeyen çalışma saati","ingilizce":"Working outside peak hours","tanim":"Temizliğin konukların yoğun kullanmadığı saatlerde yapılması ve konukların rahatsız edilmemesi için tedbir alınmasıdır.","ornek":"Açık terasın yıkama işi kahvaltı saatinde değil, kahvaltı bitip konuklar plaja indikten sonra, 11.00’de yapılır.","sektor":"Konuk dinlenmek için gelmiştir; gürültü, ıslak zemin ve kimyasal kokusu tatilini bozar.","iliskili":["kh1-5-171","kh1-5-178"],"kontrol":null},{"id":"kh1-5-178","konu":"5.2.1","terim":"Islak zemin temizliğinde levha ve alan kapatma","ingilizce":"Wet floor sign and area closure","tanim":"Kayma kazasını önlemek için ıslak zemin temizliğinden önce uyarı işareti ve levha konup temizlenen alanın kullanıma tamamen kapatılmasıdır.","ornek":"Havuz kenarındaki zemini yıkamadan önce görevli alanın çevresine levha koyar.","sektor":"Levhasız ıslak zeminde kayan konuk yaralanabilir; bu hem insan hem itibar kaybıdır. Gerekirse çalışma alanı emniyet şeridiyle çevrilir.","iliskili":["kh1-5-171","kh1-5-050","kh1-5-029"],"kontrol":null,"gorsel":"t10e-islak-zemin-levhasi"},{"id":"kh1-5-185","konu":"5.2.2","terim":"Dış mekânda temizlenen alanlar","ingilizce":"Exterior areas to be cleaned","tanim":"İşletmenin türüne ve sunduğu hizmetin çeşitliliğine göre değişen; giriş ve otopark, yürüyüş yolu, spor alanı, animasyon alanı, yiyecek içecek alanı, havuz, plaj ve kaplıca gibi bölümlerdir.","ornek":"Bir şehir otelinde yalnızca giriş ve otopark temizlenirken, Çeşme’deki bir tatil köyünde plaj ve havuz çevresi de listeye girer.","sektor":"Temizlik listesi her işletmede aynı değildir; görevli önce kendi otelinin alan listesini öğrenir.","iliskili":["kh1-5-186","kh1-5-187","kh1-5-190"],"kontrol":null},{"id":"kh1-5-186","konu":"5.2.2","terim":"Konaklama işletmesinin girişi","ingilizce":"Hotel entrance area","tanim":"Konuğun işletmeye geldiğinde ilk karşılaştığı, otopark ve bina arasındaki giriş alanıdır.","ornek":"Sabah 07.30’da görevli, giriş merdivenlerindeki izmarit ve yaprakları süpürerek konuk gelmeden önce yolu temizler.","sektor":"Girişteki bakım konuğun işletmeyi hatırlamasına doğrudan etki eder; bu alan öncelikle temizlenir.","iliskili":["kh1-5-185","kh1-5-201"],"kontrol":null,"gorsel":"t11e-otel-giris-lobisi"},{"id":"kh1-5-187","konu":"5.2.2","terim":"Animasyon alanı","ingilizce":"Entertainment area","tanim":"Bahçe, amfi tiyatro ve açık hava diskosu gibi konukların eğlenmesi için kullanılan dış mekân bölümüdür.","ornek":"Akşam gösterisinden önce animasyon ekibi sahneyi hazırlarken görevli etrafın çöplerini toplar.","sektor":"Gösteriden sonra çöp, bardak ve izmarit hızla toplanmazsa ertesi sabah alan bakımsız görünür.","iliskili":["kh1-5-188","kh1-5-189","kh1-5-185"],"kontrol":null,"gorsel":"t11e-acik-hava-amfisi"},{"id":"kh1-5-188","konu":"5.2.2","terim":"Amfi tiyatro","ingilizce":"Amphitheatre","tanim":"Kademeli oturma düzenine sahip, genellikle gösteri ve etkinlik için kullanılan açık hava sahnesidir.","ornek":"Fethiye’deki bir tatil köyünde akşam gösterisi bittikten sonra görevli basamak ve sıraları kontrol eder.","sektor":"Çok sayıda konuk oturduğundan çöp ve dökülen içecek çok olur; temizlik hemen yapılır.","iliskili":["kh1-5-187","kh1-5-189"],"kontrol":null,"gorsel":"t13a-aspendos-tiyatro"},{"id":"kh1-5-189","konu":"5.2.2","terim":"Açık hava diskosu","ingilizce":"Open-air disco","tanim":"Gece eğlencesi için kurulan, çatısı olmayan eğlence alanıdır.","ornek":"Sabah 06.00’da diskonun çevresindeki bardak ve şişeler meydan arabasındaki torbalara toplanır.","sektor":"Gece yoğun kullanılan alan sabaha kadar kirli kalırsa kahvaltıya giden konuklar tarafından görülür.","iliskili":["kh1-5-187","kh1-5-188"],"kontrol":null},{"id":"kh1-5-190","konu":"5.2.2","terim":"Açık havada yiyecek içecek alanı","ingilizce":"Outdoor dining area","tanim":"Konukların yemek ve içeceklerini dışarıda tükettiği masa ve oturma bölümleridir.","ornek":"Plaj barının yanındaki masalarda öğle yemeği sonrası görevli tabak kırıntılarını ve bardakları toplar.","sektor":"Yiyecek artığı böcekleri ve kötü kokuyu çeker; bu yüzden bu alanlarda temizlik sık yapılır.","iliskili":["kh1-5-185","kh1-5-211"],"kontrol":null,"gorsel":"g3-restoran-terasi-masalari"},{"id":"kh1-5-191","konu":"5.2.2","terim":"Kaplıca alanı","ingilizce":"Thermal spa area","tanim":"Sıcak su kaynaklarıyla hizmet veren ve konukların dinlenme amaçlı kullandığı açık hava bölümüdür.","ornek":"Afyon’daki bir termal otelde dış havuz çevresindeki zeminler her sabah yıkanır.","sektor":"Kaplıca alanı da havuz ve plaj gibi ıslak zemin demektir; kayma riski nedeniyle zemin sık kontrol edilir.","iliskili":["kh1-5-185","kh1-5-226"],"kontrol":null,"gorsel":"t12e-acik-hava-kaplica"},{"id":"kh1-5-192","konu":"5.2.2","terim":"Bahçe ve parklar","ingilizce":"Gardens and parks","tanim":"Tatil amaçlı konaklama işletmelerinde konukların hoşça vakit geçirmesi için bitkilerle ve süs havuzlarıyla düzenlenmiş açık alanlardır.","ornek":"Belek’teki bir otelde konuklar kahvaltıdan sonra bahçedeki banklarda kitap okur.","sektor":"Konuk burada vakit geçirdiği için bank ve yollar temiz olmalıdır.","iliskili":["kh1-5-193","kh1-5-195","kh1-5-196"],"kontrol":null,"gorsel":"t11e-cicek-yatagi-kew"},{"id":"kh1-5-193","konu":"5.2.2","terim":"Peyzaj düzenlemesi","ingilizce":"Landscaping","tanim":"Bahçe, park ve yürüyüş alanlarının bitki ve yapılarla estetik ve kullanışlı biçimde düzenlenmesidir.","ornek":"Bodrum’daki bir otelin bahçesinde kaya, ağaç ve çiçekler yürüyüş yoluyla uyumlu yerleştirilmiştir.","sektor":"Bitki bakımı genellikle bahçıvanın işi olsa da çevre temizliği kat hizmetlerindedir.","iliskili":["kh1-5-192","kh1-5-194"],"kontrol":null,"gorsel":"g3-ekoturizm-tesisi"},{"id":"kh1-5-194","konu":"5.2.2","terim":"Süs havuzu","ingilizce":"Ornamental pond","tanim":"Bahçeyi güzelleştirmek amacıyla yapılan, yüzme için kullanılmayan küçük havuzdur.","ornek":"Marmaris’teki bir otelin bahçesindeki süs havuzu, girişteki konukları karşılar.","sektor":"Çevresindeki yaprak ve çöpler görünümü bozduğu için günlük kontrolde unutulmaz.","iliskili":["kh1-5-192","kh1-5-193"],"kontrol":null,"gorsel":"t10e-suhavuzu-bitkili"},{"id":"kh1-5-195","konu":"5.2.2","terim":"Bahçe mobilyası ve bank tozunun alınması","ingilizce":"Dusting garden furniture and benches","tanim":"Açık alandaki mobilya ve bankların nemli bezle silinerek tozlarının alınmasıdır.","ornek":"Sabah 08.00’de Belek’teki bir otelde görevli Murat, bahçedeki masa ve bankların tozunu nemli bezle alır.","sektor":"Konuk oturacağı yerin temiz olmasını bekler; tozlu bir bank oturmadan fark edilir ve bakımsız izlenim bırakır.","iliskili":["kh1-5-192","kh1-5-196"],"kontrol":null,"gorsel":"t11e-bahce-banki"},{"id":"kh1-5-196","konu":"5.2.2","terim":"Dökülen yaprakların ve çöplerin toplanması","ingilizce":"Collecting fallen leaves and litter","tanim":"Bahçe ve yürüyüş yollarında ağaçlardan dökülen yaprakların toplanması ve çöplerin süpürülmesidir.","ornek":"Sonbaharda Kaş’taki bir otelin yolunda görevli, her sabah yaprakları süpürüp çuvala koyar.","sektor":"Yaprak yığını ıslanınca kayganlaşır; konuğun düşmesine yol açabilir.","iliskili":["kh1-5-192","kh1-5-195"],"kontrol":null,"gorsel":"t10e-yaprak-yiginlari"},{"id":"kh1-5-197","konu":"5.2.2","terim":"Dış mekânda çöp kutusunun boşaltılması","ingilizce":"Emptying outdoor bins","tanim":"Bahçe, yürüyüş yolu, otopark ve spor alanındaki çöp kutularının boşaltılıp içine yeni poşet takılmasıdır.","ornek":"Her sabah ve öğleden sonra görevli, yürüyüş yolundaki çöp kutularını boşaltır ve yeni poşet takar.","sektor":"Taşan çöp kutusu hem görüntüyü hem hijyeni bozar; sıcak havada koku yayar.","iliskili":["kh1-5-192","kh1-5-196"],"kontrol":null,"gorsel":"t11e-dis-mekan-cop-kutusu"},{"id":"kh1-5-198","konu":"5.2.2","terim":"Aydınlatma ve levha kontrolü","ingilizce":"Checking lighting and signs","tanim":"Bahçe, yol ve alanlardaki aydınlatma direklerinin ve yönlendirme ya da uyarı levhalarının çalışıp çalışmadığına bakılmasıdır.","ornek":"Akşam yolundaki lambalardan biri yanmıyorsa görevli bunu teknik servise bildirir.","sektor":"Karanlık yol konuk güvenliğini tehdit eder; arıza gördüğünde görevli teknik servise haber verir.","iliskili":["kh1-5-192","kh1-5-197"],"kontrol":null},{"id":"kh1-5-199","konu":"5.2.2","terim":"Yürüyüş yolu","ingilizce":"Walkway","tanim":"Resort işletmelerinde aktivite alanları arasındaki geçişi sağlayan, peyzajı özenli yapılmış yollardır.","ornek":"Kemer’de plajdan restorana giden konuk, bitkilerle çevrili yürüyüş yolundan geçer.","sektor":"Yolda çöp, yaprak ve bozuk aydınlatma güvenlik ve görüntü sorunudur; günlük süpürülüp kontrol edilir.","iliskili":["kh1-5-197","kh1-5-200"],"kontrol":null,"gorsel":"t10e-bahce-yuruyus-yolu"},{"id":"kh1-5-200","konu":"5.2.2","terim":"Yönlendirme ve uyarı levhası","ingilizce":"Directional and warning sign","tanim":"Konuğa yönünü gösteren ya da dikkat etmesi gereken durumu bildiren işaret panolarıdır.","ornek":"Plaja giden yolun başındaki yön levhası kirliyse okunmaz; görevli onu siler.","sektor":"Okunmayan levha konukların kaybolmasına, uyarı levhası ise kazaya yol açabilir.","iliskili":["kh1-5-199","kh1-5-198"],"kontrol":null,"gorsel":"h5a-acil-cikis-levhasi"},{"id":"kh1-5-201","konu":"5.2.2","terim":"Otopark","ingilizce":"Car park","tanim":"Konukların araçlarını park ettiği, genellikle ana giriş kapısına yakın açık ya da kapalı alandır.","ornek":"Akşam 18.00’de otoparka gelen konuk aracını giriş kapısına yakın bölümde park eder.","sektor":"Otopark konuğun gördüğü ilk alanlardan biridir; yerdeki çöp ve izmarit ilk izlenimi düşürür.","iliskili":["kh1-5-202","kh1-5-203"],"kontrol":null,"gorsel":"t10e-otopark-park-yerleri"},{"id":"kh1-5-202","konu":"5.2.2","terim":"Açık ve kapalı otopark","ingilizce":"Open-air and covered car park","tanim":"Üstü açık ya da çatılı olabilen, işletmelerin araç park alanı türleridir.","ornek":"Şehir otelinin yer altında kapalı otoparkı vardır; resort otelin otoparkı ise açıktır.","sektor":"Kapalı otoparkta havalandırma kontrolü de temizliğe dahildir.","iliskili":["kh1-5-201","kh1-5-204"],"kontrol":null,"gorsel":"t10e-kapali-otopark-binasi"},{"id":"kh1-5-203","konu":"5.2.2","terim":"Sert süpürge ile otopark temizliği","ingilizce":"Sweeping car parks with a stiff broom","tanim":"Otopark zeminindeki çöp ve tozun sert süpürgeyle süpürülmesi işlemidir.","ornek":"Sabah 07.00’de Antalya’daki bir otelin açık otoparkında görevli Serkan, zemindeki çöp ve tozu sert süpürgeyle süpürür.","sektor":"Otopark zemini kaba kire uygun olarak sert süpürgeyle temizlenir; konuk aracından inerken temiz bir zemin görür.","iliskili":["kh1-5-201","kh1-5-197"],"kontrol":null,"gorsel":"t11e-sert-supurge-yol"},{"id":"kh1-5-204","konu":"5.2.2","terim":"Kapalı otoparkta havalandırma kontrolü","ingilizce":"Ventilation check for covered car parks","tanim":"Egzoz gazı ve kokunun birikmemesi için çatılı otoparktaki havalandırma sisteminin çalışıp çalışmadığına bakılmasıdır.","ornek":"Görevli kapalı otoparkı temizlerken havalandırmanın çalıştığını kontrol eder.","sektor":"Havalandırması arızalı kapalı alan egzoz gazı ve koku biriktirir; arıza teknik servise bildirilir.","iliskili":["kh1-5-202","kh1-5-201"],"kontrol":null,"gorsel":"t10e-yeralti-otopark"},{"id":"kh1-5-205","konu":"5.2.2","terim":"Açık spor alanı","ingilizce":"Outdoor sports facility","tanim":"Tenis kortu, basketbol ve futbol sahası gibi konukların açık havada spor yapabildiği tesislerdir.","ornek":"Belek’teki bir otelde konuklar sabah tenis oynar; akşam profesyonel bir kulüp kampı için futbol sahasını kullanır.","sektor":"Oteller açık spor alanlarını konukların yanında profesyonel spor kulüplerinin kamp ve antrenmanına da açabilir.","iliskili":["kh1-5-206","kh1-5-207","kh1-5-208"],"kontrol":null,"gorsel":"h3b-plaj-voleybolu"},{"id":"kh1-5-206","konu":"5.2.2","terim":"Spor alanı zemininin temizliği","ingilizce":"Cleaning sports surfaces","tanim":"Kortta, sahada ya da çim alanda zemin türüne uygun yöntemle süpürülmesi ya da çöplerin elle toplanması işlemidir.","ornek":"Sabah 08.00’de Belek’teki bir otelin tenis kortunda görevli Ayşe, zemini uygun süpürgeyle süpürür; çim sahada ise çöpleri elle toplar.","sektor":"Yöntem zemine göre seçilir; uygun olmayan yöntem zemine zarar verebilir.","iliskili":["kh1-5-205","kh1-5-207"],"kontrol":null,"gorsel":"t11e-acik-basketbol-sahasi"},{"id":"kh1-5-207","konu":"5.2.2","terim":"Tribün ve oturma alanlarının temizliği","ingilizce":"Cleaning stands and seating areas","tanim":"Spor alanındaki tribün ve oturma yerlerindeki çöplerin toplanması ve tozunun alınmasıdır.","ornek":"Maçtan sonra görevli tribündeki bardak ve çekirdek kabuklarını toplar, oturma yerlerini siler.","sektor":"İzleyiciler çöp bırakır; toplanmazsa ertesi gün kullanılmaz.","iliskili":["kh1-5-205","kh1-5-206"],"kontrol":null,"gorsel":"t11e-tribun-kirmizi-koltuk"},{"id":"kh1-5-208","konu":"5.2.2","terim":"Spor alanındaki giyinme kabini, tuvalet ve duşlar","ingilizce":"Sports facility changing rooms, toilets and showers","tanim":"Konuğun antrenman sonrası kullandığı giyinme kabini, tuvalet ve duşların temizlenip eksik sabun, kâğıt havlu ve tuvalet kâğıdının tamamlanmasıdır.","ornek":"Antrenmandan sonra görevli duşları temizler, eksik sabun ve tuvalet kâğıdını tamamlar.","sektor":"Sporcu duş ve kabini temiz bulmak ister; eksik sabun hemen fark edilir.","iliskili":["kh1-5-205","kh1-5-209"],"kontrol":null,"gorsel":"t11e-soyunma-dolaplari-bank"},{"id":"kh1-5-209","konu":"5.2.2","terim":"Arızanın teknik servise bildirilmesi","ingilizce":"Reporting faults to the technical service","tanim":"Aydınlatma, levha veya donanımdaki sorunu görevlinin kendisi onarmadan teknik servise haber vermesidir.","ornek":"Akşam 20.00’de görevli Elif, tenis kortunun aydınlatmasında yanmayan bir lamba görür ve onarmaya kalkmadan teknik servise bildirir.","sektor":"Temizlik görevlisi arızayı fark eder, onarımı yetkili teknik ekip yapar; bu hem güvenliği hem iş bölümünü korur.","iliskili":["kh1-5-208","kh1-5-198"],"kontrol":null},{"id":"kh1-5-210","konu":"5.2.2","terim":"Plaj","ingilizce":"Beach","tanim":"Konukların denize girerek güneşlendiği, dinlendiği ve eğlendiği dış mekân bölümüdür.","ornek":"Antalya’daki bir otelde konuklar sabah 10.00’dan akşama kadar plajda yüzer, güneşlenir ve içecek içer.","sektor":"Plaj tatil otelinin en önemli çekim merkezlerinden biridir; konuk zamanının çoğunu burada geçirdiği için plajdaki temizlik doğrudan memnuniyeti belirler.","iliskili":["kh1-5-211","kh1-5-212"],"kontrol":null,"gorsel":"g1-bos-plaj-salgin"},{"id":"kh1-5-211","konu":"5.2.2","terim":"Plajda yiyecek içecek çöpü","ingilizce":"Food and drink litter on the beach","tanim":"Konuklara plajda verilen yeme içme hizmetinden doğan, hızla toplanmazsa sıcakta kötü kokan atıklardır.","ornek":"Öğlen 13.00’te Side’deki bir otelin plaj barı yoğunken görevli, bardak ve tabak artıklarıyla dolan kutuların poşetlerini sık sık değiştirir.","sektor":"Çöp hızlı toplanmazsa sıcakta kötü koku yayılır; bu yüzden plajda çöp kutuları sık boşaltılır.","iliskili":["kh1-5-210","kh1-5-190"],"kontrol":null,"gorsel":"t11e-plaj-cop-kutulari"},{"id":"kh1-5-212","konu":"5.2.2","terim":"Plaj kum eleme ve temizleme makinesi","ingilizce":"Beach cleaning machine","tanim":"Genellikle traktörün arkasına bağlanan ve plajdaki istenmeyen otları, iri taşları ve çöpleri toplayan makinedir.","ornek":"Nisan ayında sezon açılmadan önce Kemer’deki bir otelde traktöre bağlı makine plajın üzerinden geçerek ot ve iri taşları toplar.","sektor":"Makine kumu elle toplanamayacak kadar geniş alanda tek seferde arındırır; işletmeler bunu sezon başında ve sonunda yapar.","iliskili":["kh1-5-210","kh1-5-213"],"kontrol":null,"gorsel":"t15af-plaj-temizleme"},{"id":"kh1-5-213","konu":"5.2.2","terim":"Plaja kum serilmesi","ingilizce":"Spreading sand on the beach","tanim":"Eleme ve temizlikten sonra gerektiğinde plaja yeni kum getirilip yüzeye serilmesi işlemidir.","ornek":"Sezon başı temizliği bittikten sonra Bodrum’daki bir otelde ince kalan kısma kum getirilip düzeltilir.","sektor":"Kum serme, temizliğin son adımıdır; plajın hem temiz hem düzenli görünmesini sağlar.","iliskili":["kh1-5-212","kh1-5-214"],"kontrol":null,"gorsel":"t11e-plaj-kum-serme-dozer"},{"id":"kh1-5-214","konu":"5.2.2","terim":"Sezon başı ve sonu plaj temizliği","ingilizce":"Start- and end-of-season beach cleaning","tanim":"İşletmelerin sezon başında ve sonunda plajı makine ile detaylı olarak temizlemesidir.","ornek":"Mayıs ayında sezon açılmadan, ekim sonunda ise sezon kapanırken Fethiye’deki bir otelde plaj makineyle detaylı temizlenir.","sektor":"Günlük işler plajı sezon boyunca temiz tutar; derin temizlik ise yılda iki kez yapılan ayrı bir işlemdir.","iliskili":["kh1-5-212","kh1-5-213"],"kontrol":null},{"id":"kh1-5-292","konu":"5.2.2","terim":"Su sporları alanı","ingilizce":"Water sports area","tanim":"Plajı olan konaklama işletmelerinde konukların su sporlarını yapabilmesi için ayrılmış özel alandır.","ornek":"Bodrum’daki bir otelde sabah 10.00’da konuklar plajın yanında ayrılmış bölümde su sporlarına başlar; görevli bölümün çevresindeki çöpleri toplar.","sektor":"Plajın bir parçası olarak çevresi de temiz tutulur; ayrıntılar işletmeye göre değişir.","iliskili":["kh1-5-210","kh1-5-214"],"kontrol":null,"gorsel":"t11e-jet-ski-lagun"},{"id":"kh1-5-215","konu":"5.2.2","terim":"Şezlong","ingilizce":"Sun lounger","tanim":"Konukların uzanarak güneşlendiği plaj ve havuz mobilyasıdır.","ornek":"Akşam 19.00’da konuklar plajdan ayrılınca görevli Serkan, şezlongları yıkar.","sektor":"Şezlong konuğun en çok temas ettiği plaj eşyasıdır; her gün konuklar ayrıldıktan sonra yıkanır.","iliskili":["kh1-5-217","kh1-5-216"],"kontrol":null,"gorsel":"t10e-sezlonglar-sira"},{"id":"kh1-5-216","konu":"5.2.2","terim":"Plaj sehpası","ingilizce":"Beach side table","tanim":"Şezlongların yanına konan, içecek ve eşya koymaya yarayan küçük masadır.","ornek":"Sabah 08.30’da plajda görevli Ayşe, sehpalar üzerindeki içecek artıklarını toplar ve sehpaları deterjanlı bezle siler.","sektor":"Dökülen içecek sehpada yapışkan iz bırakır; bu yüzden sehpalar sık ve deterjanlı bezle silinir.","iliskili":["kh1-5-215","kh1-5-218"],"kontrol":null},{"id":"kh1-5-217","konu":"5.2.2","terim":"Şezlong minderi","ingilizce":"Sun lounger cushion","tanim":"Şezlonga konan, rahat uzanmayı sağlayan yastık ya da döşemedir.","ornek":"Akşam 19.00’da görevli Murat, Çeşme’deki otelin plajında şezlong minderlerini toplar, üzerindeki kumu silkeler ve lekeli olanı temiz minderle değiştirir.","sektor":"Minderler her akşam toplanır; yıpranmış ve lekeli olanlar temiz minderle değiştirilir.","iliskili":["kh1-5-215","kh1-5-219"],"kontrol":null,"gorsel":"t11e-mindelli-sezlonglar"},{"id":"kh1-5-218","konu":"5.2.2","terim":"Plaj şemsiyesi","ingilizce":"Parasol","tanim":"Konukları güneşten koruyan, plajda ve havuz kenarında kullanılan şemsiyedir.","ornek":"Sabah 09.00’da Marmaris’teki otelde görevli plaj şemsiyelerini açıp kontrol eder, kolu gevşek olanı yenisiyle değiştirir.","sektor":"Arızalı şemsiye rüzgârda tehlikeli olabilir; bu nedenle kontrol edilir ve gün sonunda tümü toplanır.","iliskili":["kh1-5-215","kh1-5-219"],"kontrol":null,"gorsel":"t15af-plaj-semsiye"},{"id":"kh1-5-219","konu":"5.2.2","terim":"Plaj kapanışında malzemelerin toplanması","ingilizce":"End-of-day beach tidy-up","tanim":"Gün sonunda plaj hizmeti bittiğinde şezlong, şemsiye, sehpa ve minderlerin toplanarak korunmasıdır.","ornek":"Akşam 19.30’da plaj kapanınca Çeşme’deki bir otelde görevliler şezlong, şemsiye, sehpa ve minderleri toplar.","sektor":"Malzeme gece dışarıda kalırsa rüzgâr, nem ve kum zarar verir; toplama hem malzemeyi korur hem sabahki düzeni kolaylaştırır.","iliskili":["kh1-5-217","kh1-5-218"],"kontrol":null},{"id":"kh1-5-220","konu":"5.2.2","terim":"Plajda havlu dağıtımı ve takibi","ingilizce":"Beach towel distribution and tracking","tanim":"Konukların plajda kullandığı havluların toplanması ve plajdaki havlu dağıtım bölümü tarafından takip edilmesidir.","ornek":"Öğlen 14.00’te Alanya’daki bir otelin plajında havlu azalınca görevli Elif, temiz havlu getirir; havlu dağıtım bölümü hangi havlunun kimde olduğunu takip eder.","sektor":"Takip kaybolan havluların sayısını azaltır; konuğun elinde temiz havlu bulunması memnuniyeti artırır.","iliskili":["kh1-5-240","kh1-5-221"],"kontrol":null,"gorsel":"t10c-plaj-havlu-standi"},{"id":"kh1-5-221","konu":"5.2.2","terim":"Soyunma (üst değiştirme) kabini","ingilizce":"Changing cabin","tanim":"Konukların plajda ya da havuz kenarında kıyafetini değiştirdiği küçük kapalı bölümdür.","ornek":"Öğleden sonra 15.00’te görevli Elif, soyunma kabininin içine bakar, zemindeki kum ve suyu temizler; havuz kenarındaki üst değiştirme kabininde biriken suyu da tahliye eder.","sektor":"Konuk kabini kullanmadan önce temiz görmek ister; birikmiş kum ve su hem hijyeni hem güvenliği bozar. Kabin yüzeyleri ve gün içindeki dezenfeksiyon kabinin kullanım sıklığına göre yapılır. Havuz çevresinde aynı kabine üst değiştirme kabini denir; biriken su kaymaya yol açtığı için tahliye edilir.","iliskili":["kh1-5-222","kh1-5-223"],"kontrol":null,"gorsel":"t10e-plaj-kabinleri-pastel"},{"id":"kh1-5-222","konu":"5.2.2","terim":"Kabinde unutulan eşyanın teslimi","ingilizce":"Handing in items left in cabins","tanim":"Konuğun kabinde unuttuğu eşyanın gerekli yere teslim edilmesidir.","ornek":"Akşam 18.00’da görevli bir soyunma kabininde güneş gözlüğü bulur ve ön büroya teslim eder.","sektor":"Bulunan eşya kayıt altına alınır ve sahibine ulaştırılır; bu da konuğun işletmeye güvenini artırır. Bulunan eşya tutanakla ön büroya teslim edilir.","iliskili":["kh1-5-221","kh1-5-220"],"kontrol":null},{"id":"kh1-5-223","konu":"5.2.2","terim":"Plaj tuvaleti, lavabo ve duşları","ingilizce":"Beach toilets, basins and showers","tanim":"Plajda konukların kullandığı tuvalet, lavabo ve duşların özel kimyasalla temizlenip yıkanması, ayna ve musluğun su lekesi kalmayacak biçimde silinmesidir.","ornek":"Öğleden sonra 14.30’da görevli Murat, plaj tuvaletini kimyasalla temizler, aynayı ve muslukları silerek su lekesi bırakmaz.","sektor":"Plaj tuvaleti kumla ve suyla çabuk kirlenir; ayna ve musluktaki leke konuğun gözüne ilk çarpan ayrıntıdır.","iliskili":["kh1-5-221","kh1-5-224"],"kontrol":null,"gorsel":"t10e-plaj-wc-dus-blogu"},{"id":"kh1-5-224","konu":"5.2.2","terim":"Duş giderinde kum birikmesinin kontrolü","ingilizce":"Checking shower drains for sand","tanim":"Plajdaki duşlarda ve zeminde bulunan su giderlerinin kumla tıkanmasına karşı kontrol edilmesi işlemidir.","ornek":"Öğle 12.00’de görevli Serkan, plaj duşunun gideri yavaş akınca bunu fark eder ve tıkanmayı teknik servise bildirir.","sektor":"Kumla tıkanan gider suyun birikmesine ve kaymaya yol açar; görevli tıkanıklığı kendisi çözmeye çalışmadan teknik servise bildirir.","iliskili":["kh1-5-223","kh1-5-225"],"kontrol":null},{"id":"kh1-5-225","konu":"5.2.2","terim":"Plaj tuvaletinde sarf malzemesi tamamlama","ingilizce":"Restocking beach toilets","tanim":"Sıvı sabun, tuvalet kâğıdı ve kâğıt havlu gibi tükenen malzemelerin yeniden doldurulmasıdır.","ornek":"Her turun sonunda görevli Ayşe, plaj tuvaletindeki sıvı sabun, tuvalet kâğıdı ve kâğıt havlu eksiklerini tamamlar.","sektor":"Eksik sabun ya da kâğıt konuğun fark ettiği ilk eksikliklerdendir; bu yüzden her temizlik turunda kontrol edilir.","iliskili":["kh1-5-223","kh1-5-224"],"kontrol":null,"gorsel":"t12s-tuvalet-kagidi"},{"id":"kh1-5-226","konu":"5.2.2","terim":"Havuz","ingilizce":"Swimming pool","tanim":"Yüzmek, serinlemek ve dinlenmek için yapılmış su alanıdır.","ornek":"Öğleden sonra 14.00’te Belek’teki bir otelde konuk havuzda yüzer, sonra havuz kenarındaki şezlonga uzanır.","sektor":"Havuz da plaj gibi tatil otelinin önemli çekim merkezidir; konuklar yüzmek, serinlemek ve dinlenmek için buraları seçer. Havuzun kullanım saatleri işletme tarafından belirlenir ve konuklara duyurulur.","iliskili":["kh1-5-227","kh1-5-228"],"kontrol":null,"gorsel":"t10e-acik-havuz-palmiye"},{"id":"kh1-5-227","konu":"5.2.2","terim":"Açık ve kapalı havuz","ingilizce":"Outdoor and indoor pool","tanim":"Üstü açık ya da çatıyla kapalı olabilen, hizmet verdiği dönem de buna göre değişen havuz türleridir.","ornek":"Antalya’daki bir otelde açık havuz yalnızca yaz sezonunda hizmet verirken kapalı havuz yıl boyunca kullanılır.","sektor":"Plaj ve açık havuz yaz sezonu boyunca açık tutulur; kapalı havuz ise on iki ay hizmet verir.","iliskili":["kh1-5-226","kh1-5-229"],"kontrol":null,"gorsel":"t13c-kapali-havuz"},{"id":"kh1-5-228","konu":"5.2.2","terim":"Havuzun gelir kaynağı olması","ingilizce":"Pool as a revenue source","tanim":"İşletmenin havuzu abonelik ve etkinliklerle de kullanıma açarak gelir elde etmesidir.","ornek":"Cumartesi akşamı Kuşadası’ndaki bir otel havuz çevresini düğün yemeğine açar; hafta içi aynı havuz abone müşterilere hizmet verir.","sektor":"Havuz toplu yemek, düğün ve abonelik gibi etkinliklerle de kullanıldığından işletmenin önemli gelir kaynaklarındandır; bu yüzden çevresinin bakımlı olması gerekir.","iliskili":["kh1-5-226","kh1-5-227"],"kontrol":null,"gorsel":"t11e-otel-havuzu-sezlonglar"},{"id":"kh1-5-229","konu":"5.2.2","terim":"Su parkı","ingilizce":"Water park","tanim":"Havuzlara ek olarak kaydıraklar ve çeşitli etkinlikler bulunduran geniş alanlı tesistir.","ornek":"Antalya’daki büyük bir tatil köyünde çocuklar öğleden sonra su parkındaki kaydıraklarda oynar.","sektor":"Su parkı havuzlarla birlikte yalnızca geniş alanlı işletmelerde bulunur; kullanımı yoğun olduğundan çevre temizliği de çok iş çıkarır.","iliskili":["kh1-5-227","kh1-5-230"],"kontrol":null,"gorsel":"t11e-su-parki-havuzlari"},{"id":"kh1-5-230","konu":"5.2.2","terim":"Havuz suyu temizliğinde teknik servis","ingilizce":"Pool water maintenance by the technical service","tanim":"Havuzun suyunun temizliği ve dezenfeksiyonunun teknik servis tarafından görevlendirilen kişilerce günlük yapılmasıdır.","ornek":"Sabah 07.00’de Bodrum’daki otelde teknik servis görevlisi havuz suyunu kontrol eder ve dezenfeksiyon işlemini yapar.","sektor":"Havuz suyunun temizliği ve dezenfeksiyonu teknik servis görevlilerine aittir; kat hizmetleri havuz çevresini temizler.","iliskili":["kh1-5-229","kh1-5-231"],"kontrol":null,"gorsel":"t4-havuz-filtreleri"},{"id":"kh1-5-231","konu":"5.2.2","terim":"Havuz çevresinde görev paylaşımı","ingilizce":"Division of tasks around the pool","tanim":"Çöp toplama, şezlong ve şemsiye düzeni ile çevre temizliğinin kat hizmetlerinde, bitki bakımının ise bahçıvanda olduğu iş paylaşımıdır.","ornek":"Sabah Marmaris’teki bir otelde kat hizmetleri görevlisi şezlonglar ve çöpleri düzenlerken bahçıvan havuz kenarındaki bitkileri budar.","sektor":"İş bölümü işletmeden işletmeye değişebilir; yeni görevli sorumluluğunun nerede bittiğini sorarak öğrenir.","iliskili":["kh1-5-230","kh1-5-226"],"kontrol":null},{"id":"kh1-5-232","konu":"5.2.2","terim":"Ayak yıkama ve dezenfeksiyon alanı","ingilizce":"Footbath","tanim":"Konuğun havuza girmeden önce ayaklarını yıkadığı ve dezenfekte ettiği alandır.","ornek":"Sabah 08.30’da görevli Elif, Kemer’deki bir otelde havuz girişindeki ayak yıkama alanını temizler ve suyunu yeniler.","sektor":"Ayak yıkama alanı havuz suyunu temiz tutmaya yardım eder; bu yüzden günlük temizlenir ve suyu değiştirilir.","iliskili":["kh1-5-233","kh1-5-235"],"kontrol":null,"gorsel":"t15af-ayak-yikama-nozul"},{"id":"kh1-5-233","konu":"5.2.2","terim":"Havuz çevresindeki duşlar","ingilizce":"Pool showers","tanim":"Açık ve kapalı duşların sık kontrolü, temizliği, dezenfeksiyonu ve sabun ile şampuan eksiklerinin tamamlanmasıdır.","ornek":"Öğlen 12.30’da Çeşme’deki bir otelin havuz çevresinde görevli Murat duşları kontrol eder, temizler ve sabun, şampuan eksiklerini tamamlar.","sektor":"Konuk havuza girmeden ve çıktıktan sonra duş kullanır; duş çevresi temiz ve donanımlı olmalıdır.","iliskili":["kh1-5-232","kh1-5-221"],"kontrol":null,"gorsel":"t15af-havuz-dusu"},{"id":"kh1-5-235","konu":"5.2.2","terim":"Havuz çevresi genel tuvaletleri","ingilizce":"Poolside public toilets","tanim":"Havuzu kullanan konukların ihtiyacı için yapılmış, temizliği genel tuvaletlerle aynı işlemlerle yürütülen tuvaletlerdir.","ornek":"Öğle saatlerinde görevli Serkan, havuz yanındaki genel tuvaleti kontrol edip temizler.","sektor":"Havuz çevresindeki genel tuvaletlerin temizliği, genel tuvaletlerde uygulanan işlemlerle aynıdır; konuk yoğunluğu nedeniyle sık kontrol gerekir.","iliskili":["kh1-5-232","kh1-5-221"],"kontrol":null},{"id":"kh1-5-236","konu":"5.2.2","terim":"Taşma kanalı","ingilizce":"Overflow channel","tanim":"Havuz suyunun kenardan taşan fazlasını toplayıp süzen, havuzun teknik sistemine bağlı kanaldır.","ornek":"Sabah 09.00’da görevli Murat, havuz kenarındaki zemini temizlerken taşma kanalının ızgarasına dokunmaz; yalnızca kanal dışında kalan alanı temizler.","sektor":"Kanal havuzun teknik sisteminin parçasıdır ve bakımı teknik servise aittir; kat hizmetleri havuz çevresindeki zemini temizler. Görevli ızgarayı açmaya çalışmaz, tıkanma ya da arıza görürse bildirir.","iliskili":["kh1-5-233","kh1-5-235"],"kontrol":null},{"id":"kh1-5-237","konu":"5.2.2","terim":"Güneşlenme ve dinlenme alanı düzeni","ingilizce":"Sunbathing area setup","tanim":"Havuz açılmadan önce şezlong, minder ve şemsiyelerin düzenli yerleştirilmesidir.","ornek":"Sabah 08.45’te havuz açılmadan önce görevli Elif, Bodrum’daki bir otelde şezlong, minder ve şemsiyeleri düzenli biçimde yerleştirir.","sektor":"Havuz açılmadan önce hazır olan alan, konuğa ilk andan düzenli bir görünüm sunar; bu iş ilk yapılan işlerdendir.","iliskili":["kh1-5-238","kh1-5-241"],"kontrol":null,"gorsel":"t10f-cabana-havuz-kenari"},{"id":"kh1-5-238","konu":"5.2.2","terim":"Havuz çevresinde çöp ve kül tablası","ingilizce":"Litter and ashtrays around the pool","tanim":"Konuklar havuzdayken şezlonglar arasında dolaşılarak çöplerin toplanması ve kül tablalarının boşaltılmasıdır.","ornek":"Öğlen 13.00’te havuz konuklarla doluyken görevli Murat, şezlonglar arasında dolaşıp çöpleri toplar ve kül tablalarını boşaltır.","sektor":"Havuz açıkken çöp ve kül tablası sık kontrol edilmezse konuk dinlenirken rahatsız olur; bu iş gün içinde tekrarlanır.","iliskili":["kh1-5-237","kh1-5-239"],"kontrol":null},{"id":"kh1-5-239","konu":"5.2.2","terim":"Oda havlusunun havuzda kullanılmaması","ingilizce":"Room towels not used at the pool","tanim":"Odada kullanılan havluların havuz ve plajda kullanılmaması, bunun için havuz havlularının renginin farklı olmasıdır.","ornek":"Öğleden sonra konuk odasındaki havluyu havuza getirince görevli Ayşe, ona havuz havlusu verir.","sektor":"Oda havlusu ile havuz ve plaj havlusunun karışmaması için bunların renkleri farklıdır.","iliskili":["kh1-5-240","kh1-5-238"],"kontrol":null,"gorsel":"t12s-havuz-havlulari"},{"id":"kh1-5-240","konu":"5.2.2","terim":"Havuz havlusu dağıtım alanı","ingilizce":"Pool towel hut","tanim":"Plaj ve havuz havlularının konuklara dağıtıldığı, ıslak havluların geri alınarak çamaşırhaneye gönderildiği ayrılmış alandır.","ornek":"Akşamüstü görevli Serkan, Çeşme’deki otelin havuz kenarındaki dağıtım alanında ıslak havluları toplayıp çamaşırhaneye gönderir.","sektor":"Konuklara sürekli kuru havlu dağıtılır; genellikle bu iş genel alan görevlilerince yapılır. İşletmeye göre havluyu ayrı bir dağıtım bölümü ya da genel alan görevlisi takip eder.","iliskili":["kh1-5-239","kh1-5-220"],"kontrol":null,"gorsel":"t10k-havuz-havlu-kulubesi"},{"id":"kh1-5-241","konu":"5.2.2","terim":"Havuz kapanışında malzemelerin toplanması ve dezenfeksiyonu","ingilizce":"End-of-day pool tidy-up and disinfection","tanim":"Gün sonunda şezlong, şemsiye, sehpa ve minderlerin güvenceye alınmak için toplanıp dezenfekte edilmesidir.","ornek":"Akşam 19.30’da havuz kapanınca görevli Murat, şezlong, şemsiye, sehpa ve minderleri toplar ve dezenfeksiyon işlemini uygular.","sektor":"Havuz kapandıktan sonra malzemeyi toplamak onu güvenceye alır; dezenfeksiyon ertesi günün hijyenini sağlar.","iliskili":["kh1-5-237","kh1-5-240"],"kontrol":null},{"id":"kh1-5-242","konu":"5.2.3","terim":"Dış mekân temizliğinde meydan arabası","ingilizce":"Public area trolley for exterior cleaning","tanim":"Günlük dış mekân temizliğinde gereken araç ve malzemeleri temizlenecek alana taşımak için kullanılan arabadır.","ornek":"Sabah 07.45’te görevli Ayşe, malzemelerle dolu meydan arabasını meydan ofisinden alıp havuz çevresine götürür.","sektor":"Gerekli her şey arabada olduğunda görevli eksik malzeme için ofise dönmek zorunda kalmaz; bu da iş akışını hızlandırır.","iliskili":["kh1-5-133","kh1-5-244","kh1-5-245"],"kontrol":null,"gorsel":"t15af-dis-mekan-arabasi"},{"id":"kh1-5-244","konu":"5.2.3","terim":"Meydan arabasındaki renkli toz bezleri","ingilizce":"Colour-coded dusting cloths on the trolley","tanim":"Farklı yüzeylerin tozunu almak için arabada taşınan, renkleri yüzeye göre ayrılmış bezlerdir.","ornek":"Görevli Elif bahçedeki ahşap bank için bir renkte, tuvalet kapısı için başka renkte bezi kullanır ve bezleri karıştırmaz.","sektor":"Renk ayrımı bir alandaki kirin ya da mikrobun başka alana taşınmasını önler; renkleri işletme belirler.","iliskili":["kh1-5-242","kh1-5-245"],"kontrol":null,"gorsel":"t15af-renkli-toz-bezleri"},{"id":"kh1-5-245","konu":"5.2.3","terim":"Süpürge ve faraş","ingilizce":"Broom and dustpan","tanim":"Zemindeki kaba çöpleri süpürüp toplamak için kullanılan alet takımıdır.","ornek":"Sabah giriş merdivenindeki yaprakları süpüren görevli Murat, topladıklarını faraşla çöp torbasına aktarır.","sektor":"Önce kaba çöp alınır, sonra yüzey silinir; bu sıra zemini temiz ve çizilmeden bırakır.","iliskili":["kh1-5-242","kh1-5-246"],"kontrol":null,"gorsel":"t11e-sari-faras-fircasi"},{"id":"kh1-5-246","konu":"5.2.3","terim":"Mop aleti ve mop paspası","ingilizce":"Mop and mop pad","tanim":"Sert zeminleri silmek için kullanılan, mop paspası takılan saplı alettir.","ornek":"Teras zeminini temizleyen görevli Ayşe, sert zeminde temiz mop paspasını kullanır.","sektor":"Her alan için temiz paspas kullanmak kiri bir yerden başka yere taşımaz; kirli paspas ayrılır.","iliskili":["kh1-5-245","kh1-5-244"],"kontrol":null,"gorsel":"t11e-mop-paspasi-basligi"},{"id":"kh1-5-247","konu":"5.2.3","terim":"Tuvalet için eksik malzeme takımı","ingilizce":"Toilet supplies","tanim":"Tuvaletlerdeki eksik malzemeleri tamamlamak için arabada taşınan tuvalet kâğıdı, kâğıt havlu ve sabundur.","ornek":"Öğleden sonra 14.00’te plaj tuvaletinde kâğıt havlu bitince görevli Murat, arabasından yenisini alıp yerine koyar.","sektor":"Eksik sarf malzemesi arabada hazır olduğunda görevli tuvaleti hemen tamamlar ve konuk mağdur olmaz.","iliskili":["kh1-5-242","kh1-5-249"],"kontrol":null,"gorsel":"t15af-tuvalet-kagidi"},{"id":"kh1-5-248","konu":"5.2.3","terim":"Cam silme aleti","ingilizce":"Window squeegee","tanim":"Cam ve ayna yüzeylerini lekesiz silmek için kullanılan alettir.","ornek":"Sabah 08.00’de görevli Elif, girişteki camdaki parmak izlerini cam silme aletiyle lekesiz siler.","sektor":"Cam silme aleti suyu tek hamlede toplar ve çizgi bırakmaz; giriş camı konuğun ilk gördüğü yüzeylerden biridir.","iliskili":["kh1-5-247","kh1-5-249"],"kontrol":null,"gorsel":"t11e-cam-silme-lastigi"},{"id":"kh1-5-249","konu":"5.2.3","terim":"Deterjan, kimyasal temizleyici, cila ve parfüm","ingilizce":"Detergent, chemical cleaners, polish and air freshener","tanim":"Yüzeyi temizlemek, parlatmak ve kokulandırmak için arabada bulunan sıvı ve sprey ürünlerdir.","ornek":"Görevli Serkan, ahşap bankı silerken arabadaki ahşaba uygun cilayı seçer ve deterjanla karıştırmaz.","sektor":"Her yüzey için uygun ürün seçilir; ürünler birbirine karıştırılmaz ve etiketindeki talimata uyulur.","iliskili":["kh1-5-248","kh1-5-250"],"kontrol":null,"gorsel":"h3b-kimyasal-deposu"},{"id":"kh1-5-250","konu":"5.2.3","terim":"Çöp torbası ve sepet","ingilizce":"Bin liners and basket","tanim":"Çöp toplamak için kullanılan torba ile malzemeleri bir arada taşımayı sağlayan sepettir.","ornek":"Akşam 18.30’da görevli Ayşe, dolan çöp kutusunun torbasını çıkarıp arabadaki yedek torbayı takar.","sektor":"Yedek torbayı arabada taşıyan görevli işi yarım bırakmaz; sepet ise küçük malzemeleri bir arada tutar.","iliskili":["kh1-5-249","kh1-5-251"],"kontrol":null,"gorsel":"t11e-cop-torbali-sepet"},{"id":"kh1-5-251","konu":"5.2.3","terim":"Eldiven, maske ve uyarı levhası","ingilizce":"Gloves, mask and warning sign","tanim":"Arabada iş sağlığı ve güvenliği için taşınan koruyucu ekipman ve uyarı işaretidir.","ornek":"Terastaki ıslak zemini silmeden önce görevli Murat, eldivenini takar ve alanın girişine uyarı levhası koyar.","sektor":"Koruyucu ekipman işe başlamadan önce giyilir; levha ise konuğu ıslak zemine karşı uyarır.","iliskili":["kh1-5-250","kh1-5-247"],"kontrol":null,"gorsel":"t15af-eldiven-maske"},{"id":"kh1-5-252","konu":"5.2.3","terim":"Elektrik süpürgesi","ingilizce":"Vacuum cleaner","tanim":"Toz ve kuru kiri emen, elektrikle çalışan temizlik makinesidir.","ornek":"Sabah 07.30’da görevli Serkan, otelin girişindeki paspasta biriken kumu elektrik süpürgesiyle emer.","sektor":"Elektrik süpürgesi kuru kiri hızla alır; elektrikli olduğu için kablo ve priz kontrolü yapılır.","iliskili":["kh1-5-253","kh1-5-254"],"kontrol":null,"gorsel":"t15af-supurge-parke"},{"id":"kh1-5-253","konu":"5.2.3","terim":"Halı yıkama makinesi","ingilizce":"Carpet cleaning machine","tanim":"Halıları su ve deterjanla yıkayan makinedir.","ornek":"Cuma günü Kuşadası’ndaki bir otelde açık teras halısı halı yıkama makinesiyle yıkanır.","sektor":"Halı yıkama makinesi sıradan süpürmenin alamadığı derin kiri çıkarır. Elektrikle çalıştığı için kullanmadan önce kablo ve prizler kontrol edilir, kablo ve hortum çevreye fazla yayılmaz.","iliskili":["kh1-5-252","kh1-5-254"],"kontrol":null},{"id":"kh1-5-254","konu":"5.2.3","terim":"Sert yüzey yıkama ve cilalama makinesi","ingilizce":"Hard-floor washing and polishing machine","tanim":"Taş, mermer gibi sert zeminlerin hem yıkanmasını hem cilalanmasını sağlayan makinedir.","ornek":"Haftalık işlerde Çeşme’deki bir otelin giriş zemini sert yüzey makinesiyle yıkanıp cilalanır.","sektor":"Makine çalışırken ıslak zemin ve kablo riski doğar; bu yüzden uyarı levhası konur ve kablo kontrol edilir.","iliskili":["kh1-5-253","kh1-5-255"],"kontrol":null,"gorsel":"t10e-zemin-yikama-makinesi"},{"id":"kh1-5-255","konu":"5.2.3","terim":"Dezenfeksiyon ve sterilizasyon cihazı","ingilizce":"Disinfection and sterilisation device","tanim":"Yüzeylerdeki mikropları öldürmek için kullanılan cihazdır.","ornek":"Öğleden sonra görevli Ayşe, plaj kabinlerini ve ortak kullanılan dolapları dezenfeksiyon cihazıyla işler.","sektor":"Cihaz yüzeydeki mikrop sayısını azaltır; çok kişinin dokunduğu alanlarda hijyen için kullanılır.","iliskili":["kh1-5-254","kh1-5-252"],"kontrol":null,"gorsel":"t11e-sterilizator-hazne"},{"id":"kh1-5-256","konu":"5.2.3","terim":"Seyyar merdiven","ingilizce":"Step ladder","tanim":"Yüksek yerlerde çalışmak için yerinden taşınabilen merdivendir.","ornek":"Girişteki tabelayı silmek için görevli Murat, seyyar merdiveni getirir; iş arkadaşı Serkan merdiveni tutar.","sektor":"Seyyar merdiven yüksek yerlere ulaşmak içindir; sağlam olmalı ve çalışan yalnız bırakılmamalıdır.","iliskili":["kh1-5-257","kh1-5-034"],"kontrol":null,"gorsel":"t15ag-seyyar-merdiven"},{"id":"kh1-5-257","konu":"5.2.3","terim":"Ek elektrik kablosu","ingilizce":"Extension cable","tanim":"Makinelerin prize ulaşması için temizlik alanına taşınan yeterince uzun kablodur.","ornek":"Bahçede sert yüzey makinesi için prize uzak olduğundan görevli Elif, yeterince uzun bir ek kablo getirir.","sektor":"Kablo gerektiği kadar açılır ve ortalığa yayılmaz; bu hem takılmayı hem prizi korur.","iliskili":["kh1-5-256","kh1-5-254"],"kontrol":null,"gorsel":"t15ag-uzatma-kablosu"},{"id":"kh1-5-259","konu":"5.2.3","terim":"Meydan arabasının ofise dönüşü","ingilizce":"Returning the trolley to the office","tanim":"Temizlik bitince meydan arabası ve makinelerin ofise getirilmesi, temizlenmesi ve eksik malzemenin tamamlanmasıdır.","ornek":"Öğleden sonra 16.00’da görevli Ayşe, meydan arabasını ofise getirir, temizler ve eksik malzemeleri tamamlar.","sektor":"Araba temiz ve tam dolu teslim edildiğinde bir sonraki vardiya hemen çalışmaya başlar.","iliskili":["kh1-5-022","kh1-5-133"],"kontrol":null},{"id":"kh1-5-260","konu":"5.2.3","terim":"Çöp konteyneri","ingilizce":"Waste container","tanim":"Çöplerin tesisten gönderilmeden önce depolandığı büyük kutudur.","ornek":"Akşam görevli Murat, topladığı çöp torbalarını otelin arka tarafındaki çöp konteynerine boşaltır.","sektor":"Konteyner çöpün tesisten çıkmadan önce biriktiği yerdir; konuk alanından uzakta durur.","iliskili":["kh1-5-250","kh1-5-259"],"kontrol":null,"gorsel":"t10e-cop-konteynerleri"},{"id":"kh1-5-261","konu":"5.2.4","terim":"Dış mekân temizliğinin yapılması","ingilizce":"Carrying out exterior cleaning","tanim":"Dış mekânın planlı, doğru araç gereçle ve zamanında bakımla temiz tutulmasıdır.","ornek":"Sabah 07.30’da genel alanlar şefi planı verir; Elif dış mekân için gereken araçları seçip işe başlar.","sektor":"Konuklar işletmeye girmeden önce dış mekânı görür; doğru planlanan temizlik alanları sürekli bakımlı ve temiz tutar.","iliskili":["kh1-5-262","kh1-5-263","kh1-5-264"],"kontrol":null,"gorsel":"t12c-plaj-kum-makinesi"},{"id":"kh1-5-262","konu":"5.2.4","terim":"Doğru araç gereç","ingilizce":"Using the right tools","tanim":"Temizliğin yapılacak işe ve zemine uygun araç gereçle (mop, süpürge, tırmık, cam silme aleti gibi) yapılmasıdır.","ornek":"Sabah görevli Murat, sert zeminde mop, çim alanda tırmık kullanır; çimi süpürgeyle ezmez.","sektor":"Yanlış araç yüzeye zarar verir ya da işi uzatır; doğru araç işi hem hızlı hem güvenli yaptırır.","iliskili":["kh1-5-261","kh1-5-264"],"kontrol":null},{"id":"kh1-5-263","konu":"5.2.4","terim":"Araç gereçlerin zamanında bakımı","ingilizce":"Timely maintenance of equipment","tanim":"Temizlik araçlarının bakımının zamanında yapılmasıdır.","ornek":"Akşam görevli Ayşe, kullandığı makinenin filtresini temizleyip yerine koyar.","sektor":"Zamanında bakım yapılmayan araç bozulur ve temizliği aksatır.","iliskili":["kh1-5-261","kh1-5-262"],"kontrol":null},{"id":"kh1-5-264","konu":"5.2.4","terim":"Doğru yerde doğru malzeme","ingilizce":"Right product for the right surface","tanim":"Her yüzey için cila, deterjan ve temizleyici gibi ürünlerin o yüzeye uygun olanının seçilmesidir.","ornek":"Görevli Elif ahşap bankı silerken cilayı ahşap için, camı silerken cam temizleyicisini kullanır.","sektor":"Her alanda o alana uygun malzeme kullanılır; yanlış ürün yüzeye zarar verir.","iliskili":["kh1-5-262","kh1-5-261"],"kontrol":null},{"id":"kh1-5-270","konu":"5.2.4","terim":"Bahçe, park, yürüyüş yolu ve otopark temizliği uygulaması","ingilizce":"Garden, park, walkway and car park cleaning practice","tanim":"Okul bahçesinde yapılan, bahçe, park, yürüyüş yolu ve otoparkın günlük temizliğini adım adım uygulatan çalışmadır.","ornek":"Okul bahçesinde sabah 10.00’da başlayan çalışmada öğrenci Elif, yaprak toplama, çöp kutusu boşaltma ve aydınlatma kontrolü basamaklarını sırayla uygular.","sektor":"Ders materyaline göre süre 20 dakikadır; bu uygulama okul bahçesinde yapılır, öğrenci dış mekân işinin sırasını gerçek koşullara yakın yaşar.","iliskili":["kh1-5-272","kh1-5-271","kh1-5-274"],"kontrol":null},{"id":"kh1-5-271","konu":"5.2.4","terim":"Yaprak ve çöpün sert fırçayla süpürülmesi","ingilizce":"Sweeping leaves and litter with a stiff brush","tanim":"Ağaçlardan dökülen yaprakların ve yerdeki çöplerin sert fırça ile süpürülerek yüzeyin temizlenmesidir.","ornek":"Bahçe yolundaki yaprakları ve yerdeki çöpleri öğrenci Murat sert fırçayla süpürüp yüzeyi temizler.","sektor":"Yaprak ve çöp yoldan alınmazsa ıslanınca yol kayganlaşabilir; süpürmeden sonra yüzey temiz kalır.","iliskili":["kh1-5-270","kh1-5-272"],"kontrol":null,"gorsel":"t15ag-yaprak-supurme"},{"id":"kh1-5-272","konu":"5.2.4","terim":"Yeşil alanın tırmıkla temizlenmesi","ingilizce":"Raking green areas","tanim":"Çim ve yeşil alanlardaki yaprak ve çöplerin tırmıkla toplanmasıdır.","ornek":"Okul bahçesindeki çim alanda öğrenci Ayşe, yaprak ve çöpleri tırmıkla toplar.","sektor":"Yeşil alanlarda yaprak ve çöp tırmıkla toplanır; sert zeminlerde ise süpürge ve fırça kullanılır.","iliskili":["kh1-5-270","kh1-5-271"],"kontrol":null,"gorsel":"t10e-yaprak-yigini-tirmik"},{"id":"kh1-5-273","konu":"5.2.4","terim":"Toplanan çöpün sepete ya da konteynere konması","ingilizce":"Putting collected litter in the basket or container","tanim":"Süpürülüp toplanan atıkların rüzgârla dağılmaması için çöp sepetine, oradan da çöp konteynerine aktarılmasıdır.","ornek":"Süpürülüp toplanan çöpleri öğrenci Serkan, çöp sepetine ve oradan çöp konteynerine boşaltır.","sektor":"Toplanan çöp yerde bırakılırsa rüzgârla yeniden dağılır; konteynere gidene kadar sepette tutulur.","iliskili":["kh1-5-271","kh1-5-260"],"kontrol":null,"gorsel":"t15ag-cop-sepeti"},{"id":"kh1-5-274","konu":"5.2.4","terim":"Kullanım yoğunluğuna göre işlemin tekrarı","ingilizce":"Repeating tasks by usage","tanim":"Alanın kullanım yoğunluğuna göre temizlik işlemlerinin tekrarlanmasıdır.","ornek":"Kalabalık bir hafta sonunda görevli Elif, yürüyüş yolundaki temizlik turunu gün içinde birkaç kez tekrarlar.","sektor":"Alan ne kadar yoğun kullanılıyorsa temizlik o kadar sık tekrarlanır.","iliskili":["kh1-5-270","kh1-5-273"],"kontrol":null},{"id":"kh1-5-275","konu":"5.2.4","terim":"Plaj temizliği uygulaması","ingilizce":"Beach cleaning practice","tanim":"Atölyede plaj tuvaleti, lavabo, duş ve soyunma kabinlerinin temizliğini sırayla uygulama çalışmasıdır.","ornek":"Kat hizmetleri atölyesinde öğrenci Murat, kabin zeminini silmeden önce levhayı koyar, lavaboları temizler, zemini paspaslar ve bezleri renklerine göre ayırır.","sektor":"Ders materyaline göre plaj uygulaması 40 dakika sürer; diğer uygulamalar 20 dakikadır.","iliskili":["kh1-5-276","kh1-5-277","kh1-5-278"],"kontrol":null},{"id":"kh1-5-276","konu":"5.2.4","terim":"Güvenlik ve uyarı levhasının yerleştirilmesi ve toplanması","ingilizce":"Placing and collecting safety signs","tanim":"Kabin temizliğinden önce güvenlik levhası yerleştirilmesi, işten sonra toplanmasıdır.","ornek":"Kabin zeminini silmeden önce öğrenci Ayşe, kapıya uyarı levhasını koyar ve iş bitince levhayı toplar.","sektor":"Levha konuğu ıslak zemine karşı uyarır; temizlik süresince alan kullanım dışı kalır.","iliskili":["kh1-5-275","kh1-5-278"],"kontrol":null,"gorsel":"t11d-islak-zemin-kova"},{"id":"kh1-5-277","konu":"5.2.4","terim":"Lavaboların kimyasal ve sünger ile temizlenmesi","ingilizce":"Cleaning basins with chemical cleaner and sponge","tanim":"Plaj tuvaletindeki lavaboların temizlik ürünü ve sünger ya da bezle yıkanıp ayna ve musluklarla birlikte lekesiz silinmesidir.","ornek":"Öğrenci Serkan, plaj tuvaletinin lavabosunu kimyasal ve sünger ile yıkar, aynaları ve muslukları silerek kurular.","sektor":"Lavabo, ayna ve musluktaki su lekesi temizliğin eksik kaldığını gösterir; bu yüzden sonunda kuru bezle silinir.","iliskili":["kh1-5-275","kh1-5-278"],"kontrol":null,"gorsel":"t11d-sunger"},{"id":"kh1-5-278","konu":"5.2.4","terim":"Kabinin içinden başlayarak zemin paspaslanması","ingilizce":"Mopping from inside out","tanim":"Tuvalet ve kabin zeminlerinin içeriden başlayarak paspaslanması ve biriken su ile kumun temizlenmesidir.","ornek":"Öğrenci Elif, kabinin içinden başlayıp kapıya doğru ilerleyerek zemini paspaslar; biriken su ve kumu temizler.","sektor":"İçeriden dışarıya silmek temizlenen yere yeniden basılmasını engeller.","iliskili":["kh1-5-277","kh1-5-276"],"kontrol":null,"gorsel":"t11d-kova-mop"},{"id":"kh1-5-279","konu":"5.2.4","terim":"Oda parfümü sıkılması","ingilizce":"Applying air freshener","tanim":"Temizlikten sonra kabin ve tuvalet içine oda parfümü sıkılmasıdır.","ornek":"Kabin ve tuvaleti temizleyen öğrenci Murat, işi bitirince içeri oda parfümü sıkar.","sektor":"Parfüm temizlik bittikten sonra uygulanır; hoş koku temizlik hissini tamamlar.","iliskili":["kh1-5-278","kh1-5-280"],"kontrol":null,"gorsel":"t15ag-oda-spreyi"},{"id":"kh1-5-280","konu":"5.2.4","terim":"Temizlik bezlerinin renge göre ayrılması","ingilizce":"Sorting cloths by colour","tanim":"Kullanılan temizlik bezlerinin rengine göre farklı poşetlere konmasıdır.","ornek":"İş bitince öğrenci Ayşe, kullandığı temizlik bezlerini renklerine göre farklı poşetlere koyar.","sektor":"Renk ayrımı kirli bezlerin karışmasını önler; çamaşırhane bezleri alana göre yıkayabilir.","iliskili":["kh1-5-279","kh1-5-275"],"kontrol":null,"gorsel":"t12s-renkli-bezler"},{"id":"kh1-5-281","konu":"5.2.4","terim":"Havuz çevresi temizliği uygulaması","ingilizce":"Pool surround cleaning practice","tanim":"Atölyede havuz çevresindeki kabin, duş, tuvalet ve havlu dağıtım alanlarının temizliğini sırayla uygulama çalışmasıdır.","ornek":"Atölyede öğrenci Elif, havuz açılmadan önce şezlongları düzenler, gün içinde çöpleri toplar, kapanışta malzemeleri toplayıp dezenfekte eder.","sektor":"Ders materyaline göre süre 20 dakikadır; hazırlık adımları diğer uygulamalarla aynıdır.","iliskili":["kh1-5-282","kh1-5-283"],"kontrol":null},{"id":"kh1-5-282","konu":"5.2.4","terim":"Toplu giyinme alanındaki dolapların dezenfeksiyonu","ingilizce":"Disinfecting lockers in changing areas","tanim":"Çok kişinin dokunduğu boş eşya dolaplarının tozunun alınıp dezenfekte edilmesi işlemidir.","ornek":"Toplu giyinme alanında öğrenci Murat, boş dolapların tozunu alır ve dezenfeksiyon işlemini uygular.","sektor":"Çok kişinin dokunduğu dolap yüzeyleri hijyen riski taşır; dezenfeksiyon bu riski azaltır.","iliskili":["kh1-5-281","kh1-5-283"],"kontrol":null,"gorsel":"t11e-ahsap-dolaplar-numarali"},{"id":"kh1-5-283","konu":"5.2.4","terim":"Açık duş alanı zemininin temizliği","ingilizce":"Cleaning open shower floors","tanim":"Kayma riskine karşı açık duşların zemininin temizlenip fazla suyun uzaklaştırılmasıdır; plajdaki duşlarda kum da alınır.","ornek":"Öğrenci Ayşe, havuz kenarındaki açık duş alanının zeminini temizler ve fazla suyu uzaklaştırır.","sektor":"Açık duş zemini sık ıslandığı için kayma riski taşır; bu yüzden fazla su, plajda ise kum da uzaklaştırılır.","iliskili":["kh1-5-282","kh1-5-281"],"kontrol":null},{"id":"kh1-5-284","konu":"5.2.4","terim":"Dış mekân uygulamasında iş sonu toplama","ingilizce":"End-of-task tidy-up for exterior work","tanim":"Meydan arabasındaki dolu çöp torbasının yenilenmesi, süpürge, çekçek (lastikli cam silme aleti), fırça ve tırmığın yıkanıp kurumaya bırakılması, kirli bez, mop ve paspasların ayrı torbalarla çamaşırhaneye hazırlanmasıdır.","ornek":"Öğrenci Elif uygulamayı bitirince arabadaki dolu torbayı çıkarıp yenisini takar, süpürge ve tırmığı yıkar, kirli bezleri ayrı torbaya koyar.","sektor":"Her uygulama yaprağı aynı kapanış adımlarıyla biter; iç mekândaki karşılığı “Uygulama sonu toplama” kartındadır. Aletler temiz ve kuru saklanırsa uzun ömürlü olur ve bir sonraki alana kir taşımaz.","iliskili":["kh1-5-147","kh1-5-287"],"kontrol":null},{"id":"kh1-5-287","konu":"5.2.4","terim":"Meydan arabasının tozunun alınması","ingilizce":"Dusting the trolley","tanim":"İş bitiminde meydan arabasının tozunun alınarak temizlenmesidir.","ornek":"En son işte öğrenci Ayşe, meydan arabasının üzerindeki tozu alıp ofise temiz bırakır.","sektor":"Meydan arabasının tozu da son adımdır; temiz araç bir sonraki görevliyi kirli ekipmanla başlatmaz.","iliskili":["kh1-5-284","kh1-5-259"],"kontrol":null}],"sorular":[{"id":"kh1-5-s001","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi genel alan sayılmaz?","secenekler":["Dördüncü kattaki 412 numaralı konuk odası","Zemin kattaki idare ofisi ve evrak arşivi","Personelin kullandığı soyunma odası","Konuklara açık otel içi spor salonu"],"dogru":0,"aciklama":"Genel alan, konuk odaları dışında kalan konuk ve personel alanlarıdır. İdare ofisi, soyunma odası ve spor salonu bu gruptadır.","konu":"5.1"},{"id":"kh1-5-s002","tur":"coktan-secmeli","soru":"Genel alanların temizliği konuk odası kadar önemli sayılır. Asıl neden hangisidir?","secenekler":["Bu alanlar yalnızca otelde konaklayan konuklar tarafından kullanılır","Konuk otel hakkındaki ilk izlenimini bu alanlarda gördüklerinden edinir","Genel alanlar konuk odalarına göre çok daha pahalı malzemelerle döşenmiş olur","Bu alanların temizliği yasal olarak odalardan önce yapılmak zorundadır"],"dogru":1,"aciklama":"Konuk kapıdan girince önce lobiyi görür; kalmayı düşünen ziyaretçiler de bu alanlara bakarak karar verir. Alanları yalnız konaklayan konuk kullanmaz.","konu":"5.1"},{"id":"kh1-5-s003","tur":"coktan-secmeli","soru":"Öğleden sonra lobide bir bardak meyve suyu devrildi ve zemin ıslandı. Meydancı olarak ilk işin ne olur?","secenekler":["Zeminin gece temizliğinde silinmesini beklemek","Lobiyi kapatıp konukları başka bir alana yönlendirmek","Uyarı levhasını koyup dökülen sıvıyı hemen temizlemek","Şefe haber verip onay gelene kadar beklemek"],"dogru":2,"aciklama":"Kapısı kapatılamayan alanlarda dökülmeye fark edilir edilmez müdahale edilir. Lobi kapatılamaz; onay beklemek düşme riskini uzatır.","konu":"5.1"},{"id":"kh1-5-s004","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi konukların az olduğu gece saatlerine bırakılan ağır bakım işlerindendir?","secenekler":["Lobi mermerinin cila makinesiyle yenilenmesi","Dökülen içeceğin vakit kaybetmeden silinmesi","Çöp kovasının tur sırasında boşaltılması","Taşan çöp poşetinin hemen değiştirilmesi"],"dogru":0,"aciklama":"Cilalama özel makine ister ve zemini bir süre kullanılamaz kılar. Diğer üç iş anında yapılan küçük müdahalelerdir.","konu":"5.1"},{"id":"kh1-5-s005","tur":"coktan-secmeli","soru":"Yoğun kullanılan genel alanlarda cilalama gibi ağır bakım işleri neden çoğunlukla gece yapılır?","secenekler":["Konuk az olduğundan rahatsızlık ve kayma riski azalır","Gündüz bu makinelerin kullanımı mevzuatla yasaklanmıştır","Gece vardiyasındaki personel daha deneyimli olur","Temizlik kimyasalları yalnızca gece saatlerinde etki eder"],"dogru":0,"aciklama":"Makine gürültüsü ve ıslak zemin konuğu rahatsız eder, düşme riski doğurur. Gece bu etkiler en aza iner.","konu":"5.1"},{"id":"kh1-5-s006","tur":"coktan-secmeli","soru":"Genel alanlar şefi ile meydancı arasındaki iş bölümü hangisidir?","secenekler":["Şef sahada temizlik yapar, meydancı çizelgeyi hazırlar","Şef yalnız personel, meydancı yalnız konuk alanından sorumludur","İkisi aynı işi yapar, fark yalnızca unvandadır","Şef planlar ve denetler, meydancı sahada temizlik yapar"],"dogru":3,"aciklama":"Şef çalışma planını kurar ve denetler; meydancı bu plana göre alanları temizler. Alan paylaşımı yoktur.","konu":"5.1"},{"id":"kh1-5-s007","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi genel alanlar şefinin görevi değildir?","secenekler":["Genel alandaki teknik arızayı kendisi onarmak","Arızayı teknik servise bildirip giderilmesini denetlemek","Malzeme ihtiyacını belirleyip temin etmek","Günlük ve periyodik temizlik işlerini düzenlemek"],"dogru":0,"aciklama":"Şef arızayı bildirir ve giderilmesini denetler; onarım teknik servisin işidir.","konu":"5.1"},{"id":"kh1-5-s008","tur":"coktan-secmeli","soru":"Genel alanlar şefine bağlı çalışan meydancının sektörde kullanılan İngilizce unvanlarından biri hangisidir?","secenekler":["Housekeeping room attendant","Public area attendant","Bell attendant (bellboy)","Laundry area attendant"],"dogru":1,"aciklama":"Meydancı public area attendant ya da houseman olarak da anılır ve genel alanları temizler; room attendant ise konuk odalarını temizleyen görevlidir.","konu":"5.1"},{"id":"kh1-5-s009","tur":"coktan-secmeli","soru":"Meydancı Kemal koridordaki apliğin yanıp söndüğünü fark etti. Doğru davranış hangisidir?","secenekler":["Arızayı fark eder etmez şefine bildirmek","Apliğin ampulünü kendisi değiştirip konuyu kimseye söylememek","Elektrik panosundan sigortayı kendi kararıyla indirmek","Arızayı geçiştirip sonra bakmak"],"dogru":0,"aciklama":"Meydancı teknik arıza ve hasarı amirine bildirir. Elektrik işine yetkisiz müdahale riskli ve yetki dışıdır.","konu":"5.1"},{"id":"kh1-5-s010","tur":"coktan-secmeli","soru":"Toplantı odasının perdesine kahve döküldü. Meydancının uygun davranışı hangisidir?","secenekler":["Kirli perdeyi temiziyle değiştirip kirliyi çamaşırhaneye göndermek","Lekeyi sert bir fırçayla perde yerindeyken ovalamak ve kurutmak","Perdeyi olduğu gibi bırakıp toplantı bitene kadar beklemek ve sonra bakmak","Perdeyi gizlice başka bir salonun perdesiyle değiştirip kimseye söylememek"],"dogru":0,"aciklama":"Genel alanlarda kirlenen perde ve tül çıkarılıp yerine temizi takılır. Yerinde ovmak kumaşa zarar verebilir.","konu":"5.1"},{"id":"kh1-5-s011","tur":"dogru-yanlis","soru":"Meydancı, genel alanda unutulmuş bir eşya bulursa yerini değiştirmeden konuk kendisi bulana kadar bırakır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Unutulan eşya amire haber verilerek ilgili birime teslim edilir; yerinde bırakılan eşya kaybolabilir.","konu":"5.1"},{"id":"kh1-5-s012","tur":"coktan-secmeli","soru":"Meydancı lobide unutulmuş bir telefon buldu. Doğru davranış hangisidir?","secenekler":["Sahibi gelene kadar kendi dolabında güvenle saklamak","Bulunduğu yerde bırakıp işine devam etmek","Telefonu açıp rehberden sahibine ulaşmaya çalışmak","Amirine haber verip ilgili birime teslim etmek"],"dogru":3,"aciklama":"Eşya kayıt altına alınarak ilgili birime teslim edilir. Gizlice saklamak ya da kurcalamak güveni zedeler.","konu":"5.1"},{"id":"kh1-5-s013","tur":"coktan-secmeli","soru":"Meydancı neden yanında çöp poşeti, bez ve eldiven bulundurur?","secenekler":["Dökülmelere malzeme aramadan müdahale etmek için","Konuklara küçük ikramlar yapabilmek için","Şefe işini yaptığını göstermek için","Üniformasının zorunlu bir parçası sayıldığı için"],"dogru":0,"aciklama":"Anında müdahale hazırlıklı olmaya bağlıdır. Malzeme aramak süreyi uzatır ve konuğu bekletir.","konu":"5.1"},{"id":"kh1-5-s014","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi iyi bir meydancının özelliği sayılmaz?","secenekler":["Kullandığı makineleri temizleyip depoya kaldırmak","Teknik arızaları bildirmeden kendi kendine çözmeye çalışmak","Görev yerindeki sorunlara müdahale edip çözebildiklerini çözmek","Bölgesinde gereken tüm gereçleri ve yedek paspası bulundurmak"],"dogru":1,"aciklama":"Çözemediği ve teknik olan arızaları şefine ve teknik servise bildirir. Bildirimsiz müdahale kuralın dışına çıkmaktır.","konu":"5.1"},{"id":"kh1-5-s015","tur":"coktan-secmeli","soru":"Araç gerecin bakımıyla ilgili hangi uygulama doğrudur?","secenekler":["Kullanım sonrası temizleyip kurutarak depodaki yerine koymak","Ertesi sabah tekrar kullanmak üzere kirli hâliyle arabada bırakmak","Yıkamadan depo girişine yığıp vardiyadan çıkmak","Yalnızca bozulduğunda temizleyip bakım yapmak"],"dogru":0,"aciklama":"Temiz ve düzenli saklanan araç gereç uzun ömürlüdür ve ertesi gün eksiksiz bulunur.","konu":"5.1"},{"id":"kh1-5-s016","tur":"dogru-yanlis","soru":"Meydancı, görev yerindeki sorunlardan çözebildiklerini kendisi çözer, çözemediklerini şefine bildirir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Görevini sahiplenen personel sorunlara müdahale eder; çözemediği durumu geciktirmeden amirine bildirir.","konu":"5.1"},{"id":"kh1-5-s017","tur":"coktan-secmeli","soru":"İç mekânlarda günlük temizlik için alanın kapatılamamasının nedeni hangisidir?","secenekler":["Alan kapatıldığında kimyasal kullanımının yasak olması","Temizlik personelinin sayısının yetersiz olması","Bu alanların kapılarının bulunmaması","Konukların bu alanları sürekli kullanması"],"dogru":3,"aciklama":"İç mekânlar konukların vakit geçirdiği ve hizmet aldığı alanlardır; bu nedenle işler konuk varken ve onu rahatsız etmeden yapılır.","konu":"5.1.1"},{"id":"kh1-5-s018","tur":"coktan-secmeli","soru":"Öğleden sonra lobide oturan konukların yanında toz almak gerekiyor. En uygun davranış hangisidir?","secenekler":["Sakin hareket edip araçları geçiş yolundan uzak tutmak","Konuklar kalkana kadar toz almayı ertelemek","Lobiyi şeritle kapatıp konuklardan ayrılmalarını rica etmek","Bezi sık sık çırparak hızlı çalışıp işi bitirmek"],"dogru":0,"aciklama":"Alanlar kapatılmadığından temizlik konuk rahatsız edilmeden yapılır. Bez çırpmak tozu savurur.","konu":"5.1.1"},{"id":"kh1-5-s019","tur":"coktan-secmeli","soru":"Periyodik ya da daha detaylı temizlik işleri ne zaman yapılır?","secenekler":["Konukların alanı en yoğun kullandığı saatlerde hızlıca","Her sabah alan tamamen kapatılarak","Yalnızca otel yıllık bakım için kapandığında","Konukların alanı kullanmadığı zamanlarda"],"dogru":3,"aciklama":"Detaylı temizlik alanın kullanımını etkilediği için konuk kullanmadığı saatlere planlanır.","konu":"5.1.1"},{"id":"kh1-5-s020","tur":"coktan-secmeli","soru":"Islak paspas yapılırken kayma ve düşme tehlikesini doğrudan belirten levha hangisidir?","secenekler":["Servis Dışı","Sizin İçin Temizleniyor","Kullanım Dışı Alan","Dikkat Kaygan Zemin"],"dogru":3,"aciklama":"Diğer levhalar alanın hizmet durumunu bildirir; kaygan zemin levhası ise doğrudan düşme riskini belirtir.","konu":"5.1.1"},{"id":"kh1-5-s021","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi iç mekân temizliğinde yanlış güvenlik uygulamasıdır?","secenekler":["Kablonun kullanılmayan kısmını makine koluna veya omuza toplamak","Islak zeminde kaymaz tabanlı ayakkabı giymek","Elektrikli süpürgenin kablosunu zemine yayılmış bırakmak","Ağır bir sehpayı bir arkadaşın yardımıyla taşımak"],"dogru":2,"aciklama":"Yayılmış kablo konukların takılıp düşmesine yol açar; kablonun kullanılmayan kısmı makine kolunda ya da omuzda toplanır.","konu":"5.1.1"},{"id":"kh1-5-s022","tur":"coktan-secmeli","soru":"Lobi tavanındaki apliği silmen gerekiyor. Hangi hazırlık doğrudur?","secenekler":["Elektrik açıkken nemli bezle hızlıca silmek","Sandalyenin üzerine çıkıp tek başına silmek","Elektriği kesip sağlam merdivende arkadaşının desteğiyle çalışmak","Elektriği kapatıp merdivende hiç destek almadan tek başına çalışmak"],"dogru":2,"aciklama":"Aydınlatma temizliğinden önce elektrik kesilir; yüksekte çalışırken sağlam merdiven ve refakat eden bir personel gerekir.","konu":"5.1.1"},{"id":"kh1-5-s023","tur":"coktan-secmeli","soru":"Ağır bir sehpayı çekmeden önce dizlerini bükerek durmanın ve gerekirse yardım istemenin amacı nedir?","secenekler":["Sehpanın zeminde iz bırakmasını önlemek","Omuriliğe fazla yük binmesini önlemek","İşi daha kısa sürede bitirmek","Sehpa hasarında sorumluluğu paylaşmak"],"dogru":1,"aciklama":"Yanlış kaldırma omurga sakatlığına yol açar; doğru pozisyon ve yardım bunu önler.","konu":"5.1.1"},{"id":"kh1-5-s024","tur":"coktan-secmeli","soru":"Tuvalette asidik temizleyiciyi çamaşır suyuyla aynı anda kullanmak neden yanlıştır?","secenekler":["Çamaşır suyu asidik ürünü tamamen etkisiz bırakıp işe yaramaz hâle getirir","Birlikte kullanılınca yüzeyde kalıcı bir leke bırakırlar","Ürünler birlikte kullanılınca çok çabuk tükenir","Bazı ürünlerin birlikte kullanılması zehirli gaz oluşturur"],"dogru":3,"aciklama":"Belirli kimyasalların karışımı zehirli gaz çıkarır; bu yüzden ürünler ayrı kullanılır, alan havalandırılır.","konu":"5.1.1"},{"id":"kh1-5-s025","tur":"coktan-secmeli","soru":"Yeni bir cam temizleme sıvısı aldın. Kullanmadan önce ilk yapman gereken hangisidir?","secenekler":["Eski sıvıyla karıştırarak daha güçlü hâle getirmek","Etiketini ve kullanım talimatını okumak","Kokusuna bakarak ne işe yaradığını anlamak","Doğrudan cama sıkıp sonucunu görmek"],"dogru":1,"aciklama":"Kimyasalın içeriği ve kullanım talimatı bilinmeden kullanılmaz; uyarılara uyulur.","konu":"5.1.1"},{"id":"kh1-5-s026","tur":"coktan-secmeli","soru":"Personele kapasitesinin üzerinde iş yüklenmesi neden sakıncalıdır?","secenekler":["Temizlik malzemesi çok daha çabuk tükenir ve stok sorunu çıkar","Aşırı yorulan ve acele eden personelde kaza riski artar","Otele gelen konuk sayısı zorunlu olarak azalır","Makineler beklenenden daha sık bozulur"],"dogru":1,"aciklama":"Temizlik işleri bir plana göre yapılır; aşırı iş yükü kazaya ve hataya yol açar.","konu":"5.1.1"},{"id":"kh1-5-s027","tur":"dogru-yanlis","soru":"İlk yardım bilgisi yalnızca sağlık personelinin sahip olması gereken bir bilgidir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Genel alan görevlisinin de kazalara karşı ilk yardım bilgisine sahip olması beklenir.","konu":"5.1.1"},{"id":"kh1-5-s028","tur":"coktan-secmeli","soru":"Lobide konukların dinlendiği ya da misafirleriyle görüştüğü salon alanı günümüzde hangi adla da anılır?","secenekler":["Fuaye alanı","Concierge servisi","Meydan ofisi","Lounge salonu"],"dogru":3,"aciklama":"Lounge, lobide dinlenme ve görüşme için ayrılmış salon alanıdır. Fuaye toplantı alanlarının önündeki ara alandır.","konu":"5.1.2"},{"id":"kh1-5-s029","tur":"coktan-secmeli","soru":"Sabah lobide temizlik başlarken concierge ekibinin bıraktığı bavullar temizlenecek alanı kapatıyor. En uygun çözüm hangisidir?","secenekler":["Temizliği o gün tümüyle iptal etmek","Planları birbirine göre ayarlayıp iş birliği yapmak","Bavulları kendi başına başka yere taşımak","Concierge ekibinden bavullarla birlikte alandan hemen ayrılmasını istemek"],"dogru":1,"aciklama":"Organizasyon yapısına göre lobi temizliğinde housekeeping ve concierge iş birliği yapabilir.","konu":"5.1.2"},{"id":"kh1-5-s030","tur":"coktan-secmeli","soru":"Yoğun saatlerde lobide yapılması uygun olan iş hangisidir?","secenekler":["Mermer zeminin cila makinesiyle yenilenmesi","Halıların tamamen yıkanıp kurutulması","Kapalı dolap ve radyatör aralarında detaylı toz alma","Alanı kontrol edip küçük müdahale yapmak"],"dogru":3,"aciklama":"Genel temizlik sakin saatte yapılır; yoğun saatlerde kontrol ve küçük müdahale yeterlidir.","konu":"5.1"},{"id":"kh1-5-s031","tur":"coktan-secmeli","soru":"Aynı bezle hem lobideki tezgâhı hem de camı silmek neden sakıncalıdır?","secenekler":["Cam yüzeyler yalnızca kâğıt havluyla silinir, bezle silinmez","Aynı bez iki yüzeyde daha çabuk eskir","Kir bir yüzeyden diğerine taşınır, renk kuralı bozulur","Bez renkleri yalnızca görünüş içindir ve hiçbir önemi yoktur"],"dogru":2,"aciklama":"Her yüzey için işletmenin belirlediği renk dışında bez kullanılmaz; böylece kir ve mikrop yayılmaz.","konu":"5.1.2"},{"id":"kh1-5-s032","tur":"coktan-secmeli","soru":"Toz alırken yüzeye önce temizleyici sıkıp nemlendirmenin asıl amacı nedir?","secenekler":["Tozu havaya savurmadan bezde toplamak","Yüzeyi tamamen dezenfekte etmek","Bezin ömrünü uzatmak ve yıpranmasını önlemek","Yüzeye ince bir cila tabakası yedirmek"],"dogru":0,"aciklama":"Nemli yüzey tozu havaya karıştırmaz; kuru bez tozu savurabilir.","konu":"5.1.2"},{"id":"kh1-5-s033","tur":"coktan-secmeli","soru":"Toz alma bitti. Kullandığın kırmızı, mavi ve sarı bezleri ne yaparsın?","secenekler":["Bezleri karıştırıp tek bir poşete doldururum","Her rengi arabadaki kendi kirli poşetine koyarım","Silkeleyip arabaya geri asarım, ertesi gün kullanırım","Personel lavabosunda elle yıkayıp sererim"],"dogru":1,"aciklama":"Bezler renklerine göre ayrılır ve mesai sonunda çamaşırhaneye teslim edilir.","konu":"5.1.2"},{"id":"kh1-5-s034","tur":"coktan-secmeli","soru":"İş planında “radyatör araları ve yangın dolabının üstü” yazıyor. Bu iş hangi tür temizliktir?","secenekler":["Günlük toz alma işlemi","Sterilizasyon uygulaması","Detaylı toz alma","Cilalama işlemi"],"dogru":2,"aciklama":"Günlük yapılmayan, iş planına göre belirli aralıklarla yapılan toz alma detaylı toz almadır.","konu":"5.1.2"},{"id":"kh1-5-s035","tur":"coktan-secmeli","soru":"Mermer lobiyi ıslak paspaslarken doğru ilerleme yönü hangisidir?","secenekler":["Ana kapıdan başlayıp içeriye doğru","Ortadan başlayıp kenarlara doğru yayılarak","Ana kapıya en uzak yerden başlayıp çıkış kapısına doğru","En kalabalık köşeden başlayıp diğer uca doğru ilerleyerek"],"dogru":2,"aciklama":"Islak paspasta kapıya en uzak yerden başlanır ve S çizerek çıkış kapısına doğru ilerlenir; böylece temizlenen yere yeniden basılmaz.","konu":"5.1.2"},{"id":"kh1-5-s036","tur":"coktan-secmeli","soru":"Mermer zemin ıslak paspaslanmadan önce zeminde hangi hazırlık yapılır?","secenekler":["Zemin cilalanır, sonra makineyle parlatılıp mopla silinir","Zemin bol suyla yıkanır, sonra süpürülüp kurulanır","Eski cila sökülür, sonra zemin siyah pedle ovalanır","Zemin süpürülür, sonra kuru mopla tozdan arındırılır"],"dogru":3,"aciklama":"Önce zemin süpürülür ve kuru mopla tozdan arındırılır, sonra ıslak paspas yapılır; yıkama, cilalama ya da cila sökme bu hazırlığın yerine geçmez.","konu":"5.1.2"},{"id":"kh1-5-s037","tur":"coktan-secmeli","soru":"Cila sökücü kimyasalla hazırlanmış su ve siyah sert ped hangi işlem için kullanılır?","secenekler":["Yeni cilanın zemine yedirilmesi","Cilalı zeminin son parlatılması","Zeminin günlük olarak toz alınması","Eski cilanın sökülüp temizlenmesi"],"dogru":3,"aciklama":"Yeni cila sürülmeden önce eski cila siyah sert pedle sökülür; yedirme ve parlatma ayrı adımlardır.","konu":"5.1.2"},{"id":"kh1-5-s038","tur":"coktan-secmeli","soru":"Eski cila sökülmeden üzerine yeni cila sürülürse ne olur?","secenekler":["Katlar birikir, zemin lekeli ve kirli görünür","Yeni cila zemine hiç tutunmaz ve akar","Zemin çok daha dayanıklı ve parlak olur","Makine ped kullanmadan çalışabilir hâle gelir"],"dogru":0,"aciklama":"Eski cila önce sökülür; aksi hâlde eski cilanın kiri yeni cilanın altında kalır.","konu":"5.1.2"},{"id":"kh1-5-s039","tur":"coktan-secmeli","soru":"Cila makinesini alana getirmeden önce neyi kontrol edersin?","secenekler":["Pedin rengini, su tankının sıcaklığını ve model numarasını","Zeminin ne zamandır cilasız olduğunu","Makinenin taşıma ağırlığını ve boyutunu","Çalışma durumunu, kablo ve fişte kaçak olup olmadığını"],"dogru":3,"aciklama":"Kaçak akım iş kazasına yol açabilir; makine çalışmadan önce emniyet açısından kontrol edilir.","konu":"5.1.2"},{"id":"kh1-5-s040","tur":"coktan-secmeli","soru":"Cila sürüldükten sonra makineyle ovalamanın amacı nedir?","secenekler":["Cilayı hızla kurutup zemin üzerinde sertleştirmek","Cilayı zeminden tekrar sökmek","Sürtünme ısısıyla cilayı zemine yedirmek","Zemini ıslatıp serinletmek"],"dogru":2,"aciklama":"Makine sürtünmeyle oluşan ısıyla cilayı zemine yedirir; ders materyaline göre bu işlem cilayı kurutmayacak biçimde yapılır.","konu":"5.1.2"},{"id":"kh1-5-s041","tur":"coktan-secmeli","soru":"Taş ya da mermer yüzeyli koridor ve merdivende doğru temizlik sırası hangisidir?","secenekler":["Önce ıslak mopla silmek, sonra süpürmek","Yalnızca kuru mopla geçip hiçbir kimyasal kullanmamak","Doğrudan cila makinesiyle ovalayıp bırakmak","Önce süpürüp vakumlamak, sonra nemli mopla silmek"],"dogru":3,"aciklama":"Kuru kir önce alınır; sonra nemli mopla temizlenir. Ters sırada kir çamurlaşır.","konu":"5.1.2"},{"id":"kh1-5-s042","tur":"coktan-secmeli","soru":"Halı neden akar oluşumuna elverişlidir?","secenekler":["Sürekli ıslak tutulan bir yüzey olduğu için","Yalnızca açık renkli döşendiğinde etkilendiği için","Tüylü tekstil ürünü olduğundan toz biriktirir","Asansörlere yakın döşendiği için"],"dogru":2,"aciklama":"Halı tozlanmaya ve akara elverişlidir; günlük vakum ve kirliliğe göre yıkama bunu azaltır.","konu":"5.1.2"},{"id":"kh1-5-s043","tur":"coktan-secmeli","soru":"Halıdaki kahve lekesine leke çıkarıcı kimyasalı nasıl uygularsın?","secenekler":["Lekenin tam ortasından dışa doğru yayarak","Önce lekenin çevresindeki tüm halıya yayarak","Lekeyi sert fırçayla ovarak ve hızla","Lekenin dış kenarından merkeze doğru"],"dogru":3,"aciklama":"Dıştan merkeze uygulama lekenin yayılmasını önler.","konu":"5.1.2"},{"id":"kh1-5-s044","tur":"coktan-secmeli","soru":"Halı yıkamada ilk defa kullanacağın bir ürünü nerede denersin?","secenekler":["Lobinin en görünür köşesinde ve herkesin gözü önünde","Yıkamadan sonra tüm halıda","Halının görünmeyen bir bölümünde","Başka bir odanın perdesinde"],"dogru":2,"aciklama":"Ürün rengi solduruyorsa görünür alan zarar görmeden fark edilir.","konu":"5.1.2"},{"id":"kh1-5-s045","tur":"coktan-secmeli","soru":"Yıkanan halının üzerine neden tam kurumadan eşya konmaz?","secenekler":["Islak halıya basmak lekeyi yayar, kiri halıya taşır","Halı kuruyunca küçülür ve şekil değiştirir","Mobilya bacakları ıslak halıyı yırtar ve kalıcı iz bırakır","Şampuan kuruduktan sonra etkisini tamamen yitirir"],"dogru":0,"aciklama":"Halı kuruyana kadar alan kullanıma kapatılır; ıslak halıda leke ve koku oluşur.","konu":"5.1.2"},{"id":"kh1-5-s046","tur":"coktan-secmeli","soru":"Bir otelde halılar kirlilik durumuna göre yıkanıyor. Aşağıdakilerden hangisi halı temizleme yöntemlerinden biri değildir?","secenekler":["Islak-kuru temizleme","Kuru köpükle temizleme","Sabunlu temizleme","Cilalı temizleme"],"dogru":3,"aciklama":"Halılar ıslak-kuru, kuru köpük ve sabunlu olmak üzere üç şekilde temizlenir. Cilalama sert zeminlere uygulanan bir işlemdir, halıya değil.","konu":"5.1.2"},{"id":"kh1-5-s047","tur":"coktan-secmeli","soru":"Açık renkli ve koyu renkli halılar yan yana döşenmiş. Temizlik programında hangisine daha fazla özen gösterilir?","secenekler":["Koyu renkli halıya, çünkü kir birikimi daha fazladır","Kiri daha kolay gösteren açık renkli halıya","İkisine eşit; renk farkı gözetilmez","Yalnızca koyu halıya, açık halı kendi kendine temizlenir"],"dogru":1,"aciklama":"Açık renkli halı kiri koyu renkliye göre daha çabuk gösterir; bu yüzden temizliğine daha fazla özen gösterilir.","konu":"5.1.2"},{"id":"kh1-5-s048","tur":"coktan-secmeli","soru":"Ahşap yüzeylerin temizliğinde hangisi yanlıştır?","secenekler":["Kuru mopla tozdan arındırmak","Çalı süpürgesi ve sert fırçayla süpürmek","Ahşap temizleyici kullanmak","Cila sonrası beyaz yumuşak pedle parlatmak"],"dogru":1,"aciklama":"Sert fırça ve çalı süpürgesi ahşabı çizer; ahşap suya ve aşındırıcıya karşı hassastır.","konu":"5.2.2"},{"id":"kh1-5-s049","tur":"coktan-secmeli","soru":"Ahşap tezgâha cila uygulanacak. Doğru uygulama hangisidir?","secenekler":["Cilayı yüzeye kalın bir tabaka hâlinde dökmek ve sertleşene kadar bırakmak","Asit bazlı bir ürünle önce yüzeyi iyice silmek","Cilayı bezle dairesel hareketlerle yedirip kurumasını beklemek","Cilayı sert fırçayla çizgiler hâlinde sürmek"],"dogru":2,"aciklama":"Ahşap cilası dairesel hareketlerle yedirilir; yüzeyde parlaklık oluşana kadar işlem sürer.","konu":"5.1.2"},{"id":"kh1-5-s050","tur":"coktan-secmeli","soru":"Lobideki kumaş kaplı koltukların bakımı için hangisi doğrudur?","secenekler":["Haftada bir silkelenir, hiç yıkanmaz","Yalnızca ıslak bezle silinir, vakumlanmaz","Yıkama gerekmedikçe dokunulmaz, toz alınmaz","Her gün vakumlanır, yoğunluğa göre yıkanır"],"dogru":3,"aciklama":"Kumaş koltuklar toz ve akar biriktirdiği için günlük vakumlanır.","konu":"5.1.2"},{"id":"kh1-5-s051","tur":"coktan-secmeli","soru":"Metal yüzeyler için ürün seçmeden önce metalin cinsi neden bilinmelidir?","secenekler":["Metaller yalnızca suyla temizlenebilir","Pirinç hiçbir kimyasalla temizlenemez ve cilalanamaz","Çelik, pirinç, bakır gibi metaller farklı ürün ister","Bütün metaller aynı ürünle aynı sürede parlar"],"dogru":2,"aciklama":"Yanlış ürün metali matlaştırabilir ya da çizebilir.","konu":"5.1.2"},{"id":"kh1-5-s052","tur":"coktan-secmeli","soru":"Lobide aydınlatma armatürünü silmeden önce hangisi yapılmalıdır?","secenekler":["Aydınlatmanın en yüksek parlaklığa getirilmesi","Elektriğin kesilip güvenlik önleminin alınması","Armatürün suyla yıkanması","Ampulün çıkarılıp bir kenara bırakılması"],"dogru":1,"aciklama":"Aydınlatma temizliğinde elektrik çarpmasına karşı önce elektrik kesilir.","konu":"5.1.2"},{"id":"kh1-5-s053","tur":"coktan-secmeli","soru":"Asansör temizliği neden odaların bulunduğu katlarda değil lobide yapılır?","secenekler":["Lobide kimyasal kullanımı katlara göre daha serbesttir","Böylece katlardaki konuklar rahatsız edilmez","Asansörler yalnız lobi katında kirlenir","Katlarda temizlik malzemesi bulunamaz"],"dogru":1,"aciklama":"Temizlik ekipmanı lobiye getirilir ve işlem orada yapılarak kat trafiği etkilenmez.","konu":"5.1.2"},{"id":"kh1-5-s054","tur":"coktan-secmeli","soru":"Otelde dört asansör var. Hangisi doğru temizlik uygulamasıdır?","secenekler":["Dördünü aynı anda kapatıp işi hızla bitirmek ve sonra açmak","Yalnızca gece saatlerinde temizlemek","Temizliği ancak bozulduklarında yapmak","Sırayla temizleyip en az birini açık tutmak"],"dogru":3,"aciklama":"Tüm asansörler aynı anda kullanım dışı bırakılmaz; konuk bavuluyla beklemek zorunda kalmamalıdır.","konu":"5.1.2"},{"id":"kh1-5-s055","tur":"coktan-secmeli","soru":"Asansör temizliğine yukarıdan aşağıya doğru başlamanın nedeni nedir?","secenekler":["Kir aşağı akacağından temizlenen yer bozulmaz","Zemin en son kurusun diye","Alt yüzeyler daha pahalı malzemeden olduğu için","Bez kullanımı bu şekilde daha az olduğu için"],"dogru":0,"aciklama":"Önce üst, sonra alt temizlenirse aşağı akan kir yeniden temizliği bozmaz.","konu":"5.1.2"},{"id":"kh1-5-s056","tur":"coktan-secmeli","soru":"Asansör kontrol panelini temizlerken hangisine dikkat edilir?","secenekler":["Panele doğrudan cam sıvısı sıkılır","Fazla nemli veya ıslak bez kullanılmaz","Panel bol suyla yıkanıp hızlıca kurulanır","Panele hiç dokunulmaz, yalnız çevresi silinir"],"dogru":1,"aciklama":"Panelde elektrik akımı ve elektronik kartlar vardır; sürekli temas edildiği için hijyen de gerekir.","konu":"5.1.2"},{"id":"kh1-5-s057","tur":"coktan-secmeli","soru":"Metal parlatıcı neden doğrudan metale değil de havlu beze uygulanır?","secenekler":["Beze sürülen parlatıcı yüzeyde daha uzun süre parlak kalır","Metale sıkıldığında yüzeye zarar verir, durulamada fazla su gerektirir","Bez kullanılınca ikinci bir kuru bezle kurulamaya gerek kalmaz ve iz bırakmaz","Parlatıcı yalnız renkli bezlere sürülürse işe yarar"],"dogru":1,"aciklama":"Parlatıcı doğrudan metale sıkılırsa yüzeye zarar verebilir ve durulama için fazla su gerekir; bu yüzden önce havlu beze uygulanır, ikinci kuru bezle kurulanır.","konu":"5.1.2"},{"id":"kh1-5-s058","tur":"coktan-secmeli","soru":"Asansör metal yüzeyi parlatılırken hangi uygulama doğrudur?","secenekler":["Tek bezle daire çizerek silmek","Sağdan sola doğru silmek","İki ayrı havlu bezle yukarıdan aşağıya silmek","Parlatıcıyı yüzeyde bırakıp kurumasını beklemek"],"dogru":2,"aciklama":"Oval, daire ya da yatay silme iz bırakır; ikinci kuru bezle yüzeyde parlatıcı kalmayacak şekilde kurulanır.","konu":"5.1.2"},{"id":"kh1-5-s059","tur":"coktan-secmeli","soru":"Birinci asansörü sildiğin bezi ikinci asansörde kullanmamanın nedeni nedir?","secenekler":["Bez ikinci asansörde işe yaramaz","Bezin rengi solup yüzeye geçebilir","Asansör panelleri bezle temas edince zarar görür","Kir ve mikrop bir yüzeyden diğerine taşınır"],"dogru":3,"aciklama":"Kullanılan bezler arabadaki kirli torbaya konur, mesai sonunda çamaşırhaneye teslim edilir.","konu":"5.1.2"},{"id":"kh1-5-s060","tur":"coktan-secmeli","soru":"Ofis temizliği sırasında masadaki evraklara nasıl davranılır?","secenekler":["Kendi düzenince yeniden sıralanır","Başka bir masaya taşınır","Gereksiz görülenler çöp kutusuna atılır","Karıştırılmaz; çevresi silinir"],"dogru":3,"aciklama":"Evrak çalışanın işine aittir; karıştırmak güven kaybına ve iş kaybına yol açar.","konu":"5.1.2"},{"id":"kh1-5-s061","tur":"coktan-secmeli","soru":"Ofis temizliği sonunda aşağıdakilerden hangisi yapılmaz?","secenekler":["Pencerelerin kapatılıp kontrol edilmesi","Oda parfümü sıkılması","Isıtıcı ve klimanın açık bırakılması","Kapının kilitlenmesi"],"dogru":2,"aciklama":"Temizlik sonunda ısıtıcı, fan, klima gibi cihazlar kapatılır; açık unutulan cihaz yangın ve enerji kaybı yaratır.","konu":"5.1.2"},{"id":"kh1-5-s062","tur":"coktan-secmeli","soru":"Ofiste toz almanın doğru yönü hangisidir?","secenekler":["Rastgele sırayla, önce göze çarpan yerlerden","Zeminden başlayıp tavana doğru","Kapıdan başlayıp saat yönünde, yukarıdan aşağıya","Pencereden başlayıp kapıya doğru, saat yönünün tersine"],"dogru":2,"aciklama":"Düzenli bir yön hiçbir yerin atlanmamasını sağlar.","konu":"5.1.2"},{"id":"kh1-5-s063","tur":"coktan-secmeli","soru":"Toplantı sonrası halının süpürülmesi kimin işidir?","secenekler":["Genel alan temizlik personelinin","Yiyecek içecek personelinin","Toplantıyı düzenleyen firmanın personelinin","Teknik servis çalışanlarının"],"dogru":0,"aciklama":"Yiyecek içecek personeli düzen ve servisi yapar; temizlik ve periyodik işler genel alan ekibine aittir.","konu":"5.1.2"},{"id":"kh1-5-s064","tur":"coktan-secmeli","soru":"Toplantı salonu temizliğinde genel alan personeli aşağıdakilerden hangisini yapmaz?","secenekler":["Halıların elektrikli süpürgeyle düzenli olarak süpürülmesi","Servis sonrası bardak ve fincanların toplanması","Camların silinmesi","Fuaye alanının temizlenmesi"],"dogru":1,"aciklama":"Düzen, servis ve boşların toplanması yiyecek içecek personelinin işidir; genel alan ekibi halı, toz, cam ve fuaye temizliğini yapar.","konu":"5.1"},{"id":"kh1-5-s065","tur":"coktan-secmeli","soru":"Seminer salonu ve kongre merkezi için hangisi söylenebilir?","secenekler":["Sekiz on kişilik küçük çalışma odalarıdır","Yüzlerce kişinin toplandığı, sandalyeli veya koltuklu alanlardır","Konukların yalnızca yemek yediği, servis yapılan geniş alanlardır","Personelin dinlendiği özel odalardır"],"dogru":1,"aciklama":"Bu alanlar konaklama işletmesinin gelir getiren önemli bölümleridir.","konu":"5.1.2"},{"id":"kh1-5-s066","tur":"coktan-secmeli","soru":"Fitness salonundaki spor aletlerinin temizliği kimin sorumluluğundadır?","secenekler":["Genel alan temizlik personelinin","Teknik servis ekibinin","Alanda çalışan spor personelinin","Spor yapan konukların kendisinin"],"dogru":2,"aciklama":"Spor aletlerinin temizlik, bakım ve hijyeni o alandaki personele aittir. Zemin, cam, ayna ve giyinme odaları genel alan ekibinindir.","konu":"5.1.2"},{"id":"kh1-5-s067","tur":"coktan-secmeli","soru":"Spor ve SPA alanlarında hijyen neden diğer alanlardan daha önemlidir?","secenekler":["Nem ve sıcaklıkla bakteri ve mantarlar kolayca ürer","Burada elektrik tesisatı ve su bağlantıları daha çok bulunur","Konuklar burada daha uzun süre vakit geçirir","Zeminlerin tamamı mermerden yapılmıştır"],"dogru":0,"aciklama":"Toplu spor yapılan alanlarda konuklar birçok yere temas eder; yetersiz temizlik ciddi sağlık sorunlarına yol açabilir.","konu":"5.1.2"},{"id":"kh1-5-s068","tur":"coktan-secmeli","soru":"SPA ve spor alanı temizliğinde hangisi yanlış bir uygulamadır?","secenekler":["Fazla suyu zeminden vakumla çekmek ve kurutmak","Havlu, peştamal ve sabunu tamamlamak","Islak paspastan önce uyarı levhası koymamak","Giyinme odalarını sık dezenfekte etmek"],"dogru":2,"aciklama":"Islak paspas öncesi çalışma bölgesine “Kaygan Zemin” levhası konur.","konu":"5.1.2"},{"id":"kh1-5-s069","tur":"coktan-secmeli","soru":"SPA alanında genel alan temizlik görevlisi ile SPA personeli arasındaki iş bölümü hangi seçenekte doğru verilmiştir?","secenekler":["SPA’nın genel temizliğini kendi personeli, giyinme odalarını ve dolapları genel alan görevlisi yapar","Giyinme odaları da dâhil bütün SPA alanını yalnızca genel alan görevlisi temizler ve bakımını yapar","SPA alanının tamamını kendi personeli, yalnızca cam ve aynaları genel alan görevlisi temizler ve düzenler","Sauna ve hamamı genel alan görevlisi, giyinme odalarını SPA personeli temizleyip bakımını yapar"],"dogru":0,"aciklama":"SPA’nın genel temizliği alanın kendi personelinindir; zemin, cam, ayna, giyinme odaları ve dolaplar ise genel alan personelince temizlenir. Tamamını tek tarafa yüklemek bu paylaşıma aykırıdır.","konu":"5.1.2"},{"id":"kh1-5-s070","tur":"coktan-secmeli","soru":"Restoran ve kafeteryanın temizliğinde iş bölümü nasıldır?","secenekler":["Tamamını yalnızca genel alan personeli temizler","Tamamını yalnızca mutfak personeli temizler","Mutfağı ve restoranı servis personeli, perde ve camı mutfak personeli temizler","Mutfağı mutfak, restoranı servis; perde ve camı genel alan temizler"],"dogru":3,"aciklama":"İşletmeler arasında farklılık olsa da perde temizliği ve cam silme genel alan personeline aittir.","konu":"5.1.2"},{"id":"kh1-5-s071","tur":"coktan-secmeli","soru":"Cam yüzeyi silerken lastikli cam silme aletinin doğru kullanımı hangisidir?","secenekler":["Cam sıvısı sıkıp “S” çizerek yukarıdan aşağıya boşluksuz silmek","Camın ortasından başlayıp yatay çizgilerle bütün camı baştan sona geçmek","Sıvıyı bezle yayıp kuruyana kadar camın üzerinde bekletmek","Aşağıdan yukarıya doğru çizgiler hâlinde silmek"],"dogru":0,"aciklama":"S hareketi boşluk bırakmaz ve su izi oluşmasını önler; yukarıdan aşağıya çalışmak damlayan suyu yeni silinen alana düşürmez.","konu":"5.1.2"},{"id":"kh1-5-s072","tur":"coktan-secmeli","soru":"Aynanın temizliği neden yalnız ön yüze uygulanır?","secenekler":["Arka yüzeyi duvara sabitlenmiştir","Arka yüz cam silme sıvısına dayanıklı değildir","Ayna yalnız ön yüzde toz tutar","Arka yüz her zaman temiz kalır"],"dogru":0,"aciklama":"Aynalarda temizlik yöntemi camla aynıdır; fakat arka taraf duvara bağlı olduğundan yalnız ön yüz silinir.","konu":"5.1.2"},{"id":"kh1-5-s073","tur":"coktan-secmeli","soru":"Bina dış cephe camlarını kimler temizler?","secenekler":["Genel alan görevlileri uzun merdivenlerle","Konuk odası görevlileri ile kat sorumluları birlikte","Endüstriyel dağcılık eğitimi almış personel","Otelin güvenlik görevlileri ve bekçiler"],"dogru":2,"aciklama":"Dış cephe cam temizliği tehlikeli ve sık yapılmayan bir iştir; işletmede bu nitelikte personel yoksa dışarıdan hizmet alınır.","konu":"5.1.2"},{"id":"kh1-5-s074","tur":"coktan-secmeli","soru":"Genel tuvalet temizliğinde tüketim malzemeleriyle ilgili doğru uygulama hangisidir?","secenekler":["Sabun, kâğıt havlu ve tuvalet kâğıdını tükenmeden tamamlamak","Malzemeleri yalnızca konuk istediğinde ve şikâyet geldiğinde tamamlamak","Malzemelerin haftada bir toplu dağıtılması","Malzemenin şef talimat verince yenilenmesi"],"dogru":0,"aciklama":"Eksik malzeme konuğu memnun etmez ve hijyeni bozar; görevli tükenmeden tamamlar.","konu":"5.1.2"},{"id":"kh1-5-s075","tur":"coktan-secmeli","soru":"Pisuvarlar sifon çalışmadığında neden kötü koku yayar?","secenekler":["Seramikten yapıldıkları ve yan yana dizildikleri için","Suyu çok tükettikleri için","Kapak mekanizması bulunmadığı için","Panelle ayrıldıkları için"],"dogru":2,"aciklama":"Kapağı olmadığından sifon sistemi çalışmadığında koku doğrudan dışarı yayılır.","konu":"5.1.2"},{"id":"kh1-5-s076","tur":"coktan-secmeli","soru":"Genel tuvalette oturularak kullanılan klozet türü hangisidir?","secenekler":["Alafranga tuvalet","Alaturka tuvalet","Pisuvar teçhizatı","Lavabo"],"dogru":0,"aciklama":"Alafranga tuvalet oturularak kullanılır; alaturka tuvalet zemine yerleştirilmiştir ve çömelerek kullanılır, pisuvar ise ayakta kullanılan teçhizattır.","konu":"5.1.2"},{"id":"kh1-5-s077","tur":"dogru-yanlis","soru":"Genel tuvalette kirli bezle temizlik yapılmaz; çünkü kirli bez bulaşma riskini artırır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Kirli bezle temizlik bulaşma riskini artırır; bu yüzden tuvalet temizliğinde temiz bez kullanılır ve kullanılan bezler gün sonunda ayrı poşetlerle çamaşırhaneye teslim edilir.","konu":"5.1.2"},{"id":"kh1-5-s078","tur":"coktan-secmeli","soru":"Tuvalet zemininde aşındırıcı ve kireç çözücü kimyasallar kullanılırsa ne olabilir?","secenekler":["Derz dolgusu sökülüp su alt kata akabilir","Fayans rengi parlar ve zemin yenilenmiş gibi görünür","Zemin daha az kaygan hâle gelir","Klozet kapakları artık kapanmaz"],"dogru":0,"aciklama":"Derz dolgusu fayans aralarını dolduran harçtır; aşındırıcı ürünlerle zamanla sökülür.","konu":"5.1.2"},{"id":"kh1-5-s079","tur":"coktan-secmeli","soru":"Genel tuvalette haşere görüldüğünde hemen rapor edilmesinin amacı nedir?","secenekler":["Böceği hangi görevlinin yakalayıp uzaklaştıracağını belirlemek","Hijyen riskini bildirip ilaçlamanın hızla başlamasını sağlamak","Tuvaletin o gün tamamen kapatılıp hizmet dışı bırakılmasını sağlamak","Konuk şikâyetlerinin ayrıntılı kaydını tutup işletmeye duyurmak"],"dogru":1,"aciklama":"Haşere hijyen ve işletme imajı için ciddi bir risktir; zamanında bildirmek ilaçlamanın hızlı başlamasını sağlar. Süpürüp geçmek ya da kimyasalı habersiz sıkmak sorunu çözmez.","konu":"5.1.2"},{"id":"kh1-5-s080","tur":"coktan-secmeli","soru":"Kapı arkasındaki WC kontrol fişi ne için kullanılır?","secenekler":["Konuk şikâyetlerini kayda geçirmek için","Malzeme siparişi vermek için","Temizlik saatini yazıp imzalamak için","Kapı anahtarını teslim etmek için"],"dogru":2,"aciklama":"Fiş temizliğin takip edildiğini ve kimin yaptığını gösterir; doldurulan fişler sabah genel alanlar şefine teslim edilir.","konu":"5.1.2"},{"id":"kh1-5-s081","tur":"coktan-secmeli","soru":"Genel tuvalet temizliği sonrası kişisel koruyucu ekipmanla ilgili doğru uygulama hangisidir?","secenekler":["Eldiveni cebine koyup ertesi gün de kullanmak","Maskeyi lavabonun yanına bırakmak","Ellerini yalnızca suyla çalkalamak","Tek kullanımlıkları çöpe atıp ellerini sabunla yıkamak"],"dogru":3,"aciklama":"Tek kullanımlık maske ve eldiven atılır; su ve sabunla el hijyeni sağlanır.","konu":"5.1.2"},{"id":"kh1-5-s082","tur":"coktan-secmeli","soru":"Tuvalet temizliğinde farklı yüzeylerde farklı renkte bez kullanılmasının amacı nedir?","secenekler":["Bezlerin daha az yıpranmasını ve uzun ömürlü olmasını sağlamak","Kirin yüzeyden yüzeye taşınmasını önlemek","Konuğa renkli bir görüntü vermek","Çamaşırhane maliyetini düşürmek"],"dogru":1,"aciklama":"Klozet bezi lavabo ya da cam için kullanılmaz; renk kodu işletmeden işletmeye değişebilir.","konu":"5.1.2"},{"id":"kh1-5-s083","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi dezenfeksiyon ile sterilizasyon arasındaki farkı doğru anlatır?","secenekler":["Dezenfeksiyon yalnızca insan vücudunda uygulanır","Sterilizasyon tüm mikroorganizmaları yok eder","Sterilizasyon yalnızca kimyasalla yapılabilir","İkisi tamamen aynı işlem için kullanılır"],"dogru":1,"aciklama":"Sterilizasyon daha kapsamlıdır; patojen olan ya da olmayan tüm mikroorganizmaları yok eder. Dezenfeksiyon öldürür ya da üremesini durdurur.","konu":"5.1.2"},{"id":"kh1-5-s084","tur":"coktan-secmeli","soru":"UV ışınlı sterilizasyon yapan personelin koruyucu ekipman ve gözlük kullanması neden gerekir?","secenekler":["Işın gözü ve cildi yaralayabilir","Lamba çok sıcak olduğu için","Işınlar kimyasal bıraktığı ve havayı kirlettiği için","Cihaz çok ses çıkardığı için"],"dogru":0,"aciklama":"UV ışığa uzun süre maruz kalmak tehlikelidir; işlem konukların az olduğu gece saatlerinde yapılır.","konu":"5.1.2"},{"id":"kh1-5-s085","tur":"coktan-secmeli","soru":"Dezenfektanlar neden belirli koşullarda kullanılır?","secenekler":["Çok pahalı ürünler olduklarından yalnız yetkililer kullanır","Genel olarak kuvvetli zehirler oldukları için","Yalnız soğuk ortamda çalıştıkları için","Kokusuz oldukları için"],"dogru":1,"aciklama":"Dezenfektanlar genellikle kuvvetli zehirdir; bu yüzden yalnız talimata uygun kullanılır ve insanın doğrudan kullandığı ürünlerde dezenfektan artığı denetlenir.","konu":"5.1.2"},{"id":"kh1-5-s086","tur":"coktan-secmeli","soru":"UV ışınlı sterilizasyonu kimyasal dezenfeksiyondan ayıran temel özellik hangisidir?","secenekler":["Işıkla çalışması, kimyasal madde gerektirmemesi","Yalnızca sıvı dezenfektanla birlikte uygulanabilmesi","Konuklar varken de rahatça kullanılabilmesi","Koruyucu ekipman istemeyecek kadar zararsız olması"],"dogru":0,"aciklama":"UV cihazı özel lambayla ışın yayar ve kimyasal gerektirmez; ancak ışın göze ve cilde zararlıdır, bu yüzden işlem konuk az iken ve koruyucu ekipmanla yapılır.","konu":"5.1.2"},{"id":"kh1-5-s087","tur":"coktan-secmeli","soru":"Meydan arabasıyla alana taşınmayıp görevli tarafından ayrıca getirilen malzeme hangisidir?","secenekler":["Mop sapı ve temiz mop paspasları","Elektrikli süpürge gibi kablolu araçlar","Cam silme aleti ve renkli toz bezleri","Çöp torbası ile malzeme sepeti"],"dogru":1,"aciklama":"Elektrikli temizlik araçları arabanın içinde değil, görevli tarafından ayrıca alana getirilir; mop, cam silme aleti, toz bezleri, çöp torbası ve sepet ise arabada taşınır.","konu":"5.1.3"},{"id":"kh1-5-s088","tur":"coktan-secmeli","soru":"Genel alan ekibi için araç gereç ve malzeme stokunun her zaman yeterli tutulmasının nedeni nedir?","secenekler":["Stok biterse iş durur ve hizmet standardı bozulur","Stok arttıkça birim maliyet düşer ve işletme kazanır","Konuklar depoyu görmek ister","Depo boş görünmesin diye"],"dogru":0,"aciklama":"Ders materyaline göre malzeme, iş gücünden sonra kat hizmetlerinin en büyük maliyetidir; tükenmeden tedarik hem kaliteyi hem maliyeti korur.","konu":"5.1.3"},{"id":"kh1-5-s089","tur":"coktan-secmeli","soru":"Uygulamaya başlamadan önceki kişisel bakım adımları arasında hangisi yer almaz?","secenekler":["Takıları çıkarıp kişisel bakım ve hijyen kurallarını uygulamak","Meydan arabasını ofisten alıp yüklemek","Üniformayı giymek","İsimliği takmak"],"dogru":1,"aciklama":"İlk dört adım kişisel bakım ve hijyen, takılar, işletmenin üniforması ve isimliktir; arabayı yüklemek görev talimatından sonra gelen hazırlık adımıdır.","konu":"5.1.4"},{"id":"kh1-5-s090","tur":"coktan-secmeli","soru":"Uygulama öncesi “görev talimatı” adımlarından doğru sıra hangisidir?","secenekler":["Meydan ofisi anahtarı, iş programı, toplantı","İş programı, toplantı, meydan ofisi anahtarı","Anahtar, toplantı, iş programı","Toplantı, iş programı, ofis anahtarı"],"dogru":3,"aciklama":"Önce toplantıya katılınır, iş programı öğrenilir, sonra alanın gerecini taşıyan ofisin anahtarı alınır.","konu":"5.1.4"},{"id":"kh1-5-s091","tur":"coktan-secmeli","soru":"Lobi temizliği uygulamasında zemin temizliğinden önce hangisi yapılır?","secenekler":["Zemin cilalanır ve parlatılır","Halı yıkanır","Uyarı levhası yerleştirilir","Camlar yıkanır"],"dogru":2,"aciklama":"Zemin işine geçmeden önce konuk güvenliği için levha ve işaretler konur.","konu":"5.1.4"},{"id":"kh1-5-s092","tur":"coktan-secmeli","soru":"Genel tuvalet uygulamasında kapıya gelindiğinde neden önce çalınıp “Housekeeping” denir?","secenekler":["Kapının kilitli olup olmadığını anlamak için","Şefi çağırmak için","Koku gidermek için","İçeride konuk olma ihtimaline karşı"],"dogru":3,"aciklama":"Konuğun özel alanına haber vermeden girilmez.","konu":"5.1.4"},{"id":"kh1-5-s093","tur":"coktan-secmeli","soru":"Halı yıkama uygulamasında doğru sıra hangisidir?","secenekler":["Önce şampuanlı yıkama, sonra elektrikli süpürge","Önce süpürge, sonra leke çıkarma, sonra yıkama","Önce leke çıkarma, sonra tozdan arındırma, sonra yıkama","Önce kurutma, sonra yıkama"],"dogru":1,"aciklama":"Halı önce tozdan arındırılır; sonra lekeler çıkarılır; ardından şampuanla yıkanır ve köpük çekilir.","konu":"5.1.4"},{"id":"kh1-5-s094","tur":"coktan-secmeli","soru":"Cam ve ayna temizliği uygulamasında perdeler için ne yapılır?","secenekler":["Sökülüp çöpe atılır","Islanmamaları için tedbir alınır","Camla birlikte yıkanır","Üzerine cam sıvısı sıkılıp silinir ve kurutulur"],"dogru":1,"aciklama":"Cam silerken akan sıvı perdeye geçebilir; bu yüzden koruyucu tedbir alınır.","konu":"5.1.4"},{"id":"kh1-5-s095","tur":"senaryo","durum":"Gece 01.30. Lobi mermerini cilalamak için makineyi alana getirdin. Prize takmadan önce kablonun kaplamasında yıpranma gördün.","soru":"Ne yaparsın?","secenekler":["Makineyi çalıştırmadan şefine bildiririm","Üzerine bant sarıp çalışmaya devam ederim","Kabloyu gizleyip işe başlarım","Konuk uyanmasın diye hızla bitiririm"],"dogru":0,"aciklama":"Kablo veya fişte kaçak olması iş kazası riskidir; arıza makine kullanılmadan şefe bildirilir. Bantlamak güvenli çözüm değildir.","konu":"5.1.2"},{"id":"kh1-5-s096","tur":"senaryo","durum":"Dolu bir haftada saat 15.00. Dört asansörün tamamı aynı anda temizlik için kapatılmış, lobide bavullu konuklar kuyruk oluşturmuş.","soru":"Ne yaparsın?","secenekler":["Temizliği hızlandırıp konuklardan biraz beklemelerini isterim","Bir asansörü hemen açıp temizliği sırayla sürdürürüm","Konuklara merdiveni kullanmalarını söylerim","Temizliği akşama bırakıp bütün asansörleri açarım"],"dogru":1,"aciklama":"Asansörler sırayla temizlenir, hepsi aynı anda kapatılmaz. Konuk bavuluyla beklememeli ve merdivene yönlendirilmemelidir.","konu":"5.1.2"},{"id":"kh1-5-s097","tur":"senaryo","durum":"Sabah 07.30. Spor salonunda birkaç konuk hâlâ egzersiz yapıyor. Zemini ıslak paspaslaman gerekiyor.","soru":"Ne yaparsın?","secenekler":["Önce paspaslar sonra levhayı koyarım","Konuklar çıkıp salon boşalana kadar beklerim ve hiçbir şey yapmam","Levha yerine konuklara sözlü uyarı yapıp başlarım","Önce çalışma bölgesine kaygan zemin levhasını koyarım"],"dogru":3,"aciklama":"Islak paspas öncesi çalışma bölgesine levha konur. Sözlü uyarı kaymayı önlemez; önce paspaslamak da konuğu riske atar.","konu":"5.1.2"},{"id":"kh1-5-s098","tur":"senaryo","durum":"Genel tuvaletin bir kabin köşesinde küçük bir böcek gördün. Şef o anda ofisinde değil.","soru":"Ne yaparsın?","secenekler":["Hemen rapor eder, şefe ve sorumluya bildiririm","Böceği süpürüp işime devam ederim","Güçlü kimyasal sıkıp bu konuyu kimseye söylemem","Kabini kapatıp rapor etmeden geçerim"],"dogru":0,"aciklama":"Haşere görüldüğünde derhal rapor edilir; kimyasalı habersiz kullanmak başka risk doğurur.","konu":"5.1.2"},{"id":"kh1-5-s099","tur":"senaryo","durum":"Gece yıkanan koridor halısı henüz nemli. Sabah 06.00’da bir grup, valizleriyle bu koridordan geçmek istiyor.","soru":"Ne yaparsın?","secenekler":["Halının üzerine havlu serip bu yoldan geçmelerini söylerim","Sert fırçayla halıyı kurutmaya çalışırım","Alanı kapalı tutar, konukları başka yola yönlendiririm","Sandalyeleri yerleştirip alanı açarım"],"dogru":2,"aciklama":"Halı tam kuruyana kadar kullanıma kapatılır; nemli halıya basmak lekeyi yayar ve koku yapar.","konu":"5.1.2"},{"id":"kh1-5-s101","tur":"coktan-secmeli","soru":"Genel alanlar şefi bu haftanın işleri arasına dış duvarların yıkanmasını ve saksı çiçeklerinin yapraklarının silinmesini yazdı. Bu işler hangi temizlik türüne girer?","secenekler":["Günlük temizlik turu işleri","Periyodik temizlik işleri","Haftalık ve aylık temizlik","Sezon başı plaj temizliği"],"dogru":2,"aciklama":"Duvar yıkama ve bitki silme her gün değil, düzenli aralıklarla yapılan haftalık ve aylık işlerdir. Periyodik temizlik cila sökme ve boyama gibi daha seyrek, daha büyük işleri kapsar.","konu":"5.2"},{"id":"kh1-5-s102","tur":"coktan-secmeli","soru":"Dış mekânda aşağıdakilerden hangisi periyodik temizlik kapsamında yapılır?","secenekler":["Kül tablalarını boşaltma","Cila sökme ve yeniden cilalama","Çöp poşetlerini değiştirme","Bitki yapraklarını nemli bezle silme"],"dogru":1,"aciklama":"Cila sökme ve yeniden cilalama uzun aralıklarla yapılan büyük bir iştir. Diğer üçü günlük ya da haftalık işlerdir.","konu":"5.2"},{"id":"kh1-5-s103","tur":"dogru-yanlis","soru":"Bina cam kaplamasının temizliği ve eski cilanın sökülmesi, günlük dış mekân temizliği kapsamında yapılan işlerdir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Cam kaplama temizliği, cila sökme ve boyama periyodik işlerdir. Günlük temizlik toz alma, kül tablası ve çöp kutusu boşaltma, çöp poşeti değiştirme ve sert yüzey süpürmeyi kapsar.","konu":"5.2"},{"id":"kh1-5-s104","tur":"coktan-secmeli","soru":"Konuk otele girmeden önce dış mekânı görür. Bu yüzden dış mekân temizliği özellikle hangi sonucu doğurur?","secenekler":["Resepsiyondaki bekleme süresini kısaltır","İç mekân temizliğini gereksiz kılar","İşletme hakkındaki ilk izlenimi etkiler","Yalnızca oda fiyatını belirler"],"dogru":2,"aciklama":"Dış mekân konuğun ilk karşılaştığı alandır; bu nedenle işletmeye bakışını doğrudan etkiler. İç mekân temizliği yine de gereklidir.","konu":"5.2"},{"id":"kh1-5-s105","tur":"dogru-yanlis","soru":"Şehir otellerinde dış mekân genellikle resort otellerden daha geniştir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Açık alanlar şehir merkezindeki iş amaçlı otellerde az, coğrafi güzelliklere yakın resort otellerde daha fazladır.","konu":"5.2.1"},{"id":"kh1-5-s106","tur":"coktan-secmeli","soru":"Bir resort otelde havuz suyunun temizliği ve dezenfeksiyonu hangi bölümün görevidir?","secenekler":["Kat hizmetleri genel alan görevlisi","Bahçıvanlar","Yiyecek içecek bölümü","Teknik servis"],"dogru":3,"aciklama":"Havuz suyunun temizliğini teknik servis görevlendirdiği kişilerle yapar. Kat hizmetleri havuzun çevresini temizler.","konu":"5.2.2"},{"id":"kh1-5-s107","tur":"coktan-secmeli","soru":"Havuz çevresindeki yeşil alanların bakımı, budanması ve peyzaj işleri genellikle kim tarafından yapılır?","secenekler":["Genel alan temizleme görevlileri","Teknik servis bölümü personeli","Bahçıvanlar ve bahçe görevlileri","Çamaşırhane bölümü görevlileri"],"dogru":2,"aciklama":"Bitki bakımı bahçıvanların işidir; genel alan görevlisi çevrenin çöp ve temizlik işini yapar. İş bölümü işletmeye göre değişebilir.","konu":"5.2.2"},{"id":"kh1-5-s108","tur":"coktan-secmeli","soru":"Gece 23.00’te teras zeminini yıkayacaksın. Alanı kullanıma açık bırakırsan kayma riski doğar. Islak zemin temizliğinden önce ilk yapılacak işlem hangisidir?","secenekler":["Konuklara dikkatli yürümelerini söyleyip alanı açık bırakmak","Yalnızca kaymayan ayakkabı giyip çalışmaya başlamak","Uyarı levhası koyup alanı kullanıma kapatmak","Zemini yıkayıp levhayı iş bitince koymak"],"dogru":2,"aciklama":"Islak zemin temizliğinden önce levha konur ve alan tamamen kapatılır. Kaymayan ayakkabı da gereklidir, ama konuğu koruyan asıl önlem alanın kapatılmasıdır.","konu":"5.2.1"},{"id":"kh1-5-s109","tur":"coktan-secmeli","soru":"Kimyasal temizleyiciyle çalışırken aşağıdakilerden hangisi yanlış bir uygulamadır?","secenekler":["Çalışmadan önce eldiven ve maske takmak","Etiketteki kullanım talimatını okumak","Çalışılan alanı sürekli havalandırmak","İki ürünü hızlı sonuç için karıştırmak"],"dogru":3,"aciklama":"Bazı ürünlerin bir arada kullanılması zehirli gaz oluşturabilir. Diğer üç seçenek kimyasalla güvenli çalışmanın kurallarıdır.","konu":"5.1.1"},{"id":"kh1-5-s110","tur":"coktan-secmeli","soru":"Girişteki tabelayı silmek için merdiven gerekiyor. Hangi uygulama doğrudur?","secenekler":["Yakındaki sandalyenin üzerine çıkıp hızlıca silmek","Merdiven sallansa da kısa sürede bitirmek için çıkmak","Konuklar geçerken merdiveni açık bırakıp ara vermek","Sağlam merdivene çıkıp iş arkadaşından destek almak"],"dogru":3,"aciklama":"Yüksekte çalışırken sağlam merdiven kullanılır ve çalışana bir personel refakat eder. Sandalye ya da sallanan merdiven düşme riski doğurur.","konu":"5.2.1"},{"id":"kh1-5-s111","tur":"dogru-yanlis","soru":"Dış mekân temizliğinde işler bir plan dâhilinde yürütülür ve personele kapasitesinin üzerinde iş yüklenmez.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Aşırı yük yorgunluğa, dikkatsizliğe ve kazaya yol açar; bu yüzden iş güne bölünür ve plana bağlanır.","konu":"5.2.1"},{"id":"kh1-5-s112","tur":"dogru-yanlis","soru":"Dış mekân temizliği konukların yoğun kullanmadığı saatlere planlanır; çünkü gürültü, ıslak zemin ve kimyasal kokusu konuğun tatilini bozar.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Konuk dinlenmek için gelmiştir; gürültü, ıslak zemin ve kimyasal kokusu tatilini bozar. Bu yüzden temizlik konukların yoğun kullanmadığı saatlerde yapılır ve konukları rahatsız etmemek için tedbir alınır.","konu":"5.2.1"},{"id":"kh1-5-s113","tur":"coktan-secmeli","soru":"Bahçedeki ağır bir saksıyı yerinden oynatman gerekiyor. Hangisi doğru davranıştır?","secenekler":["Doğru duruş alıp iş arkadaşından yardım istemek","Beli bükerek tek başına hızlıca kaldırıp taşımak","Saksıyı yerden sürükleyerek yerinden çıkarmak","Yük çok ağır gelirse zorlayarak devam etmek"],"dogru":0,"aciklama":"Ağır eşya yardım alınarak ve omuriliğe fazla yük bindirmeyecek pozisyonda taşınır. Tek başına kaldırmak belde ciddi yaralanmaya yol açar.","konu":"5.2.1"},{"id":"kh1-5-s114","tur":"coktan-secmeli","soru":"Bahçede makineyi prize bağlarken uzun kablo hakkında hangisi doğrudur?","secenekler":["Tamamen açılıp alan boyunca yola serilir","Kapı aralığına sıkıştırılarak sabitlenir","Yıpranmış yeri bantlanıp kullanılmaya devam edilir","Gerektiği kadar açılır, ortalığa yayılmaz"],"dogru":3,"aciklama":"Yerde dolaşan kablo takılıp düşmeye neden olur; bu yüzden kablo kullanılacak kadar açılır ve düzenli kontrol edilir.","konu":"5.2.1"},{"id":"kh1-5-s115","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi animasyon alanı olarak temizlenen dış mekân bölümlerindendir?","secenekler":["Amfi tiyatro","Soyunma kabini","Otopark","Havlu dağıtım alanı"],"dogru":0,"aciklama":"Bahçeler, amfi tiyatrolar ve açık hava diskoları animasyon için kullanılan alanlardır. Diğer üçü farklı alan türleridir.","konu":"5.2.2"},{"id":"kh1-5-s116","tur":"coktan-secmeli","soru":"Kapalı otoparkı günlük temizlerken diğer işlere ek olarak neye bakılır?","secenekler":["Havalandırma sisteminin çalışıp çalışmadığına","Duşlardaki giderlerde tıkanıklık olup olmadığına","Şezlong minderlerinde leke bulunup bulunmadığına","Tribün oturma yerlerinde toz olup olmadığına"],"dogru":0,"aciklama":"Kapalı otoparkta havalandırmanın çalışması kontrol edilir. Diğer seçenekler otoparkla ilgisi olmayan alanlara aittir.","konu":"5.2.2"},{"id":"kh1-5-s117","tur":"dogru-yanlis","soru":"Spor alanında zemin türüne bakılmaksızın her yerde aynı süpürge kullanılabilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Spor alanı zeminine uygun biçimde süpürülür ya da çöpler elle toplanır; uygun olmayan yöntem zemine zarar verebilir.","konu":"5.2.2"},{"id":"kh1-5-s118","tur":"coktan-secmeli","soru":"Tenis kortunun aydınlatmasında yanmayan bir lamba görüyorsun. Doğru davranış hangisidir?","secenekler":["Direğe çıkıp lambayı değiştirmek","Sorunu görmeyip işe devam etmek","Konukları alandan uzaklaştırmak","Durumu teknik servise bildirmek"],"dogru":3,"aciklama":"Aydınlatma, levha ve donanım arızası teknik servise bildirilir. Temizlik görevlisi onarım yapmaz.","konu":"5.2.2"},{"id":"kh1-5-s119","tur":"coktan-secmeli","soru":"Plaj kum eleme ve temizleme makinesi hangi dönemde kullanılır?","secenekler":["Her öğle yemeğinden sonra","Her gün konuklar ayrıldıktan sonra","Sezon başında ve sonunda","Yalnızca hafta sonları"],"dogru":2,"aciklama":"Bu makine plajı sezon başında ve sonunda detaylı temizler. Günlük işler ise çöp toplama, şezlong ve kabin temizliğidir.","konu":"5.2.2"},{"id":"kh1-5-s120","tur":"coktan-secmeli","soru":"Plajda şezlongların her gün yıkanması hangi zamanda yapılır?","secenekler":["Konuklar plaja inmeden önce sabah erkenden","Konuklar plajdan ayrıldıktan sonra","Konuklar uzanırken öğleden sonra","Yalnızca sezon başında bir kez"],"dogru":1,"aciklama":"Şezlonglar her gün konuklar ayrıldıktan sonra yıkanır; böylece konuk rahatsız edilmez ve ertesi gün temiz kullanılır.","konu":"5.2.2"},{"id":"kh1-5-s121","tur":"coktan-secmeli","soru":"Akşam minderleri toplarken lekeli bir minder buldun. Ne yaparsın?","secenekler":["Temiz bir minderle değiştirirsin","Lekeli yüzü alta çevirip koyarsın","Üstüne havlu serip kullanıma sunarsın","Konuk şikâyet edince değiştirirsin"],"dogru":0,"aciklama":"Yıpranmış ve lekeli minderler temiz minderlerle değiştirilir; lekeyi saklamak kirli görünümü ortadan kaldırmaz.","konu":"5.2.2"},{"id":"kh1-5-s122","tur":"coktan-secmeli","soru":"Plajda ya da havuzda kullanılan havluların odadaki havlulardan farkı nedir?","secenekler":["Renklerinin farklı olması","Boyutlarının daha büyük olması","Üzerindeki işletme amblemi","Kumaşlarının daha ince olması"],"dogru":0,"aciklama":"Karışmayı önlemek için plaj ve havuz havluları odalardakilerden farklı renktedir; oda havluları dışarıda kullanılmaz.","konu":"5.2.2"},{"id":"kh1-5-s123","tur":"coktan-secmeli","soru":"Soyunma kabini kontrolünde bir güneş gözlüğü buldun. Doğru işlem hangisidir?","secenekler":["Kabin kapısına asıp sahibinin gelmesini beklemek","Plaj barı görevlisine bırakıp tekrar bakmamak","Gerekli yere, örneğin ön büroya teslim etmek","Kendi dolabında saklamak"],"dogru":2,"aciklama":"Unutulan eşya gerekli yerlere teslim edilir; böylece kaydı tutulur ve sahibine ulaştırılır.","konu":"5.2.2"},{"id":"kh1-5-s124","tur":"dogru-yanlis","soru":"Kumla tıkanan plaj duşu giderini görevli kendisi söküp onarır; teknik servise bildirmesi gerekmez.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kum birikmesine karşı giderler kontrol edilir; tıkalı gider görülünce onarım için teknik servise bildirilir.","konu":"5.2.2"},{"id":"kh1-5-s125","tur":"dogru-yanlis","soru":"Plajdaki yiyecek içecek çöpleri sıcakta kötü koku yaptığı için çöp kutuları sık sık boşaltılır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Çöplere hızlı müdahale edilmezse sıcağa bağlı olarak istenmeyen kokular oluşur; bu yüzden çöp kutuları sık boşaltılır.","konu":"5.2.2"},{"id":"kh1-5-s126","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi havuz çevresinde kat hizmetlerinin değil teknik servisin işidir?","secenekler":["Çöplerin toplanması","Şezlong ve şemsiyelerin yerleştirilmesi","Kül tablalarının boşaltılması","Havuz suyunun dezenfeksiyonu"],"dogru":3,"aciklama":"Havuz suyu teknik servise aittir. Çevre temizliği, çöp, şezlong ve şemsiye işleri kat hizmetleri bölümüne aittir.","konu":"5.2.2"},{"id":"kh1-5-s127","tur":"coktan-secmeli","soru":"Ayak yıkama ve dezenfeksiyon alanının temizliği hakkında hangisi doğrudur?","secenekler":["Haftada bir kez temizlenir","Yalnızca sezon başında temizlenir","Su değişimi konuk şikâyetine bırakılır","Günlük temizlenir ve suyu değiştirilir"],"dogru":3,"aciklama":"Konuğun havuza girmeden önce kullandığı bu alanın temizliği ve suyunun değişimi her gün yapılır.","konu":"5.2.2"},{"id":"kh1-5-s128","tur":"coktan-secmeli","soru":"Havuz çevresindeki üst değiştirme kabininde su birikmiş. Ne yapılır?","secenekler":["Kapısı kapatılıp bırakılır","Zeminin kuruması beklenir","Biriken su tahliye edilir","Kullanım dışı bırakılır"],"dogru":2,"aciklama":"Biriken su kayma riski doğurur; kabinler sık kontrol edilir ve su tahliye edilir. Unutulan eşya sorumlulara teslim edilir.","konu":"5.2.2"},{"id":"kh1-5-s129","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi havuz kullanıma açılmadan önce yapılan hazırlıktır?","secenekler":["Şezlong ve şemsiye düzeninin hazırlanması","Konukların arasında dolaşıp çöp toplanması","Islak havluların çamaşırhaneye gönderilmesi","Kül tablalarının dolaşılarak boşaltılması"],"dogru":0,"aciklama":"Güneşlenme ve dinlenme alanının düzeni havuz açılmadan önce hazırlanır. Çöp toplama ve kül tablası boşaltma ise havuz açıkken yapılan işlerdir.","konu":"5.2.2"},{"id":"kh1-5-s130","tur":"coktan-secmeli","soru":"Havuz kapandıktan sonra şezlong, şemsiye, sehpa ve minderler için hangisi yapılır?","secenekler":["Gece boyunca yerinde bırakılıp ertesi sabah yıkanır","Yalnızca şemsiyeler toplanıp diğerleri yerinde bırakılır","Güvenceye almak için toplanır ve dezenfekte edilir","Minderler suya batırılıp bir gece boyunca bekletilir"],"dogru":2,"aciklama":"Havuz kapanışında malzeme toplanır ve dezenfeksiyon işlemi uygulanır.","konu":"5.2.2"},{"id":"kh1-5-s131","tur":"coktan-secmeli","soru":"Havuz kenarındaki havlu dağıtım alanında ıslak havlular birikti. Doğru uygulama hangisidir?","secenekler":["Havluları güneşte kurutup konuklara hemen yeniden dağıtmak","Islakları alıp çamaşırhaneye göndermek, kuru havlu vermek","Islak havluları odalardan gelen havlularla aynı yerde saklamak","Kuru havlu bitene kadar ıslak havluları dağıtmaya devam etmek"],"dogru":1,"aciklama":"Islak havlular geri alınıp çamaşırhaneye gönderilir ve konuklara sürekli kuru havlu dağıtılır. Oda havluları plaj ve havuz havlularıyla karıştırılmaz.","konu":"5.2.2"},{"id":"kh1-5-s132","tur":"coktan-secmeli","soru":"Meydan arabasında renkli toz bezleri bulunmasının amacı nedir?","secenekler":["Kiri bir alandan başka alana taşımamak","Bezleri birbirinden kolay ayırt etmek","İşletmenin kurumsal renklerini yansıtmak","Bezlerin daha uzun dayanmasını sağlamak"],"dogru":0,"aciklama":"Toz bezleri yüzeylere göre farklı renklerde seçilir; böylece bir alanın kiri başka alana taşınmaz.","konu":"5.2.3"},{"id":"kh1-5-s133","tur":"coktan-secmeli","soru":"Sert zeminleri silmek için meydan arabasında hangi takım bulunur?","secenekler":["Süpürge ve faraş takımı","Cam silme aleti ve süngeri","Çöp sepeti ve çöp torbaları","Mop sapı ve mop paspası"],"dogru":3,"aciklama":"Sert zeminler mop aleti ve paspasıyla silinir. Süpürge ve faraş kaba çöpü toplar; cam silme aleti cam içindir.","konu":"5.2.3"},{"id":"kh1-5-s134","tur":"coktan-secmeli","soru":"Açık terastaki halıyı derinlemesine yıkamak için hangi makine kullanılır?","secenekler":["Halı yıkama makinesi","Elektrik süpürgesi","Sert yüzey yıkama ve cilalama makinesi","Dezenfeksiyon cihazı"],"dogru":0,"aciklama":"Halılar için halı yıkama makinesi vardır. Elektrik süpürgesi toz alır; sert yüzey makinesi sert zeminler içindir.","konu":"5.2.3"},{"id":"kh1-5-s135","tur":"coktan-secmeli","soru":"Halı yıkama makinesi ile sert yüzey yıkama ve cilalama makinesi arasındaki fark hangisidir?","secenekler":["Birincisi halıda, ikincisi sert zeminde kullanılır","Birincisi sert zeminde, ikincisi halıda kullanılır","İkisi de yalnız kuru toz alır, farkları ses düzeyidir","İkisi de aynı zemin türü için üretilmiştir"],"dogru":0,"aciklama":"Halılar için halı yıkama makinesi, taş ve mermer gibi sert zeminler için sert yüzey makinesi kullanılır. Kuru toz alan araç ise elektrik süpürgesidir.","konu":"5.2.3"},{"id":"kh1-5-s136","tur":"coktan-secmeli","soru":"Temizlik bittiğinde kullanılan cihaz ve malzemelerle ilgili hangisi doğrudur?","secenekler":["Kirli olarak ofise getirilir","Ertesi sabah kullanılmak üzere alanda bırakılır","Toplanıp temizlenir ve yerine yerleştirilir","Yalnızca elektrikli cihazlar toplanır"],"dogru":2,"aciklama":"İş bitiminde tüm cihaz ve malzemeler toplanarak temizlenir ve yerlerine konur.","konu":"5.1"},{"id":"kh1-5-s137","tur":"dogru-yanlis","soru":"Süpürülüp toplanan çöp yerde bırakılmaz; rüzgârla yeniden dağılmasın diye sepette tutulup çöp konteynerine boşaltılır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Toplanan çöp yerde kalırsa rüzgârla dağılır; konteynere gidene kadar sepette tutulur.","konu":"5.2.4"},{"id":"kh1-5-s138","tur":"coktan-secmeli","soru":"Dış mekânın sürekli bakımlı ve temiz kalması neye bağlıdır?","secenekler":["Doğru araç, zamanında bakım, doğru malzeme","Yalnızca temizliğin çok sık yapılmasına","Her alanda en pahalı kimyasalın kullanılmasına","Bütün alanların aynı yöntemle yıkanmasına"],"dogru":0,"aciklama":"Dış mekânın temiz ve bakımlı kalması; temizliğin doğru araç gereçle, bakımın zamanında yapılması ve malzemenin doğru yerde kullanılmasıyla mümkündür; sık temizlik tek başına yetmez.","konu":"5.2.4"},{"id":"kh1-5-s139","tur":"coktan-secmeli","soru":"Temmuz ayında sabah 10.00’da plajda çalışacaksın. Sıcağa karşı hangi önlem doğrudur?","secenekler":["Daha rahat çalışmak için koruyucu kıyafeti çıkarmak","Şapka takıp aşırı güneşten korunmak","Temizliği öğle sıcağına bırakmak","Gölgeli alanlara hiç girmeden çalışmak"],"dogru":1,"aciklama":"Açık alanda çalışan personel güneş, sıcak ve soğuk gibi etkilere karşı önlem alır. İşi öğle sıcağına bırakmak sağlığı da konuk memnuniyetini de olumsuz etkiler.","konu":"5.2.1"},{"id":"kh1-5-s140","tur":"coktan-secmeli","soru":"Plajda bir kabinin zeminini paspaslarken hangi sıra uygulanır?","secenekler":["Kapıdan içeri doğru ilerleyerek silinir","Önce dışarısı, sonra kabinin içi silinir","Kabinin içinden başlayarak silinir","Rastgele noktalardan başlanarak silinir"],"dogru":2,"aciklama":"Zemin içeriden başlayarak paspaslanır; böylece silinen alana yeniden basılmaz.","konu":"5.2.4"},{"id":"kh1-5-s141","tur":"coktan-secmeli","soru":"Plajda temizlik bitince kullanılan bezler nasıl ayrılır?","secenekler":["Bez türleri karışık biçimde tek poşete doldurulur","Arabanın üzerinde kurumaya bırakılıp ertesi gün kullanılır","Kirli oldukları için çöp konteynerine atılır","Renklerine göre farklı poşetlere konur"],"dogru":3,"aciklama":"Kullanılan temizlik bezleri renge göre ayrı poşetlere konur; farklı alanlardan gelen kirli bezler karışmaz.","konu":"5.2.4"},{"id":"kh1-5-s142","tur":"coktan-secmeli","soru":"Kullanılan kirli mop ve paspaslara iş bitince ne yapılır?","secenekler":["Temiz bezlerle aynı sepete konup arabada saklanır","Hortumla durulayıp yeniden kullanılmak üzere asılır","Çöp konteynerine atılıp yenileri alınır","Ayrı kirli torbalarla çamaşırhaneye hazırlanır"],"dogru":3,"aciklama":"Kirli bezler, mop ve paspaslar ayrı kirli torbalarla çamaşırhaneye hazırlanır.","konu":"5.2.4"},{"id":"kh1-5-s143","tur":"coktan-secmeli","soru":"Toplu giyinme alanındaki boş eşya dolapları için hangi işlem yapılır?","secenekler":["Yalnızca kapakları kilitlenip bırakılır","Çamaşırhaneye gönderilip yıkanır","Tozu alınır ve dezenfekte edilir","Konuk isterse temizlenir ve açılır"],"dogru":2,"aciklama":"Boş dolapların tozu alınarak dezenfekte edilir; çok kişinin dokunduğu yüzeylerde hijyen için gereklidir.","konu":"5.2.4"},{"id":"kh1-5-s144","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi uygulama değerlendirme ölçütlerinden biridir?","secenekler":["Zamanı kullanma becerisi","Alandaki konuk sayısı","Kullanılan malzeme fiyatı","Yaprak toplama süresi"],"dogru":0,"aciklama":"Ölçütler iş için ön hazırlık, uygulama becerisi, zamanı kullanma, iletişim ve olağan dışı durumlara hazır bulunuşluktur.","konu":"5.1.4"},{"id":"kh1-5-s145","tur":"coktan-secmeli","soru":"Bahçe ve parklarda günlük yapılan temizlik işi hangisidir?","secenekler":["Cam kaplamayı temizlemek","Çöp kutularını boşaltmak","Duvarları yeniden boyamak","Ahşabın cilasını sökmek"],"dogru":1,"aciklama":"Çöp kutularının boşaltılması günlük işlerdendir; cam kaplama, boya ve cila daha seyrek yapılır.","konu":"5.2"},{"id":"kh1-5-s146","tur":"dogru-yanlis","soru":"Yürüyüş yollarında günlük temizlik yalnızca çöp toplamayı kapsar; aydınlatma ve yönlendirme levhalarına bakılmaz.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yürüyüş yolunda çöp kovaları boşaltılır, yapraklar toplanır, çöpler süpürülür; aydınlatma ve yönlendirme levhaları da kontrol edilir.","konu":"5.2.2"},{"id":"kh1-5-s147","tur":"dogru-yanlis","soru":"Plajda yeni kum eleme ve temizlikten önce serilir; kum serme, temizliğin ilk adımıdır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Önce kum elenip plaj temizlenir; gerekiyorsa yeni kum bundan sonra, temizliğin son adımı olarak serilir.","konu":"5.2.2"},{"id":"kh1-5-s148","tur":"dogru-yanlis","soru":"Su parkları genellikle geniş alanlara kurulmuş işletmelerde havuzlarla birlikte bulunur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Geniş alanlı konaklama işletmelerinde havuzlarla birlikte çeşitli aktivitelerin yer aldığı su parkları da bulunabilir.","konu":"5.2.2"},{"id":"kh1-5-s149","tur":"coktan-secmeli","soru":"Havuzların işletme için önemli gelir kaynağı sayılmasının nedeni hangisidir?","secenekler":["Havuz suyunun işletme dışına satılması","Abonelik ve etkinliklerle gelir sağlanması","Her konuktan ayrıca havuz ücreti alınması","Havuz çevresinin dışarıya kiraya verilmesi"],"dogru":1,"aciklama":"Havuzlar abonelik sistemleriyle ve toplu yemek, düğün gibi etkinliklerle de kullanıma sunulur; bu yüzden gelir kaynağıdır.","konu":"5.2.2"},{"id":"kh1-5-s150","tur":"dogru-yanlis","soru":"Plajda arızalı şemsiyeler kontrol edilip yenileriyle değiştirilir; çünkü arızalı şemsiye rüzgârda tehlikeli olabilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Arızalı şemsiye rüzgârda tehlikeli olabilir; bu yüzden şemsiyeler kontrol edilir, arızalı olanlar değiştirilir ve gün sonunda hepsi toplanır.","konu":"5.2.2"},{"id":"kh1-5-s151","tur":"coktan-secmeli","soru":"Meydan arabası iş bitince nereye getirilir ve ne yapılır?","secenekler":["Alana bırakılıp ertesi sabah toplanır ve temizlenir","Çamaşırhaneye götürülüp yıkanıp kurutulur","Ofise getirilip temizlenir, eksikleri tamamlanır","Kullanılmış malzemesiyle birlikte olduğu gibi saklanır"],"dogru":2,"aciklama":"Temizlik bittikten sonra araba ofise getirilip temizlenir ve eksikleri tamamlanır; sonraki görevli hazır ekipmanla işe başlar.","konu":"5.2.3"},{"id":"kh1-5-s152","tur":"coktan-secmeli","soru":"Meydan arabasında çöp torbası ve sepetin bulunmasının nedeni nedir?","secenekler":["Atıkları ve kirli bezleri çamaşırhaneye götürmek","Çöp toplamak ve malzemeleri taşımak","Havuz suyunu boşaltıp seviyesini düzenlemek","Konuk eşyasını güvenle saklayıp teslim etmek"],"dogru":1,"aciklama":"Çöp torbası çöp toplamak, sepet ise küçük malzemeleri topluca taşımak içindir.","konu":"5.2.3"},{"id":"kh1-5-s153","tur":"coktan-secmeli","soru":"Giyinme kabinlerinde uygulanan dezenfeksiyonun gün içinde sıklığı neye göre belirlenir?","secenekler":["Sezonun aylarına göre","Kabinin kullanım sıklığına göre","Plajdaki şezlong sayısına göre","Personelin vardiya saatine göre"],"dogru":1,"aciklama":"Soyunma kabini yüzeyleri ve dezenfeksiyon işlemleri kullanım sıklığına göre yapılır.","konu":"5.2.2"},{"id":"kh1-5-s154","tur":"dogru-yanlis","soru":"Plaj ve açık havuz yaz sezonu boyunca açık tutulurken kapalı havuzlu işletmeler yıl boyunca hizmet verir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Açık havuz ve plaj sezonluk, kapalı havuz ise on iki ay hizmet verir.","konu":"5.2.2"},{"id":"kh1-5-s155","tur":"coktan-secmeli","soru":"Akşam gösterisinin ardından kademeli oturma düzenli açık hava sahnesinin basamaklarında bardak ve çöp kaldı. Hangi alanı temizliyorsun?","secenekler":["Açık hava diskosu","Süs havuzu","Yürüyüş yolu","Amfi tiyatro"],"dogru":3,"aciklama":"Amfi tiyatro kademeli oturma düzenli açık hava sahnesidir; çok sayıda konuk oturduğu için çöp ve dökülen içecek hemen toplanır. Açık hava diskosu ise çatısı olmayan gece eğlence alanıdır.","konu":"5.2.2"},{"id":"kh1-5-s156","tur":"coktan-secmeli","soru":"Bahçedeki bir havuz yüzme için kullanılmıyor, yalnızca bahçeyi güzelleştiriyor. Bu havuz hangisidir?","secenekler":["Açık havuz","Süs havuzu","Su parkı","Kapalı havuz"],"dogru":1,"aciklama":"Süs havuzu bahçe düzenlemesinin parçasıdır ve yüzmeye ayrılmaz; açık havuz, kapalı havuz ve su parkı konukların kullanımı içindir.","konu":"5.2.2"},{"id":"kh1-5-s157","tur":"coktan-secmeli","soru":"Bir maçtan sonra spor alanındaki tribünde hangi temizlik yapılır?","secenekler":["Zeminin cilası sökülüp yenilenir","Yalnızca duşlar temizlenip bırakılır","Temizlik tamamen teknik servise bırakılır","Çöp toplanır, oturma yerleri silinir"],"dogru":3,"aciklama":"Tribün ve oturma alanlarındaki çöpler toplanır, oturma yerlerinin tozu alınır; spor alanında bu günlük işlerdendir.","konu":"5.2.2"},{"id":"kh1-5-s158","tur":"dogru-yanlis","soru":"Otellerin açık spor alanları yalnızca konuklara açıktır; profesyonel spor kulüpleri burada kamp yapamaz.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Oteller açık spor alanlarını hem konuklara hem de profesyonel kulüplerin kamp ve antrenmanlarına açabilir.","konu":"5.2.2"},{"id":"kh1-5-s159","tur":"coktan-secmeli","soru":"Konuğun havuza girmeden önce ayaklarını yıkadığı ve dezenfekte ettiği alan hangisidir?","secenekler":["Üst değiştirme kabinleri ve duş alanı","Havlu dağıtım ve toplama noktası alanı","Ayak yıkama ve dezenfekte alanı","Taşma kanalı ve çevresindeki alan"],"dogru":2,"aciklama":"Havuza girmeden önce kullanılan bu alan ayak yıkama ve dezenfeksiyon alanıdır; kabin üst değiştirmek, dağıtım alanı havlu vermek içindir.","konu":"5.2.2"},{"id":"kh1-5-s160","tur":"coktan-secmeli","soru":"Meydan ofisi hangi amaçla kullanılır?","secenekler":["Malzeme saklanan, arabanın yüklendiği ofistir","Konuk kayıp eşyalarının teslim alındığı birimdir","Teknik servisin makine onardığı atölyedir","Plaj havlularının dağıtıldığı noktadır"],"dogru":0,"aciklama":"Genel alan malzemeleri meydan ofisinde saklanır; araba oradan yüklenir ve iş bitince ofise geri getirilir.","konu":"5.1.3"},{"id":"kh1-5-s161","tur":"coktan-secmeli","soru":"Giriş camındaki parmak izlerini lekesiz silmek için hangi alet kullanılır?","secenekler":["Mop aleti","Cam silme aleti","Sert zemin fırçası","Çöp faraşı"],"dogru":1,"aciklama":"Cam yüzeylerde cam silme aleti kullanılır; mop zemin içindir, faraş çöp toplamak içindir.","konu":"5.2.3"},{"id":"kh1-5-s162","tur":"coktan-secmeli","soru":"Çim alandaki yaprak ve çöpleri toplamak için hangi alet kullanılır?","secenekler":["Mop","Cam silme aleti","Tırmık","Elektrik süpürgesi"],"dogru":2,"aciklama":"Yeşil alanlar tırmıkla temizlenir; sert zemin için süpürge ve fırça kullanılır.","konu":"5.2.4"},{"id":"kh1-5-s163","tur":"coktan-secmeli","soru":"Uygulamada iş öncesi görev talimatı nasıl alınır?","secenekler":["Meydan arabasını alıp doğrudan alana giderek","Toplantıya katılıp şeften programı öğrenerek","Önceki vardiyadan iş programını sorarak","Konuk geri bildirimlerini okuyup yönelerek"],"dogru":1,"aciklama":"Görev talimatı için toplantıya katılınır ve iş programı genel alanlar şefinden öğrenilir.","konu":"5.1.4"},{"id":"kh1-5-s164","tur":"coktan-secmeli","soru":"Uygulamaya başlamadan önce kişisel bakım adımında takılar için hangisi yapılır?","secenekler":["Üniformanın altına saklanır","Takılar çıkarılır","Yalnızca yüzük bırakılır","Üniformanın cebine konup yanında taşınır"],"dogru":1,"aciklama":"İş öncesi kişisel bakımda takılar çıkarılır; hijyen ve güvenlik gerekir.","konu":"5.1.4"},{"id":"kh1-5-s165","tur":"dogru-yanlis","soru":"Kimyasal temizleyiciyle çalışmaya başladıktan sonra eldiven ve maske takılması yeterlidir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Eldiven ve maske kimyasalla çalışmaya başlamadan önce takılır.","konu":"5.1.1"},{"id":"kh1-5-s166","tur":"dogru-yanlis","soru":"Kaymaz tabanlı ayakkabı giyen görevlinin ıslak zeminde uyarı levhası koymasına gerek kalmaz.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Ayakkabı görevliyi korur, levha ise konuğu uyarır; ikisi birlikte uygulanır.","konu":"5.1.1"},{"id":"kh1-5-s167","tur":"dogru-yanlis","soru":"Açık alanda bir kaza olduğunda ilk yardım bilen personel müdahale edebilir ya da doğru yardımı çağırabilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Personelin oluşabilecek kazalara karşı ilk yardım bilgisine sahip olması dış mekân güvenlik önlemlerindendir.","konu":"5.2.1"},{"id":"kh1-5-s168","tur":"dogru-yanlis","soru":"Plajda havlu takibi yapılır; çünkü takip kaybolan havluların sayısını azaltır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Takip kaybolan havluların sayısını azaltır; konuğun elinde temiz havlu bulunması da memnuniyeti artırır.","konu":"5.2.2"},{"id":"kh1-5-s169","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi günlük dış mekân temizliği işi değildir?","secenekler":["Sert yüzeyleri süpürüp paspaslamak","Tuvalet ve giyinme kabinlerini temizlemek","Çöp poşetlerini değiştirmek","Dış yüzeylerin yeniden boyanması"],"dogru":3,"aciklama":"Boyama periyodik işlerdendir. Diğer üçü günlük temizlikte yapılır.","konu":"5.2"},{"id":"kh1-5-s170","tur":"coktan-secmeli","soru":"Dış mekân temizliği günlük, haftalık, aylık ve periyodik planlanır ve hangi bölüm tarafından uygulanır?","secenekler":["Ön büro","Yiyecek içecek","Kat hizmetleri","Teknik servis"],"dogru":2,"aciklama":"Dış mekân temizliğinin planı kat hizmetlerince yapılır ve uygulanır.","konu":"5.2"},{"id":"kh1-5-s171","tur":"senaryo","durum":"Öğleden sonra 15.00’te plajdaki soyunma kabinini kontrol ederken yerde bir cüzdan buldun. Konuk görünürde yok.","soru":"Ne yaparsın?","secenekler":["Cüzdanın içine bakıp sahibini kendin aramaya çalışırsın","Cüzdanı karıştırmadan kaydını tutup ön büroya teslim edersin","Plaj barı görevlisine bırakıp konuk gelirse almasını söylersin","Cüzdanı kabinde bırakıp kapıyı kapatırsın"],"dogru":1,"aciklama":"Unutulan eşya gerekli yerlere teslim edilir. Kaydı tutmak hem eşyayı hem seni korur; barda bırakmak ya da kabinde bırakmak eşyanın kaybolmasına yol açabilir.","konu":"5.2.2"},{"id":"kh1-5-s172","tur":"senaryo","durum":"Sabah 11.00’de havuz kenarındaki açık duş alanının zeminini yıkaman gerekiyor. Konuklar o bölümde dolaşıyor.","soru":"Ne yaparsın?","secenekler":["Konuklara dikkat etmelerini söyleyip yıkamaya devam edersin","Konuk azalınca hızlıca yıkar, levha koymazsın","Levha koyup alanı kapatır, kaymayan ayakkabınla yıkarsın","Yıkamayı akşama bırakıp alanı olduğu gibi bırakırsın"],"dogru":2,"aciklama":"Islak zemin temizliğinden önce levha konur ve alan kapatılır. Konuklara sözle uyarmak yeterli değildir; işi sürekli ertelemek ise alanın kirli kalmasına neden olur.","konu":"5.2.1"},{"id":"kh1-5-s173","tur":"senaryo","durum":"Akşam 20.30’da bahçe yolunda lambalardan birinin yanmadığını fark ettin. Yoldan konuklar geçiyor.","soru":"İlk adımın ne olur?","secenekler":["Merdiven getirip lambayı kendin değiştirirsin","Şef gelene kadar bir şey yapmadan beklersin","Arızayı teknik servise hemen bildirirsin","Sabah turunda not almak üzere aklında tutarsın"],"dogru":2,"aciklama":"Aydınlatma arızası teknik servise bildirilir; onarım görevlinin işi değildir. Beklemek ya da ertelemek karanlık yolda kaza riskini sürdürür.","konu":"5.2.2"},{"id":"kh1-5-s174","tur":"senaryo","durum":"Sabah 09.30’da plaj tuvaletinde lekeli bir lavabo yıkıyorsun. İki ayrı temizlik ürünün var ve leke zor çıkıyor.","soru":"Ne yaparsın?","secenekler":["İki ürünü karıştırıp etkisini artırmaya çalışırsın","Etiketi okuyup ürünleri ayrı kullanır, maske ve eldiven takarsın","Maskeni çıkarıp işi daha hızlı bitirmek için çalışmaya başlarsın","Lekeli lavaboyu temizlemeden bırakıp sıradaki bölüme geçersin"],"dogru":1,"aciklama":"Ürünler karıştırılmaz; zehirli gaz oluşabilir. Maske ve eldiven işe başlamadan takılır ve alan havalandırılır.","konu":"5.2.1"},{"id":"kh1-5-s175","tur":"senaryo","durum":"Öğleden sonra 16.00’da havuz çevresindeki temizliği bitirdin. Meydan arabası ve makineler hâlâ alanda.","soru":"Ne yaparsın?","secenekler":["Kirli bezleri temiz bezlerin yanına koyup arabayı ofise bırakırsın","Arabayı alanda bırakıp işe ertesi sabah aynı arabayla devam edersin","Yalnızca makineleri toplar, kirli bezleri arabada bırakıp gidersin","Cihazları toplar, arabayı ofiste temizleyip eksiği tamamlarsın"],"dogru":3,"aciklama":"İş bitiminde cihazlar toplanır, temizlenir; araba ofise getirilip temizlenir ve eksikleri tamamlanır. Kirli bezler ayrı hazırlanır.","konu":"5.2.3"},{"id":"kh1-5-s176","tur":"senaryo","durum":"Sabah 08.30. Lobideki ahşap kaplı resepsiyon panelinde parmak izleri var. Meydan arabasında çalı süpürge ile petrol bazlı bir ürün duruyor ve acele ediyorsun.","soru":"Ne yaparsın?","secenekler":["Petrol bazlı ürünü bezle sürerek panelin parlaması için hızlıca silerim","Çalı süpürgeyle paneli çizmeden hafifçe süpürerek kirleri alırım","Yumuşak bezle ahşap temizleyicisini kullanıp paneli nazikçe silerim","Paneli kuru bırakıp parmak izlerini akşam vardiyasına bırakırım"],"dogru":2,"aciklama":"Ahşapta sert fırça ve çalı süpürge çizer, petrol ürünleri ahşabı bozar; yumuşak bezle uygun malzeme kullanılır. Parmak izini bekletmek ise ilk izlenimi bozar.","konu":"5.1.2"},{"id":"kh1-5-s177","tur":"senaryo","durum":"Gece 23.30. Şefin yeni aldığı halı şampuanını açık renkli koridor halısında ilk kez kullanacaksın. Koridor boş ve alan kapatılmış durumda.","soru":"Ne yaparsın?","secenekler":["Şampuanı doğrudan koridorun tamamına sürüp makineyi çalıştırırım","Önce ürünü mobilyanın arkasındaki görünmeyen köşede denerim","Şefin aldığı üründür diye hiç denemeden kolay görünen bir noktada başlarım","Lekeler kesin çıksın diye şampuanı iki kat yoğun kullanırım"],"dogru":1,"aciklama":"İlk kez kullanılan ürün önce görünmeyen yerde denenir; rengi soldurursa görünür alan zarar görmez. Diğer şıklar halıyı riske atar.","konu":"5.1.2"},{"id":"kh1-5-s178","tur":"senaryo","durum":"Sabah 10.00. Plajdaki ağır bir şezlongu temizlik için başka yere çekmen gerekiyor. Yanında yalnızca sen varsın, diğer görevli biraz uzakta çalışıyor.","soru":"Ne yaparsın?","secenekler":["Beli öne eğip şezlongu tek hamlede kaldırırım, çünkü vakit kaybetmek istemem","Temizliği yapmadan şezlongu olduğu yerde bırakıp sonraki işe geçerim","Yardım istemeden dizlerimi bükmeden, hızlıca kaldırmayı denerim","Arkadaşımı çağırır, dizlerimi bükerek birlikte taşırız"],"dogru":3,"aciklama":"Ağır eşya uygun pozisyonla ve gerekirse yardım alınarak taşınır; yanlış kaldırma bel ve omurgaya zarar verir. Yardım istemek güvenlik kuralıdır.","konu":"5.2.1"},{"id":"kh1-5-s179","tur":"senaryo","durum":"Akşam 19.00. Kapalı otoparkı temizlerken havalandırmanın çalışmadığını ve egzoz kokusunun biriktiğini fark ettin. Otoparkta araçlar var.","soru":"Ne yaparsın?","secenekler":["Koku zaten araçlardan geldiği için temizliği hızla bitirip çıkarım","Arızayı teknik servise bildirir, şefimi de haberdar ederim","Havalandırmayı kendim açmaya çalışıp panoyu kurcalarım","Kokuyu parfümle bastırır, kimseye söylemeden devam ederim"],"dogru":1,"aciklama":"Havalandırması arızalı kapalı alanda egzoz gazı ve koku birikir; arıza teknik servise bildirilir. Kendi başına müdahale ya da kokuyu gizlemek sorunu çözmez.","konu":"5.2.2"}],"siralamalar":[{"id":"kh1-5-r01","konu":"5.1.3","baslik":"Meydan arabasını hazırlama","yonerge":"Genel alan görevlisi olarak işe başlarken meydan arabasını hazırlama adımlarını sıraya koy.","adimlar":["Genel alanlar şefinden meydan ofisinin anahtarını teslim al.","Meydan ofisine git ve koruyucu eldivenini giy.","Arabadaki dolu çöp torbasını yenisiyle değiştir ve arabayı gözden geçirip eksik malzemeleri belirle.","Eksik tuvalet kâğıdı, kâğıt havlu ve sabunu tamamla.","Arabayı dikkatli bir şekilde temizlenecek alana götür."],"aciklama":"Ofisin anahtarı şeften alınır ve ofiste eldiven giyilir; çöp torbası yenilenip eksikler belirlenir, ardından tamamlanır ve araba en son alana götürülür."},{"id":"kh1-5-r02","konu":"5.1.2","baslik":"Mermer zemine cila uygulaması","yonerge":"Genel alan görevlisi olarak mermer zemini cilalama adımlarını sıraya koy.","adimlar":["Makinenin çalışmasını, kablo ve fişte kaçak olup olmadığını kontrol et.","Makineyi alana getir ve “Dikkat Kaygan Zemin” levhasını koy.","Tanka cila sökücü kimyasalla hazırlanmış su koy.","Siyah sert pedle eski cilayı ov ve kimyasallı suyu vakumla çek.","Zemini temiz suyla durula ve paspasla kurula.","Cilayı ince katlar hâlinde zemine püskürt.","Makineyle cilayı kurutmayacak biçimde ovalayarak zemine yedir.","Zemini detaylı olarak mopla sil."],"aciklama":"Güvenlik ve makine kontrolü başta gelir; eski cila sökülüp zemin durulandıktan sonra yeni cila sürülür, yedirilir ve son olarak mopla temizlenir."},{"id":"kh1-5-r03","konu":"5.1.4","baslik":"Lobi temizliği","yonerge":"Genel alan görevlisi olarak lobinin günlük temizliğini yaparken adımları sıraya koy.","adimlar":["Kişisel bakım yap, üniformanı giy ve isimliğini tak.","Şefinden iş programını öğren, meydan ofisinden arabayı ve gereçleri al.","Arabayı lobiye getir.","Oturma grubunun ve mobilyaların tozunu al, çöpleri boşalt.","Uyarı levhasını yerleştirip zemini tozdan arındır, cinsine göre (taş, ahşap, halı) temizle.","Kullandığın araç gereçleri toplayıp arabayı temizle."],"aciklama":"Hazırlık ve plan ilk iştir; toz alma ve çöp boşaltma zemin işinden önce yapılır ki toz yeni temizlenen zemine düşmesin; levha zemin işiyle birlikte konur; toplama ve araba temizliği en sonda gelir."},{"id":"kh1-5-r04","konu":"5.1.4","baslik":"Asansör temizliği","yonerge":"Genel alan görevlisi olarak bir asansörü temizleme adımlarını sıraya koy.","adimlar":["Kişisel bakım yap, üniformanı giy ve iş programını öğren.","Arabayı alıp asansörlerin bulunduğu lobiye git.","Temizlikle ilgili güvenlik uyarı levhalarını ve işaretlerini yerleştir.","Duvarları, aynaları ve içteki düğmeleri temizleyip dezenfekte et.","Asansör zeminini ve kapı raylarını tozdan arındırıp uygun şekilde sil.","Kullandığın bezleri rengine göre ayrı poşetlere koy."],"aciklama":"Asansör lobide temizlenir; önce levha konur, temizlik yukarıdan aşağıya ilerler (duvar ve düğmeler, sonra zemin ve raylar) ve bezler en son ayrılır."},{"id":"kh1-5-r05","konu":"5.1.4","baslik":"Genel tuvalet temizliği","yonerge":"Genel alandaki bir tuvaleti temizlerken adımları sıraya koy.","adimlar":["Temizlik arabasını hazırla ve tuvaletin önüne getir.","Kapıyı çalıp “Housekeeping” diye seslen, içeride kimse olmadığından emin olup gir ve eldivenini giy.","Kabin içindeki ve dışındaki çöp kovalarını boşalt.","Klozetleri, pisuvarları, lavaboları ve aynaları uygun kimyasal ve bezle temizle.","Zemini kabin içinden girişe doğru paspasla.","WC kontrol fişini doldurup imzala."],"aciklama":"Araba hazırlanır; kapı çalınıp içeride kimse olmadığından emin olunur, içeri girilir ve eldiven giyilir. Çöp kovaları boşaltılır, yüzeyler temizlenir, zemin kabin içinden girişe doğru silinir ve temizlik en son fişle kayıt altına alınır."},{"id":"kh1-5-r06","konu":"5.1.4","baslik":"Halı yıkama","yonerge":"Genel alanda halı yıkarken adımları sıraya koy.","adimlar":["Elektrikli süpürge ve halı yıkama makinesinin elektrik bağlantılarını ve prizlerini kontrol et.","Halıyı elektrikli süpürgeyle tozdan arındır.","Lekeleri leke çıkarıcı kimyasalla dıştan merkeze doğru uygula.","Makineye ölçülü su ve şampuan koyup köpüklü suyu halıya yay.","Halıdaki köpüğü ve fazla suyu vakumla çek.","Makinenin kirli su tankını boşalt, fırçalarını yıka, süpürgeyi temizleyip yerine koy."],"aciklama":"Elektrik güvenliği ilk kontroldür; halı yıkanmadan önce tozdan arındırılır ve lekeler çıkarılır; yıkama, köpük çekme ve ekipman temizliği bu sırayla biter."},{"id":"kh1-5-r07","konu":"5.1.4","baslik":"Cam temizliği","yonerge":"Genel alandaki bir camı temizlerken adımları sıraya koy.","adimlar":["Güvenlik kurallarına uy ve perdelerin ıslanmaması için tedbir al.","Cam yüzeyine sprey şeklinde cam temizlik sıvısı sık.","Lastikli cam silme aletiyle “S” çizerek yukarıdan aşağıya doğru sil.","Camın alt kenarında toplanan suyu kuru bezle alıp camı silerek parlat.","Yağ veya leke kaldıysa işlemi tekrarla.","Kullandığın bezleri poşetlerine koy, cam silme aletini ve diğer araçları yıkayıp kurumaya bırak."],"aciklama":"Güvenlikle başlanır; sıvı sıkılıp aletle yukarıdan aşağıya silinir, alt kenarda biriken su alınıp cam parlatılır; en sonda araçlar yıkanır."},{"id":"kh1-5-r08","konu":"5.2.4","baslik":"Dış mekân görevine hazırlık","yonerge":"Genel alan görevlisi olarak iş öncesi adımları sıraya koy.","adimlar":["Kişisel bakım ve hijyen kurallarına uy, takılarını çıkar.","Üniformanı giy, isimliğini tak ve güneşe karşı önlemlerini al.","Kat hizmetleri müdürünün yaptığı toplantıya katıl.","Genel alanlar şefinden günlük iş programını öğren ve meydan ofisinin anahtarını teslim al.","Meydan ofisinden meydan arabasını alıp temizlik yapılacak alana git."],"aciklama":"Önce kendi hazırlığın tamamlanır, sonra günün talimatı ve anahtar alınır, en son araç gereçle alana gidilir."},{"id":"kh1-5-r09","konu":"5.2.2","baslik":"Bahçe ve yürüyüş yolu temizliği","yonerge":"Bahçede günlük temizlik adımlarını sıraya koy.","adimlar":["Nemli bezle dış mekân mobilyalarının tozunu al.","Yaprak ve çöpleri sert yüzeyde fırçayla süpür, yeşil alanda tırmıkla topla.","Toplanan çöpleri çöp sepetine ya da konteynere koy.","Alanın kullanım yoğunluğuna göre işlemleri tekrarla."],"aciklama":"Toz önce alınır ki yere düşen kir sonra süpürülsün; toplanan çöp hemen taşınır, işlemler en sonda kullanım yoğunluğuna göre tekrarlanır."},{"id":"kh1-5-r10","konu":"5.2.2","baslik":"Plaj kabinlerinin temizliği","yonerge":"Plajdaki soyunma kabini, tuvalet ve duş temizliğini sıraya koy.","adimlar":["Kabin, tuvalet ve duşları kontrol et, bulduğun kayıp eşyayı teslim et.","Güvenlik ve uyarı levhalarını yerleştir, lavaboları kimyasal ve sünger ile yıka, ayna ve muslukları sil.","Zemini kabinin içinden başlayarak dışarıya doğru paspasla.","Levhaları ve diğer malzemeleri topla."],"aciklama":"Kontrol ve levha hazırlığı başta gelir; lavabo ve aynalar temizlenir, zemin içeriden dışarıya paspaslanır, levha ve malzemelerin toplanması en sonda gelir."},{"id":"kh1-5-r11","konu":"5.2.2","baslik":"Havuz çevresinin günü","yonerge":"Havuz çevresindeki işleri gün akışına göre sıraya koy.","adimlar":["Havuz açılmadan önce şezlong, minder ve şemsiyeleri düzenli yerleştir.","Havuz açıkken konukların arasında dolaşıp çöpleri topla, kül tablalarını boşalt.","Havuz kapanınca şezlong, şemsiye, sehpa ve minderleri topla ve dezenfekte et.","Bezleri renklerine göre ayrı poşetlere koy, meydan arabasını ofise getirip temizle."],"aciklama":"İş açılışta düzenle başlar, gün içinde kontrolle sürer, kapanışta toplama ve dezenfeksiyonla biter; en sonda bezler ayrılır ve araba ofise teslim edilir."},{"id":"kh1-5-r12","konu":"5.2.3","baslik":"Meydan arabasının günü","yonerge":"Meydan arabasının yüklenmesinden ofise dönüşüne kadar adımları sıraya koy.","adimlar":["Meydan ofisinden gerekli malzemeleri arabaya yükle.","Arabayı ve işe uygun makineleri temizlenecek alana götür.","Temizliği yap.","Kullanılan tüm cihaz ve malzemeleri topla.","Arabayı ve makineleri meydan ofisine getir, temizle ve eksik malzemeleri tamamla."],"aciklama":"Önce hazırlık ve işe gidiş, sonra temizlik, en sonda toplama ve ofise dönüş gelir; araba temiz ve tam dolu teslim edilir."}],"acikSorular":[{"id":"kh1-5-y01","konu":"5.1.2","soru":"Otelin lobisindeki açık renkli halıda leke var ve halının yıkanması gerekiyor. Yıkamaya başlamadan önce yapılacak hazırlığı, yıkama sırasındaki uygulamaları ve yıkamadan sonra alınacak önlemi yazınız; bu sıranın neden önemli olduğunu açıklayınız.","olcut":[{"metin":"Yıkamadan önce halının elektrikli süpürgeyle tozdan arındırıldığını belirtir.","puan":15},{"metin":"Lekenin leke çıkarıcı kimyasalla dıştan merkeze doğru çıkarıldığını yazar.","puan":15},{"metin":"Daha önce kullanılmamış bir ürünün önce halının görünmeyen bir bölümünde denendiğini belirtir.","puan":20},{"metin":"Halı şampuanı ve yıkama makinesi kullanıldıktan sonra köpüğün ve fazla suyun vakumla çekildiğini yazar.","puan":15},{"metin":"Halı tam kurumadan üzerine eşya yerleştirilmemesi gerektiğini belirtir.","puan":10},{"metin":"Sıranın önemini mantıklı gerekçelerle açıklar: hazırlık adımları (toz alma, leke çıkarma, deneme) halıya zarar verilmesini önler; yıkama sonrası adımlar (vakumla çekme, kurumadan eşya koymama) halının düzgün kurumasını sağlar.","puan":25}],"ornek":"Önce halı elektrikli süpürgeyle vakumlanarak tozdan arındırılır. Leke varsa leke çıkarıcı kimyasalla dıştan merkeze doğru çıkarılır; daha önce kullanılmamış bir ürün halının görünmeyen bir bölümünde denenir. Sonra halı, halı yıkama makinesi ve halı şampuanıyla yıkanır; şampuan köpürtülerek halının derinlerine kadar işlemesi sağlanır. Yıkamadan sonra köpük ve fazla su vakumla çekilir, halı tam kurumadan üzerine eşya yerleştirilmez. Bu sıra önemlidir: hazırlık ve deneme adımları, özen gerektiren açık renkli halının zarar görmesini önler; vakumla çekme ve kurumayı beklemek ise halının düzgün kurumasını sağlar.","ipucu":"Her adım atlandığında halıya ya da temizliğe ne gibi bir zarar gelebileceğini düşünün."},{"id":"kh1-5-y02","konu":"5.1.1","soru":"Genel alan temizliği yapan yeni bir meydancı, tuvalet temizliğinde işi hızlandırmak için iki ayrı temizlik ürününü karıştırmak istiyor. Bu davranışın neden yanlış olduğunu açıklayınız ve kimyasallarla çalışırken alınması gereken diğer güvenlik önlemlerini yazınız.","olcut":[{"metin":"Temizlik ürünlerinin birbirine karıştırılmaması gerektiğini belirtir.","puan":15},{"metin":"Bazı ürünlerin bir arada kullanılmasının zehirli gaz oluşturduğunu yazar.","puan":20},{"metin":"Kimyasallarla çalışırken eldiven ve maske takılması gerektiğini belirtir.","puan":15},{"metin":"Ürünlerin içeriğinin ve kullanım talimatının bilinmesi, uyarılara uyulması gerektiğini yazar.","puan":15},{"metin":"Kimyasalla çalışılan alanın havalandırılması gerektiğini belirtir.","puan":10},{"metin":"Önlemlerin neden gerekli olduğunu açıklar: iç mekânlarda temizlik konuklar alanı kullanırken yapıldığından zehirli gaz yalnız çalışanı değil çevredeki konukları da etkileyebilir.","puan":25}],"ornek":"Temizlik ürünleri birbirine karıştırılmamalıdır. Çünkü bazı ürünler bir arada kullanılınca zehirli gaz oluşturur. Meydancı bundan önce ürünün içeriğini ve kullanım talimatını öğrenmeli, uyarılara uymalıdır. Kimyasalla çalışırken eldiven ve maske takmalı, çalıştığı alanı havalandırmalıdır. Bu önlemler alınmazsa zehirli gaz hem temizlik görevlisinin hem tuvaleti kullanan konukların solunum yollarına zarar verir.","ipucu":"Hızlı çalışmak ile güvenli çalışmak arasındaki farkı düşünün; önlemlerin kimi hangi tehlikeden koruduğuna bakın."}]}]`),r=JSON.parse(`[{"ders":"kat-hizmetleri-10","onay":true,"diyaloglar":[{"id":"kh1-d01","unite":1,"baslik":"İki Rapor, Tek Oda","rol":"Kat şefi","karsi":"Ön büro görevlisi","sahne":"Saat 10.20. Ön büro, 618 numaralı odayı kendi raporunda boş temiz, kat hizmetleri raporunda ise dolu görüyor ve kat ofisini arıyor. Kat görevlisi Selin sabah turunda odada valiz ve kullanılmış bir yatak görüp dolu yazmıştı; telefona kat şefi çıkıyor.","kavramlar":["kh1-1-249","kh1-1-250","kh1-1-251","kh1-1-252","kh1-1-253","kh1-1-254","kh1-1-255"],"adimlar":[{"konuk":"Günaydın, ön büro arıyor. 618 numaralı oda bizim raporda boş temiz, sizin raporda dolu görünüyor. Hangisi doğru?","ingilizce":"Good morning, front office here. Room 618 shows as vacant clean on our report but occupied on yours. Which one is correct?","secenekler":[{"metin":"Bizim rapor, kat görevlimizin sabah odada gördüklerine dayanıyor. Siz önce kendi kaydınıza bir bakın, sonra konuşalım.","puan":1,"tepki":"Ön büro görevlisi “Peki, bakarız” der ama konu açıkta kalır. Farkın kimde olduğunu tartışmak yerine odayı yeniden kontrol edip son durumu bildirmek gerekir."},{"metin":"Günaydın. İki rapor uyuşmuyor, bu bir uyuşmazlık. Odayı hemen yeniden kontrol edip size telefonla dönerim.","ingilizce":"Good morning. The two reports do not match, so this is a discrepancy. I will check the room again now and phone you back.","puan":2,"tepki":"Ön büro görevlisi rahatlar: “Tamam, bekliyorum.” Uyuşmazlık çıkınca odayı yeniden kontrol edip son durumu ön büroya bildirmek, iki bölümün aynı bilgiye ulaşmasını sağlar."},{"metin":"Bizim rapor kesin doğru, sizin kayıt yanlış. Odayı yeniden kontrol etmeme gerek yok, siz düzeltin.","puan":0,"tepki":"Ön büro görevlisi şaşırır: “Emin misiniz?” Odaya yeniden bakmadan kesin konuşmak yanlış bilgiye yol açar; neden bulunmadan uyuşmazlık çözülmez."}]},{"konuk":"Bu oda öğleden sonra gelecek bir konuk için ayrıldı. Kontrolü bir an önce yapabilir misiniz?","ingilizce":"That room has been set aside for a guest arriving this afternoon. Could you check it as soon as possible?","secenekler":[{"metin":"Tamam, şu an elimde bir iş var. Onu bitirir bitirmez odaya bakıp size dönerim.","puan":1,"tepki":"Ön büro görevlisi gerginleşir: “Ne zaman, tam olarak?” Satış bekleyen bir odada ön büronun kat hizmetlerinin yanıtına ihtiyacı vardır; uyuşmazlık çıkan oda sıraya bırakılmaz."},{"metin":"Odayı sabah kat görevlimiz gördü, ona sorun. Ben bu işe karışmayayım; rapor zaten onun imzasıyla gelmişti.","puan":0,"tepki":"Ön büro görevlisi hayal kırıklığına uğrar. Uyuşmazlıkta odayı yeniden kontrol edip son durumu bildirmek kat hizmetlerinin görevidir; kat şefi sorumluluğu başkasına atmaz."},{"metin":"Elbette, hemen gidiyorum. Yatağa, valize ve konuk eşyalarına bakıp birkaç dakika içinde size dönerim.","ingilizce":"Of course, I am going there now. I will look at the bed, the luggage and any belongings, and ring you back in a few minutes.","puan":2,"tepki":"Ön büro görevlisi: “Teşekkürler, sonucu bekleyip odayı ona göre vereceğim.” Yatak, valiz ve konuk eşyaları odanın gerçek durumunu gösterir; ön büro odayı satabilmek için bu son durumu bekler."}]},{"konuk":"Odayı gördünüz mü? Son durum nedir?","ingilizce":"Have you seen the room? What is the final status?","secenekler":[{"metin":"Baktım, oda dolu gibi duruyor. Eşyalar var ama yatak için emin değilim, sanırım bizim rapor doğru olmalı.","puan":1,"tepki":"Ön büro görevlisi kararsız kalır: “Gibi mi, kesin mi?” “Gibi” ve “sanırım” içeren bir yanıt kaydı düzeltmeye yetmez; son durum açık ve net bildirilir."},{"metin":"618 dolu: valiz ve eşyalar içeride, yatak kullanılmış. Kaydınızı kontrol etmenizi rica ederim.","ingilizce":"Room 618 is occupied: the luggage and belongings are inside, and the bed has been used. Please check your record.","puan":2,"tepki":"Ön büro görevlisi kaydı açar: “Çıkış yanlış işlenmiş olabilir.” Kat hizmetlerinin bildirdiği son durum, ön büronun kayıtlarını gerçeğe göre düzeltmesine dayanak olur."},{"metin":"Oda dolu, ama hatayı hep ön büro yapıyor. Kendi kaydınızı düzeltin, bizi de bir daha aramayın.","puan":0,"tepki":"Ön büro görevlisi savunmaya geçer: “Her seferinde mi?” Suçlayıcı dil iki bölüm arasındaki iş birliğini bozar; son durum suçlamadan, olduğu gibi bildirilir."}]},{"konuk":"Teşekkürler. Housekeeper uyuşmazlık raporunu hazırlayacak. Rapora neler yazılmalı?","ingilizce":"Thank you. The executive housekeeper will prepare the discrepancy report. What should go into it?","secenekler":[{"metin":"Kat ve oda numarası, iki bölümün durumu ve kontrol sonucu yan yana yazılmalı; nedenini de birlikte araştıralım.","ingilizce":"The floor and room number, both departments’ statuses and the result of the check should be written side by side, and we should find the cause together.","puan":2,"tepki":"Ön büro görevlisi başını sallar: “Böylece fark bir bakışta görülür.” Uyuşmazlık raporunda iki bölümün durumu yan yana yazılır; neden bulunmadan yapılan düzeltme aynı hatanın tekrarına yol açar."},{"metin":"Rapora hiçbir şey yazılmasın, kaydınızı sessizce düzeltin. Böylece iki bölümün de başı derde girmez.","puan":0,"tepki":"Ön büro görevlisi duraksar: “Peki neden oldu?” Sessiz düzeltme olayı kayıtsız bırakır; nedeni bilinmeyen hata yeniden yaşanır."},{"metin":"Şimdilik yalnız oda numarası yazılsın. Ayrıntılara sonra bakarız, rapor bu kadarıyla da anlaşılır.","puan":1,"tepki":"Ön büro görevlisi kısa bir not alır. Eksik yazılan rapor farkı göstermez; uyuşmazlık raporunda kat, oda, iki bölümün durumu ve kontrol sonucu bulunmalıdır."}]},{"konuk":"Kaydı düzeltiyorum. Böyle bir uyuşmazlığın bir daha çıkmaması için ne yapabiliriz?","ingilizce":"I am correcting the record now. What can we do to stop a discrepancy like this happening again?","secenekler":[{"metin":"Bu tür şeyler olur, her gün her yerde karşımıza çıkıyor. Yine olursa yine konuşuruz, merak etmeyin.","puan":1,"tepki":"Ön büro görevlisi omuz silker: “Peki.” Uyuşmazlığın nedenleri bellidir (eksik işaretleme, işlenmeyen satış, yansımayan değişiklik) ve önlenebilir; “olur” demek çözüm sunmaz."},{"metin":"Siz dikkatli olun yeter, bizim tarafta hata çıkmaz. Kayıtlarınızı iki kez kontrol edip gönderin, hata hep orada oluyor.","puan":0,"tepki":"Ön büro görevlisinin sesi sertleşir. Hatayı tek bölüme yüklemek çözüm getirmez; ön büro ve kat hizmetleri raporları birbirine bağlıdır."},{"metin":"Satış ve oda değişikliğini iki bölüme birlikte bildirelim; odayı da kapıda kontrol edip işaretleyelim.","ingilizce":"Let us report every sale and room change to both departments at the same time, and check each room at the door before marking its status.","puan":2,"tepki":"Ön büro görevlisi memnun olur: “Çok iyi olur, teşekkürler, iyi çalışmalar.” Satış ya da oda değişikliği iki raporda birlikte işlenir, işaretleme de kapıda kontrolle yapılırsa fark baştan doğmaz."}]}]},{"id":"kh1-d02","unite":1,"baslik":"Çekmecede Bulunan Kol Saati","rol":"Kat görevlisi","karsi":"Kat şefi","sahne":"Saat 11.40. Çıkış yapılmış 507 numaralı odayı kontrol eden kat görevlisi, komodinin çekmecesinde bir kol saati buldu ve telsizle haber verdi. Kat şefi Hülya Hanım hemen odanın kapısına geliyor.","kavramlar":["kh1-1-276","kh1-1-277","kh1-1-279","kh1-1-280","kh1-1-281"],"adimlar":[{"konuk":"Telsizden duydum, 507’de bir şey bulmuşsun. Anlat bakalım, ne buldun, nerede?","ingilizce":"I heard on the radio that you found something in 507. Tell me what you found and where.","secenekler":[{"metin":"Çekmecede bıraktım. Çıkış yapan konuk dönerse bulur diye düşündüm, ellemek istemedim.","puan":0,"tepki":"Kat şefi endişelenir: “Oda başka bir konuğa verilebilir.” Bulunan eşya yerinde bırakılırsa kayda geçmez; sahibine teslimde de dayanak kalmaz."},{"metin":"Bir saat buldum, odayı bitirince getiririm. Önce yatağı yapayım, yarım kalmasın.","puan":1,"tepki":"Kat şefi kaşlarını çatar: “Saat hâlâ odada mı?” Eşya oda bitene kadar beklemez; kayda girmeyen eşyanın izi kaybolabilir."},{"metin":"Komodinin çekmecesinde bir kol saati buldum, şu an yanımda. Size teslim ediyorum.","ingilizce":"I found a wristwatch in the bedside drawer. I have it with me, and I am handing it over to you.","puan":2,"tepki":"Kat şefi saati alır: “Doğru yaptın, hemen haber verdin.” Unutulan eşyanın kaydı ve saklanması kat hizmetlerinin sorumluluğudur; bu yüzden bulan kişi eşyayı gecikmeden kat şefine bildirir."}]},{"konuk":"Formu ben düzenliyorum. Eşya hakkında bana hangi bilgileri vereceksin?","ingilizce":"I will fill in the form. What information can you give me about the item?","secenekler":[{"metin":"Saati 507’de buldum, odadan çıkış yapılmıştı. Gerisini siz yazarsınız, ben başka odaya geçeyim, kusura bakmayın.","puan":1,"tepki":"Kat şefi boş alanlar bırakmak zorunda kalır. Eksik bilgi eşyanın kaydını zayıflatır; cins, yer, tarih ve durum açıkça söylenmelidir."},{"metin":"Cinsini, bulunduğu yeri ve tarihi, durumunu ve bulan olarak adımı söylerim.","ingilizce":"I can tell you what it is, where and when I found it, its condition, and my name as the finder.","puan":2,"tepki":"Kat şefi formu hızla doldurur: “Tamam, alanlar eksiksiz.” Formdaki her alan, eşyanın kimden kime geçtiğini izlemeyi sağlar."},{"metin":"Adımı yazmayın, bir sorun çıkarsa uğraşmak istemem. Saatin cinsini ve yerini yazsanız yeter.","puan":0,"tepki":"Kat şefi ciddileşir: “Kayıt kimin bulduğunu da göstermeli.” Bulanın adı olmazsa eşyanın izi sürülemez; her alan kimden kime geçtiğini göstermek için vardır."}]},{"konuk":"Saat oldukça değerli görünüyor. Nerede saklayacağız?","ingilizce":"The watch looks quite valuable. Where shall we keep it?","secenekler":[{"metin":"Şimdilik çekmecede dursun, akşam kilitli yere koyarız. Zaten kat ofisinin kapısı kapalı.","puan":1,"tepki":"Kat şefi karşı çıkar: “Akşama kadar açıkta kalmasın.” Kıymetli eşyanın bekleme süresi de güvenli ortamda geçmelidir."},{"metin":"Kat arabasının üst bölümünde dursun, yanımda taşırım. Gözümün önünde olur, kimse de bakmaz zaten.","puan":0,"tepki":"Kat şefi başını iki yana sallar: “Araba koridorda duruyor.” Herkesin geçtiği yerdeki arabada kalan eşya kaybolabilir; değerli eşya güvenli bölümde saklanır."},{"metin":"Değerli olduğu için kilitli dolapta saklayalım. Sıradan eşyaların rafında durmasın.","ingilizce":"As it is valuable, let us keep it in the locked cabinet rather than on the shelf for ordinary items.","puan":2,"tepki":"Kat şefi dolabı açar: “Evet, değerine göre saklıyoruz.” Kıymetli eşya zarar görmesin ve karışmasın diye güvenli bir ortamda tutulur."}]},{"konuk":"Form iki nüsha. Nüshalar nereye gidecek?","ingilizce":"The form has two copies. Where do they go?","secenekler":[{"metin":"Nüsha gerekmez, saat zaten dolapta. Kayıt tutmak için ayrıca kâğıt harcamayalım.","puan":0,"tepki":"Kat şefi itiraz eder: “Dolaptaki eşyanın kaydı kâğıtta durur.” Kayıt olmazsa saati kimin bulduğu ve kime verildiği sonradan kanıtlanamaz."},{"metin":"İkisi de kat ofisinde kalsın, ön büroya sözlü söyleriz. Ofisteki dosya bizim için yeter.","puan":1,"tepki":"Kat şefi uyarır: “Ön büro eline bir şey olmadan konuğa ne diyecek?” Nüshalardan biri ön büroya gitmezse konuk sorduğunda ön büro cevap veremez."},{"metin":"Bir nüsha ön büroya gider, diğeri kat ofisi dosyasında kalır. Konuk sorarsa iki bölümde de kayıt var.","ingilizce":"One copy goes to the front office and the other stays in our file, so both departments hold the record if the guest asks.","puan":2,"tepki":"Kat şefi onaylar: “Güzel, kayıt iki yerde.” Formun bir nüshası ön büroya gittiği için konuk telefonla sorduğunda iki bölüm de aynı kayda ulaşır."}]},{"konuk":"Ön büro aradı: 507’nin konuğu saatini sormuş, gelip alacakmış. Teslimde neye dikkat edeceğiz?","ingilizce":"Front office rang: the guest from 507 has asked about the watch and will come to collect it. What should we pay attention to when we hand it over?","secenekler":[{"metin":"Teslimi forma işleyelim: teslim eden ve teslim alanın bilgisi yazılsın, eşyanın izi belli olsun.","ingilizce":"Let us record the handover on the form, with details of who hands it over and who receives it, so the trail is clear.","puan":2,"tepki":"Kat şefi gülümser: “Güzel iş çıkardın, teşekkürler.” Formdaki teslim eden ve teslim alan alanları eşyanın izini tamamlar ve konuğa teslimde dayanak olur."},{"metin":"Saati hemen verelim, konuk bekliyor. Teslim bilgilerini forma konuk gittikten sonra yazarız.","puan":1,"tepki":"Kat şefi başını sallar ama memnun değildir. Teslim bilgisi sonraya bırakılırsa unutulabilir ya da yanlış yazılabilir; teslim anında forma işlemek eşyanın izini eksiksiz tutar."},{"metin":"Konuk saati tarif ederse yeter, kayda geçirmeye gerek yok; vakit kaybetmeyelim.","puan":0,"tepki":"Kat şefi sertleşir: “Sahibi olduğunu nasıl bileceğiz?” Kayıtsız teslim, eşyanın doğru kişiye gittiğini göstermez; form konuğa teslimde dayanak olmak için tutulur."}]}]},{"id":"kh1-d03","unite":2,"baslik":"Kapıdaki Kart İkinci Güne Kalınca","rol":"Kat görevlisi","karsi":"Kat şefi","sahne":"Pazartesi sabahı 10.00. 406 numaralı odanın kapı kolunda DND kartı asılı. Kat görevlisi bu odayla ilgili her kararı kat şefi Hülya Hanım’la konuşarak veriyor; konuşma salı sabahına kadar sürüyor.","kavramlar":["kh1-2-050","kh1-2-054","kh1-2-055","kh1-2-056","kh1-2-057"],"adimlar":[{"konuk":"Günaydın. 406’nın kapı kolunda DND kartı asılıymış. Bu odayı nasıl yapacaksın?","ingilizce":"Good morning. I hear there is a Do Not Disturb card on the handle of 406. What will you do about this room?","secenekler":[{"metin":"Kapıyı bir kez çalıp bakarım. Ses gelmezse pas kartıyla girerim, kart unutulmuş da olabilir, konuk uyuyordur belki.","puan":0,"tepki":"Kat şefi hemen uyarır: “DND varken kapı çalınmaz.” Konuğun isteği temizlik programının önündedir; kartlı odaya girmek mahremiyeti ihlal eder."},{"metin":"Kartı gördüm, odayı atlıyorum. Konuk istemediği için girmiyorum, başka bir şey yapmama gerek yok.","puan":1,"tepki":"Kat şefi başını sallar: “Girmemen doğru, ama...” Konuk temizliğin neden yapılmadığını bilmeyebilir; kapının altına uyarı kartı bırakılması bu belirsizliği giderir."},{"metin":"Kapıyı çalmadan geçiyorum. Kapının altından, girilemediğini bildiren DND uyarı kartını bırakacağım.","ingilizce":"I will not knock. I will slide a notification card under the door to say that we could not go in.","puan":2,"tepki":"Kat şefi onaylar: “Güzel, konuk neden temizlenmediğini bilecek.” DND asılı odaya girilmez; uyarı kartı konuğa girilememe nedenini bildirir ve gerekirse resepsiyonu aramasını söyler."}]},{"konuk":"Gün bitiyor. 406 için raporuna ne yazacaksın?","ingilizce":"The day is ending. What will you write in your report for 406?","secenekler":[{"metin":"DND yüzünden giremediğim odayı tarih ve saatiyle raporuma yazıyorum. Siz de sisteme işlersiniz.","ingilizce":"I am writing in my report that I could not enter the room because of Do Not Disturb, with the date and time, and you can enter it in the system.","puan":2,"tepki":"Kat şefi kaydı sisteme işler. Girilemeyen odanın tarih ve saatle yazılması, olası bir şikâyette girilmeme nedenini açıkça gösterir."},{"metin":"406’yı da temiz yazıyorum, rapor boş kalmasın. Konuk zaten şikâyet etmez, kimse de sormaz.","puan":0,"tepki":"Kat şefi sertleşir: “Temizlenmeyen odayı temiz göstermek yanlış bilgidir.” Yanlış rapor ön büroyu ve yönetimi yanıltır; konuk şikâyet ederse gerçeği gösteren kayıt kalmaz."},{"metin":"Rapora yazmama gerek yok, kapının altına kartı bıraktım. Konuk isterse kendisi resepsiyonu arar, böylece iş uzamaz.","puan":1,"tepki":"Kat şefi eksik bulur: “Kart konuğa gidiyor, rapor bize.” Girilemeyen DND odası akşam raporunda belirtilmezse sistemde iz kalmaz."}]},{"konuk":"Günaydın, salı sabahı. Dün 406’ya giremediğini biliyorum. Bu sabah durum ne?","ingilizce":"Good morning, it is Tuesday. I know you could not get into 406 yesterday. What is the situation this morning?","secenekler":[{"metin":"Kart hâlâ asılı. Konuk uzun uyuyordur herhalde, rahatsız etmek istemedim, bir şey demedim.","puan":1,"tepki":"Kat şefi gerginleşir: “İki gündür kimse girmedi.” İkinci günde de asılı kalan kartı bildirmemek, konuğun sağlığını kontrol etme fırsatını kaçırır."},{"metin":"Kart hâlâ asılı, girmedim. Ön büro konuğu arayıp iyi olup olmadığını sorsun diye size bildiriyorum.","ingilizce":"The card is still on the door and I have not gone in. I am telling you so that front office can ring the guest and check that everything is all right.","puan":2,"tepki":"Kat şefi ön büroyu arar: “Hemen konuğu arasınlar.” DND ertesi gün de asılıysa ön büro konuğu arar, sağlık durumunu ve bir ihtiyacı olup olmadığını sorar."},{"metin":"Bir günü geçti, kart herhalde unutulmuş. Kaldırıp odayı yapıyorum, belki konuk memnun olur.","puan":0,"tepki":"Kat şefi engeller: “Kartı sen kaldıramazsın.” Kartı kaldırmak ya da odaya girmek konuğun isteğini yok saymaktır; uzayan DND’de ön büro konuğu arar."}]},{"konuk":"Ön büro konuğu aradı ama telefona çıkmadı. Şimdi ne yapıyoruz?","ingilizce":"Front office rang the guest but there was no answer. What do we do now?","secenekler":[{"metin":"Tek başıma girmem. Siz güvenlik görevlisi ve yetkili biriyle girin; ben kapıda hazır beklerim.","ingilizce":"I will not go in on my own. You should go in with a security officer and an authorised person, and I will wait at the door, ready to help.","puan":2,"tepki":"Kat şefi güvenlik görevlisini çağırır: “Birlikte gireceğiz.” Uzayan DND’de konuğun hasta olabileceği düşünülür; odaya yetkili bir kişi ve güvenlik görevlisiyle birlikte girilir."},{"metin":"Pas anahtarımla ben hızlıca bakıp çıkayım, bir dakika sürmez. Güvenliği çağırmakla vakit kaybederiz.","puan":0,"tepki":"Kat şefi hemen engeller: “Hayır, tek başına girme.” Uzayan DND’de oda tek kişiyle değil yetkililerle birlikte açılır; tek başına girmek hem görevliyi hem konuğun mahremiyetini riske atar."},{"metin":"Siz bilirsiniz, ben kendi odalarıma devam edeyim. Yardım gerekirse telsizden beni çağırırsınız.","puan":1,"tepki":"Kat şefi “Peki” der ama durumun ciddiyeti karşılık bulmaz. Ekipten birinin yardıma hazır beklemesi süreci hızlandırır."}]},{"konuk":"Odadayız. Konuk yatakta, çok halsiz görünüyor ama konuşabiliyor. Ne yapılmalı?","ingilizce":"We are in the room. The guest is in bed and looks very weak, but can speak. What should be done?","secenekler":[{"metin":"Hemen doktor çağıralım. Hastaneye gitmesi gerekirse 112’yi arayıp ambulans isteyelim.","ingilizce":"Let us call a doctor straight away. If the guest needs to go to hospital, we will ring 112 for an ambulance.","puan":2,"tepki":"Kat şefi doktoru arar: “Yoldaymış, teşekkürler.” Konuk hastaysa doktor çağrılır; hastaneye gitmesi gerekiyorsa 112’den ambulans istenir."},{"metin":"Konuğu fazla rahatsız etmeyelim, belki sadece yorgundur. Odayı toplayıp çıkalım, akşam tekrar bakarız.","puan":0,"tepki":"Kat şefi şaşkınlıkla bakar: “Hasta birini bırakamayız.” Halsiz bir konuk yalnız bırakılmaz; doktor çağrılır ve gerekirse ambulans istenir."},{"metin":"Ben konuğun yanında beklerim, doktor gerekip gerekmediğine siz karar verirsiniz.","puan":1,"tepki":"Kat şefi başını sallar: “Yanında kal.” Yanında beklemek iyidir, ama doktorun ve gerekirse ambulansın çağrılması geciktirilmez."}]}]},{"id":"kh1-d04","unite":2,"baslik":"Kartı Odada Unutan Konuk","rol":"Kat görevlisi","sahne":"Saat 14.10, üçüncü kat koridoru. Kat görevlisi arabasıyla yan odayı hazırlarken telaşlı bir hanım konuk yanına geliyor: oda kartını içeride unutmuş, kapı kapanmış ve toplantısına geç kalıyor.","kavramlar":["kh1-2-017","kh1-2-037","kh1-2-038","kh1-2-248","kh1-2-254"],"adimlar":[{"konuk":"Affedersiniz, oda kartımı içeride unuttum. Pas anahtarınızla açabilirsiniz, değil mi? Toplantıya geç kalacağım.","ingilizce":"Excuse me, I have left my key card inside the room. You can open the door with your pass key, can’t you? I am going to be late for my meeting.","secenekler":[{"metin":"Tamam, madem acil, çabuk açıyorum. Yalnız kimseye söylemeyin, ben de işimden olmayayım.","puan":0,"tepki":"Konuk teşekkür eder, oysa oda yetkisiz biçimde açılmıştır. Pas anahtarı imzayla alınan, kayıtlı bir güvenlik aracıdır; konuğa oda açmak için kullanılırsa güvenlik zedelenir."},{"metin":"Geçmiş olsun efendim. Pas anahtarı konuklar için kullanılmıyor; resepsiyon size hemen yardımcı olur.","ingilizce":"I am sorry to hear that, madam. We cannot use the pass key for guests, but reception can help you straight away.","puan":2,"tepki":"Konuk başını sallar: “Anladım, hemen gidiyorum.” Pas anahtarı konuğa oda açmak için kullanılmaz; görevli kuralı söylerken konuğu çözüme de yönlendirir."},{"metin":"Açamam efendim, pas anahtarı yasak. Bu konuda yapabileceğim bir şey yok, kusura bakmayın.","puan":1,"tepki":"Konuk bozulur: “Peki ne yapacağım?” Kural doğru söylendi ama konuğa çözüm yolu gösterilmedi; kuralla birlikte nereye gideceği de söylenmelidir."}]},{"konuk":"Ama on beş dakikadır buradayım ve bu odada kalıyorum! Lütfen, yalnızca bu seferlik.","ingilizce":"But I have been standing here for fifteen minutes, and I am staying in this room! Please, just this once.","secenekler":[{"metin":"Sizi anlıyorum. Güvenlik gereği açamıyorum ama kat şefimize ve resepsiyona şimdi haber veriyorum.","ingilizce":"I understand. For security reasons I cannot open it, but I am informing our floor supervisor and reception right now.","puan":2,"tepki":"Konuk biraz yatışır: “Peki, teşekkürler.” Kararı kendi vermek yerine kat şefi gibi yetkili kişiye haber vermek ve konuğun acelesini anlamak gerginliği azaltır."},{"metin":"Kuralları ben koymadım efendim, lütfen bana kızmayın. Üzgünüm ama yapabileceğim bir şey yok.","puan":1,"tepki":"Konuk daha da gerilir: “Size kızmıyorum, çözüm istiyorum.” Sorumluluğu başkasına atan bir cümle çözüm sunmaz."},{"metin":"Başka biri açar, ben işimin başındayım. Arabamla bu katta daha çok odam var, beni daha fazla oyalamayın.","puan":0,"tepki":"Konuk sesini yükseltir. İstek yerine getirilemese bile konuğa karşı soğukkanlı ve kibar kalınır; kabalık sorunu büyütür."}]},{"konuk":"Peki neden bu kadar katısınız? Sizin anahtarınız da kapıyı açıyor sonuçta.","ingilizce":"Why are you so strict? Your key opens the door too, after all.","secenekler":[{"metin":"İşletmemizin kuralı böyle, gerekçesini ayrıca anlatmam gerekmiyor. Sorularınız için resepsiyona gidebilirsiniz.","puan":1,"tepki":"Konuk omuz silker. Cevap doğru ama kapalı; gerekçeyi kısaca anlatmak konuğun kuralı kabullenmesini kolaylaştırır."},{"metin":"Pas anahtarı birçok kapıyı açtığı için imzayla verilir ve kayıtlıdır; konuklar için kullanılmaz.","ingilizce":"A pass key opens many doors, so it is signed for and recorded; it is not used for guests.","puan":2,"tepki":"Konuk başını sallar: “Mantıklı, anladım.” Gerekçe kısaca anlatılınca kural keyfî görünmez; pas anahtarının imzayla alınıp kayıtlı tutulması güvenliğin parçasıdır."},{"metin":"Bunu ben bilmem, kural bana öyle söylendi. İsterseniz gidip yönetime sorun, orada anlatırlar.","puan":0,"tepki":"Konuk hayal kırıklığına uğrar: “Kimse bilmiyor mu?” Görevli kuralın nedenini bilmeli ve konuğa kısaca anlatabilmelidir."}]},{"konuk":"Peki, toplantıya çok az kaldı. Bana nasıl yardımcı olabilirsiniz?","ingilizce":"All right, there is very little time before my meeting. How can you help me?","secenekler":[{"metin":"Asansörle lobiye inin, resepsiyon orada. Sıraya girip durumu anlatırsanız yardımcı olurlar.","puan":1,"tepki":"Konuk yönü anlar ama bekleyeceğini düşünür. Resepsiyona önceden haber vermek konuğun zamanını kazandırır ve ilgiyi gösterir."},{"metin":"Resepsiyonu arayıp geldiğinizi haber vereyim, sizi bekletmesinler. Asansörle lobiye inebilirsiniz.","ingilizce":"I will ring reception to let them know you are on your way, so that they do not keep you waiting. You can take the lift down to the lobby.","puan":2,"tepki":"Konuk rahatlar: “Çok teşekkür ederim.” Kat hizmetleri ile ön büro arasındaki haberleşme, konuğun beklemeden ilgilenilmesini sağlar."},{"metin":"Bana düşen bir şey yok, ben yetkili değilim. Resepsiyonu kendiniz bulun, vaktim yok.","puan":0,"tepki":"Konuk sinirle uzaklaşır. Yetkisi olmayan görevli bile konuğu çözüme ulaştırmak için elinden geleni yapar; “gidin” demek hizmet anlayışına aykırıdır."}]},{"konuk":"Teşekkürler, bir daha unutmam. İyi çalışmalar.","ingilizce":"Thank you, I won’t forget it again. Have a good day.","secenekler":[{"metin":"Tamam, iyi günler. Ben işime döneyim, başka odalar bekliyor.","puan":1,"tepki":"Konuk başını sallayıp hızla uzaklaşır. Sorun çözülmüş olsa da soğuk bir veda kurulan güveni zayıflatır."},{"metin":"Bir daha unutmayın, herkes sizin için koşturmak zorunda değil.","puan":0,"tepki":"Konuğun yüzü asılır. Konuğa ders vermek profesyonelliğe aykırıdır; yardım edildikten sonra söylenen bu cümle özenin değerini düşürür."},{"metin":"Rica ederim efendim. İyi toplantılar dilerim, iyi günler.","ingilizce":"You are welcome, madam. I wish you a successful meeting and a good day.","puan":2,"tepki":"Konuk gülümseyerek ayrılır. Kibar bir veda gergin başlayan görüşmeyi olumlu kapatır; konuk otele güvenle döner."}]}]},{"id":"kh1-d05","unite":3,"baslik":"Bebek Karyolası ve Ek Yatak","rol":"Kat görevlisi","sahne":"Akşam 19.00. Dört aylık bebeği ve altı yaşındaki oğluyla gelen aile resepsiyondan ilave yatak istedi; talep kat ofisine iletildi. Kat görevlisi bebek karyolası ve portatif yatakla 312 numaralı odanın kapısına geliyor, kapıyı anne açıyor.","kavramlar":["kh1-3-072","kh1-3-073","kh1-3-077","kh1-3-079","kh1-3-080"],"adimlar":[{"konuk":"İyi akşamlar, resepsiyondan bebek için yatak istemiştik. Siz mi getirdiniz?","ingilizce":"Good evening, we asked reception for a bed for the baby. Did you bring it?","secenekler":[{"metin":"Karyolayı koridorda bırakıyorum, siz kurarsınız. Elimde başka odaların işleri var, bekleyenler çok.","puan":0,"tepki":"Anne şaşkınlıkla bebeğini kucaklar. Talep gelince yatağı hazırlayıp odaya taşımak kat görevlisinin işidir; kurulumu konuğa bırakmak hizmeti eksik bırakır."},{"metin":"Evet, karyola burada, kurulumunu hemen yaparım. Odanın neresine kurmamı istersiniz, siz söyleyin yeter.","puan":1,"tepki":"Anne yeri gösterir ama bebek takımını göremez. Karyolayla birlikte bebeğe uygun küçük ölçülü takım da getirilmelidir; yetişkin çarşafı karyolaya uymaz."},{"metin":"Evet efendim, karyolayı ve küçük ölçülü bebek takımını getirdim. Yatağınızın yanına kurayım mı?","ingilizce":"Yes, madam, I have brought the cot and a small baby bedding set. Shall I set it up next to your bed?","puan":2,"tepki":"Anne rahatlar: “Tam istediğimiz gibi.” Talep gelince karyola ve bebeğe uygun küçük ölçülü takım birlikte getirilir; yerleşimi konuğa sormak ona kendini önemli hissettirir."}]},{"konuk":"Bebeğin yatağı ıslanırsa ne olacak? Yatağın temiz olduğundan emin olmak istiyorum.","ingilizce":"What happens if the baby wets the cot? I want to be sure that the bed is clean.","secenekler":[{"metin":"Önce sıvı geçirmez alezi, sonra alt çarşafı seriyorum. Islanırsa alez yatağı korur, çarşaf kolayca değişir.","ingilizce":"I put a waterproof protector down first, then the bottom sheet. If it gets wet, the protector shields the mattress and the sheet is easy to change.","puan":2,"tepki":"Anne gülümser: “Sağ olun, içim rahatladı.” Bebek yatağı ıslanmaya yatkındır; sıvı geçirmez alez yatağı korur ve temizliği kolaylaştırır."},{"metin":"Merak etmeyin, her şey temiz ve kontrol edildi. Islanırsa arayın, hemen değiştiririm.","puan":1,"tepki":"Anne kısmen rahatlar ama yatağın nasıl korunduğunu öğrenemez. Güven vermenin yolu hazırlığı kısaca anlatmaktır; alez ve temiz takım burada önemlidir."},{"metin":"Elimdeki yetişkin çarşafını serip katlayarak sıkıştırırım, karyolaya uydurulur nasılsa; olur biter.","puan":0,"tepki":"Anne endişelenir: “Karyolaya uyar mı?” Yetişkin çarşafı karyolaya uymaz; bebek yatağında küçük ölçülü takım ve sıvı geçirmez alez kullanılır."}]},{"konuk":"Oğlumuz için portatif yatağı da getirmişsiniz, teşekkürler. Ama odamız dar, nereye kurulacak?","ingilizce":"Thank you for bringing the folding bed for our son. But our room is small; where will it go?","secenekler":[{"metin":"Yatağı kapının hemen önüne kurayım, taşıması kolay olur. Eşyalara dokunmadan da sığar, böylece işim kısalır.","puan":0,"tepki":"Anne endişelenir: “Kapıdan nasıl çıkacağız?” Portatif yatak geçişi kapatmayacak yere kurulur; gerekirse eşyalar kenara çekilerek yer açılır."},{"metin":"Nereye isterseniz oraya kurarım, siz bir köşe gösterin. Eşyaları ben sonra yerleştiririm.","puan":1,"tepki":"Anne bir köşeyi gösterir ama odanın darlığı hesaba katılmamıştır. Yatağın yerini önceden düşünüp eşyaları kenara alarak geçiş alanı açmak görevlinin işidir."},{"metin":"Önce komodinle sandalyeyi kenara alıp yer açayım, sonra kurayım. Geçiş alanı açık kalacak.","ingilizce":"First I will move the bedside table and chair aside to make room, then set the bed up. There will still be a clear way through.","puan":2,"tepki":"Anne memnun olur: “Çok düşünceli.” Portatif yatağın yeri baştan belirlenir ve eşyalar kenara alınarak çevresinde geçiş alanı bırakılır; böylece oda daralmaz."}]},{"konuk":"Portatif yatak biraz sade görünüyor. Oğlum üzerinde rahat uyuyabilir mi?","ingilizce":"The folding bed looks rather plain. Will my son sleep comfortably on it?","secenekler":[{"metin":"Biraz sade görünüyor ama idare eder, çocuklar her yerde uyur. Gece sorun olmaz diye düşünüyorum, üzülmeyin.","puan":1,"tepki":"Anne pek ikna olmaz. “İdare eder” sözü özen göstermez; ilave yatak da sabit yataklarla aynı özenle hazırlanmalıdır."},{"metin":"Diğer yataklarla aynı sırayla hazırlıyorum: koruyucu, çarşaf, battaniye ya da pike, yastık, örtü.","ingilizce":"I make it up in the same order as the other beds: protector, sheets, blanket or coverlet, pillow and bedspread.","puan":2,"tepki":"Anne rahatlar: “Böyle olunca sorun yok.” Portatif yatak da sabit yatak kadar temiz ve düzenli hazırlanır; koruyucu, çarşaflar ve örtü sırayla yerleştirilir."},{"metin":"Elimde çarşaf az kaldı; yatağa bir battaniye serip geçiştiririm. Bir gecelik, çocuk fark etmez.","puan":0,"tepki":"Anne endişelenir: “Hijyenik mi bu?” Portatif yatak da koruyucu, çarşaf, battaniye ya da pike, yastık ve örtüyle sırayla hazırlanır; kestirme çözüm yatağı hijyenik ve düzenli kılmaz."}]},{"konuk":"Her şeyi hazırladınız, çok teşekkür ederiz. Gece bir şeye ihtiyacımız olursa kimi arayalım?","ingilizce":"You have prepared everything, thank you so much. Who should we call if we need anything during the night?","secenekler":[{"metin":"Resepsiyonu aramanız yeterli efendim, talebinizi bize hemen iletirler. İyi geceler dilerim.","ingilizce":"Just ring reception, madam, and they will pass your request on to us straight away. Good night.","puan":2,"tepki":"Anne gülümser: “Çok teşekkürler, iyi akşamlar.” İlave yatak gibi talepler resepsiyon aracılığıyla kat ofisine iletilir; konuk kime ulaşacağını bildiğinde kendini güvende hisseder."},{"metin":"Resepsiyonu arayabilirsiniz, onlar nasıl yapılacağını bilir. İyi geceler dilerim.","puan":1,"tepki":"Anne “Teşekkürler” der ama isteğin kat ofisine nasıl ulaşacağını anlamaz. Talepler resepsiyon aracılığıyla kat ofisine iletilir; bunu söylemek konuğa yol gösterir, “bilir” demek göstermez."},{"metin":"Bir şey olursa kendiniz çözersiniz, gece kimse bakmaz. Zaten çok da bir şey olmaz.","puan":0,"tepki":"Anne endişelenir. Konuğa yardım edilmeyeceğini söylemek güveni yıkar; talepler resepsiyon aracılığıyla kat ofisine iletilir."}]}]},{"id":"kh1-d06","unite":3,"baslik":"Akşam Servisi: Konuk Odadayken","rol":"Kat görevlisi","sahne":"Saat 21.00. 305 numaralı odada kalan erkek konuk akşam yemeğinden döndü ve odasında dinleniyor. Kat görevlisi, bu odanın yatak açma servisi (turn down) için kapıya geliyor.","kavramlar":["kh1-3-083","kh1-3-084","kh1-3-088","kh1-3-090","kh1-3-206"],"adimlar":[{"konuk":"Kim o?","ingilizce":"Who is it?","secenekler":[{"metin":"(Kapıyı üç kez nazikçe çalar.) Housekeeping. Yatak açma servisi için girebilir miyim efendim?","ingilizce":"Housekeeping. May I come in for the turn down service, sir?","puan":2,"tepki":"Konuk kapıya yaklaşır: “Buyurun, girin.” Konuk odadayken kapı çalınır ve girmeden önce izin istenir; bu, konuğun mahremiyetine saygıdır."},{"metin":"(Cevap beklemeden pas kartını kullanır.) Yatak açma servisi, hemen yapıp çıkıyorum, sizi bekletmem.","puan":0,"tepki":"Konuk irkilir: “Ben buradayım!” Cevap beklenmeden girmek konuğun mahremiyetini ihlal eder; konuk odadayken izin alınmadan odaya girilmez."},{"metin":"(Kapıyı bir kez vurur.) Housekeeping, iyi akşamlar. Bir dakikalığına odaya bakmam gerekiyor.","puan":1,"tepki":"Konuk kapının ardından “Ne için?” diye sorar. Gelenin kim olduğu anlaşıldı ama hizmetin adı söylenmedi ve izin istenmedi; girmeden önce izin alınmalıdır."}]},{"konuk":"Peki, devam edin. Ben şu koltukta kitap okuyacağım, rahatsız olmayın. Ne kadar sürer?","ingilizce":"All right, go ahead. I will be reading in this armchair, so please don’t mind me. How long will it take?","secenekler":[{"metin":"Çok sürmez efendim, siz okumaya devam edin. Ben bir an önce işimi bitirip çıkarım.","puan":1,"tepki":"Konuk “Peki” der. Süre söylendi ama ne yapılacağı anlatılmadı; hizmetin ne olduğunu ve sessiz çalışılacağını kısaca belirtmek konuğu rahatlatır."},{"metin":"Siz okuyun, ben arkadaşımla telsizden konuşarak çalışırım; böylece iş daha çabuk biter.","puan":0,"tepki":"Konuk kitabından başını kaldırır, rahatsız olur. Konuk odadayken hızlı ve sessiz çalışılır; konuşma sesi dinlenmeyi bozar."},{"metin":"Birkaç dakika efendim. Hızlı ve sessiz çalışıp yatağınızı açacağım, odayı gece için hazırlayacağım.","ingilizce":"Just a few minutes, sir. I will work quickly and quietly, turn down your bed and get the room ready for the night.","puan":2,"tepki":"Konuk kitabına döner: “Rahat çalışın.” İzinden sonra hızlı ve sessiz çalışmak, konuğu dinlenirken rahatsız etmez."}]},{"konuk":"Yarın sabah erken bir toplantım var, kahvaltıya yetişemem. Bunun için bir şey yapabilir miyim?","ingilizce":"I have an early meeting tomorrow and won’t make it to breakfast. Is there anything I can do about that?","secenekler":[{"metin":"Yatağın üzerine kahvaltı istek formunu bırakıyorum; yarınki isteğinizi şimdiden işaretleyebilirsiniz.","ingilizce":"I am leaving a breakfast order form on the bed. You can mark your request for tomorrow morning now.","puan":2,"tepki":"Konuk formu eline alır: “Harika, hemen doldururum.” Kahvaltı istek formu ertesi sabahın isteğini önceden bildirmeyi sağlar; sabah servisi de kolaylaşır."},{"metin":"Bu konuda resepsiyonu aramanız gerekir, bende bir bilgi yok. Onlar size kahvaltı konusunda yardımcı olur.","puan":1,"tepki":"Konuk “Tamam” der ama formdan haberi olmaz. Turn down sırasında yatağın üzerine kahvaltı istek formu bırakıldığını bilmek görevlinin işidir."},{"metin":"Kahvaltıyı kaçırırsanız yapacak bir şey yok; öğle yemeğine kalın, kahvaltı saatleri belli.","puan":0,"tepki":"Konuk bozulur. Kahvaltı istek formu tam da böyle durumlar için vardır; çözümü bilmeyip konuğu geri çevirmek hizmeti eksik bırakır."}]},{"konuk":"Bir şey daha: perdeleri çekmeyin lütfen, ışığı da kısmayın. Yatmadan önce kendim hallederim.","ingilizce":"One more thing: please don’t draw the curtains or dim the lights. I will do it myself before I go to bed.","secenekler":[{"metin":"Perdeleri çekmek bu hizmetin kuralı. Ben yine de çekeyim, ışığı da kısayım; siz sonra açarsınız.","puan":0,"tepki":"Konuk başını iki yana sallar: “Ben istemiyorum.” Turn down konuğun isteği doğrultusunda yapılır; konuk bir adımı istemiyorsa o adım atlanır."},{"metin":"Elbette efendim, perdeler ve ışık sizde. Pencere ile balkon kapısı da sizde kalsın, size hiç zahmet olmasın.","puan":1,"tepki":"Konuk başını sallar ama pencerenin açık kalıp kalmadığını düşünür. Perde ve ışık konuğun tercihidir; pencere ve balkon kapısını kontrol etmek ise konuğun gece güvenliği için görevlinin işidir."},{"metin":"Elbette efendim, perdeler ve ışık sizde. Pencere ile balkon kapısını kontrol edip kapalı bırakıyorum.","ingilizce":"Of course, sir. I will leave the curtains and lights to you, and I will check that the windows and the balcony door are closed.","puan":2,"tepki":"Konuk teşekkür eder: “Tam böyle olsun.” Turn down konuğun isteği doğrultusunda yapılır; pencere ve balkon kapısının kapalı olması ise konuğun gece güvenliğini sağlar."}]},{"konuk":"Teşekkür ederim. Yastığa bırakılan o küçük not da çok nazikmiş.","ingilizce":"Thank you. That little note left on the pillow is very kind too.","secenekler":[{"metin":"Rica ederim efendim, iyi geceler. Ben artık çıkıyorum, başka odalar da bekliyor.","puan":1,"tepki":"Konuk başını sallar. Veda kibar ama kısa; bir isteği olursa nereye ulaşacağını da söylemek hizmeti tamamlardı."},{"metin":"Notu herkese bırakıyoruz, özel bir şey değil; otelin standardı. İyi geceler.","puan":0,"tepki":"Konuk soğur. Küçük bir nezaket ifadesini küçümsemek hizmetin sıcaklığını bozar; not, konuğa iyi dilek iletmek içindir."},{"metin":"Rica ederim efendim. İyi geceler dilerim; bir isteğiniz olursa resepsiyonu arayabilirsiniz.","ingilizce":"You are welcome, sir. I wish you a good night, and please ring reception if you need anything.","puan":2,"tepki":"Konuk gülümser: “İyi geceler.” Turn down, iyi geceler notu ve nazik bir vedayla tamamlanır; konuk özenle karşılandığını hisseder."}]}]},{"id":"kh1-d07","unite":4,"baslik":"Gözüne Ürün Sıçrayınca","rol":"Kat görevlisi","karsi":"Stajyer","sahne":"Saat 09.40, dördüncü kat. Kat görevlisi, banyo temizliği yapan stajyer Efe’ye eşlik ediyor. Efe işe birkaç gün önce başladı ve işleri hızlandırmak istiyor; son banyonun penceresi yok.","kavramlar":["kh1-4-032","kh1-4-033","kh1-4-034","kh1-4-036","kh1-4-037"],"adimlar":[{"konuk":"WC temizleyiciyle kireç çözücüyü aynı kovada karıştırıp tek seferde sürsem daha çabuk bitirirdim. Olur mu?","ingilizce":"If I mixed the toilet cleaner and the descaler in one bucket and applied them in one go, I would finish faster. Is that all right?","secenekler":[{"metin":"Karıştırmayın bence, hızlı da olsa riskli. Ürünleri tek tek sürmek biraz uzun sürer ama olsun.","puan":1,"tepki":"Efe omuz silker: “Neden riskli ki?” Kural doğru söylendi ama nedeni anlatılmadı; gerekçeyi bilen stajyer kuralı daha kolay hatırlar."},{"metin":"Hayır, ürünleri karıştırmıyoruz; karışım zehirli gaz çıkarabilir. Her ürün kendi talimatına göre, ayrı kullanılır.","ingilizce":"No, we never mix products; the mixture can give off toxic gas. Each product is used on its own, following its instructions.","puan":2,"tepki":"Efe elini kovadan çeker: “İyi ki sordum.” Farklı temizlik maddeleri karıştırılınca beklenmedik tepkime olur ve zehirli gaz çıkabilir; her ürün ayrı ve kendi talimatına göre kullanılır."},{"metin":"Olur, yalnız banyonun penceresini açın, kapıyı da aralık tutun. Koku gider, sorun kalmaz.","puan":0,"tepki":"Efe duraksar: “Emin misiniz?” Havalandırma karışımın zehirli gaz çıkarma riskini ortadan kaldırmaz; farklı ürünler hiçbir koşulda karıştırılmaz."}]},{"konuk":"Peki. Şimdi son banyoda kireç çözücü kullanacağım ama penceresi yok. Maskeyi sonra takarım, önce şu işi bitireyim.","ingilizce":"All right. Now I will use the descaler in the last bathroom, but it has no window. I will put the mask on afterwards; let me finish this first.","secenekler":[{"metin":"Önce eldiven ve maskeyi takın, sonra kapıyı açıp banyoyu havalandırın. Asidik ürün kapalı ortamda maskesiz kullanılmaz.","ingilizce":"Put your gloves and mask on first, then open the door and ventilate the bathroom. An acidic product must never be used in a closed space without a mask.","puan":2,"tepki":"Efe maskesini takar: “Haklısınız, tamam.” Koruyucu donanım işin başında takılır, ortasında değil; kireç çözücü gibi asidik ürünlerin buharı kapalı ortamda solunum yollarını tahriş edebilir."},{"metin":"Maskenizi takın yeter. Pencere de yok zaten, havalandırmayı ürünü sürdükten sonra düşünürüz.","puan":1,"tepki":"Efe maskeyi takıp işe başlar. Maske doğru, ama asidik ürünle çalışırken banyonun havalandığından işe başlamadan önce emin olunur."},{"metin":"Maske gereksiz. İki dakikalık iş, hızlıca bitirirsiniz; maske takmak işi uzatır, vakit kaybedersiniz.","puan":0,"tepki":"Efe maskesiz başlar ve birkaç dakika sonra öksürmeye başlar. Asidik ürünler kapalı ortamlarda maskesiz kullanılmaz; kısa süren işte de koruyucu takılır."}]},{"konuk":"Aynayı silmek için temizleyiciyi sıktım ama ürün gözüme sıçradı! Gözüm yanıyor!","ingilizce":"I sprayed the cleaner to wipe the mirror, but it splashed into my eye! It is burning!","secenekler":[{"metin":"Lavaboya gidin, gözünüzü kısa süre yıkayın; geçmezse doktora gideriz.","puan":1,"tepki":"Efe gözünü yıkar ama gözü hâlâ yanar. Yıkama kısa kesilmeden bol ve akan suyla yapılır; doktora gitmek de yıkamanın ardından, şikâyet geçse bile atlanmaz."},{"metin":"Gözünüzü kuru bezle ovuşturun, geçer. Ürün zaten az sıçramıştır, abartmayın.","puan":0,"tepki":"Efe gözünü ovunca daha çok yanar. Sıçrayan ürün bezle ovularak değil, bol ve akan suyla yıkanarak uzaklaştırılır."},{"metin":"Hemen lavaboya gelin. Gözünüzü bol ve akan suyla yıkayın, ben yanınızdayım.","ingilizce":"Come to the basin right now. Rinse your eye with plenty of running water; I am right beside you.","puan":2,"tepki":"Efe lavaboya eğilir ve gözünü yıkar. Göze sıçrayan ürün önce bol ve akan suyla yıkanır; doktora başvurmak bundan sonra gelir."}]},{"konuk":"Biraz geçti, sanırım iyiyim. Şefe söylemeyelim, kızar. Hadi işe dönelim.","ingilizce":"It has eased a little, and I think I am fine. Let us not tell the supervisor, as they will be cross. Come on, let us get back to work.","secenekler":[{"metin":"Doktora gidelim ama şefimize söylemeyelim; zaten iyi görünüyorsunuz, bir şey olmamış gibi davranalım.","puan":1,"tepki":"Efe rahatlar ama kaza kayıtsız kalır. Doktora gitmek doğru; ancak olay amire de bildirilir, çünkü bildirilmeyen kaza ekibin önlem almasını engeller."},{"metin":"Hayır, doktora gitmeniz gerek; yıkamak yalnızca ilk adımdı. Olayı kat şefimize de bildireceğim.","ingilizce":"No, you need to see a doctor; rinsing was only the first step. I will also tell our floor supervisor.","puan":2,"tepki":"Efe iç çekip başını sallar: “Tamam, gidelim.” Önce yıkama yapılır, sonra doktora gidilir ve olay amire bildirilir; saklanan kaza ekibi korumasız bırakır."},{"metin":"Haklısınız, kimseye söylemeyelim. Yıkadık, geçti; kimse bilmesin, işe devam edelim.","puan":0,"tepki":"Efe rahatlar ama sorun çözülmez. Gizlenen bir kaza yeniden yaşanabilir; kimyasal sıçraması amire bildirilir ve gerekirse doktora başvurulur."}]},{"konuk":"Teşekkür ederim. Bundan sonra neye dikkat etmeliyim ki bir daha olmasın?","ingilizce":"Thank you. What should I watch for from now on so that this does not happen again?","secenekler":[{"metin":"Etiketi ve talimatı okuyun, eldiven ile maskeyi baştan takın; ürünü yüzeye değil süngere uygulayın.","ingilizce":"Read the label and instructions, wear your gloves and mask from the start, and apply the product to a sponge, not straight onto the surface.","puan":2,"tepki":"Efe not defterine yazar: “Bunları unutmam.” Talimata uymak, koruyucuyu baştan takmak ve ürünü doğrudan yüzeye dökmeyip süngere ya da beze uygulamak kazaları azaltır."},{"metin":"Bundan sonra aynalara dokunmayın, siz yalnızca zeminle uğraşın; kimyasalı ben kullanırım, kazaya yer kalmaz.","puan":0,"tepki":"Efe moralini bozar. Çalışanı işten uzaklaştırmak çözüm değildir; kimyasalın doğru kullanım kuralları öğretilir."},{"metin":"Biraz daha dikkatli olun, acele etmeyin. Gerisini zamanla öğrenirsiniz, merak etmeyin.","puan":1,"tepki":"Efe “Tamam” der ama neye dikkat edeceğini bilemez. Somut kurallar (etiket, koruyucu, doğru uygulama) verilmezse genel bir dikkat uyarısı yetmez."}]}]},{"id":"kh1-d08","unite":4,"baslik":"Banyoda Eksik Set","rol":"Kat görevlisi","sahne":"Akşam 20.15. 410 numaralı odada kalan iki kişi, banyodaki buklet malzemelerinin eksik olduğunu kat ofisine bildirdi. Kat görevlisi kat arabasından aldığı malzemelerle odanın kapısına geliyor; kapıyı bir erkek konuk açıyor.","kavramlar":["kh1-4-181","kh1-4-192","kh1-4-202","kh1-4-212","kh1-4-227"],"adimlar":[{"konuk":"Ah, geldiniz. İki kişiyiz ama banyoda yalnızca bir diş seti ve bir şampuan vardı.","ingilizce":"Ah, you’re here. There are two of us, but there was only one dental kit and one bottle of shampoo in the bathroom.","secenekler":[{"metin":"Rapora göre odada tek kişi görünüyordu efendim, o yüzden tek set konmuş. Yine de tamamlayayım.","puan":1,"tepki":"Konuk bozulur: “Bu benim hatam mı?” Kişi sayısı kayıtta farklı olsa bile konuğa mazeret sunulmaz; eksik özürle tamamlanır."},{"metin":"İyi baktınız mı? Banyoda eksik malzeme olmaz, belki yerini unuttunuz ya da bir yere koydunuz, bir daha bakın.","puan":0,"tepki":"Konuk gücenir: “İki kez baktım.” Eksik bildiren konuğun sözü sorgulanmaz; kontrol görevlinin işidir ve eksik hemen tamamlanır."},{"metin":"Özür dilerim efendim, eksiği hemen tamamlıyorum. İki kişi kaldığınız için ikişer set bırakıyorum.","ingilizce":"I am sorry, sir. I will put it right straight away. As two people are staying, I will leave two of each.","puan":2,"tepki":"Konuk rahatlar: “Çok teşekkürler.” Banyodaki buklet malzemesi odada kalan kişi sayısı kadar bulunur; eksik bildirilince bahane aranmadan tamamlanır."}]},{"konuk":"Lavabonun yanında iki kart var, biri havlu değişim kartı, öbürü çevre kartı galiba. Ne işe yarıyorlar?","ingilizce":"There are two cards by the basin, a towel change card and an environment card, I think. What are they for?","secenekler":[{"metin":"Üzerlerinde yazıyor efendim, okursanız anlarsınız. Sorunuz olursa tekrar sorun.","puan":1,"tepki":"Konuk kartlara tekrar bakıp omuz silker. Kartlar konuğun işini kolaylaştırmak için konur; görevli sorulunca kısaca açıklayabilmelidir."},{"metin":"Çevre kartı sizi çevre uygulamalarımıza davet eder; havlu değişim kartıyla havlu tercihinizi bildirirsiniz.","ingilizce":"The environment card invites you to join us in our environmental practices, and the towel change card lets you tell us your towel preference.","puan":2,"tepki":"Konuk kartları okur: “Anladım, güzel bir uygulama.” Havlu değişim kartı konuğun tercihini sorar; çevre kartı ise otelin çevre duyarlılığını konuğa duyurur."},{"metin":"Onlar odayı güzel göstermek için konmuş birer süs, dikkate almanıza gerek yok.","puan":0,"tepki":"Konuk şaşırır. Kartlar konuğun tercihini bildirmesi içindir; “süs” demek yanlış bilgidir ve konuğun isteklerinin yerine gelmesini engeller."}]},{"konuk":"Havlularımın her gün değiştirilmesini istemiyorum. Kartı işaretlersem yeterli mi?","ingilizce":"I don’t want my towels changed every day. Is it enough if I mark the card?","secenekler":[{"metin":"Evet efendim, kartla bildirmeniz yeterli. Siz istemedikçe havlularınız yerinde kalır.","ingilizce":"Yes, sir. Marking the card is enough, and your towels will stay where they are unless you ask for a change.","puan":2,"tepki":"Konuk kartı işaretler: “Güzel, teşekkürler.” Kartla bildirilen tercihe göre, konuk istemediği sürece havlu değiştirilmeden yerinde bırakılır."},{"metin":"Havlular her gün değişir, kart bir şey fark ettirmez. Biz zaten standart olarak hepsini yeniliyoruz.","puan":0,"tepki":"Konuk şaşırır. Çevre kartı uygulamasında konuğun tercihi esas alınır; tercihi yok saymak hem konuğu hem işletmenin çevre duyarlılığını hiçe sayar."},{"metin":"İsterseniz bana söyleyin, ben kendi notlarıma yazarım. Kartı işaretlemenize gerek kalmaz.","puan":1,"tepki":"Konuk “Peki” der ama başka bir görevli gelirse isteğin bilinmeyeceğinden endişelenir. Tercih kartla bildirildiğinde herkes aynı bilgiye ulaşır."}]},{"konuk":"Şampuanı lavabonun yanında gördüm. Duşa girerken yanımda olsa daha iyi olurdu.","ingilizce":"I saw the shampoo by the basin. It would have been better to have it with me in the shower.","secenekler":[{"metin":"Otelin yerleştirme düzeni böyle, değiştiremem. Ben yalnızca bana gösterilen yere koyuyorum.","puan":0,"tepki":"Konuk tartışmak istemez ama bozulur. Yerleştirme kuralları konuğun kolay ulaşmasını amaçlar; makul bir isteğe kuralı gerekçe göstermek hizmeti soğutur."},{"metin":"Haklısınız. Duş jeli ve şampuanı duş alanına alıyorum, diş setini lavabonun yanında bırakıyorum.","ingilizce":"You are right. I will move the shower gel and shampoo to the shower area and leave the dental kit by the basin.","puan":2,"tepki":"Konuk memnun olur: “İşte bu.” Malzemeler kullanım yerine ve sırasına göre dizilir; duş jeli ve şampuan duş alanında, diş seti lavabonun yanında durur."},{"metin":"Hepsi lavabonun yanında kalsın, duşa girerken oradan alırsınız. Zaten çok uzak değil, bir adımlık yol.","puan":1,"tepki":"Konuk isteksizce onaylar. Malzemeler konuğun ihtiyaç duyduğu yerde bulunmalıdır; kullanım sırasına göre yerleştirme konuğun işini kolaylaştırır."}]},{"konuk":"Bu kadar çabuk hallettiğiniz için teşekkürler.","ingilizce":"Thank you for sorting it out so quickly.","secenekler":[{"metin":"Bundan sonra eksik varsa gelmeden önce iyice kontrol edin; her seferinde gelemem, işim çok.","puan":0,"tepki":"Konuk yüzünü ekşitir. Eksik bildiren konuğu suçlamak profesyonelliğe aykırıdır; yardım ettikten sonra söylenen bu cümle özeni siler."},{"metin":"Rica ederim efendim, iyi akşamlar. Başka isteğiniz olursa söylersiniz.","puan":1,"tepki":"Konuk başını sallar. Veda kibar ama kontrol atlandı; malzemelerin yerinde olduğuna son bir kez bakmak hizmeti tamamlar."},{"metin":"Rica ederim efendim. Çıkmadan önce her şeyin yerinde olduğuna bir kez daha bakıyorum.","ingilizce":"You are welcome, sir. Before I leave, I will check once more that everything is in place.","puan":2,"tepki":"Konuk gülümser: “Çok memnun kaldım.” Yerleştirme sonrası kontrol eksiği çıkmadan yakalar; son bir bakış konuğun şikâyetini baştan önler."}]}]},{"id":"kh1-d09","unite":5,"baslik":"Gece Lobisinde Islak Zemin","rol":"Meydancı","sahne":"Gece 23.30. Lobide birkaç konuk hâlâ oturuyor. Meydancı mermer zemini ıslak silmeye hazırlanıyor ve iki asansörden birini temizlemeye başlıyor. Valizli bir erkek konuk, asansöre gitmek için lobiden geçiyor.","kavramlar":["kh1-5-004","kh1-5-007","kh1-5-021","kh1-5-050","kh1-5-082"],"adimlar":[{"konuk":"İyi akşamlar. Zemini mi siliyorsunuz? Asansöre gitmek için buradan geçebilir miyim?","ingilizce":"Good evening. Are you mopping the floor? Can I walk through here to get to the lift?","secenekler":[{"metin":"Buyurun geçin efendim, zemin şu an kuru. Islak silmeden önce kaygan zemin levhasını koyacağım, merak etmeyin.","ingilizce":"Please go ahead, sir; the floor is dry at the moment. I will put out a wet floor sign before I mop, so don’t worry.","puan":2,"tepki":"Konuk gülümseyip geçer: “Teşekkürler.” Islak paspastan önce levha konur ve konuk varken temizlik onu rahatsız etmeden yürütülür."},{"metin":"Buyurun, ama dikkatli olun. Birazdan ıslak silmeye başlayacağım, zemin kayganlaşabilir.","puan":1,"tepki":"Konuk dikkatle geçer ama arkasından gelen konuklar uyarılmamış olur. Sözlü uyarı yetmez; ıslak zemin silinmeden önce levha konur."},{"metin":"Ben silerken siz duvar tarafından, yavaş yavaş geçin. Kayganlaşabilir ama dikkat ederseniz sorun olmaz.","puan":0,"tepki":"Konuk dengesini korumaya çalışarak ilerler. Levha koymadan ıslak zemin bırakmak düşme kazasına yol açar; uyarı yalnız sözle değil levhayla yapılır."}]},{"konuk":"Asansörlerden birinde “Sizin İçin Temizleniyor” levhası var. Valizlerle bekleyecek miyim?","ingilizce":"There is a “Being Cleaned for You” sign on one of the lifts. Will I have to wait with my luggage?","secenekler":[{"metin":"Temizlik saati bu, bekleyeceksiniz. Diğerini de kapatmak üzereydim, ikisini birden bitirmek istiyorum; acelem yok.","puan":0,"tepki":"Konuk sinirlenir: “Valizlerle mi bekleyeceğim?” Asansörlerin hepsini aynı anda kullanım dışı bırakmak konukları mağdur eder; asansörler sırayla temizlenir."},{"metin":"Biraz bekleyin efendim, bunu bitirince ikisini de açarım. Birkaç dakikanızı alır.","puan":1,"tepki":"Konuk sabırsızca saatine bakar. Diğer asansör açıkken konuğu bekletmek gereksizdir; birden fazla asansörde temizlik sırayla yapılır ve biri her zaman açık kalır."},{"metin":"Hayır efendim, diğer asansör açık. Asansörleri sırayla ve lobi katında temizliyoruz, biri hep açık kalıyor.","ingilizce":"No, sir, the other lift is available. We clean the lifts one at a time and on the lobby floor, so one is always open.","puan":2,"tepki":"Konuk valizini diğer asansöre doğru çeker: “Ne güzel düşünülmüş.” Asansörler sırayla temizlenince konuklar bavullarıyla beklemez; temizlik lobide yapılınca katlardaki konuklar rahatsız edilmez."}]},{"konuk":"Yarın sabah erken kahvaltıya ineceğim. O saatlerde lobide temizlik gürültüsü olur mu?","ingilizce":"I will be coming down early for breakfast tomorrow. Will there be cleaning noise in the lobby then?","secenekler":[{"metin":"Temizlik gürültüsü işimizin parçası, otel de zaten hareketli bir yer; buna alışmanız gerekir.","puan":0,"tepki":"Konuk gücenir. Konuğun dinlenme ve kahvaltı saatleri gözetilir; gürültülü ağır işler konukların az olduğu saatlere bırakılır."},{"metin":"Ağır işleri konuk azken geceleri yapıyoruz. Sabah yoğun saatte yalnızca kontrol ve küçük müdahale var.","ingilizce":"We do the heavy jobs at night when there are few guests. In the busy morning hours we only make checks and small touch-ups.","puan":2,"tepki":"Konuk rahatlar: “Güzel, sakin bir kahvaltı olur.” Ağır bakım konuk az iken gece yapılır; yoğun saatlerde yalnızca kontrol ve küçük müdahale kalır."},{"metin":"Sabah lobide hep biri çalışır efendim ama genelde sessizdir, sizi rahatsız eder diye düşünmem, merak etmeyin.","puan":1,"tepki":"Konuk “Genelde mi?” diye sorar. Belirsiz bir cevap güven vermez; temizlik zamanlamasının ilkesi (ağır iş gece, gündüz kontrol) açıkça söylenmelidir."}]},{"konuk":"Şu masanın yanında kahve dökülmüş, çocuğum koşarken az kalsın kayıp düşüyordu. Neden daha önce silinmedi?","ingilizce":"Coffee has been spilled by that table, and my child nearly slipped and fell while running. Why wasn’t it wiped up earlier?","secenekler":[{"metin":"Özür dilerim efendim, çocuğunuzun iyi olmasına sevindim. Hemen levhayı koyup zemini siliyorum.","ingilizce":"I am sorry, sir, and I am glad your child is all right. I will put a wet floor sign down and wipe the floor straight away.","puan":2,"tepki":"Konuk sakinleşir: “Teşekkürler, hızlı davrandınız.” Dökülen sıvıya fark edildiği anda müdahale edilir; yedek bezi ve levhası yanında olan görevli zemini beklemeden güvenli hâle getirir."},{"metin":"Az önce dökülmüş olmalı, ben görmedim. Bu benim sorunum değil, lobide herkes bir şey dökebilir, ne yapayım?","puan":0,"tepki":"Konuk sinirlenir. Genel alanlarda zemini güvende tutmak meydancının sorumluluğundadır; sorumluluğu reddetmek güveni sarsar."},{"metin":"Hemen siliyorum efendim, bezim yanımda. Birkaç dakikada zemin kuru ve temiz olur.","puan":1,"tepki":"Konuk özür duymadığı için bozuk bir sesle “Çocuk düşebilirdi” der. Müdahale hızlı ama konuğun yaşadığı tehlikeye özür ve ilgi gösterilmedi."}]},{"konuk":"Teşekkürler. Bu arada şu koltukta bir cep telefonu gördüm. Burada oturan kimsenin değil galiba.","ingilizce":"Thank you. By the way, I saw a mobile phone on that sofa. I don’t think it belongs to anyone sitting here.","secenekler":[{"metin":"Teşekkür ederim efendim. Şefime haber verip telefonu kaydıyla birlikte ilgili birime teslim edeceğim.","ingilizce":"Thank you, sir. I will tell my supervisor and hand the phone over to the relevant department, and it will be recorded.","puan":2,"tepki":"Konuk teşekkür eder: “İyi ki size söyledim.” Genel alanda unutulan eşya amire bildirilir ve ilgili birime teslim edilir; kayıt, konuğun güvenini korur."},{"metin":"Telefonu cebime alayım, birisi sorarsa veririm. Kayıt işiyle de uğraşmayalım, ortalık karışır.","puan":0,"tepki":"Konuk huzursuz olur. Unutulan eşya gizlice saklanmaz; kayıtsız kalan eşyanın sahibine ulaşması zorlaşır ve güven zedelenir."},{"metin":"Teşekkürler, birazdan bakarım. Şimdilik yerinde dursun, sahibi gelip alır belki; gelmezse sonra düşünürüz.","puan":1,"tepki":"Konuk uzaklaşırken endişelenir. Bulunan eşya bulunduğu gibi bırakılmaz; yerinde kalırsa kaybolabilir ya da yanlış kişinin eline geçebilir."}]}]},{"id":"kh1-d10","unite":5,"baslik":"Havuz Başında Bir Sabah","rol":"Meydancı","sahne":"Öğleden önce 11.30, bir tatil otelinin havuz çevresi. Meydancı şezlongların arasında çöp topluyor ve açık duş alanını kontrol ediyor. Odasının havlusunu omzuna atmış bir hanım konuk havuza doğru yürüyor.","kavramlar":["kh1-5-178","kh1-5-218","kh1-5-230","kh1-5-236","kh1-5-239"],"adimlar":[{"konuk":"Günaydın. Odamdaki havluyu havuza getirdim. Bir sakıncası var mı?","ingilizce":"Good morning. I’ve brought the towel from my room to the pool. Is that a problem?","secenekler":[{"metin":"Olur, kimse bakmaz zaten. Yalnız havlu kirlenirse ya da kaybolursa o sizin sorununuz.","puan":0,"tepki":"Konuk ne yapacağını bilemez. Kuralı önemsemeyen cevap havlu karışıklığına ve takip güçlüğüne yol açar; oda havlusu havuza götürülmez."},{"metin":"Oda havlusu havuzda kullanılmıyor efendim; size hemen farklı renkte bir havuz havlusu getireyim.","ingilizce":"Room towels are not used at the pool, madam; let me bring you a pool towel in a different colour straight away.","puan":2,"tepki":"Konuk gülümser: “Tamam, teşekkürler.” Oda ve havuz havluları karışmasın diye renkleri farklıdır; kuralı söylerken konuğa çözüm de sunulur."},{"metin":"Havuzda oda havlusu kullanılmaz efendim, kurallarımız böyle. Lütfen odanıza bırakın, orada kalsın.","puan":1,"tepki":"Konuk “Peki ne yapacağım?” der. Kural doğru söylendi ama konuğa yardım edilmedi; havlu getirilmeli ya da dağıtım alanı gösterilmelidir."}]},{"konuk":"Duşun orada su birikmiş, çok kaygan. Küçük bir çocuk kayıp düşecekti.","ingilizce":"Water has collected by the shower and it’s very slippery. A small child nearly slipped and fell.","secenekler":[{"metin":"Birazdan bakarım, şimdi şezlongların dizilimini bitireyim. Önce o işi tamamlamam gerekiyor.","puan":1,"tepki":"Konuk endişelenir: “Ya biri düşerse?” Kayma riski olan alana hemen müdahale edilir; işin sırası konuk güvenliğinin önüne geçmez."},{"metin":"Geçmiş olsun, çocuk iyi mi? Oraya hemen levha koyup alanı kapatıyorum; sonra suyu çekip gideri kontrol edeceğim.","ingilizce":"I’m sorry to hear that. Is the child all right? I will put a sign there and close off the area right away, then clear the water and check the drain.","puan":2,"tepki":"Konuk rahatlar: “Çok iyi olur.” Islak zemin temizlenmeden önce levha konup alan kapatılır; açık duş zemininde fazla su uzaklaştırılarak kayma riski azaltılır."},{"metin":"Çocuklar orada koşmasın efendim, ailelerine söyleyin. Islak zeminde koşmak tehlikeli.","puan":0,"tepki":"Konuk gücenir. Zeminin güvenliği konuğa bırakılamaz; ıslak alan görevlinin sorumluluğundadır ve levhayla kapatılarak temizlenir."}]},{"konuk":"Havuz kenarındaki ızgaralardan biri gevşek, ayağım takıldı.","ingilizce":"One of the grilles at the edge of the pool is loose, and my foot caught on it.","secenekler":[{"metin":"Geçmiş olsun efendim. Izgaraya kendim müdahale etmiyorum; teknik servise bildirip çevresini ayırıyorum.","ingilizce":"I’m sorry to hear that, madam. I will not try to fix the grille myself; I will tell maintenance and mark off the area.","puan":2,"tepki":"Konuk başını sallar: “Doğru, kimse takılmasın.” Taşma kanalı havuzun teknik sistemidir ve bakımı teknik servise aittir; görevli arıza görünce bildirir, kendisi müdahale etmez."},{"metin":"Teknik servise bildiririm efendim. Şimdilik dikkat edin, oradan geçmemeye çalışın.","puan":1,"tepki":"Konuk teşekkür eder ama başkasının takılmasından endişe eder. Arıza bildirilir ve güvenlik için çevresi de işaretlenir; konuğa yalnızca “dikkat edin” demek yetmez."},{"metin":"Ben bakıp sıkıştırmaya çalışayım, belki yerine oturur. Teknik servisi çağırmaya gerek kalmaz, vakit kazanırız.","puan":0,"tepki":"Konuk geri çekilir. Teknik arızaya yetkisiz müdahale hem iş güvenliği riski hem de garanti sorunu doğurur; görevli bildirir, onarımı teknik servis yapar."}]},{"konuk":"Havuzun suyu bu sabah biraz bulanık görünüyor. Temizlik yapılıyor mu?","ingilizce":"The pool water looks a little cloudy this morning. Is it being cleaned?","secenekler":[{"metin":"Bence bir şey yok, bulanık görünmesi güneşin yansımasından. Rahatça yüzebilirsiniz.","puan":0,"tepki":"Konuk yüzmeye karar verir ama içi rahat etmez. Suyun durumu hakkında tahminle hüküm vermek görevlinin yetkisinde değildir; kontrol teknik servise aittir."},{"metin":"Havuz suyunu teknik servis kontrol edip dezenfekte eder; ben çevreyi temizliyorum. Hemen haber verip size döneceğim.","ingilizce":"Maintenance checks and disinfects the pool water; I look after the area around it. I will let them know now and come back to you.","puan":2,"tepki":"Konuk teşekkür eder: “Güzel, bekliyorum.” Havuz suyunun temizliği ve dezenfeksiyonu teknik servise aittir; konuğun sorusu doğru bölüme iletilir."},{"metin":"Bu teknik servisin işi efendim, onlara sormanız gerekir. Ben yalnızca çevreyle ilgileniyorum.","puan":1,"tepki":"Konuk cevap alamadan döner. İş bölümü doğru söylendi ama konuğun sorusu sahipsiz bırakıldı; sorunun teknik servise iletilmesi gerekirdi."}]},{"konuk":"Teşekkürler. Şezlongumu şemsiyenin altına çekeceğim ama şemsiyenin sapı sallanıyor gibi.","ingilizce":"Thank you. I’m going to pull my sunbed under the parasol, but the pole seems to be wobbling.","secenekler":[{"metin":"Şemsiye benim sorumluluğumda değil, plaj ekibini arayın. Ben havuz çevresine bakıyorum.","puan":0,"tepki":"Konuk bıkkınlıkla uzaklaşır. Arızayı gören görevli çözümü başlatır; konuğu başka birine yönlendirmek görevi sahiplenmemektir."},{"metin":"Şezlongu çekin, şemsiye şimdilik idare eder. Rüzgâr çıkarsa tekrar bakarız, size haber veririm, merak etmeyin.","puan":1,"tepki":"Konuk şezlongu çeker ama şemsiyenin sallanmasından rahatsız olur. Gevşek şemsiye altına geçilmeden kontrol edilip değiştirilmelidir."},{"metin":"Bir dakika efendim, yardım edeyim. Sallanan şemsiye rüzgârda tehlikeli; kapatıp yenisini kuruyorum.","ingilizce":"One moment, madam, let me help. A loose parasol is dangerous in the wind, so I will close it and put up another.","puan":2,"tepki":"Konuk teşekkür eder: “Ne kadar dikkatlisiniz.” Arızalı şemsiye rüzgârda tehlikeli olabilir; kolu gevşek şemsiye yenisiyle değiştirilir."}]}]},{"id":"kh1-d11","unite":1,"baslik":"Defterde İmzası Duran Pas Kartı","rol":"Kat görevlisi","karsi":"Kat şefi","sahne":"Saat 17.15, vardiya bitimine kırk dakika var. Kat görevlisi Hande, pas kartını ceketinde bulamıyor; kart sabah kat ofisinde defterde imzasıyla teslim alınmıştı. Kat şefi Hülya Hanım ofiste, Hande’nin telaşını fark edip yanına geliyor.","kavramlar":["kh1-1-265","kh1-1-266","kh1-1-267"],"adimlar":[{"konuk":"Hande, bir şey mi arıyorsun? Yüzün solmuş.","ingilizce":"Hande, are you looking for something? You look worried.","secenekler":[{"metin":"Biraz daha bakayım, bulurum. Bulamazsam size söylerim, sizi şimdilik yormak istemem.","puan":1,"tepki":"Hülya Hanım kaşlarını çatar: “Beklemek mi?” Kayıp kart güvenlik riski taşır; her geçen dakika riski büyütür, bu yüzden hemen bildirmek gerekir."},{"metin":"Pas kartımı bulamıyorum, Hülya Hanım. Sabah imzayla almıştım. Size hemen haber vermek istedim.","ingilizce":"I cannot find my pass card. I signed for it this morning, and I wanted to tell you straight away.","puan":2,"tepki":"Hülya Hanım ciddileşir ama sakin kalır: “İyi ki hemen söyledin.” Kartın kimde olduğu defterde imzayla bellidir; bildirim gecikmeyince önlem de zamanında alınır."},{"metin":"Hiçbir şey aramıyorum. Kart bir yerdedir, kimse bulsa bile ne yapacak ki?","puan":0,"tepki":"Hülya Hanım sertleşir: “Kart sende değilse bu ciddi bir konu.” Kayıp kartı saklamak ya da önemsememek, odalar için güvenlik riski doğurur."}]},{"konuk":"Kartı en son nerede kullandığını hatırlıyor musun? Sabah nasıl teslim almıştın?","ingilizce":"Where did you last use the card? How did you take it this morning?","secenekler":[{"metin":"Bilmiyorum, defterle işim yok. Kartı bana verdiler, kayıt tutmadım.","puan":0,"tepki":"Hülya Hanım başını iki yana sallar: “Kayıt tutulmadan kart verilmez.” Pas kartı alınırken ve verilirken defterde imza atılır; kayıtsız teslim kimde olduğunu belirsiz bırakır."},{"metin":"Üçüncü kattaydım sanırım. Defterde yazar mı bilmiyorum, bakmadım.","puan":1,"tepki":"Hülya Hanım defteri kendisi kontrol eder. Teslim saatini ve imzayı bilmek, kartın nerede kaybolduğunu daraltmaya yardım eder; sanırım demek yeterli değildir."},{"metin":"Sabah 08.30’da kat ofisinde deftere adımı ve saati yazıp imzaladım. Son kullanımım üçüncü kattaydı.","ingilizce":"I wrote my name and the time in the book and signed for it at half past eight. I last used it on the third floor.","puan":2,"tepki":"Hülya Hanım defteri açar: “Kayıtta imzanı görüyorum.” Teslim alma imza ile yapıldığı için kartın kimde olduğu belli olur, arama da buradan başlar."}]},{"konuk":"Kayıp bir kartın hemen bildirilmesi neden bu kadar önemli sence?","ingilizce":"Why do you think it matters so much to report a lost card immediately?","secenekler":[{"metin":"Çünkü kart bulan biri odalara girebilir. Bu yüzden zaman kaybetmeden haber vermek gerekir.","ingilizce":"Because whoever finds the card could enter the rooms, so it must be reported without delay.","puan":2,"tepki":"Hülya Hanım başını sallar: “Kesinlikle.” Kayıp kart güvenlik riski taşıdığı için gecikmeden bildirilir; böylece önlemler hemen alınabilir."},{"metin":"Yönetim bildirim ister diye, yoksa fazla bir önemi yok.","puan":0,"tepki":"Hülya Hanım kaşını kaldırır: “Önemi var.” Bildirim bir kural gereği değil, konukların oda güvenliği içindir; kart kötü niyetli birinin eline geçebilir."},{"metin":"Kat şefi gerektiğinde işlem yapabilsin diye, günün sonunda haber vermek de yeterli olur.","puan":1,"tepki":"Hülya Hanım düzeltir: “Gün sonuna kadar beklenmez.” Haber vermek doğru bir adımdır ama gecikmeden yapılmalıdır, çünkü risk kart bulunana kadar sürer."}]},{"konuk":"Tamam, kartı arayacağız. Bu arada kayda ne geçeceğiz?","ingilizce":"Right, we will look for the card. In the meantime, what shall we put on record?","secenekler":[{"metin":"Kayıt tutmayalım. Kart bulunursa sorun kalmaz; defteri de olduğu gibi bırakalım.","puan":0,"tepki":"Hülya Hanım itiraz eder: “Olmaz.” Anahtar ve kart işlemleri imza ile kayda geçer; kayıtsız bırakılan kayıp, ileride kimde olduğunu bilmeyi imkânsız kılar."},{"metin":"Sabah 08.30’da imzayla aldığımı, 17.15’te kaybolduğunu fark ettiğimi ve size hemen haber verdiğimi yazalım.","ingilizce":"Let us record that I signed for it at half past eight, noticed it was missing at quarter past five, and told you at once.","puan":2,"tepki":"Hülya Hanım notu alır: “Net, zamanlı ve eksiksiz.” Defterdeki imzalı teslim saati ve kaybın fark edildiği an, kartın izini sürmeyi kolaylaştırır."},{"metin":"Sadece kartın kayıp olduğunu yazalım; saat ve imza bilgisine gerek yok, kart zaten bulunur.","puan":1,"tepki":"Hülya Hanım kısa bir not alır. Kayıp bildirimi saat ve imza bilgisiyle birlikte yazılırsa kartın nerede ve ne zaman kaybolduğu daha kolay anlaşılır."}]},{"konuk":"Kartı odanın kapısında bulmuşlar, güvenlikte. Teşekkürler, gününü bitir artık.","ingilizce":"They found the card at a room door and it is with security. Thank you, you can finish your day now.","secenekler":[{"metin":"Kart bulundu ya, bundan sonra imza atmasam da olur; böylece vakit kaybetmem.","puan":0,"tepki":"Hülya Hanım uyarır: “İmza vazgeçilmez.” İmza kartın kimde olduğunu gösterir ve güvenliği sağlar; bulundu diye bırakılmaz."},{"metin":"Sağ olun, kartı güvenlikten alıp gelirim.","puan":1,"tepki":"Hülya Hanım başını sallar. Kartı geri alırken teslim saatini ve imzayı deftere yazmak da gerekir; yalnızca almak kaydı tamamlamaz."},{"metin":"Teşekkür ederim, Hülya Hanım. Yarın pas kartını imzayla alıp akşam yine imzayla teslim edeceğim.","ingilizce":"Thank you. Tomorrow I will sign for the card in the morning and sign it back in the evening.","puan":2,"tepki":"Hülya Hanım gülümser: “Aynen öyle.” Pas kartı her zaman imza karşılığı alınıp verilirse kartın kimde olduğu hep bellidir."}]}]},{"id":"kh1-d12","unite":2,"baslik":"Banyo Bitmeden Dönen Konuk","rol":"Kat görevlisi","sahne":"Saat 11.15, 214 numaralı oda. Kat görevlisi kapıyı çalıp temizlik istenip istenmediğini sormuş, Bay Becker onaylayıp çıkmıştır. Görevli kapıya Oda Görevlisi kartını asıp banyoya geçmiştir. Konuk beklenenden erken dönüyor.","kavramlar":["kh1-2-041","kh1-2-043","kh1-2-044","kh1-2-077"],"adimlar":[{"konuk":"Aa, oda hâlâ temizleniyor galiba. Telefon şarj aletimi almam gerekiyordu.","ingilizce":"Oh, the room is still being cleaned. I need to pick up my phone charger.","secenekler":[{"metin":"Odanın temizliği bitmedi, şimdi giremezsiniz. Lütfen koridorda bekleyin.","puan":0,"tepki":"Konuk şaşırır: “Kendi odama giremiyor muyum?” Konuğu kendi odasının kapısında bekletmek yanlıştır; konuğa önce sakıncası sorulur."},{"metin":"Hoş geldiniz, temizliğe devam etmemde sakınca var mı?","ingilizce":"Welcome back. Do you mind if I continue cleaning?","puan":2,"tepki":"Konuk gülümser: “Hayır, buyurun devam edin.” Konuk odaya gelince önce temizliğin sakıncası sorulur, karar konuğundur."},{"metin":"Hoş geldiniz, şarj aletinizi alın, ben banyoya devam ediyorum.","puan":1,"tepki":"Konuk şarj aletini alır ama temizliğe devam edilmesi için görüşü sorulmamıştır; devam etmeden önce konuğa sormak gerekir."}]},{"konuk":"Devam edin. Bu arada masadaki buruşuk kâğıt çok önemli bir not; atmadınız, değil mi?","ingilizce":"Please carry on. By the way, the crumpled paper on the desk is an important note. You didn’t throw it away, did you?","secenekler":[{"metin":"Atmadım efendim; çöp olduğundan emin olmadığım için masada bıraktım.","ingilizce":"No, sir. I wasn’t sure it was rubbish, so I left it on the desk.","puan":2,"tepki":"Konuk rahatlar. Çöp olduğundan emin olunmayan eşya atılmaz; konuk için önemli olabilir."},{"metin":"Buruşuk kâğıt çöptür, torbayla birlikte kat arabasına koydum.","puan":0,"tepki":"Konuk telaşlanır: “Notum gitti!” Emin olunmayan kâğıt çöp sayılmaz; bu hata konuğu zor durumda bırakır."},{"metin":"Sanırım atmadım, bir bakayım.","puan":1,"tepki":"Konuk bir an tedirgin olur; kâğıdın nerede olduğunu bilmek gerekirdi."}]},{"konuk":"Kapıyı neden açık bırakmışsınız? Biraz tuhaf geldi.","ingilizce":"Why did you leave the door open? It feels a bit odd.","secenekler":[{"metin":"Kapıyı hemen kapatayım, rahatsız etmeyeyim.","puan":0,"tepki":"Konuk bu kez şüphelenir. Çalışırken kapı açık tutulur ve kapıya kart asılır; böylece hem görevli hem konuk güvende olur."},{"metin":"Kapı açık kalır efendim, kuralımız böyle.","puan":1,"tepki":"Konuk tam ikna olmaz; açık kapının nedeni, yani güvenlik, açıklanmalıydı."},{"metin":"Güvenlik için çalışırken kapı açık kalır efendim; kapıdaki kart da bunu gösterir.","ingilizce":"For safety, the door stays open while I work, sir. The card on it shows the room is being serviced.","puan":2,"tepki":"Konuk başını sallar: “Mantıklı, teşekkürler.” Kart ve açık kapı, odada işlem yapıldığını gösterir ve hem görevlinin hem konuğun güvenliğini sağlar."}]},{"konuk":"Aslında başım ağrımaya başladı, biraz uzanmak istiyorum. Temizliği sonraya bırakabilir miyiz?","ingilizce":"Actually, I’ve got a headache and I’d like to lie down for a while. Could we leave the cleaning for later?","secenekler":[{"metin":"Beş dakika daha izin verin, sadece banyoyu bitireyim.","puan":1,"tepki":"Konuk isteksizce kabul eder; konuk temizlik istemediğine göre hemen çıkmak gerekirdi."},{"metin":"Tabii efendim, araç gereci toplayıp çıkıyorum. Odanızı başka saatte temizler, raporuma not ederim.","ingilizce":"Of course, sir. I’ll gather my things and leave. I’ll clean at another time and note it in my report.","puan":2,"tepki":"Konuk teşekkür eder. Konuk istemezse oda başka bir saatte temizlenir ve bu, oda durum raporuna not edilir."},{"metin":"Banyo yarım kaldı, bitirmeden çıkarsam kat şefi bana kızar.","puan":0,"tepki":"Konuk rahatsız olur: “Dinlenmek istiyorum.” Konuğun isteği işin önündedir; amir baskısını konuğa yansıtmak yanlıştır."}]},{"konuk":"Teşekkür ederim, anlayış gösterdiğiniz için çok naziksiniz.","ingilizce":"Thank you, you are very kind to be so understanding.","secenekler":[{"metin":"Rica ederim, geçmiş olsun. Odanızı başka saatte hazırlarız.","ingilizce":"You’re welcome, I hope you feel better soon. We will prepare your room at another time.","puan":2,"tepki":"Konuk gülümseyerek kapıyı kapatır. Nazik veda ve odanın başka saatte temizleneceğini bildirmek konuğu rahatlatır."},{"metin":"Görevim bu. Başka bir şey var mı?","puan":1,"tepki":"Konuk yine de teşekkür eder; cevap soğuk ve kısa kalır."},{"metin":"Önemli değil. Yarın da aynı saatte gelirim, odada olsanız da girerim.","puan":0,"tepki":"Konuk şaşırır: “Odadayken mi?” Konuk içerideyse kapı çalınır ve önce temizlik isteyip istemediği sorulur."}]}]},{"id":"kh1-d13","unite":3,"baslik":"Balayı Odasında Çift Kuğu","rol":"Kat görevlisi","karsi":"Kat şefi","sahne":"Saat 13.30. 212 numaralı oda öğleden sonra gelecek bir balayı çiftine hazırlanıyor. Kat görevlisi Deniz, kat arabasının yanında kat şefi Nilay Hanım’ın son sorularını yanıtlıyor; yatak yapılacak ve havlu figürü bırakılacak.","kavramlar":["kh1-3-023","kh1-3-025","kh1-3-027","kh1-3-182","kh1-3-191"],"adimlar":[{"konuk":"212 balayı odası, çift saat 15.00’te geliyor. Odaya çıkmadan önce kat arabanız hazır mı?","ingilizce":"Room 212 is for a honeymoon couple arriving at three. Is your trolley ready before you go up?","secenekler":[{"metin":"Arabada genelde her şey bulunur, dün akşam da baktım. Yolda bir şey eksik çıkarsa inip alırım.","puan":1,"tepki":"Nilay Hanım başını sallar: “Odaya çıkıp tekrar inmek vakit alır.” Kontrol işe başlamadan yapılırsa oda yarıda kalmaz."},{"metin":"Listeme bakıp çarşaf, nevresim, yastık kılıfı ve havluları tek tek sayıyorum. Eksik varsa şimdi tamamlarım.","ingilizce":"Let me check the trolley against my list: sheets, duvet covers, pillowcases and towels. If anything is missing, I will top it up now.","puan":2,"tepki":"Nilay Hanım onaylar: “Güzel, çıkabilirsiniz.” Listeyle denetlemek, malzemenin yettiğini işe başlamadan gösterir."},{"metin":"Hazır sayılır, sayıp durmaya gerek yok. Zaman kaybetmeden hemen çıkıyorum.","puan":0,"tepki":"Nilay Hanım uyarır: “Peki yetmezse?” Listeyle kontrol edilmeden çıkmak, odada eksik malzemeyi ortaya çıkarır ve işi yarıda keser."}]},{"konuk":"Yatağı hangi sırayla yapacaksınız?","ingilizce":"In what order will you make the bed?","secenekler":[{"metin":"Koruyucu, alt çarşaf, üst çarşaf, battaniye, yastık; en son yatak örtüsü.","ingilizce":"First the mattress protector, then the bottom sheet, top sheet, blanket and pillows, and the bedspread last.","puan":2,"tepki":"Nilay Hanım memnun olur. Koruyucudan başlayıp yatak örtüsüyle biten sıra, çarşafı yeniden sökme zahmetini önler."},{"metin":"Önce yatak örtüsünü serer, çarşafları ve battaniyeyi onun üzerine yerleştiririm.","puan":0,"tepki":"Nilay Hanım başını sallar: “Böyle olmaz.” Yatak örtüsü en son serilir; sıra bozulursa çarşaflar yeniden sökülür."},{"metin":"Alt çarşafla başlar, sonra üst çarşafı, battaniyeyi ve yastıkları yerleştiririm.","puan":1,"tepki":"Nilay Hanım yarım kabul eder: “Koruyucuyu unutmayın.” Sıra koruyucuyla başlar; yatak örtüsü sona kalır."}]},{"konuk":"Çifte havlu figürü bırakacaksınız. Nasıl hazırlayacaksınız?","ingilizce":"You will leave a piece of towel art for the couple. How will you prepare it?","secenekler":[{"metin":"Lekesi çıkmamış eski havlularla yaparım; figürde pek belli olmaz.","puan":0,"tepki":"Nilay Hanım itiraz eder: “Konuk görür.” Figürde yıpranmış ya da lekeli havlu kullanılmaz; yalnız temiz havlu kullanılır."},{"metin":"Tek bir kuğu yapıp yatağın ortasına bırakırım.","puan":1,"tepki":"Nilay Hanım ekler: “İki kişi gelecek.” Balayı odasına bir çift olarak, aynı türden iki figür yerleştirilir."},{"metin":"Yıpranmamış, lekesiz temiz havlularla iki kuğu yapıp yatağa bırakırım.","ingilizce":"I will make two swans from clean, stain-free towels in good condition and leave them on the bed.","puan":2,"tepki":"Nilay Hanım gülümser: “Çift kuğu çok yakışır.” Figür yalnız temiz havlularla ve çift olarak hazırlanır."}]},{"konuk":"Kuğular hazır. Yatağın üzerine nasıl yerleştireceksiniz?","ingilizce":"The swans are ready. How will you place them on the bed?","secenekler":[{"metin":"Kuğuları yatağın iki yanına ayrı ayrı bırakırım; gagalarını birleştirmeye uğraşmam.","puan":1,"tepki":"Nilay Hanım düzeltir: “Kalp şekli oluşmadı.” Kuğuların gagaları birleştirilince kalp şekli çıkar; balayı için daha anlamlıdır."},{"metin":"İki kuğuyu gagalarından birleştirip yatağın üzerine, girişten görünecek biçimde koyarım.","ingilizce":"I will join the two swans at the beaks and place them on the bed so that they can be seen from the doorway.","puan":2,"tepki":"Nilay Hanım onaylar. Gagalar birleşince kalp şekli oluşur; konuk figürü yatağın üzerinde ilk görür."},{"metin":"Yatak örtüsünün altına koyarım; konuk bulunca şaşırır.","puan":0,"tepki":"Nilay Hanım şaşırır: “Neden saklıyorsunuz?” Konuk figürü yatağın üzerinde ilk görür; gizlemek emeği boşa çıkarır."}]},{"konuk":"Yatak ve figür tamam. İşiniz bittiğinde oda durum raporu ve pas anahtarı için ne yapacaksınız?","ingilizce":"The bed and the swans are done. What will you do with the room status report and the master key when you finish?","secenekler":[{"metin":"Anahtarı yarın sabah geri bırakırım; rapor da o zaman hazırlanır, merak etmeyin.","puan":0,"tepki":"Nilay Hanım ciddileşir: “Anahtar sizde kalamaz.” Pas anahtarı iş bitince imza karşılığı teslim edilir; rapor da teslim edilir."},{"metin":"Raporu doldurur, anahtarı imza atmadan size bırakırım; imzayı sonra atarız.","puan":1,"tepki":"Nilay Hanım uyarır: “İmzasız teslim olmaz.” Pas anahtarı imza karşılığı, tarih ve saatiyle teslim edilir; imza sorumluluğun kayda geçmesini sağlar."},{"metin":"İşim bitince işlemleri gözden geçirir, oda durum raporunu size teslim eder, pas anahtarını imza karşılığı, tarih ve saatle veririm.","ingilizce":"When I have finished, I will check everything, hand you the room status report and return the master key against my signature, with the date and time.","puan":2,"tepki":"Nilay Hanım teşekkür eder. Kontrol, rapor ve imzalı anahtar teslimi işi kapatır; sorumluluk da kayda geçer."}]}]},{"id":"kh1-d14","unite":4,"baslik":"Boş Odada Akan Su","rol":"Kat görevlisi","karsi":"Yeni görevli","sahne":"Sabah 08.30. Üç gündür boş duran 312 numaralı odanın kapısında, işe yeni başlayan Deniz bekliyor. Kat ofisi onu bu odaya yolladı; temizlenecek bir şey olmayan odada neden iş yapıldığını anlamıyor.","kavramlar":["kh1-4-097","kh1-4-104","kh1-4-105","kh1-4-106","kh1-4-108"],"adimlar":[{"konuk":"Bu oda tertemiz ve kimse girmemiş. Neden musluklarını açıyoruz?","ingilizce":"This room is spotless and nobody has used it. Why are we turning the taps on?","secenekler":[{"metin":"Bu bir kural, listede yazıyor. Sen yine de her odada aynısını yap.","puan":1,"tepki":"Deniz itiraz etmez ama işin nedenini öğrenemez. Gerekçe açıklanmazsa görevli uygulamayı unutabilir."},{"metin":"Kullanılmayan odada su durgun kalır ve bakteri riski artar. Lejyoner hastalığına karşı suyu akıtıyoruz.","ingilizce":"Water left standing in an empty room can breed bacteria. We flush the taps to help prevent Legionnaires’ disease.","puan":2,"tepki":"Deniz başını sallar: “Demek temizlik için değil, güvenlik için.” Durgun suyun bakteri riskini artırdığını bilmek işin nedenini kavratır."},{"metin":"Çok önemli bir iş değil; zaman olmazsa bazen atlasak da olur, kimse fark etmez.","puan":0,"tepki":"Deniz şaşırır. Boş odada su akıtmak legionella takibinin parçasıdır; atlanırsa durgun suda bakteri üreyebilir ve konuğun sağlığı riske girer."}]},{"konuk":"Peki musluğu ne kadar açık tutacağız? Süreyi ben mi belirleyeceğim?","ingilizce":"So how long do we keep the tap running? Do I decide the time myself?","secenekler":[{"metin":"Sen karar verirsin: su berraklaşıp kokusuz görününce musluğu kapatabilirsin.","puan":0,"tepki":"Berrak görünen su güvenli demek değildir. Süre, teknik servisin talimatına göre belirlenir; görevli kendi kararıyla kısaltamaz."},{"metin":"Süreyi uzun tutalım, dakikalarca açık kalsın; ne kadar çok su akarsa o kadar iyi.","puan":1,"tepki":"Niyet iyi ama gereksiz su harcanır. Doğru süre talimatta yazar; fazlası da eksiği de uygun değildir."},{"metin":"Süre odanın ne kadar boş kaldığına göre değişir. Süreyi teknik servis belirler; yazılı talimata bakarız.","ingilizce":"The time depends on how long the room has been empty. Maintenance sets it, so we follow the written instructions.","puan":2,"tepki":"Deniz talimat listesini kat ofisinden almayı not eder. Süreyi belirlemek oda görevlisinin değil teknik servisin işidir."}]},{"konuk":"Hangi odalarda bunu yapacağımı nereden bileceğim?","ingilizce":"How will I know which rooms I should do this in?","secenekler":[{"metin":"Otomasyondaki legionella kontrol listesine bakarız. Boş odalar günlük listelenir ve yapılanlar işaretlenir.","ingilizce":"We check the Legionella control list on the PMS screen. Vacant rooms are listed daily and completed ones are ticked.","puan":2,"tepki":"Deniz listeyi açar ve 312’yi bulur. Ekran boş odaları günlük gösterir; işaret, hangi odaya girildiğini kanıtlar."},{"metin":"Her sabah aklında kalan odalara bakarsın; liste tutmana gerek yok.","puan":0,"tepki":"Hafızaya güvenmek odaların atlanmasına yol açar. Takip, listeye ve kayda dayanmalıdır."},{"metin":"Boş göründüğünü düşündüğün odalara girip kendi kararınla su akıtırsın, bu da yeter.","puan":1,"tepki":"Bu yöntem işler ama düzensizdir. Hangi odanın yapıldığı belli olmaz ve bir oda atlanabilir."}]},{"konuk":"Su akıttım. Bununla iş bitti mi?","ingilizce":"I’ve run the water. Is that all?","secenekler":[{"metin":"Evet, su akıttıysan iş bitti, başka kimseye göstermene gerek yok.","puan":0,"tepki":"Eksik kalır. Takip listesi kat şefi tarafından imzalanıp dosyalanmadıkça denetimde gösterilecek kayıt oluşmaz."},{"metin":"Gün sonunda listeyi kat şefine veririz. Kat şefi suyu akıtılan odaları işaretleyip imzalar, liste dosyaya girer ve denetimde gösterilir.","ingilizce":"At the end of the day we give the list to the housekeeping supervisor, who ticks off the rooms where the water was run and signs it; the list is filed and shown during inspections.","puan":2,"tepki":"Deniz kat şefine uğramak için not alır. İmzalı liste, işlemin yapıldığını gösteren belgedir ve halk sağlığı denetiminde sunulur."},{"metin":"Listeyi kendin imzalayıp dosyalayabilirsin; kat şefini beklemene gerek kalmaz.","puan":1,"tepki":"İmzayı kat şefi atar. Onun imzası olmadan liste tamamlanmış sayılmaz ve denetimde gösterilecek kayıt eksik kalır."}]},{"konuk":"Teşekkürler, şimdi anladım. Bir sonraki odaya geçelim mi?","ingilizce":"Thank you, I understand now. Shall we move on to the next room?","secenekler":[{"metin":"Olur, gidelim. Ama sonra aynı şeyi tekrar sormaya kalkma, bir kez anlattım.","puan":1,"tepki":"Ton kaba kaçar. Görev devam eder ama yeni çalışan soru sormaktan çekinebilir."},{"metin":"Tabii, ama bu işi ben yaparım; sen yarın başlarsın, bugün yalnızca izle.","puan":0,"tepki":"Fırsat kaçar. Yeni görevli uygulamayı yanında görerek ve yaparak öğrenir; teşvik edilmelidir."},{"metin":"Güzel. Sırayı sen yap, ben eşlik edeyim; ne yapacağını söyleyerek ilerle.","ingilizce":"Good. You take the lead and I’ll follow; tell me what you’re doing as you go.","puan":2,"tepki":"Deniz kendine güvenle odaya girer. Bilgiyi söyleyerek uygulamak, sürecin hem yapıldığını hem öğrenildiğini gösterir."}]}]},{"id":"kh1-d15","unite":5,"baslik":"Islak Halı, Bekleyen Grup","rol":"Meydancı","karsi":"Ön büro görevlisi","sahne":"Akşam 18.40. İkinci kat koridorunun halısı az önce yıkandı; köpük çekildi ama halı henüz nemli ve alan levhayla kapatıldı. Ön büro görevlisi Cem, yarım saat sonra valizleriyle çıkış yapacak bir grubu bu koridordan geçirmek istiyor ve meydancıya soruyor.","kavramlar":["kh1-5-063","kh1-5-064","kh1-5-066","kh1-5-067","kh1-5-068"],"adimlar":[{"konuk":"Koridorun halısı bitti mi? Yarım saat sonra bir grup valizleriyle çıkacak.","ingilizce":"Is the corridor carpet finished? A group will be checking out with their luggage in half an hour.","secenekler":[{"metin":"Bitti, koridor hazır; grubu hemen gönderebilirsiniz, halının kurumasını beklemeye gerek yok.","puan":0,"tepki":"Cem koridora yönelir ama halı hâlâ nemli. Kurumadan alanı kullanıma açmak lekeyi yayar ve kiri halıya geri taşır."},{"metin":"Yıkama ve köpük çekme bitti ama halı kurumadı. Kuruyana dek alan kapalı kalmalı.","ingilizce":"The washing and foam extraction are finished, but the carpet is not dry yet. The area must stay closed until it dries.","puan":2,"tepki":"Cem başını sallar: “Anladım, grubu bekletmem gerek.” Islak halıya eşya konmaz, alan kuruyana dek kapalı kalır; meydancı bunu bildirdi."},{"metin":"Bitirmek üzereyim, şefe sorup size haber vereyim; sonra grubu gönderirsiniz.","puan":1,"tepki":"Cem biraz bekler. Doğru yönde ama gereksiz gecikme: kuruma kuralını meydancı kendisi bildirebilirdi."}]},{"konuk":"Valizler tekerlekli, bir kerecik geçiverseler ne olur ki?","ingilizce":"The suitcases are on wheels. What harm could one quick pass do?","secenekler":[{"metin":"Islak halıya basmak lekeyi yayar, ayakkabıdaki kiri de halıya taşır. Kurumasını beklemek daha güvenli.","ingilizce":"Walking on a wet carpet spreads stains and carries dirt from shoes into it. It is safer to wait until it dries.","puan":2,"tepki":"Cem ikna olur: “Haklısın, yeni yıkanan halıyı bozmayalım.” Islak halıya basmak lekeyi yayar ve kiri halıya geri taşır."},{"metin":"Olmaz bence, sonra bir sorun çıkabilir; ne olacağını tam bilmiyorum ama pek uygun görmüyorum açıkçası.","puan":1,"tepki":"Cem omuz silker: “Neden olmaz?” Doğru karar ama gerekçesiz; neden anlatılırsa iş arkadaşı da kuralı benimser."},{"metin":"Tamam, tek sıra hızlıca geçsinler; küçük bir şey olur, iz kalmaz herhalde, grubu da boşuna beklettirmeyiz.","puan":0,"tepki":"Cem grubu yönlendirir; halıda tekerlek ve ayakkabı izleri belirir. Islak halıya basmak lekeyi yayar, kiri geri taşır."}]},{"konuk":"Peki, bekleyelim. Bu arada krem renkli lobi halısında bir konuğun döktüğü kahve lekesi var. Sana bırakayım mı?","ingilizce":"Fine, we will wait. By the way, a guest spilled coffee on the cream lobby carpet. Shall I leave it with you?","secenekler":[{"metin":"Bakarım, ama önce koridor işini tamamen bitirmem gerekiyor; lobiye ondan sonra bakarım.","puan":1,"tepki":"Cem rahatlamaz: lekeli lobi konuklara açık. Açık renkli halı kiri çabuk gösterir ve daha çok özen ister; lekeyle beklemek izlenimi bozar."},{"metin":"Tabii, leke çıkarıcıyı hemen halının ortasına sürerim; leke ortada olduğu için en doğrusu bu.","puan":0,"tepki":"Cem lekenin büyüdüğünü görür. Leke çıkarıcı dıştan merkeze doğru sürülür; ortadan başlamak lekeyi yayar."},{"metin":"Tabii. Önce halıyı vakumlarım, sonra leke çıkarıcıyı dış kenardan merkeze doğru sürerim.","ingilizce":"Of course. I will vacuum the carpet first, then apply the stain remover from the outer edge of the stain towards the centre.","puan":2,"tepki":"Cem rahatlar: “Güzel, krem rengi halı kiri çabuk gösterir.” Önce vakum, sonra dıştan merkeze uygulama lekenin yayılmasını önler."}]},{"konuk":"Yeni halı şampuanı geldi, şef yarın denemek istiyor. Doğrudan koridora mı sürülür?","ingilizce":"A new carpet shampoo has arrived and the supervisor wants to try it tomorrow. Can it be used straight on the corridor carpet?","secenekler":[{"metin":"Doğrudan koridora sürelim, zaman kazanırız; bir sorun çıkarsa sonra düzeltiriz nasılsa, zaten şef de ürünü beğenip aldı.","puan":0,"tepki":"Cem çekinir. Ürün rengi solduruyorsa zarar herkesin göreceği yerde ortaya çıkar; yeni ürün önce denenir."},{"metin":"Önce mobilyanın arkasındaki görünmeyen bir köşede deneyelim. Rengi solduruyorsa görünür alan zarar görmeden anlarız.","ingilizce":"Let us test it first on a hidden corner behind the furniture. If it fades the colour, we will find out without damaging any visible area.","puan":2,"tepki":"Cem not alır: “Mantıklı, riski küçük tutuyoruz.” Yeni ürün görünmeyen yerde denenirse renk solması görünür alanı bozmadan anlaşılır."},{"metin":"Önce koridorun küçük bir bölümüne sürüp bakalım, her şey yolundaysa koridorun tamamına geçeriz; böylece zaman da kaybetmeyiz.","puan":1,"tepki":"Cem başını sallar ama küçük alan koridorda göz önünde. Deneme görünmeyen bir yerde yapılırsa risk tamamen ortadan kalkar."}]},{"konuk":"Grup bekledi, sorun çıkmadı. Halı kurudu mu, levhayı kaldırabilir miyiz?","ingilizce":"The group waited without any problem. Is the carpet dry now? Can we remove the sign?","secenekler":[{"metin":"Halı tam kurudu, nemi kalmadı. Levhayı kaldırıp koridoru açıyorum.","ingilizce":"The carpet is completely dry. I am removing the sign and opening the corridor now.","puan":2,"tepki":"Cem teşekkür eder: “Ellerine sağlık, grup valizleriyle rahatça geçebilir.” Kuruyan halı koku yapmaz, akar oluşumunu da kolaylaştırmaz."},{"metin":"Sanırım kurudu ama tam emin değilim, siz de bir bakın lütfen, ben işimi bitirmeye gidiyorum.","puan":1,"tepki":"Cem bakmaya gider. Kontrol işini başkasına bırakmak güveni azaltır; kurumayı meydancı kendisi doğrulamalıdır."},{"metin":"Yüzeyi kurudu sayılır, açın; içi biraz nemli kalsa da sorun olmaz, grubu bekletmeyelim.","puan":0,"tepki":"Cem endişelenir: halının dibi nemli. Halıda kalan nem koku yapar ve akar oluşumunu kolaylaştırır."}]}]}]}]`);export{t};